INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0128', 'c124-c21c-cc3d', '{"id":"person-0128","name":"Seol Gangu","title":"Amsa Water District Patrol Squad Leader","position":"Amsa Water District Patrol Squad Leader","rank":"Sergeant","commonTier":"T5","occupation":"Water District Patrol and Detour Water Supply","gender":"Male","stage":"S2","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0128","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0128","name":"설강우","title":"암사 급수구역 순찰대 조장","position":"암사 급수구역 순찰대 조장","rank":"병장","commonTier":"T5","occupation":"급수구역 순찰·우회 급수","gender":"남성","stage":"S2","state":"S05","stateName":"동방사","detailRoute":"/people/person-0128","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0129', 'c9c0-cda9-c8fc', '{"id":"person-0129","name":"Ji Mokhyeon","title":"Waterworks Guard Corps Messenger","position":"Eastern Command Messenger","characterId":"K128","rank":"Sergeant","commonTier":"T5","occupation":"Delivery of Sealed Administrative and Military Dispatches","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#person-Ji-Mokhyeon","detailRoute":"/people/person-0129","birthDate":"2078-07-15","birthday":"07-15","age":48,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":7,"effective":7}},"skills":[{"id":"k128-sealed-delivery","name":"Sealed delivery","rating":65}],"traits":[{"id":"k128-choice","name":"Checks both approvals","description":"She refused departure whenever a seal cord sat loose and read any envoy who did not put verbal dispatches into the ledger as a forger. Short of breath or not, she held two copies in one hand.","behavior":"Anecdote. In 2125 he caught a night illegal crosser and reissued the guard code tags. By this deed the signature of the water-supply escort courier post rose into the ledger.","stress":"Fear. That one forged water dispatch would trigger a collective blockade and the courier network would become the coup''s horn. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Under command to carry Kim Woochan''s operations table only under seal, held a contract delivering Im Gyeore''s deadline clause to the lesser states, and weighed each time whether to pass ratification copies to Yun Seorin.","effects":[]},{"id":"k128-boundary","name":"Maintains work boundaries","description":"Office. Rank: sergeant. Title: water-supply escort courier. He sent the dispatches to the administration bureau and the escort at once, and a dispatch formation ran only with both Jeong Soyul''s rehearing stamp and Kim Woochan''s operations table.","behavior":"Office. Rank: sergeant. Title: water-supply escort courier. He sent the dispatches to the administration bureau and the escort at once, and a dispatch formation ran only with both Jeong Soyul''s rehearing stamp and Kim Woochan''s operations table.","stress":"Fear. That one forged water dispatch would trigger a collective blockade and the courier network would become the coup''s horn. The actual response is not yet recorded.","relationship":"Relations. Under command to carry Kim Woochan''s operations table only under seal, held a contract delivering Im Gyeore''s deadline clause to the lesser states, and weighed each time whether to pass ratification copies to Yun Seorin.","effects":[]}],"narrative":"Anecdote. In 2125 he caught a night illegal crosser and reissued the guard code tags. By this deed the signature of the water-supply escort courier post rose into the ledger. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c9c0-cda9-c8fc","name":"Chungju Ji Clan","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":70,"Openness":-50,"Force":80,"Material":20,"Communal":35,"Principle":-20,"Public":-30,"Eligibility":-20,"Dispersed":-45,"Transformative":-25},"desire":{"Longing":45,"Monopoly":30,"Risk":25,"Display":-25,"Sustained":-15,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Delivery of Sealed Administrative and Military Dispatches","Rank":"Sergeant","Title":"Eastern Command Messenger","Values":"Authority 70 | Openness −50 | Force 80 | Materialism 20 | Community 35 | Principle −20 | Publicity −30 | Qualification −20 | Dispersion −45 | Transformation −25","Desires":"Craving 45 | Monopoly 30 | Risk 25 | Display −25 | Persistence −15 | Orientation Fluid | Bonding Contract Cohabitation"},"sections":{"Offices":"Rank: Sergeant. Title: Eastern Command Herald. Sends dispatches to the administrative office and the Eastern Command simultaneously, and a deployment order runs only when both Jeong Soyul''s re-review seal and Kim Uchan''s operation sheet are present.\n\nAnecdote. In 2125, Ji Mokhyeon caught an unauthorized night crosser and changed the guard cipher tags.","Relationships":"A command of carrying Kim Uchan''s operation sheets only while sealed; a contract delivering Im Gyeore''s deadline clauses to the weaker states; and weighing each time whether to hand Yun Seorin a copy of the ratification.","Ambition":"Make the dispatch of the Eastern Protection Force and the notice ending emergency supervision valid only in the herald ledger that Ji Mokhyeon seals personally.\n\nFear. Ji Mokhyeon fears that a single forged water-supply dispatch will trigger a mass blockade, turning the herald network into the bugle of a coup.","Intervention":"You can find forged dispatches and protect the seals, or expose the withheld documents in the bag to nullify the deployment plan."},"biography":"Ji Mokhyeon refuses to depart if the seal cord is loose, and treats any envoy who does not enter oral messages in the ledger as a forger. Even out of breath, Ji Mokhyeon holds two copies in one hand.\n\n- Affiliation: Eastern Command\n- Occupation: Delivering sealed administrative and military dispatches\n- Rank: Sergeant\n- Title: Eastern Command Herald\nLife. Ji Mokhyeon was born in the 3rd generation. Ji Mokhyeon grew up at the Amsa guard post. Ji Mokhyeon''s post as Eastern Command Herald opened after catching an unauthorized night river crossing.\n- In duties linked to Amsa 2-dong, Ji Mokhyeon seals administrative and military dispatches together and demands both the re-review seal and the operation sheet.\n\n**Office.** Rank: Sergeant. Title: Eastern Command Herald. Sends dispatches to the administrative office and the Eastern Command simultaneously, and a deployment order runs only when both Jeong Soyul''s re-review seal and Kim Uchan''s operation sheet are present.\n\nAnecdote. In 2125, Ji Mokhyeon caught an unauthorized night crosser and changed the guard cipher tags.\n\n**Relationships.** A command of carrying Kim Uchan''s operation sheets only while sealed; a contract delivering Im Gyeore''s deadline clauses to the weaker states; and weighing each time whether to hand Yun Seorin a copy of the ratification.\n\n**Ambition.** Make the dispatch of the Eastern Protection Force and the notice ending emergency supervision valid only in the herald ledger that Ji Mokhyeon seals personally.\n\nFear. Ji Mokhyeon fears that a single forged water-supply dispatch will trigger a mass blockade, turning the herald network into the bugle of a coup.\n\n**Intervention.** You can find forged dispatches and protect the seals, or expose the withheld documents in the bag to nullify the deployment plan.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 70 | Openness −50 | Force 80 | Materialism 20 | Community 35 | Principle −20 | Publicity −30 | Qualification −20 | Dispersion −45 | Transformation −25\n- Desires: Craving 45 | Monopoly 30 | Risk 25 | Display −25 | Persistence −15 | Orientation Fluid | Bonding Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Ji Mokhyeon","type":"Command","to":"Kim Uchan","basis":"A command that carries Gim Uchan''s operations chart only in sealed form, and"},{"from":"Ji Mokhyeon","type":"Contract","to":"Im Gyeore","basis":"a contract that delivers Im Gyeore''s term clause to the pharmacy, and"}],"incoming":[]}}', '{"id":"person-0129","name":"지목현","title":"상수호위단 전령","position":"동방사 전령","characterId":"K128","rank":"병장","commonTier":"T5","occupation":"행정·군사 전갈 봉함 전달","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-지목현","detailRoute":"/people/person-0129","birthDate":"2078-07-15","birthday":"07-15","age":48,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":9,"effective":9},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":7,"effective":7}},"skills":[{"id":"k128-sealed-delivery","name":"봉함 전달","rating":65}],"traits":[{"id":"k128-choice","name":"두 날인 확인","description":"봉인 끈이 느슨하면 출발을 거부하고, 구두 전갈을 원장에 올리지 않는 사신을 위조로 본다. 숨이 차도 사본 두 장을 한 손에 쥔다.","behavior":"일화. 2125년 야간 무단 도꾼을 붙잡아 경비 암호패를 갈았다. 이 일로 동방사 전령 자리의 서명이 장부에 올랐다.","stress":"공포. 위조 급수 전갈 한 장이 집단 봉쇄를 발동시켜 전령망이 쿠데타의 나팔이 되는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 김우찬의 작전표를 봉인 상태로만 나르는 지휘이고, 임겨레의 기한 조항을 약소국에 배달하는 계약이며, 윤서린에게 인준 사본을 넘길지 매번 저울질한다.","effects":[]},{"id":"k128-boundary","name":"업무 경계를 지킴","description":"관직. 품계 병장. 직함은 동방사 전령. 전갈을 행정청과 동방사에 동시에 보내고, 파견 편성은 정소율의 재심 날인과 김우찬의 작전표가 둘 다 있어야 달린다.","behavior":"관직. 품계 병장. 직함은 동방사 전령. 전갈을 행정청과 동방사에 동시에 보내고, 파견 편성은 정소율의 재심 날인과 김우찬의 작전표가 둘 다 있어야 달린다.","stress":"공포. 위조 급수 전갈 한 장이 집단 봉쇄를 발동시켜 전령망이 쿠데타의 나팔이 되는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 김우찬의 작전표를 봉인 상태로만 나르는 지휘이고, 임겨레의 기한 조항을 약소국에 배달하는 계약이며, 윤서린에게 인준 사본을 넘길지 매번 저울질한다.","effects":[]}],"narrative":"일화. 2125년 야간 무단 도꾼을 붙잡아 경비 암호패를 갈았다. 이 일로 동방사 전령 자리의 서명이 장부에 올랐다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c9c0-cda9-c8fc","name":"충주 지씨","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":70,"개방":-50,"무력":80,"물질":20,"공동":35,"원칙":-20,"공개":-30,"자격":-20,"분산":-45,"변혁":-25},"desire":{"갈망":45,"독점":30,"위험":25,"과시":-25,"지속":-15,"지향":"유동","결합":"계약동거"},"fields":{"소속":"동방사","생업":"행정·군사 전갈 봉함 전달","품계":"병장","직함":"동방사 전령","가치관":"권위 70 | 개방 −50 | 무력 80 | 물질 20 | 공동 35 | 원칙 −20 | 공개 −30 | 자격 −20 | 분산 −45 | 변혁 −25","욕망":"갈망 45 | 독점 30 | 위험 25 | 과시 −25 | 지속 −15 | 지향 유동 | 결합 계약동거"},"sections":{"관직":"품계 병장. 직함은 동방사 전령. 전갈을 행정청과 동방사에 동시에 보내고, 파견 편성은 정소율의 재심 날인과 김우찬의 작전표가 둘 다 있어야 달린다.\n\n일화. 지목현은 2125년 야간 무단 도꾼을 붙잡아 경비 암호패를 갈았다.","관계":"김우찬의 작전표를 봉인 상태로만 나르는 지휘이고, 임겨레의 기한 조항을 약소국에 배달하는 계약이며, 윤서린에게 인준 사본을 넘길지 매번 저울질한다.","야망":"동부 보호군 파견과 비상감독 종료 통지를 자신이 날인하는 전령 원장에만 유효하게 만든다.\n\n공포. 지목현은 위조 급수 전갈 한 장이 집단 봉쇄를 발동시켜 전령망이 쿠데타의 나팔이 되는 일을 두려워한다.","개입":"위조 전갈을 찾아 봉인을 지키거나, 가방 속 보류 문서를 폭로해 파견안을 무력화할 수 있다."},"biography":"지목현은 봉인 끈이 느슨하면 출발을 거부하고, 구두 전갈을 원장에 올리지 않는 사신을 위조로 본다. 숨이 차도 사본 두 장을 한 손에 쥔다.\n\n- 소속: 동방사\n- 생업: 행정·군사 전갈 봉함 전달\n- 품계: 병장\n- 직함: 동방사 전령\n생애. 지목현은 3세대에 태어났다. 지목현은 암사 경비 초소에서 자랐다. 지목현의 동방사 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 지목현은 암사2동과 연결된 업무에서 행정·군사 전갈을 함께 봉하고 재심 날인과 작전표를 모두 요구한다.\n\n**관직.** 품계 병장. 직함은 동방사 전령. 전갈을 행정청과 동방사에 동시에 보내고, 파견 편성은 정소율의 재심 날인과 김우찬의 작전표가 둘 다 있어야 달린다.\n\n일화. 지목현은 2125년 야간 무단 도꾼을 붙잡아 경비 암호패를 갈았다.\n\n**관계.** 김우찬의 작전표를 봉인 상태로만 나르는 지휘이고, 임겨레의 기한 조항을 약소국에 배달하는 계약이며, 윤서린에게 인준 사본을 넘길지 매번 저울질한다.\n\n**야망.** 동부 보호군 파견과 비상감독 종료 통지를 자신이 날인하는 전령 원장에만 유효하게 만든다.\n\n공포. 지목현은 위조 급수 전갈 한 장이 집단 봉쇄를 발동시켜 전령망이 쿠데타의 나팔이 되는 일을 두려워한다.\n\n**개입.** 위조 전갈을 찾아 봉인을 지키거나, 가방 속 보류 문서를 폭로해 파견안을 무력화할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 70 | 개방 −50 | 무력 80 | 물질 20 | 공동 35 | 원칙 −20 | 공개 −30 | 자격 −20 | 분산 −45 | 변혁 −25\n- 욕망: 갈망 45 | 독점 30 | 위험 25 | 과시 −25 | 지속 −15 | 지향 유동 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"지목현","type":"지휘","to":"김우찬","basis":"김우찬의 작전표를 봉인 상태로만 나르는 지휘이고"},{"from":"지목현","type":"계약","to":"임겨레","basis":"임겨레의 기한 조항을 약국에 배달하는 계약이며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0130', 'b9c8-c7a5-d765', '{"id":"person-0130","name":"Ma Gilsang","title":"Eastern Bridge Underside Surveyor","position":"Eastern Bridge Underside Surveyor","characterId":"K129","rank":"Sergeant","commonTier":"T5","occupation":"Bridge Underside Water Sampling and Vibration Survey","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#person-Ma-Gilsang","detailRoute":"/people/person-0130","birthDate":"2097-09-21","birthday":"09-21","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":9,"effective":9},"intrigue":{"base":13,"effective":13},"learning":{"base":10,"effective":10},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k129-bridge-sampling","name":"Bridge water sampling","rating":60}],"traits":[{"id":"k129-choice","name":"Withholds hostile attribution","description":"He read time from the water temperature under the bridge and took no pride in a manhole missing from the map. He counted a late report a fault.","behavior":"Anecdote. In 2125, when the first report of a bridge-raid exercise proved wrong, he reopened the observation column. By this deed the signature of the eastern bridge underside surveyor post rose into the ledger.","stress":"Fear. That the survey routes would be sealed as military secrets and the water-main maps would be sold as the protection zone''s infiltration routes. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Under command to hand surveys to I Yunseo''s blockade clock, competing with Go Seojun''s ridge reconnaissance over passage coordinates, and sending bypass dotted lines to Seo Raon''s public map by contract.","effects":[]},{"id":"k129-boundary","name":"Maintains work boundaries","description":"Office. Rank: sergeant. Title: eastern bridge underside surveyor. He left intake and vibration in the same ledger, and a damaged section was marked hostile action only when I Yunseo and Jeong Soyul signed together.","behavior":"Office. Rank: sergeant. Title: eastern bridge underside surveyor. He left intake and vibration in the same ledger, and a damaged section was marked hostile action only when I Yunseo and Jeong Soyul signed together.","stress":"Fear. That the survey routes would be sealed as military secrets and the water-main maps would be sold as the protection zone''s infiltration routes. The actual response is not yet recorded.","relationship":"Relations. Under command to hand surveys to I Yunseo''s blockade clock, competing with Go Seojun''s ridge reconnaissance over passage coordinates, and sending bypass dotted lines to Seo Raon''s public map by contract.","effects":[]}],"narrative":"Anecdote. In 2125, when the first report of a bridge-raid exercise proved wrong, he reopened the observation column. By this deed the signature of the eastern bridge underside surveyor post rose into the ledger. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b9c8-c7a5-d765","name":"Jangheung Ma Clan","crest":"clan-crests/b9c8-c7a5-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":-30,"Force":50,"Material":20,"Communal":25,"Principle":-10,"Public":-45,"Eligibility":-10,"Dispersed":-50,"Transformative":-20},"desire":{"Longing":-5,"Monopoly":20,"Risk":0,"Display":-5,"Sustained":-10,"Orientation":"Reason","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Bridge Underside Water Sampling and Vibration Survey","Rank":"Sergeant","Title":"Eastern Bridge Underside Surveyor","Values":"Authority 60 | Openness −30 | Force 50 | Material 20 | Communal 25 | Principle −10 | Publicity −45 | Qualification −10 | Dispersion −50 | Transformation −20","Desires":"Craving −5 | Monopoly 20 | Risk 0 | Display −5 | Persistence −10 | Orientation Opposite-sex | Union Contract Cohabitation"},"sections":{"Offices":"Rank: Sergeant. Title: Eastern Bridge Underside Surveyor. Records water samples and vibrations in the same ledger, and a damaged section is marked as a hostile act only when Yi Yunseo and Jeong Soyul sign at the same time.\n\nAnecdote. When the initial report turned out wrong in the 2125 bridge assault drill, Ma Gilsang reopened the observation compartment.","Relationships":"Receives orders to hand surveys over to Yi Yunseo''s blockade clock, competes with Go Seojun''s ridge reconnaissance over passage coordinates, and sends detour dotted lines to Seo Raon''s public map by contract.","Ambition":"Draws the flooded detours of the eastern Han River bridges and the outer approach roads on a single public nautical chart so that the Blockade Corps stops firing by mistake.\n\nFear. Ma Gilsang fears that the survey routes will be sealed as military secrets and the water-pipe map sold as an infiltration route for the Protectorate.","Intervention":"Can take charge of diving escort to determine the cause of damage, or expose the secret infiltration route markings."},"biography":"Ma Gilsang reads the time from the water temperature of the supply pipes beneath the bridge, and takes no pride in manholes that are not on the map. He regards a late report as a sin.\n\n- Affiliation: Eastern Defense Command\n- Livelihood: Water sampling and vibration surveys under the bridge\n- Rank: Sergeant\n- Title: Eastern Bridge Underside Surveyor\nLife. Ma Gilsang was born in the 4th generation. Ma Gilsang grew up at the Amsa guard post. Ma Gilsang''s post of Eastern Bridge Underside Surveyor opened up after a night-time unauthorized river crossing was caught.\n- In duties linked with Amsa 2-dong, Ma Gilsang manages the ledger of water sampling and vibrations under the bridge, and obtains signatures from both the administration and the Blockade Corps for any damage.\n\n**Office.** Rank: Sergeant. Title: Eastern Bridge Underside Surveyor. Records water samples and vibrations in the same ledger, and a damaged section is marked as a hostile act only when Yi Yunseo and Jeong Soyul sign at the same time.\n\nAnecdote. When the initial report turned out wrong in the 2125 bridge assault drill, Ma Gilsang reopened the observation compartment.\n\n**Relations.** Receives orders to hand surveys over to Yi Yunseo''s blockade clock, competes with Go Seojun''s ridge reconnaissance over passage coordinates, and sends detour dotted lines to Seo Raon''s public map by contract.\n\n**Ambition.** Draws the flooded detours of the eastern Han River bridges and the outer approach roads on a single public nautical chart so that the Blockade Corps stops firing by mistake.\n\nFear. Ma Gilsang fears that the survey routes will be sealed as military secrets and the water-pipe map sold as an infiltration route for the Protectorate.\n\n**Intervention.** Can take charge of diving escort to determine the cause of damage, or expose the secret infiltration route markings.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 60 | Openness −30 | Force 50 | Material 20 | Communal 25 | Principle −10 | Publicity −45 | Qualification −10 | Dispersion −50 | Transformation −20\n- Desires: Craving −5 | Monopoly 20 | Risk 0 | Display −5 | Persistence −10 | Orientation Opposite-sex | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Ma Gilsang","type":"Command","to":"I Yunseo","basis":"Receives command to hand over surveying to Yi Yunseo''s blockade clock"},{"from":"Ma Gilsang","type":"Rivalry","to":"Go Seojun","basis":"competes with Go Seojun''s ridge reconnaissance over passage coordinates"}],"incoming":[{"from":"Ju Rian","type":"Contract","to":"Ma Gilsang","basis":"Divides Ma Gilsang''s bridge underside surveys and detour dotted lines by contract"}]}}', '{"id":"person-0130","name":"마길상","title":"동부 교량 하부 탐사원","position":"동부 교량 하부 탐사원","characterId":"K129","rank":"병장","commonTier":"T5","occupation":"교량 하부 채수·진동 조사","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-마길상","detailRoute":"/people/person-0130","birthDate":"2097-09-21","birthday":"09-21","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":9,"effective":9},"intrigue":{"base":13,"effective":13},"learning":{"base":10,"effective":10},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k129-bridge-sampling","name":"교량 채수 조사","rating":60}],"traits":[{"id":"k129-choice","name":"적대 판정 유보","description":"교량 아래 상수관 수온으로 시간을 읽고, 지도에 없는 맨홀을 자랑으로 여기지 않는다. 늦은 보고를 죄로 본다.","behavior":"일화. 2125년 교량 습격 훈련에서 최초 보고가 틀리자 참관 칸을 다시 열었다. 이 일로 동부 교량 하부 탐사원 자리의 서명이 장부에 올랐다.","stress":"공포. 탐사 경로가 군사 비밀로 봉인되어 상수관 지도가 보호권의 침투로로 팔리는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 이윤서의 봉쇄 시계에 측량을 넘기는 지휘를 받고, 고서준의 능선 정찰과 통행 좌표를 경쟁하며, 서라온의 공개 지도에 우회 점선을 계약으로 보낸다.","effects":[]},{"id":"k129-boundary","name":"업무 경계를 지킴","description":"관직. 품계 병장. 직함은 동부 교량 하부 탐사원. 채수와 진동을 같은 원장에 남기고, 파손 구간은 이윤서와 정소율이 동시에 서명해야 적대행위로 표시한다.","behavior":"관직. 품계 병장. 직함은 동부 교량 하부 탐사원. 채수와 진동을 같은 원장에 남기고, 파손 구간은 이윤서와 정소율이 동시에 서명해야 적대행위로 표시한다.","stress":"공포. 탐사 경로가 군사 비밀로 봉인되어 상수관 지도가 보호권의 침투로로 팔리는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 이윤서의 봉쇄 시계에 측량을 넘기는 지휘를 받고, 고서준의 능선 정찰과 통행 좌표를 경쟁하며, 서라온의 공개 지도에 우회 점선을 계약으로 보낸다.","effects":[]}],"narrative":"일화. 2125년 교량 습격 훈련에서 최초 보고가 틀리자 참관 칸을 다시 열었다. 이 일로 동부 교량 하부 탐사원 자리의 서명이 장부에 올랐다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b9c8-c7a5-d765","name":"장흥 마씨","crest":"clan-crests/b9c8-c7a5-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":-30,"무력":50,"물질":20,"공동":25,"원칙":-10,"공개":-45,"자격":-10,"분산":-50,"변혁":-20},"desire":{"갈망":-5,"독점":20,"위험":0,"과시":-5,"지속":-10,"지향":"이성","결합":"계약동거"},"fields":{"소속":"동방사","생업":"교량 하부 채수·진동 조사","품계":"병장","직함":"동부 교량 하부 탐사원","가치관":"권위 60 | 개방 −30 | 무력 50 | 물질 20 | 공동 25 | 원칙 −10 | 공개 −45 | 자격 −10 | 분산 −50 | 변혁 −20","욕망":"갈망 −5 | 독점 20 | 위험 0 | 과시 −5 | 지속 −10 | 지향 이성 | 결합 계약동거"},"sections":{"관직":"품계 병장. 직함은 동부 교량 하부 탐사원. 채수와 진동을 같은 원장에 남기고, 파손 구간은 이윤서와 정소율이 동시에 서명해야 적대행위로 표시한다.\n\n일화. 마길상은 2125년 교량 습격 훈련에서 최초 보고가 틀리자 참관 칸을 다시 열었다.","관계":"이윤서의 봉쇄 시계에 측량을 넘기는 지휘를 받고, 고서준의 능선 정찰과 통행 좌표를 경쟁하며, 서라온의 공개 지도에 우회 점선을 계약으로 보낸다.","야망":"동부 한강 교량과 외곽 진입로의 침수 우회를 한 장의 공개 해도로 그려 봉쇄대가 오인 사격을 멈추게 한다.\n\n공포. 마길상은 탐사 경로가 군사 비밀로 봉인되어 상수관 지도가 보호권의 침투로로 팔리는 일을 두려워한다.","개입":"잠수 호위를 맡아 파손 원인을 밝히거나, 비밀 침투로 표시를 폭로할 수 있다."},"biography":"마길상은 교량 아래 상수관 수온으로 시간을 읽고, 지도에 없는 맨홀을 자랑으로 여기지 않는다. 늦은 보고를 죄로 본다.\n\n- 소속: 동방사\n- 생업: 교량 하부 채수·진동 조사\n- 품계: 병장\n- 직함: 동부 교량 하부 탐사원\n생애. 마길상은 4세대에 태어났다. 마길상은 암사 경비 초소에서 자랐다. 마길상의 동부 교량 하부 탐사원 자리는 야간 무단 도하 적발로 열렸다.\n- 마길상은 암사2동과 연결된 업무에서 교량 하부 채수·진동 원장을 관리하고 파손에는 행정·봉쇄대 양쪽 서명을 받는다.\n\n**관직.** 품계 병장. 직함은 동부 교량 하부 탐사원. 채수와 진동을 같은 원장에 남기고, 파손 구간은 이윤서와 정소율이 동시에 서명해야 적대행위로 표시한다.\n\n일화. 마길상은 2125년 교량 습격 훈련에서 최초 보고가 틀리자 참관 칸을 다시 열었다.\n\n**관계.** 이윤서의 봉쇄 시계에 측량을 넘기는 지휘를 받고, 고서준의 능선 정찰과 통행 좌표를 경쟁하며, 서라온의 공개 지도에 우회 점선을 계약으로 보낸다.\n\n**야망.** 동부 한강 교량과 외곽 진입로의 침수 우회를 한 장의 공개 해도로 그려 봉쇄대가 오인 사격을 멈추게 한다.\n\n공포. 마길상은 탐사 경로가 군사 비밀로 봉인되어 상수관 지도가 보호권의 침투로로 팔리는 일을 두려워한다.\n\n**개입.** 잠수 호위를 맡아 파손 원인을 밝히거나, 비밀 침투로 표시를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 −30 | 무력 50 | 물질 20 | 공동 25 | 원칙 −10 | 공개 −45 | 자격 −10 | 분산 −50 | 변혁 −20\n- 욕망: 갈망 −5 | 독점 20 | 위험 0 | 과시 −5 | 지속 −10 | 지향 이성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"마길상","type":"지휘","to":"이윤서","basis":"이윤서의 봉쇄 시계에 측량을 넘기는 지휘를 받고"},{"from":"마길상","type":"경쟁","to":"고서준","basis":"고서준의 능선 정찰과 통행 좌표를 경쟁하며"}],"incoming":[{"from":"주리안","type":"계약","to":"마길상","basis":"마길상의 교량 하부 측량과 우회 점선을 계약으로 나눈다"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0131', 'c5f0-ace1-c0b0', '{"id":"person-0131","name":"Yeon Hajin","title":"Waterworks Administration Water Ledger Archivist","position":"Waterworks Administration Water Ledger Archivist","rank":"Sergeant","commonTier":"T5","occupation":"Water Ledger Copy Recording and Appeal Review Management","gender":"Male","stage":"S2","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0131","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0131","name":"연하진","title":"상수행정 급수원장 기록관","position":"상수행정 급수원장 기록관","rank":"병장","commonTier":"T5","occupation":"급수원장 사본 기록·재심 관리","gender":"남성","stage":"S2","state":"S05","stateName":"동방사","detailRoute":"/people/person-0131","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0132', 'b098-b098-c8fc-7f85', '{"id":"person-0132","name":"Na Hyowon","title":"Amsa Station Concourse Stationmaster","position":"Amsa Station Concourse Stationmaster","characterId":"K131","rank":"Company Commander","commonTier":"T4","occupation":"Concourse Water Counter and Waiting Ticket Management","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#character-na-hyowon","detailRoute":"/people/person-0132","birthDate":"2094-06-11","birthday":"06-11","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k131-water-queue","name":"Water queue management","rating":60}],"traits":[{"id":"k131-choice","name":"Water access first","description":"She counted the waiting crowd by dried stamp marks at the window and never put the protection escort''s stop announcements ahead of the water cups. When the chalk ran short, she cut the broadcasts.","behavior":"Anecdote. In 2125, when the accounts of two witnesses split, she opened a public confrontation. By this deed the signature of the Amsa Station concourse stationmaster post rose into the ledger.","stress":"Fear. That the concourse window would be swallowed by training-ground stop notices and the water-cup line would seep out under the bridge. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Executing Han Bora''s release hours in platform chalk, allied with Cha Naru in announcing the clinic lockdown by window stamps. Moved Choi Doyun''s alley waiting notes into the station chalkboard''s column.","effects":[]},{"id":"k131-boundary","name":"Maintains work boundaries","description":"Office. Rank: company commander. Title: Amsa Station concourse stationmaster. She did not sound the munitions-car whistle before the water-cup line circled the window once, and left only stamped waiting notes on the chalkboard.","behavior":"Office. Rank: company commander. Title: Amsa Station concourse stationmaster. She did not sound the munitions-car whistle before the water-cup line circled the window once, and left only stamped waiting notes on the chalkboard.","stress":"Fear. That the concourse window would be swallowed by training-ground stop notices and the water-cup line would seep out under the bridge. The actual response is not yet recorded.","relationship":"Relations. Executing Han Bora''s release hours in platform chalk, allied with Cha Naru in announcing the clinic lockdown by window stamps. Moved Choi Doyun''s alley waiting notes into the station chalkboard''s column.","effects":[]}],"narrative":"Anecdote. In 2125, when the accounts of two witnesses split, she opened a public confrontation. By this deed the signature of the Amsa Station concourse stationmaster post rose into the ledger. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b098-b098-c8fc-7f85","name":"Naju Na Clan","crest":"clan-crests/b098-b098-c8fc-7f85.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":65,"Openness":-35,"Force":55,"Material":10,"Communal":35,"Principle":-15,"Public":-40,"Eligibility":-15,"Dispersed":-55,"Transformative":-30},"desire":{"Longing":-5,"Monopoly":30,"Risk":-25,"Display":10,"Sustained":-10,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Concourse Water Counter and Waiting Ticket Management","Rank":"Company Commander","Title":"Amsa Station Concourse Stationmaster","Values":"Authority 65 | Openness −35 | Force 55 | Material 10 | Communal 35 | Principle −15 | Publicity −40 | Qualification −15 | Dispersion −55 | Transformation −30","Desires":"Craving −5 | Possessiveness 30 | Risk −25 | Display 10 | Endurance −10 | Orientation Same-sex | Union Contract Cohabitation"},"sections":{"Offices":"Rank: Company Commander. Title: Stationmaster of the Amsa Station Concourse. She does not sound the quartermaster car whistle until the water-cup line has gone once around the counter, and she leaves only stamped waiting slips on the blackboard.\n\nAnecdote. In 2125, when the accounts of two witnesses diverged, Na Hyo-won opened a public confrontation.","Relationships":"An ally who enforces Han Bo-ra''s dispatch times with platform chalk and announces infirmary lockdowns with the counter stamp. She moves Choe Do-yun''s alley waiting slips into the station blackboard column.","Ambition":"She makes the water cups, medical queue and transit stamps get stamped at one counter, so that protection contracts are not signed outside the counter.\n\nFear. Na Hyo-won fears that the concourse counter will be swallowed by the training ground''s stop announcements, and that the water-cup line will seep out beneath the bridge.","Intervention":"She can place the water-cup-only counter ahead of the registry''s announcements, or single out from the blackboard the hand that tampered with the dry stamp spots."},"biography":"Na Hyo-won counts the people waiting by the dry spots on the counter stamp, and does not put the protective Eastern Directorate''s stop announcements ahead of the water cups. When the chalk grows short, she cuts back the announcements.\n\n- Affiliation: Eastern Directorate\n- Livelihood: Concourse water counter and waiting-ticket management\n- Rank: Company Commander\n- Title: Stationmaster of the Amsa Station Concourse\nLife. Na Hyo-won was born in the 4th generation. Na Hyo-won grew up on concourse duty. Na Hyo-won''s post as Stationmaster of the Amsa Station Concourse opened through a substitute shift covering an unexcused absence.\n- In work tied to Amsa 2-dong, Na Hyo-won handles the Amsa Station water-cup, medical-queue and transit-stamp counters.\n\n**Office.** Rank: Company Commander. Title: Stationmaster of the Amsa Station Concourse. She does not sound the quartermaster car whistle until the water-cup line has gone once around the counter, and she leaves only stamped waiting slips on the blackboard.\n\nAnecdote. In 2125, when the accounts of two witnesses diverged, Na Hyo-won opened a public confrontation.\n\n**Relationships.** An ally who enforces Han Bo-ra''s dispatch times with platform chalk and announces infirmary lockdowns with the counter stamp. She moves Choe Do-yun''s alley waiting slips into the station blackboard column.\n\n**Ambition.** She makes the water cups, medical queue and transit stamps get stamped at one counter, so that protection contracts are not signed outside the counter.\n\nFear. Na Hyo-won fears that the concourse counter will be swallowed by the training ground''s stop announcements, and that the water-cup line will seep out beneath the bridge.\n\n**Intervention.** She can place the water-cup-only counter ahead of the registry''s announcements, or single out from the blackboard the hand that tampered with the dry stamp spots.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 65 | Openness −35 | Force 55 | Materialism 10 | Communality 35 | Principle −15 | Publicity −40 | Credentials −15 | Decentralization −55 | Transformation −30\n- Desires: Craving −5 | Possessiveness 30 | Risk −25 | Display 10 | Endurance −10 | Orientation Same-sex | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Na Hyowon","type":"Command","to":"Han Bora","basis":"enforcing Han Bora''s departure times with platform chalk,"}],"incoming":[]}}', '{"id":"person-0132","name":"나효원","title":"암사역 대합실 역장","position":"암사역 대합실 역장","characterId":"K131","rank":"중대장","commonTier":"T4","occupation":"대합실 급수 창구·대기표 관리","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-나효원","detailRoute":"/people/person-0132","birthDate":"2094-06-11","birthday":"06-11","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k131-water-queue","name":"급수 대기표 관리","rating":60}],"traits":[{"id":"k131-choice","name":"급수 창구 우선","description":"창구 스탬프의 마른 자리로 대기 인원을 세고, 보호 동방사의 정차 방송을 급수 컵보다 앞에 두지 않는다. 분필이 짧아지면 방송을 줄인다.","behavior":"일화. 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 암사역 대합실 역장 자리의 서명이 장부에 올랐다.","stress":"공포. 대합실 창구가 훈련장 정차 안내에 먹혀 급수 컵 줄이 교량 밑으로 스며 나가는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 한보라의 출고 시각을 승강장 분필로 집행하며, 차나루의 의무소 봉쇄를 창구 스탬프로 알리는 동맹이다. 최도윤의 골목 대기 쪽지를 역 칠판 칸에 옮긴다.","effects":[]},{"id":"k131-boundary","name":"업무 경계를 지킴","description":"관직. 품계 중대장. 직함은 암사역 대합실 역장. 급수 컵 줄이 창구를 한 바퀴 돌기 전에는 군수 칸 호각을 울리지 않고, 대기 쪽지는 스탬프가 찍힌 것만 칠판에 남긴다.","behavior":"관직. 품계 중대장. 직함은 암사역 대합실 역장. 급수 컵 줄이 창구를 한 바퀴 돌기 전에는 군수 칸 호각을 울리지 않고, 대기 쪽지는 스탬프가 찍힌 것만 칠판에 남긴다.","stress":"공포. 대합실 창구가 훈련장 정차 안내에 먹혀 급수 컵 줄이 교량 밑으로 스며 나가는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 한보라의 출고 시각을 승강장 분필로 집행하며, 차나루의 의무소 봉쇄를 창구 스탬프로 알리는 동맹이다. 최도윤의 골목 대기 쪽지를 역 칠판 칸에 옮긴다.","effects":[]}],"narrative":"일화. 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 암사역 대합실 역장 자리의 서명이 장부에 올랐다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b098-b098-c8fc-7f85","name":"나주 나씨","crest":"clan-crests/b098-b098-c8fc-7f85.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":65,"개방":-35,"무력":55,"물질":10,"공동":35,"원칙":-15,"공개":-40,"자격":-15,"분산":-55,"변혁":-30},"desire":{"갈망":-5,"독점":30,"위험":-25,"과시":10,"지속":-10,"지향":"동성","결합":"계약동거"},"fields":{"소속":"동방사","생업":"대합실 급수 창구·대기표 관리","품계":"중대장","직함":"암사역 대합실 역장","가치관":"권위 65 | 개방 −35 | 무력 55 | 물질 10 | 공동 35 | 원칙 −15 | 공개 −40 | 자격 −15 | 분산 −55 | 변혁 −30","욕망":"갈망 −5 | 독점 30 | 위험 −25 | 과시 10 | 지속 −10 | 지향 동성 | 결합 계약동거"},"sections":{"관직":"품계 중대장. 직함은 암사역 대합실 역장. 급수 컵 줄이 창구를 한 바퀴 돌기 전에는 군수 칸 호각을 울리지 않고, 대기 쪽지는 스탬프가 찍힌 것만 칠판에 남긴다.\n\n일화. 나효원은 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다.","관계":"한보라의 출고 시각을 승강장 분필로 집행하며, 의무소 봉쇄를 창구 스탬프로 알리는 동맹이다. 최도윤의 골목 대기 쪽지를 역 칠판 칸에 옮긴다.","야망":"급수 컵과 진료 대기와 통행 스탬프가 한 창구에서 찍히게 해, 보호계약이 창구 밖에서 서명되지 않게 한다.\n\n공포. 나효원은 대합실 창구가 훈련장 정차 안내에 먹혀 급수 컵 줄이 교량 밑으로 스며 나가는 일을 두려워한다.","개입":"급수 컵 전용 창구를 등록소 안내보다 앞에 두거나, 마른 스탬프 자리를 조작한 손을 칠판에서 가릴 수 있다."},"biography":"나효원은 창구 스탬프의 마른 자리로 대기 인원을 세고, 보호 동방사의 정차 방송을 급수 컵보다 앞에 두지 않는다. 분필이 짧아지면 방송을 줄인다.\n\n- 소속: 동방사\n- 생업: 대합실 급수 창구·대기표 관리\n- 품계: 중대장\n- 직함: 암사역 대합실 역장\n생애. 나효원은 4세대에 태어났다. 나효원은 대합실 당직에서 자랐다. 나효원의 암사역 대합실 역장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 나효원은 암사2동과 연결된 업무에서 암사역 급수 컵과 진료 대기, 통행 스탬프 창구를 맡는다.\n\n**관직.** 품계 중대장. 직함은 암사역 대합실 역장. 급수 컵 줄이 창구를 한 바퀴 돌기 전에는 군수 칸 호각을 울리지 않고, 대기 쪽지는 스탬프가 찍힌 것만 칠판에 남긴다.\n\n일화. 나효원은 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다.\n\n**관계.** 한보라의 출고 시각을 승강장 분필로 집행하며, 의무소 봉쇄를 창구 스탬프로 알리는 동맹이다. 최도윤의 골목 대기 쪽지를 역 칠판 칸에 옮긴다.\n\n**야망.** 급수 컵과 진료 대기와 통행 스탬프가 한 창구에서 찍히게 해, 보호계약이 창구 밖에서 서명되지 않게 한다.\n\n공포. 나효원은 대합실 창구가 훈련장 정차 안내에 먹혀 급수 컵 줄이 교량 밑으로 스며 나가는 일을 두려워한다.\n\n**개입.** 급수 컵 전용 창구를 등록소 안내보다 앞에 두거나, 마른 스탬프 자리를 조작한 손을 칠판에서 가릴 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 65 | 개방 −35 | 무력 55 | 물질 10 | 공동 35 | 원칙 −15 | 공개 −40 | 자격 −15 | 분산 −55 | 변혁 −30\n- 욕망: 갈망 −5 | 독점 30 | 위험 −25 | 과시 10 | 지속 −10 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"나효원","type":"지휘","to":"한보라","basis":"한보라의 출고 시각을 승강장 분필로 집행하며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0133', 'c591-ccad-c8fc', '{"id":"person-0133","name":"Yang Giseok","title":"Godeok Base Siding Supervisor","position":"Godeok Base Siding Supervisor","characterId":"K132","rank":"Company Commander","commonTier":"T4","occupation":"Siding Power and Interlocking Inspection","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#person-yang-gi-seok","detailRoute":"/people/person-0133","birthDate":"2070-02-14","birthday":"02-14","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k132-siding-interlock","name":"Siding interlock checking","rating":65}],"traits":[{"id":"k132-choice","name":"Protects waterworks interlock","description":"When the siding lamps blinked twice in a row he stopped talking, and he pasted no munitions-charging notes on the battery box. He erased no lamp counts from the rotation log.","behavior":"Anecdote. When the Godeok lamps went out all at once at midnight, Yang Giseok pulled the merchants'' charging lines and left only the purification motor''s lockout alive.","stress":"Fear. That on an empty-box night the purification motor''s lockout would not open, and the merchants'' council would call that gap the price of a protection extension. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Under command to match lamp counts to Park Hayul''s release whistle, he lent only the needle to Yang Pilho''s trials. The refusals on empty-box nights remained as debts to the merchants'' council.","effects":[]},{"id":"k132-boundary","name":"Maintains work boundaries","description":"Office. Rank: company commander. Title: Godeok depot siding supervisor. When the lamps blinked twice in a row he pulled the munitions line, and opened the charging box''s bolt only after the water train''s lockout.","behavior":"Office. Rank: company commander. Title: Godeok depot siding supervisor. When the lamps blinked twice in a row he pulled the munitions line, and opened the charging box''s bolt only after the water train''s lockout.","stress":"Fear. That on an empty-box night the purification motor''s lockout would not open, and the merchants'' council would call that gap the price of a protection extension. The actual response is not yet recorded.","relationship":"Relations. Under command to match lamp counts to Park Hayul''s release whistle, he lent only the needle to Yang Pilho''s trials. The refusals on empty-box nights remained as debts to the merchants'' council.","effects":[]}],"narrative":"Anecdote. When the Godeok lamps went out all at once at midnight, Yang Giseok pulled the merchants'' charging lines and left only the purification motor''s lockout alive. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c591-ccad-c8fc","name":"Cheongju Yang Clan","crest":"clan-crests/c591-ccad-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":-35,"Force":65,"Material":15,"Communal":40,"Principle":-20,"Public":-50,"Eligibility":-25,"Dispersed":-50,"Transformative":-40},"desire":{"Longing":5,"Monopoly":-25,"Risk":-15,"Display":-5,"Sustained":20,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Siding Power and Interlocking Inspection","Rank":"Company Commander","Title":"Godeok Base Siding Supervisor","Values":"Authority 60 | Openness −35 | Force 65 | Materialism 15 | Communality 40 | Principle −20 | Publicity −50 | Credentials −25 | Decentralization −50 | Transformation −40","Desires":"Craving 5 | Possessiveness −25 | Risk −15 | Display −5 | Endurance 20 | Orientation Fluid | Union Monogamy"},"sections":{"Offices":"Rank: Company Commander. Title: Godeok Base Stabling Track Supervisor. When the lamp blinks twice in a row across two cars, he pulls the quartermaster line, and he opens the latch of the charging box only after the water train interlock has opened.","Anecdote":"When the Godeok lamps all went out at once in the dead of night, Yang Gi-seok left only the purification motor interlock in place and pulled the Merchant Guild''s charging line.","Relationships":"He takes direction from Bak Ha-yul''s dispatch whistle, matching lamp counts to it, and lends only the needle to the test runs. A refusal on a night when the box is empty remains as a debt owed to the Merchant Guild.","Ambition":"He binds the stabling lamps into an interlock reserved for water and patrol service, so that late-night dispatches must pass through the purification motor.\n\nFear. Yang Gi-seok fears that on a night when the box is empty the purification motor interlock will not open, and the Merchant Guild will name that gap as the price of extending its protection.","Intervention":"He can choose to keep only the water train interlock alive on a night when the box is empty, or single out on the stabling blackboard the hand that erased the lamp counts."},"biography":"Yang Gi-seok stops talking when the stabling lamp blinks twice in a row across two cars, and never lets a quartermaster charging slip be stuck on the outside of a battery box. He never erases the shift lamp counts from the log.\n\n- Affiliation: Eastern Directorate\n- Livelihood: Stabling-track power and interlock inspection\n- Rank: Company Commander\n- Title: Godeok Base Stabling Track Supervisor\nLife. Yang Gi-seok was born in the 3rd generation. Yang Gi-seok grew up at Sinjeong Depot. Yang Gi-seok''s post as Godeok Base Stabling Track Supervisor opened after a defect report filed just before a derailment.\n- In work tied to Godeok 2-dong, Yang Gi-seok monitors the stabling lamps and the lock state of the purification motor, and cuts off the quartermaster charging line.\n\n**Office.** Rank: Company Commander. Title: Godeok Base Stabling Track Supervisor. When the lamp blinks twice in a row across two cars, he pulls the quartermaster line, and he opens the latch of the charging box only after the water train interlock has opened.\n\n**Anecdote.** When the Godeok lamps all went out at once in the dead of night, Yang Gi-seok left only the purification motor interlock in place and pulled the Merchant Guild''s charging line.\n\n**Relationships.** He takes direction from Bak Ha-yul''s dispatch whistle, matching lamp counts to it, and lends only the needle to the test runs. A refusal on a night when the box is empty remains as a debt owed to the Merchant Guild.\n\n**Ambition.** He binds the stabling lamps into an interlock reserved for water and patrol service, so that late-night dispatches must pass through the purification motor.\n\nFear. Yang Gi-seok fears that on a night when the box is empty the purification motor interlock will not open, and the Merchant Guild will name that gap as the price of extending its protection.\n\n**Intervention.** He can choose to keep only the water train interlock alive on a night when the box is empty, or single out on the stabling blackboard the hand that erased the lamp counts.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 60 | Openness −35 | Force 65 | Materialism 15 | Communality 40 | Principle −20 | Publicity −50 | Credentials −25 | Decentralization −50 | Transformation −40\n- Desires: Craving 5 | Possessiveness −25 | Risk −15 | Display −5 | Endurance 20 | Orientation Fluid | Union Monogamy\n:::","relations":{"outgoing":[{"from":"Yang Giseok","type":"Command","to":"Bak Hayul","basis":"Receives command to match lamp counts to Bak Hayul''s dispatch whistle"}],"incoming":[{"from":"Seol Bom-i","type":"Contract","to":"Yang Giseok","basis":"Backing Yang Gi-seok''s allocation of stabling-track power from the generation side, and"}]}}', '{"id":"person-0133","name":"양기석","title":"고덕기지 유치선 감독","position":"고덕기지 유치선 감독","characterId":"K132","rank":"중대장","commonTier":"T4","occupation":"유치선 전력·쇄정 점검","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-양기석","detailRoute":"/people/person-0133","birthDate":"2070-02-14","birthday":"02-14","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k132-siding-interlock","name":"유치선 쇄정 점검","rating":65}],"traits":[{"id":"k132-choice","name":"정수 쇄정 보전","description":"유치 램프가 두 칸 연속 깜빡이면 말을 멈추고, 군수 충전 쪽지는 축전지 함 겉에 붙이지 않는다. 교대 램프 횟수를 일지에서 지우지 않는다.","behavior":"일화. 고덕 램프가 심야에 한꺼번에 꺼지자 양기석은 정수 전동기 쇄정만 남기고 상회 충전 줄을 뽑았다.","stress":"공포. 함이 빈 밤에 정수 전동기 쇄정이 열리지 않고, 상회가 그 공백을 보호 연장의 값으로 부르는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 박하율의 출고 호각에 램프 횟수를 맞추는 지휘를 받고, 양필호의 시운전에 바늘만 빌려 준다. 함이 빈 밤의 거절은 상회 쪽 빚으로 남긴다.","effects":[]},{"id":"k132-boundary","name":"업무 경계를 지킴","description":"관직. 품계 중대장. 직함은 고덕기지 유치선 감독. 램프가 두 칸 연속 깜빡이면 군수 줄을 뽑고, 급수열차 쇄정이 열린 뒤에만 충전 함의 빗장을 연다.","behavior":"관직. 품계 중대장. 직함은 고덕기지 유치선 감독. 램프가 두 칸 연속 깜빡이면 군수 줄을 뽑고, 급수열차 쇄정이 열린 뒤에만 충전 함의 빗장을 연다.","stress":"공포. 함이 빈 밤에 정수 전동기 쇄정이 열리지 않고, 상회가 그 공백을 보호 연장의 값으로 부르는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 박하율의 출고 호각에 램프 횟수를 맞추는 지휘를 받고, 양필호의 시운전에 바늘만 빌려 준다. 함이 빈 밤의 거절은 상회 쪽 빚으로 남긴다.","effects":[]}],"narrative":"일화. 고덕 램프가 심야에 한꺼번에 꺼지자 양기석은 정수 전동기 쇄정만 남기고 상회 충전 줄을 뽑았다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c591-ccad-c8fc","name":"청주 양씨","crest":"clan-crests/c591-ccad-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":-35,"무력":65,"물질":15,"공동":40,"원칙":-20,"공개":-50,"자격":-25,"분산":-50,"변혁":-40},"desire":{"갈망":5,"독점":-25,"위험":-15,"과시":-5,"지속":20,"지향":"유동","결합":"단혼"},"fields":{"소속":"동방사","생업":"유치선 전력·쇄정 점검","품계":"중대장","직함":"고덕기지 유치선 감독","가치관":"권위 60 | 개방 −35 | 무력 65 | 물질 15 | 공동 40 | 원칙 −20 | 공개 −50 | 자격 −25 | 분산 −50 | 변혁 −40","욕망":"갈망 5 | 독점 −25 | 위험 −15 | 과시 −5 | 지속 20 | 지향 유동 | 결합 단혼"},"sections":{"관직":"품계 중대장. 직함은 고덕기지 유치선 감독. 램프가 두 칸 연속 깜빡이면 군수 줄을 뽑고, 급수열차 쇄정이 열린 뒤에만 충전 함의 빗장을 연다.","일화":"고덕 램프가 심야에 한꺼번에 꺼지자 양기석은 정수 전동기 쇄정만 남기고 상회 충전 줄을 뽑았다.","관계":"박하율의 출고 호각에 램프 횟수를 맞추는 지휘를 받고, 시운전에 바늘만 빌려 준다. 함이 빈 밤의 거절은 상회 쪽 빚으로 남긴다.","야망":"유치 램프를 급수·순찰 전용 쇄정으로 묶어 심야 출고가 정수 전동기를 거치게 한다.\n\n공포. 양기석은 함이 빈 밤에 정수 전동기 쇄정이 열리지 않고, 상회가 그 공백을 보호 연장의 값으로 부르는 일을 두려워한다.","개입":"함이 빈 밤에 급수열차 쇄정만 살리는 쪽을 고르거나, 램프 횟수를 지운 손을 유치 칠판에서 가릴 수 있다."},"biography":"양기석은 유치 램프가 두 칸 연속 깜빡이면 말을 멈추고, 군수 충전 쪽지는 축전지 함 겉에 붙이지 않는다. 교대 램프 횟수를 일지에서 지우지 않는다.\n\n- 소속: 동방사\n- 생업: 유치선 전력·쇄정 점검\n- 품계: 중대장\n- 직함: 고덕기지 유치선 감독\n생애. 양기석은 3세대에 태어났다. 양기석은 신정 차량기지에서 자랐다. 양기석의 고덕기지 유치선 감독 자리는 탈선 직전 결함 보고로 열렸다.\n- 양기석은 고덕2동과 연결된 업무에서 유치 램프와 정수 전동기 잠금 상태를 살피고 군수 충전 줄을 차단한다.\n\n**관직.** 품계 중대장. 직함은 고덕기지 유치선 감독. 램프가 두 칸 연속 깜빡이면 군수 줄을 뽑고, 급수열차 쇄정이 열린 뒤에만 충전 함의 빗장을 연다.\n\n**일화.** 고덕 램프가 심야에 한꺼번에 꺼지자 양기석은 정수 전동기 쇄정만 남기고 상회 충전 줄을 뽑았다.\n\n**관계.** 박하율의 출고 호각에 램프 횟수를 맞추는 지휘를 받고, 시운전에 바늘만 빌려 준다. 함이 빈 밤의 거절은 상회 쪽 빚으로 남긴다.\n\n**야망.** 유치 램프를 급수·순찰 전용 쇄정으로 묶어 심야 출고가 정수 전동기를 거치게 한다.\n\n공포. 양기석은 함이 빈 밤에 정수 전동기 쇄정이 열리지 않고, 상회가 그 공백을 보호 연장의 값으로 부르는 일을 두려워한다.\n\n**개입.** 함이 빈 밤에 급수열차 쇄정만 살리는 쪽을 고르거나, 램프 횟수를 지운 손을 유치 칠판에서 가릴 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 −35 | 무력 65 | 물질 15 | 공동 40 | 원칙 −20 | 공개 −50 | 자격 −25 | 분산 −50 | 변혁 −40\n- 욕망: 갈망 5 | 독점 −25 | 위험 −15 | 과시 −5 | 지속 20 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"양기석","type":"지휘","to":"박하율","basis":"박하율의 출고 호각에 램프 횟수를 맞추는 지휘를 받고"}],"incoming":[{"from":"설봄이","type":"계약","to":"양기석","basis":"양기석의 유치선 전력 배분을 발전 쪽에서 받치고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0134', 'c8fc-c2e0-c548', '{"id":"person-0134","name":"Ju Dan-a","title":"Godeok Water Market Auctioneer","position":"Godeok Water Market Auctioneer","characterId":"K133","rank":"Sergeant","commonTier":"T5","occupation":"Water Market Quality Sample Check and Auction","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#person-ju-dan-a","detailRoute":"/people/person-0134","birthDate":"2077-10-15","birthday":"10-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":12,"effective":12},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k133-water-auction","name":"Water auction","rating":65}],"traits":[{"id":"k133-choice","name":"Quality before sale","description":"She read canteen prices faster than the river wind and struck out at once from the morning lottery any merchant who cheated the scales. She bargained like a song but never raised the price in the service alleys.","behavior":"Anecdote. An emergency price offer from Nam Yungyeong''s side arrives just before the Godeok water market''s morning lottery. Ju Dana sends the offer back, reads the quality-sample sticker on each lot of raw water, and ties the substandard lots to the berth after writing down the winning bidder''s name.","stress":"Fear. That Garak''s price ledger would swallow the Godeok berths and eastern drinking water would sell at ration prices. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. A contract splitting gate slips and order with Ju Eunsol, checking Jeong Soyul''s water district seals before the auction, and sending Nam Yungyeong''s emergency price offer back as a grudge.","effects":[]},{"id":"k133-boundary","name":"Maintains work boundaries","description":"Office. Rank: sergeant. Title: Godeok water market auctioneer. She checked water-quality specimen stickers before the auction opened and let no substandard raw water sail even after a winning bid.","behavior":"Office. Rank: sergeant. Title: Godeok water market auctioneer. She checked water-quality specimen stickers before the auction opened and let no substandard raw water sail even after a winning bid.","stress":"Fear. That Garak''s price ledger would swallow the Godeok berths and eastern drinking water would sell at ration prices. The actual response is not yet recorded.","relationship":"Relations. A contract splitting gate slips and order with Ju Eunsol, checking Jeong Soyul''s water district seals before the auction, and sending Nam Yungyeong''s emergency price offer back as a grudge.","effects":[]}],"narrative":"Anecdote. An emergency price offer from Nam Yungyeong''s side arrives just before the Godeok water market''s morning lottery. Ju Dana sends the offer back, reads the quality-sample sticker on each lot of raw water, and ties the substandard lots to the berth after writing down the winning bidder''s name. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c8fc-c2e0-c548","name":"Sinan Ju Clan","crest":"clan-crests/c8fc-c2e0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-40,"Force":60,"Material":45,"Communal":35,"Principle":-20,"Public":-35,"Eligibility":-20,"Dispersed":-50,"Transformative":-20},"desire":{"Longing":10,"Monopoly":0,"Risk":35,"Display":25,"Sustained":40,"Orientation":"Fluid","Union":"None"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Water Market Quality Sample Check and Auction","Rank":"Sergeant","Title":"Godeok Water Market Auctioneer","Values":"Authority 55 | Openness −40 | Force 60 | Material 45 | Communal 35 | Principle −20 | Transparency −35 | Qualification −20 | Decentralization −50 | Transformation −20","Desires":"Craving 10 | Monopoly 0 | Risk 35 | Display 25 | Persistence 40 | Orientation Fluid | Pairing None"},"sections":{"Offices":"Rank Sergeant. Title: Auctioneer of the Godeok Water Market. Before an auction begins, checks the water-quality sample stickers; raw water that falls below standard is not shipped out even if it has been awarded to a bidder.","Anecdote":"An emergency price offer from Nam Yungyeong''s side arrives just before the morning lottery at the Godeok Water Market. Ju Dana sends the offer back, reads the water-quality sample stickers on the raw water placed on the auction block one by one, and for any raw water below standard, writes down the winning bidder''s name and then keeps it tied up at the berth.","Relationships":"A contract that splits gate vouchers and turn order; she checks Jeong Soyul''s water-district seal before the auction, and returns Nam Yungyeong''s emergency price offer with resentment.","Ambition":"She opens auctions of water barges and gate cargo only together with the administrative seal, so that the water price becomes the public ledger of the protection compact.\n\nFear. Ju Dana fears that Garak''s price ledger will swallow even the Godeok berths, so that eastern drinking water is sold at military ration prices.","Intervention":"He can expose the smuggler-boat winning-bid ledger, or escort the sealed samples to protect his public auction."},"biography":"Ju Dana reads canteen prices faster than the river wind, and immediately strikes merchants who cheat the scales from the morning lottery. She haggles as if singing, but never raises prices in the service alleys.\n\n- Affiliation: Eastern Office\n- Livelihood: Checking water-quality samples and auctioning at the water market\n- Rank: Sergeant\n- Title: Auctioneer of the Godeok Water Market\nLife. Ju Dana was born in Generation 3. Ju Dana grew up on the water-purification night watch in Yeongdeungpo. Ju Dana''s post as Auctioneer of the Godeok Water Market opened through a valve signature on Muddy Water Night.\n- In work connected with Godeok 1-dong, Ju Dana handles the water market''s water-quality samples and administrative seals, and holds back the departure of raw water that falls short of standard.\n\n**Office.** Rank Sergeant. Title: Auctioneer of the Godeok Water Market. Before an auction begins, checks the water-quality sample stickers; raw water that falls below standard is not shipped out even if it has been awarded to a bidder.\n\n**Anecdote.** An emergency price offer from Nam Yungyeong''s side arrives just before the morning lottery at the Godeok Water Market. Ju Dana sends the offer back, reads the water-quality sample stickers on the raw water placed on the auction block one by one, and for any raw water below standard, writes down the winning bidder''s name and then keeps it tied up at the berth.\n\n**Relations.** A contract that splits gate vouchers and turn order; she checks Jeong Soyul''s water-district seal before the auction, and returns Nam Yungyeong''s emergency price offer with resentment.\n\n**Ambition.** She opens auctions of water barges and gate cargo only together with the administrative seal, so that the water price becomes the public ledger of the protection compact.\n\nFear. Ju Dana fears that Garak''s price ledger will swallow even the Godeok berths, so that eastern drinking water is sold at military ration prices.\n\n**Intervention.** You can expose the smuggling winning-bid ledger, or escort the sealed samples to protect her public auction.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness −40 | Force 60 | Material 45 | Communal 35 | Principle −20 | Transparency −35 | Qualification −20 | Decentralization −50 | Transformation −20\n- Desires: Craving 10 | Monopoly 0 | Risk 35 | Display 25 | Persistence 40 | Orientation Fluid | Pairing None\n:::","relations":{"outgoing":[{"from":"Ju Dan-a","type":"Contract","to":"Jeong Soyul","basis":"Checking Jeong Soyul''s water supply district seals before the auction"}],"incoming":[]}}', '{"id":"person-0134","name":"주단아","title":"고덕 급수시장 경매사","position":"고덕 급수시장 경매사","characterId":"K133","rank":"병장","commonTier":"T5","occupation":"급수시장 수질 표본 확인·경매","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-주단아","detailRoute":"/people/person-0134","birthDate":"2077-10-15","birthday":"10-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":12,"effective":12},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k133-water-auction","name":"급수 경매","rating":65}],"traits":[{"id":"k133-choice","name":"낙찰보다 품질 기준","description":"강바람보다 수통 시세를 빨리 읽고, 저울을 속이는 상인을 아침 추첨에서 즉시 뺀다. 흥정을 노래처럼 하지만 복무 골목의 가격은 올리지 않는다.","behavior":"일화. 남윤경 쪽의 비상 시세 제의가 고덕 급수시장 아침 추첨 직전에 도착한다. 주단아는 제의서를 돌려보내고 경매대에 오른 원수의 수질 표본 스티커를 하나씩 읽으며, 기준에 모자란 원수는 낙찰자 이름을 적은 뒤 선석에 묶어 둔다.","stress":"공포. 가락의 가격 원장이 고덕 선석까지 삼켜 동부 식수가 군량 시세로 팔리는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 주은솔의 관문 전표와 순번을 나누는 계약이고, 정소율의 급수 구역 봉인을 경매 전 확인하며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.","effects":[]},{"id":"k133-boundary","name":"업무 경계를 지킴","description":"관직. 품계 병장. 직함은 고덕 급수시장 경매사. 경매 시작 전 수질 표본 스티커를 확인하고, 기준 미달 원수는 낙찰이 되어도 출항시키지 않는다.","behavior":"관직. 품계 병장. 직함은 고덕 급수시장 경매사. 경매 시작 전 수질 표본 스티커를 확인하고, 기준 미달 원수는 낙찰이 되어도 출항시키지 않는다.","stress":"공포. 가락의 가격 원장이 고덕 선석까지 삼켜 동부 식수가 군량 시세로 팔리는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 주은솔의 관문 전표와 순번을 나누는 계약이고, 정소율의 급수 구역 봉인을 경매 전 확인하며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.","effects":[]}],"narrative":"일화. 남윤경 쪽의 비상 시세 제의가 고덕 급수시장 아침 추첨 직전에 도착한다. 주단아는 제의서를 돌려보내고 경매대에 오른 원수의 수질 표본 스티커를 하나씩 읽으며, 기준에 모자란 원수는 낙찰자 이름을 적은 뒤 선석에 묶어 둔다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c8fc-c2e0-c548","name":"신안 주씨","crest":"clan-crests/c8fc-c2e0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":-40,"무력":60,"물질":45,"공동":35,"원칙":-20,"공개":-35,"자격":-20,"분산":-50,"변혁":-20},"desire":{"갈망":10,"독점":0,"위험":35,"과시":25,"지속":40,"지향":"유동","결합":"없음"},"fields":{"소속":"동방사","생업":"급수시장 수질 표본 확인·경매","품계":"병장","직함":"고덕 급수시장 경매사","가치관":"권위 55 | 개방 −40 | 무력 60 | 물질 45 | 공동 35 | 원칙 −20 | 공개 −35 | 자격 −20 | 분산 −50 | 변혁 −20","욕망":"갈망 10 | 독점 0 | 위험 35 | 과시 25 | 지속 40 | 지향 유동 | 결합 없음"},"sections":{"관직":"품계 병장. 직함은 고덕 급수시장 경매사. 경매 시작 전 수질 표본 스티커를 확인하고, 기준 미달 원수는 낙찰이 되어도 출항시키지 않는다.","일화":"남윤경 쪽의 비상 시세 제의가 고덕 급수시장 아침 추첨 직전에 도착한다. 주단아는 제의서를 돌려보내고 경매대에 오른 원수의 수질 표본 스티커를 하나씩 읽으며, 기준에 모자란 원수는 낙찰자 이름을 적은 뒤 선석에 묶어 둔다.","관계":"관문 전표와 순번을 나누는 계약이고, 정소율의 급수 구역 봉인을 경매 전 확인하며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.","야망":"급수 바지선과 관문 화물의 경매를 행정 봉인과 함께만 열어 물 시세가 보호계약의 공개 장부가 되게 한다.\n\n공포. 주단아는 가락의 가격 원장이 고덕 선석까지 삼켜 동부 식수가 군량 시세로 팔리는 일을 두려워한다.","개입":"밀선 낙찰 장부를 폭로하거나, 봉인 표본을 호송해 그의 공개 경매를 지킬 수 있다."},"biography":"주단아는 강바람보다 수통 시세를 빨리 읽고, 저울을 속이는 상인을 아침 추첨에서 즉시 뺀다. 흥정을 노래처럼 하지만 복무 골목의 가격은 올리지 않는다.\n\n- 소속: 동방사\n- 생업: 급수시장 수질 표본 확인·경매\n- 품계: 병장\n- 직함: 고덕 급수시장 경매사\n생애. 주단아는 3세대에 태어났다. 주단아는 영등포 정수 당직에서 자랐다. 주단아의 고덕 급수시장 경매사 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 주단아는 고덕1동과 연결된 업무에서 급수시장 수질 표본과 행정 봉인을 맡고 기준에 못 미친 원수의 출항을 보류한다.\n\n**관직.** 품계 병장. 직함은 고덕 급수시장 경매사. 경매 시작 전 수질 표본 스티커를 확인하고, 기준 미달 원수는 낙찰이 되어도 출항시키지 않는다.\n\n**일화.** 남윤경 쪽의 비상 시세 제의가 고덕 급수시장 아침 추첨 직전에 도착한다. 주단아는 제의서를 돌려보내고 경매대에 오른 원수의 수질 표본 스티커를 하나씩 읽으며, 기준에 모자란 원수는 낙찰자 이름을 적은 뒤 선석에 묶어 둔다.\n\n**관계.** 관문 전표와 순번을 나누는 계약이고, 정소율의 급수 구역 봉인을 경매 전 확인하며, 남윤경의 비상 시세 제의를 원한으로 돌려보낸다.\n\n**야망.** 급수 바지선과 관문 화물의 경매를 행정 봉인과 함께만 열어 물 시세가 보호계약의 공개 장부가 되게 한다.\n\n공포. 주단아는 가락의 가격 원장이 고덕 선석까지 삼켜 동부 식수가 군량 시세로 팔리는 일을 두려워한다.\n\n**개입.** 밀선 낙찰 장부를 폭로하거나, 봉인 표본을 호송해 그의 공개 경매를 지킬 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 −40 | 무력 60 | 물질 45 | 공동 35 | 원칙 −20 | 공개 −35 | 자격 −20 | 분산 −50 | 변혁 −20\n- 욕망: 갈망 10 | 독점 0 | 위험 35 | 과시 25 | 지속 40 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"주단아","type":"계약","to":"정소율","basis":"정소율의 급수 구역 봉인을 경매 전 확인하며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0135', 'cc28-c5f0-c548', '{"id":"person-0135","name":"Cha Yun-mok","title":"Eastern Mobile Medical Vehicle Squad Leader","position":"Eastern Mobile Medical Vehicle Squad Leader","characterId":"K134","rank":"Sergeant","commonTier":"T5","occupation":"Alleyway Clinic at the Mobile Medical Vehicle","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#person-cha-yunmok","detailRoute":"/people/person-0135","birthDate":"2084-07-01","birthday":"07-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":12,"effective":12},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k134-mobile-care","name":"Mobile alley care","rating":60}],"traits":[{"id":"k134-choice","name":"Neutral care routes","description":"He gauged dehydration from the moisture on the stretcher straps and pinned no note telling him to skip one alley for statistics onto the van''s nameplate. He drew the boiled-water marks on the medicine boxes himself.","behavior":"Anecdote. When the eastern patrol train overlaid the clinic van''s route with a weapons-search line, Cha Yunmok opened solidarity care only in the shaded alleys toward Bukhansan Bogukmun and refused escort boarding.","stress":"Fear. That the stretcher nameplates would turn into refugee notes and the van would be called only as a convoy to Bukhansan Bogukmun. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Owing a debt to avoid dodging Jang Sehwa''s neutral cars, turning stretchers into the alleys whenever Cha Naru''s purification window closed. Exchanged only nameplates with Baek On.","effects":[]},{"id":"k134-boundary","name":"Maintains work boundaries","description":"Office. Rank: sergeant. Title: eastern mobile clinic van chief. He drew the alleys'' water state on the van''s side board, and when a service note was pasted he opened shaded care with Choi Doyun''s joint signature.","behavior":"Office. Rank: sergeant. Title: eastern mobile clinic van chief. He drew the alleys'' water state on the van''s side board, and when a service note was pasted he opened shaded care with Choi Doyun''s joint signature.","stress":"Fear. That the stretcher nameplates would turn into refugee notes and the van would be called only as a convoy to Bukhansan Bogukmun. The actual response is not yet recorded.","relationship":"Relations. Owing a debt to avoid dodging Jang Sehwa''s neutral cars, turning stretchers into the alleys whenever Cha Naru''s purification window closed. Exchanged only nameplates with Baek On.","effects":[]}],"narrative":"Anecdote. When the eastern patrol train overlaid the clinic van''s route with a weapons-search line, Cha Yunmok opened solidarity care only in the shaded alleys toward Bukhansan Bogukmun and refused escort boarding. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":-20,"Force":35,"Material":10,"Communal":25,"Principle":-20,"Public":-40,"Eligibility":-30,"Dispersed":-45,"Transformative":-25},"desire":{"Longing":45,"Monopoly":-10,"Risk":35,"Display":5,"Sustained":30,"Orientation":"Bisexual","Union":"None"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Alleyway Clinic at the Mobile Medical Vehicle","Rank":"Sergeant","Title":"Eastern Mobile Medical Vehicle Squad Leader","Values":"Authority 60 | Openness −20 | Force 35 | Material 10 | Communal 25 | Principle −20 | Transparency −40 | Qualification −30 | Decentralization −45 | Transformation −25","Desires":"Craving 45 | Monopoly −10 | Risk 35 | Display 5 | Persistence 30 | Orientation Bisexual | Pairing None"},"sections":{"Offices":"Rank Sergeant. Title: Foreman of the Eastern Mobile Medical Car. Draws the alley''s moisture on the board at the car''s side, and when a service note is posted, opens a shade clinic with Choe Doyun''s countersignature.","Anecdote":"When the Eastern Patrol Train overlapped the medical car''s route with a weapons-search line, Cha Yunmok opened solidarity clinics only in the shade of the alleys toward Bukhansanbogungmun and refused to let an escort ride along.","Relationships":"Takes on debt so as not to avoid Jang Sehwa''s neutral car, and when the water-purification window closes, diverts the stretchers into the alleys. Swaps only name tags with Baek On.","Ambition":"To make the medical car stop even in alleys where a service note has been posted, so that the minimum line remains only on the name tag at the car''s side.\n\nFear. Cha Yunmok fears that the stretcher name tags will be swapped for refugee notes and the car will be called only a convoy bound for Bukhansanbogungmun.","Intervention":"You can return a box whose boiled-water mark has been erased to the car''s shade, or expose the route along which the stretcher name tags passed over to the refugee side."},"biography":"Cha Yunmok gauges the degree of dehydration by the moisture on the stretcher straps, and does not stick notes telling the car to skip an alley by statistics onto the name tag on the car''s side. Draws the boiled-water mark on the reagent box by hand.\n\n- Affiliation: Eastern Office\n- Livelihood: Alley clinics by the mobile medical car\n- Rank: Sergeant\n- Title: Foreman of the Eastern Mobile Medical Car\nLife. Cha Yunmok was born in Generation 3. Cha Yunmok grew up at the Jegi-dong infirmary. Cha Yunmok''s post as Foreman of the Eastern Mobile Medical Car opened through a seal on counterfeit medicine.\n- Cha Yunmok links the Eastern Mobile Medical Car''s alley clinic work, connected with Amsa 1-dong, to the water-purification window''s work through handovers.\n- In work connected with Jeongneung 4-dong, Cha Yunmok handles the shade solidarity clinics in the alleys toward Bukhansanbogungmun and the refusal of escort riders. A station and a clinic are different facilities.\n\n**Office.** Rank Sergeant. Title: Foreman of the Eastern Mobile Medical Car. Draws the alley''s moisture on the board at the car''s side, and when a service note is posted, opens a shade clinic with Choe Doyun''s countersignature.\n\n**Anecdote.** When the Eastern Patrol Train overlapped the medical car''s route with a weapons-search line, Cha Yunmok opened solidarity clinics only in the shade of the alleys toward Bukhansanbogungmun and refused to let an escort ride along.\n\n**Relations.** Takes on debt so as not to avoid Jang Sehwa''s neutral car, and when the water-purification window closes, diverts the stretchers into the alleys. Swaps only name tags with Baek On.\n\n**Ambition.** To make the medical car stop even in alleys where a service note has been posted, so that the minimum line remains only on the name tag at the car''s side.\n\nFear. Cha Yunmok fears that the stretcher name tags will be swapped for refugee notes and the car will be called only a convoy bound for Bukhansanbogungmun.\n\n**Intervention.** You can return a box whose boiled-water mark has been erased to the car''s shade, or expose the route along which the stretcher name tags passed over to the refugee side.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 60 | Openness −20 | Force 35 | Material 10 | Communal 25 | Principle −20 | Transparency −40 | Qualification −30 | Decentralization −45 | Transformation −25\n- Desires: Craving 45 | Monopoly −10 | Risk 35 | Display 5 | Persistence 30 | Orientation Bisexual | Pairing None\n:::","relations":{"outgoing":[{"from":"Cha Yun-mok","type":"Debt","to":"Jang Sehwa","basis":"Takes on debt so as not to avoid Jang Sehwa''s neutral car"}],"incoming":[]}}', '{"id":"person-0135","name":"차윤목","title":"동부 이동의무차 반장","position":"동부 이동의무차 반장","characterId":"K134","rank":"병장","commonTier":"T5","occupation":"이동의무차 골목 진료","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-차윤목","detailRoute":"/people/person-0135","birthDate":"2084-07-01","birthday":"07-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":12,"effective":12},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k134-mobile-care","name":"골목 이동 진료","rating":60}],"traits":[{"id":"k134-choice","name":"진료 경로 중립","description":"들것 끈의 물기로 탈수 정도를 가늠하고, 한 골목을 통계로 건너뛰라는 쪽지를 차 옆 명찰에 꽂지 않는다. 시약 상자의 끓인 물 표시는 직접 그린다.","behavior":"일화. 동부 순찰열차가 의무차 경로를 무기 수색선으로 겹치자 차윤목은 북한산보국문 쪽 골목 그늘에서만 연대 진료를 열고 호위 탑승을 거절했다.","stress":"공포. 들것 명찰이 난민 쪽지로 바뀌어 차가 북한산보국문행 호송으로만 불리는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 장세화의 중립 칸을 피하지 않으려 빚을 지고, 차나루의 정수 창구가 닫히면 들것을 골목으로 돌린다. 백온과 명찰만 바꿔 든다.","effects":[]},{"id":"k134-boundary","name":"업무 경계를 지킴","description":"관직. 품계 병장. 직함은 동부 이동의무차 반장. 차 옆 판에 골목 물기를 그리고, 복무 쪽지가 붙으면 최도윤의 연서로 그늘 진료를 연다.","behavior":"관직. 품계 병장. 직함은 동부 이동의무차 반장. 차 옆 판에 골목 물기를 그리고, 복무 쪽지가 붙으면 최도윤의 연서로 그늘 진료를 연다.","stress":"공포. 들것 명찰이 난민 쪽지로 바뀌어 차가 북한산보국문행 호송으로만 불리는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 장세화의 중립 칸을 피하지 않으려 빚을 지고, 차나루의 정수 창구가 닫히면 들것을 골목으로 돌린다. 백온과 명찰만 바꿔 든다.","effects":[]}],"narrative":"일화. 동부 순찰열차가 의무차 경로를 무기 수색선으로 겹치자 차윤목은 북한산보국문 쪽 골목 그늘에서만 연대 진료를 열고 호위 탑승을 거절했다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":-20,"무력":35,"물질":10,"공동":25,"원칙":-20,"공개":-40,"자격":-30,"분산":-45,"변혁":-25},"desire":{"갈망":45,"독점":-10,"위험":35,"과시":5,"지속":30,"지향":"양성","결합":"없음"},"fields":{"소속":"동방사","생업":"이동의무차 골목 진료","품계":"병장","직함":"동부 이동의무차 반장","가치관":"권위 60 | 개방 −20 | 무력 35 | 물질 10 | 공동 25 | 원칙 −20 | 공개 −40 | 자격 −30 | 분산 −45 | 변혁 −25","욕망":"갈망 45 | 독점 −10 | 위험 35 | 과시 5 | 지속 30 | 지향 양성 | 결합 없음"},"sections":{"관직":"품계 병장. 직함은 동부 이동의무차 반장. 차 옆 판에 골목 물기를 그리고, 복무 쪽지가 붙으면 최도윤의 연서로 그늘 진료를 연다.","일화":"동부 순찰열차가 의무차 경로를 무기 수색선으로 겹치자 차윤목은 북한산보국문 쪽 골목 그늘에서만 연대 진료를 열고 호위 탑승을 거절했다.","관계":"장세화의 중립 칸을 피하지 않으려 빚을 지고, 정수 창구가 닫히면 들것을 골목으로 돌린다. 백온과 명찰만 바꿔 든다.","야망":"복무 쪽지가 붙은 골목에도 의무차가 서게 해, 최저선이 차 옆 명찰에만 남게 한다.\n\n공포. 차윤목은 들것 명찰이 난민 쪽지로 바뀌어 차가 북한산보국문행 호송으로만 불리는 일을 두려워한다.","개입":"끓인 물 표시가 지워진 상자를 차 그늘로 되돌리거나, 들것 명찰이 난민 쪽으로 넘어간 경로를 폭로할 수 있다."},"biography":"차윤목은 들것 끈의 물기로 탈수 정도를 가늠하고, 한 골목을 통계로 건너뛰라는 쪽지를 차 옆 명찰에 꽂지 않는다. 시약 상자의 끓인 물 표시는 직접 그린다.\n\n- 소속: 동방사\n- 생업: 이동의무차 골목 진료\n- 품계: 병장\n- 직함: 동부 이동의무차 반장\n생애. 차윤목은 3세대에 태어났다. 차윤목은 제기동 의무소에서 자랐다. 차윤목의 동부 이동의무차 반장 자리는 가짜 약 봉인으로 열렸다.\n- 차윤목은 암사1동과 연결된 동부 이동의무차 골목 진료 업무를 정수 창구 업무와 인계로 잇는다.\n- 차윤목은 정릉4동과 연결된 업무에서 북한산보국문 쪽 골목 그늘 연대 진료와 호위 탑승 거부를 다룬다. 역과 진료소는 다른 시설이다.\n\n**관직.** 품계 병장. 직함은 동부 이동의무차 반장. 차 옆 판에 골목 물기를 그리고, 복무 쪽지가 붙으면 최도윤의 연서로 그늘 진료를 연다.\n\n**일화.** 동부 순찰열차가 의무차 경로를 무기 수색선으로 겹치자 차윤목은 북한산보국문 쪽 골목 그늘에서만 연대 진료를 열고 호위 탑승을 거절했다.\n\n**관계.** 장세화의 중립 칸을 피하지 않으려 빚을 지고, 정수 창구가 닫히면 들것을 골목으로 돌린다. 백온과 명찰만 바꿔 든다.\n\n**야망.** 복무 쪽지가 붙은 골목에도 의무차가 서게 해, 최저선이 차 옆 명찰에만 남게 한다.\n\n공포. 차윤목은 들것 명찰이 난민 쪽지로 바뀌어 차가 북한산보국문행 호송으로만 불리는 일을 두려워한다.\n\n**개입.** 끓인 물 표시가 지워진 상자를 차 그늘로 되돌리거나, 들것 명찰이 난민 쪽으로 넘어간 경로를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 −20 | 무력 35 | 물질 10 | 공동 25 | 원칙 −20 | 공개 −40 | 자격 −30 | 분산 −45 | 변혁 −25\n- 욕망: 갈망 45 | 독점 −10 | 위험 35 | 과시 5 | 지속 30 | 지향 양성 | 결합 없음\n:::","relations":{"outgoing":[{"from":"차윤목","type":"빚","to":"장세화","basis":"장세화의 중립 칸을 피하지 않으려 빚을 지고"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0136', 'c124-c21c-cc3d', '{"id":"person-0136","name":"Seol Bom-i","title":"Godeok Base Emergency Power Operator","position":"Godeok Base Emergency Power Operator","characterId":"K135","rank":"Company Commander","commonTier":"T4","occupation":"Emergency Generator Fuel and Output Operation","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#person-seol-bomi","detailRoute":"/people/person-0136","birthDate":"2082-11-14","birthday":"11-14","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":11,"effective":11},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k135-generator-output","name":"Generator output operation","rating":65}],"traits":[{"id":"k135-choice","name":"Rejects concealed allocation","description":"Sensitive to the smell of fuel, she hated verbal power routing. She took the political pressure to divert power from the purification motors to the training-ground lighting as an insult.","behavior":"Anecdote. In 2125 he felt out a wheel defect just short of a siding derailment and stopped the train. By this deed the signature of the Godeok depot emergency generator operator post rose into the ledger.","stress":"Fear. That on a night when the fuel ran dry the water gates would turn by hand alone, and the protection force''s dispatch would fill the gap. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Backed Yang Giseok''s siding power distribution from the generation side, matched output to Yang Pilho''s trials, and had obeyed Bae Woojin''s restoration-record disclosure but refused concealed power routing.","effects":[]},{"id":"k135-boundary","name":"Maintains work boundaries","description":"Office. Rank: company commander. Title: Godeok depot emergency generator operator. Every shift she sealed the fuel remainder and output logs and sent them to Yang Giseok, and below minimum output she cut the munitions power even under the commander''s urging.","behavior":"Office. Rank: company commander. Title: Godeok depot emergency generator operator. Every shift she sealed the fuel remainder and output logs and sent them to Yang Giseok, and below minimum output she cut the munitions power even under the commander''s urging.","stress":"Fear. That on a night when the fuel ran dry the water gates would turn by hand alone, and the protection force''s dispatch would fill the gap. The actual response is not yet recorded.","relationship":"Relations. Backed Yang Giseok''s siding power distribution from the generation side, matched output to Yang Pilho''s trials, and had obeyed Bae Woojin''s restoration-record disclosure but refused concealed power routing.","effects":[]}],"narrative":"Anecdote. In 2125 he felt out a wheel defect just short of a siding derailment and stopped the train. By this deed the signature of the Godeok depot emergency generator operator post rose into the ledger. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c124-c21c-cc3d","name":"Sunchang Seol Clan","crest":"clan-crests/c124-c21c-cc3d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":-35,"Force":50,"Material":20,"Communal":35,"Principle":-20,"Public":-40,"Eligibility":-30,"Dispersed":-40,"Transformative":-25},"desire":{"Longing":30,"Monopoly":-30,"Risk":-25,"Display":10,"Sustained":5,"Orientation":"Same-Sex","Union":"None"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Emergency Generator Fuel and Output Operation","Rank":"Company Commander","Title":"Godeok Base Emergency Power Operator","Values":"Authority 60 | Openness −35 | Force 50 | Material 20 | Communal 35 | Principle −20 | Publicity −40 | Qualification −30 | Decentralization −40 | Transformation −25","Desires":"Craving 30 | Monopoly −30 | Risk −25 | Display 10 | Persistence 5 | Orientation same-sex | Union none"},"sections":{"Offices":"Rank: Company Commander. Title: Godeok Base Emergency Generation Operator. Every shift, seals the fuel reserve and output log and sends it to Yang Giseok, and cuts military power distribution whenever output falls below the minimum, even when the commander presses.\n\nAnecdote. In 2125, Seol Bomi detected a wheel defect by touch just before a derailment on the siding and stopped the train.","Relationships":"Supports Yang Giseok''s siding power allocation from the generation side, matches output to test runs, and has complied with Bae Ujin''s public disclosure of restoration results but refused concealed power distribution.","Ambition":"Binds Godeok emergency generation and Amsa pump power into a single public distribution grid to protect the quality sovereignty of the eastern raw water.\n\nFear. Seol Bomi fears nights when the fuel runs out, the floodgates turn only by hand, and a Protectorate Force dispatch fills that gap.","Intervention":"He can secure substitute fuel to open a dual distribution grid, or expose the tampering with the output logs so that the operations chief is replaced."},"biography":"Seol Bomi is sensitive to the smell of fuel and dislikes verbal power distribution. Seol Bomi regards political pressure to divert power to the training ground lighting rather than the water-purification motors as an insult.\n\n- Affiliation: Eastern Defense Command\n- Occupation: Emergency generation fuel and output operation\n- Rank: Company Commander\n- Title: Godeok Base Emergency Generation Operator\nLife. Seol Bomi was born in the 3rd generation. Seol Bomi grew up at the Sinjeong depot. Seol Bomi''s post as Godeok Base Emergency Generation Operator opened through a defect report made just before a derailment.\n- In work connected with Godeok 2-dong, Seol Bomi manages the emergency generation fuel and output seals and cuts military power distribution if output falls short of the minimum.\n\n**Office.** Rank: Company Commander. Title: Godeok Base Emergency Generation Operator. Every shift, seals the fuel reserve and output log and sends it to Yang Giseok, and cuts military power distribution whenever output falls below the minimum, even when the commander presses.\n\nAnecdote. In 2125, Seol Bomi detected a wheel defect by touch just before a derailment on the siding and stopped the train.\n\n**Relations.** Supports Yang Giseok''s siding power allocation from the generation side, matches output to test runs, and has complied with Bae Ujin''s public disclosure of restoration results but refused concealed power distribution.\n\n**Ambition.** Binds Godeok emergency generation and Amsa pump power into a single public distribution grid to protect the quality sovereignty of the eastern raw water.\n\nFear. Seol Bomi fears nights when the fuel runs out, the floodgates turn only by hand, and a Protectorate Force dispatch fills that gap.\n\n**Intervention.** You can open dual distribution by securing alternative fuel, or expose tampering with the output log to replace the operator.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 60 | Openness −35 | Force 50 | Material 20 | Communal 35 | Principle −20 | Publicity −40 | Qualification −30 | Decentralization −40 | Transformation −25\n- Desires: Craving 30 | Monopoly −30 | Risk −25 | Display 10 | Persistence 5 | Orientation same-sex | Union none\n:::","relations":{"outgoing":[{"from":"Seol Bom-i","type":"Contract","to":"Bae Ujin","basis":"Obeys Bae Ujin''s public disclosure of restoration results but refuses concealed power distribution"},{"from":"Seol Bom-i","type":"Contract","to":"Yang Giseok","basis":"Backing Yang Gi-seok''s allocation of stabling-track power from the generation side, and"}],"incoming":[]}}', '{"id":"person-0136","name":"설봄이","title":"고덕기지 비상발전 운전장","position":"고덕기지 비상발전 운전장","characterId":"K135","rank":"중대장","commonTier":"T4","occupation":"비상발전 연료·출력 운전","gender":"남성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-설봄이","detailRoute":"/people/person-0136","birthDate":"2082-11-14","birthday":"11-14","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":11,"effective":11},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k135-generator-output","name":"발전 출력 운전","rating":65}],"traits":[{"id":"k135-choice","name":"은폐 배전 거부","description":"연료 냄새에 예민하고 구두 배전을 싫어한다. 정수 전동기보다 훈련장 조명에 전력을 돌리라는 정치적 압박을 모욕으로 여긴다.","behavior":"일화. 2125년 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 이 일로 고덕기지 비상발전 운전장 자리의 서명이 장부에 올랐다.","stress":"공포. 연료가 바닥난 밤에 수문이 수동으로만 돌아가고, 그 공백을 보호군 파견이 메우는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 양기석의 유치선 전력 배분을 발전 쪽에서 받치고, 양필호의 시운전에 출력을 맞추며, 배우진의 복구 실적 공개에는 복종해 왔지만 은폐 배전은 거부해 왔다.","effects":[]},{"id":"k135-boundary","name":"업무 경계를 지킴","description":"관직. 품계 중대장. 직함은 고덕기지 비상발전 운전장. 매 교대 연료 잔량과 출력 일지를 봉인해 양기석에게 보내고, 최저 출력 이하면 사령의 독촉이 있어도 군수 배전을 끊는다.","behavior":"관직. 품계 중대장. 직함은 고덕기지 비상발전 운전장. 매 교대 연료 잔량과 출력 일지를 봉인해 양기석에게 보내고, 최저 출력 이하면 사령의 독촉이 있어도 군수 배전을 끊는다.","stress":"공포. 연료가 바닥난 밤에 수문이 수동으로만 돌아가고, 그 공백을 보호군 파견이 메우는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 양기석의 유치선 전력 배분을 발전 쪽에서 받치고, 양필호의 시운전에 출력을 맞추며, 배우진의 복구 실적 공개에는 복종해 왔지만 은폐 배전은 거부해 왔다.","effects":[]}],"narrative":"일화. 2125년 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 이 일로 고덕기지 비상발전 운전장 자리의 서명이 장부에 올랐다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c124-c21c-cc3d","name":"순창 설씨","crest":"clan-crests/c124-c21c-cc3d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":-35,"무력":50,"물질":20,"공동":35,"원칙":-20,"공개":-40,"자격":-30,"분산":-40,"변혁":-25},"desire":{"갈망":30,"독점":-30,"위험":-25,"과시":10,"지속":5,"지향":"동성","결합":"없음"},"fields":{"소속":"동방사","생업":"비상발전 연료·출력 운전","품계":"중대장","직함":"고덕기지 비상발전 운전장","가치관":"권위 60 | 개방 −35 | 무력 50 | 물질 20 | 공동 35 | 원칙 −20 | 공개 −40 | 자격 −30 | 분산 −40 | 변혁 −25","욕망":"갈망 30 | 독점 −30 | 위험 −25 | 과시 10 | 지속 5 | 지향 동성 | 결합 없음"},"sections":{"관직":"품계 중대장. 직함은 고덕기지 비상발전 운전장. 매 교대 연료 잔량과 출력 일지를 봉인해 양기석에게 보내고, 최저 출력 이하면 사령의 독촉이 있어도 군수 배전을 끊는다.\n\n일화. 설봄이는 2125년 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다.","관계":"양기석의 유치선 전력 배분을 발전 쪽에서 받치고, 시운전에 출력을 맞추며, 배우진의 복구 실적 공개에는 복종해 왔지만 은폐 배전은 거부해 왔다.","야망":"고덕 비상 발전과 암사 펌프 전력을 하나의 공개 배전망으로 묶어 동부 원수의 품질 주권을 지킨다.\n\n공포. 설봄이는 연료가 바닥난 밤에 수문이 수동으로만 돌아가고, 그 공백을 보호군 파견이 메우는 일을 두려워한다.","개입":"대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다."},"biography":"설봄이는 연료 냄새에 예민하고 구두 배전을 싫어한다. 정수 전동기보다 훈련장 조명에 전력을 돌리라는 정치적 압박을 모욕으로 여긴다.\n\n- 소속: 동방사\n- 생업: 비상발전 연료·출력 운전\n- 품계: 중대장\n- 직함: 고덕기지 비상발전 운전장\n생애. 설봄이는 3세대에 태어났다. 설봄이는 신정 차량기지에서 자랐다. 설봄이의 고덕기지 비상발전 운전장 자리는 탈선 직전 결함 보고로 열렸다.\n- 설봄이는 고덕2동과 연결된 업무에서 비상발전 연료·출력 봉인을 관리하고 최저 출력에 못 미치면 군수 배전을 차단한다.\n\n**관직.** 품계 중대장. 직함은 고덕기지 비상발전 운전장. 매 교대 연료 잔량과 출력 일지를 봉인해 양기석에게 보내고, 최저 출력 이하면 사령의 독촉이 있어도 군수 배전을 끊는다.\n\n일화. 설봄이는 2125년 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다.\n\n**관계.** 양기석의 유치선 전력 배분을 발전 쪽에서 받치고, 시운전에 출력을 맞추며, 배우진의 복구 실적 공개에는 복종해 왔지만 은폐 배전은 거부해 왔다.\n\n**야망.** 고덕 비상 발전과 암사 펌프 전력을 하나의 공개 배전망으로 묶어 동부 원수의 품질 주권을 지킨다.\n\n공포. 설봄이는 연료가 바닥난 밤에 수문이 수동으로만 돌아가고, 그 공백을 보호군 파견이 메우는 일을 두려워한다.\n\n**개입.** 대체 연료를 구해 이중 배전을 열거나, 출력 일지 조작을 밝혀 운전장을 교체할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 −35 | 무력 50 | 물질 20 | 공동 35 | 원칙 −20 | 공개 −40 | 자격 −30 | 분산 −40 | 변혁 −25\n- 욕망: 갈망 30 | 독점 −30 | 위험 −25 | 과시 10 | 지속 5 | 지향 동성 | 결합 없음\n:::","relations":{"outgoing":[{"from":"설봄이","type":"계약","to":"배우진","basis":"배우진의 복구 실적 공개에는 복종하되 은폐 배전은 거부한다"},{"from":"설봄이","type":"계약","to":"양기석","basis":"양기석의 유치선 전력 배분을 발전 쪽에서 받치고"}],"incoming":[]}}');
