INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0140', 'bc30-bd84-c131-88f5', '{"id":"person-0140","name":"Bae Eun-chan","title":"Protection Clause Logistics Clerk","position":"Protection Clause Logistics Clerk","rank":"Sergeant","commonTier":"T5","occupation":"Protected Supplies Logistics Dispatch and Deadline Check","gender":"Male","stage":"S3","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0140","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0140","name":"배은찬","title":"보호조항 병참 서기","position":"보호조항 병참 서기","rank":"병장","commonTier":"T5","occupation":"보호물자 병참 출고·기한 확인","gender":"남성","stage":"S3","state":"S05","stateName":"동방사","detailRoute":"/people/person-0140","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0141', 'b958-bb38-d654-67f3', '{"id":"person-0141","name":"Ryu Ga-on","title":"Protection Force Deployment Escort Officer","position":"Protection Force Deployment Escort Officer","characterId":"K140","rank":"Sergeant","commonTier":"T5","occupation":"Deployed Personnel Roster and Escort Management","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#Person-Ryu-Gaon","detailRoute":"/people/person-0141","birthDate":"2079-08-10","birthday":"08-10","age":47,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k140-limited-escort","name":"Return-timed escort management","rating":60}],"traits":[{"id":"k140-choice","name":"Turns back at a locked bridge","description":"He read the militia barricade on the bridge not as a rescue target but as a passage refusal, and took no verbal garrison permit as an order. His routes were short and he wrote the return hours in advance.","behavior":"Anecdote. In 2125, meeting a raid mid-convoy, he secured the roster of lives before the freight. By this deed the signature of the protection force dispatch convoy master post rose into the ledger.","stress":"Fear. That the convoy train would stop on the Seongdong bridge and that stop would become the established fact of garrison. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Coupling a convoy car onto Han Bora''s patrol dispatch and executing Bae Woojin''s dispatch plan, but turning back with a record before Ki Hagyeom''s bridge lock.","effects":[]},{"id":"k140-boundary","name":"Maintains work boundaries","description":"Office. Rank: sergeant. Title: protection force dispatch convoy master. A dispatch roster departed only with both the water administration''s stamp and the escort''s code tags, and he turned back at the Godeok siding any roster whose return column stood empty.","behavior":"Office. Rank: sergeant. Title: protection force dispatch convoy master. A dispatch roster departed only with both the water administration''s stamp and the escort''s code tags, and he turned back at the Godeok siding any roster whose return column stood empty.","stress":"Fear. That the convoy train would stop on the Seongdong bridge and that stop would become the established fact of garrison. The actual response is not yet recorded.","relationship":"Relations. Coupling a convoy car onto Han Bora''s patrol dispatch and executing Bae Woojin''s dispatch plan, but turning back with a record before Ki Hagyeom''s bridge lock.","effects":[]}],"narrative":"Anecdote. In 2125, meeting a raid mid-convoy, he secured the roster of lives before the freight. By this deed the signature of the protection force dispatch convoy master post rose into the ledger. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":-35,"Force":60,"Material":25,"Communal":35,"Principle":-20,"Public":-30,"Eligibility":-20,"Dispersed":-55,"Transformative":-20},"desire":{"Longing":15,"Monopoly":-35,"Risk":30,"Display":-20,"Sustained":-15,"Orientation":"Bisexual","Union":"Polyamorous"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Deployed Personnel Roster and Escort Management","Rank":"Sergeant","Title":"Protection Force Deployment Escort Officer","Values":"Authority 60 | Openness −35 | Force 60 | Material 25 | Communal 35 | Principle −20 | Publicity −30 | Qualification −20 | Decentralization −55 | Transformation −20","Desires":"Craving 15 | Monopoly −35 | Risk 30 | Display −20 | Persistence −15 | Orientation bisexual | Union polyamorous"},"sections":{"Offices":"Rank: Sergeant. Title: Protectorate Force Dispatch Escort Officer. A dispatch roster departs only when both the Sangsu Administration seal and the Eastern Defense Command cipher tag are present, and any roster with a blank return time is turned back at the Godeok stabling siding.\n\nAnecdote. In 2125, ambushed during an escort, Ryu Gaon secured the personnel ledger before the cargo.","Relationships":"Attaches escort cars to Han Bora''s patrol train dispatch and carries out Bae Ujin''s dispatch plan, but in front of Gi Hagyeom''s bridge lock, leaves a record and turns back.","Ambition":"Keeps the Protectorate Force dispatch only as a time-limited escort, so that eastern officers do not settle in at the Ttukseom pump room.\n\nFear. Ryu Gaon fears that the escort train will stop at the Seongdong bridge and that the stop will become a fait accompli of garrisoning.","Intervention":"You can open the escort in a limited way by delivering a roster with return times written in, or disqualify the escort officer by exposing a car where garrison supplies are hidden."},"biography":"Ryu Gaon reads the militia barricade on the bridge not as a rescue target but as a refusal of passage, and does not accept verbal garrison permission as an order. Routes are short and the return time is written down in advance.\n\n- Affiliation: Eastern Defense Command\n- Occupation: Dispatch personnel roster and escort management\n- Rank: Sergeant\n- Title: Protectorate Force Dispatch Escort Officer\nLife. Ryu Gaon was born in the 3rd generation. Ryu Gaon grew up on the Sinnae transfer duty shift. Ryu Gaon''s post as Protectorate Force Dispatch Escort Officer opened after stopping an unticketed departing train.\n- In dispatch work connected with Godeok 2-dong, Ryu Gaon makes the administrative seal, the military cipher tag and the return time conditions, and returns if passage over the bridge is refused. Ryu Gaon holds no right of garrison.\n- In work connected with Seongsu 1-ga 2-dong, Ryu Gaon cross-checks the Ttukseom pump room dispatch plan against Gi Hagyeom''s refusal of bridge passage and the resulting return. This does not imply that the dispatch succeeds or that a garrison is established.\n\n**Office.** Rank: Sergeant. Title: Protectorate Force Dispatch Escort Officer. A dispatch roster departs only when both the Sangsu Administration seal and the Eastern Defense Command cipher tag are present, and any roster with a blank return time is turned back at the Godeok stabling siding.\n\nAnecdote. In 2125, ambushed during an escort, Ryu Gaon secured the personnel ledger before the cargo.\n\n**Relations.** Attaches escort cars to Han Bora''s patrol train dispatch and carries out Bae Ujin''s dispatch plan, but in front of Gi Hagyeom''s bridge lock, leaves a record and turns back.\n\n**Ambition.** Keeps the Protectorate Force dispatch only as a time-limited escort, so that eastern officers do not settle in at the Ttukseom pump room.\n\nFear. Ryu Gaon fears that the escort train will stop at the Seongdong bridge and that the stop will become a fait accompli of garrisoning.\n\n**Intervention.** You can open the escort in a limited way by delivering a roster with return times written in, or disqualify the escort officer by exposing a car where garrison supplies are hidden.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 60 | Openness −35 | Force 60 | Material 25 | Communal 35 | Principle −20 | Publicity −30 | Qualification −20 | Decentralization −55 | Transformation −20\n- Desires: Craving 15 | Monopoly −35 | Risk 30 | Display −20 | Persistence −15 | Orientation bisexual | Union polyamorous\n:::","relations":{"outgoing":[{"from":"Ryu Ga-on","type":"Contract","to":"Han Bora","basis":"attaching a convoy car to Han Bora''s patrol train dispatch and"},{"from":"Ryu Ga-on","type":"Contract","to":"Gi Ha-gyeom","basis":"Carries out Bae Ujin''s dispatch proposal, but turns back with a record left in front of Gi Hagyeom''s bridge lock"}],"incoming":[{"from":"Gi Ha-gyeom","type":"Contract","to":"Ryu Ga-on","basis":"Turns back the passage request of Amsa convoy chief Ryu Gaon, leaving only a record"}]}}', '{"id":"person-0141","name":"류가온","title":"보호군 파견 호송책","position":"보호군 파견 호송책","characterId":"K140","rank":"병장","commonTier":"T5","occupation":"파견 인명 명부·호송 관리","gender":"여성","stage":"S3","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-류가온","detailRoute":"/people/person-0141","birthDate":"2079-08-10","birthday":"08-10","age":47,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k140-limited-escort","name":"귀환 시각 호송 관리","rating":60}],"traits":[{"id":"k140-choice","name":"잠금 앞에서 돌아섬","description":"교량 위 민병 바리케이드를 구원 대상이 아니라 통과 거부로 읽고, 구두 주둔 허가를 명령으로 받지 않는다. 경로는 짧고 귀환 시각은 미리 적는다.","behavior":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 보호군 파견 호송책 자리의 서명이 장부에 올랐다.","stress":"공포. 호송 열차가 성동 교량에서 멈추고, 그 정차가 주둔의 기정사실이 되는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 한보라의 순찰열차 배차에 호송 칸을 붙이고, 배우진의 파견안을 실행하되 기하겸의 교량 잠금 앞에서는 기록을 남기고 돌아선다.","effects":[]},{"id":"k140-boundary","name":"업무 경계를 지킴","description":"관직. 품계 병장. 직함은 보호군 파견 호송책. 파견 명단은 상수행정 날인과 동방사 암호패가 함께 있어야 출발하고, 귀환 시각이 빈 칸은 고덕 유치선에서 되돌린다.","behavior":"관직. 품계 병장. 직함은 보호군 파견 호송책. 파견 명단은 상수행정 날인과 동방사 암호패가 함께 있어야 출발하고, 귀환 시각이 빈 칸은 고덕 유치선에서 되돌린다.","stress":"공포. 호송 열차가 성동 교량에서 멈추고, 그 정차가 주둔의 기정사실이 되는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 한보라의 순찰열차 배차에 호송 칸을 붙이고, 배우진의 파견안을 실행하되 기하겸의 교량 잠금 앞에서는 기록을 남기고 돌아선다.","effects":[]}],"narrative":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 보호군 파견 호송책 자리의 서명이 장부에 올랐다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b958-bb38-d654-67f3","name":"문화 류씨","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":-35,"무력":60,"물질":25,"공동":35,"원칙":-20,"공개":-30,"자격":-20,"분산":-55,"변혁":-20},"desire":{"갈망":15,"독점":-35,"위험":30,"과시":-20,"지속":-15,"지향":"양성","결합":"다자"},"fields":{"소속":"동방사","생업":"파견 인명 명부·호송 관리","품계":"병장","직함":"보호군 파견 호송책","가치관":"권위 60 | 개방 −35 | 무력 60 | 물질 25 | 공동 35 | 원칙 −20 | 공개 −30 | 자격 −20 | 분산 −55 | 변혁 −20","욕망":"갈망 15 | 독점 −35 | 위험 30 | 과시 −20 | 지속 −15 | 지향 양성 | 결합 다자"},"sections":{"관직":"품계 병장. 직함은 보호군 파견 호송책. 파견 명단은 상수행정 날인과 동방사 암호패가 함께 있어야 출발하고, 귀환 시각이 빈 칸은 고덕 유치선에서 되돌린다.\n\n일화. 류가온은 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다.","관계":"한보라의 순찰열차 배차에 호송 칸을 붙이고, 배우진의 파견안을 실행하되 기하겸의 교량 잠금 앞에서는 기록을 남기고 돌아선다.","야망":"보호군 파견을 기간 한정 호송으로만 남겨, 동부 장교가 뚝섬 펌프실에 눌러앉지 않게 한다.\n\n공포. 류가온은 호송 열차가 성동 교량에서 멈추고, 그 정차가 주둔의 기정사실이 되는 일을 두려워한다.","개입":"귀환 시각이 적힌 명단을 전달해 호송을 제한적으로 열거나, 주둔용 물자가 숨겨진 칸을 폭로해 호송책을 실격시킬 수 있다."},"biography":"류가온은 교량 위 민병 바리케이드를 구원 대상이 아니라 통과 거부로 읽고, 구두 주둔 허가를 명령으로 받지 않는다. 경로는 짧고 귀환 시각은 미리 적는다.\n\n- 소속: 동방사\n- 생업: 파견 인명 명부·호송 관리\n- 품계: 병장\n- 직함: 보호군 파견 호송책\n생애. 류가온은 3세대에 태어났다. 류가온은 신내 환승 당직에서 자랐다. 류가온의 보호군 파견 호송책 자리는 무표 출발 열차 저지로 열렸다.\n- 류가온은 고덕2동과 연결된 파견 업무에서 행정 날인·군사 암호패·귀환 시각을 조건으로 삼고 교량 통과가 거부되면 복귀한다. 주둔권은 없다.\n- 류가온은 성수1가2동과 연결된 업무에서 뚝섬 펌프실 파견안과 기하겸의 교량 통과 거부·복귀 관계를 대조한다. 파견 성사나 주둔을 뜻하지 않는다.\n\n**관직.** 품계 병장. 직함은 보호군 파견 호송책. 파견 명단은 상수행정 날인과 동방사 암호패가 함께 있어야 출발하고, 귀환 시각이 빈 칸은 고덕 유치선에서 되돌린다.\n\n일화. 류가온은 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다.\n\n**관계.** 한보라의 순찰열차 배차에 호송 칸을 붙이고, 배우진의 파견안을 실행하되 기하겸의 교량 잠금 앞에서는 기록을 남기고 돌아선다.\n\n**야망.** 보호군 파견을 기간 한정 호송으로만 남겨, 동부 장교가 뚝섬 펌프실에 눌러앉지 않게 한다.\n\n공포. 류가온은 호송 열차가 성동 교량에서 멈추고, 그 정차가 주둔의 기정사실이 되는 일을 두려워한다.\n\n**개입.** 귀환 시각이 적힌 명단을 전달해 호송을 제한적으로 열거나, 주둔용 물자가 숨겨진 칸을 폭로해 호송책을 실격시킬 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 −35 | 무력 60 | 물질 25 | 공동 35 | 원칙 −20 | 공개 −30 | 자격 −20 | 분산 −55 | 변혁 −20\n- 욕망: 갈망 15 | 독점 −35 | 위험 30 | 과시 −20 | 지속 −15 | 지향 양성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"류가온","type":"계약","to":"한보라","basis":"한보라의 순찰열차 배차에 호송 칸을 붙이고"},{"from":"류가온","type":"계약","to":"기하겸","basis":"배우진의 파견안을 실행하되 기하겸의 교량 잠금 앞에서는 기록을 남기고 돌아선다"}],"incoming":[{"from":"기하겸","type":"계약","to":"류가온","basis":"암사 호송책 류가온의 통과 요청을 기록만 남기고 되돌린다"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0142', 'c5c4-c601-c6d4', '{"id":"person-0142","name":"Eom Si-wan","title":"Eastern Charter Declaration Courier","position":"Eastern Charter Declaration Courier","rank":"Sergeant","commonTier":"T5","occupation":"Sealing and Delivering Charter Copies","gender":"Male","stage":"S3","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0142","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0142","name":"엄시완","title":"동부 헌장 선언 전령","position":"동부 헌장 선언 전령","rank":"병장","commonTier":"T5","occupation":"헌장 사본 봉함·전달","gender":"남성","stage":"S3","state":"S05","stateName":"동방사","detailRoute":"/people/person-0142","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0143', 'c5ec-c758-b839-4f59', '{"id":"person-0143","name":"Yeo Seo-ha","title":"Black Dispatch Slip Investigation Clerk","position":"Black Dispatch Slip Investigation Clerk","rank":"Sergeant","commonTier":"T5","occupation":"Dispatch Investigation Log and Testimony Recording","gender":"Male","stage":"S3","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0143","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0143","name":"여서하","title":"검은 배차표 조사 서기","position":"검은 배차표 조사 서기","rank":"병장","commonTier":"T5","occupation":"배차 조사 일지·증언 기록","gender":"남성","stage":"S3","state":"S05","stateName":"동방사","detailRoute":"/people/person-0143","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0144', 'b0a8-c758-b839', '{"id":"person-0144","name":"Nam Hwi-gang","title":"Floodgate Bridge Blockade Commander","position":"Floodgate Bridge Blockade Commander","characterId":"K143","rank":"Sergeant","commonTier":"T5","occupation":"Bridge Lever and Opening Countersignature Management","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#Person-Nam-Hwigang","detailRoute":"/people/person-0144","birthDate":"2082-07-09","birthday":"07-09","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K115","recipientName":"Bae Ujin","basis":"It overlaps with Bae Ujin''s guard network, but the bridge levers are held divided.","sourceRef":{"path":"lore/characters/Cast-State-05.json","anchor":"Person-Nam-Hwigang-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k143-bridge-countersign","name":"Bridge opening countersign checking","rating":60}],"traits":[{"id":"k143-choice","name":"Rejects unilateral opening","description":"He spoke briefly on the bridge and confirmed only whose hand lowered the blockade lever. He left sealing hours over praise.","behavior":"Anecdote. A runner from Bae Woojin''s escort net asks for the sluice bridge to be opened on a spoken order and a single written command. Nam Hwigang sends the command back and, keeping hold of the blockade lever until a second duty officer''s joint signature comes, writes down the seal time on the bridge.","stress":"Fear. That when the blockade keys gathered in one hand, the bridge would become the lesser states'' hostage. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Overlapping Bae Woojin''s escort network, but holding the bridge lever divided.","effects":[]},{"id":"k143-boundary","name":"Maintains work boundaries","description":"Office. Rank: sergeant. Title: water gate bridge blockade commander. He took opening requests only with two duty hands'' joint signature and sent back a single order sheet.","behavior":"Office. Rank: sergeant. Title: water gate bridge blockade commander. He took opening requests only with two duty hands'' joint signature and sent back a single order sheet.","stress":"Fear. That when the blockade keys gathered in one hand, the bridge would become the lesser states'' hostage. The actual response is not yet recorded.","relationship":"Relations. Overlapping Bae Woojin''s escort network, but holding the bridge lever divided.","effects":[]}],"narrative":"Anecdote. A runner from Bae Woojin''s escort net asks for the sluice bridge to be opened on a spoken order and a single written command. Nam Hwigang sends the command back and, keeping hold of the blockade lever until a second duty officer''s joint signature comes, writes down the seal time on the bridge. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-35,"Force":70,"Material":20,"Communal":30,"Principle":-30,"Public":-45,"Eligibility":-20,"Dispersed":-50,"Transformative":-35},"desire":{"Longing":45,"Monopoly":-30,"Risk":-25,"Display":10,"Sustained":15,"Orientation":"Same-Sex","Union":"None"},"fields":{"Affiliation":"Eastern Command","Livelihood":"Bridge Lever and Opening Countersignature Management","Rank":"Sergeant","Title":"Floodgate Bridge Blockade Commander","Values":"Authority 55 | Openness −35 | Force 70 | Material 20 | Communal 30 | Principle −30 | Publicity −45 | Qualification −20 | Decentralization −50 | Transformation −35","Desires":"Craving 45 | Monopoly −30 | Risk −25 | Display 10 | Persistence 15 | Orientation same-sex | Union none"},"sections":{"Offices":"Rank: Sergeant. Title: Floodgate Bridge Blockade Commander. Opening requests are accepted only with co-signatures from two duty officers; a single order sheet is sent back.","Anecdote":"A messenger from Bae Ujin''s escort network asks for the Sluice Bridge to be opened on a verbal instruction and a single order sheet alone. Nam Hwigang sends the order sheet back and, gripping the lockdown lever until the second duty officer''s countersignature arrives, records the sealing time on the bridge.","Relationships":"It overlaps with Bae Ujin''s guard network, but the bridge levers are held divided.","Ambition":"Enter the Sluice Bridge lockdown authority as a standalone entry in the bridge ledger, rather than leaving it to the verbal instruction of the Eastern Command commander.\n\nFear. Nam Hwigang fears that if the lockdown key gathers in a single hand, the bridge will become a hostage of the weaker states.","Intervention":"You can add your name to the lockdown countersignature, or hide an open walkway."},"biography":"Nam Hwigang speaks briefly on the bridge and only checks whose hand brings the lockdown lever down. He leaves a sealing time rather than praise.\n\n- Affiliation: Eastern Command\n- Occupation: Managing the bridge lever and opening countersignatures\n- Rank: Sergeant\n- Title: Sluice Bridge Lockdown Commander\nLife. Nam Hwigang was born in the third generation. Nam Hwigang grew up at the Amsa guard post. Nam Hwigang''s post as Sluice Bridge Lockdown Commander opened up after catching an unauthorized night crossing.\n- In work connected with Amsa 2-dong, Nam Hwigang checks the bridge lever and the countersignatures of two duty officers, and rejects any single-sheet order. The lockdown key cannot be gathered into one person''s hands by the commander''s verbal instruction alone.\n\n**Office.** Rank: Sergeant. Title: Sluice Bridge Lockdown Commander. He accepts an opening request only with the countersignatures of two duty officers, and sends back any single order sheet.\n\n**Anecdote.** A messenger from Bae Ujin''s escort network asks for the Sluice Bridge to be opened on a verbal instruction and a single order sheet alone. Nam Hwigang sends the order sheet back and, gripping the lockdown lever until the second duty officer''s countersignature arrives, records the sealing time on the bridge.\n\n**Relations.** He overlaps with Bae Ujin''s escort network, but the two share the bridge lever between them.\n\n**Ambition.** Enter the Sluice Bridge lockdown authority as a standalone entry in the bridge ledger, rather than leaving it to the verbal instruction of the Eastern Command commander.\n\nFear. Nam Hwigang fears that if the lockdown key gathers in a single hand, the bridge will become a hostage of the weaker states.\n\n**Intervention.** You can add your name to the lockdown countersignature, or hide an open walkway.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness −35 | Force 70 | Material 20 | Communal 30 | Principle −30 | Publicity −45 | Qualification −20 | Dispersion −50 | Transformation −35\n- Desires: Longing 45 | Monopoly −30 | Risk −25 | Display 10 | Persistence 15 | Orientation: same-sex | Union: none\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0144","name":"남휘강","title":"수문 교량 봉쇄 지휘관","position":"수문 교량 봉쇄 지휘관","characterId":"K143","rank":"병장","commonTier":"T5","occupation":"교량 레버·개방 연서 관리","gender":"여성","stage":"S2","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-05#인물-남휘강","detailRoute":"/people/person-0144","birthDate":"2082-07-09","birthday":"07-09","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K115","recipientName":"배우진","basis":"배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","sourceRef":{"path":"lore/characters/Cast-State-05.json","anchor":"인물-남휘강-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"k143-bridge-countersign","name":"교량 개방 연서 확인","rating":60}],"traits":[{"id":"k143-choice","name":"단독 개방 거부","description":"교량 위에서는 짧게 말하고, 봉쇄 레버를 누구 손으로 내리는지만 확인한다. 칭찬보다 봉인 시각을 남긴다.","behavior":"일화. 배우진의 호위망에서 온 전령이 구두 지시와 명령서 한 장만으로 수문 교량 개방을 청한다. 남휘강은 명령서를 돌려보내고, 두 번째 당직의 연서가 올 때까지 봉쇄 레버를 쥔 채 교량 위 봉인 시각을 적는다.","stress":"공포. 봉쇄 키가 한 손에 모이면 교량이 약소국 볼모가 되는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","effects":[]},{"id":"k143-boundary","name":"업무 경계를 지킴","description":"관직. 품계 병장. 직함은 수문 교량 봉쇄 지휘관. 개방 요청은 두 명의 당직 연서가 있어야 받고, 한 장의 명령서는 돌려보낸다.","behavior":"관직. 품계 병장. 직함은 수문 교량 봉쇄 지휘관. 개방 요청은 두 명의 당직 연서가 있어야 받고, 한 장의 명령서는 돌려보낸다.","stress":"공포. 봉쇄 키가 한 손에 모이면 교량이 약소국 볼모가 되는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","effects":[]}],"narrative":"일화. 배우진의 호위망에서 온 전령이 구두 지시와 명령서 한 장만으로 수문 교량 개방을 청한다. 남휘강은 명령서를 돌려보내고, 두 번째 당직의 연서가 올 때까지 봉쇄 레버를 쥔 채 교량 위 봉인 시각을 적는다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":-35,"무력":70,"물질":20,"공동":30,"원칙":-30,"공개":-45,"자격":-20,"분산":-50,"변혁":-35},"desire":{"갈망":45,"독점":-30,"위험":-25,"과시":10,"지속":15,"지향":"동성","결합":"없음"},"fields":{"소속":"동방사","생업":"교량 레버·개방 연서 관리","품계":"병장","직함":"수문 교량 봉쇄 지휘관","가치관":"권위 55 | 개방 −35 | 무력 70 | 물질 20 | 공동 30 | 원칙 −30 | 공개 −45 | 자격 −20 | 분산 −50 | 변혁 −35","욕망":"갈망 45 | 독점 −30 | 위험 −25 | 과시 10 | 지속 15 | 지향 동성 | 결합 없음"},"sections":{"관직":"품계 병장. 직함은 수문 교량 봉쇄 지휘관. 개방 요청은 두 명의 당직 연서가 있어야 받고, 한 장의 명령서는 돌려보낸다.","일화":"배우진의 호위망에서 온 전령이 구두 지시와 명령서 한 장만으로 수문 교량 개방을 청한다. 남휘강은 명령서를 돌려보내고, 두 번째 당직의 연서가 올 때까지 봉쇄 레버를 쥔 채 교량 위 봉인 시각을 적는다.","관계":"배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.","야망":"수문 교량 봉쇄권을 동방사 사령의 구두 지시가 아니라 교량 장부에 단독 항목으로 올린다.\n\n공포. 남휘강은 봉쇄 키가 한 손에 모이면 교량이 약소국 볼모가 되는 일을 두려워한다.","개입":"봉쇄 연서에 이름을 올리거나, 열린 보행로를 숨길 수 있다."},"biography":"남휘강은 교량 위에서는 짧게 말하고, 봉쇄 레버를 누구 손으로 내리는지만 확인한다. 칭찬보다 봉인 시각을 남긴다.\n\n- 소속: 동방사\n- 생업: 교량 레버·개방 연서 관리\n- 품계: 병장\n- 직함: 수문 교량 봉쇄 지휘관\n생애. 남휘강은 3세대에 태어났다. 남휘강은 암사 경비 초소에서 자랐다. 남휘강의 수문 교량 봉쇄 지휘관 자리는 야간 무단 도하 적발로 열렸다.\n- 남휘강은 암사2동과 연결된 업무에서 교량 레버와 두 당직자의 연서를 확인하고 한 장짜리 명령서는 반려한다. 사령의 구두 지시만으로 봉쇄 키를 한 사람에게 모을 수 없다.\n\n**관직.** 품계 병장. 직함은 수문 교량 봉쇄 지휘관. 개방 요청은 두 명의 당직 연서가 있어야 받고, 한 장의 명령서는 돌려보낸다.\n\n**일화.** 배우진의 호위망에서 온 전령이 구두 지시와 명령서 한 장만으로 수문 교량 개방을 청한다. 남휘강은 명령서를 돌려보내고, 두 번째 당직의 연서가 올 때까지 봉쇄 레버를 쥔 채 교량 위 봉인 시각을 적는다.\n\n**관계.** 배우진의 호위망과 겹치지만, 교량 레버는 나누어 쥔다.\n\n**야망.** 수문 교량 봉쇄권을 동방사 사령의 구두 지시가 아니라 교량 장부에 단독 항목으로 올린다.\n\n공포. 남휘강은 봉쇄 키가 한 손에 모이면 교량이 약소국 볼모가 되는 일을 두려워한다.\n\n**개입.** 봉쇄 연서에 이름을 올리거나, 열린 보행로를 숨길 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 −35 | 무력 70 | 물질 20 | 공동 30 | 원칙 −30 | 공개 −45 | 자격 −20 | 분산 −50 | 변혁 −35\n- 욕망: 갈망 45 | 독점 −30 | 위험 −25 | 과시 10 | 지속 15 | 지향 동성 | 결합 없음\n:::","relations":{"outgoing":[],"incoming":[]}}');
