INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0267', 'd3c9-cda9-c8fc', '{"id":"person-0267","name":"Pyeong Eun-u","title":"Corridor Headcount Witness","position":"Headcount Witness Acolyte","rank":"Postulant","commonTier":"T5","occupation":"Scouting Reports · Verifying Armed Passage Passes","gender":"Female","stage":"S3","state":"S10","stateName":"Anguk Order","detailRoute":"/people/person-0267","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0267","name":"평은우","title":"회랑 인원조사 증인","position":"인원조사 증인 행자","rank":"행자","commonTier":"T5","occupation":"정찰 보고·무장 통과 표 확인","gender":"여성","stage":"S3","state":"S10","stateName":"안국총림","detailRoute":"/people/person-0267","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0268', 'b2e8-c5f0-c548-6bb5', '{"id":"person-0268","name":"Dan Yu-jin","title":"Refugee Attendant at the Weak States Conference","position":"Consultation Attendant Acolyte","characterId":"K267","rank":"Postulant","commonTier":"T5","occupation":"Posting Consultation Drafts · Clan Vote Results","gender":"Male","stage":"S3","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#inmul-dan-yujin","detailRoute":"/people/person-0268","birthDate":"2087-07-31","birthday":"07-31","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"meeting-support","name":"Meeting draft and vote posting","rating":55}],"traits":[{"id":"meeting-support-disposition","name":"Leaves bribery notes visible","description":"Publishes bribery notes rather than erasing them.","behavior":"Publishes bribery notes rather than erasing them.","stress":"Fears meeting statements reduced to labor numbers.","relationship":"Supports Baek On at meetings, places citizenship text at Jeong Yura’s seat and coordinates Sodu’s family-message route.","effects":[]},{"id":"recorded-boundary","name":"Same votes in two places","description":"Posts vote results simultaneously at camp and meeting.","behavior":"Posts vote results simultaneously at camp and meeting.","stress":"Fears meeting statements reduced to labor numbers.","relationship":"Supports Baek On at meetings, places citizenship text at Jeong Yura’s seat and coordinates Sodu’s family-message route.","effects":[]}],"narrative":"Published a bribery note from the attendance bag and posted votes at camp and meeting together, then placed a citizenship draft at negotiations.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b2e8-c5f0-c548-6bb5","name":"Yeonan Dan Clan","crest":"clan-crests/b2e8-c5f0-c548-6bb5.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-65,"Openness":75,"Force":-35,"Material":-15,"Communal":80,"Principle":35,"Public":25,"Eligibility":35,"Dispersed":40,"Transformative":10},"desire":{"Longing":-5,"Monopoly":0,"Risk":10,"Display":10,"Sustained":20,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Livelihood":"Posting Consultation Drafts · Clan Vote Results","Affiliation":"The Government","Rank":"Postulant","Title":"Consultation Attendant Acolyte","Values":"Authority −65 | Openness 75 | Force −35 | Material −15 | Communal 80 | Principle 35 | Publicity 25 | Qualification 35 | Dispersal 40 | Transformation 10","Desires":"Craving −5 | Monopoly 0 | Risk 10 | Display 10 | Persistence 20 | Orientation same-sex | Bonding non-exclusive"},"sections":{"Life":"Born 2087-07-31; active at the 2126 opening. Grew up in the Jegi-dong infirmary. The duty log of the Negotiation Attendant Postulant holds an entry about a counterfeit-medicine sealing job.\n- Proposes Jongno 1·2·3·4-ga-dong as the reference point for Dan Yujin''s work of drafting negotiation texts and posting clan vote results. It does not confirm current duty assignment, residence, domain, or ownership.","Offices":"Rank: Postulant. Title: Negotiation Attendant Postulant. Posts the clan vote results at the encampment and the meeting hall at the same time on the same day, and leaves bribe notes on the bulletin board as they are.","Anecdote":"At a negotiation session, just before Baek On''s turn to speak, a single bribe note slips into the attendant''s bag. Dan Yujin pins the note to the bulletin board for all to see, posts the clan vote results at the encampment and the meeting hall at the same time, and then places a citizenship text on Jeong Yura''s joint-negotiation seat.","Relationships":"Supports Baek On''s meeting remarks through attendant duty, submits a citizenship text to Jeong Yura''s joint-negotiation seat, and keeps in line with Sodu''s family-council courier route.","Ambition":"In the negotiations, raises the follower roster as a clause of the joint negotiation so that partitioned subjugation cannot split the follower roster apart.","Fear":"That the attendant''s bag will be swapped for a copy of the military register, leaving meeting remarks only as labor-force numbers.","Intervention":"Can make the bribe note public, or escort a witness to the follower roster draft to the meeting hall."},"biography":"If an oral relief promise is not transcribed into the courier ledger, treats it as never made, and does not use symbols that reduce a child''s name to a number. Warm, but the meeting note is cold.\n\n- Occupation: Drafting negotiation texts and posting clan vote results\n- Affiliation: The Government\n- Rank: Postulant\n- Title: Negotiation Attendant Postulant\n**Life.** Born 2087-07-31; active at the 2126 opening. Grew up in the Jegi-dong infirmary. The duty log of the Negotiation Attendant Postulant holds an entry about a counterfeit-medicine sealing job.\n- Proposes Jongno 1·2·3·4-ga-dong as the reference point for Dan Yujin''s work of drafting negotiation texts and posting clan vote results. It does not confirm current duty assignment, residence, domain, or ownership.\n\n**Office.** Rank: Postulant. Title: Negotiation Attendant Postulant. Posts the clan vote results at the encampment and the meeting hall at the same time on the same day, and leaves bribe notes on the bulletin board as they are.\n\n**Anecdote.** At a negotiation session, just before Baek On''s turn to speak, a single bribe note slips into the attendant''s bag. Dan Yujin pins the note to the bulletin board for all to see, posts the clan vote results at the encampment and the meeting hall at the same time, and then places a citizenship text on Jeong Yura''s joint-negotiation seat.\n\n**Relationships.** Supports Baek On''s meeting remarks through attendant duty, submits a citizenship text to Jeong Yura''s joint-negotiation seat, and keeps in line with Sodu''s family-council courier route.\n\n**Ambition.** In the negotiations, raises the follower roster as a clause of the joint negotiation so that partitioned subjugation cannot split the follower roster apart.\n\n**Fear.** That the attendant''s bag will be swapped for a copy of the military register, leaving meeting remarks only as labor-force numbers.\n\n**Intervention.** Can make the bribe note public, or escort a witness to the follower roster draft to the meeting hall.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −65 | Openness 75 | Force −35 | Material −15 | Communal 80 | Principle 35 | Publicity 25 | Qualification 35 | Dispersal 40 | Transformation 10\n- Desires: Craving −5 | Monopoly 0 | Risk 10 | Display 10 | Persistence 20 | Orientation same-sex | Bonding non-exclusive\n:::","relations":{"outgoing":[{"from":"Dan Yu-jin","type":"Contract","to":"Baek On","basis":"backs up Baek On''s remarks at the council with action, and"},{"from":"Dan Yu-jin","type":"Contract","to":"Jeong Yura","basis":"by placing a citizenship text on Jeong Yura''s joint-negotiation seat"}],"incoming":[]}}', '{"id":"person-0268","name":"단유진","title":"약소국 회의 난민 수행원","position":"협의 수행 행자","characterId":"K267","rank":"행자","commonTier":"T5","occupation":"협의 문안·문중 표 결과 게시","gender":"남성","stage":"S3","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-단유진","detailRoute":"/people/person-0268","birthDate":"2087-07-31","birthday":"07-31","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"meeting-support","name":"회의 문안·표결 게시","rating":55}],"traits":[{"id":"meeting-support-disposition","name":"매수 쪽지를 남김","description":"매수 쪽지를 지우지 않고 공개 게시한다.","behavior":"매수 쪽지를 지우지 않고 공개 게시한다.","stress":"회의 발언이 노동력 숫자로 바뀔 것을 두려워한다.","relationship":"백온의 회의 발언을 수행으로 받치고, 정유라의 공동교섭 좌석에 시민권 문안을 올리며, 소두의 가족 회의 전령로와 줄을 맞춘다.","effects":[]},{"id":"recorded-boundary","name":"두 곳의 같은 표결","description":"숙영과 회의장에 표결 결과를 동시에 게시한다.","behavior":"숙영과 회의장에 표결 결과를 동시에 게시한다.","stress":"수행 가방이 군사호적 사본으로 바뀌어 회의 발언이 노동력 숫자로만 남는 것.","relationship":"백온의 회의 발언을 수행으로 받치고, 정유라의 공동교섭 좌석에 시민권 문안을 올리며, 소두의 가족 회의 전령로와 줄을 맞춘다.","effects":[]}],"narrative":"수행 가방의 매수 쪽지를 공개하고 표결을 숙영과 회의장에 동시에 붙였다. 시민권 문안을 협의 좌석에 올린 행동이 근거다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b2e8-c5f0-c548-6bb5","name":"연안 단씨","crest":"clan-crests/b2e8-c5f0-c548-6bb5.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-65,"개방":75,"무력":-35,"물질":-15,"공동":80,"원칙":35,"공개":25,"자격":35,"분산":40,"변혁":10},"desire":{"갈망":-5,"독점":0,"위험":10,"과시":10,"지속":20,"지향":"동성","결합":"비독점"},"fields":{"생업":"협의 문안·문중 표 결과 게시","소속":"정부","품계":"행자","직함":"협의 수행 행자","가치관":"권위 −65 | 개방 75 | 무력 −35 | 물질 −15 | 공동 80 | 원칙 35 | 공개 25 | 자격 35 | 분산 40 | 변혁 10","욕망":"갈망 −5 | 독점 0 | 위험 10 | 과시 10 | 지속 20 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2087-07-31 출생, 2126년 개막에 활동했다. 제기동 의무소에서 자랐다. 협의 수행 행자 당직 기록에는 가짜 약 봉인으 일이 남아 있다.\n- 단유진의 협의 문안·문중 표 결과 게시 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 행자. 직함은 협의 수행 행자. 문중 표 결과를 당일 숙영과 회의장에 동시에 붙이고, 매수 쪽지는 게시판에 그대로 남긴다.","일화":"협의 자리에서 백온의 발언 차례 직전에 매수 쪽지 한 장이 수행 가방에 들어온다. 단유진은 쪽지를 게시판에 붙여 공개하고, 문중 표 결과를 숙영과 회의장에 동시에 게시한 뒤 정유라의 공동교섭 좌석에 시민권 문안을 올린다.","관계":"백온의 회의 발언을 수행으로 받치고, 정유라의 공동교섭 좌석에 시민권 문안을 올리며, 소두의 가족 회의 전령로와 줄을 맞춘다.","야망":"협의에서 신도 명부를 공동교섭의 조항으로 올려 분할 복속이 신도 명부를 갈라놓지 못하게 한다.","공포":"수행 가방이 군사호적 사본으로 바뀌어 회의 발언이 노동력 숫자로만 남는 것.","개입":"매수 쪽지를 공개하거나, 신도 명부 초안 증인을 회의장까지 호송할 수 있다."},"biography":"구두 구호 약속을 전령 원장에 옮기지 않으면 없던 일로 돌리고, 아이 이름을 숫자로 줄이는 기호를 쓰지 않는다. 따뜻하나 회의 쪽지는 차갑다.\n\n- 생업: 협의 문안·문중 표 결과 게시\n- 소속: 정부\n- 품계: 행자\n- 직함: 협의 수행 행자\n**생애.** 2087-07-31 출생, 2126년 개막에 활동했다. 제기동 의무소에서 자랐다. 협의 수행 행자 당직 기록에는 가짜 약 봉인으 일이 남아 있다.\n- 단유진의 협의 문안·문중 표 결과 게시 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 행자. 직함은 협의 수행 행자. 문중 표 결과를 당일 숙영과 회의장에 동시에 붙이고, 매수 쪽지는 게시판에 그대로 남긴다.\n\n**일화.** 협의 자리에서 백온의 발언 차례 직전에 매수 쪽지 한 장이 수행 가방에 들어온다. 단유진은 쪽지를 게시판에 붙여 공개하고, 문중 표 결과를 숙영과 회의장에 동시에 게시한 뒤 정유라의 공동교섭 좌석에 시민권 문안을 올린다.\n\n**관계.** 백온의 회의 발언을 수행으로 받치고, 정유라의 공동교섭 좌석에 시민권 문안을 올리며, 소두의 가족 회의 전령로와 줄을 맞춘다.\n\n**야망.** 협의에서 신도 명부를 공동교섭의 조항으로 올려 분할 복속이 신도 명부를 갈라놓지 못하게 한다.\n\n**공포.** 수행 가방이 군사호적 사본으로 바뀌어 회의 발언이 노동력 숫자로만 남는 것.\n\n**개입.** 매수 쪽지를 공개하거나, 신도 명부 초안 증인을 회의장까지 호송할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −65 | 개방 75 | 무력 −35 | 물질 −15 | 공동 80 | 원칙 35 | 공개 25 | 자격 35 | 분산 40 | 변혁 10\n- 욕망: 갈망 −5 | 독점 0 | 위험 10 | 과시 10 | 지속 20 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"단유진","type":"계약","to":"백온","basis":"백온의 회의 발언을 수행으로 뒷받침하고"},{"from":"단유진","type":"계약","to":"정유라","basis":"정유라의 공동교섭 좌석에 시민권 문안을 올리며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0269', 'c21c-d64d-c0b0', '{"id":"person-0269","name":"Sun Ji-min","title":"Deserter from the Forced Registration Column","position":"Forced Registration Deserter Acolyte","characterId":"K268","rank":"Postulant","commonTier":"T5","occupation":"Forced Registration Desertion Records · Shift Separation Testimony","gender":"Female","stage":"S3","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#inmul-sun-jimin","detailRoute":"/people/person-0269","birthDate":"2074-05-13","birthday":"05-13","age":52,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"detour-return","name":"Mountain detour return","rating":45}],"traits":[{"id":"detour-return-disposition","name":"Family boundary within loyalty","description":"Falls silent over survival but leaves the line before family-separation tags.","behavior":"Falls silent over survival but leaves the line before family-separation tags.","stress":"Fears departure labeled rebellion and triggering camp searches.","relationship":"Conflicts with O Hangyeol’s oath without opening the store, returns through Bokmo’s detour and explains departure to Baek On’s family meeting.","effects":[]},{"id":"recorded-boundary","name":"Leaves the side door closed","description":"Left despite oath conflict but did not open the store side door.","behavior":"Left despite oath conflict but did not open the store side door.","stress":"Fears departure labeled rebellion and triggering camp searches.","relationship":"Conflicts with O Hangyeol’s oath without opening the store, returns through Bokmo’s detour and explains departure to Baek On’s family meeting.","effects":[]}],"narrative":"Left the forced-registration line and returned by mountain paths without opening the store side door. Departure does not imply combat victory or new powers.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c21c-d64d-c0b0","name":"Hongsan Sun Clan","crest":"clan-crests/c21c-d64d-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-45,"Openness":40,"Force":-50,"Material":-20,"Communal":60,"Principle":35,"Public":35,"Eligibility":35,"Dispersed":50,"Transformative":5},"desire":{"Longing":30,"Monopoly":5,"Risk":10,"Display":10,"Sustained":30,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Forced Registration Desertion Records · Shift Separation Testimony","Affiliation":"The Government","Rank":"Postulant","Title":"Forced Registration Deserter Acolyte","Values":"Authority −45 | Openness 40 | Force −50 | Material −20 | Communal 60 | Principle 35 | Publicity 35 | Qualification 35 | Dispersal 50 | Transformation 5","Desires":"Longing 30 | Exclusivity 5 | Risk 10 | Display 10 | Persistence 30 | Orientation Fluid | Union Contract Cohabitation"},"sections":{"Life":"Born 2074-05-13, active at the 2126 opening. Raised on waiting-hall duty. The duty record of the Forced-Registration Defector Postulant notes taking a substitute duty after an unauthorized absence from shift.\n- Pyeongchang-dong is proposed as the work reference point for Sun Jimin''s forced-registration defection records and shift-separation testimony. It does not confirm a current posting, residence, fief, or ownership.\n- Jongno 1·2·3·4-ga-dong is proposed as the work reference point for Sun Jimin''s forced-registration defection records and shift-separation testimony. It does not confirm a current posting, residence, fief, or ownership.","Offices":"Rank: Postulant. Title: Forced-Registration Defector Postulant. Writes the time of defection and the names of the remaining devotees on the same slip, and testifies that armed duty and ration duty must not be held by the same person.","Anecdote":"During the autumn procession at Bukhansan Bogungmun, when Amsa tied water-supply rights to service re-registration, Sun Jimin slipped out of the forced-registration line and turned back to the mountain path.","Relationships":"Though clashing with O Hangyeol''s militia oath, did not open the storehouse side door, bypasses the encampment by Bokmo''s detour route, and offers Baek On the reasons for the defection at the family council.","Ambition":"Leave the route out of the forced-registration procession on record as a rescue case, so that the Grand Monastery does not become a mercenary force.","Fear":"The fear that the defection will be recorded only as a mutiny, and the remaining camp will face a retaliatory search.","Intervention":"Can hide defectors to open a rescue case, or lay out the roster of the retaliatory search before the Mountain Assembly."},"biography":"When oath and survival collide, falls silent for a long time and then steps one pace out of the procession. Before an iron tally that is loyal yet splits families, breaks the silence.\n\n- Occupation: Forced-registration defection records and shift-separation testimony\n- Affiliation: The Government\n- Rank: Postulant\n- Title: Forced-Registration Defector Postulant\n**Life.** Born 2074-05-13, active at the 2126 opening. Raised on waiting-hall duty. The duty record of the Forced-Registration Defector Postulant notes taking a substitute duty after an unauthorized absence from shift.\n- Pyeongchang-dong is proposed as the work reference point for Sun Jimin''s forced-registration defection records and shift-separation testimony. It does not confirm a current posting, residence, fief, or ownership.\n- Jongno 1·2·3·4-ga-dong is proposed as the work reference point for Sun Jimin''s forced-registration defection records and shift-separation testimony. It does not confirm a current posting, residence, fief, or ownership.\n\n**Office.** Rank: Postulant. Title: Forced-Registration Defector Postulant. Writes the time of defection and the names of the remaining devotees on the same slip, and testifies that armed duty and ration duty must not be held by the same person.\n\n**Anecdote.** During the autumn procession at Bukhansan Bogungmun, when Amsa tied water-supply rights to service re-registration, Sun Jimin slipped out of the forced-registration line and turned back to the mountain path.\n\n**Relationships.** Though in conflict with O Hangyeol''s militia oath, did not open the warehouse side door; detours around the camp by way of Bokmo''s bypass; and offers Baek On the reason for the defection at a family council.\n\n**Ambition.** Leave the route out of the forced-registration procession on record as a rescue case, so that the Grand Monastery does not become a mercenary force.\n\n**Fear.** That the defection will be recorded only as a mutiny, and the remaining camp will face a retaliatory search.\n\n**Intervention.** Can hide defectors to open a rescue case, or lay out the roster of the retaliatory search before the Mountain Assembly.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −45 | Openness 40 | Force −50 | Material −20 | Communal 60 | Principle 35 | Publicity 35 | Qualification 35 | Dispersal 50 | Transformation 5\n- Desires: Longing 30 | Exclusivity 5 | Risk 10 | Display 10 | Persistence 30 | Orientation Fluid | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Sun Ji-min","type":"Contract","to":"O Han-gyeol","basis":"Clashing with Oh Hangyeol''s militia oath, yet leaving the storehouse side door unopened, and"},{"from":"Sun Ji-min","type":"Contract","to":"Bok Mo","basis":"Detouring around the encampment by Bokmo''s detour"}],"incoming":[]}}', '{"id":"person-0269","name":"순지민","title":"강제등록 행렬 이탈자","position":"강제등록 이탈 행자","characterId":"K268","rank":"행자","commonTier":"T5","occupation":"강제등록 이탈 기록·교대 분리 증언","gender":"여성","stage":"S3","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-순지민","detailRoute":"/people/person-0269","birthDate":"2074-05-13","birthday":"05-13","age":52,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"detour-return","name":"산길 우회 귀환","rating":45}],"traits":[{"id":"detour-return-disposition","name":"서약보다 가족의 선","description":"생존 갈등에 침묵하다 가족 분리 철표 앞에서 행렬을 벗어난다.","behavior":"생존 갈등에 침묵하다 가족 분리 철표 앞에서 행렬을 벗어난다.","stress":"이탈이 반란으로 기록돼 숙영이 수색될 것을 두려워한다.","relationship":"오한결의 민병 서약과 충돌하면서도 창고 옆문은 열지 않았고, 복모의 우회로로 숙영을 우회하며, 백온에게 이탈의 이유를 가족 회의에서 바친다.","effects":[]},{"id":"recorded-boundary","name":"옆문을 열지 않음","description":"서약과 충돌해 이탈했지만 창고 옆문은 열지 않았다.","behavior":"서약과 충돌해 이탈했지만 창고 옆문은 열지 않았다.","stress":"이탈이 반란으로만 기록되어 남은 숙영이 보복 수색을 받는 것.","relationship":"오한결의 민병 서약과 충돌하면서도 창고 옆문은 열지 않았고, 복모의 우회로로 숙영을 우회하며, 백온에게 이탈의 이유를 가족 회의에서 바친다.","effects":[]}],"narrative":"강제등록 줄에서 빠져 산길로 돌아갔으며 창고 옆문은 열지 않았다. 이탈은 호송 전투 승리나 새 권한을 뜻하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c21c-d64d-c0b0","name":"홍산 순씨","crest":"clan-crests/c21c-d64d-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-45,"개방":40,"무력":-50,"물질":-20,"공동":60,"원칙":35,"공개":35,"자격":35,"분산":50,"변혁":5},"desire":{"갈망":30,"독점":5,"위험":10,"과시":10,"지속":30,"지향":"유동","결합":"계약동거"},"fields":{"생업":"강제등록 이탈 기록·교대 분리 증언","소속":"정부","품계":"행자","직함":"강제등록 이탈 행자","가치관":"권위 −45 | 개방 40 | 무력 −50 | 물질 −20 | 공동 60 | 원칙 35 | 공개 35 | 자격 35 | 분산 50 | 변혁 5","욕망":"갈망 30 | 독점 5 | 위험 10 | 과시 10 | 지속 30 | 지향 유동 | 결합 계약동거"},"sections":{"생애":"2074-05-13 출생, 2126년 개막에 활동했다. 대합실 당직에서 자랐다. 강제등록 이탈 행자 당직 기록에는 교대 무단 결근 뒤 대체 당직을 맡은 일이 남아 있다.\n- 순지민의 강제등록 이탈 기록·교대 분리 증언 업무 기준점으로 평창동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n- 순지민의 강제등록 이탈 기록·교대 분리 증언 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 행자. 직함은 강제등록 이탈 행자. 이탈 시각과 남은 신도 이름을 같은 쪽지에 적고, 무장 근무와 배급 근무를 같은 사람이 겸하지 못하게 증언한다.","일화":"가을의 북한산보국문 행렬에서 암사가 급수권과 복무 재등록을 묶자 순지민은 강제등록 줄에서 빠져나와 산길로 되돌아갔다.","관계":"오한결의 민병 서약과 충돌하면서도 창고 옆문은 열지 않았고, 복모의 우회로로 숙영을 우회하며, 백온에게 이탈의 이유를 가족 회의에서 바친다.","야망":"강제등록 행렬에서 빠져나온 경로를 구출 사건으로 남겨 총림이 용병이 되지 않게 한다.","공포":"이탈이 반란으로만 기록되어 남은 숙영이 보복 수색을 받는 것.","개입":"이탈자를 숨겨 구출 사건을 열거나, 보복 수색의 명단을 산중총회에 펼칠 수 있다."},"biography":"맹세와 생존이 충돌하면 오래 침묵한 뒤 행렬에서 한 걸음 빠진다. 충성스러우나 가족을 갈라놓는 철표 앞에서는 침묵을 깬다.\n\n- 생업: 강제등록 이탈 기록·교대 분리 증언\n- 소속: 정부\n- 품계: 행자\n- 직함: 강제등록 이탈 행자\n**생애.** 2074-05-13 출생, 2126년 개막에 활동했다. 대합실 당직에서 자랐다. 강제등록 이탈 행자 당직 기록에는 교대 무단 결근 뒤 대체 당직을 맡은 일이 남아 있다.\n- 순지민의 강제등록 이탈 기록·교대 분리 증언 업무 기준점으로 평창동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n- 순지민의 강제등록 이탈 기록·교대 분리 증언 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 행자. 직함은 강제등록 이탈 행자. 이탈 시각과 남은 신도 이름을 같은 쪽지에 적고, 무장 근무와 배급 근무를 같은 사람이 겸하지 못하게 증언한다.\n\n**일화.** 가을의 북한산보국문 행렬에서 암사가 급수권과 복무 재등록을 묶자 순지민은 강제등록 줄에서 빠져나와 산길로 되돌아갔다.\n\n**관계.** 오한결의 민병 서약과 충돌하면서도 창고 옆문은 열지 않았고, 복모의 우회로로 숙영을 우회하며, 백온에게 이탈의 이유를 가족 회의에서 바친다.\n\n**야망.** 강제등록 행렬에서 빠져나온 경로를 구출 사건으로 남겨 총림이 용병이 되지 않게 한다.\n\n**공포.** 이탈이 반란으로만 기록되어 남은 숙영이 보복 수색을 받는 것.\n\n**개입.** 이탈자를 숨겨 구출 사건을 열거나, 보복 수색의 명단을 산중총회에 펼칠 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −45 | 개방 40 | 무력 −50 | 물질 −20 | 공동 60 | 원칙 35 | 공개 35 | 자격 35 | 분산 50 | 변혁 5\n- 욕망: 갈망 30 | 독점 5 | 위험 10 | 과시 10 | 지속 30 | 지향 유동 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"순지민","type":"계약","to":"오한결","basis":"오한결의 민병 서약과 충돌하면서도 창고 옆문은 열지 않았고"},{"from":"순지민","type":"계약","to":"복모","basis":"복모의 우회로로 숙영을 우회하며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0270', 'd64d-b0a8-c591', '{"id":"person-0270","name":"Hong Eun-seo","title":"Party to Meritorious Subject Reward Relief","position":"Relief Share Acolyte","characterId":"K269","rank":"Postulant","commonTier":"T5","occupation":"Cross-Checking Relief Ration Tickets · Reward Copies","gender":"Male","stage":"S3","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#inmul-hong-eunseo","detailRoute":"/people/person-0270","birthDate":"2070-09-17","birthday":"09-17","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"relief-comparison","name":"Relief and reward-copy comparison","rating":55}],"traits":[{"id":"relief-comparison-disposition","name":"Preserves relief names","description":"Dims light after children sleep and records overlapping names separately.","behavior":"Dims light after children sleep and records overlapping names separately.","stress":"Fears names becoming collateral for offices.","relationship":"Compares relief with Ran Jiho’s missing registry entries and applies Hwang Serin’s ration sheet under Baek On’s pledge.","effects":[]},{"id":"recorded-boundary","name":"Rejects absent-person votes","description":"Blocks added community votes without personal attendance.","behavior":"Blocks added community votes without personal attendance.","stress":"Fears names becoming collateral for offices.","relationship":"Compares relief with Ran Jiho’s missing registry entries and applies Hwang Serin’s ration sheet under Baek On’s pledge.","effects":[]}],"narrative":"Compared relief copies transferred into office-reward columns line by line against rations. Recording names supports comparison; restored relief remains an ambition.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d64d-b0a8-c591","name":"Namyang Hong Clan","crest":"clan-crests/d64d-b0a8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-55,"Openness":50,"Force":-45,"Material":-20,"Communal":50,"Principle":35,"Public":35,"Eligibility":35,"Dispersed":55,"Transformative":0},"desire":{"Longing":25,"Monopoly":0,"Risk":25,"Display":5,"Sustained":30,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Livelihood":"Cross-Checking Relief Ration Tickets · Reward Copies","Affiliation":"The Government","Rank":"Postulant","Title":"Relief Share Acolyte","Values":"Authority −55 | Openness 50 | Force −45 | Material −20 | Communal 50 | Principle 35 | Publicity 35 | Qualification 35 | Dispersal 55 | Transformation 0","Desires":"Longing 25 | Exclusivity 0 | Risk 25 | Display 5 | Persistence 30 | Orientation Bisexual | Union Non-exclusive"},"sections":{"Life":"Born 2070-09-17, active at the 2126 opening. Raised on waiting-hall duty. The duty record of the Relief Share Postulant notes taking a substitute duty after an unauthorized absence from shift.\n- Jongno 1·2·3·4-ga-dong is proposed as the work reference point for Hong Eunseo''s reconciliation of relief ration tickets and compensation copies. It does not confirm a current posting, residence, fief, or ownership.","Offices":"Rank: Postulant. Title: Relief Share Postulant. Reconciles the compensation copies against the actual ration tickets every evening, and prevents additional clan tickets from being written without the person''s own attendance.","Anecdote":"On a night when the heating fails, a copy arrives at the camp in which the relief shares have been rewritten into the rank-and-title column. After the children fall asleep, Hong Eunseo dims the light and matches that copy line by line against Hwang Serin''s public ration tickets, and separately writes down the names that overlap with the blank entries in the Seoul Station register that Ran Jiho pointed out.","Relationships":"Examines the blank entries in Ran Jiho''s Seoul Station register together with the relief column of their own, enforces Hwang Serin''s public ration tickets at the camp, and places Baek On''s refuge oath on the first line of the relief ledger.","Ambition":"Recover the relief shares cut by meritorious-service rewards through the Grand Monastery''s public rations, so that founding rewards do not flow only to particular warehouses.","Fear":"The fear that on a night when the heating fails, the camp will turn into a barracks for duty monks and the names of relief recipients will become collateral for rank and title.","Intervention":"Can escort the relief that will fill the blank entries, or strike from the ledger the names written as collateral for rank and title."},"biography":"Cannot forget the winter just after the founding when relief boxes were being turned into rank-and-title columns, and refuses any word telling them to fill empty places with arbitrary names. After the children fall asleep, the first thing they do is dim the light.\n\n- Occupation: Reconciling relief ration tickets and compensation copies\n- Affiliation: The Government\n- Rank: Postulant\n- Title: Relief Share Postulant\n**Life.** Born 2070-09-17, active at the 2126 opening. Raised on waiting-hall duty. The duty record of the Relief Share Postulant notes taking a substitute duty after an unauthorized absence from shift.\n- Jongno 1·2·3·4-ga-dong is proposed as the work reference point for Hong Eunseo''s reconciliation of relief ration tickets and compensation copies. It does not confirm a current posting, residence, fief, or ownership.\n\n**Office.** Rank: Postulant. Title: Relief Share Postulant. Reconciles the compensation copies against the actual ration tickets every evening, and prevents additional clan tickets from being written without the person''s own attendance.\n\n**Anecdote.** On a night when the heating fails, a copy arrives at the camp in which the relief shares have been rewritten into the rank-and-title column. After the children fall asleep, Hong Eunseo dims the light and matches that copy line by line against Hwang Serin''s public ration tickets, and separately writes down the names that overlap with the blank entries in the Seoul Station register that Ran Jiho pointed out.\n\n**Relationships.** Examines the blank entries in Ran Jiho''s Seoul Station register together with the relief column of their own, enforces Hwang Serin''s public ration tickets at the camp, and places Baek On''s refuge oath on the first line of the relief ledger.\n\n**Ambition.** Recover the relief shares cut by meritorious-service rewards through the Grand Monastery''s public rations, so that founding rewards do not flow only to particular warehouses.\n\n**Fear.** That on a night when the heating fails, the camp will turn into a barracks for duty monks and the names of relief recipients will become collateral for rank and title.\n\n**Intervention.** Can escort the relief that will fill the blank entries, or strike from the ledger the names written as collateral for rank and title.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −55 | Openness 50 | Force −45 | Material −20 | Communal 50 | Principle 35 | Publicity 35 | Qualification 35 | Dispersal 55 | Transformation 0\n- Desires: Longing 25 | Exclusivity 0 | Risk 25 | Display 5 | Persistence 30 | Orientation Bisexual | Union Non-exclusive\n:::","relations":{"outgoing":[{"from":"Hong Eun-seo","type":"Contract","to":"Hwang Serin","basis":"Enforcing Hwang Serin''s public ration table at the encampment, and"}],"incoming":[]}}', '{"id":"person-0270","name":"홍은서","title":"공신 보상 구호 당사자","position":"구호 몫 행자","characterId":"K269","rank":"행자","commonTier":"T5","occupation":"구호 배급표·보상 사본 대조","gender":"남성","stage":"S3","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-홍은서","detailRoute":"/people/person-0270","birthDate":"2070-09-17","birthday":"09-17","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"relief-comparison","name":"구호·보상 사본 대조","rating":55}],"traits":[{"id":"relief-comparison-disposition","name":"구호 이름 보존","description":"아이들이 잠든 뒤 불빛을 줄이고 겹치는 이름을 따로 적는다.","behavior":"아이들이 잠든 뒤 불빛을 줄이고 겹치는 이름을 따로 적는다.","stress":"이름이 관작 담보로 바뀔 것을 두려워한다.","relationship":"란지호의 서울역 명부 빈 칸과 자신의 구호 칸을 함께 살피고, 황세린의 공개 배급표를 숙영에서 집행하며, 백온의 피난처 맹세를 구호 원장의 첫 줄에 둔다.","effects":[]},{"id":"recorded-boundary","name":"본인 없는 표 거부","description":"본인 출석 없이 문중 추가 표를 적지 못하게 한다.","behavior":"본인 출석 없이 문중 추가 표를 적지 못하게 한다.","stress":"난방이 떨어진 밤에 숙영이 당직 승려의 병영으로 바뀌고 구호 당사자 이름이 관작 담보가 되는 것.","relationship":"란지호의 서울역 명부 빈 칸과 자신의 구호 칸을 함께 살피고, 황세린의 공개 배급표를 숙영에서 집행하며, 백온의 피난처 맹세를 구호 원장의 첫 줄에 둔다.","effects":[]}],"narrative":"관작 칸으로 옮겨진 구호 사본을 실제 배급표와 한 줄씩 맞췄다. 이름을 따로 적는 대조가 강점이며 구호 회복은 아직 야망이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d64d-b0a8-c591","name":"남양 홍씨","crest":"clan-crests/d64d-b0a8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-55,"개방":50,"무력":-45,"물질":-20,"공동":50,"원칙":35,"공개":35,"자격":35,"분산":55,"변혁":0},"desire":{"갈망":25,"독점":0,"위험":25,"과시":5,"지속":30,"지향":"양성","결합":"비독점"},"fields":{"생업":"구호 배급표·보상 사본 대조","소속":"정부","품계":"행자","직함":"구호 몫 행자","가치관":"권위 −55 | 개방 50 | 무력 −45 | 물질 −20 | 공동 50 | 원칙 35 | 공개 35 | 자격 35 | 분산 55 | 변혁 0","욕망":"갈망 25 | 독점 0 | 위험 25 | 과시 5 | 지속 30 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2070-09-17 출생, 2126년 개막에 활동했다. 대합실 당직에서 자랐다. 구호 몫 행자 당직 기록에는 교대 무단 결근 뒤 대체 당직을 맡은 일이 남아 있다.\n- 홍은서의 구호 배급표·보상 사본 대조 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 행자. 직함은 구호 몫 행자. 보상 사본과 실제 배급표를 저녁마다 대조하고, 문중 추가 표는 본인 출석 없이 적지 못하게 막는다.","일화":"난방이 떨어진 밤, 구호 몫이 관작 칸으로 옮겨 적힌 사본이 숙영에 도착한다. 홍은서는 아이들이 잠든 뒤 불빛을 줄이고 그 사본을 황세린의 공개 배급표와 한 줄씩 맞대며, 란지호가 짚은 서울역 명부의 빈 칸과 겹치는 이름을 따로 적는다.","관계":"란지호의 서울역 명부 빈 칸과 자신의 구호 칸을 함께 살피고, 황세린의 공개 배급표를 숙영에서 집행하며, 백온의 피난처 맹세를 구호 원장의 첫 줄에 둔다.","야망":"공신 보상에 깎인 구호 몫을 총림 공개 배급으로 되찾아 창건 보상이 특정 창고로만 흐르지 않게 한다.","공포":"난방이 떨어진 밤에 숙영이 당직 승려의 병영으로 바뀌고 구호 당사자 이름이 관작 담보가 되는 것.","개입":"빈 칸을 채울 구호를 호송하거나, 관작 담보로 적힌 이름을 원장에서 지울 수 있다."},"biography":"창건 직후 구호 상자가 관작 칸으로 바뀌던 겨울을 잊지 못하고, 빈 자리를 임의의 이름으로 메우라는 말을 거부한다. 아이들이 잠든 뒤에는 불빛부터 줄인다.\n\n- 생업: 구호 배급표·보상 사본 대조\n- 소속: 정부\n- 품계: 행자\n- 직함: 구호 몫 행자\n**생애.** 2070-09-17 출생, 2126년 개막에 활동했다. 대합실 당직에서 자랐다. 구호 몫 행자 당직 기록에는 교대 무단 결근 뒤 대체 당직을 맡은 일이 남아 있다.\n- 홍은서의 구호 배급표·보상 사본 대조 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 행자. 직함은 구호 몫 행자. 보상 사본과 실제 배급표를 저녁마다 대조하고, 문중 추가 표는 본인 출석 없이 적지 못하게 막는다.\n\n**일화.** 난방이 떨어진 밤, 구호 몫이 관작 칸으로 옮겨 적힌 사본이 숙영에 도착한다. 홍은서는 아이들이 잠든 뒤 불빛을 줄이고 그 사본을 황세린의 공개 배급표와 한 줄씩 맞대며, 란지호가 짚은 서울역 명부의 빈 칸과 겹치는 이름을 따로 적는다.\n\n**관계.** 란지호의 서울역 명부 빈 칸과 자신의 구호 칸을 함께 살피고, 황세린의 공개 배급표를 숙영에서 집행하며, 백온의 피난처 맹세를 구호 원장의 첫 줄에 둔다.\n\n**야망.** 공신 보상에 깎인 구호 몫을 총림 공개 배급으로 되찾아 창건 보상이 특정 창고로만 흐르지 않게 한다.\n\n**공포.** 난방이 떨어진 밤에 숙영이 당직 승려의 병영으로 바뀌고 구호 당사자 이름이 관작 담보가 되는 것.\n\n**개입.** 빈 칸을 채울 구호를 호송하거나, 관작 담보로 적힌 이름을 원장에서 지울 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −55 | 개방 50 | 무력 −45 | 물질 −20 | 공동 50 | 원칙 35 | 공개 35 | 자격 35 | 분산 55 | 변혁 0\n- 욕망: 갈망 25 | 독점 0 | 위험 25 | 과시 5 | 지속 30 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"홍은서","type":"계약","to":"황세린","basis":"황세린의 공개 배급표를 숙영에서 집행하며"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0271', 'c724-d30c-d3c9', '{"id":"person-0271","name":"Yun San-ho","title":"Evacuation Route Guide Squad Leader","position":"Evacuation Route Guide Abbot","characterId":"K270","rank":"Head Monk","commonTier":"T3","occupation":"Evacuation Route Markers · Guiding the Deed Queue","gender":"Female","stage":"S2","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#inmul-yun-sanho","detailRoute":"/people/person-0271","birthDate":"2064-12-13","birthday":"12-13","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K245","recipientName":"Baek On","basis":"Meshes with Baek On''s refugee-representative register, but the milestone key is held by the squad leader.","sourceRef":{"path":"lore/characters/Cast-State-10.json","anchor":"inmul-yun-sanho-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"refuge-guidance","name":"Refuge-sign and queue guidance","rating":50}],"traits":[{"id":"refuge-guidance-disposition","name":"Records beside erased text","description":"Does not invent erased text and posts a supplemental note beside it.","behavior":"Does not invent erased text and posts a supplemental note beside it.","stress":"Fears guidance gaps becoming a quarantine hostage line.","relationship":"Checks against Baek On’s refugee roster while the sign keys remain with the team lead.","effects":[]},{"id":"recorded-boundary","name":"Boundary of assessment","description":"Refers forgery suspicion only to scripture-copy duty.","behavior":"Refers forgery suspicion only to scripture-copy duty.","stress":"Fears guidance gaps becoming a quarantine hostage line.","relationship":"Checks against Baek On’s refugee roster while the sign keys remain with the team lead.","effects":[]}],"narrative":"Checked an erased sign with a flashlight and posted a note beside it. Routes those without certificates to the queue and refers forgery concerns to copy duty.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-65,"Openness":75,"Force":-40,"Material":-25,"Communal":80,"Principle":20,"Public":40,"Eligibility":30,"Dispersed":55,"Transformative":0},"desire":{"Longing":20,"Monopoly":-15,"Risk":-20,"Display":20,"Sustained":15,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Livelihood":"Evacuation Route Markers · Guiding the Deed Queue","Affiliation":"The Government","Rank":"Head Monk","Title":"Evacuation Route Guide Abbot","Values":"Authority −65 | Openness 75 | Force −40 | Material −25 | Community 80 | Principle 20 | Disclosure 40 | Qualification 30 | Dispersion 55 | Change 0","Desires":"Craving 20 | Monopoly −15 | Risk −20 | Display 20 | Persistence 15 | Orientation: fluid | Bonding: monogamous"},"sections":{"Life":"Born 2064-12-13, active at the 2126 opening. Grew up in the Bogungmun evacuation barracks. The Evacuation Route Guide Abbot duty records still include an entry about drawing up an orphan register.\n- Proposes Pyeongchang-dong as the reference point for Yun Sanho''s work guiding the evacuation-route signposts and certificate waiting queue. Does not confirm a current posting, residence, fief, or ownership.\n- Proposes Jongno 1·2·3·4-ga-dong as the reference point for Yun Sanho''s work guiding the evacuation-route signposts and certificate waiting queue. Does not confirm a current posting, residence, fief, or ownership.","Offices":"Rank: Abbot. Title: Evacuation Route Guide Abbot. Parties without a lineage certificate are sent to the waiting queue, and forgery suspicions are passed only to the Scripture Transcription duty.","Anecdote":"On the night the lettering on one evacuation-route signpost is erased, parties without lineage certificates gather at that chokepoint. Yun Sanho checks the signpost with a flashlight, sticks a note beside the erased letters, sends the party to the waiting queue, and then passes the forgery suspicion to the Scripture Transcription duty.","Relationships":"Meshes with Baek On''s refugee-representative register, but the milestone key is held by the squad leader.","Ambition":"Opens evacuation-route guidance in line with the believer reunion register and the Seoul-internal guidance timetable.","Fear":"The fear that when a gap in guidance opens, the corridor will become a line of quarantine hostages.","Intervention":"Can explain the reason for the sealed southern road, or testify to a register rejoining."},"biography":"Checks the evacuation-route signposts with a flashlight and, instead of rewriting erased letters, attaches a note beside them. Makes no grand promises.\n\n- Livelihood: Guiding the evacuation-route signposts and certificate waiting queue\n- Affiliation: The Government\n- Rank: Abbot\n- Title: Evacuation Route Guide Abbot\n**Life.** Born 2064-12-13, active at the 2126 opening. Grew up in the Bogungmun evacuation barracks. The Evacuation Route Guide Abbot duty records still include an entry about drawing up an orphan register.\n- Proposes Pyeongchang-dong as the reference point for Yun Sanho''s work guiding the evacuation-route signposts and certificate waiting queue. Does not confirm a current posting, residence, fief, or ownership.\n- Proposes Jongno 1·2·3·4-ga-dong as the reference point for Yun Sanho''s work guiding the evacuation-route signposts and certificate waiting queue. Does not confirm a current posting, residence, fief, or ownership.\n\n**Office.** Rank: Abbot. Title: Evacuation Route Guide Abbot. Parties without a lineage certificate are sent to the waiting queue, and forgery suspicions are passed only to the Scripture Transcription duty.\n\n**Anecdote.** On the night the lettering on one evacuation-route signpost is erased, parties without lineage certificates gather at that chokepoint. Yun Sanho checks the signpost with a flashlight, sticks a note beside the erased letters, sends the party to the waiting queue, and then passes the forgery suspicion to the Scripture Transcription duty.\n\n**Relations.** Interlocks with Baek On''s refugee representative register, but the foreman holds the signpost key.\n\n**Ambition.** Opens evacuation-route guidance in line with the believer reunion register and the Seoul-internal guidance timetable.\n\n**Fear.** That a gap in guidance will turn the corridor into a line of quarantine hostages.\n\n**Intervention.** Can explain the reason for the sealed southern road, or testify to a register rejoining.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −65 | Openness 75 | Force −40 | Material −25 | Community 80 | Principle 20 | Disclosure 40 | Qualification 30 | Dispersion 55 | Change 0\n- Desires: Craving 20 | Monopoly −15 | Risk −20 | Display 20 | Persistence 15 | Orientation: fluid | Bonding: monogamous\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0271","name":"윤산호","title":"피난로 안내 반장","position":"피난로 안내 주지","characterId":"K270","rank":"주지","commonTier":"T3","occupation":"피난로 이정표·증서 대기열 안내","gender":"여성","stage":"S2","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-윤산호","detailRoute":"/people/person-0271","birthDate":"2064-12-13","birthday":"12-13","age":62,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[{"recipientId":"K245","recipientName":"백온","basis":"백온의 난민대표 명부와 맞물리되, 이정표 열쇠는 반장이 쥔다.","sourceRef":{"path":"lore/characters/Cast-State-10.json","anchor":"인물-윤산호-p5"}}],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"refuge-guidance","name":"피난 표지·대기열 안내","rating":50}],"traits":[{"id":"refuge-guidance-disposition","name":"지운 글자 옆 기록","description":"원래 글자를 임의로 새로 쓰지 않고 옆에 보완 쪽지를 붙인다.","behavior":"원래 글자를 임의로 새로 쓰지 않고 옆에 보완 쪽지를 붙인다.","stress":"안내 공백이 검역 볼모의 줄이 될 것을 두려워한다.","relationship":"백온의 난민대표 명부와 맞물리되, 이정표 열쇠는 반장이 쥔다.","effects":[]},{"id":"recorded-boundary","name":"판단 권한의 경계","description":"위조 의심은 장경 필사 당직에만 넘긴다.","behavior":"위조 의심은 장경 필사 당직에만 넘긴다.","stress":"안내 공백이 생기면 회랑이 검역 볼모의 줄이 되는 것.","relationship":"백온의 난민대표 명부와 맞물리되, 이정표 열쇠는 반장이 쥔다.","effects":[]}],"narrative":"지워진 표지를 손전등으로 확인하고 옆에 쪽지를 붙였다. 증서 없는 일행은 대기열로 보내며 위조 판단은 필사 당직에 넘긴다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c724-d30c-d3c9","name":"파평 윤씨","crest":"clan-crests/c724-d30c-d3c9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-65,"개방":75,"무력":-40,"물질":-25,"공동":80,"원칙":20,"공개":40,"자격":30,"분산":55,"변혁":0},"desire":{"갈망":20,"독점":-15,"위험":-20,"과시":20,"지속":15,"지향":"유동","결합":"단혼"},"fields":{"생업":"피난로 이정표·증서 대기열 안내","소속":"정부","품계":"주지","직함":"피난로 안내 주지","가치관":"권위 −65 | 개방 75 | 무력 −40 | 물질 −25 | 공동 80 | 원칙 20 | 공개 40 | 자격 30 | 분산 55 | 변혁 0","욕망":"갈망 20 | 독점 −15 | 위험 −20 | 과시 20 | 지속 15 | 지향 유동 | 결합 단혼"},"sections":{"생애":"2064-12-13 출생, 2126년 개막에 활동했다. 보국문 피난 막사에서 자랐다. 피난로 안내 주지 당직 기록에는 고아 명부 줄 일이 남아 있다.\n- 윤산호의 피난로 이정표·증서 대기열 안내 업무 기준점으로 평창동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n- 윤산호의 피난로 이정표·증서 대기열 안내 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 주지. 직함은 피난로 안내 주지. 혈연 증서가 없는 일행은 대기열로 보내고, 위조 의심은 장경 필사 당직에만 넘긴다.","일화":"피난로 이정표 하나의 글자가 지워진 밤, 혈연 증서 없는 일행이 그 길목에 모인다. 윤산호는 손전등으로 이정표를 확인해 지워진 글자 옆에 쪽지를 붙이고, 일행을 대기열로 보낸 뒤 위조 의심 건은 장경 필사 당직에 넘긴다.","관계":"백온의 난민대표 명부와 맞물리되, 이정표 열쇠는 반장이 쥔다.","야망":"피난로 안내를 신도 재결합 명부와 서울 내부 안내 시각표에 맞춰 연다.","공포":"안내 공백이 생기면 회랑이 검역 볼모의 줄이 되는 것.","개입":"봉한 남쪽 길의 이유를 열거나, 명부 합류를 증언할 수 있다."},"biography":"피난로 이정표를 손전등으로 확인하고, 지워진 글자는 새로 쓰지 않고 옆에 붙인다. 큰 약속은 하지 않는다.\n\n- 생업: 피난로 이정표·증서 대기열 안내\n- 소속: 정부\n- 품계: 주지\n- 직함: 피난로 안내 주지\n**생애.** 2064-12-13 출생, 2126년 개막에 활동했다. 보국문 피난 막사에서 자랐다. 피난로 안내 주지 당직 기록에는 고아 명부 줄 일이 남아 있다.\n- 윤산호의 피난로 이정표·증서 대기열 안내 업무 기준점으로 평창동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n- 윤산호의 피난로 이정표·증서 대기열 안내 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 주지. 직함은 피난로 안내 주지. 혈연 증서가 없는 일행은 대기열로 보내고, 위조 의심은 장경 필사 당직에만 넘긴다.\n\n**일화.** 피난로 이정표 하나의 글자가 지워진 밤, 혈연 증서 없는 일행이 그 길목에 모인다. 윤산호는 손전등으로 이정표를 확인해 지워진 글자 옆에 쪽지를 붙이고, 일행을 대기열로 보낸 뒤 위조 의심 건은 장경 필사 당직에 넘긴다.\n\n**관계.** 백온의 난민대표 명부와 맞물리되, 이정표 열쇠는 반장이 쥔다.\n\n**야망.** 피난로 안내를 신도 재결합 명부와 서울 내부 안내 시각표에 맞춰 연다.\n\n**공포.** 안내 공백이 생기면 회랑이 검역 볼모의 줄이 되는 것.\n\n**개입.** 봉한 남쪽 길의 이유를 열거나, 명부 합류를 증언할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −65 | 개방 75 | 무력 −40 | 물질 −25 | 공동 80 | 원칙 20 | 공개 40 | 자격 30 | 분산 55 | 변혁 0\n- 욕망: 갈망 20 | 독점 −15 | 위험 −20 | 과시 20 | 지속 15 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0272', 'c774-acbd-c8fc-674e', '{"id":"person-0272","name":"Yi Hong-won","title":"Chairman","position":"Chairman of Seongha Group, Hereditary Position of the Yi Family","characterId":"K271","rank":"Chairman","commonTier":"T1","occupation":"Seongha Electronics Elder","gender":"Male","stage":"Key","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Yi-Hongwon","detailRoute":"/people/person-0272","birthDate":"2067-05-03","birthday":"05-03","age":59,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":11,"effective":11},"martial":{"base":11,"effective":11},"stewardship":{"base":14,"effective":14},"intrigue":{"base":12,"effective":12},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k271-succession-records","name":"Succession-record separation","rating":65}],"traits":[{"id":"k271-trait-1","name":"Votes apart from seniority","description":"Keeps different succession grounds out of one box.","behavior":"Keeps different succession grounds out of one box.","stress":"Moves votes out even on the eve of the succession test.","relationship":"Lends Bae Woojin the gate without merging gate custody with escort command.","effects":[]}],"narrative":"Before the succession test, he moved community votes outside the test venue to keep them apart from seniority records. He preserved gates and duties, but separating the procedures does not establish abolished heredity or fully fair succession.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:capital-s11","name":{"ko":"Gangnam Station Directly Held Land"},"holderPersonId":"K271","directLiegePersonId":null,"stateId":"S11","stationRef":{"stationId":"Gangnam","stationName":"Gangnam"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"c774-acbd-c8fc-674e","name":"Gyeongju I Clan","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"Authority":10,"Openness":-20,"Force":-10,"Material":30,"Communal":20,"Principle":10,"Public":-10,"Eligibility":80,"Dispersed":10,"Transformative":-30},"desire":{"Longing":0,"Monopoly":20,"Risk":-20,"Display":-30,"Sustained":60,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Livelihood":"Seongha Electronics Elder","Affiliation":"Seongha Group","Rank":"Chairman","Title":"Chairman of Seongha Group, Hereditary Position of the Yi Family"},"sections":{"Life":"Gangnam Station, Seongha Electronics computer room. The test wheelset of Sinjeong Wheelway belongs to Yu Sejin. Yi Hongwon became chairman after keeping the Gangnam Station barrier gate and the Gangnam Station duty box unbroken. The capital of Seongha Group is Gangnam Station, and the chairmanship is hereditary in the Yi clan. When a succession exam is held, the Gangnam Station company quarters cast ballots. It sponsors the Seongjeon General Assembly as the state faith. Seongha Electronics'' parts, labor, and records links are connected through Seoul-internal contract and duty work between the Seocho 4-dong headquarters and the Yeoksam 1-dong work district. Bae Ujin''s escort borrows this barrier gate, but the gate belongs to Yi Hongwon.","Offices":"Rank: Chairman. Title: Chairman of Seongha Group, hereditary in the Yi clan. Livelihood alias: Seongha Electronics elder.","Anecdote":"On the eve of the succession exam, Yi Hongwon sent the Gangnam Station company quarters'' ballots out of the exam hall. The ballots did not mix with the seniority box.","Houses":"The Yi clan. Steward. The steward of Sinjeong Wheelway (HC02) is Yu Sejin.","Relationships":"Bak Taegyeom and wheelsets. Gang Minseo and standards. Bae Ujin and the barrier gate.\n\n- Livelihood: Seongha Electronics elder\n- Affiliation: Seongha Group\n- Rank: Chairman\n- Title: Chairman of Seongha Group, hereditary in the Yi clan\n- Yi Hongwon handles Seongha Electronics elder duties in Seocho 4-dong. Connects the Gangnam Station headquarters, the chairman''s office bulletin board, and the waiting hall''s handover, access, and duty for daily-life freight as dong-level work reference points. The North Gate is an access duty for Gangnam Station and does not create northern-region domination or a new fortress\n\nThe maintenance apprentices beside Yi Hongwon, the Seongha Electronics elder, and the Seongha Electronics work foremen."},"biography":"**Life.** Gangnam Station, Seongha Electronics computer room. The test wheelset of Sinjeong Wheelway belongs to Yu Sejin. Yi Hongwon became chairman after keeping the Gangnam Station barrier gate and the Gangnam Station duty box unbroken. The capital of Seongha Group is Gangnam Station, and the chairmanship is hereditary in the Yi clan. When a succession exam is held, the Gangnam Station company quarters cast ballots. It sponsors the Seongjeon General Assembly as the state faith. Seongha Electronics'' parts, labor, and records links are connected through Seoul-internal contract and duty work between the Seocho 4-dong headquarters and the Yeoksam 1-dong work district. Bae Ujin''s escort borrows this barrier gate, but the gate belongs to Yi Hongwon.\n**Office.** Rank: Chairman. Title: Chairman of Seongha Group, hereditary in the Yi clan. Livelihood alias: Seongha Electronics elder.\n**Anecdote.** On the eve of the succession exam, Yi Hongwon sent the Gangnam Station company quarters'' ballots out of the exam hall. The ballots did not mix with the seniority box.\n**Family.** The Yi clan. Steward. The steward of Sinjeong Wheelway (HC02) is Yu Sejin.\n**Relations.** Bak Taegyeom and wheelsets. Gang Minseo and standards. Bae Ujin and the barrier gate.\n\n- Livelihood: Seongha Electronics elder\n- Affiliation: Seongha Group\n- Rank: Chairman\n- Title: Chairman of Seongha Group, hereditary in the Yi clan\n- Yi Hongwon handles Seongha Electronics elder duties in Seocho 4-dong. Connects the Gangnam Station headquarters, the chairman''s office bulletin board, and the waiting hall''s handover, access, and duty for daily-life freight as dong-level work reference points. The North Gate is an access duty for Gangnam Station and does not create northern-region domination or a new fortress\n\nThe maintenance apprentices beside Yi Hongwon, the Seongha Electronics elder, and the Seongha Electronics work foremen.","relations":{"outgoing":[],"incoming":[{"from":"Song Ha-yul","type":"Master and Disciple","to":"Yi Hong-won","basis":"Trains under the chairman as a vehicle maintenance apprentice"},{"from":"Jo U-chan","type":"Command","to":"Yi Hong-won","basis":"Divides wheelset processes under the chairman''s command"},{"from":"Seo Jin-a","type":"Rivalry","to":"Yi Hong-won","basis":"Contests mixed residential-and-technical governance"},{"from":"Hwang No-eul","type":"Command","to":"Yi Hong-won","basis":"Reports steel stock to the chairman"},{"from":"An Dohan","type":"Contract","to":"Yi Hong-won","basis":"Depends on northern wheelset exchange times"},{"from":"Eom Nuri","type":"Contract","to":"Yi Hong-won","basis":"seeks to protect Yi Hongwon''s public technical trial"},{"from":"Dan Geonu","type":"Contract","to":"Yi Hong-won","basis":"Cites Yi Hongwon''s technical exam schedule as grounds for declining the meeting,"}]}}', '{"id":"person-0272","name":"이홍원","title":"회장","position":"성하그룹 회장, 이씨 가문 세습","characterId":"K271","rank":"회장","commonTier":"T1","occupation":"성하전자 원로","gender":"남성","stage":"주요","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-이홍원","detailRoute":"/people/person-0272","birthDate":"2067-05-03","birthday":"05-03","age":59,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":11,"effective":11},"martial":{"base":11,"effective":11},"stewardship":{"base":14,"effective":14},"intrigue":{"base":12,"effective":12},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k271-succession-records","name":"승계 자료 분리","rating":65}],"traits":[{"id":"k271-trait-1","name":"표와 연공을 따로","description":"서로 다른 승계 근거를 한 함에 섞지 않는다.","behavior":"서로 다른 승계 근거를 한 함에 섞지 않는다.","stress":"승계 시험 전날에도 표를 시험장 밖으로 옮긴다.","relationship":"배우진에게 문을 빌려 주되 문 관리와 호위 지휘를 나눈다.","effects":[]}],"narrative":"승계 시험 전날 공동체의 표를 시험장 밖으로 내보내 연공 함과 섞이지 않게 했다. 차단문과 당직을 지켜 왔지만 그 절차 분리가 세습 폐지나 공정한 승계의 완성을 뜻하지는 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:capital-s11","name":{"ko":"강남역 직영지"},"holderPersonId":"K271","directLiegePersonId":null,"stateId":"S11","stationRef":{"stationId":"강남","stationName":"강남"},"adminRefs":[],"geometrySource":null,"territorialScale":null,"formalTitleRank":null}],"clan":{"id":"c774-acbd-c8fc-674e","name":"경주 이씨","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":true,"values":{"권위":10,"개방":-20,"무력":-10,"물질":30,"공동":20,"원칙":10,"공개":-10,"자격":80,"분산":10,"변혁":-30},"desire":{"갈망":0,"독점":20,"위험":-20,"과시":-30,"지속":60,"지향":"이성","결합":"단혼"},"fields":{"생업":"성하전자 원로","소속":"성하그룹","품계":"회장","직함":"성하그룹 회장, 이씨 가문 세습"},"sections":{"생애":"강남역 성하전자 전산실. 신정차륜가의 시험 차륜은 유세진의 것이다. 이홍원이 회장이 된 것은 강남역 차단문과 강남역 당직함을 끊기지 않게 지킨 뒤였다. 성하그룹의 수도는 강남역이고 회장직은 이씨 가문이 세습한다. 승계 시험이 열리면 강남역 사택이 표를 던진다. 성전총회를 국가 신앙으로 후원한다. 성하전자의 부품·노동·기록 연결은 서초4동 본사와 역삼1동 작업 생활권의 서울 내부 계약·당직 업무로 잇는다. 배우진의 호위는 이 차단문을 빌리지만 차단문은 이홍원의 것이다.","관직":"품계 회장. 직함은 성하그룹 회장, 이씨 가문 세습. 생업 별명은 성하전자 원로.","일화":"승계 시험 전날, 이홍원은 강남역 사택의 표를 시험장 밖으로 내보냈다. 표가 연공 함과 섞이지 않았다.","가문":"이씨 가문. 관리인. 신정차륜가(HC02) 관리인은 유세진이다.","관계":"박태겸과 차륜. 강민서와 규격. 배우진과 차단문.\n\n- 생업: 성하전자 원로\n- 소속: 성하그룹\n- 품계: 회장\n- 직함: 성하그룹 회장, 이씨 가문 세습\n- 이홍원은 서초4동에서 성하전자 원로 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다\n\n성하전자 원로 이홍원 곁의 정비 도제와 성하전자 작업 반장들이다."},"biography":"**생애.** 강남역 성하전자 전산실. 신정차륜가의 시험 차륜은 유세진의 것이다. 이홍원이 회장이 된 것은 강남역 차단문과 강남역 당직함을 끊기지 않게 지킨 뒤였다. 성하그룹의 수도는 강남역이고 회장직은 이씨 가문이 세습한다. 승계 시험이 열리면 강남역 사택이 표를 던진다. 성전총회를 국가 신앙으로 후원한다. 성하전자의 부품·노동·기록 연결은 서초4동 본사와 역삼1동 작업 생활권의 서울 내부 계약·당직 업무로 잇는다. 배우진의 호위는 이 차단문을 빌리지만 차단문은 이홍원의 것이다.\n**관직.** 품계 회장. 직함은 성하그룹 회장, 이씨 가문 세습. 생업 별명은 성하전자 원로.\n**일화.** 승계 시험 전날, 이홍원은 강남역 사택의 표를 시험장 밖으로 내보냈다. 표가 연공 함과 섞이지 않았다.\n**가문.** 이씨 가문. 관리인. 신정차륜가(HC02) 관리인은 유세진이다.\n**관계.** 박태겸과 차륜. 강민서와 규격. 배우진과 차단문.\n\n- 생업: 성하전자 원로\n- 소속: 성하그룹\n- 품계: 회장\n- 직함: 성하그룹 회장, 이씨 가문 세습\n- 이홍원은 서초4동에서 성하전자 원로 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다\n\n성하전자 원로 이홍원 곁의 정비 도제와 성하전자 작업 반장들이다.","relations":{"outgoing":[],"incoming":[{"from":"송하율","type":"신도","to":"이홍원","basis":"차량 정비 도제로 회장 밑에서 수련"},{"from":"조우찬","type":"지휘","to":"이홍원","basis":"차륜 공정을 회장 지휘로 나눔"},{"from":"서진아","type":"경쟁","to":"이홍원","basis":"주거·기술 혼합 통치를 다툼"},{"from":"황노을","type":"지휘","to":"이홍원","basis":"철재 재고를 회장에게 보고"},{"from":"안도한","type":"계약","to":"이홍원","basis":"북부 차륜 교환 시각을 의존"},{"from":"엄누리","type":"계약","to":"이홍원","basis":"이홍원의 공개 기술시험을 지키려 하며"},{"from":"단건우","type":"계약","to":"이홍원","basis":"이홍원의 기술시험 일정을 회의 사절의 근거로 들고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0273', 'c1a1-d64d-c8fc-5b8b', '{"id":"person-0273","name":"Song Ha-yul","title":"Vehicle Maintenance Apprentice","position":"Seongha Electronics Vehicle Maintenance Apprentice","characterId":"K272","rank":"Employee","commonTier":"T5","occupation":"Managing Vehicle Maintenance Logs · Defective Parts Samples","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Song-Hayul","detailRoute":"/people/person-0273","birthDate":"2068-01-01","birthday":"01-01","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k272-defect-sample-preservation","name":"Defect sample preservation","rating":50}],"traits":[{"id":"k272-priority","name":"Tool accountability","description":"Song Hayul preserves defective samples and posts logs directly. His ambition to enter through public trials is documented, not command success.","behavior":"Office. Rank: assistant manager. Title: vehicle maintenance apprentice. He pasted the maintenance logs directly on the Elder''s board, not the squad leader''s, and cut defective parts out as specimens.","stress":"Fear. That a hidden defect in a trial wheel would remain under his signature and become the pretext for handing the base to the residents'' representatives.","relationship":"Relations. I Hongwon''s apprentice, he shared brake parts with Hwang Jiho through the apprentice exchange with Park Taegyeom. Matched the north gate torch signals with Kang Taesan.","effects":[]},{"id":"k272-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: assistant manager. Title: vehicle maintenance apprentice. He pasted the maintenance logs directly on the Elder''s board, not the squad leader''s, and cut defective parts out as specimens.","stress":"Fear. That a hidden defect in a trial wheel would remain under his signature and become the pretext for handing the base to the residents'' representatives.","relationship":"Relations. I Hongwon''s apprentice, he shared brake parts with Hwang Jiho through the apprentice exchange with Park Taegyeom. Matched the north gate torch signals with Kang Taesan.","effects":[]}],"narrative":"Song Hayul preserves defective samples and posts logs directly. His ambition to enter through public trials is documented, not command success.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-d64d-c8fc-5b8b","name":"Song Clan of Hongju","crest":"clan-crests/c1a1-d64d-c8fc-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":-20,"Force":-15,"Material":30,"Communal":25,"Principle":5,"Public":5,"Eligibility":90,"Dispersed":5,"Transformative":-30},"desire":{"Longing":0,"Monopoly":-25,"Risk":10,"Display":20,"Sustained":30,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Livelihood":"Managing Vehicle Maintenance Logs · Defective Parts Samples","Affiliation":"Arc","Rank":"Employee","Title":"Seongha Electronics Vehicle Maintenance Apprentice","Values":"Authority 0 | Openness −20 | Force −15 | Materialism 30 | Community 25 | Principle 5 | Publicity 5 | Qualification 90 | Dispersion 5 | Transformation −30","Desires":"Craving 0 | Possessiveness −25 | Risk 10 | Display 20 | Endurance 30 | Orientation: Opposite-sex | Union: Polyamorous"},"sections":{"Life":"Grew up at the Gangnam Station rail depot. The Seongha Electronics vehicle maintenance apprentice post opened up because of a defect report filed just before a derailment.\n- Song Hayul handles vehicle maintenance logs and defective-part sample management in Seocho 4-dong. Song links the Gangnam Station headquarters/Chairman''s Office board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Song is I Hongwon''s apprentice and shares braking parts with Hwang Jiho through an apprentice exchange with Bak Taegyeom. Song coordinates North Gate torch signals with Gang Taesan","Offices":"Rank: Staff Member. Title: Seongha Electronics Vehicle Maintenance Apprentice. Posts maintenance logs directly on the Chairman''s Office board rather than going through the Seongha Electronics work foreman, and cuts up defective parts to keep as samples.","Anecdote":"A deliberately shaved bearing turned up in a leading heir''s test wheel.","Relationships":"Apprentice of Yi Hongwon; through apprentice exchange with Bak Taegyeom, shares brake parts with Hwang Jiho. Coordinates North Gate torch signals with Gang Taesan.","Ambition":"Through the public succession exam, aims to become the next elder candidate and prove with their own hands the path of I Hongwon, who would break the I clan''s succession.","Fear":"That a defect hidden in the test wheelset will remain under their own signature and become the pretext for handing the depot to the company quarters'' representative.","Intervention":"Can serve as exam supervisor, or trace the source tool of the defective part."},"biography":"Quick with the hands and sparing with words. Does not boast about exam scores but cannot tolerate someone siphoning off another person''s tools.\n\n- Livelihood: Vehicle maintenance logs and defective-part sample management\n- Affiliation: Arc\n- Rank: Staff Member\n- Title: Seongha Electronics Vehicle Maintenance Apprentice\n**Life.** Grew up at the Gangnam Station rail depot. The Seongha Electronics vehicle maintenance apprentice post opened up because of a defect report filed just before a derailment.\n- Song Hayul handles vehicle maintenance logs and defective-part sample management in Seocho 4-dong. Song links the Gangnam Station headquarters/Chairman''s Office board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Song is I Hongwon''s apprentice and shares braking parts with Hwang Jiho through an apprentice exchange with Bak Taegyeom. Song coordinates North Gate torch signals with Gang Taesan\n\n**Office.** Rank: Staff Member. Title: Seongha Electronics Vehicle Maintenance Apprentice. Posts maintenance logs directly on the Chairman''s Office board rather than going through the Seongha Electronics work foreman, and cuts up defective parts to keep as samples.\n\n**Anecdote.** A deliberately shaved bearing turned up in a leading heir''s test wheel.\n\n**Relations.** Is I Hongwon''s apprentice and shares braking parts with Hwang Jiho through an apprentice exchange with Bak Taegyeom. Coordinates North Gate torch signals with Gang Taesan.\n\n**Ambition.** Through the public succession exam, aims to become the next elder candidate and prove with their own hands the path of I Hongwon, who would break the I clan''s succession.\n\n**Fear.** That a defect hidden in the test wheel will remain under their own signature and become the pretext for handing the depot over to a housing-compound representative.\n\n**Intervention.** Can serve as exam supervisor, or trace the source tool of the defective part.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 0 | Openness −20 | Force −15 | Materialism 30 | Community 25 | Principle 5 | Publicity 5 | Qualification 90 | Dispersion 5 | Transformation −30\n- Desires: Craving 0 | Possessiveness −25 | Risk 10 | Display 20 | Endurance 30 | Orientation: Opposite-sex | Union: Polyamorous\n:::","relations":{"outgoing":[{"from":"Song Ha-yul","type":"Master and Disciple","to":"Yi Hong-won","basis":"Trains under the chairman as a vehicle maintenance apprentice"},{"from":"Song Ha-yul","type":"Contract","to":"Isaac Walker","basis":"Sharing brake parts with the Yongsan apprentices"}],"incoming":[{"from":"Dumo","type":"Master and Disciple","to":"Song Ha-yul","basis":"Receives Song Hayul''s apprentice daily work on site"},{"from":"Chu Jihun","type":"Oath","to":"Song Ha-yul","basis":"Receives Song Hayul''s apprentice daily work as grounds for exposure"}]}}', '{"id":"person-0273","name":"송하율","title":"차량 정비 도제","position":"성하전자 차량 정비 도제","characterId":"K272","rank":"사원","commonTier":"T5","occupation":"차량 정비 일지·불량 부품 표본 관리","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-송하율","detailRoute":"/people/person-0273","birthDate":"2068-01-01","birthday":"01-01","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k272-defect-sample-preservation","name":"불량 표본 보존","rating":50}],"traits":[{"id":"k272-priority","name":"공구에 대한 책임","description":"송하율은 불량을 표본으로 남기고 일지를 직접 게시한다. 공개 시험 진입의 야망은 확인되지만 지휘 성과는 없다.","behavior":"정비 일지를 성하전자 작업 반장이 아닌 회장실 게시판에 직접 붙이고, 불량 부품은 잘라 표본으로 남긴다.","stress":"시험 차륜에 숨은 결함이 자기 서명으로 남아 사택 대표에게 기지를 내주는 명분이 되는 것.","relationship":"이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다.","effects":[]},{"id":"k272-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 사원. 직함은 성하전자 차량 정비 도제. 정비 일지를 성하전자 작업 반장이 아닌 회장실 게시판에 직접 붙이고, 불량 부품은 잘라 표본으로 남긴다.","stress":"공포. 시험 차륜에 숨은 결함이 자기 서명으로 남아 사택 대표에게 기지를 내주는 명분이 되는 것.","relationship":"관계. 이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다.","effects":[]}],"narrative":"송하율은 불량을 표본으로 남기고 일지를 직접 게시한다. 공개 시험 진입의 야망은 확인되지만 지휘 성과는 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-d64d-c8fc-5b8b","name":"홍주 송씨","crest":"clan-crests/c1a1-d64d-c8fc-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":-20,"무력":-15,"물질":30,"공동":25,"원칙":5,"공개":5,"자격":90,"분산":5,"변혁":-30},"desire":{"갈망":0,"독점":-25,"위험":10,"과시":20,"지속":30,"지향":"이성","결합":"다자"},"fields":{"생업":"차량 정비 일지·불량 부품 표본 관리","소속":"Arc","품계":"사원","직함":"성하전자 차량 정비 도제","가치관":"권위 0 | 개방 −20 | 무력 −15 | 물질 30 | 공동 25 | 원칙 5 | 공개 5 | 자격 90 | 분산 5 | 변혁 −30","욕망":"갈망 0 | 독점 −25 | 위험 10 | 과시 20 | 지속 30 | 지향 이성 | 결합 다자"},"sections":{"생애":"강남역 차량기지에서 자랐다. 성하전자 차량 정비 도제 자리는 탈선 직전 결함 보고로 열렸다.\n- 송하율은 서초4동에서 차량 정비 일지·불량 부품 표본 관리 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다","관직":"품계 사원. 직함은 성하전자 차량 정비 도제. 정비 일지를 성하전자 작업 반장이 아닌 회장실 게시판에 직접 붙이고, 불량 부품은 잘라 표본으로 남긴다.","일화":"유력 후계자의 시험 차륜에서 의도적으로 깎인 베어링이 나왔다.","관계":"이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다.","야망":"공개 승계 시험으로 다음 원로 후보에 올라 이씨 가문 승계를 끊는 이홍원의 길을 자기 손으로 증명한다.","공포":"시험 차륜에 숨은 결함이 자기 서명으로 남아 사택 대표에게 기지를 내주는 명분이 되는 것.","개입":"시험 감독을 맡거나, 결함 부품의 출처 공구를 추적할 수 있다."},"biography":"손이 빠르고 말이 적다. 시험 점수를 자랑하지 않지만 남의 공구를 빼돌리는 일은 참지 못한다.\n\n- 생업: 차량 정비 일지·불량 부품 표본 관리\n- 소속: Arc\n- 품계: 사원\n- 직함: 성하전자 차량 정비 도제\n**생애.** 강남역 차량기지에서 자랐다. 성하전자 차량 정비 도제 자리는 탈선 직전 결함 보고로 열렸다.\n- 송하율은 서초4동에서 차량 정비 일지·불량 부품 표본 관리 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다\n\n**관직.** 품계 사원. 직함은 성하전자 차량 정비 도제. 정비 일지를 성하전자 작업 반장이 아닌 회장실 게시판에 직접 붙이고, 불량 부품은 잘라 표본으로 남긴다.\n\n**일화.** 유력 후계자의 시험 차륜에서 의도적으로 깎인 베어링이 나왔다.\n\n**관계.** 이홍원의 도제이며 박태겸과의 도제 교환으로 황지호와 제동 부품을 나눈다. 강태산과 북문 횃불 신호를 맞춘다.\n\n**야망.** 공개 승계 시험으로 다음 원로 후보에 올라 이씨 가문 승계를 끊는 이홍원의 길을 자기 손으로 증명한다.\n\n**공포.** 시험 차륜에 숨은 결함이 자기 서명으로 남아 사택 대표에게 기지를 내주는 명분이 되는 것.\n\n**개입.** 시험 감독을 맡거나, 결함 부품의 출처 공구를 추적할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 −20 | 무력 −15 | 물질 30 | 공동 25 | 원칙 5 | 공개 5 | 자격 90 | 분산 5 | 변혁 −30\n- 욕망: 갈망 0 | 독점 −25 | 위험 10 | 과시 20 | 지속 30 | 지향 이성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"송하율","type":"신도","to":"이홍원","basis":"차량 정비 도제로 회장 밑에서 수련"},{"from":"송하율","type":"계약","to":"아이작 워커","basis":"제동 부품을 용산 도제와 나눔"}],"incoming":[{"from":"두모","type":"신도","to":"송하율","basis":"송하율의 도제 일과를 현장에서 받고"},{"from":"추지훈","type":"맹세","to":"송하율","basis":"송하율의 도제 일과를 폭로 근거로 받고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0274', 'c870-c625-cc9c-8d99', '{"id":"person-0274","name":"Jo U-chan","title":"Work Foreman","position":"Seongha Electronics Work Foreman","characterId":"K273","rank":"Employee","commonTier":"T5","occupation":"Managing Work Crew Rotation · Accident Signatures","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Jo-Uchan","detailRoute":"/people/person-0274","birthDate":"2065-04-02","birthday":"04-02","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k273-work-crew-allocation","name":"Work crew allocation","rating":60}],"traits":[{"id":"k273-priority","name":"Demands demonstrated competence","description":"Jo Uchan rotates work crews and requires shared accident accountability from foremen and apprentices. Technical approval comes into conflict with residential anxiety.","behavior":"Office. Rank: assistant manager. Title: work squad leader. He rotated the work squads through stations and demanded the squad leader''s and the apprentice''s signatures together for every accident.","stress":"Fear. That populous residents'' representatives would seize the base on the pretext of water anxiety.","relationship":"Relations. Divided the wheel process under I Hongwon''s command and applied Gang Minseo''s repair standards in the field. Held the suspicion that the trial wheels had leaked to Gang Daeun.","effects":[]},{"id":"k273-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: assistant manager. Title: work squad leader. He rotated the work squads through stations and demanded the squad leader''s and the apprentice''s signatures together for every accident.","stress":"Fear. That populous residents'' representatives would seize the base on the pretext of water anxiety.","relationship":"Relations. Divided the wheel process under I Hongwon''s command and applied Gang Minseo''s repair standards in the field. Held the suspicion that the trial wheels had leaked to Gang Daeun.","effects":[]}],"narrative":"Jo Uchan rotates work crews and requires shared accident accountability from foremen and apprentices. Technical approval comes into conflict with residential anxiety.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c870-c625-cc9c-8d99","name":"Jo Clan of Okcheon","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":-20,"Force":-20,"Material":35,"Communal":15,"Principle":5,"Public":5,"Eligibility":65,"Dispersed":10,"Transformative":-25},"desire":{"Longing":-5,"Monopoly":5,"Risk":-10,"Display":5,"Sustained":10,"Orientation":"Reason","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Managing Work Crew Rotation · Accident Signatures","Affiliation":"Arc","Rank":"Employee","Title":"Seongha Electronics Work Foreman","Values":"Authority 15 | Openness −20 | Force −20 | Materialism 35 | Community 15 | Principle 5 | Publicity 5 | Qualification 65 | Dispersion 10 | Transformation −25","Desires":"Craving −5 | Possessiveness 5 | Risk −10 | Display 5 | Endurance 10 | Orientation: Opposite-sex | Union: Contract Cohabitation"},"sections":{"Life":"Grew up on waiting-hall duty. The Seongha Electronics work foreman post opened up as a substitute duty for an unexcused shift absence.\n- Jo Uchan handles work crew rotation and accident signature management in Seocho 4-dong. Jo links the Gangnam Station headquarters/Chairman''s Office board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Under I Hongwon''s command, Jo divides the wheel process and applies Gang Minseo''s repair specifications on site. Jo suspects that the test wheel leaked to Gang Daeun","Offices":"Rank: Staff Member. Title: Seongha Electronics Work Foreman. Rotates work crews, and for every accident requires the signatures of both the foreman and the apprentice.","Anecdote":"When rumors of a defect in the test parts spread through the Gangnam Station housing compounds, the representatives demanded that the depot''s main gate be used as a ration window.","Relationships":"Under I Hongwon''s command, divides the wheel process and applies Gang Minseo''s repair specifications on site. Suspects that the test wheel leaked to Gang Daeun.","Ambition":"Aims to protect Seongha Electronics'' Gangnam Station stronghold by getting the engineers'' Chairman''s Office to approve restarting the depot ahead of the housing petitions.","Fear":"That the representative of a populous housing compound will seize the depot under the pretext of water-supply anxiety.","Intervention":"Can seal off the workshop to carry out the test, or mediate negotiations between the housing representatives and the foreman."},"biography":"Cold toward anyone who cannot prove their skill, and remembers the blame for accidents down to the date. Makes decisions beneath the wheels rather than in meetings.\n\n- Livelihood: Work crew rotation and accident signature management\n- Affiliation: Arc\n- Rank: Staff Member\n- Title: Seongha Electronics Work Foreman\n**Life.** Grew up on waiting-hall duty. The Seongha Electronics work foreman post opened up as a substitute duty for an unexcused shift absence.\n- Jo Uchan handles work crew rotation and accident signature management in Seocho 4-dong. Jo links the Gangnam Station headquarters/Chairman''s Office board and the waiting-hall handover of daily-life cargo, access, and duty to a dong-level duty reference point. The North Gate is an approach watch for Gangnam Station and does not establish rule over the northern district or a new fortress. Under I Hongwon''s command, Jo divides the wheel process and applies Gang Minseo''s repair specifications on site. Jo suspects that the test wheel leaked to Gang Daeun\n\n**Office.** Rank: Staff Member. Title: Seongha Electronics Work Foreman. Rotates work crews, and for every accident requires the signatures of both the foreman and the apprentice.\n\n**Anecdote.** When rumors of a defect in the test parts spread through the Gangnam Station housing compounds, the representatives demanded that the depot''s main gate be used as a ration window.\n\n**Relations.** Under I Hongwon''s command, divides the wheel process and applies Gang Minseo''s repair specifications on site. Suspects that the test wheel leaked to Gang Daeun.\n\n**Ambition.** Aims to protect Seongha Electronics'' Gangnam Station stronghold by getting the engineers'' Chairman''s Office to approve restarting the depot ahead of the housing petitions.\n\n**Fear.** That the representative of a populous housing compound will seize the depot under the pretext of water-supply anxiety.\n\n**Intervention.** Can seal off the workshop to carry out the test, or mediate negotiations between the housing representatives and the foreman.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness −20 | Force −20 | Materialism 35 | Community 15 | Principle 5 | Publicity 5 | Qualification 65 | Dispersion 10 | Transformation −25\n- Desires: Craving −5 | Possessiveness 5 | Risk −10 | Display 5 | Endurance 10 | Orientation: Opposite-sex | Union: Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Jo U-chan","type":"Command","to":"Yi Hong-won","basis":"Divides wheelset processes under the chairman''s command"},{"from":"Jo U-chan","type":"Contract","to":"Gang Minseo","basis":"Applies repair standards to the work crew"},{"from":"Jo U-chan","type":"Grudge","to":"Clara Bennett","basis":"Grudge over the suspected test-wheel leak"}],"incoming":[{"from":"Dumo","type":"Contract","to":"Jo U-chan","basis":"Is assigned by rotation to Jo Uchan''s work crew"},{"from":"Bongbok","type":"Contract","to":"Jo U-chan","basis":"Takes charge of injuries in Jo Uchan''s work crew"},{"from":"Sobong","type":"Contract","to":"Jo U-chan","basis":"Carries Jo Uchan''s restart notices"},{"from":"Gukdu","type":"Command","to":"Jo U-chan","basis":"Moves the logs under Jo Uchan''s command"},{"from":"Eo Yerin","type":"Oath","to":"Jo U-chan","basis":"Testifies to the defect in Jo Uchan''s work crew"}]}}', '{"id":"person-0274","name":"조우찬","title":"작업 반장","position":"성하전자 작업 반장","characterId":"K273","rank":"사원","commonTier":"T5","occupation":"작업 조 순환·사고 서명 관리","gender":"여성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-조우찬","detailRoute":"/people/person-0274","birthDate":"2065-04-02","birthday":"04-02","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k273-work-crew-allocation","name":"작업 조 배치","rating":60}],"traits":[{"id":"k273-priority","name":"숙련 증명 요구","description":"조우찬은 작업 조를 순환시키고 반장과 도제에게 사고 책임을 함께 묻는다. 기술 승인 우선이 사택 불안과 충돌한다.","behavior":"작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.","stress":"인구 많은 사택 대표가 급수 불안을 구실로 기지를 점거하는 것.","relationship":"이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. 강다은에게 시험 차륜이 새어 나갔다는 의심을 품는다.","effects":[]},{"id":"k273-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 사원. 직함은 성하전자 작업 반장. 작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.","stress":"공포. 인구 많은 사택 대표가 급수 불안을 구실로 기지를 점거하는 것.","relationship":"관계. 이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. 강다은에게 시험 차륜이 새어 나갔다는 의심을 품는다.","effects":[]}],"narrative":"조우찬은 작업 조를 순환시키고 반장과 도제에게 사고 책임을 함께 묻는다. 기술 승인 우선이 사택 불안과 충돌한다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c870-c625-cc9c-8d99","name":"옥천 조씨","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":-20,"무력":-20,"물질":35,"공동":15,"원칙":5,"공개":5,"자격":65,"분산":10,"변혁":-25},"desire":{"갈망":-5,"독점":5,"위험":-10,"과시":5,"지속":10,"지향":"이성","결합":"계약동거"},"fields":{"생업":"작업 조 순환·사고 서명 관리","소속":"Arc","품계":"사원","직함":"성하전자 작업 반장","가치관":"권위 15 | 개방 −20 | 무력 −20 | 물질 35 | 공동 15 | 원칙 5 | 공개 5 | 자격 65 | 분산 10 | 변혁 −25","욕망":"갈망 −5 | 독점 5 | 위험 −10 | 과시 5 | 지속 10 | 지향 이성 | 결합 계약동거"},"sections":{"생애":"대합실 당직에서 자랐다. 성하전자 작업 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 조우찬은 서초4동에서 작업 조 순환·사고 서명 관리 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. 강다은에게 시험 차륜이 새어 나갔다는 의심을 품는다","관직":"품계 사원. 직함은 성하전자 작업 반장. 작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.","일화":"시험 부품 결함 소문이 강남역 사택에 퍼지자 대표들이 기지 정문을 배급 창구로 쓰자고 주장했다.","관계":"이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. 강다은에게 시험 차륜이 새어 나갔다는 의심을 품는다.","야망":"기술자 회장실가 사택 청원보다 먼저 기지 가동을 승인하게 만들어 성하전자 강남역 거점을 지킨다.","공포":"인구 많은 사택 대표가 급수 불안을 구실로 기지를 점거하는 것.","개입":"작업장을 봉인해 시험을 진행하거나, 사택 대표와 반장의 교섭을 중재할 수 있다."},"biography":"숙련을 증명하지 못한 사람에게 차갑고, 사고 책임을 날짜까지 기억한다. 회의보다 차륜 아래에서 결정을 내린다.\n\n- 생업: 작업 조 순환·사고 서명 관리\n- 소속: Arc\n- 품계: 사원\n- 직함: 성하전자 작업 반장\n**생애.** 대합실 당직에서 자랐다. 성하전자 작업 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 조우찬은 서초4동에서 작업 조 순환·사고 서명 관리 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. 강다은에게 시험 차륜이 새어 나갔다는 의심을 품는다\n\n**관직.** 품계 사원. 직함은 성하전자 작업 반장. 작업 조를 순환 배치하고, 사고 한 건에 반장과 도제의 서명을 함께 요구한다.\n\n**일화.** 시험 부품 결함 소문이 강남역 사택에 퍼지자 대표들이 기지 정문을 배급 창구로 쓰자고 주장했다.\n\n**관계.** 이홍원의 지휘로 차륜 공정을 나누고 강민서의 수리 규격을 현장 적용한다. 강다은에게 시험 차륜이 새어 나갔다는 의심을 품는다.\n\n**야망.** 기술자 회장실가 사택 청원보다 먼저 기지 가동을 승인하게 만들어 성하전자 강남역 거점을 지킨다.\n\n**공포.** 인구 많은 사택 대표가 급수 불안을 구실로 기지를 점거하는 것.\n\n**개입.** 작업장을 봉인해 시험을 진행하거나, 사택 대표와 반장의 교섭을 중재할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 −20 | 무력 −20 | 물질 35 | 공동 15 | 원칙 5 | 공개 5 | 자격 65 | 분산 10 | 변혁 −25\n- 욕망: 갈망 −5 | 독점 5 | 위험 −10 | 과시 5 | 지속 10 | 지향 이성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"조우찬","type":"지휘","to":"이홍원","basis":"차륜 공정을 회장 지휘로 나눔"},{"from":"조우찬","type":"계약","to":"강민서","basis":"수리 규격을 작업반에 적용"},{"from":"조우찬","type":"원한","to":"클라라 베넷","basis":"시험 차륜 유출 의심의 원한"}],"incoming":[{"from":"두모","type":"계약","to":"조우찬","basis":"조우찬의 작업 조에 순환 배치된다"},{"from":"봉복","type":"계약","to":"조우찬","basis":"조우찬의 작업 조 부상을 맡고"},{"from":"소봉","type":"계약","to":"조우찬","basis":"조우찬의 가동 통지를 나르고"},{"from":"국두","type":"지휘","to":"조우찬","basis":"조우찬의 지휘로 일지를 옮기고"},{"from":"어예린","type":"맹세","to":"조우찬","basis":"조우찬의 작업 조에서 결함을 증언하고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0275', 'c11c-b2ec-c131', '{"id":"person-0275","name":"Seo Jin-a","title":"Residential Community Auditor","position":"Gangnam Station Company Housing Auditor","characterId":"K274","rank":"Employee","commonTier":"T5","occupation":"Company Housing Petitions · Auditing Remaining Water Supply","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#person-Seo-Jina","detailRoute":"/people/person-0275","birthDate":"2092-02-08","birthday":"02-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k274-petition-and-water-record-review","name":"Petition and water record review","rating":55}],"traits":[{"id":"k274-priority","name":"Responsibility for deprivation","description":"Seo Jina publishes petitions beside remaining water and requires attendance at nighttime cutoffs. Dual approval remains an ambition, not an established government.","behavior":"Office. Rank: assistant manager. Title: residential community auditor. She pasted the residential election results and the water-residue levels on one board and forbade night cutoffs without audit attendance.","stress":"Fear. That Han Jaemok''s collective cutoff clause would scatter the Changdong housing population in one night.","relationship":"Relations. Contested the mixed housing-technology rule with I Hongwon and watched Han Jaemok''s water-supply talks from the housing side. Sought to raise the Changdong migrants onto Yun Choa''s citizenship ledger.","effects":[]},{"id":"k274-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: assistant manager. Title: residential community auditor. She pasted the residential election results and the water-residue levels on one board and forbade night cutoffs without audit attendance.","stress":"Fear. That Han Jaemok''s collective cutoff clause would scatter the Changdong housing population in one night.","relationship":"Relations. Contested the mixed housing-technology rule with I Hongwon and watched Han Jaemok''s water-supply talks from the housing side. Sought to raise the Changdong migrants onto Yun Choa''s citizenship ledger.","effects":[]}],"narrative":"Seo Jina publishes petitions beside remaining water and requires attendance at nighttime cutoffs. Dual approval remains an ambition, not an established government.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":-20,"Force":-5,"Material":20,"Communal":20,"Principle":30,"Public":5,"Eligibility":50,"Dispersed":15,"Transformative":-20},"desire":{"Longing":-15,"Monopoly":-10,"Risk":5,"Display":-25,"Sustained":15,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Company Housing Petitions · Auditing Remaining Water Supply","Affiliation":"Arc","Rank":"Employee","Title":"Gangnam Station Company Housing Auditor","Values":"Authority 10 | Openness −20 | Force −5 | Material 20 | Communal 20 | Principle 30 | Publicity 5 | Credentials 50 | Dispersal 15 | Transformation −20","Desires":"Craving −15 | Possessiveness −10 | Risk 5 | Display −25 | Endurance 15 | Orientation: same-sex | Union: contract cohabitation"},"sections":{"Life":"Grew up at the Seoul Station registry office. The post of Gangnam Station Company Housing Auditor opened with the deletion of a single line from a double ledger.\n- Seo Jina handles petition and remaining water balance audits in Seocho 2-dong. She proposes the petition, remaining water balance, water level, and incident record duties of the Gangnam Station company housing as a work reference for the Seocho 2-dong living area. Existing auditor, squad leader, and apprentice signature conditions are preserved, and personal residence or lodging ownership is not presumed. She contests mixed company-housing and technical governance with I Hongwon, and monitors Han Jaemok''s water-supply negotiations from the company housing side. She cross-checks the registration of Gangnam Station company housing residents against Yun Choa''s citizenship ledger","Offices":"Rank: Staff Member. Title: Gangnam Station Company Housing Auditor. Post petition results and remaining water balances on the same bulletin board, and ban night water cuts without an audit witness present.","Anecdote":"When a pressure drop in the northern water supply pipes was announced, company housing representatives pressed the Chairman''s Office to postpone the succession exam.","Relationships":"Contests mixed company-housing and technical governance with I Hongwon, and monitors Han Jaemok''s water-supply negotiations from the company housing side. Cross-checks Yun Choa''s citizenship ledger against the registration of Gangnam Station company housing residents.","Ambition":"Creates a dual approval that shares water-supply audit authority with the Chairman''s Office, so that Gangnam Station company housing does not empty out even if the water contracts waver.","Fear":"Han Jaemok''s collective water-cut clause scattering the Gangnam Station company housing population overnight.","Intervention":"Can bring in the emergency water-supply contract together with the company housing clauses, or block a base occupation made under the pretext of a water-cut threat."},"biography":"Logical and skilled at counting votes. Regards any moment when people go hungry because of technology as a personal defeat.\n\n- Occupation: Company housing petition and remaining water balance audit\n- Affiliation: Arc\n- Rank: Staff Member\n- Title: Gangnam Station Company Housing Auditor\n**Life.** Grew up at the Seoul Station registry office. The post of Gangnam Station Company Housing Auditor opened with the deletion of a single line from a double ledger.\n- Seo Jina handles petition and remaining water balance audits in Seocho 2-dong. She proposes the petition, remaining water balance, water level, and incident record duties of the Gangnam Station company housing as a work reference for the Seocho 2-dong living area. Existing auditor, squad leader, and apprentice signature conditions are preserved, and personal residence or lodging ownership is not presumed. She contests mixed company-housing and technical governance with I Hongwon, and monitors Han Jaemok''s water-supply negotiations from the company housing side. She cross-checks the registration of Gangnam Station company housing residents against Yun Choa''s citizenship ledger\n\n**Office.** Rank: Staff Member. Title: Gangnam Station Company Housing Auditor. Post petition results and remaining water balances on the same bulletin board, and ban night water cuts without an audit witness present.\n\n**Anecdote.** When a pressure drop in the northern water supply pipes was announced, company housing representatives pressed the Chairman''s Office to postpone the succession exam.\n\n**Relations.** Contests mixed company-housing and technical governance with I Hongwon, and monitors Han Jaemok''s water-supply negotiations from the company housing side. Cross-checks Yun Choa''s citizenship ledger against the registration of Gangnam Station company housing residents.\n\n**Ambition.** Creates a dual approval that shares water-supply audit authority with the Chairman''s Office, so that Gangnam Station company housing does not empty out even if the water contracts waver.\n\n**Fear.** Han Jaemok''s collective water-cut clause scattering the Gangnam Station company housing population overnight.\n\n**Intervention.** Can bring in the emergency water-supply contract together with the company housing clauses, or block a base occupation made under the pretext of a water-cut threat.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 10 | Openness −20 | Force −5 | Material 20 | Communal 20 | Principle 30 | Publicity 5 | Credentials 50 | Dispersal 15 | Transformation −20\n- Desires: Craving −15 | Possessiveness −10 | Risk 5 | Display −25 | Endurance 15 | Orientation: same-sex | Union: contract cohabitation\n:::","relations":{"outgoing":[{"from":"Seo Jin-a","type":"Rivalry","to":"Yi Hong-won","basis":"Contests mixed residential-and-technical governance"},{"from":"Seo Jin-a","type":"Contract","to":"Han Jae-mok","basis":"Monitors water supply negotiations from the residential side"}],"incoming":[{"from":"Sobong","type":"Contract","to":"Seo Jin-a","basis":"Posts Seo Jina''s remaining water balance notice side by side on the same wall"},{"from":"Mobok","type":"Command","to":"Seo Jin-a","basis":"Receiving orders to carry out Seo Jina''s housing audit at the base handle,"},{"from":"Pyeong Chaewon","type":"Contract","to":"Seo Jin-a","basis":"and adding the party''s handprint to Seo Jina''s housing audit box"}]}}', '{"id":"person-0275","name":"서진아","title":"주거공동체 감사","position":"강남역 사택 감사","characterId":"K274","rank":"사원","commonTier":"T5","occupation":"사택 청원·급수 잔량 감사","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-서진아","detailRoute":"/people/person-0275","birthDate":"2092-02-08","birthday":"02-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k274-petition-and-water-record-review","name":"청원·급수 기록 대조","rating":55}],"traits":[{"id":"k274-priority","name":"생활 피해의 책임","description":"서진아는 청원과 잔량을 함께 공개하며 야간 단수에 입회를 요구한다. 이중 승인은 아직 야망이며 완성된 통치 제도가 아니다.","behavior":"사택 청원 결과와 급수 잔량을 같은 게시판에 붙이고, 야간 단수는 감사 입회 없이 금지한다.","stress":"한재목의 집단 단수 조항이 강남역 사택 인구를 하룻밤에 흩어 놓는 것.","relationship":"이홍원과 사택·기술 혼합 통치를 다투며 한재목의 물 공급 협상을 사택 측에서 감시한다. 윤초아의 시민권 원장에 강남역 이주민을 올리려 한다.","effects":[]},{"id":"k274-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 사원. 직함은 강남역 사택 감사. 사택 청원 결과와 급수 잔량을 같은 게시판에 붙이고, 야간 단수는 감사 입회 없이 금지한다.","stress":"공포. 한재목의 집단 단수 조항이 강남역 사택 인구를 하룻밤에 흩어 놓는 것.","relationship":"관계. 이홍원과 사택·기술 혼합 통치를 다투며 한재목의 물 공급 협상을 사택 측에서 감시한다. 윤초아의 시민권 원장에 강남역 이주민을 올리려 한다.","effects":[]}],"narrative":"서진아는 청원과 잔량을 함께 공개하며 야간 단수에 입회를 요구한다. 이중 승인은 아직 야망이며 완성된 통치 제도가 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":-20,"무력":-5,"물질":20,"공동":20,"원칙":30,"공개":5,"자격":50,"분산":15,"변혁":-20},"desire":{"갈망":-15,"독점":-10,"위험":5,"과시":-25,"지속":15,"지향":"동성","결합":"계약동거"},"fields":{"생업":"사택 청원·급수 잔량 감사","소속":"Arc","품계":"사원","직함":"강남역 사택 감사","가치관":"권위 10 | 개방 −20 | 무력 −5 | 물질 20 | 공동 20 | 원칙 30 | 공개 5 | 자격 50 | 분산 15 | 변혁 −20","욕망":"갈망 −15 | 독점 −10 | 위험 5 | 과시 −25 | 지속 15 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"서울역 등기소에서 자랐다. 강남역 사택 감사 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 서진아는 서초2동에서 사택 청원·급수 잔량 감사 업무를 맡는다. 강남역 사택의 청원·급수 잔량·수위·사고 기록 업무를 서초2동 생활권 근무 참조로 제안한다. 기존 감사·반장·도제 서명 조건을 보존하고 개인 거주·숙소 소유는 추정하지 않는다. 이홍원과 사택·기술 혼합 통치를 다투며 한재목의 물 공급 협상을 사택 측에서 감시한다. 윤초아의 시민권 원장에 강남역 사택 주민의 등록을 대조한다","관직":"품계 사원. 직함은 강남역 사택 감사. 사택 청원 결과와 급수 잔량을 같은 게시판에 붙이고, 야간 단수는 감사 입회 없이 금지한다.","일화":"북부 급수 배관 압력 저하가 공지되자 사택 대표들이 승계 시험을 연기하라고 회장실를 압박했다.","관계":"이홍원과 사택·기술 혼합 통치를 다투며 한재목의 물 공급 협상을 사택 측에서 감시한다. 윤초아의 시민권 원장과 강남역 사택 주민 등록을 대조한다.","야망":"물 계약이 흔들려도 강남역 사택이 비지 않도록 급수 감사권을 회장실와 공유하는 이중 승인을 만든다.","공포":"한재목의 집단 단수 조항이 강남역 사택 인구를 하룻밤에 흩어 놓는 것.","개입":"비상 급수 계약을 사택 조항과 함께 가져오거나, 단수 위협을 빌미로 한 기지 점거를 막을 수 있다."},"biography":"논리적이고 표를 세는 데 능하다. 기술 탓에 사람이 굶는 순간을 개인적 패배로 여긴다.\n\n- 생업: 사택 청원·급수 잔량 감사\n- 소속: Arc\n- 품계: 사원\n- 직함: 강남역 사택 감사\n**생애.** 서울역 등기소에서 자랐다. 강남역 사택 감사 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 서진아는 서초2동에서 사택 청원·급수 잔량 감사 업무를 맡는다. 강남역 사택의 청원·급수 잔량·수위·사고 기록 업무를 서초2동 생활권 근무 참조로 제안한다. 기존 감사·반장·도제 서명 조건을 보존하고 개인 거주·숙소 소유는 추정하지 않는다. 이홍원과 사택·기술 혼합 통치를 다투며 한재목의 물 공급 협상을 사택 측에서 감시한다. 윤초아의 시민권 원장에 강남역 사택 주민의 등록을 대조한다\n\n**관직.** 품계 사원. 직함은 강남역 사택 감사. 사택 청원 결과와 급수 잔량을 같은 게시판에 붙이고, 야간 단수는 감사 입회 없이 금지한다.\n\n**일화.** 북부 급수 배관 압력 저하가 공지되자 사택 대표들이 승계 시험을 연기하라고 회장실를 압박했다.\n\n**관계.** 이홍원과 사택·기술 혼합 통치를 다투며 한재목의 물 공급 협상을 사택 측에서 감시한다. 윤초아의 시민권 원장과 강남역 사택 주민 등록을 대조한다.\n\n**야망.** 물 계약이 흔들려도 강남역 사택이 비지 않도록 급수 감사권을 회장실와 공유하는 이중 승인을 만든다.\n\n**공포.** 한재목의 집단 단수 조항이 강남역 사택 인구를 하룻밤에 흩어 놓는 것.\n\n**개입.** 비상 급수 계약을 사택 조항과 함께 가져오거나, 단수 위협을 빌미로 한 기지 점거를 막을 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 −20 | 무력 −5 | 물질 20 | 공동 20 | 원칙 30 | 공개 5 | 자격 50 | 분산 15 | 변혁 −20\n- 욕망: 갈망 −15 | 독점 −10 | 위험 5 | 과시 −25 | 지속 15 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"서진아","type":"경쟁","to":"이홍원","basis":"주거·기술 혼합 통치를 다툼"},{"from":"서진아","type":"계약","to":"한재목","basis":"물 공급 협상을 주거 쪽에서 감시"}],"incoming":[{"from":"소봉","type":"계약","to":"서진아","basis":"서진아의 급수 잔량 공지를 같은 벽에 나란히 붙인다"},{"from":"모복","type":"지휘","to":"서진아","basis":"서진아의 주거 감사를 거점 핸들에서 집행하는 지휘를 받고"},{"from":"평채원","type":"계약","to":"서진아","basis":"서진아의 주거 감사 함에 당사자 손도장을 보태고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0276', 'ad8c-c548-b3d9', '{"id":"person-0276","name":"Gwon Do-ha","title":"Rail Cavalry Squad Leader","position":"Gangnam Station Rail Cavalry Squad Leader","characterId":"K275","rank":"Employee","commonTier":"T5","occupation":"Wheel Inspection · Verifying Armament Loading","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#Person-Gwon-Doha","detailRoute":"/people/person-0276","birthDate":"2097-03-04","birthday":"03-04","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":7,"effective":7}},"skills":[{"id":"k275-escort-timing-coordination","name":"Escort timing coordination","rating":55}],"traits":[{"id":"k275-priority","name":"Discipline before charges","description":"Gwon Doha coordinates northern gate patrol and escort timings and signals. His strict charge discipline does not establish battlefield victories.","behavior":"Office. Rank: assistant manager. Title: rail cavalry squad leader. He made wheel checks mandatory before sorties and required the Elder''s and the auditor''s signatures together for arms loading.","stress":"Fear. That the rail cavalry would be absorbed into a residential militia and the base would become a barracks.","relationship":"Relations. Held I Hongwon''s north gate patrol and matched the northern convoys with Jang Sehwa. Shared the corridor signals with Kang Taesan.","effects":[]},{"id":"k275-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: assistant manager. Title: rail cavalry squad leader. He made wheel checks mandatory before sorties and required the Elder''s and the auditor''s signatures together for arms loading.","stress":"Fear. That the rail cavalry would be absorbed into a residential militia and the base would become a barracks.","relationship":"Relations. Held I Hongwon''s north gate patrol and matched the northern convoys with Jang Sehwa. Shared the corridor signals with Kang Taesan.","effects":[]}],"narrative":"Gwon Doha coordinates northern gate patrol and escort timings and signals. His strict charge discipline does not establish battlefield victories.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"Andong Gwon Clan","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":20,"Openness":-15,"Force":5,"Material":40,"Communal":30,"Principle":15,"Public":-5,"Eligibility":70,"Dispersed":20,"Transformative":-25},"desire":{"Longing":35,"Monopoly":15,"Risk":10,"Display":30,"Sustained":30,"Orientation":"None","Union":"None"},"fields":{"Livelihood":"Wheel Inspection · Verifying Armament Loading","Affiliation":"Arc","Rank":"Employee","Title":"Gangnam Station Rail Cavalry Squad Leader","Values":"Authority 20 | Openness −15 | Force 5 | Material 40 | Communal 30 | Principle 15 | Publicity −5 | Credentials 70 | Dispersal 20 | Transformation −25","Desires":"Craving 35 | Possessiveness 15 | Risk 10 | Display 30 | Endurance 30 | Orientation: none specified | Union: none"},"sections":{"Life":"Grew up on waiting-hall duty. The post of Gangnam Station Rail Cavalry Squad Leader opened through substitute duty for an unexcused shift absence.\n- Gwon Doha handles wheel inspection and armament loading verification in Seocho 4-dong. She connects the Gangnam Station headquarters and Chairman''s Office bulletin board, and the waiting-hall handover of living cargo, access, and duty, as dong-level work reference points. The North Gate is Gangnam Station''s approach duty post and does not create rule over the northern district or a new fortress. She takes charge of I Hongwon''s North Gate patrol and aligns the northern escort with Jang Sehwa. She shares corridor signals with Gang Taesan","Offices":"Rank: Staff Member. Title: Gangnam Station Rail Cavalry Squad Leader. Wheel inspection before sortie is made mandatory, and armament loading must be signed jointly by the managing director and the auditor.","Anecdote":"Right after a test wheel defect, the North Gate patrol car stopped due to faulty brakes, throwing off the escort timing.","Relationships":"Takes charge of I Hongwon''s North Gate patrol and aligns the northern escort with Jang Sehwa. Shares corridor signals with Gang Taesan.","Ambition":"Ties the North Gate patrol to the northern route of the Gangnam Station escort, moving Seongha Electronics trains according to Seoul''s internal contracts and duty rosters.","Fear":"Rail Cavalry being absorbed into the company housing militia, turning the base into barracks.","Intervention":"Can replace the braking device on site, or report the Rail Cavalry''s unauthorized arming to the Chairman''s Office."},"biography":"Likes discipline and regards silence on the tracks as part of combat. Says that an assault without skill is close to betrayal.\n\n- Occupation: Wheel inspection and armament loading verification\n- Affiliation: Arc\n- Rank: Staff Member\n- Title: Gangnam Station Rail Cavalry Squad Leader\n**Life.** Grew up on waiting-hall duty. The post of Gangnam Station Rail Cavalry Squad Leader opened through substitute duty for an unexcused shift absence.\n- Gwon Doha handles wheel inspection and armament loading verification in Seocho 4-dong. She connects the Gangnam Station headquarters and Chairman''s Office bulletin board, and the waiting-hall handover of living cargo, access, and duty, as dong-level work reference points. The North Gate is Gangnam Station''s approach duty post and does not create rule over the northern district or a new fortress. She takes charge of I Hongwon''s North Gate patrol and aligns the northern escort with Jang Sehwa. She shares corridor signals with Gang Taesan\n\n**Office.** Rank: Staff Member. Title: Gangnam Station Rail Cavalry Squad Leader. Wheel inspection before sortie is made mandatory, and armament loading must be signed jointly by the managing director and the auditor.\n\n**Anecdote.** Right after a test wheel defect, the North Gate patrol car stopped due to faulty brakes, throwing off the escort timing.\n\n**Relations.** Takes charge of I Hongwon''s North Gate patrol and aligns the northern escort with Jang Sehwa. Shares corridor signals with Gang Taesan.\n\n**Ambition.** Ties the North Gate patrol to the northern route of the Gangnam Station escort, moving Seongha Electronics trains according to Seoul''s internal contracts and duty rosters.\n\n**Fear.** Rail Cavalry being absorbed into the company housing militia, turning the base into barracks.\n\n**Intervention.** Can replace the braking device on site, or report the Rail Cavalry''s unauthorized arming to the Chairman''s Office.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 20 | Openness −15 | Force 5 | Material 40 | Communal 30 | Principle 15 | Publicity −5 | Credentials 70 | Dispersal 20 | Transformation −25\n- Desires: Craving 35 | Possessiveness 15 | Risk 10 | Display 30 | Endurance 30 | Orientation: none specified | Union: none\n:::","relations":{"outgoing":[{"from":"Gwon Do-ha","type":"Contract","to":"Jang Sehwa","basis":"Aligned the northern escort timing"},{"from":"Gwon Do-ha","type":"Contract","to":"Gang Taesan","basis":"Sharing corridor signals"}],"incoming":[{"from":"Yongdubong","type":"Contract","to":"Gwon Do-ha","basis":"Receiving Gwon Doha''s sortie list at the maintenance bay, and"}]}}', '{"id":"person-0276","name":"권도하","title":"궤도기병 반장","position":"강남역 궤도기병 반장","characterId":"K275","rank":"사원","commonTier":"T5","occupation":"차륜 점검·무장 탑재 확인","gender":"여성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-권도하","detailRoute":"/people/person-0276","birthDate":"2097-03-04","birthday":"03-04","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":7,"effective":7}},"skills":[{"id":"k275-escort-timing-coordination","name":"호송 시각 조정","rating":55}],"traits":[{"id":"k275-priority","name":"돌격보다 규율","description":"권도하는 북문 순찰과 북부 호송의 시각·신호를 맞춘다. 돌격 규율은 강경하지만 전투 승리 근거는 없다.","behavior":"출격 전에 차륜 점검을 의무화하고, 무장 탑재는 상무와 감사가 함께 서명해야 한다.","stress":"궤도기병이 사택 민병으로 흡수되어 기지가 병영이 되는 것.","relationship":"이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다.","effects":[]},{"id":"k275-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 사원. 직함은 강남역 궤도기병 반장. 출격 전에 차륜 점검을 의무화하고, 무장 탑재는 상무와 감사가 함께 서명해야 한다.","stress":"공포. 궤도기병이 사택 민병으로 흡수되어 기지가 병영이 되는 것.","relationship":"관계. 이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다.","effects":[]}],"narrative":"권도하는 북문 순찰과 북부 호송의 시각·신호를 맞춘다. 돌격 규율은 강경하지만 전투 승리 근거는 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad8c-c548-b3d9","name":"안동 권씨","crest":"clan-crests/ad8c-c548-b3d9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":20,"개방":-15,"무력":5,"물질":40,"공동":30,"원칙":15,"공개":-5,"자격":70,"분산":20,"변혁":-25},"desire":{"갈망":35,"독점":15,"위험":10,"과시":30,"지속":30,"지향":"무성향","결합":"없음"},"fields":{"생업":"차륜 점검·무장 탑재 확인","소속":"Arc","품계":"사원","직함":"강남역 궤도기병 반장","가치관":"권위 20 | 개방 −15 | 무력 5 | 물질 40 | 공동 30 | 원칙 15 | 공개 −5 | 자격 70 | 분산 20 | 변혁 −25","욕망":"갈망 35 | 독점 15 | 위험 10 | 과시 30 | 지속 30 | 지향 무성향 | 결합 없음"},"sections":{"생애":"대합실 당직에서 자랐다. 강남역 궤도기병 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 권도하는 서초4동에서 차륜 점검·무장 탑재 확인 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다","관직":"품계 사원. 직함은 강남역 궤도기병 반장. 출격 전에 차륜 점검을 의무화하고, 무장 탑재는 상무와 감사가 함께 서명해야 한다.","일화":"시험 차륜 결함 직후 북문 순찰차가 제동 불량으로 정차해 호송 시각이 어긋났다.","관계":"이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다.","야망":"북문 순찰을 강남역 호송의 북문로 묶어 서울 내부 계약과 당직표에 따라 성하전자 열차를 움직인다.","공포":"궤도기병이 사택 민병으로 흡수되어 기지가 병영이 되는 것.","개입":"제동 장치를 현장에서 교체하거나, 궤도기병의 무단 무장을 회장실에 보고할 수 있다."},"biography":"규율을 좋아하고 선로 위의 침묵을 전투의 일부로 본다. 숙련 없는 돌격은 배신에 가깝다고 말한다.\n\n- 생업: 차륜 점검·무장 탑재 확인\n- 소속: Arc\n- 품계: 사원\n- 직함: 강남역 궤도기병 반장\n**생애.** 대합실 당직에서 자랐다. 강남역 궤도기병 반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 권도하는 서초4동에서 차륜 점검·무장 탑재 확인 업무를 맡는다. 강남역 본사·회장실 게시판과 대합실 생활 화물 인계·출입·당직을 동 수준 근무 기준점으로 연결한다. 북문은 강남역 접근 당직이며 북부 권역 지배·새 요새를 만들지 않는다. 이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다\n\n**관직.** 품계 사원. 직함은 강남역 궤도기병 반장. 출격 전에 차륜 점검을 의무화하고, 무장 탑재는 상무와 감사가 함께 서명해야 한다.\n\n**일화.** 시험 차륜 결함 직후 북문 순찰차가 제동 불량으로 정차해 호송 시각이 어긋났다.\n\n**관계.** 이홍원의 북문 순찰을 맡고 장세화와 북부 호송을 맞춘다. 강태산과 회랑 신호를 공유한다.\n\n**야망.** 북문 순찰을 강남역 호송의 북문로 묶어 서울 내부 계약과 당직표에 따라 성하전자 열차를 움직인다.\n\n**공포.** 궤도기병이 사택 민병으로 흡수되어 기지가 병영이 되는 것.\n\n**개입.** 제동 장치를 현장에서 교체하거나, 궤도기병의 무단 무장을 회장실에 보고할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 20 | 개방 −15 | 무력 5 | 물질 40 | 공동 30 | 원칙 15 | 공개 −5 | 자격 70 | 분산 20 | 변혁 −25\n- 욕망: 갈망 35 | 독점 15 | 위험 10 | 과시 30 | 지속 30 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"권도하","type":"계약","to":"장세화","basis":"북부 호송 시각을 맞춤"},{"from":"권도하","type":"계약","to":"강태산","basis":"회랑 신호를 공유"}],"incoming":[{"from":"용두봉","type":"계약","to":"권도하","basis":"권도하의 출격 목록을 정비창에서 받고"}]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0277', 'd669-d68c-b355-9ec3', '{"id":"person-0277","name":"Hwang No-eul","title":"Scrap Iron Recovery Crew Foreman","position":"Seongha Electronics Scrap Iron Recovery Crew Foreman","characterId":"K276","rank":"Employee","commonTier":"T5","occupation":"Verifying Scrap Iron Recovery Weight · Shipments","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#Person-Hwang-Noeul","detailRoute":"/people/person-0277","birthDate":"2097-05-10","birthday":"05-10","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k276-recovered-inventory-management","name":"Recovered inventory management","rating":60}],"traits":[{"id":"k276-priority","name":"Public inventory standards","description":"Hwang Noeul uses public scales and inventory reports to reserve trial metal. Supply bargaining is documented, not control over regional resources.","behavior":"Office. Rank: assistant manager. Title: steel salvage work squad leader. He put salvage tonnage on the public scales and blocked the release of any steel that had entered a house-only column before the seniority council''s ratification.","stress":"Fear. That salvage steel would leave as munitions-only and the civil trains would stop forever.","relationship":"Relations. Reported inventory to I Hongwon and traded the wheel supply terms with Shin Gaon. Set aside the steel for Jo Woochan''s trial wheels first.","effects":[]},{"id":"k276-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: assistant manager. Title: steel salvage work squad leader. He put salvage tonnage on the public scales and blocked the release of any steel that had entered a house-only column before the seniority council''s ratification.","stress":"Fear. That salvage steel would leave as munitions-only and the civil trains would stop forever.","relationship":"Relations. Reported inventory to I Hongwon and traded the wheel supply terms with Shin Gaon. Set aside the steel for Jo Woochan''s trial wheels first.","effects":[]}],"narrative":"Hwang Noeul uses public scales and inventory reports to reserve trial metal. Supply bargaining is documented, not control over regional resources.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d669-d68c-b355-9ec3","name":"Hoedeok Hwang Clan","crest":"clan-crests/d669-d68c-b355-9ec3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":-20,"Force":0,"Material":35,"Communal":25,"Principle":15,"Public":0,"Eligibility":70,"Dispersed":5,"Transformative":-20},"desire":{"Longing":0,"Monopoly":30,"Risk":15,"Display":10,"Sustained":-15,"Orientation":"Fluid","Union":"None"},"fields":{"Livelihood":"Verifying Scrap Iron Recovery Weight · Shipments","Affiliation":"Arc","Rank":"Employee","Title":"Seongha Electronics Scrap Iron Recovery Crew Foreman","Values":"Authority 10 | Openness −20 | Force 0 | Material 35 | Communal 25 | Principle 15 | Publicity 0 | Qualification 70 | Dispersion 5 | Reform −20","Desires":"Craving 0 | Monopoly 30 | Risk 15 | Display 10 | Persistence −15 | Orientation Fluid | Bonding None"},"sections":{"Life":"Grew up on waiting-hall duty. The post of Seongha Electronics Steel Recovery Crew Chief opened up through a substitute duty for an unexcused shift absence.\n- Hwang Noeul handles recovered-steel weight and shipment verification in Yeoksam 1-dong. Seongha Electronics'' maintenance sample, weight, lot, measurement, work crew, and accident signature duties are refined to the Yeoksam 1-dong work-and-living area adjacent to Gangnam Station. The Yeoksam waiting-hall cargo handover is a reference only and does not confirm actual factory equipment, warehouse monopolies, or running trains. Reports stock to I Hongwon and trades wheel supply terms with Sin Gaon. Sets aside steel first for Jo Uchan''s test wheels","Offices":"Rank: Employee. Title: Seongha Electronics Steel Recovery Crew Chief. Puts recovered weights on the public scale and blocks the release of steel that went into the I Clan''s exclusive bin until the Chairman''s Office approves it.","Anecdote":"A weight record emerged showing that steel from the same lot as the defective bearing had been diverted toward the Yongsan warehouse.","Relationships":"Reports stock to I Hongwon and trades wheel supply terms with Sin Gaon. Sets aside steel first for Jo Uchan''s test wheels.","Ambition":"Binds wheel and brake steel into Seongha Electronics'' standard stock so that no particular work crew can hold parts hostage to shake the succession.","Fear":"Recovered steel being diverted to military use, so that civilian trains stop for good.","Intervention":"Can recall a steel lot, or have the Chairman''s Office halt shipments on the clan''s side."},"biography":"Pragmatic, but harsh toward those who hide scrap metal. Believes that cheating on weight is the same as shaving down the rails.\n\n- Livelihood: Recovered-steel weight and shipment verification\n- Affiliation: Arc\n- Rank: Employee\n- Title: Seongha Electronics Steel Recovery Crew Chief\n**Life.** Grew up on waiting-hall duty. The post of Seongha Electronics Steel Recovery Crew Chief opened up through a substitute duty for an unexcused shift absence.\n- Hwang Noeul handles recovered-steel weight and shipment verification in Yeoksam 1-dong. Seongha Electronics'' maintenance sample, weight, lot, measurement, work crew, and accident signature duties are refined to the Yeoksam 1-dong work-and-living area adjacent to Gangnam Station. The Yeoksam waiting-hall cargo handover is a reference only and does not confirm actual factory equipment, warehouse monopolies, or running trains. Reports stock to I Hongwon and trades wheel supply terms with Sin Gaon. Sets aside steel first for Jo Uchan''s test wheels\n\n**Office.** Rank: Employee. Title: Seongha Electronics Steel Recovery Crew Chief. Puts recovered weights on the public scale and blocks the release of steel that went into the I Clan''s exclusive bin until the Chairman''s Office approves it.\n\n**Anecdote.** A weight record emerged showing that steel from the same lot as the defective bearing had been diverted toward the Yongsan warehouse.\n\n**Relations.** Reports stock to I Hongwon and trades wheel supply terms with Sin Gaon. Sets aside steel first for Jo Uchan''s test wheels.\n\n**Ambition.** Binds wheel and brake steel into Seongha Electronics'' standard stock so that no particular work crew can hold parts hostage to shake the succession.\n\n**Fear.** Recovered steel being diverted to military use, so that civilian trains stop for good.\n\n**Intervention.** Can recall a steel lot, or have the Chairman''s Office halt shipments on the clan''s side.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 10 | Openness −20 | Force 0 | Material 35 | Communal 25 | Principle 15 | Publicity 0 | Qualification 70 | Dispersion 5 | Reform −20\n- Desires: Craving 0 | Monopoly 30 | Risk 15 | Display 10 | Persistence −15 | Orientation Fluid | Bonding None\n:::","relations":{"outgoing":[{"from":"Hwang No-eul","type":"Command","to":"Yi Hong-won","basis":"Reports steel stock to the chairman"},{"from":"Hwang No-eul","type":"Contract","to":"Alexander Miller","basis":"Trades wheel-supply terms with the Rail Clan"}],"incoming":[{"from":"Moso","type":"Contract","to":"Hwang No-eul","basis":"Matching shipments to Hwang Noeul''s recovery scale"},{"from":"Bongguk","type":"Command","to":"Hwang No-eul","basis":"Guarding the scale under Hwang Noeul''s command"},{"from":"Sun Hajun","type":"Oath","to":"Hwang No-eul","basis":"Overlaying the agreed weight on Hwang Noeul''s recovery scale"}]}}', '{"id":"person-0277","name":"황노을","title":"철재 회수 작업반장","position":"성하전자 철재 회수 작업반장","characterId":"K276","rank":"사원","commonTier":"T5","occupation":"철재 회수 중량·출고 검증","gender":"남성","stage":"S1","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-11#인물-황노을","detailRoute":"/people/person-0277","birthDate":"2097-05-10","birthday":"05-10","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":8,"effective":8},"stewardship":{"base":11,"effective":11},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k276-recovered-inventory-management","name":"회수 재고 관리","rating":60}],"traits":[{"id":"k276-priority","name":"재고의 공적 기준","description":"황노을은 공개 저울과 재고 보고로 시험 철재를 따로 둔다. 공급 조건 거래는 확인되지만 광역 자원 장악으로 확대하지 않는다.","behavior":"회수 중량을 공개 저울에 올리고, 이씨 가문 전용 칸으로 들어간 철재는 회장실 인준 전 출고를 막는다.","stress":"회수 철재가 군수 전용으로 빠져 민생 열차가 영영 멈추는 것.","relationship":"이홍원에게 재고를 보고하고 신가온에게 차륜 공급 조건을 거래한다. 조우찬의 시험 차륜에 쓸 철재를 우선 떼어 둔다.","effects":[]},{"id":"k276-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 사원. 직함은 성하전자 철재 회수 작업반장. 회수 중량을 공개 저울에 올리고, 이씨 가문 전용 칸으로 들어간 철재는 회장실 인준 전 출고를 막는다.","stress":"공포. 회수 철재가 군수 전용으로 빠져 민생 열차가 영영 멈추는 것.","relationship":"관계. 이홍원에게 재고를 보고하고 신가온에게 차륜 공급 조건을 거래한다. 조우찬의 시험 차륜에 쓸 철재를 우선 떼어 둔다.","effects":[]}],"narrative":"황노을은 공개 저울과 재고 보고로 시험 철재를 따로 둔다. 공급 조건 거래는 확인되지만 광역 자원 장악으로 확대하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d669-d68c-b355-9ec3","name":"회덕 황씨","crest":"clan-crests/d669-d68c-b355-9ec3.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":-20,"무력":0,"물질":35,"공동":25,"원칙":15,"공개":0,"자격":70,"분산":5,"변혁":-20},"desire":{"갈망":0,"독점":30,"위험":15,"과시":10,"지속":-15,"지향":"유동","결합":"없음"},"fields":{"생업":"철재 회수 중량·출고 검증","소속":"Arc","품계":"사원","직함":"성하전자 철재 회수 작업반장","가치관":"권위 10 | 개방 −20 | 무력 0 | 물질 35 | 공동 25 | 원칙 15 | 공개 0 | 자격 70 | 분산 5 | 변혁 −20","욕망":"갈망 0 | 독점 30 | 위험 15 | 과시 10 | 지속 −15 | 지향 유동 | 결합 없음"},"sections":{"생애":"대합실 당직에서 자랐다. 성하전자 철재 회수 작업반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 황노을은 역삼1동에서 철재 회수 중량·출고 검증 업무를 맡는다. 성하전자 정비 표본·중량·로트·실측·작업 조·사고 서명 업무를 강남역 인접 역삼1동 작업 생활권으로 정밀화한다. 역삼 대합실 화물 인계는 참고이며 실제 공장 설비·창고 독점·운행 열차를 확정하지 않는다. 이홍원에게 재고를 보고하고 신가온에게 차륜 공급 조건을 거래한다. 조우찬의 시험 차륜에 쓸 철재를 우선 떼어 둔다","관직":"품계 사원. 직함은 성하전자 철재 회수 작업반장. 회수 중량을 공개 저울에 올리고, 이씨 가문 전용 칸으로 들어간 철재는 회장실 인준 전 출고를 막는다.","일화":"결함 베어링과 같은 로트의 철재가 용산 창고 쪽으로 빠졌다는 중량 기록이 나왔다.","관계":"이홍원에게 재고를 보고하고 신가온에게 차륜 공급 조건을 거래한다. 조우찬의 시험 차륜에 쓸 철재를 우선 떼어 둔다.","야망":"차륜·제동 철재를 성하전자 표준 재고로 묶어 특정 작업 조가 부품을 볼모로 후계를 흔들지 못하게 한다.","공포":"회수 철재가 군수 전용으로 빠져 민생 열차가 영영 멈추는 것.","개입":"철재 로트를 회수하거나, 가문 쪽 출고를 회장실에서 정지시킬 수 있다."},"biography":"실리적이나 고철을 숨기는 사람을 가혹하게 다룬다. 무게를 속이는 일은 선로를 깎는 일과 같다고 본다.\n\n- 생업: 철재 회수 중량·출고 검증\n- 소속: Arc\n- 품계: 사원\n- 직함: 성하전자 철재 회수 작업반장\n**생애.** 대합실 당직에서 자랐다. 성하전자 철재 회수 작업반장 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 황노을은 역삼1동에서 철재 회수 중량·출고 검증 업무를 맡는다. 성하전자 정비 표본·중량·로트·실측·작업 조·사고 서명 업무를 강남역 인접 역삼1동 작업 생활권으로 정밀화한다. 역삼 대합실 화물 인계는 참고이며 실제 공장 설비·창고 독점·운행 열차를 확정하지 않는다. 이홍원에게 재고를 보고하고 신가온에게 차륜 공급 조건을 거래한다. 조우찬의 시험 차륜에 쓸 철재를 우선 떼어 둔다\n\n**관직.** 품계 사원. 직함은 성하전자 철재 회수 작업반장. 회수 중량을 공개 저울에 올리고, 이씨 가문 전용 칸으로 들어간 철재는 회장실 인준 전 출고를 막는다.\n\n**일화.** 결함 베어링과 같은 로트의 철재가 용산 창고 쪽으로 빠졌다는 중량 기록이 나왔다.\n\n**관계.** 이홍원에게 재고를 보고하고 신가온에게 차륜 공급 조건을 거래한다. 조우찬의 시험 차륜에 쓸 철재를 우선 떼어 둔다.\n\n**야망.** 차륜·제동 철재를 성하전자 표준 재고로 묶어 특정 작업 조가 부품을 볼모로 후계를 흔들지 못하게 한다.\n\n**공포.** 회수 철재가 군수 전용으로 빠져 민생 열차가 영영 멈추는 것.\n\n**개입.** 철재 로트를 회수하거나, 가문 쪽 출고를 회장실에서 정지시킬 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 −20 | 무력 0 | 물질 35 | 공동 25 | 원칙 15 | 공개 0 | 자격 70 | 분산 5 | 변혁 −20\n- 욕망: 갈망 0 | 독점 30 | 위험 15 | 과시 10 | 지속 −15 | 지향 유동 | 결합 없음\n:::","relations":{"outgoing":[{"from":"황노을","type":"지휘","to":"이홍원","basis":"철재 재고를 회장에게 보고"},{"from":"황노을","type":"계약","to":"알렉산더 밀러","basis":"차륜 공급 조건을 선로 가문과 거래"}],"incoming":[{"from":"모소","type":"계약","to":"황노을","basis":"황노을의 회수 저울과 출고를 맞추고"},{"from":"봉국","type":"지휘","to":"황노을","basis":"황노을의 지휘로 저울을 지키고"},{"from":"순하준","type":"맹세","to":"황노을","basis":"황노을의 회수 저울에 협약 중량을 겹치고"}]}}');
