INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0428', 'ac15-c9c4-c8fc', '{"id":"person-0428","name":"Gang Jiyu","title":"Gateway Duty Officer","position":"Gateway Duty Officer","rank":"Sergeant","commonTier":"T5","occupation":"Gateway Public Window Reception","gender":"Male","stage":"S4","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0428","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0428","name":"강지유","title":"관문 당직","position":"관문 당직","rank":"병장","commonTier":"T5","occupation":"관문 공개 창구 접수","gender":"남성","stage":"S4","state":"S05","stateName":"동방사","detailRoute":"/people/person-0428","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0429', 'c870-d55c-c591', '{"id":"person-0429","name":"Jo Yejun","title":"Testimony Scout","position":"Testimony Scout","characterId":"K429","rank":"","commonTier":"T3","occupation":"Public Confrontation of Witnesses and Testimony Record","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#inmul-jo-yejun","detailRoute":"/people/person-0429","birthDate":"2101-06-30","birthday":"06-30","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k429-witness-confrontation","name":"Witness confrontation","rating":45}],"traits":[{"id":"k429-choice","name":"Sets conflicting accounts side by side","description":"Anecdote. In 2125, when the accounts of two witnesses split, he opened a public confrontation. By this deed the signature of the testimony surveyor post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125, when the accounts of two witnesses split, he opened a public confrontation. By this deed the signature of the testimony surveyor post rose into the ledger.","stress":"Fear. That the testimony surveyor duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k429-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the testimony surveyor duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. The actual response is not yet recorded.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125, when the accounts of two witnesses split, he opened a public confrontation. By this deed the signature of the testimony surveyor post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-51830-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K429","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-51830-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c870-d55c-c591","name":"Hanyang Jo Clan","crest":"clan-crests/c870-d55c-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":30,"Openness":-15,"Force":-25,"Material":-30,"Communal":20,"Principle":45,"Public":-10,"Eligibility":15,"Dispersed":-25,"Transformative":-30},"desire":{"Longing":10,"Monopoly":30,"Risk":-25,"Display":15,"Sustained":-20,"Orientation":"Same-Sex","Union":"Polyamorous"},"fields":{"Livelihood":"Public Confrontation of Witnesses and Testimony Record","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Testimony Scout","Values":"Authority 30 | Openness −15 | Force −25 | Materialism −30 | Communal 20 | Principle 45 | Publicity −10 | Qualification 15 | Decentralization −25 | Transformation −30","Desires":"Craving 10 | Exclusivity 30 | Risk −25 | Display 15 | Persistence −20 | Orientation Same-sex | Bonding Polyamorous"},"sections":{"Life":"He grew up on waiting-hall duty. The Testimony Surveyor post opened as a substitute shift covering an unauthorized absence from the rotation.\n- Jo Yejun''s work of public witness confrontations and testimony records is tied to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.","Anecdote":"In 2125, when the accounts of two witnesses diverged, he opened a public confrontation. Because of this, the signature for the Testimony Surveyor post was entered in the ledger.","Relationships":"Through the handover of the work of public witness confrontations and testimony records, he is linked to the senior duty holder of the same living sphere.","Ambition":"From the Testimony Surveyor post, he carries on public witness confrontations and testimony records so that the ledger of the Seoul Metropolitan Government local civil service organization is not broken between duty shifts.","Fear":"That the Testimony Surveyor duty falls vacant, so that the stamps and registers for downtown passage tied to the work of public witness confrontations and testimony records break off, and even the endorsement of the constituent powers of the Seoul Metropolitan Government local civil service organization, which rely on those records, halts.","Intervention":"He can stand as a witness to the duty handover of the work of public witness confrontations and testimony records, or expose the empty key of that post."},"biography":"When testimonies split, he trusts the confrontation ledger rather than the loudness of a voice, and keeps the duty continuous.\n\n- Livelihood: public witness confrontations and testimony records\n- Affiliation: Seoul Metropolitan Government local civil service organization\n- Post and grade: the grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Duties: Testimony Surveyor\n**Life.** He grew up on waiting-hall duty. The Testimony Surveyor post opened as a substitute shift covering an unauthorized absence from the rotation.\n- Jo Yejun''s work of public witness confrontations and testimony records is tied to Jongno 1·2·3·4-ga-dong.\n\n**Civil Servant Post and Grade.** The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.\n\n**Anecdote.** In 2125, when the accounts of two witnesses diverged, he opened a public confrontation. Because of this, the signature for the Testimony Surveyor post was entered in the ledger.\n\n**Relations.** Through the handover of the work of public witness confrontations and testimony records, he is linked to the senior duty holder of the same living sphere.\n\n**Ambition.** From the Testimony Surveyor post, he carries on public witness confrontations and testimony records so that the ledger of the Seoul Metropolitan Government local civil service organization is not broken between duty shifts.\n\n**Fear.** That the Testimony Surveyor duty falls vacant, so that the stamps and registers for downtown passage tied to the work of public witness confrontations and testimony records break off, and even the endorsement of the constituent powers of the Seoul Metropolitan Government local civil service organization, which rely on those records, halts.\n\n**Intervention.** He can stand as a witness to the duty handover of the work of public witness confrontations and testimony records, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 30 | Openness −15 | Force −25 | Materialism −30 | Communal 20 | Principle 45 | Publicity −10 | Qualification 15 | Decentralization −25 | Transformation −30\n- Desires: Craving 10 | Exclusivity 30 | Risk −25 | Display 15 | Persistence −20 | Orientation Same-sex | Bonding Polyamorous\n:::","relations":{"outgoing":[{"from":"Jo Yejun","type":"Contract","to":"Cha Se-on","basis":"Jo Ye-jun brings testimony that diverged during the public confrontation to Cha Se-on to compare against the handwriting and testimony collation records. When Jo Ye-jun leaves a witness''s words, Cha Se-on lays the original and the testimony side by side and distinguishes where the words changed from where the documents conflict."}],"incoming":[]}}', '{"id":"person-0429","name":"조예준","title":"증언 탐사원","position":"증언 탐사원","characterId":"K429","rank":"","commonTier":"T3","occupation":"증인 공개 대질·증언 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-조예준","detailRoute":"/people/person-0429","birthDate":"2101-06-30","birthday":"06-30","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k429-witness-confrontation","name":"증인 대질","rating":45}],"traits":[{"id":"k429-choice","name":"다른 말을 나란히","description":"일화. 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","stress":"공포. 증언 탐사원 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k429-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 증언 탐사원 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-51830-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K429","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-51830-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c870-d55c-c591","name":"한양 조씨","crest":"clan-crests/c870-d55c-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":30,"개방":-15,"무력":-25,"물질":-30,"공동":20,"원칙":45,"공개":-10,"자격":15,"분산":-25,"변혁":-30},"desire":{"갈망":10,"독점":30,"위험":-25,"과시":15,"지속":-20,"지향":"동성","결합":"다자"},"fields":{"생업":"증인 공개 대질·증언 기록","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"증언 탐사원","가치관":"권위 30 | 개방 −15 | 무력 −25 | 물질 −30 | 공동 20 | 원칙 45 | 공개 −10 | 자격 15 | 분산 −25 | 변혁 −30","욕망":"갈망 10 | 독점 30 | 위험 −25 | 과시 15 | 지속 −20 | 지향 동성 | 결합 다자"},"sections":{"생애":"대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 조예준의 증인 공개 대질·증언 기록 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.","일화":"2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","관계":"증인 공개 대질·증언 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"증언 탐사원 자리에서 증인 공개 대질·증언 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"증언 탐사원 당직이 비어 증인 공개 대질·증언 기록 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.","개입":"증인 공개 대질·증언 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"증언이 갈릴 때에는 목소리의 크기보다 대질 장부를 믿고 당직을 잇는다.\n\n- 생업: 증인 공개 대질·증언 기록\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 증언 탐사원\n**생애.** 대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 조예준의 증인 공개 대질·증언 기록 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.\n\n**일화.** 2125년 증인 두 명의 말이 갈라지자 공개 대질을 열었다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.\n\n**관계.** 증인 공개 대질·증언 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 증언 탐사원 자리에서 증인 공개 대질·증언 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**공포.** 증언 탐사원 당직이 비어 증인 공개 대질·증언 기록 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.\n\n**개입.** 증인 공개 대질·증언 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 30 | 개방 −15 | 무력 −25 | 물질 −30 | 공동 20 | 원칙 45 | 공개 −10 | 자격 15 | 분산 −25 | 변혁 −30\n- 욕망: 갈망 10 | 독점 30 | 위험 −25 | 과시 15 | 지속 −20 | 지향 동성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"조예준","type":"계약","to":"차세온","basis":"조예준은 공개 대질에서 갈린 증언을 차세온에게 전해 필적·증언 대조 기록과 맞춰 본다. 조예준이 증인의 말을 남기면 차세온은 원본과 증언을 나란히 펼쳐, 말이 달라진 부분과 문서가 어긋난 부분을 구분한다."}],"incoming":[]}}');
