INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0434', 'c624-d574-c8fc', '{"id":"person-0434","name":"O Yunseo","title":"Escort Courier","position":"Gangnam Station Escort Courier","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station Escort Records and Keys Handover","gender":"Male","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0434","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0434","name":"오윤서","title":"호송 전령","position":"강남역 호송 전령","rank":"사원","commonTier":"T5","occupation":"강남역 호송 기록·열쇠 인계","gender":"남성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0434","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0435', 'c11c-b2ec-c131', '{"id":"person-0435","name":"Seo Junseo","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0435","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0435","name":"서준서","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0435","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0436', 'c2e0-c601-c0b0-8f9b', '{"id":"person-0436","name":"Sin Seungmin","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K436","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-sin-seungmin","detailRoute":"/people/person-0436","birthDate":"2095-04-15","birthday":"04-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"Public desk referral","rating":40}],"traits":[{"id":"stated-priority","name":"Requests go to the public desk","description":"A private request was redirected to the public desk; handover stays within existing keys and records. Specific prescribing expertise is not established beyond supervised care.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A private request was redirected to the public desk; handover stays within existing keys and records. Specific prescribing expertise is not established beyond supervised care.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2e0-c601-c0b0-8f9b","name":"Yeongsan Sin Clan","crest":"clan-crests/c2e0-c601-c0b0-8f9b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":25,"Force":-50,"Material":-15,"Communal":30,"Principle":40,"Public":30,"Eligibility":15,"Dispersed":20,"Transformative":-5},"desire":{"Longing":-10,"Monopoly":25,"Risk":5,"Display":-25,"Sustained":0,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −25 | Openness 25 | Force −50 | Materialism −15 | Communal 30 | Principle 40 | Publicity 30 | Qualification 15 | Decentralization 20 | Transformation −5","Desires":"Craving −10 | Exclusivity 25 | Risk 5 | Display −25 | Persistence 0 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Born on 2095-04-15. As of the opening of 2126, he holds the Prescription Clerk duties, continuing the existing duty shifts and records. In the succession record of that post, it opened as a substitute shift covering an unauthorized absence from the rotation.\n- The prescription records and duty-key handover counter in Jegi-dong is Sin Seungmin''s work reference point. This work reference point does not fix a residence, exact facility boundaries, title of nobility, fief, or right of possession.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In 2125, he turned away a private solicitation and sent it to the public counter. That day''s record remained as grounds for handover for the next duty holder to verify.","Relationships":"Sin Seungmin cross-checks prescription records against Jeon Sol''s bed waitlist roster to distinguish requests that came in through private solicitation from the actual treatment order. Requests whose records do not match are verified with Jeon Sol, so that even when medicinal herbs run short, treatment by severity is not pushed aside by solicitation.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first the path that keeps the duty unbroken. He trusts a single line in the ledger more than loud talk.\n\n- Livelihood: prescription records and duty-key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Prescription Clerk\n**Life.** Born on 2095-04-15. As of the opening of 2126, he holds the Prescription Clerk duties, continuing the existing duty shifts and records. In the succession record of that post, it opened as a substitute shift covering an unauthorized absence from the rotation.\n- The prescription records and duty-key handover counter in Jegi-dong is Sin Seungmin''s work reference point. This work reference point does not fix a residence, exact facility boundaries, title of nobility, fief, or right of possession.\n\n**Office.** Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.\n\n**Anecdote.** In 2125, he turned away a private solicitation and sent it to the public counter. That day''s record remained as grounds for handover for the next duty holder to verify.\n\n**Relations.** Sin Seungmin cross-checks prescription records against Jeon Sol''s bed waiting list to distinguish requests that came in as private solicitations from the treatment order. For requests whose records do not match, he confirms with Jeon Sol, so that even when medicinal supplies run short, treatment by severity is not pushed aside by solicitation.\n\n**Ambition.** From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.\n\n**Fear.** He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.\n\n**Intervention.** He can stand as a witness to a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 25 | Force −50 | Materialism −15 | Communal 30 | Principle 40 | Publicity 30 | Qualification 15 | Decentralization 20 | Transformation −5\n- Desires: Craving −10 | Exclusivity 25 | Risk 5 | Display −25 | Persistence 0 | Orientation Fluid | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Sin Seungmin","type":"Contract","to":"Jeon Sol","basis":"Sin Seungmin cross-checks prescription records against Jeon Sol''s bed waitlist roster to distinguish requests that came in through private solicitation from the actual treatment order. Requests whose records do not match are verified with Jeon Sol, so that even when medicinal herbs run short, treatment by severity is not pushed aside by solicitation."}],"incoming":[]}}', '{"id":"person-0436","name":"신승민","title":"처방 서기","position":"처방 서기","characterId":"K436","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-신승민","detailRoute":"/people/person-0436","birthDate":"2095-04-15","birthday":"04-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"창구 안내","rating":40}],"traits":[{"id":"stated-priority","name":"청탁을 공개 창구로","description":"사적 청탁을 공개 창구로 돌렸고 자기 열쇠와 기록만 인계한다. 처방 실력의 개별 근거는 없어 도제 치료 외 숙련을 제한한다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"사적 청탁을 공개 창구로 돌렸고 자기 열쇠와 기록만 인계한다. 처방 실력의 개별 근거는 없어 도제 치료 외 숙련을 제한한다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2e0-c601-c0b0-8f9b","name":"영산 신씨","crest":"clan-crests/c2e0-c601-c0b0-8f9b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":25,"무력":-50,"물질":-15,"공동":30,"원칙":40,"공개":30,"자격":15,"분산":20,"변혁":-5},"desire":{"갈망":-10,"독점":25,"위험":5,"과시":-25,"지속":0,"지향":"유동","결합":"비독점"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −25 | 개방 25 | 무력 −50 | 물질 −15 | 공동 30 | 원칙 40 | 공개 30 | 자격 15 | 분산 20 | 변혁 −5","욕망":"갈망 −10 | 독점 25 | 위험 5 | 과시 −25 | 지속 0 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2095-04-15에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 신승민의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"신승민은 처방 기록을 전솔의 병상 대기 명부와 대조해 사적 청탁으로 들어온 요청과 진료 순서를 구분한다. 기록이 맞지 않는 요청은 전솔에게 확인하여, 약재가 부족한 때에도 중증도에 따른 치료가 청탁에 밀리지 않게 한다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2095-04-15에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 신승민의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 신승민은 처방 기록을 전솔의 병상 대기 명부와 대조해 사적 청탁으로 들어온 요청과 진료 순서를 구분한다. 기록이 맞지 않는 요청은 전솔에게 확인하여, 약재가 부족한 때에도 중증도에 따른 치료가 청탁에 밀리지 않게 한다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 25 | 무력 −50 | 물질 −15 | 공동 30 | 원칙 40 | 공개 30 | 자격 15 | 분산 20 | 변혁 −5\n- 욕망: 갈망 −10 | 독점 25 | 위험 5 | 과시 −25 | 지속 0 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"신승민","type":"계약","to":"전솔","basis":"신승민은 처방 기록을 전솔의 병상 대기 명부와 대조해 사적 청탁으로 들어온 요청과 진료 순서를 구분한다. 기록이 맞지 않는 요청은 전솔에게 확인하여, 약재가 부족한 때에도 중증도에 따른 치료가 청탁에 밀리지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0437', 'ad8c-c548-b3d9', '{"id":"person-0437","name":"Gwon Taeyun","title":"Ridge Patrol","position":"Agwansa Ridge Patrol","rank":"Sergeant","commonTier":"T5","occupation":"Ridge Patrol Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0437","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0437","name":"권태윤","title":"능선 순찰대","position":"아관사 능선 순찰대","rank":"병장","commonTier":"T5","occupation":"능선 순찰 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0437","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
