INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0457', 'cc28-c5f0-c548', '{"id":"person-0457","name":"Cha Yewon","title":"Restoration Service Registrar · Gwanak-gu Lord","position":"Restoration Service Registrar · Gwanak-gu Lord","characterId":"K457","rank":"Lord","commonTier":"T3","occupation":"Registration & Records","gender":"Male","stage":"S4","state":"geography:duchy:11620","stateName":"Gwanak-gu","sourceRoute":"/world/Cast-State-02#inmul-cha-yewon","detailRoute":"/people/person-0457","birthDate":"2098-10-29","birthday":"10-29","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k457-citizenship-register-check","name":"Citizenship-registration crosscheck","rating":60}],"traits":[{"id":"k457-action-priority","name":"Compare names with originals","description":"The Guro Station guild council opens again the citizenship line it took as the ground for Gang Minseo''s chair. Cha Yewon matches, in order against the registry originals, the names that entered that line by refusing restoration-service registration, and signs the end of the copy bound for the council with the signature of the duty.","behavior":"The Guro Station guild council opens again the citizenship line it took as the ground for Gang Minseo''s chair. Cha Yewon matches, in order against the registry originals, the names that entered that line by refusing restoration-service registration, and signs the end of the copy bound for the council with the signature of the duty.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k457-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The Guro Station guild council opens again the citizenship line it took as the ground for Gang Minseo''s chair. Cha Yewon matches, in order against the registry originals, the names that entered that line by refusing restoration-service registration, and signs the end of the copy bound for the council with the signature of the duty. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:opening-duchy-gu-11620-S02","name":{"ko":"Gwanak-gu Ducal Directly Held Territory"},"holderPersonId":"K457","directLiegePersonId":"K029","stateId":"S02","adminRefs":[{"id":"region:1162052500","name":"Boramae-dong"},{"id":"region:1162054500","name":"Cheongnim-dong"},{"id":"region:1162056500","name":"Seonghyeon-dong"},{"id":"region:1162057500","name":"Haengun-dong"},{"id":"region:1162058500","name":"Nakseongdae-dong"},{"id":"region:1162059500","name":"Cheongnyong-dong"},{"id":"region:1162060500","name":"Euncheon-dong"},{"id":"region:1162061500","name":"Jungang-dong"},{"id":"region:1162062500","name":"Inheon-dong"},{"id":"region:1162063000","name":"Namhyeon-dong"},{"id":"region:1162064500","name":"Seowon-dong"},{"id":"region:1162065500","name":"Sinwon-dong"},{"id":"region:1162066500","name":"Seorim-dong"},{"id":"region:1162068500","name":"Sinsa-dong"},{"id":"region:1162069500","name":"Sillim-dong"},{"id":"region:1162071500","name":"Nanhyang-dong"},{"id":"region:1162072500","name":"Jowon-dong"},{"id":"region:1162073500","name":"Daehak-dong"},{"id":"region:1162074500","name":"Samseong-dong"},{"id":"region:1162076500","name":"Miseong-dong"},{"id":"region:1162077500","name":"Nangok-dong"}],"componentRefs":[],"titleId":"title:duchy-gu-11620-S02","geometrySource":null,"territorialScale":null,"formalTitleRank":"duchy"}],"subordinateHoldings":[],"openingTitles":[{"id":"title:duchy-gu-11620-S02","name":"Gwanak-gu Duchy","rank":"duchy","holderPersonId":"K457","basis":"Opening administrative-scale group gu:11620(duchy) allocation · decisive candidate selection","stateId":"S02","parentTitleId":"title:kingdom-s02","jurisdictionRefs":["region:1162052500","region:1162054500","region:1162056500","region:1162057500","region:1162058500","region:1162059500","region:1162060500","region:1162061500","region:1162062500","region:1162063000","region:1162064500","region:1162065500","region:1162066500","region:1162068500","region:1162069500","region:1162071500","region:1162072500","region:1162073500","region:1162074500","region:1162076500","region:1162077500"],"parentTitle":{"id":"title:kingdom-s02","name":"Standards League Kingdom","holderPersonId":"K029"}}],"clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":15,"Force":-10,"Material":35,"Communal":30,"Principle":20,"Public":45,"Eligibility":50,"Dispersed":30,"Transformative":25},"desire":{"Longing":-20,"Monopoly":-30,"Risk":30,"Display":-45,"Sustained":20,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Standards League","Livelihood":"Registration & Records","Rank":"Guild Member","Title":"Restoration Service Recorder","Work Location":"Guro 2-dong. Cha Yewon searches the Guro 2-dong restoration service originals, one by one, for the names on the citizenship list of those who refused registration. On the copy bound for the council, Cha Yewon puts the signature of their own duty and separately marks the names missing from Kim Nayul''s shift board.","Values":"Authority −20 | Openness 15 | Force −10 | Material 35 | Communal 30 | Principle 20 | Publicity 45 | Credentials 50 | Dispersion 30 | Transformation 25","Desires":"Craving −20 | Monopoly −30 | Risk 30 | Display −45 | Persistence 20 | Orientation bisexual | Bonding contract cohabitation"},"sections":{"Life":"Generation of 2126. Grew up at the Seoul Station registry office. The Restoration Service Records Officer post opened through the deletion of a single line from the double ledger.\n- Work location: Guro 2-dong. Cha Yewon searches the Guro 2-dong restoration service originals, one by one, for the names on the citizenship list of those who refused registration. On the copy bound for the council, Cha Yewon puts the signature of their own duty and separately marks the names missing from Kim Nayul''s shift board.","Offices":"Rank: Guild Member. Title: Restoration Service Records Officer. On the copy bound for the council, puts the signature of their own duty and separately marks the names missing from Kim Nayul''s shift board.","Anecdote":"The Guro Station Guild Council reopens the citizenship rolls it used as the basis for Gang Minseo''s seat as chair. Cha Yewon matches, one by one, the names on those rolls of people who refused restoration service registration against the registry originals, and signs the end of the copy bound for the council with the signature of their own duty.","Relationships":"Cha Yewon hands Gim Nayul a copy of the restoration-service workers'' citizenship lines, matched against the original registry. Gim Nayul checks the actual shift and registration records and separates the labor records to be put on the Council agenda from the military household register copy the Guard Corps demands.","Ambition":"Cha Yewon matches the citizenship rolls of those who refused registration against the registry originals, and intends to leave the signature of their own duty on the copy marking the omitted names.","Fear":"That the citizenship copy will be mixed with the military household register demand and Kim Nayul''s shift records will be misused.","Intervention":"The player can cross-check Cha Yewon''s citizenship copy against the registry original, or mark names missing from Kim Nayul''s shift chalkboard."},"biography":"Cha Yewon marks omissions in the citizenship copy without mixing military household register demands with labor shifts.\n\n- Affiliation: Standards League\n- Occupation: Registry and records\n- Rank: Guild Member\n- Title: Restoration Service Recorder\n**Life.** Born in the 2126 generation. Grew up at the Seoul Station registry office. The post of Restoration Service Recorder opened after a line was struck from a double ledger.\n- Workplace: Guro 2-dong. In the Guro 2-dong Restoration Service original, Cha Yewon looks up in order the names on the citizenship list who refused registration. On the copy bound for the Council, she adds her own duty signature and separately marks names missing from Kim Nayul''s shift chalkboard.\n\n**Office.** Rank: Guild Member. Title: Restoration Service Recorder. On the copy bound for the Council, she adds her own duty signature and separately marks names missing from Kim Nayul''s shift chalkboard.\n\n**Anecdote.** She reopens the citizenship line that the Guro Station Guild Council used as grounds for Gang Minseo''s seat as chair. Cha Yewon checks the names on that line, entered because they refused Restoration Service registration, one by one against the registry original, and adds her own duty signature at the end of the copy bound for the Council.\n\n**Relationships.** Cha Yewon hands Kim Nayul the copy of the Restoration Service citizenship line she has checked against the registry original. Kim Nayul verifies the actual shift and registration records and distinguishes the labor records to be placed on the Council agenda from the military household register copy that the guard corps demands.\n\n**Ambition.** Cha Yewon wants to check the citizenship line of those who refused registration against the registry original, and to leave her own duty signature on the copy that marks the omitted names.\n\n**Fear.** That the citizenship copy will be mixed with military household register demands and Kim Nayul''s shift records will be misused.\n\n**Intervention.** The player can cross-check Cha Yewon''s citizenship copy against the registry original, or mark names missing from Kim Nayul''s shift chalkboard.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −20 | Openness 15 | Force −10 | Material 35 | Communal 30 | Principle 20 | Publicity 45 | Qualification 50 | Dispersal 30 | Transformation 25\n- Desires: Craving −20 | Monopoly −30 | Risk 30 | Display −45 | Persistence 20 | Orientation Bisexual | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Cha Yewon","type":"Contract","to":"Kim Nayul","basis":"Cha Yewon hands Gim Nayul a copy of the restoration-service workers'' citizenship lines, matched against the original registry. Gim Nayul checks the actual shift and registration records and separates the labor records to be put on the Council agenda from the military household register copy the Guard Corps demands."}],"incoming":[]}}', '{"id":"person-0457","name":"차예원","title":"복구복무 기록관 · 관악구 영주","position":"복구복무 기록관 · 관악구 영주","characterId":"K457","rank":"영주","commonTier":"T3","occupation":"등기·기록","gender":"남성","stage":"S4","state":"geography:duchy:11620","stateName":"관악구","sourceRoute":"/world/Cast-State-02#인물-차예원","detailRoute":"/people/person-0457","birthDate":"2098-10-29","birthday":"10-29","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k457-citizenship-register-check","name":"시민권 등기 대조","rating":60}],"traits":[{"id":"k457-action-priority","name":"원본과 이름 대조","description":"구로역 길드 평의회가 강민서의 위원장 자리 근거로 삼은 시민권 줄을 다시 펼친다. 차예원은 복구복무자 등록을 거부해 그 줄에 오른 이름을 등기 원본과 차례로 맞추고, 평의회로 보낼 사본 끝에 자기 당직의 서명을 단다.","behavior":"구로역 길드 평의회가 강민서의 위원장 자리 근거로 삼은 시민권 줄을 다시 펼친다. 차예원은 복구복무자 등록을 거부해 그 줄에 오른 이름을 등기 원본과 차례로 맞추고, 평의회로 보낼 사본 끝에 자기 당직의 서명을 단다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k457-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"구로역 길드 평의회가 강민서의 위원장 자리 근거로 삼은 시민권 줄을 다시 펼친다. 차예원은 복구복무자 등록을 거부해 그 줄에 오른 이름을 등기 원본과 차례로 맞추고, 평의회로 보낼 사본 끝에 자기 당직의 서명을 단다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:opening-duchy-gu-11620-S02","name":{"ko":"관악구 공작령 직영지"}