INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0464', 'c774-c5f0-c548-674e', '{"id":"person-0464","name":"I Jimin","title":"Antenna Technician","position":"Vault Technician","rank":"Clerk","commonTier":"T5","occupation":"Vault Equipment Inspection & Maintenance","gender":"Male","stage":"S4","state":"S09","stateName":"Yeouido Investors'' Association","detailRoute":"/people/person-0464","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0464","name":"이지민","title":"안테나 정비사","position":"금고 정비사","rank":"서기","commonTier":"T5","occupation":"금고 설비 점검·정비","gender":"남성","stage":"S4","state":"S09","stateName":"여의도출자연합회","detailRoute":"/people/person-0464","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}');
