INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0492', 'c2ec-ccad-c1a1', '{"id":"person-0492","name":"Sim Byeolhyeon","title":"Water Supply Herald","position":"Water Supply Herald","rank":"Sergeant","commonTier":"T5","occupation":"Reservoir Release and Ration Adjustment","gender":"Female","stage":"S4","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0492","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0492","name":"심별현","title":"급수 전령","position":"급수 전령","rank":"병장","commonTier":"T5","occupation":"저수지 방류·배급량 조정","gender":"여성","stage":"S4","state":"S05","stateName":"동방사","detailRoute":"/people/person-0492","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0493', 'b178-d568-d3c9-9b6f', '{"id":"person-0493","name":"No Jua","title":"Copy Herald","position":"Copy Herald","characterId":"K493","rank":"","commonTier":"T3","occupation":"Train Schedule and Departure Signature Verification","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#person-no-jua","detailRoute":"/people/person-0493","birthDate":"2071-10-30","birthday":"10-30","age":55,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k493-departure-check","name":"Departure signature checking","rating":50}],"traits":[{"id":"k493-choice","name":"Rejects unsigned departure","description":"Anecdote. In 2125 he stopped a dispatch-sheetless train and blocked an unsigned departure. By this deed the signature of the copy courier post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125 he stopped a dispatch-sheetless train and blocked an unsigned departure. By this deed the signature of the copy courier post rose into the ledger.","stress":"Fear. That the copy courier duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k493-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the copy courier duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. The actual response is not yet recorded.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125 he stopped a dispatch-sheetless train and blocked an unsigned departure. By this deed the signature of the copy courier post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28155-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K493","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28155-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"b178-d568-d3c9-9b6f","name":"Hampyeong No Clan","crest":"clan-crests/b178-d568-d3c9-9b6f.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":-5,"Force":-30,"Material":-30,"Communal":10,"Principle":50,"Public":0,"Eligibility":20,"Dispersed":-40,"Transformative":-35},"desire":{"Longing":10,"Monopoly":-5,"Risk":10,"Display":20,"Sustained":-15,"Orientation":"None","Union":"Monogamy"},"fields":{"Livelihood":"Train Schedule and Departure Signature Verification","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Copy Herald","Values":"Authority 15 | Openness −5 | Force −30 | Materialism −30 | Community 10 | Principle 50 | Publicity 0 | Qualification 20 | Dispersion −40 | Transformation −35","Desires":"Craving 10 | Possessiveness −5 | Risk 10 | Display 20 | Persistence −15 | Orientation None | Union Monogamous"},"sections":{"Life":"Grew up on the Sinnae transfer watch. The Copy Courier post opened up through stopping a train departing without a ticket.\n- No Jua''s work of checking train dispatch sheets and departure signatures is tied to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.","Anecdote":"In 2125, she stopped a train without a dispatch sheet and prevented an unsigned departure. Because of this, the signature of the Copy Courier post was entered in the ledger.","Relationships":"Through the handover of the work of checking train dispatch sheets and departure signatures, she is connected to the senior watch of the same community.","Ambition":"From the Copy Courier post, to continue the records of checking train dispatch sheets and departure signatures so that the ledger of the Seoul Metropolitan Government Local Civil Service is not broken between watches.","Fear":"That the Copy Courier watch will fall vacant, so that the seals and rosters of downtown passage tied to the work of checking train dispatch sheets and departure signatures are cut off, and even the ratification of the Seoul Metropolitan Government Local Civil Service''s constituent forces, which rely on those records, comes to a halt.","Intervention":"She can appoint a witness to the watch handover for the work of checking train dispatch sheets and departure signatures, or expose the empty key of that post."},"biography":"She trusts the dispatch sheet and the signature before any voice urging a train to depart. She links the watches so that the signatures are not broken.\n\n- Occupation: Checking train dispatch sheets and departure signatures\n- Affiliation: Seoul Metropolitan Government Local Civil Service\n- Post and Grade: Whichever grade among Local Administrative Officer (Grade 5), Local Senior Administrative Clerk (Grade 6), Local Assistant Senior Administrative Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Assistant Administrative Clerk (Grade 9) fits a post at the Seoul Metropolitan Government headquarters or a field office\n- Duties: Copy Courier\n**Life.** Grew up on the Sinnae transfer watch. The Copy Courier post opened up through stopping a train departing without a ticket.\n- No Jua''s work of checking train dispatch sheets and departure signatures is tied to Jongno 1·2·3·4-ga-dong.\n\n**Civil Service Post and Grade.** Whichever grade among Local Administrative Officer (Grade 5), Local Senior Administrative Clerk (Grade 6), Local Assistant Senior Administrative Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Assistant Administrative Clerk (Grade 9) fits a post at the Seoul Metropolitan Government headquarters or a field office. Duties: Copy Courier.\n\n**Anecdote.** In 2125, she stopped a train without a dispatch sheet and prevented an unsigned departure. Because of this, the signature of the Copy Courier post was entered in the ledger.\n\n**Relations.** Through the handover of the work of checking train dispatch sheets and departure signatures, she is connected to the senior watch of the same community.\n\n**Ambition.** From the Copy Courier post, to continue the records of checking train dispatch sheets and departure signatures so that the ledger of the Seoul Metropolitan Government Local Civil Service is not broken between watches.\n\n**Fear.** That the Copy Courier watch will fall vacant, so that the seals and rosters of downtown passage tied to the work of checking train dispatch sheets and departure signatures are cut off, and even the ratification of the Seoul Metropolitan Government Local Civil Service''s constituent forces, which rely on those records, comes to a halt.\n\n**Intervention.** She can appoint a witness to the watch handover for the work of checking train dispatch sheets and departure signatures, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness −5 | Force −30 | Materialism −30 | Community 10 | Principle 50 | Publicity 0 | Qualification 20 | Dispersion −40 | Transformation −35\n- Desires: Craving 10 | Possessiveness −5 | Risk 10 | Display 20 | Persistence −15 | Orientation None | Union Monogamous\n:::","relations":{"outgoing":[{"from":"No Jua","type":"Contract","to":"Seop Do-yun","basis":"When No Jua finds a train missing its dispatch schedule or departure signature, she hands the copy to Seop Doyun. Seop Doyun delivers the omission to the Records Office and the council hall together, so that an unsigned departure is not mixed into the official messages on the strength of one side''s verbal confirmation alone."}],"incoming":[]}}', '{"id":"person-0493","name":"노주아","title":"사본 전령","position":"사본 전령","characterId":"K493","rank":"","commonTier":"T3","occupation":"열차 배차표·출발 서명 확인","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-노주아","detailRoute":"/people/person-0493","birthDate":"2071-10-30","birthday":"10-30","age":55,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k493-departure-check","name":"출발 서명 확인","rating":50}],"traits":[{"id":"k493-choice","name":"서명 없는 출발 거부","description":"일화. 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","stress":"공포. 사본 전령 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k493-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 사본 전령 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28155-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K493","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28155-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"b178-d568-d3c9-9b6f","name":"함평 노씨","crest":"clan-crests/b178-d568-d3c9-9b6f.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":-5,"무력":-30,"물질":-30,"공동":10,"원칙":50,"공개":0,"자격":20,"분산":-40,"변혁":-35},"desire":{"갈망":10,"독점":-5,"위험":10,"과시":20,"지속":-15,"지향":"무성향","결합":"단혼"},"fields":{"생업":"열차 배차표·출발 서명 확인","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"사본 전령","가치관":"권위 15 | 개방 −5 | 무력 −30 | 물질 −30 | 공동 10 | 원칙 50 | 공개 0 | 자격 20 | 분산 −40 | 변혁 −35","욕망":"갈망 10 | 독점 −5 | 위험 10 | 과시 20 | 지속 −15 | 지향 무성향 | 결합 단혼"},"sections":{"생애":"신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 노주아의 열차 배차표·출발 서명 확인 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.","일화":"2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","관계":"열차 배차표·출발 서명 확인 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"사본 전령 자리에서 열차 배차표·출발 서명 확인 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"사본 전령 당직이 비어 열차 배차표·출발 서명 확인 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.","개입":"열차 배차표·출발 서명 확인 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"열차의 출발을 재촉하는 소리보다 배차표와 서명을 먼저 믿는다. 서명이 끊기지 않도록 당직을 잇는다.\n\n- 생업: 열차 배차표·출발 서명 확인\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 사본 전령\n**생애.** 신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 노주아의 열차 배차표·출발 서명 확인 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.\n\n**일화.** 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 열차 배차표·출발 서명 확인 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 사본 전령 자리에서 열차 배차표·출발 서명 확인 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**공포.** 사본 전령 당직이 비어 열차 배차표·출발 서명 확인 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.\n\n**개입.** 열차 배차표·출발 서명 확인 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 −5 | 무력 −30 | 물질 −30 | 공동 10 | 원칙 50 | 공개 0 | 자격 20 | 분산 −40 | 변혁 −35\n- 욕망: 갈망 10 | 독점 −5 | 위험 10 | 과시 20 | 지속 −15 | 지향 무성향 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"노주아","type":"계약","to":"섭도윤","basis":"노주아는 배차표나 출발 서명이 빠진 열차를 발견하면 그 사본을 섭도윤에게 넘긴다. 섭도윤은 누락 내용을 기록청과 회의장에 함께 전달해, 한쪽의 구두 확인만으로 서명 없는 출발이 정식 전갈에 섞이지 않게 한다."}],"incoming":[]}}');
