INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0498', 'c8fc-c2e0-c548', '{"id":"person-0498","name":"Ju Rain","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Male","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0498","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0498","name":"주라인","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"사원","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"남성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0498","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0499', 'c6b0-b2e8-c591', '{"id":"person-0499","name":"U Hajin","title":"Medical Escort Recorder","position":"Medical Escort Recorder","characterId":"K499","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-12#person-u-hajin","detailRoute":"/people/person-0499","birthDate":"2066-08-11","birthday":"08-11","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k499-medical-escort-dispatch-reconciliation","name":"Medical escort dispatch reconciliation","rating":50}],"traits":[{"id":"k499-priority","name":"Records displaced services","description":"U Hajin matched new dispatch times individually and handed over displaced medical services separately. Reconciliation grants no operating command.","behavior":"Office. Rank: convoy hand. Title: medical convoy registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the medical convoy registrar duty post would stand empty and the City''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k499-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: convoy hand. Title: medical convoy registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the medical convoy registrar duty post would stand empty and the City''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"U Hajin matched new dispatch times individually and handed over displaced medical services separately. Reconciliation grants no operating command.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":45,"Force":-40,"Material":-10,"Communal":20,"Principle":25,"Public":20,"Eligibility":15,"Dispersed":30,"Transformative":5},"desire":{"Longing":35,"Monopoly":-5,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Livelihood":"Medical Escort Log and Duty Key Handover","Affiliation":"The Government","Rank":"Escort","Title":"Medical Escort Recorder","Values":"Authority −15 | Openness 45 | Force −40 | Materialism −10 | Community 20 | Principle 25 | Publicity 20 | Qualification 15 | Decentralization 30 | Reform 5","Desires":"Craving 35 | Monopoly −5 | Risk −10 | Display 0 | Persistence 15 | Orientation Opposite sex | Union Monogamy"},"sections":{"Life":"Born 2066-08-11. Grew up at the Seoul Station Registry Office. At the 2126 opening, holds the Medical Escort Records Officer duty post; the post''s handover record preserves the line \"opened with the deletion of one line from a double ledger.\"\n- The dispatch, shift, maintenance, passage screening, stretcher handover and duty-key record desk in Sinnae 1-dong is proposed as U Hajin''s reference point for medical escort records and duty-key handover work. It is a proposal to reconcile handover records in the Permanent Winter, and it does not confirm operating trains, new facilities, weapons, passage tolls, market monopolies, residence, exact facility boundaries, noble titles, fiefs, or possession rights.","Offices":"Rank: Escort. Title: Medical Escort Records Officer. Hands over the medical escort times on the seasonal dispatch table together with the keys and records of one''s own duty post, making the scope of the handover clear.","Anecdote":"The seasons change, and the medical train running times that Jang Sehwa wrote out in divided form pass over to the new dispatch table. U Hajin matches the departure times in the medical escort records against the medical train columns of the new dispatch table one by one, separately notes the medical escort runs that were pushed into the general train columns, and hands them over together with the duty key. The medical escort times on the seasonal dispatch table left behind then became the handover standard for the next duty officer.","Relationships":"Hands the medical escort times on the seasonal dispatch table to a senior duty officer of the same living sphere, and cross-checks them against the next shift''s receipt time in the same duty sphere.","Ambition":"Seeks to leave the medical escort times on the seasonal dispatch table as a public handover line that the next shift can check again.","Fear":"Fears that if the receipt time for the medical escort times on the seasonal dispatch table is left blank, responsibility will be shoved onto the patient and passenger lists.","Intervention":"Can set up a handover witness for the medical escort times on the seasonal dispatch table, or make public any missing signature box before the next shift."},"biography":"U Hajin, born 2066-08-11, first checks the order of the medical escort times on the seasonal dispatch table. Trusts handover times and signature boxes rather than loud voices.\n\n- Livelihood: Medical escort records and duty-key handover\n- Affiliation: The Government\n- Rank: Escort\n- Title: Medical Escort Records Officer\n**Life.** Born 2066-08-11. Grew up at the Seoul Station Registry Office. At the 2126 opening, holds the Medical Escort Records Officer duty post; the post''s handover record preserves the line \"opened with the deletion of one line from a double ledger.\"\n- The dispatch, shift, maintenance, passage screening, stretcher handover and duty-key record desk in Sinnae 1-dong is proposed as U Hajin''s reference point for medical escort records and duty-key handover work. It is a proposal to reconcile handover records in the Permanent Winter, and it does not confirm operating trains, new facilities, weapons, passage tolls, market monopolies, residence, exact facility boundaries, noble titles, fiefs, or possession rights.\n\n**Office.** Rank: Escort. Title: Medical Escort Records Officer. Hands over the medical escort times on the seasonal dispatch table together with the keys and records of one''s own duty post, making the scope of the handover clear.\n\n**Anecdote.** The seasons change, and the medical train running times that Jang Sehwa wrote out in divided form pass over to the new dispatch table. U Hajin matches the departure times in the medical escort records against the medical train columns of the new dispatch table one by one, separately notes the medical escort runs that were pushed into the general train columns, and hands them over together with the duty key. The medical escort times on the seasonal dispatch table left behind then became the handover standard for the next duty officer.\n\n**Relations.** Hands the medical escort times on the seasonal dispatch table to a senior duty officer of the same living sphere, and cross-checks them against the next shift''s receipt time in the same duty sphere.\n\n**Ambition.** Seeks to leave the medical escort times on the seasonal dispatch table as a public handover line that the next shift can check again.\n\n**Fear.** Fears that if the receipt time for the medical escort times on the seasonal dispatch table is left blank, responsibility will be shoved onto the patient and passenger lists.\n\n**Intervention.** Can set up a handover witness for the medical escort times on the seasonal dispatch table, or make public any missing signature box before the next shift.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 45 | Force −40 | Materialism −10 | Community 20 | Principle 25 | Publicity 20 | Qualification 15 | Decentralization 30 | Reform 5\n- Desires: Craving 35 | Monopoly −5 | Risk −10 | Display 0 | Persistence 15 | Orientation Opposite sex | Union Monogamy\n:::","relations":{"outgoing":[{"from":"U Hajin","type":"Contract","to":"Jeon Miri","basis":"U Hajin separately records the medical escort runs that were pushed out of the seasonal schedule into ordinary train cars and passes them to Jeon Miri. Jeon Miri checks patient severity and transfer times and reflects them in the Medical Team duty room, so that stretcher order is not erased just because the schedule changed."}],"incoming":[]}}', '{"id":"person-0499","name":"우하진","title":"의무호송 기록관","position":"의무호송 기록관","characterId":"K499","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-12#인물-우하진","detailRoute":"/people/person-0499","birthDate":"2066-08-11","birthday":"08-11","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k499-medical-escort-dispatch-reconciliation","name":"의무호송 배차 대조","rating":50}],"traits":[{"id":"k499-priority","name":"밀려난 편을 남김","description":"우하진은 새 배차표와 의무호송 출발을 하나씩 맞추고 일반 칸으로 밀려난 편을 따로 넘겼다. 기록 대조가 운행 지휘권은 아니다.","behavior":"자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"의무호송 기록관 당직이 비면 신내운수의 통행이 노선 면허의 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k499-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 호송원. 직함은 의무호송 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 의무호송 기록관 당직이 비면 신내운수의 통행이 노선 면허의 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"우하진은 새 배차표와 의무호송 출발을 하나씩 맞추고 일반 칸으로 밀려난 편을 따로 넘겼다. 기록 대조가 운행 지휘권은 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c6b0-b2e8-c591","name":"단양 우씨","crest":"clan-crests/c6b0-b2e8-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":45,"무력":-40,"물질":-10,"공동":20,"원칙":25,"공개":20,"자격":15,"분산":30,"변혁":5},"desire":{"갈망":35,"독점":-5,"위험":-10,"과시":0,"지속":15,"지향":"이성","결합":"단혼"},"fields":{"생업":"의무호송 기록·당직 열쇠 인계","소속":"정부","품계":"호송원","직함":"의무호송 기록관","가치관":"권위 −15 | 개방 45 | 무력 −40 | 물질 −10 | 공동 20 | 원칙 25 | 공개 20 | 자격 15 | 분산 30 | 변혁 5","욕망":"갈망 35 | 독점 −5 | 위험 −10 | 과시 0 | 지속 15 | 지향 이성 | 결합 단혼"},"sections":{"생애":"2066-08-11에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 우하진의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 영구 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·작위·영지·점유권은 확정하지 않는다.","관직":"품계 호송원. 직함은 의무호송 기록관. 계절 배차표의 의무호송 시각과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.","일화":"계절이 바뀌어, 장세화가 나눠 적은 의료열차 운행 시간이 새 배차표로 넘어간다. 우하진은 의무호송 기록의 출발 시각을 새 배차표의 의료열차 칸과 하나씩 맞추고, 일반 열차 칸으로 밀려난 의무호송 편을 따로 적어 당직 열쇠와 함께 넘긴다. 그때 남긴 계절 배차표의 의무호송 시각이 다음 당직의 인수 기준이 되었다.","관계":"같은 생활권 선배 당직에게 계절 배차표의 의무호송 시각을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.","야망":"계절 배차표의 의무호송 시각을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.","공포":"계절 배차표의 의무호송 시각의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.","개입":"계절 배차표의 의무호송 시각의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다."},"biography":"2066-08-11생인 우하진은 계절 배차표의 의무호송 시각의 순서를 먼저 확인한다. 큰소리보다 인수 시각과 서명 칸을 믿는다.\n\n- 생업: 의무호송 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 호송원\n- 직함: 의무호송 기록관\n**생애.** 2066-08-11에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 우하진의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 영구 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·작위·영지·점유권은 확정하지 않는다.\n\n**관직.** 품계 호송원. 직함은 의무호송 기록관. 계절 배차표의 의무호송 시각과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.\n\n**일화.** 계절이 바뀌어, 장세화가 나눠 적은 의료열차 운행 시간이 새 배차표로 넘어간다. 우하진은 의무호송 기록의 출발 시각을 새 배차표의 의료열차 칸과 하나씩 맞추고, 일반 열차 칸으로 밀려난 의무호송 편을 따로 적어 당직 열쇠와 함께 넘긴다. 그때 남긴 계절 배차표의 의무호송 시각이 다음 당직의 인수 기준이 되었다.\n\n**관계.** 같은 생활권 선배 당직에게 계절 배차표의 의무호송 시각을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.\n\n**야망.** 계절 배차표의 의무호송 시각을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.\n\n**공포.** 계절 배차표의 의무호송 시각의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.\n\n**개입.** 계절 배차표의 의무호송 시각의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 45 | 무력 −40 | 물질 −10 | 공동 20 | 원칙 25 | 공개 20 | 자격 15 | 분산 30 | 변혁 5\n- 욕망: 갈망 35 | 독점 −5 | 위험 −10 | 과시 0 | 지속 15 | 지향 이성 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"우하진","type":"계약","to":"전미리","basis":"우하진은 계절 배차표에서 일반 열차 칸으로 밀려난 의무호송 편을 따로 적어 전미리에게 전한다. 전미리는 환자 중증도와 이송 시각을 확인하고 의료조 당직실에 반영해, 배차표가 바뀌었다고 들것 순서가 지워지지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0500', 'ad6c-b2a5-c131', '{"id":"person-0500","name":"Gu Sohui","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K500","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-gu-sohui","detailRoute":"/people/person-0500","birthDate":"2070-09-14","birthday":"09-14","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"Original document custody","rating":40}],"traits":[{"id":"stated-priority","name":"Keeps the original compartment","description":"After a forged seal was exposed, copies were burned and the original compartment guarded. Personal discovery of the forgery or sanitation command is not assumed.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"After a forged seal was exposed, copies were burned and the original compartment guarded. Personal discovery of the forgery or sanitation command is not assumed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":40,"Force":-60,"Material":-10,"Communal":30,"Principle":60,"Public":30,"Eligibility":25,"Dispersed":25,"Transformative":-15},"desire":{"Longing":20,"Monopoly":35,"Risk":-30,"Display":-15,"Sustained":30,"Orientation":"None","Union":"None"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −15 | Openness 40 | Force −60 | Materialism −10 | Community 30 | Principle 60 | Publicity 30 | Qualification 25 | Decentralization 25 | Reform −15","Desires":"Craving 20 | Monopoly 35 | Risk −30 | Display −15 | Persistence 30 | Orientation None | Union None"},"sections":{"Life":"Born 2070-09-14. As of the 2126 opening, holds the Quarantine Records Officer duties, continuing the existing duty and records. The succession record for that post opens with the deletion of one line from a double ledger.\n- The quarantine records and duty-key handover desk in Jegi-dong is Gu Sohui''s work reference point. This work reference point does not confirm residence, exact facility boundaries, noble titles, fiefs, or possession rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.","Relationships":"Gu Sohui brings the original quarantine records and the entry seal to Ra Seyeong to check a suspicious copy. Ra Seyeong examines the quarantine entry and release records to confirm whether a forged seal got through, and does not declare a release before the water-quality and medicinal-efficacy records arrive.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty chain. Trusts a single ledger line rather than loud voices.\n\n- Livelihood: Quarantine records and duty-key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Quarantine Records Officer\n**Life.** Born 2070-09-14. As of the 2126 opening, holds the Quarantine Records Officer duties, continuing the existing duty and records. The succession record for that post opens with the deletion of one line from a double ledger.\n- The quarantine records and duty-key handover desk in Jegi-dong is Gu Sohui''s work reference point. This work reference point does not confirm residence, exact facility boundaries, noble titles, fiefs, or possession rights.\n\n**Office.** Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of one''s own post, and writes the receipt time of the handed-over keys and records in the ledger.\n\n**Anecdote.** In 2125, a forged seal was caught; the copies were burned and the original box was guarded. That day''s record remained as the handover basis for the next duty officer to check.\n\n**Relations.** Gu Sohui takes the original quarantine records and the entry seal to Ra Seyeong to check the suspicious copies. Ra Seyeong examines the isolation entry and release records to confirm whether a forged stamp got through, and does not declare a release before the water quality and drug efficacy records arrive.\n\n**Ambition.** To keep the White Cross Order''s ledger unbroken from the position of Quarantine Resident.\n\n**Fear.** Fears that if the Quarantine Resident''s duty post sits vacant, the White Cross Order''s passage will become hostage to Seoul''s internal backer faction.\n\n**Intervention.** Can set up a handover witness for the duty post or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 40 | Force −60 | Materialism −10 | Community 30 | Principle 60 | Publicity 30 | Qualification 25 | Decentralization 25 | Reform −15\n- Desires: Craving 20 | Monopoly 35 | Risk −30 | Display −15 | Persistence 30 | Orientation None | Union None\n:::","relations":{"outgoing":[{"from":"Gu Sohui","type":"Contract","to":"Ra Seyeong","basis":"Gu Sohui brings the original quarantine records and the entry seal to Ra Seyeong to check a suspicious copy. Ra Seyeong examines the quarantine entry and release records to confirm whether a forged seal got through, and does not declare a release before the water-quality and medicinal-efficacy records arrive."}],"incoming":[]}}', '{"id":"person-0500","name":"구소희","title":"방역 기록관","position":"방역 기록관","characterId":"K500","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-구소희","detailRoute":"/people/person-0500","birthDate":"2070-09-14","birthday":"09-14","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"original-document-custody","name":"원본 보관","rating":40}],"traits":[{"id":"stated-priority","name":"원본 칸을 지킨다","description":"위조 도장이 드러난 뒤 사본을 불사르고 원본 칸을 지켰다. 위조를 직접 발견했다거나 방역을 지휘했다고 단정하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"위조 도장이 드러난 뒤 사본을 불사르고 원본 칸을 지켰다. 위조를 직접 발견했다거나 방역을 지휘했다고 단정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"능성 구씨","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":40,"무력":-60,"물질":-10,"공동":30,"원칙":60,"공개":30,"자격":25,"분산":25,"변혁":-15},"desire":{"갈망":20,"독점":35,"위험":-30,"과시":-15,"지속":30,"지향":"무성향","결합":"없음"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −15 | 개방 40 | 무력 −60 | 물질 −10 | 공동 30 | 원칙 60 | 공개 30 | 자격 25 | 분산 25 | 변혁 −15","욕망":"갈망 20 | 독점 35 | 위험 −30 | 과시 −15 | 지속 30 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2070-09-14에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 구소희의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"구소희는 방역 기록의 원본과 출입 도장을 라세영에게 가져가 의심스러운 사본을 확인한다. 라세영은 격리 출입과 해제 기록을 살펴 위조 날인이 통과했는지 확인하고, 수질·약효 기록이 도착하기 전에는 해제를 선언하지 않는다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2070-09-14에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 구소희의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 위조 도장을 들켜 사본을 불사르고 원본 칸을 지켰다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 구소희는 방역 기록의 원본과 출입 도장을 라세영에게 가져가 의심스러운 사본을 확인한다. 라세영은 격리 출입과 해제 기록을 살펴 위조 날인이 통과했는지 확인하고, 수질·약효 기록이 도착하기 전에는 해제를 선언하지 않는다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 40 | 무력 −60 | 물질 −10 | 공동 30 | 원칙 60 | 공개 30 | 자격 25 | 분산 25 | 변혁 −15\n- 욕망: 갈망 20 | 독점 35 | 위험 −30 | 과시 −15 | 지속 30 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"구소희","type":"계약","to":"라세영","basis":"구소희는 방역 기록의 원본과 출입 도장을 라세영에게 가져가 의심스러운 사본을 확인한다. 라세영은 격리 출입과 해제 기록을 살펴 위조 날인이 통과했는지 확인하고, 수질·약효 기록이 도착하기 전에는 해제를 선언하지 않는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0501', 'bbfc-c5ec-d765-9594', '{"id":"person-0501","name":"Min Pahyeon","title":"Quarantine Clerk","position":"Guui Garrison Quarantine Clerk","rank":"Garrison Soldier","commonTier":"T5","occupation":"Quarantine Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0501","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0501","name":"민파현","title":"검역 서기","position":"구의수비대 검역 서기","rank":"수비대원","commonTier":"T5","occupation":"검역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0501","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0502', 'c9c4-d48d-ae30', '{"id":"person-0502","name":"Jin Junhyeok","title":"Auction Clerk","position":"Myeongdong Station Election Records Clerk","rank":"Congregationioner","commonTier":"T5","occupation":"Election Records and Handover Log","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0502","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0502","name":"진준혁","title":"경매 서기","position":"명동역 선거 기록 서기","rank":"교우","commonTier":"T5","occupation":"선거 기록·인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0502","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0503', 'ae40-ac15-b989-91d1', '{"id":"person-0503","name":"Kim Junho","title":"Audit Recorder","position":"Audit Recorder","rank":"Guild Member","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0503","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0503","name":"김준호","title":"감사 기록관","position":"감사 기록관","rank":"조합원","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0503","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0504', 'c774-c131-c8fc-674e', '{"id":"person-0504","name":"I Neulmin","title":"Conduit Surveyor","position":"Conduit Surveyor","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Male","stage":"S4","state":"S01","stateName":"The Sluice","detailRoute":"/people/person-0504","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0504","name":"이늘민","title":"관로 탐사원","position":"관로 탐사원","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"남성","stage":"S4","state":"S01","stateName":"수문국","detailRoute":"/people/person-0504","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0505', 'bc15-bc00-c591', '{"id":"person-0505","name":"Bak Haeun","title":"Restoration Service Recorder","position":"Restoration Service Recorder","characterId":"K505","rank":"Guild Member","commonTier":"T5","occupation":"Registration & Records","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-02#inmul-bak-haeun","detailRoute":"/people/person-0505","birthDate":"2084-06-01","birthday":"06-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k505-sealed-record-linking","name":"Linking seal and registry records","rating":60}],"traits":[{"id":"k505-action-priority","name":"Seal records and debt entries","description":"A copy of the restoration-service roster that the Eastern Command once offered in place of the pump-parts crates reaches the records duty. Park Haeun pins the seal record of the crates Gang Minseo sent back sealed beside the copy, and writes out in registry order the line from which the debt between Han Jaemok''s western water supply and Bae Woojin''s military bureau begins.","behavior":"A copy of the restoration-service roster that the Eastern Command once offered in place of the pump-parts crates reaches the records duty. Park Haeun pins the seal record of the crates Gang Minseo sent back sealed beside the copy, and writes out in registry order the line from which the debt between Han Jaemok''s western water supply and Bae Woojin''s military bureau begins.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k505-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A copy of the restoration-service roster that the Eastern Command once offered in place of the pump-parts crates reaches the records duty. Park Haeun pins the seal record of the crates Gang Minseo sent back sealed beside the copy, and writes out in registry order the line from which the debt between Han Jaemok''s western water supply and Bae Woojin''s military bureau begins. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-35,"Openness":0,"Force":-10,"Material":35,"Communal":30,"Principle":20,"Public":25,"Eligibility":55,"Dispersed":30,"Transformative":30},"desire":{"Longing":-15,"Monopoly":-10,"Risk":20,"Display":-20,"Sustained":-15,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Registration & Records","Rank":"Guild Member","Title":"Restoration Service Recorder","Work Location":"Guro 2-dong. At the Guro 2-dong records duty post, Bak Haeun lists side by side the copy of the restoration-service roster demanded by the Eastern Agency and the number of the parts box sealed by Gang Minseo. To trace the source of the contract debt remaining between Han Jaemok''s water supply and Bae Ujin''s Military Board, she hands the registry order to Je Haon.","Values":"Authority −35 | Openness 0 | Force −10 | Materialism 35 | Community 30 | Principle 20 | Publicity 25 | Qualification 55 | Decentralization 30 | Reform 30","Desires":"Craving −15 | Monopoly −10 | Risk 20 | Display −20 | Persistence −15 | Orientation None | Union Contract cohabitation"},"sections":{"Life":"Generation of 2126. Grew up at the Seoul Station Registry. The Restoration Service Recorder post opened up when a line in a double ledger was deleted.\n- Work location: Guro 2-dong. On record duty in Guro 2-dong, Bak Haeun writes side by side the copy of the restoration service roster that the Eastern Office demanded and the number on the parts box that Gang Minseo sealed. To trace the source of the contract debt left between Han Jaemok''s water supply and Bae Ujin''s Ministry of War, she passes the registration order to Je Haon.","Offices":"Rank: Guild Member. Title: Restoration Service Recorder. To trace the source of the contract debt left between Han Jaemok''s water supply and Bae Ujin''s Ministry of War, she passes the registration order to Je Haon.","Anecdote":"A copy of the restoration-service roster, which the Eastern Agency had offered in place of a box of pump parts, arrives at the records duty post. Bak Haeun attaches the seal record of the box that Gang Minseo sealed and sent back to the copy, and writes down in registry order which line the debt remaining between Han Jaemok''s Western Water Supply and Bae Ujin''s Military Board originates from.","Relationships":"Bak Haeun shows Gim Nayul the seal record of the parts crate attached to the restoration-service roster copy. Gim Nayul checks the work-crew shifts and citizenship registration records to find where service listed as payment for parts and actual union labor were treated as the same line.","Ambition":"Bak Haeun traces the registration order of the sealed parts box and the restoration service roster, intending to reveal the line where the contract debt began.","Fear":"Having the restoration service copy attached to the seal record treated on the same line as an actual labor shift.","Intervention":"The player can match Bak Haeun''s parts box seal number to the roster copy, or pass the registration order to Je Haon."},"biography":"Bak Haeun begins by doubting the line where the parts box and the restoration service roster are written as if they were the price of a single transaction.\n\n- Affiliation: Free City\n- Occupation: Registry & Records\n- Rank: Guild Member\n- Title: Restoration Service Recorder\n**Life.** Generation of 2126. Grew up at the Seoul Station Registry. The Restoration Service Recorder post opened up when a line in a double ledger was deleted.\n- Work location: Guro 2-dong. On record duty in Guro 2-dong, Bak Haeun writes side by side the copy of the restoration service roster that the Eastern Office demanded and the number on the parts box that Gang Minseo sealed. To trace the source of the contract debt left between Han Jaemok''s water supply and Bae Ujin''s Ministry of War, she passes the registration order to Je Haon.\n\n**Office.** Rank: Guild Member. Title: Restoration Service Recorder. To trace the source of the contract debt left between Han Jaemok''s water supply and Bae Ujin''s Ministry of War, she passes the registration order to Je Haon.\n\n**Anecdote.** The copy of the restoration service worker roster that the Eastern Office offered in place of a box of pump parts arrives at the record duty desk. Bak Haeun attaches the seal record of the box that Gang Minseo sealed and sent back next to the copy, and writes down, in registration order, the line from which the debt remaining between Han Jaemok''s western water supply and Bae Ujin''s Ministry of War originates.\n\n**Relationships.** Bak Haeun shows Kim Nayul the seal record of the parts box attached to the copy of the restoration service roster. Kim Nayul checks the work crew shifts and citizenship registration records to find where service written as the price of parts and actual guild labor were treated on the same line.\n\n**Ambition.** Bak Haeun traces the registration order of the sealed parts box and the restoration service roster, intending to reveal the line where the contract debt began.\n\n**Fear.** Having the restoration service copy attached to the seal record treated on the same line as an actual labor shift.\n\n**Intervention.** The player can match Bak Haeun''s parts box seal number to the roster copy, or pass the registration order to Je Haon.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −35 | Openness 0 | Force −10 | Materialism 35 | Community 30 | Principle 20 | Publicity 25 | Qualification 55 | Decentralization 30 | Transformation 30\n- Desires: Craving −15 | Possessiveness −10 | Risk 20 | Display −20 | Persistence −15 | Orientation No Orientation | Bonding Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Bak Haeun","type":"Contract","to":"Kim Nayul","basis":"Bak Haeun shows Gim Nayul the seal record of the parts crate attached to the restoration-service roster copy. Gim Nayul checks the work-crew shifts and citizenship registration records to find where service listed as payment for parts and actual union labor were treated as the same line."}],"incoming":[]}}', '{"id":"person-0505","name":"박하은","title":"복구복무 기록관","position":"복구복무 기록관","characterId":"K505","rank":"조합원","commonTier":"T5","occupation":"등기·기록","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-02#인물-박하은","detailRoute":"/people/person-0505","birthDate":"2084-06-01","birthday":"06-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k505-sealed-record-linking","name":"봉인·등기 기록 연결","rating":60}],"traits":[{"id":"k505-action-priority","name":"봉인과 빚의 줄","description":"동방사가 펌프 부품 상자 대신 내밀었던 복구복무자 명부의 사본이 기록관 당직에 들어온다. 박하은은 강민서가 봉한 채 돌려보낸 상자의 봉인 기록을 사본 옆에 붙이고, 한재목의 서부 급수와 배우진의 병조 사이에 남은 빚이 어느 줄에서 비롯하는지 등기 순서대로 적는다.","behavior":"동방사가 펌프 부품 상자 대신 내밀었던 복구복무자 명부의 사본이 기록관 당직에 들어온다. 박하은은 강민서가 봉한 채 돌려보낸 상자의 봉인 기록을 사본 옆에 붙이고, 한재목의 서부 급수와 배우진의 병조 사이에 남은 빚이 어느 줄에서 비롯하는지 등기 순서대로 적는다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k505-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"동방사가 펌프 부품 상자 대신 내밀었던 복구복무자 명부의 사본이 기록관 당직에 들어온다. 박하은은 강민서가 봉한 채 돌려보낸 상자의 봉인 기록을 사본 옆에 붙이고, 한재목의 서부 급수와 배우진의 병조 사이에 남은 빚이 어느 줄에서 비롯하는지 등기 순서대로 적는다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-35,"개방":0,"무력":-10,"물질":35,"공동":30,"원칙":20,"공개":25,"자격":55,"분산":30,"변혁":30},"desire":{"갈망":-15,"독점":-10,"위험":20,"과시":-20,"지속":-15,"지향":"무성향","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"등기·기록","품계":"조합원","직함":"복구복무 기록관","업무 위치":"구로2동. 박하은은 구로2동 기록 당직에서 동방사가 요구한 복구복무 명부 사본과 강민서가 봉한 부품 상자의 번호를 나란히 적는다. 한재목의 급수와 배우진의 병조 사이에 남은 계약 빚의 출처를 찾기 위해 등기 순서를 제하온에게 넘긴다.","가치관":"권위 −35 | 개방 0 | 무력 −10 | 물질 35 | 공동 30 | 원칙 20 | 공개 25 | 자격 55 | 분산 30 | 변혁 30","욕망":"갈망 −15 | 독점 −10 | 위험 20 | 과시 −20 | 지속 −15 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 박하은은 구로2동 기록 당직에서 동방사가 요구한 복구복무 명부 사본과 강민서가 봉한 부품 상자의 번호를 나란히 적는다. 한재목의 급수와 배우진의 병조 사이에 남은 계약 빚의 출처를 찾기 위해 등기 순서를 제하온에게 넘긴다.","관직":"품계 조합원. 직함은 복구복무 기록관. 한재목의 급수와 배우진의 병조 사이에 남은 계약 빚의 출처를 찾기 위해 등기 순서를 제하온에게 넘긴다.","일화":"동방사가 펌프 부품 상자 대신 내밀었던 복구복무자 명부의 사본이 기록관 당직에 들어온다. 박하은은 강민서가 봉한 채 돌려보낸 상자의 봉인 기록을 사본 옆에 붙이고, 한재목의 서부 급수와 배우진의 병조 사이에 남은 빚이 어느 줄에서 비롯하는지 등기 순서대로 적는다.","관계":"박하은은 복구복무 명부 사본에 붙인 부품 상자의 봉인 기록을 김나율에게 보여 준다. 김나율은 작업반 교대와 시민권 등록 기록을 확인해, 부품 대가로 적힌 복무와 실제 조합 노동이 같은 줄로 취급된 곳을 찾는다.","야망":"박하은은 봉인 부품 상자와 복구복무 명부의 등기 순서를 추적해 계약 빚이 시작된 줄을 밝히려 한다.","공포":"봉인 기록에 붙은 복구복무 사본이 실제 노동 교대와 같은 줄로 처리되는 것.","개입":"플레이어는 박하은과 부품 상자 봉인 번호를 명부 사본에 맞추거나 등기 순서를 제하온에게 전달할 수 있다."},"biography":"박하은은 부품 상자와 복구복무 명부가 한 거래의 대가처럼 적힌 줄부터 의심한다.\n\n- 소속: 자유도시\n- 생업: 등기·기록\n- 품계: 조합원\n- 직함: 복구복무 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 박하은은 구로2동 기록 당직에서 동방사가 요구한 복구복무 명부 사본과 강민서가 봉한 부품 상자의 번호를 나란히 적는다. 한재목의 급수와 배우진의 병조 사이에 남은 계약 빚의 출처를 찾기 위해 등기 순서를 제하온에게 넘긴다.\n\n**관직.** 품계 조합원. 직함은 복구복무 기록관. 한재목의 급수와 배우진의 병조 사이에 남은 계약 빚의 출처를 찾기 위해 등기 순서를 제하온에게 넘긴다.\n\n**일화.** 동방사가 펌프 부품 상자 대신 내밀었던 복구복무자 명부의 사본이 기록관 당직에 들어온다. 박하은은 강민서가 봉한 채 돌려보낸 상자의 봉인 기록을 사본 옆에 붙이고, 한재목의 서부 급수와 배우진의 병조 사이에 남은 빚이 어느 줄에서 비롯하는지 등기 순서대로 적는다.\n\n**관계.** 박하은은 복구복무 명부 사본에 붙인 부품 상자의 봉인 기록을 김나율에게 보여 준다. 김나율은 작업반 교대와 시민권 등록 기록을 확인해, 부품 대가로 적힌 복무와 실제 조합 노동이 같은 줄로 취급된 곳을 찾는다.\n\n**야망.** 박하은은 봉인 부품 상자와 복구복무 명부의 등기 순서를 추적해 계약 빚이 시작된 줄을 밝히려 한다.\n\n**공포.** 봉인 기록에 붙은 복구복무 사본이 실제 노동 교대와 같은 줄로 처리되는 것.\n\n**개입.** 플레이어는 박하은과 부품 상자 봉인 번호를 명부 사본에 맞추거나 등기 순서를 제하온에게 전달할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −35 | 개방 0 | 무력 −10 | 물질 35 | 공동 30 | 원칙 20 | 공개 25 | 자격 55 | 분산 30 | 변혁 30\n- 욕망: 갈망 −15 | 독점 −10 | 위험 20 | 과시 −20 | 지속 −15 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"박하은","type":"계약","to":"김나율","basis":"박하은은 복구복무 명부 사본에 붙인 부품 상자의 봉인 기록을 김나율에게 보여 준다. 김나율은 작업반 교대와 시민권 등록 기록을 확인해, 부품 대가로 적힌 복무와 실제 조합 노동이 같은 줄로 취급된 곳을 찾는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0506', 'cd5c-c804-c8fc-5d14', '{"id":"person-0506","name":"Choe Reuma","title":"Certification Courier","position":"Certification Courier","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0506","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0506","name":"최름아","title":"인증 전령","position":"인증 전령","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0506","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0507', 'c815-acbd-c8fc-912d', '{"id":"person-0507","name":"Jeong Bajun","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K507","rank":"","commonTier":"T3","occupation":"Wheel & Pump Maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-jeong-bajun","detailRoute":"/people/person-0507","birthDate":"2096-05-19","birthday":"05-19","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"pump","name":"Pump disassembly and shaft replacement","rating":55},{"id":"wheel","name":"Wheel-defect inspection","rating":40}],"traits":[{"id":"replace-only-worn-axles","name":"Replace Only Worn Axles","description":"Jeong Bajun shows a practical preference for repairing only the confirmed worn component.","behavior":"He dismantled the stopped pump, replaced one worn axle, and restarted it.","stress":"If a duty gap threatens to leave passage subject to a powerful state, he may focus on the necessary repair.","relationship":"When handing over to the senior duty holder, he may focus on verified work such as the replaced axle.","effects":[]},{"id":"duty-continuity-through-maintenance","name":"Duty Continuity Through Maintenance","description":"Jeong Bajun treats concrete maintenance as a means of sustaining duty and ledger continuity.","behavior":"He resolves an interruption by restarting the pump and passes on the keys and records belonging to his post.","stress":"If vacant duty could make passage hostage to a powerful state, he may place greater weight on connecting repairs with handover.","relationship":"He may cooperate with the senior duty holder through handovers linking repair results to post records.","effects":[]}],"narrative":"He disassembled a stopped pump and replaced one worn shaft. Specific repair is supported, not comprehensive manufacture or invention.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43730-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K507","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43730-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c815-acbd-c8fc-912d","name":"Gyeongju Jeong Clan","crest":"clan-crests/c815-acbd-c8fc-912d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":5,"Openness":0,"Force":-30,"Material":40,"Communal":40,"Principle":-10,"Public":-25,"Eligibility":25,"Dispersed":25,"Transformative":0},"desire":{"Longing":5,"Monopoly":40,"Risk":40,"Display":10,"Sustained":10,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Wheel & Pump Maintenance","Rank":"Teacher","Title":"Parts Logistics Merchant","Values":"Authority 5 | Openness 0 | Force −30 | Materialism 40 | Community 40 | Principle −10 | Publicity −25 | Qualification 25 | Decentralization 25 | Transformation 0","Desires":"Craving 5 | Possessiveness 40 | Risk 40 | Display 10 | Persistence 10 | Orientation Bisexual | Bonding Non-exclusive"},"sections":{"Life":"Generation of 2126. Jeong Bajun grew up at Sinjeong Depot. Jeong Bajun took the Parts Logistics Officer post after reporting a defect just before a derailment.\n- Jeong Bajun''s Parts Logistics Officer duties are connected to Seongsu 2-ga 1-dong.","Offices":"Jeong Bajun hands over only the keys and records attached to his own post. He does not invent authority that does not exist.","Anecdote":"In 2125, Jeong Bajun took apart a stalled pump, replaced just one worn shaft, and got it running again. Because of this, the signature for the Parts Logistics Officer post was entered in the ledger.","Relationships":"Jeong Bajun is bound by handover to a senior watch keeper from the same living area.","Ambition":"On the Parts Logistics Officer watch, Jeong Bajun wants to keep the Arc''s ledger connected without a break.","Fear":"Jeong Bajun fears that if the Parts Logistics Officer watch falls vacant, the Arc''s passage will become a hostage of a great power.","Intervention":"Jeong Bajun can bring in a witness to the watch handover or expose an empty key."},"biography":"Jeong Bajun chooses first not to break the watch. Jeong Bajun trusts a single line in the ledger over loud talk.\n\n- Affiliation: Arc\n- Occupation: Wheel & Pump Maintenance\n- Rank: Teacher\n- Title: Parts Logistics Officer\n**Life.** Generation of 2126. Jeong Bajun grew up at Sinjeong Depot. Jeong Bajun took the Parts Logistics Officer post after reporting a defect just before a derailment.\n- Jeong Bajun''s Parts Logistics Officer duties are connected to Seongsu 2-ga 1-dong.\n\n**Office.** Jeong Bajun hands over only the keys and records attached to his own post. He does not invent authority that does not exist.\n\n**Anecdote.** In 2125, Jeong Bajun took apart a stalled pump, replaced just one worn shaft, and got it running again. Because of this, the signature for the Parts Logistics Officer post was entered in the ledger.\n\n**Relationships.** Jeong Bajun is bound by handover to a senior watch keeper from the same living area.\n\n**Ambition.** On the Parts Logistics Officer watch, Jeong Bajun wants to keep the Arc''s ledger connected without a break.\n\n**Fear.** Jeong Bajun fears that if the Parts Logistics Officer watch falls vacant, the Arc''s passage will become a hostage of a great power.\n\n**Intervention.** Jeong Bajun can bring in a witness to the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 5 | Openness 0 | Force −30 | Materialism 40 | Community 40 | Principle −10 | Publicity −25 | Qualification 25 | Decentralization 25 | Transformation 0\n- Desires: Craving 5 | Possessiveness 40 | Risk 40 | Display 10 | Persistence 10 | Orientation Bisexual | Bonding Non-exclusive\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0507","name":"정바준","title":"부품 물류상","position":"부품 물류상","characterId":"K507","rank":"","commonTier":"T3","occupation":"차륜·펌프 정비","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-정바준","detailRoute":"/people/person-0507","birthDate":"2096-05-19","birthday":"05-19","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"pump","name":"펌프 분해·축 교체","rating":55},{"id":"wheel","name":"차륜 결함 점검","rating":40}],"traits":[{"id":"replace-only-worn-axles","name":"마모 축만 교체","description":"정바준은 확인된 마모 부위에 수리를 한정하는 실용적 성향을 보인다.","behavior":"멈춘 펌프를 분해해 마모 축 하나만 교체하고 다시 가동했다.","stress":"당직 공백으로 통행이 강국에 종속될 우려가 커지면 필요한 수리에 집중하려 할 수 있다.","relationship":"선배 당직과 인계할 때는 교체한 축처럼 확인된 작업 내용을 중심으로 설명할 수 있다.","effects":[]},{"id":"duty-continuity-through-maintenance","name":"정비로 당직 연결","description":"정바준은 구체적 정비를 당직과 장부의 연속성을 지키는 수단으로 여긴다.","behavior":"펌프를 재가동하는 수리로 중단을 해소하고 자기 직위의 열쇠와 기록을 넘긴다.","stress":"당직이 비어 통행이 강국의 볼모가 될 가능성을 느끼면 정비와 인계의 연결을 더 중시할 수 있다.","relationship":"선배 당직과는 수리 결과와 직위 기록을 이어 주는 인계를 통해 협력하려 할 수 있다.","effects":[]}],"narrative":"정지 펌프를 분해해 마모 축 하나를 갈았다. 구체적 정비 수행만 평가하며 제조·발명 전체 능력은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43730-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K507","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43730-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c815-acbd-c8fc-912d","name":"경주 정씨","crest":"clan-crests/c815-acbd-c8fc-912d.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":5,"개방":0,"무력":-30,"물질":40,"공동":40,"원칙":-10,"공개":-25,"자격":25,"분산":25,"변혁":0},"desire":{"갈망":5,"독점":40,"위험":40,"과시":10,"지속":10,"지향":"양성","결합":"비독점"},"fields":{"소속":"Arc","생업":"차륜·펌프 정비","품계":"교사","직함":"부품 물류상","가치관":"권위 5 | 개방 0 | 무력 −30 | 물질 40 | 공동 40 | 원칙 −10 | 공개 −25 | 자격 25 | 분산 25 | 변혁 0","욕망":"갈망 5 | 독점 40 | 위험 40 | 과시 10 | 지속 10 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2126년 세대. 정바준은 신정 차량기지에서 자랐다. 정바준은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 정바준의 부품 물류상 업무는 성수2가1동과 연결된다.","관직":"정바준은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 정바준은 정지했던 펌프를 분해해 마모 축 하나만 갈아 다시 돌렸다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"정바준은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"정바준은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"정바준은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"정바준은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"정바준은 당직을 끊지 않는 쪽을 먼저 고른다. 정바준은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 차륜·펌프 정비\n- 품계: 교사\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 정바준은 신정 차량기지에서 자랐다. 정바준은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 정바준의 부품 물류상 업무는 성수2가1동과 연결된다.\n\n**관직.** 정바준은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 정바준은 정지했던 펌프를 분해해 마모 축 하나만 갈아 다시 돌렸다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 정바준은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 정바준은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 정바준은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 정바준은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 5 | 개방 0 | 무력 −30 | 물질 40 | 공동 40 | 원칙 −10 | 공개 −25 | 자격 25 | 분산 25 | 변혁 0\n- 욕망: 갈망 5 | 독점 40 | 위험 40 | 과시 10 | 지속 10 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[],"incoming":[]}}');
