INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0514', 'c624-d574-c8fc', '{"id":"person-0514","name":"O Jiho","title":"Wheel Technician","position":"Seongha Electronics Wheel Technician","rank":"Employee","commonTier":"T5","occupation":"Seongha Electronics Wheel Maintenance Records & Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0514","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0514","name":"오지호","title":"차륜 정비사","position":"성하전자 차륜 정비사","rank":"사원","commonTier":"T5","occupation":"성하전자 차륜 정비 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0514","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0515', 'c11c-b2ec-c131', '{"id":"person-0515","name":"Seo Seoseo","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0515","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0515","name":"서서서","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0515","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0516', 'c2e0-d3c9-c0b0', '{"id":"person-0516","name":"Sin Habin","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Logistics Merchant","characterId":"K516","rank":"Resident","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#Inmul-Sin-Habin","detailRoute":"/people/person-0516","birthDate":"2098-01-22","birthday":"01-22","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"surgical-procedure","name":"Surgical procedure","rating":55}],"traits":[{"id":"stated-priority","name":"Keeps working through an outage","description":"Surgery continued under phone light during an outage. Only this performed procedure supports the rating; overall outcomes are unknown.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Surgery continued under phone light during an outage. Only this performed procedure supports the rating; overall outcomes are unknown.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2e0-d3c9-c0b0","name":"Pyeongsan Sin Clan","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":35,"Force":-50,"Material":5,"Communal":10,"Principle":35,"Public":15,"Eligibility":15,"Dispersed":20,"Transformative":-5},"desire":{"Longing":25,"Monopoly":5,"Risk":-10,"Display":5,"Sustained":-10,"Orientation":"None","Union":"Monogamy"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −20 | Openness 35 | Force −50 | Materialism 5 | Community 10 | Principle 35 | Publicity 15 | Credentials 15 | Decentralization 20 | Transformation −5","Desires":"Craving 25 | Exclusivity 5 | Risk −10 | Display 5 | Persistence −10 | Orientation None | Union Monogamous"},"sections":{"Life":"Born on 2098-01-22. As of the 2126 opening, he holds the post of Herbal Supply Steward, connecting the existing watch and its records. The succession record for that post opened with a counterfeit medicine seal.\n- The medicinal-supply management records and watch key handover desk in Jegi-dong is Sin Habin''s work reference point. This work reference point does not establish a residence, exact facility boundaries, noble title, fief, or possession rights.","Offices":"Rank: Resident. Title: Medicinal Herb Management Resident. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, when the power went out during surgery, continued operating by the light of a handheld phone. That day''s record remained as the handover basis for the next shift to verify.","Relationships":"Sin Habin hands the custody records of the medicinal herbs used in surgery to Dong Juha and has the next supply inspected. Dong Juha checks origin and drying date and arranges the dispatch order to match the treatment assignment seal, so that care after the blackout is not cut off again by a shortage of herbs.","Ambition":"From the post of Medicinal Herb Management Resident, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that if the Medicinal Herb Management Resident''s watch falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the watch. He trusts a single ledger line more than loud talk.\n\n- Livelihood: Medicinal-supply management records and watch key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Herbal Supply Steward\n**Life.** Born on 2098-01-22. As of the 2126 opening, he holds the post of Herbal Supply Steward, connecting the existing watch and its records. The succession record for that post opened with a counterfeit medicine seal.\n- The medicinal-supply management records and watch key handover desk in Jegi-dong is Sin Habin''s work reference point. This work reference point does not establish a residence, exact facility boundaries, noble title, fief, or possession rights.\n\n**Office.** Rank: Resident. Title: Medicinal Materials Management Resident. He hands over only the keys and records of his own post, and writes in the ledger the time at which the handed-over keys and records were received.\n\n**Anecdote.** In 2125, when the power went out during surgery, he kept operating with the scalpel under a mobile phone''s light. That day''s record remained as handover evidence for the next watch to verify.\n\n**Relationships.** Sin Habin hands the management records of the medicinal materials used in surgery to Dong Juha, to have the next supply inspected. Dong Juha checks the place of origin and drying date and sets the shipping order to match the treatment-assignment seal, so that care after the blackout is not cut off again by a shortage of medicinal materials.\n\n**Ambition.** From the post of Medicinal Materials Management Resident, he keeps the ledger of the White Cross Order connected without a break.\n\n**Fear.** If the Medicinal Materials Management Resident watch falls vacant, he fears that the White Cross Order''s passage will become a hostage of Seoul''s internal patron forces.\n\n**Intervention.** He can bring in a witness to the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 35 | Force −50 | Materialism 5 | Community 10 | Principle 35 | Publicity 15 | Credentials 15 | Decentralization 20 | Transformation −5\n- Desires: Craving 25 | Exclusivity 5 | Risk −10 | Display 5 | Persistence −10 | Orientation None | Union Monogamous\n:::","relations":{"outgoing":[{"from":"Sin Habin","type":"Contract","to":"Dong Juha","basis":"Sin Habin hands the custody records of the medicinal herbs used in surgery to Dong Juha and has the next supply inspected. Dong Juha checks origin and drying date and arranges the dispatch order to match the treatment assignment seal, so that care after the blackout is not cut off again by a shortage of herbs."}],"incoming":[]}}', '{"id":"person-0516","name":"신하빈","title":"약재 물류상","position":"약재 물류상","characterId":"K516","rank":"수련의","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-신하빈","detailRoute":"/people/person-0516","birthDate":"2098-01-22","birthday":"01-22","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"surgical-procedure","name":"수술 수행","rating":55}],"traits":[{"id":"stated-priority","name":"정전에도 손을 멈추지 않는다","description":"정전 중 휴대전화 불빛 아래 수술을 이어갔다. 단일 일화로 확인되는 수행만 반영하며 수술 전반의 성공률은 모른다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"정전 중 휴대전화 불빛 아래 수술을 이어갔다. 단일 일화로 확인되는 수행만 반영하며 수술 전반의 성공률은 모른다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2e0-d3c9-c0b0","name":"평산 신씨","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":35,"무력":-50,"물질":5,"공동":10,"원칙":35,"공개":15,"자격":15,"분산":20,"변혁":-5},"desire":{"갈망":25,"독점":5,"위험":-10,"과시":5,"지속":-10,"지향":"무성향","결합":"단혼"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"약재 물류상","가치관":"권위 −20 | 개방 35 | 무력 −50 | 물질 5 | 공동 10 | 원칙 35 | 공개 15 | 자격 15 | 분산 20 | 변혁 −5","욕망":"갈망 25 | 독점 5 | 위험 −10 | 과시 5 | 지속 −10 | 지향 무성향 | 결합 단혼"},"sections":{"생애":"2098-01-22에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 신하빈의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 수술 중 정전이 되자 손전화 아래에서 칼을 계속했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"신하빈은 수술에 쓴 약재의 관리 기록을 동주하에게 넘겨 다음 공급을 검수받는다. 동주하는 원산지와 건조 일자를 확인하고 진료 배정 날인에 맞춰 출하 순서를 잡아 정전 뒤의 진료가 약재 공백으로 다시 끊기지 않게 한다.","야망":"약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 약재 물류상\n**생애.** 2098-01-22에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 신하빈의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 수술 중 정전이 되자 손전화 아래에서 칼을 계속했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 신하빈은 수술에 쓴 약재의 관리 기록을 동주하에게 넘겨 다음 공급을 검수받는다. 동주하는 원산지와 건조 일자를 확인하고 진료 배정 날인에 맞춰 출하 순서를 잡아 정전 뒤의 진료가 약재 공백으로 다시 끊기지 않게 한다.\n\n**야망.** 약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 35 | 무력 −50 | 물질 5 | 공동 10 | 원칙 35 | 공개 15 | 자격 15 | 분산 20 | 변혁 −5\n- 욕망: 갈망 25 | 독점 5 | 위험 −10 | 과시 5 | 지속 −10 | 지향 무성향 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"신하빈","type":"계약","to":"동주하","basis":"신하빈은 수술에 쓴 약재의 관리 기록을 동주하에게 넘겨 다음 공급을 검수받는다. 동주하는 원산지와 건조 일자를 확인하고 진료 배정 날인에 맞춰 출하 순서를 잡아 정전 뒤의 진료가 약재 공백으로 다시 끊기지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0517', 'ad8c-c548-b3d9', '{"id":"person-0517","name":"Gwon Yerin","title":"Outpost Courier","position":"Agwansa Outpost Courier","rank":"Sergeant","commonTier":"T5","occupation":"Outpost Courier Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0517","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0517","name":"권예린","title":"초소 전령","position":"아관사 초소 전령","rank":"병장","commonTier":"T5","occupation":"초소 전령 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0517","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
