INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0519', 'c548-c21c-d765', '{"id":"person-0519","name":"An Gangmin","title":"Escort Patrol","position":"Escort Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Escort Patrol Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0519","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0519","name":"안강민","title":"호송 순찰대","position":"호송 순찰대","rank":"조합원","commonTier":"T5","occupation":"호송 순찰 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0519","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0520', 'c1a1-c5ec-c0b0', '{"id":"person-0520","name":"Song Jaehyeon","title":"Ration District Clerk","position":"Ration District Clerk","characterId":"K520","rank":"Clerk","commonTier":"T5","occupation":"Water Distribution Duty","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#Inmul-Song-Jaehyeon","detailRoute":"/people/person-0520","birthDate":"2080-04-14","birthday":"04-14","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k520-release-discussion","name":"Release discussion","rating":50}],"traits":[{"id":"k520-action-priority","name":"Sustain release discussions","description":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","behavior":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]},{"id":"k520-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]}],"narrative":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-c5ec-c0b0","name":"Yeosan Song Clan","crest":"clan-crests/c1a1-c5ec-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":40,"Openness":-5,"Force":0,"Material":60,"Communal":30,"Principle":5,"Public":10,"Eligibility":-10,"Dispersed":-40,"Transformative":-20},"desire":{"Longing":30,"Monopoly":-40,"Risk":-5,"Display":30,"Sustained":-15,"Orientation":"None","Union":"Non-Exclusive"},"fields":{"Affiliation":"Free City","Livelihood":"Water Distribution Duty","Rank":"Clerk","Title":"Ration District Clerk","Work Location":"Sinjeong 2-dong. During the drought of 2125, Song Jaehyeon recorded the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives, and transferred it into I Seodam''s Sinjeong 2-dong handover ledger.","Values":"Authority 40 | Openness −5 | Force 0 | Materialism 60 | Community 30 | Principle 5 | Publicity 10 | Credentials −10 | Decentralization −40 | Transformation −20","Desires":"Craving 30 | Exclusivity −40 | Risk −5 | Display 30 | Persistence −15 | Orientation None | Union Non-exclusive"},"sections":{"Life":"Generation of 2126. Raised at the Yeongdeungpo water purification watch. The Ration District Clerk post opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. During the drought of 2125, Song Jaehyeon recorded the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives, and transferred it into I Seodam''s Sinjeong 2-dong handover ledger.","Offices":"Rank: Jusa (Junior Officer). Title: Ration District Clerk. During the drought of 2125, Song Jaehyeon recorded the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives, and transferred it into I Seodam''s Sinjeong 2-dong handover ledger.","Anecdote":"During the drought of 2125, Song Jaehyeon recorded in the master ledger the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives.","Relationships":"Works as Lee Seodam''s Ration District Clerk and takes the water distribution watch.","Ambition":"In the post of Ration District Clerk, keeps the Water Gate Bureau''s ledger linked without a break.","Fear":"That the Water Gate Bureau''s passage becomes a hostage of the great powers if the Ration District Clerk''s watch is left vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the watch. He trusts a single ledger line more than loud talk.\n\n- Affiliation: Water Gate Bureau\n- Livelihood: Water distribution watch\n- Rank: Jusa (Junior Officer)\n- Title: Ration District Clerk\n**Life.** Generation of 2126. Raised at the Yeongdeungpo water purification watch. The Ration District Clerk post opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. During the drought of 2125, Song Jaehyeon recorded the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives, and transferred it into I Seodam''s Sinjeong 2-dong handover ledger.\n\n**Office.** Rank: Jusa (Junior Officer). Title: Ration District Clerk. During the drought of 2125, Song Jaehyeon recorded the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives, and transferred it into I Seodam''s Sinjeong 2-dong handover ledger.\n\n**Anecdote.** During the drought of 2125, Song Jaehyeon recorded in the master ledger the remaining water in Seoul''s reservoirs side by side with the discharge volume requested by the ration representatives.\n\n**Relationships.** He works as I Seodam''s Ration District Clerk and takes charge of the water distribution watch.\n\n**Ambition.** From the post of Ration District Clerk, he keeps the ledger of the Water Gate Bureau connected without a break.\n\n**Fear.** That if the Ration District Clerk watch falls vacant, the Water Gate Bureau''s passage will become a hostage of the great powers.\n\n**Intervention.** He can bring in a witness to the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 40 | Openness −5 | Force 0 | Materialism 60 | Community 30 | Principle 5 | Publicity 10 | Credentials −10 | Decentralization −40 | Transformation −20\n- Desires: Craving 30 | Exclusivity −40 | Risk −5 | Display 30 | Persistence −15 | Orientation None | Union Non-exclusive\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Song Jaehyeon","type":"Command","to":"I Seo-dam","basis":"Serves as clerk of Yi Seodam''s ration district and holds the water distribution watch"}],"incoming":[]}}', '{"id":"person-0520","name":"송재현","title":"배급구역 서기","position":"배급구역 서기","characterId":"K520","rank":"주사","commonTier":"T5","occupation":"급수 배분 당직","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-송재현","detailRoute":"/people/person-0520","birthDate":"2080-04-14","birthday":"04-14","age":46,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k520-release-discussion","name":"방류량 협의","rating":50}],"traits":[{"id":"k520-action-priority","name":"방류량 협의 지속","description":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","behavior":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]},{"id":"k520-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]}],"narrative":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-c5ec-c0b0","name":"여산 송씨","crest":"clan-crests/c1a1-c5ec-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":40,"개방":-5,"무력":0,"물질":60,"공동":30,"원칙":5,"공개":10,"자격":-10,"분산":-40,"변혁":-20},"desire":{"갈망":30,"독점":-40,"위험":-5,"과시":30,"지속":-15,"지향":"무성향","결합":"비독점"},"fields":{"소속":"자유도시","생업":"급수 배분 당직","품계":"주사","직함":"배급구역 서기","업무 위치":"신정2동. 송재현은 2125년 가뭄에 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 기록하고 이서담의 신정2동 인계 장부에 옮긴다.","가치관":"권위 40 | 개방 −5 | 무력 0 | 물질 60 | 공동 30 | 원칙 5 | 공개 10 | 자격 −10 | 분산 −40 | 변혁 −20","욕망":"갈망 30 | 독점 −40 | 위험 −5 | 과시 30 | 지속 −15 | 지향 무성향 | 결합 비독점"},"sections":{"생애":"2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 송재현은 2125년 가뭄에 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 기록하고 이서담의 신정2동 인계 장부에 옮긴다.","관직":"품계 주사. 직함은 배급구역 서기이다. 송재현은 2125년 가뭄에 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 기록하고 이서담의 신정2동 인계 장부에 옮긴다.","일화":"2125년 가뭄에 송재현은 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 원장에 남겼다.","관계":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","야망":"배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 급수 배분 당직\n- 품계: 주사\n- 직함: 배급구역 서기\n**생애.** 2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 송재현은 2125년 가뭄에 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 기록하고 이서담의 신정2동 인계 장부에 옮긴다.\n\n**관직.** 품계 주사. 직함은 배급구역 서기이다. 송재현은 2125년 가뭄에 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 기록하고 이서담의 신정2동 인계 장부에 옮긴다.\n\n**일화.** 2125년 가뭄에 송재현은 서울 저수조의 남은 물과 배급 대표가 요청한 방류량을 맞대어 원장에 남겼다.\n\n**관계.** 이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.\n\n**야망.** 배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 40 | 개방 −5 | 무력 0 | 물질 60 | 공동 30 | 원칙 5 | 공개 10 | 자격 −10 | 분산 −40 | 변혁 −20\n- 욕망: 갈망 30 | 독점 −40 | 위험 −5 | 과시 30 | 지속 −15 | 지향 무성향 | 결합 비독점\n:::","directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"송재현","type":"지휘","to":"이서담","basis":"이서담의 배급구역 서기로 급수 배분 당직을 맡음"}],"incoming":[]}}');
