INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0531', 'b0a8-c758-b839', '{"id":"person-0531","name":"Nam San-won","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0531","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0531","name":"남산원","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0531","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0532', 'c2ec-ccad-c1a1', '{"id":"person-0532","name":"Sim Tae-yang","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K532","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#character-simtaeyang","detailRoute":"/people/person-0532","birthDate":"2089-05-01","birthday":"05-01","age":37,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"Ledger preservation","rating":40}],"traits":[{"id":"stated-priority","name":"Rescues records of people first","description":"They removed the people ledger first in a fire. This fits a concern for continuity but offers little evidence of prescribing expertise.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"They removed the people ledger first in a fire. This fits a concern for continuity but offers little evidence of prescribing expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":35,"Force":-45,"Material":-15,"Communal":20,"Principle":40,"Public":15,"Eligibility":20,"Dispersed":20,"Transformative":-10},"desire":{"Longing":30,"Monopoly":-15,"Risk":-5,"Display":-5,"Sustained":20,"Orientation":"Same-Sex","Union":"None"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −20 | Openness 35 | Force −45 | Materialism −15 | Community 20 | Principle 40 | Publicity 15 | Credentials 20 | Decentralization 20 | Transformation −10","Desires":"Craving 30 | Monopoly −15 | Risk −5 | Display −5 | Endurance 20 | Orientation Same-sex | Bonding None"},"sections":{"Life":"Born on 2089-05-01. As of the opening in 2126, holds the Prescription Clerk duty and carries on the existing duty shifts and records. In the succession record of that duty, it opened up as a replacement duty after an unexcused shift absence.\n- The prescription records and duty key handover desk in Jegi-dong is Sim Taeyang''s work reference point. This work reference point does not confirm a residence, exact facility boundaries, a title of nobility, a fief, or possession rights.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In the 2125 station fire, carried out the register of lives first. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Sim Taeyang hands over the ledger of lives rescued from the fire and the prescription records to Jeon Sol. Jeon Sol identifies the patients missing from the bed waitlist roster and sets the treatment order by severity, so that the loss of records does not lead to anyone being dropped from treatment.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty shifts. Trusts a single line in the ledger more than loud words.\n\n- Livelihood: Prescription records and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Prescription Clerk\n**Life.** Born on 2089-05-01. As of the opening in 2126, holds the Prescription Clerk duty and carries on the existing duty shifts and records. In the succession record of that duty, it opened up as a replacement duty after an unexcused shift absence.\n- The prescription records and duty key handover desk in Jegi-dong is Sim Taeyang''s work reference point. This work reference point does not confirm a residence, exact facility boundaries, a title of nobility, a fief, or possession rights.\n\n**Office.** Rank: Resident. Title: Prescription Resident. Hands over only the keys and records of their own post, and writes into the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** During the station fire of 2125, carried out the life ledger first. That day''s record remained as the basis of handover for the next duty shift to confirm.\n\n**Relationships.** Sim Taeyang hands over the life ledger and prescription records saved from the fire to Jeon Sol. Jeon Sol checks for patients missing from the hospital bed waiting roster and sets the order of treatment according to severity, so that the loss of records does not lead to omitted treatment.\n\n**Ambition.** From the Prescription Resident post, to carry on the ledger of the White Cross Order without breaking it.\n\n**Fear.** Fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal patron factions.\n\n**Intervention.** Can appoint a witness to a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 35 | Force −45 | Materialism −15 | Community 20 | Principle 40 | Publicity 15 | Credentials 20 | Decentralization 20 | Transformation −10\n- Desires: Craving 30 | Monopoly −15 | Risk −5 | Display −5 | Endurance 20 | Orientation Same-sex | Bonding None\n:::","relations":{"outgoing":[{"from":"Sim Tae-yang","type":"Contract","to":"Jeon Sol","basis":"Sim Taeyang hands over the ledger of lives rescued from the fire and the prescription records to Jeon Sol. Jeon Sol identifies the patients missing from the bed waitlist roster and sets the treatment order by severity, so that the loss of records does not lead to anyone being dropped from treatment."}],"incoming":[]}}', '{"id":"person-0532","name":"심태양","title":"처방 서기","position":"처방 서기","characterId":"K532","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-심태양","detailRoute":"/people/person-0532","birthDate":"2089-05-01","birthday":"05-01","age":37,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"장부 보존","rating":40}],"traits":[{"id":"stated-priority","name":"인명 기록을 먼저 구한다","description":"화재 때 인명 장부를 우선 반출했다. 장부 연속성을 원하는 태도와 연결되지만 처방 전문성의 증거는 부족하다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"화재 때 인명 장부를 우선 반출했다. 장부 연속성을 원하는 태도와 연결되지만 처방 전문성의 증거는 부족하다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":35,"무력":-45,"물질":-15,"공동":20,"원칙":40,"공개":15,"자격":20,"분산":20,"변혁":-10},"desire":{"갈망":30,"독점":-15,"위험":-5,"과시":-5,"지속":20,"지향":"동성","결합":"없음"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −20 | 개방 35 | 무력 −45 | 물질 −15 | 공동 20 | 원칙 40 | 공개 15 | 자격 20 | 분산 20 | 변혁 −10","욕망":"갈망 30 | 독점 −15 | 위험 −5 | 과시 −5 | 지속 20 | 지향 동성 | 결합 없음"},"sections":{"생애":"2089-05-01에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 심태양의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"심태양은 화재에서 구한 인명 장부와 처방 기록을 전솔에게 인계한다. 전솔은 병상 대기 명부에서 빠진 환자를 확인하고 중증도에 따라 진료 순서를 잡아, 기록 손실이 치료 누락으로 이어지지 않게 한다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2089-05-01에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 심태양의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 심태양은 화재에서 구한 인명 장부와 처방 기록을 전솔에게 인계한다. 전솔은 병상 대기 명부에서 빠진 환자를 확인하고 중증도에 따라 진료 순서를 잡아, 기록 손실이 치료 누락으로 이어지지 않게 한다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 35 | 무력 −45 | 물질 −15 | 공동 20 | 원칙 40 | 공개 15 | 자격 20 | 분산 20 | 변혁 −10\n- 욕망: 갈망 30 | 독점 −15 | 위험 −5 | 과시 −5 | 지속 20 | 지향 동성 | 결합 없음\n:::","relations":{"outgoing":[{"from":"심태양","type":"계약","to":"전솔","basis":"심태양은 화재에서 구한 인명 장부와 처방 기록을 전솔에게 인계한다. 전솔은 병상 대기 명부에서 빠진 환자를 확인하고 중증도에 따라 진료 순서를 잡아, 기록 손실이 치료 누락으로 이어지지 않게 한다."}],"incoming":[]}}');
