INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0566', 'c190-bc00-c591', '{"id":"person-0566","name":"Son Byeolyeon","title":"Escort Logistics Merchant","position":"Myeongdong Station Relief Supplies Duty","rank":"Congregationioner","commonTier":"T5","occupation":"Relief Supplies Handover Records","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0566","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0566","name":"손별연","title":"호송 물류상","position":"명동역 구휼 물자 당직","rank":"교우","commonTier":"T5","occupation":"구휼 물자 인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0566","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0567', 'bc30-bd84-c131-88f5', '{"id":"person-0567","name":"Bae Bitmin","title":"Escort Patrol","position":"Escort Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Escort Patrol Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0567","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0567","name":"배빛민","title":"호송 순찰대","position":"호송 순찰대","rank":"조합원","commonTier":"T5","occupation":"호송 순찰 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0567","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0568', 'bc31-c218-c6d0', '{"id":"person-0568","name":"Baek Sanseok","title":"Ration District Clerk","position":"Ration District Clerk","characterId":"K568","rank":"Clerk","commonTier":"T5","occupation":"Water Distribution Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-baek-san-seok","detailRoute":"/people/person-0568","birthDate":"2065-12-15","birthday":"12-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k568-release-discussion","name":"Release discussion","rating":50}],"traits":[{"id":"k568-action-priority","name":"Discuss ration conditions","description":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","behavior":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]},{"id":"k568-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]}],"narrative":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc31-c218-c6d0","name":"Suwon Baek Clan","crest":"clan-crests/bc31-c218-c6d0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":0,"Force":20,"Material":40,"Communal":20,"Principle":5,"Public":10,"Eligibility":0,"Dispersed":-55,"Transformative":-10},"desire":{"Longing":50,"Monopoly":-15,"Risk":5,"Display":-25,"Sustained":0,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Affiliation":"Free City","Livelihood":"Water Distribution Duty","Rank":"Clerk","Title":"Ration District Clerk","Work Location":"Sinjeong 2-dong. In the drought of 2125, Baek Sanseok cross-checks the water level of Seoul''s ration reservoir overnight against the ration representative''s release request and hands the ledger over to Yi Seodam of Sinjeong 2-dong.","Values":"Authority 55 | Openness 0 | Force 20 | Materialism 40 | Communality 20 | Principle 5 | Publicity 10 | Qualification 0 | Decentralization −55 | Transformation −10","Desires":"Craving 50 | Possessiveness −15 | Risk 5 | Display −25 | Endurance 0 | Orientation Fluid | Bonding Monogamous"},"sections":{"Life":"Generation of 2126. Grew up at the Yeongdeungpo water purification watch. The post of Ration District Clerk opened with a valve signature on the night of the muddy water.\n- Work location: Sinjeong 2-dong. In the drought of 2125, Baek Sanseok cross-checks the water level of Seoul''s ration reservoir overnight against the ration representative''s release request and hands the ledger over to Yi Seodam of Sinjeong 2-dong.","Offices":"Rank: Senior Clerk. Title: Ration District Clerk. In the drought of 2125, Baek Sanseok cross-checks the water level of Seoul''s ration reservoir overnight against the ration representative''s release request and hands the ledger over to Yi Seodam of Sinjeong 2-dong.","Anecdote":"In the drought of 2125, Baek Sanseok cross-checked the water level of Seoul''s ration reservoir overnight against the representative''s release request and handed the ledger over to Yi Seodam.","Relationships":"Works as Lee Seodam''s Ration District Clerk and takes the water distribution watch.","Ambition":"In the post of Ration District Clerk, keeps the Water Gate Bureau''s ledger linked without a break.","Fear":"That the Water Gate Bureau''s passage becomes a hostage of the great powers if the Ration District Clerk''s watch is left vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the watch. Trusts a single line in the ledger over loud voices.\n\n- Affiliation: Water Gate Bureau\n- Livelihood: Water distribution watch\n- Rank: Senior Clerk\n- Title: Ration District Clerk\n**Life.** Generation of 2126. Grew up at the Yeongdeungpo water purification watch. The post of Ration District Clerk opened with a valve signature on the night of the muddy water.\n- Work location: Sinjeong 2-dong. In the drought of 2125, Baek Sanseok cross-checks the water level of Seoul''s ration reservoir overnight against the ration representative''s release request and hands the ledger over to Yi Seodam of Sinjeong 2-dong.\n\n**Office.** Rank: Senior Clerk. Title: Ration District Clerk. In the drought of 2125, Baek Sanseok cross-checks the water level of Seoul''s ration reservoir overnight against the ration representative''s release request and hands the ledger over to Yi Seodam of Sinjeong 2-dong.\n\n**Anecdote.** In the drought of 2125, Baek Sanseok cross-checked the water level of Seoul''s ration reservoir overnight against the representative''s release request and handed the ledger over to Yi Seodam.\n\n**Relationships.** Serves as Ration District Clerk to Yi Seodam and takes charge of the water distribution watch.\n\n**Ambition.** To keep the ledger of the Water Gate Bureau unbroken from the post of Ration District Clerk.\n\n**Fear.** That if the Ration District Clerk''s watch falls vacant, the Water Gate Bureau''s passage will become a hostage of the great powers.\n\n**Intervention.** Can bring in a witness to the handover of the watch or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness 0 | Force 20 | Materialism 40 | Communality 20 | Principle 5 | Publicity 10 | Qualification 0 | Decentralization −55 | Transformation −10\n- Desires: Craving 50 | Possessiveness −15 | Risk 5 | Display −25 | Endurance 0 | Orientation Fluid | Bonding Monogamous\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Baek Sanseok","type":"Command","to":"I Seo-dam","basis":"Serves as clerk of Yi Seodam''s ration district and holds the water distribution watch"}],"incoming":[]}}', '{"id":"person-0568","name":"백산석","title":"배급구역 서기","position":"배급구역 서기","characterId":"K568","rank":"주사","commonTier":"T5","occupation":"급수 배분 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-백산석","detailRoute":"/people/person-0568","birthDate":"2065-12-15","birthday":"12-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k568-release-discussion","name":"방류량 협의","rating":50}],"traits":[{"id":"k568-action-priority","name":"배급 조건 협의","description":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","behavior":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]},{"id":"k568-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]}],"narrative":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc31-c218-c6d0","name":"수원 백씨","crest":"clan-crests/bc31-c218-c6d0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":0,"무력":20,"물질":40,"공동":20,"원칙":5,"공개":10,"자격":0,"분산":-55,"변혁":-10},"desire":{"갈망":50,"독점":-15,"위험":5,"과시":-25,"지속":0,"지향":"유동","결합":"단혼"},"fields":{"소속":"자유도시","생업":"급수 배분 당직","품계":"주사","직함":"배급구역 서기","업무 위치":"신정2동. 백산석은 2125년 가뭄에 서울 배급 저수조의 수위를 배급 대표의 방류 요청과 밤새 대조하고 신정2동의 이서담에게 원장을 넘긴다.","가치관":"권위 55 | 개방 0 | 무력 20 | 물질 40 | 공동 20 | 원칙 5 | 공개 10 | 자격 0 | 분산 −55 | 변혁 −10","욕망":"갈망 50 | 독점 −15 | 위험 5 | 과시 −25 | 지속 0 | 지향 유동 | 결합 단혼"},"sections":{"생애":"2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 백산석은 2125년 가뭄에 서울 배급 저수조의 수위를 배급 대표의 방류 요청과 밤새 대조하고 신정2동의 이서담에게 원장을 넘긴다.","관직":"품계 주사. 직함은 배급구역 서기이다. 백산석은 2125년 가뭄에 서울 배급 저수조의 수위를 배급 대표의 방류 요청과 밤새 대조하고 신정2동의 이서담에게 원장을 넘긴다.","일화":"2125년 가뭄에 백산석은 서울 배급 저수조 수위와 대표의 방류 요청을 밤새 대조해 이서담에게 원장을 넘겼다.","관계":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","야망":"배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 급수 배분 당직\n- 품계: 주사\n- 직함: 배급구역 서기\n**생애.** 2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 백산석은 2125년 가뭄에 서울 배급 저수조의 수위를 배급 대표의 방류 요청과 밤새 대조하고 신정2동의 이서담에게 원장을 넘긴다.\n\n**관직.** 품계 주사. 직함은 배급구역 서기이다. 백산석은 2125년 가뭄에 서울 배급 저수조의 수위를 배급 대표의 방류 요청과 밤새 대조하고 신정2동의 이서담에게 원장을 넘긴다.\n\n**일화.** 2125년 가뭄에 백산석은 서울 배급 저수조 수위와 대표의 방류 요청을 밤새 대조해 이서담에게 원장을 넘겼다.\n\n**관계.** 이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.\n\n**야망.** 배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 0 | 무력 20 | 물질 40 | 공동 20 | 원칙 5 | 공개 10 | 자격 0 | 분산 −55 | 변혁 −10\n- 욕망: 갈망 50 | 독점 −15 | 위험 5 | 과시 −25 | 지속 0 | 지향 유동 | 결합 단혼\n:::","directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"백산석","type":"지휘","to":"이서담","basis":"이서담의 배급구역 서기로 급수 배분 당직을 맡음"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0569', 'd5c8-d0dc-c778-8a31', '{"id":"person-0569","name":"Heo Dau","title":"Work Crew Courier","position":"Work Crew Courier","rank":"Guild Member","commonTier":"T5","occupation":"Transfer Message Delivery","gender":"Male","stage":"S4","state":"S02","stateName":"The Gauge","detailRoute":"/people/person-0569","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0569","name":"허다우","title":"작업반 전령","position":"작업반 전령","rank":"조합원","commonTier":"T5","occupation":"환승 전갈 전달","gender":"남성","stage":"S4","state":"S02","stateName":"규격맹","detailRoute":"/people/person-0569","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0570', 'c720-ac15-b989', '{"id":"person-0570","name":"Yu Bayeong","title":"Retainer Recorder","position":"Retainer Recorder","characterId":"K570","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#inmul-yu-ba-yeong","detailRoute":"/people/person-0570","birthDate":"2082-07-22","birthday":"07-22","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"seed","name":"Temperature and seed-release checks","rating":50},{"id":"handover","name":"Record and key handover","rating":45}],"traits":[{"id":"mark-missing-safety-stamps","name":"Mark Missing Safety Stamps","description":"Yu Bayeong favors making the missing required safety-review stamp explicit despite the resident representative''s stamp.","behavior":"Yu Bayeong wrote on the first handover line that the seed-release request lacked a safety-review stamp.","stress":"When the resident representative''s stamp meets Bak Jinsol''s safety-review requirement, Yu Bayeong may record the blank field to expose the unmet condition.","relationship":"Yu Bayeong may make the missing safety-review stamp the first fact conveyed to the next duty holder.","effects":[]},{"id":"requests-and-keys-together","name":"Requests and Keys Together","description":"Yu Bayeong favors preserving handover context by transferring an incomplete request with its associated key.","behavior":"After recording the missing stamp, Yu Bayeong bundled the request with the storage key and handed them to the next duty holder.","stress":"Fear that a duty gap could leave passage hostage may encourage keeping the unresolved condition and key together.","relationship":"With the next duty holder, Yu Bayeong may share outstanding checks by transferring the request and key together.","effects":[]}],"narrative":"She marked a missing safety signature first and passed the request with the key. Specific seed-release checks are her supported strength.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c720-ac15-b989","name":"Gangneung Yu Clan","crest":"clan-crests/c720-ac15-b989.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":15,"Force":-20,"Material":0,"Communal":0,"Principle":70,"Public":40,"Eligibility":40,"Dispersed":20,"Transformative":10},"desire":{"Longing":35,"Monopoly":35,"Risk":-20,"Display":-45,"Sustained":35,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Arc","Livelihood":"Records and Keys Handover","Rank":"Assistant Manager","Title":"Retainer Recorder","Duty":"Gayang 1-dong. In Gayang 1-dong, Yu Bayeong matches seed records and handover signatures against the originals and passes them to the next shift. Suspect seals or empty safety review boxes are delivered to Jeong Harin together with the originals.","Values":"Authority −5 | Openness 15 | Force −20 | Material 0 | Communal 0 | Principle 70 | Publicity 40 | Qualification 40 | Dispersion 20 | Transformation 10","Desires":"Craving 35 | Monopoly 35 | Risk −20 | Display −45 | Persistence 35 | Orientation Fluid | Union Contract Cohabitation"},"sections":{"Life":"Of the generation of 2126. Grew up at the Seoul Station Registry Office. Yu Bayeong is in charge of reconciling seed records with storage vault handover records.\n- Duties: Gayang 1-dong. In Gayang 1-dong, Yu Bayeong matches seed records and handover signatures against the originals and passes them to the next shift. Suspect seals or empty safety review boxes are delivered to Jeong Harin together with the originals.","Offices":"Rank: Deputy. Title: Seed Records Officer. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.","Anecdote":"A seed release request bearing only the Resident Representative''s seal comes in to the Seed Records Officer''s shift. Yu Bayeong writes on the first line of the handover record that the safety review seal box, which Park Jinsol also requires, is empty, then bundles the request and the storage vault key together and passes them to the next shift.","Relationships":"Yu Bayeong informs Jeong Harin of the blank safety review seal box on a seed release request form and hands over the relevant records. Jeong Harin confirms the reproducible review basis, so that a request bearing only the resident representative''s seal is not processed as grounds for release.","Ambition":"Yu Bayeong intends to deliver the request with the empty safety review seal box to the next shift and to Jeong Harin in the same state.","Fear":"That a single Resident Representative seal will be read as a double seal across a shift change and become the grounds for taking seeds out.","Intervention":"The player can compare the first line of Yu Bayeong''s handover with the empty box on the request and ask Jeong Harin to confirm the grounds for the review."},"biography":"In Gayang 1-dong, Yu Bayeong first checks the original seed records for missing lines. Even when pressed to hurry the storage vault release, Yu reconciles the handover record with the temperature and humidity ledger before passing it to Park Jinsol.\n\n- Affiliation: Arc\n- Livelihood: Record and key handover\n- Rank: Deputy\n- Title: Seed Records Officer\n**Life.** Of the generation of 2126. Grew up at the Seoul Station Registry Office. Yu Bayeong is in charge of reconciling seed records with storage vault handover records.\n- Duties: Gayang 1-dong. In Gayang 1-dong, Yu Bayeong matches seed records and handover signatures against the originals and passes them to the next shift. Suspect seals or empty safety review boxes are delivered to Jeong Harin together with the originals.\n\n**Office.** Rank: Deputy. Title: Seed Records Officer. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.\n\n**Anecdote.** A seed release request bearing only the Resident Representative''s seal comes in to the Seed Records Officer''s shift. Yu Bayeong writes on the first line of the handover record that the safety review seal box, which Park Jinsol also requires, is empty, then bundles the request and the storage vault key together and passes them to the next shift.\n\n**Relationships.** Yu Bayeong informs Jeong Harin of the empty safety review seal box on the seed release request and hands over the record in question. Jeong Harin confirms a reproducible basis for the review so that a request with only the Resident Representative''s seal is not processed as grounds for taking seeds out.\n\n**Ambition.** Yu Bayeong intends to deliver the request with the empty safety review seal box to the next shift and to Jeong Harin in the same state.\n\n**Fear.** That a single Resident Representative seal will be read as a double seal across a shift change and become the grounds for taking seeds out.\n\n**Intervention.** The player can compare the first line of Yu Bayeong''s handover with the empty box on the request and ask Jeong Harin to confirm the grounds for the review.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 15 | Force −20 | Material 0 | Communal 0 | Principle 70 | Publicity 40 | Qualification 40 | Dispersion 20 | Transformation 10\n- Desires: Craving 35 | Monopoly 35 | Risk −20 | Display −45 | Persistence 35 | Orientation Fluid | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Yu Bayeong","type":"Contract","to":"Jeong Harin","basis":"Yu Bayeong informs Jeong Harin of the blank safety review seal box on a seed release request form and hands over the relevant records. Jeong Harin confirms the reproducible review basis, so that a request bearing only the resident representative''s seal is not processed as grounds for release."}],"incoming":[]}}', '{"id":"person-0570","name":"유바영","title":"종자 기록관","position":"종자 기록관","characterId":"K570","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-유바영","detailRoute":"/people/person-0570","birthDate":"2082-07-22","birthday":"07-22","age":44,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"seed","name":"온습도·종자 출고 확인","rating":50},{"id":"handover","name":"기록·열쇠 인수인계","rating":45}],"traits":[{"id":"mark-missing-safety-stamps","name":"빈 안전 날인 표시","description":"유바영은 주민대표 날인과 별개로 요구된 안전심사 날인의 공백을 분명히 드러내는 편이다.","behavior":"종자 출고 요청서의 안전심사 날인 칸이 비었다는 사실을 인수인계 기록 첫 줄에 적었다.","stress":"주민대표 날인과 박진솔의 안전심사 요구가 맞물릴 때 빈 칸을 기록해 미충족 조건을 드러내려 할 수 있다.","relationship":"다음 당직이 요청을 넘겨받을 때 안전심사 날인이 없다는 사실을 먼저 알리려 할 수 있다.","effects":[]},{"id":"requests-and-keys-together","name":"요청서와 열쇠 함께","description":"유바영은 미완료 요청의 문서와 관련 열쇠를 함께 넘겨 인계 맥락을 보존하는 편이다.","behavior":"날인 공백을 기록한 뒤 요청서와 보존고 열쇠를 한데 묶어 다음 당직에게 건넸다.","stress":"당직 공백이 통행을 볼모로 만들까 우려하면 미완료 조건과 열쇠가 분리되지 않도록 살필 수 있다.","relationship":"다음 당직과는 요청서와 열쇠를 함께 전달해 남은 확인 사항을 공유하려 할 수 있다.","effects":[]}],"narrative":"안전심사 날인이 빈 종자 요청을 인계 첫 줄에 기록하고 열쇠와 묶어 넘겼다. 구체적인 출고 조건 확인이 강점이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c720-ac15-b989","name":"강릉 유씨","crest":"clan-crests/c720-ac15-b989.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":15,"무력":-20,"물질":0,"공동":0,"원칙":70,"공개":40,"자격":40,"분산":20,"변혁":10},"desire":{"갈망":35,"독점":35,"위험":-20,"과시":-45,"지속":35,"지향":"유동","결합":"계약동거"},"fields":{"소속":"Arc","생업":"기록·열쇠 인수인계","품계":"대리","직함":"종자 기록관","업무":"가양1동. 유바영은 가양1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 의심 날인이나 빈 안전심사 칸은 정하린에게 원본과 함께 전한다.","가치관":"권위 −5 | 개방 15 | 무력 −20 | 물질 0 | 공동 0 | 원칙 70 | 공개 40 | 자격 40 | 분산 20 | 변혁 10","욕망":"갈망 35 | 독점 35 | 위험 −20 | 과시 −45 | 지속 35 | 지향 유동 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 유바영은 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 가양1동. 유바영은 가양1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 의심 날인이나 빈 안전심사 칸은 정하린에게 원본과 함께 전한다.","관직":"품계 대리. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.","일화":"주민대표 날인만 찍힌 종자 출고 요청서가 종자 기록관 당직에 들어온다. 유바영은 박진솔이 함께 요구하는 안전심사 날인 칸이 비었다는 사실을 인수인계 기록 첫 줄에 적고, 요청서와 보존고 열쇠를 한데 묶어 다음 당직에게 건넨다.","관계":"유바영은 종자 출고 요청서의 빈 안전심사 날인 칸을 정하린에게 알리고 해당 기록을 넘긴다. 정하린은 재현 가능한 심사 근거를 확인해, 주민대표 날인만 있는 요청이 반출 근거로 처리되지 않게 한다.","야망":"유바영은 안전심사 날인 칸이 빈 요청서를 다음 당직과 정하린에게 같은 상태로 전달하려 한다.","공포":"주민대표 날인 하나가 교대 사이에 이중 날인으로 읽혀 종자 반출 근거가 되는 것.","개입":"플레이어는 유바영의 인수 첫 줄과 요청서의 빈 칸을 대조해 정하린에게 심사 근거 확인을 요청할 수 있다."},"biography":"가양1동에서 유바영은 종자 원본의 빠진 줄을 먼저 살핀다. 보존고 출고를 재촉받아도 인수 기록과 온습도 장부를 맞춘 뒤 박진솔에게 넘긴다.\n\n- 소속: Arc\n- 생업: 기록·열쇠 인수인계\n- 품계: 대리\n- 직함: 종자 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 유바영은 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 가양1동. 유바영은 가양1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 의심 날인이나 빈 안전심사 칸은 정하린에게 원본과 함께 전한다.\n\n**관직.** 품계 대리. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.\n\n**일화.** 주민대표 날인만 찍힌 종자 출고 요청서가 종자 기록관 당직에 들어온다. 유바영은 박진솔이 함께 요구하는 안전심사 날인 칸이 비었다는 사실을 인수인계 기록 첫 줄에 적고, 요청서와 보존고 열쇠를 한데 묶어 다음 당직에게 건넨다.\n\n**관계.** 유바영은 종자 출고 요청서의 빈 안전심사 날인 칸을 정하린에게 알리고 해당 기록을 넘긴다. 정하린은 재현 가능한 심사 근거를 확인해, 주민대표 날인만 있는 요청이 반출 근거로 처리되지 않게 한다.\n\n**야망.** 유바영은 안전심사 날인 칸이 빈 요청서를 다음 당직과 정하린에게 같은 상태로 전달하려 한다.\n\n**공포.** 주민대표 날인 하나가 교대 사이에 이중 날인으로 읽혀 종자 반출 근거가 되는 것.\n\n**개입.** 플레이어는 유바영의 인수 첫 줄과 요청서의 빈 칸을 대조해 정하린에게 심사 근거 확인을 요청할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 15 | 무력 −20 | 물질 0 | 공동 0 | 원칙 70 | 공개 40 | 자격 40 | 분산 20 | 변혁 10\n- 욕망: 갈망 35 | 독점 35 | 위험 −20 | 과시 −45 | 지속 35 | 지향 유동 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"유바영","type":"계약","to":"정하린","basis":"유바영은 종자 출고 요청서의 빈 안전심사 날인 칸을 정하린에게 알리고 해당 기록을 넘긴다. 정하린은 재현 가능한 심사 근거를 확인해, 주민대표 날인만 있는 요청이 반출 근거로 처리되지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0571', 'b0a8-c758-b839', '{"id":"person-0571","name":"Nam Gaeun","title":"Holding Track Patrol","position":"Holding Track Patrol","rank":"Teacher","commonTier":"T5","occupation":"Guard & Patrol","gender":"Female","stage":"S4","state":"S04","stateName":"Arc","detailRoute":"/people/person-0571","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0571","name":"남가은","title":"유치선 순찰대","position":"유치선 순찰대","rank":"교사","commonTier":"T5","occupation":"경비·순찰","gender":"여성","stage":"S4","state":"S04","stateName":"Arc","detailRoute":"/people/person-0571","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0572', 'c2ec-ccad-c1a1', '{"id":"person-0572","name":"Sim Rahyeon","title":"Gateway Duty Officer","position":"Gateway Duty Officer","rank":"Sergeant","commonTier":"T5","occupation":"Gateway Public Window Reception","gender":"Male","stage":"S4","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0572","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0572","name":"심라현","title":"관문 당직","position":"관문 당직","rank":"병장","commonTier":"T5","occupation":"관문 공개 창구 접수","gender":"남성","stage":"S4","state":"S05","stateName":"동방사","detailRoute":"/people/person-0572","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0573', 'b178-ad50-d558-76e7', '{"id":"person-0573","name":"No Saho","title":"Testimony Scout","position":"Testimony Scout","characterId":"K573","rank":"","commonTier":"T3","occupation":"Public Counter Petition Intake & Referral","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#Person-No-Saho","detailRoute":"/people/person-0573","birthDate":"2095-12-03","birthday":"12-03","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k573-request-routing","name":"Request routing to public desk","rating":45}],"traits":[{"id":"k573-choice","name":"Returns requests to public desks","description":"Anecdote. In 2125 he sent a private petition back and passed it to the public window. By this deed the signature of the testimony surveyor post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125 he sent a private petition back and passed it to the public window. By this deed the signature of the testimony surveyor post rose into the ledger.","stress":"Fear. That the testimony surveyor duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k573-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the testimony surveyor duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. The actual response is not yet recorded.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125 he sent a private petition back and passed it to the public window. By this deed the signature of the testimony surveyor post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28237-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K573","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28237-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"b178-ad50-d558-76e7","name":"Gyoha No Clan","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":5,"Force":-30,"Material":-35,"Communal":20,"Principle":40,"Public":-20,"Eligibility":15,"Dispersed":-30,"Transformative":-20},"desire":{"Longing":-5,"Monopoly":-10,"Risk":0,"Display":25,"Sustained":40,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Livelihood":"Public Counter Petition Intake & Referral","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Testimony Scout","Values":"Authority 15 | Openness 5 | Force −30 | Material −35 | Communal 20 | Principle 40 | Publicity −20 | Qualification 15 | Dispersion −30 | Transformation −20","Desires":"Craving −5 | Monopoly −10 | Risk 0 | Display 25 | Persistence 40 | Orientation Fluid | Union Monogamy"},"sections":{"Life":"Grew up at the Waiting Hall shift. The Testimony Surveyor post opened as a substitute shift for an unauthorized absence from the rotation.\n- No Saho''s work of receiving and redirecting petitions at the public window is connected to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"The grade appropriate to a post in a Seoul Metropolitan Government headquarters or office, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.","Anecdote":"In 2125, turned away a private petition and sent it to the public window. Because of this, the signature for the Testimony Surveyor post was entered in the ledger.","Relationships":"Through the handover of the work of receiving and redirecting petitions at the public window, connected to senior shift-holders of the same living sphere.","Ambition":"From the Testimony Surveyor post, continues the records of receiving and redirecting petitions at the public window so that the ledger of the Seoul Metropolitan Local Civil Service Organization is not broken between shifts.","Fear":"That the Testimony Surveyor shift will fall vacant, breaking the seals and rosters of downtown passage tied to the work of receiving and redirecting petitions at the public window, and halting even the ratification of the factions of the Seoul Metropolitan Local Civil Service Organization that rely on those records.","Intervention":"Can bring in a witness to the shift handover of the work of receiving and redirecting petitions at the public window, or expose the empty key of that post."},"biography":"Trusts the single line left at the public window over private petitions. Keeping the shifts connected also begins with not letting go of that ledger.\n\n- Livelihood: Receiving and redirecting petitions at the public window\n- Affiliation: Seoul Metropolitan Local Civil Service Organization\n- Position and Grade: Whichever grade fits a post at the Seoul Metropolitan headquarters or field offices among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Duties: Testimony Surveyor\n**Life.** Grew up at the Waiting Hall shift. The Testimony Surveyor post opened as a substitute shift for an unauthorized absence from the rotation.\n- No Saho''s work of receiving and redirecting petitions at the public window is connected to Jongno 1·2·3·4-ga-dong.\n\n**Civil Service Position and Grade.** Whichever grade fits a post at the Seoul Metropolitan headquarters or field offices among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Testimony Surveyor.\n\n**Anecdote.** In 2125, turned away a private petition and sent it to the public window. Because of this, the signature for the Testimony Surveyor post was entered in the ledger.\n\n**Relationships.** Through the handover of the work of receiving and redirecting petitions at the public window, connected to senior shift-holders of the same living sphere.\n\n**Ambition.** From the Testimony Surveyor post, continues the records of receiving and redirecting petitions at the public window so that the ledger of the Seoul Metropolitan Local Civil Service Organization is not broken between shifts.\n\n**Fear.** That the Testimony Surveyor shift will fall vacant, breaking the seals and rosters of downtown passage tied to the work of receiving and redirecting petitions at the public window, and halting even the ratification of the factions of the Seoul Metropolitan Local Civil Service Organization that rely on those records.\n\n**Intervention.** Can bring in a witness to the shift handover of the work of receiving and redirecting petitions at the public window, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness 5 | Force −30 | Material −35 | Communal 20 | Principle 40 | Publicity −20 | Qualification 15 | Dispersion −30 | Transformation −20\n- Desires: Craving −5 | Monopoly −10 | Risk 0 | Display 25 | Persistence 40 | Orientation Fluid | Union Monogamy\n:::","relations":{"outgoing":[{"from":"No Saho","type":"Contract","to":"Seol Dahin","basis":"No Saho passes to Seol Dahin the intake details and testimony of the solicitation redirected to the public window. Seol Dahin obtains the confirmations needed for the notarization window and the medical waiting tickets, so that no private transfer request is processed ahead of the patient queue."}],"incoming":[]}}', '{"id":"person-0573","name":"노사호","title":"증언 탐사원","position":"증언 탐사원","characterId":"K573","rank":"","commonTier":"T3","occupation":"공개 창구 청탁 접수·회송","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-노사호","detailRoute":"/people/person-0573","birthDate":"2095-12-03","birthday":"12-03","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k573-request-routing","name":"청탁 창구 회송","rating":45}],"traits":[{"id":"k573-choice","name":"공개 창구로 돌림","description":"일화. 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","stress":"공포. 증언 탐사원 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k573-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 증언 탐사원 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-gu-28237-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K573","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-gu-28237-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"b178-ad50-d558-76e7","name":"교하 노씨","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":5,"무력":-30,"물질":-35,"공동":20,"원칙":40,"공개":-20,"자격":15,"분산":-30,"변혁":-20},"desire":{"갈망":-5,"독점":-10,"위험":0,"과시":25,"지속":40,"지향":"유동","결합":"단혼"},"fields":{"생업":"공개 창구 청탁 접수·회송","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"증언 탐사원","가치관":"권위 15 | 개방 5 | 무력 −30 | 물질 −35 | 공동 20 | 원칙 40 | 공개 −20 | 자격 15 | 분산 −30 | 변혁 −20","욕망":"갈망 −5 | 독점 −10 | 위험 0 | 과시 25 | 지속 40 | 지향 유동 | 결합 단혼"},"sections":{"생애":"대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 노사호의 공개 창구 청탁 접수·회송 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.","관계":"공개 창구 청탁 접수·회송 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"증언 탐사원 자리에서 공개 창구 청탁 접수·회송 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"증언 탐사원 당직이 비어 공개 창구 청탁 접수·회송 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.","개입":"공개 창구 청탁 접수·회송 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"사적 청탁보다 공개 창구에 남는 한 줄을 믿는다. 당직을 잇는 일도 그 장부를 놓지 않는 데서 시작한다.\n\n- 생업: 공개 창구 청탁 접수·회송\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 증언 탐사원\n**생애.** 대합실 당직에서 자랐다. 증언 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 노사호의 공개 창구 청탁 접수·회송 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 증언 탐사원.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 증언 탐사원 자리의 서명이 장부에 올랐다.\n\n**관계.** 공개 창구 청탁 접수·회송 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 증언 탐사원 자리에서 공개 창구 청탁 접수·회송 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**공포.** 증언 탐사원 당직이 비어 공개 창구 청탁 접수·회송 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.\n\n**개입.** 공개 창구 청탁 접수·회송 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 5 | 무력 −30 | 물질 −35 | 공동 20 | 원칙 40 | 공개 −20 | 자격 15 | 분산 −30 | 변혁 −20\n- 욕망: 갈망 −5 | 독점 −10 | 위험 0 | 과시 25 | 지속 40 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"노사호","type":"계약","to":"설다흰","basis":"노사호는 공개 창구로 돌린 청탁의 접수 내용과 증언을 설다흰에게 전한다. 설다흰은 공증 창구와 의무 대기표에 필요한 확인을 받아, 사적인 이송 요청이 환자 대기열보다 먼저 처리되지 않게 한다."}],"incoming":[]}}');
