INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0576', 'cangnyeong-seong-yeolcha', '{"id":"person-0576","name":"Seong Eunhyeon","title":"Stand-In Courier","position":"Currency Exchange Courier","rank":"Clerk","commonTier":"T5","occupation":"Currency Exchange Courier Takeover and Ledger Delivery","gender":"Female","stage":"S4","state":"S09","stateName":"Yeouido Investors'' Association","detailRoute":"/people/person-0576","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0576","name":"성은현","title":"대역 전령","position":"환전 전령","rank":"서기","commonTier":"T5","occupation":"환전 전령 인수·장부 전달","gender":"여성","stage":"S4","state":"S09","stateName":"여의도출자연합회","detailRoute":"/people/person-0576","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0577', 'cc28-c5f0-c548', '{"id":"person-0577","name":"Cha Namwon","title":"Refugee Recorder","position":"Scripture Transcription Acolyte","characterId":"K577","rank":"Postulant","commonTier":"T5","occupation":"Transcribed Scripture and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#Person-Cha-Namwon","detailRoute":"/people/person-0577","birthDate":"2068-04-18","birthday":"04-18","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"vote-comparison","name":"Community vote-total comparison","rating":50}],"traits":[{"id":"vote-comparison-disposition","name":"Checks own vote too","description":"Checks personal vote records against the transcript too.","behavior":"Checks personal vote records against the transcript too.","stress":"Is wary of transcripts diverging from assembly votes.","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]},{"id":"recorded-boundary","name":"Hands over comparison copy","description":"Hands over the vote comparison with the keys.","behavior":"Hands over the vote comparison with the keys.","stress":"Is wary of transcripts diverging from assembly votes.","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]}],"narrative":"Compared posted and copied vote totals by community and checked personal voting records, handing the comparison over with duty keys.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-60,"Openness":80,"Force":-35,"Material":-20,"Communal":75,"Principle":50,"Public":30,"Eligibility":30,"Dispersed":55,"Transformative":5},"desire":{"Longing":-15,"Monopoly":-5,"Risk":-35,"Display":-30,"Sustained":60,"Orientation":"Bisexual","Union":"None"},"fields":{"Livelihood":"Transcribed Scripture and Duty Keys Handover","Affiliation":"The Government","Rank":"Postulant","Title":"Scripture Transcription Acolyte","Values":"Authority −60 | Openness 80 | Force −35 | Materialism −20 | Communal 75 | Principle 50 | Publicity 30 | Qualification 30 | Decentralization 55 | Transformation 5","Desires":"Craving −15 | Monopoly −5 | Risk −35 | Display −30 | Persistence 60 | Orientation Bisexual | Bonding None"},"sections":{"Life":"Born 2068-04-18, active at the 2126 opening. Grew up at the Seoul Station Registry Office. The Scripture Transcription Postulant duty log records a day when one line of a double ledger was deleted.\n- Jongno 1·2·3·4-ga-dong is proposed as the reference point for Cha Namwon''s work of handing over scripture transcripts and duty keys. It does not confirm his current posting, residence, estate, or ownership.","Offices":"Rank: Postulant. Title: Scripture Transcription Postulant. He hands over only the keys and transcripts of his own duty and creates no authority that he does not have. He casts his vote only at the Mountain General Assembly.","Anecdote":"On the evening the Mountain General Assembly vote ends, the per-clan results that Yun Choa will post that day come down to the transcription duty. Cha Namwon copies them over, matching the vote counts of the posted copy and the transcript for each clan, cross-checks the lines against the Mountain General Assembly record in which he cast his own vote, and hands over that cross-checked copy when he hands over the duty keys.","Relationships":"Cha Namwon receives the last line of a senior duty''s ledger and begins the next shift''s record.","Ambition":"He keeps the transcription order of scriptures and ledgers so that the voting record continues alongside the original.","Fear":"That the vote lines and the supply lines will get mixed up in the gap between duties.","Intervention":"He can hand over the vote copy and the supply ledger separately, or call a shift witness."},"biography":"For vote results, he matches the per-clan lines and the transcript in turn. When he hands over the keys, he hands over the cross-checked copy as well.\n\n- Livelihood: Scripture transcript and duty key handover\n- Affiliation: The Government\n- Rank: Postulant\n- Title: Scripture Transcription Postulant\n**Life.** Born 2068-04-18, active at the 2126 opening. Grew up at the Seoul Station Registry Office. The Scripture Transcription Postulant duty log records a day when one line of a double ledger was deleted.\n- Jongno 1·2·3·4-ga-dong is proposed as the reference point for Cha Namwon''s work of handing over scripture transcripts and duty keys. It does not confirm his current posting, residence, estate, or ownership.\n\n**Office.** Rank: Postulant. Title: Scripture Transcription Postulant. He hands over only the keys and transcripts of his own duty and creates no authority that he does not have. He casts his vote only at the Mountain General Assembly.\n\n**Anecdote.** On the evening the Mountain General Assembly vote ends, the per-clan results that Yun Choa will post that day come down to the transcription duty. Cha Namwon copies them over, matching the vote counts of the posted copy and the transcript for each clan, cross-checks the lines against the Mountain General Assembly record in which he cast his own vote, and hands over that cross-checked copy when he hands over the duty keys.\n\n**Relationships.** Cha Namwon receives the last line of a senior duty''s ledger and begins the next shift''s record.\n\n**Ambition.** He keeps the transcription order of scriptures and ledgers so that the voting record continues alongside the original.\n\n**Fear.** That the vote lines and the supply lines will get mixed up in the gap between duties.\n\n**Intervention.** He can hand over the vote copy and the supply ledger separately, or call a shift witness.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −60 | Openness 80 | Force −35 | Materialism −20 | Communal 75 | Principle 50 | Publicity 30 | Qualification 30 | Decentralization 55 | Transformation 5\n- Desires: Craving −15 | Monopoly −5 | Risk −35 | Display −30 | Persistence 60 | Orientation Bisexual | Bonding None\n:::","relations":{"outgoing":[{"from":"Cha Namwon","type":"Contract","to":"Yun Choa","basis":"After the Mountain Convocation vote, Cha Namwon hands Yun Choa a record comparing the posted copy with the transcribed copy. Yun Choa posts the results by clan the same day and checks the differences, so that the next transcription watch does not carry forward wrong vote counts."}],"incoming":[]}}', '{"id":"person-0577","name":"차남원","title":"피난 기록관","position":"장경 필사 행자","characterId":"K577","rank":"행자","commonTier":"T5","occupation":"장경 필사본·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-차남원","detailRoute":"/people/person-0577","birthDate":"2068-04-18","birthday":"04-18","age":58,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"vote-comparison","name":"문중 표 수 대조","rating":50}],"traits":[{"id":"vote-comparison-disposition","name":"자기 표도 대조","description":"자기 투표 기록까지 필사본과 맞춘다.","behavior":"자기 투표 기록까지 필사본과 맞춘다.","stress":"필사본과 총회 표가 어긋날 것을 경계한다.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"recorded-boundary","name":"대조본 인계","description":"열쇠를 넘길 때 표 수 대조본도 건넨다.","behavior":"열쇠를 넘길 때 표 수 대조본도 건넨다.","stress":"장경 필사 행자 당직이 비면 안국총림의 필사본이 끊기고 문중 표가 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"총회 표결 뒤 게시본과 필사본의 표 수를 문중마다 맞추고 자기 투표 기록과 대조했다. 대조본을 열쇠와 함께 인계한다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-60,"개방":80,"무력":-35,"물질":-20,"공동":75,"원칙":50,"공개":30,"자격":30,"분산":55,"변혁":5},"desire":{"갈망":-15,"독점":-5,"위험":-35,"과시":-30,"지속":60,"지향":"양성","결합":"없음"},"fields":{"생업":"장경 필사본·당직 열쇠 인계","소속":"정부","품계":"행자","직함":"장경 필사 행자","가치관":"권위 −60 | 개방 80 | 무력 −35 | 물질 −20 | 공동 75 | 원칙 50 | 공개 30 | 자격 30 | 분산 55 | 변혁 5","욕망":"갈망 −15 | 독점 −5 | 위험 −35 | 과시 −30 | 지속 60 | 지향 양성 | 결합 없음"},"sections":{"생애":"2068-04-18 출생, 2126년 개막에 활동했다. 서울역 등기소에서 자랐다. 장경 필사 행자 당직 기록에는 이중 장부 한 줄 삭제 일이 남아 있다.\n- 차남원의 장경 필사본·당직 열쇠 인계 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 행자. 직함은 장경 필사 행자. 자기 당직의 열쇠와 필사본만 넘기고, 없는 권한은 만들지 않는다. 표는 산중총회에서만 던진다.","일화":"산중총회 표결이 끝난 저녁, 윤초아가 당일 게시할 문중별 결과가 필사 당직으로 내려온다. 차남원은 게시본과 필사본의 표 수를 문중마다 맞춰 옮기고, 자기 표를 던진 산중총회 기록과도 줄을 대조한 뒤, 당직 열쇠를 넘길 때 그 대조본도 건넨다.","관계":"차남원은 선배 당직의 장부 끝줄을 받아 다음 교대 기록을 시작한다.","야망":"경전과 장부의 필사 순서를 지켜 표결 기록이 원본과 함께 이어지게 한다.","공포":"당직 공백 사이에 표결 줄과 물자 줄이 뒤섞이는 것.","개입":"표결 사본과 물자 장부를 분리해 건네거나 교대 증인을 세울 수 있다."},"biography":"표결 결과는 문중별 줄과 필사본을 차례로 맞춘다. 열쇠를 넘길 때 대조본도 함께 건넨다.\n\n- 생업: 장경 필사본·당직 열쇠 인계\n- 소속: 정부\n- 품계: 행자\n- 직함: 장경 필사 행자\n**생애.** 2068-04-18 출생, 2126년 개막에 활동했다. 서울역 등기소에서 자랐다. 장경 필사 행자 당직 기록에는 이중 장부 한 줄 삭제 일이 남아 있다.\n- 차남원의 장경 필사본·당직 열쇠 인계 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 행자. 직함은 장경 필사 행자. 자기 당직의 열쇠와 필사본만 넘기고, 없는 권한은 만들지 않는다. 표는 산중총회에서만 던진다.\n\n**일화.** 산중총회 표결이 끝난 저녁, 윤초아가 당일 게시할 문중별 결과가 필사 당직으로 내려온다. 차남원은 게시본과 필사본의 표 수를 문중마다 맞춰 옮기고, 자기 표를 던진 산중총회 기록과도 줄을 대조한 뒤, 당직 열쇠를 넘길 때 그 대조본도 건넨다.\n\n**관계.** 차남원은 선배 당직의 장부 끝줄을 받아 다음 교대 기록을 시작한다.\n\n**야망.** 경전과 장부의 필사 순서를 지켜 표결 기록이 원본과 함께 이어지게 한다.\n\n**공포.** 당직 공백 사이에 표결 줄과 물자 줄이 뒤섞이는 것.\n\n**개입.** 표결 사본과 물자 장부를 분리해 건네거나 교대 증인을 세울 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −60 | 개방 80 | 무력 −35 | 물질 −20 | 공동 75 | 원칙 50 | 공개 30 | 자격 30 | 분산 55 | 변혁 5\n- 욕망: 갈망 −15 | 독점 −5 | 위험 −35 | 과시 −30 | 지속 60 | 지향 양성 | 결합 없음\n:::","relations":{"outgoing":[{"from":"차남원","type":"계약","to":"윤초아","basis":"차남원은 산중총회 표결 뒤 게시본과 필사본을 대조한 기록을 윤초아에게 넘긴다. 윤초아는 문중별 결과를 당일 게시하며 그 차이를 확인해, 다음 필사 당직이 틀린 표 수를 이어 쓰지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0578', 'c8fc-c2e0-c548', '{"id":"person-0578","name":"Ju Neurin","title":"Escort Courier","position":"Gangnam Station Escort Courier","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station Escort Records and Keys Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0578","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0578","name":"주늘인","title":"호송 전령","position":"강남역 호송 전령","rank":"사원","commonTier":"T5","occupation":"강남역 호송 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0578","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0579', 'c6b0-b2e8-c591', '{"id":"person-0579","name":"U Dalmin","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0579","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0579","name":"우달민","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0579","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0580', 'ad6c-d3c9-d574-4e18', '{"id":"person-0580","name":"Gu Reumgyeol","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K580","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-gureumgyeol","detailRoute":"/people/person-0580","birthDate":"2072-06-20","birthday":"06-20","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"Public desk referral","rating":40}],"traits":[{"id":"stated-priority","name":"Redirects to public procedure","description":"A private request was sent to the public desk. This short episode does not establish broad negotiation success or prescribing ability.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A private request was sent to the public desk. This short episode does not establish broad negotiation success or prescribing ability.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-d3c9-d574-4e18","name":"Pyeonghae Gu Clan","crest":"clan-crests/ad6c-d3c9-d574-4e18.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":20,"Force":-60,"Material":-30,"Communal":20,"Principle":35,"Public":10,"Eligibility":15,"Dispersed":25,"Transformative":-10},"desire":{"Longing":0,"Monopoly":30,"Risk":-40,"Display":20,"Sustained":35,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −15 | Openness 20 | Force −60 | Materialism −30 | Communal 20 | Principle 35 | Publicity 10 | Qualification 15 | Decentralization 25 | Transformation −10","Desires":"Craving 0 | Monopoly 30 | Risk −40 | Display 20 | Persistence 35 | Orientation Bisexual | Bonding Non-exclusive"},"sections":{"Life":"Born 2072-06-20. At the 2126 opening, he holds the Prescription Clerk post and carries on the existing duty and records. The succession record of that post shows it opened as a substitute duty for an unexcused absence from a shift.\n- The prescription record and duty key handover counter in Jegi-dong is Gureumgyeol''s work reference point. This work reference point does not confirm a residence, exact facility boundaries, a title, an estate, or a right of possession.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In 2125, he turned away a private solicitation and sent it to the public counter. That day''s record remained as grounds for handover for the next duty holder to verify.","Relationships":"Gureumgyeol redirects requests to change the treatment order to the public desk and passes the prescription records and request details to Eun Chaeyun. Eun Chaeyun assigns by clinical findings and the triage chart so that a request does not push aside the turn of a more critical patient.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the duty chain. He trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Prescription record and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Prescription Clerk\n**Life.** Born 2072-06-20. At the 2126 opening, he holds the Prescription Clerk post and carries on the existing duty and records. The succession record of that post shows it opened as a substitute duty for an unexcused absence from a shift.\n- The prescription record and duty key handover counter in Jegi-dong is Gureumgyeol''s work reference point. This work reference point does not confirm a residence, exact facility boundaries, a title, an estate, or a right of possession.\n\n**Office.** Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes the time of receipt for the keys and records handed over in the ledger.\n\n**Anecdote.** In 2125 he sent back a private solicitation and directed it to the public counter. That day''s record remained as the handover basis for the next duty to check.\n\n**Relationships.** Gureumgyeol redirects requests to change treatment order to the public counter and passes the prescription records and the content of the request to Eun Chaeyun. Eun Chaeyun assigns by clinical findings and a severity chart, so that no solicitation pushes aside the turn of a more critical patient.\n\n**Ambition.** From the Prescription Resident seat, he keeps the White Cross Order''s ledger connected without a break.\n\n**Fear.** He fears that if the Prescription Resident duty goes unfilled, the White Cross Order''s passage will become a hostage of Seoul''s internal patron powers.\n\n**Intervention.** He can call a duty handover witness or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 20 | Force −60 | Materialism −30 | Communal 20 | Principle 35 | Publicity 10 | Qualification 15 | Decentralization 25 | Transformation −10\n- Desires: Craving 0 | Monopoly 30 | Risk −40 | Display 20 | Persistence 35 | Orientation Bisexual | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Gu Reumgyeol","type":"Contract","to":"Eun Chaeyun","basis":"Gureumgyeol redirects requests to change the treatment order to the public desk and passes the prescription records and request details to Eun Chaeyun. Eun Chaeyun assigns by clinical findings and the triage chart so that a request does not push aside the turn of a more critical patient."}],"incoming":[]}}', '{"id":"person-0580","name":"구름결","title":"처방 서기","position":"처방 서기","characterId":"K580","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-구름결","detailRoute":"/people/person-0580","birthDate":"2072-06-20","birthday":"06-20","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"창구 안내","rating":40}],"traits":[{"id":"stated-priority","name":"공개 절차로 돌려보낸다","description":"청탁을 돌려보내 공개 창구를 쓰게 했다. 개인 교섭 성공이나 처방 능력의 폭은 짧은 일화로 판단할 수 없다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"청탁을 돌려보내 공개 창구를 쓰게 했다. 개인 교섭 성공이나 처방 능력의 폭은 짧은 일화로 판단할 수 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ad6c-d3c9-d574-4e18","name":"평해 구씨","crest":"clan-crests/ad6c-d3c9-d574-4e18.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":20,"무력":-60,"물질":-30,"공동":20,"원칙":35,"공개":10,"자격":15,"분산":25,"변혁":-10},"desire":{"갈망":0,"독점":30,"위험":-40,"과시":20,"지속":35,"지향":"양성","결합":"비독점"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −15 | 개방 20 | 무력 −60 | 물질 −30 | 공동 20 | 원칙 35 | 공개 10 | 자격 15 | 분산 25 | 변혁 −10","욕망":"갈망 0 | 독점 30 | 위험 −40 | 과시 20 | 지속 35 | 지향 양성 | 결합 비독점"},"sections":{"생애":"2072-06-20에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 구름결의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"구름결은 치료 순서를 바꿔 달라는 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록과 요청 내용을 전한다. 은채윤은 진료 소견과 중증도 표로 배정해, 청탁이 더 위중한 환자의 순서를 밀어내지 않게 한다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2072-06-20에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구가 구름결의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 구름결은 치료 순서를 바꿔 달라는 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록과 요청 내용을 전한다. 은채윤은 진료 소견과 중증도 표로 배정해, 청탁이 더 위중한 환자의 순서를 밀어내지 않게 한다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 20 | 무력 −60 | 물질 −30 | 공동 20 | 원칙 35 | 공개 10 | 자격 15 | 분산 25 | 변혁 −10\n- 욕망: 갈망 0 | 독점 30 | 위험 −40 | 과시 20 | 지속 35 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"구름결","type":"계약","to":"은채윤","basis":"구름결은 치료 순서를 바꿔 달라는 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록과 요청 내용을 전한다. 은채윤은 진료 소견과 중증도 표로 배정해, 청탁이 더 위중한 환자의 순서를 밀어내지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0581', 'bbfc-c5ec-d765-9594', '{"id":"person-0581","name":"Min Bahyeon","title":"Ridge Patrol","position":"Agwansa Ridge Patrol","rank":"Sergeant","commonTier":"T5","occupation":"Ridge Patrol Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0581","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0581","name":"민바현","title":"능선 순찰대","position":"아관사 능선 순찰대","rank":"병장","commonTier":"T5","occupation":"능선 순찰 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0581","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0582', 'c9c4-d48d-ae30', '{"id":"person-0582","name":"Jin Dollin","title":"Warehouse Duty Officer","position":"Myeongdong Station Confirmation Roster Duty Officer","rank":"Congregationioner","commonTier":"T5","occupation":"Confirmation Roster Handover Record","gender":"Female","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0582","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0582","name":"진돌린","title":"창고 당직","position":"명동역 인준 명부 당직","rank":"교우","commonTier":"T5","occupation":"인준 명부 인수인계 기록","gender":"여성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0582","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
