INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0595', 'c11c-b2ec-c131', '{"id":"person-0595","name":"Seo Rameun","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0595","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0595","name":"서람은","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0595","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0596', 'c2e0-d3c9-c0b0', '{"id":"person-0596","name":"Sin Nabin","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K596","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-sinnabin","detailRoute":"/people/person-0596","birthDate":"2084-04-01","birthday":"04-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"Payment ledger reconciliation","rating":50}],"traits":[{"id":"stated-priority","name":"Signs corrections","description":"A duplicate payment was reconciled, removed, and signed. This is a narrow record-handling strength, not sanitation expertise bestowed by title.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A duplicate payment was reconciled, removed, and signed. This is a narrow record-handling strength, not sanitation expertise bestowed by title.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2e0-d3c9-c0b0","name":"Pyeongsan Sin Clan","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":35,"Force":-75,"Material":-10,"Communal":25,"Principle":55,"Public":30,"Eligibility":15,"Dispersed":25,"Transformative":-15},"desire":{"Longing":5,"Monopoly":35,"Risk":25,"Display":-30,"Sustained":5,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −25 | Openness 35 | Force −75 | Materiality −10 | Communality 25 | Principle 55 | Publicity 30 | Qualification 15 | Dispersion 25 | Transformation −15","Desires":"Craving 5 | Exclusivity 35 | Risk 25 | Display −30 | Persistence 5 | Orientation Fluid | Union Contract Cohabitation"},"sections":{"Life":"Born on 2084-04-01. As of the 2126 opening, holds the post of Quarantine Records Officer, continuing the existing duty roster and records. The succession record for this post shows it opened through the deletion of a single line in the double ledger.\n- The quarantine records and duty-key handover window in Jegi-dong is Sin Na-bin''s work reference point. This work reference point does not fix a residence, exact facility boundaries, noble title, fief, or holding rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.","Relationships":"Sin Nabin passes Su Chorong the signature that corrected the double payment in the quarantine ledger. Su Chorong examines the quarantine entry stamps and on-site checks to find places where the same entry or release was recorded twice, and does not make release rounds before the water-quality and efficacy records.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first to keep the duty roster unbroken. Trusts a single ledger line over loud talk.\n\n- Livelihood: Quarantine records and duty-key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Quarantine Records Officer\n**Life.** Born on 2084-04-01. As of the 2126 opening, holds the post of Quarantine Records Officer, continuing the existing duty roster and records. The succession record for this post shows it opened through the deletion of a single line in the double ledger.\n- The quarantine records and duty-key handover window in Jegi-dong is Sin Na-bin''s work reference point. This work reference point does not fix a residence, exact facility boundaries, noble title, fief, or holding rights.\n\n**Office.** Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for each key and record handed over.\n\n**Anecdote.** In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.\n\n**Relations.** Sin Na-bin passes the signature that corrected the double payment in the quarantine ledger to Su Cho-rong. Su Cho-rong examines the quarantine entry stamps and on-site confirmations to find where the same entry or release was recorded twice, and does not make release patrols before the water-quality and drug-efficacy records are in.\n\n**Ambition.** From the post of Quarantine Resident, to keep the White Cross Order''s ledger continuously connected.\n\n**Fear.** Fears that if the Quarantine Resident''s duty post is left empty, the White Cross Order''s passage will become a hostage to Seoul''s internal patron factions.\n\n**Intervention.** Can arrange a witness for the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 35 | Force −75 | Materiality −10 | Communality 25 | Principle 55 | Publicity 30 | Qualification 15 | Dispersion 25 | Transformation −15\n- Desires: Craving 5 | Exclusivity 35 | Risk 25 | Display −30 | Persistence 5 | Orientation Fluid | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Sin Nabin","type":"Contract","to":"Su Choreong","basis":"Sin Nabin passes Su Chorong the signature that corrected the double payment in the quarantine ledger. Su Chorong examines the quarantine entry stamps and on-site checks to find places where the same entry or release was recorded twice, and does not make release rounds before the water-quality and efficacy records."}],"incoming":[]}}', '{"id":"person-0596","name":"신나빈","title":"방역 기록관","position":"방역 기록관","characterId":"K596","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-신나빈","detailRoute":"/people/person-0596","birthDate":"2084-04-01","birthday":"04-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"지급 장부 대조","rating":50}],"traits":[{"id":"stated-priority","name":"수정에 서명을 남긴다","description":"이중 지급을 대조해 한 줄을 지우고 서명했다. 기록 처리의 좁은 강점이며 방역 전문성은 직함에서 부여하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"이중 지급을 대조해 한 줄을 지우고 서명했다. 기록 처리의 좁은 강점이며 방역 전문성은 직함에서 부여하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2e0-d3c9-c0b0","name":"평산 신씨","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":35,"무력":-75,"물질":-10,"공동":25,"원칙":55,"공개":30,"자격":15,"분산":25,"변혁":-15},"desire":{"갈망":5,"독점":35,"위험":25,"과시":-30,"지속":5,"지향":"유동","결합":"계약동거"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −25 | 개방 35 | 무력 −75 | 물질 −10 | 공동 25 | 원칙 55 | 공개 30 | 자격 15 | 분산 25 | 변혁 −15","욕망":"갈망 5 | 독점 35 | 위험 25 | 과시 −30 | 지속 5 | 지향 유동 | 결합 계약동거"},"sections":{"생애":"2084-04-01에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 신나빈의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"신나빈은 방역 장부의 이중 지급을 정정한 서명을 수초롱에게 전한다. 수초롱은 격리 출입 도장과 현장 확인을 살펴 같은 출입이나 해제가 중복 기록된 곳을 찾고, 수질·약효 기록 전에는 해제 순찰을 돌지 않는다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2084-04-01에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 신나빈의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 신나빈은 방역 장부의 이중 지급을 정정한 서명을 수초롱에게 전한다. 수초롱은 격리 출입 도장과 현장 확인을 살펴 같은 출입이나 해제가 중복 기록된 곳을 찾고, 수질·약효 기록 전에는 해제 순찰을 돌지 않는다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 35 | 무력 −75 | 물질 −10 | 공동 25 | 원칙 55 | 공개 30 | 자격 15 | 분산 25 | 변혁 −15\n- 욕망: 갈망 5 | 독점 35 | 위험 25 | 과시 −30 | 지속 5 | 지향 유동 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"신나빈","type":"계약","to":"수초롱","basis":"신나빈은 방역 장부의 이중 지급을 정정한 서명을 수초롱에게 전한다. 수초롱은 격리 출입 도장과 현장 확인을 살펴 같은 출입이나 해제가 중복 기록된 곳을 찾고, 수질·약효 기록 전에는 해제 순찰을 돌지 않는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0597', 'ad8c-c548-b3d9', '{"id":"person-0597","name":"Gwon Mayun","title":"Quarantine Clerk","position":"Guui Garrison Quarantine Clerk","rank":"Garrison Soldier","commonTier":"T5","occupation":"Quarantine Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0597","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0597","name":"권마윤","title":"검역 서기","position":"구의수비대 검역 서기","rank":"수비대원","commonTier":"T5","occupation":"검역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0597","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0598', 'd669-d68c-b355-9ec3', '{"id":"person-0598","name":"Hwang Ajin","title":"Auction Clerk","position":"Myeongdong Station Election Records Clerk","rank":"Congregationioner","commonTier":"T5","occupation":"Election Records and Handover Log","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0598","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0598","name":"황아진","title":"경매 서기","position":"명동역 선거 기록 서기","rank":"교우","commonTier":"T5","occupation":"선거 기록·인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0598","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0599', 'c548-c21c-d765', '{"id":"person-0599","name":"An Kamin","title":"Audit Recorder","position":"Audit Recorder","characterId":"K599","rank":"Unregistered","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#person-an-ka-min","detailRoute":"/people/person-0599","birthDate":"2073-09-21","birthday":"09-21","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":6,"effective":6},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"membership-comparison","name":"Membership register comparison","rating":60}],"traits":[{"id":"evidenced-choice","name":"Compares against originals","description":"Matched faction lists name by name to the original, separated duplicates and omissions, and handed over the comparison. No authority or achievement beyond these actions is granted.","behavior":"The recorded choice shows this disposition within its context; it is not established for every situation.","stress":"May recheck originals and handovers when shifts are blocked or records disappear.","relationship":"Hands keys and records to the next duty worker and watches for factional obstruction.","effects":[]},{"id":"handover-continuity","name":"Concern for record continuity","description":"Seeks continuity of the specific records entrusted to this person, rather than new authority.","behavior":"Seeks to check the continuity of assigned records and signatures.","stress":"Loss of the assigned records or a blocked handover may heighten concern about accountability.","relationship":"Hands keys and records to the next duty worker and watches for factional obstruction.","effects":[]}],"narrative":"Matched faction lists name by name to the original, separated duplicates and omissions, and handed over the comparison. No authority or achievement beyond these actions is granted.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":20,"Force":-35,"Material":0,"Communal":15,"Principle":40,"Public":30,"Eligibility":15,"Dispersed":45,"Transformative":5},"desire":{"Longing":20,"Monopoly":30,"Risk":30,"Display":-30,"Sustained":-20,"Orientation":"None","Union":"Non-Exclusive"},"fields":{"Livelihood":"Audit Log and Duty Key Handover","Affiliation":"Arc","Community Role":"Guild Member","Duty":"Audit Recorder","Values":"Authority −25 | Openness 20 | Force −35 | Materiality 0 | Communality 15 | Principle 40 | Publicity 30 | Qualification 15 | Dispersion 45 | Transformation 5","Desires":"Craving 20 | Exclusivity 30 | Risk 30 | Display −30 | Persistence −20 | Orientation No Orientation | Union Non-Exclusive"},"sections":{"Life":"Born on 2073-09-21, An Ka-min handles Audit Records Officer duties at the Sicheong Station union workshop in the Permanent Winter. Checks the members'' direct election and public vote records, distinguishing offices conferred by the Government from community duties.\n- An Ka-min handles Audit Records Officer duties at the Sicheong Station union workshop in Sogong-dong. This work reference point does not fix a residence, exact facility boundaries, noble title, fief, or holding rights.","Duty":"The community role is union member, and the duty is Audit Records Officer. This duty is an internal function of the Jeongdong General Labor Federation, not The Government civil service office or a feudal rank.","Anecdote":"Ahead of the direct election of the chairperson, the workshop faction and the line faction submit different member lists to the audit duty. An Ka-min cross-checks both lists against the original member roster name by name, records the overlapping names and the missing names separately, and hands the cross-check table and the duty key to the next audit duty officer.","Relationships":"An Ka-min''s existing relationship record is as follows. Bound by handover to a senior on duty in the same work and living sphere.","Goals":"An Ka-min seeks to keep the signing, handover, and disclosure procedures of the Audit Records Officer''s work verifiable in the Sicheong Station union ledger.","Fear":"The fear that the signatures or handover records of the Audit Records Officer''s work will be altered, collapsing An Ka-min''s scope of responsibility and the members'' disclosure procedures together.","Intervention":"An Ka-min can cross-check the relevant signatures and handover times and make the records public, but cannot grant new offices, ranks, rights, or fiefs."},"biography":"At the Sicheong Station union workshop in the Permanent Winter, An Ka-min first cross-checks the Audit Records Officer''s work records against the signatures on public votes. On days when water supply, passage, and contract schedules overlap, records receipt times and handover order in the same ledger.\n\n- Livelihood: Audit records and duty-key handover\n- Affiliation: Jeongdong General Labor Federation\n- Community Role: Union member\n- Duty: Audit Records Officer\n**Life.** Born on 2073-09-21, An Ka-min handles Audit Records Officer duties at the Sicheong Station union workshop in the Permanent Winter. Checks the members'' direct election and public vote records, distinguishing offices conferred by the Government from community duties.\n- An Ka-min handles Audit Records Officer duties at the Sicheong Station union workshop in Sogong-dong. This work reference point does not fix a residence, exact facility boundaries, noble title, fief, or holding rights.\n\n**Duty.** The community role is union member, and the duty is Audit Records Officer. This duty is an internal function of the Jeongdong General Labor Federation, not The Government civil service office or a feudal rank.\n\n**Anecdote.** Ahead of the direct election of the chairperson, the workshop faction and the line faction submit different member lists to the audit duty. An Ka-min cross-checks both lists against the original member roster name by name, records the overlapping names and the missing names separately, and hands the cross-check table and the duty key to the next audit duty officer.\n\n**Relations.** An Ka-min''s existing relationship record is as follows. Bound by handover to a senior on duty in the same work and living sphere.\n\n**Goal.** An Ka-min seeks to keep the signing, handover, and disclosure procedures of the Audit Records Officer''s work verifiable in the Sicheong Station union ledger.\n\n**Fear.** The fear that the signatures or handover records of the Audit Records Officer''s work will be altered, collapsing An Ka-min''s scope of responsibility and the members'' disclosure procedures together.\n\n**Intervention.** An Ka-min can cross-check the relevant signatures and handover times and make the records public, but cannot grant new offices, ranks, rights, or fiefs.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 20 | Force −35 | Materiality 0 | Communality 15 | Principle 40 | Publicity 30 | Qualification 15 | Dispersion 45 | Transformation 5\n- Desires: Craving 20 | Exclusivity 30 | Risk 30 | Display −30 | Persistence −20 | Orientation No Orientation | Union Non-Exclusive\n:::","relations":{"outgoing":[{"from":"An Kamin","type":"Contract","to":"An Taegyeong","basis":"An Kamin hands An Taegyeong a duplicate-and-omission sheet that compares each faction''s union member roster against the original. When disclosing the voting roll and attendance, An Taegyeong checks those discrepancies so that faction rosters do not stand in for the voting record of the union membership as a whole."}],"incoming":[]}}', '{"id":"person-0599","name":"안카민","title":"감사 기록관","position":"감사 기록관","characterId":"K599","rank":"미등록","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#인물-안카민","detailRoute":"/people/person-0599","birthDate":"2073-09-21","birthday":"09-21","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":6,"effective":6},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"membership-comparison","name":"조합원 명부 대조","rating":60}],"traits":[{"id":"evidenced-choice","name":"원본 기준으로 대조","description":"파벌 명단을 원본과 이름마다 맞춰 중복과 누락을 나누고 대조표를 인계했다. 확인된 행동 범위를 넘는 권한과 성과는 부여하지 않는다.","behavior":"확인된 선택에서는 원본 기준으로 대조을 드러낸다. 다른 상황까지 불변 성향으로 확정하지 않는다.","stress":"교대가 막히거나 기록이 사라지면 원본과 인계를 재확인할 수 있다.","relationship":"다음 당직에게 열쇠와 기록을 넘기며 파벌의 인계 방해를 경계한다.","effects":[]},{"id":"handover-continuity","name":"기록 단절 경계","description":"감사 기록관 자리에서 시청역 조합 장부를 끊기지 않게 잇고, 작업장 파벌이 갈려도 조합원 전원의 위원장 직접선거 결과를 지킨다.","behavior":"맡은 기록과 서명의 연결을 확인하려 한다.","stress":"감사 기록관 당직이 비고 선거 파벌이 인수인계를 가로막아 Arc의 통행이 강국 볼모가 되는 것.","relationship":"다음 당직에게 열쇠와 기록을 넘기며 파벌의 인계 방해를 경계한다.","effects":[]}],"narrative":"파벌 명단을 원본과 이름마다 맞춰 중복과 누락을 나누고 대조표를 인계했다. 확인된 행동 범위를 넘는 권한과 성과는 부여하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"순흥 안씨","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":20,"무력":-35,"물질":0,"공동":15,"원칙":40,"공개":30,"자격":15,"분산":45,"변혁":5},"desire":{"갈망":20,"독점":30,"위험":30,"과시":-30,"지속":-20,"지향":"무성향","결합":"비독점"},"fields":{"생업":"감사 기록·당직 열쇠 인계","소속":"Arc","공동체 역할":"조합원","직무":"감사 기록관","가치관":"권위 −25 | 개방 20 | 무력 −35 | 물질 0 | 공동 15 | 원칙 40 | 공개 30 | 자격 15 | 분산 45 | 변혁 5","욕망":"갈망 20 | 독점 30 | 위험 30 | 과시 −30 | 지속 −20 | 지향 무성향 | 결합 비독점"},"sections":{"생애":"2073-09-21에 태어난 안카민은 영구 겨울의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 안카민은 소공동의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 정하지 않는다.","직무":"공동체 역할은 조합원이며 직무는 감사 기록관이다. 이 직무는 Arc 내부 기능이고 대한민국 정부 공무원 관직이나 봉건 품계가 아니다.","일화":"위원장 직접선거를 앞두고 작업장 파벌과 노선 파벌이 서로 다른 조합원 명단을 감사 당직에 낸다. 안카민은 두 명단을 조합원 명부 원본과 이름마다 대조해 겹친 이름과 빠진 이름을 나누어 적고, 그 대조표와 당직 열쇠를 다음 감사 당직에게 건넨다.","관계":"안카민의 기존 관계 기록은 다음과 같다. 같은 업무·생활권 선배 당직과 인수인계로 묶인다.","목표":"안카민은 감사 기록관 업무의 서명·인계·공개 절차를 시청역 조합 장부에서 검증 가능하게 유지하려 한다.","공포":"감사 기록관 업무의 서명이나 인계 기록이 바뀌어 안카민의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.","개입":"안카민은 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다."},"biography":"안카민은 영구 겨울의 시청역 조합 작업장에서 감사 기록관 업무 기록과 공개 표결 서명을 먼저 대조한다. 급수·통행·계약 일정이 겹치는 날에는 접수 시각과 인계 순서를 같은 장부에 남긴다.\n\n- 생업: 감사 기록·당직 열쇠 인계\n- 소속: Arc\n- 공동체 역할: 조합원\n- 직무: 감사 기록관\n**생애.** 2073-09-21에 태어난 안카민은 영구 겨울의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 안카민은 소공동의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 정하지 않는다.\n\n**직무.** 공동체 역할은 조합원이며 직무는 감사 기록관이다. 이 직무는 Arc 내부 기능이고 대한민국 정부 공무원 관직이나 봉건 품계가 아니다.\n\n**일화.** 위원장 직접선거를 앞두고 작업장 파벌과 노선 파벌이 서로 다른 조합원 명단을 감사 당직에 낸다. 안카민은 두 명단을 조합원 명부 원본과 이름마다 대조해 겹친 이름과 빠진 이름을 나누어 적고, 그 대조표와 당직 열쇠를 다음 감사 당직에게 건넨다.\n\n**관계.** 안카민의 기존 관계 기록은 다음과 같다. 같은 업무·생활권 선배 당직과 인수인계로 묶인다.\n\n**목표.** 안카민은 감사 기록관 업무의 서명·인계·공개 절차를 시청역 조합 장부에서 검증 가능하게 유지하려 한다.\n\n**공포.** 감사 기록관 업무의 서명이나 인계 기록이 바뀌어 안카민의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.\n\n**개입.** 안카민은 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 20 | 무력 −35 | 물질 0 | 공동 15 | 원칙 40 | 공개 30 | 자격 15 | 분산 45 | 변혁 5\n- 욕망: 갈망 20 | 독점 30 | 위험 30 | 과시 −30 | 지속 −20 | 지향 무성향 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"안카민","type":"계약","to":"안태경","basis":"안카민은 파벌별 조합원 명단을 원본과 대조한 중복·누락표를 안태경에게 넘긴다. 안태경은 투표 명부와 출석을 공개할 때 그 차이를 확인해, 파벌 명단이 조합원 전체의 투표 기록을 대신하지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0600', 'c1a1-c740-c9c4-5b8b', '{"id":"person-0600","name":"Song Haji","title":"Conduit Surveyor","position":"Conduit Surveyor","characterId":"K600","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-song-ha-ji","detailRoute":"/people/person-0600","birthDate":"2073-02-13","birthday":"02-13","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k600-public-counter-referral","name":"Public-counter referral","rating":45}],"traits":[{"id":"k600-action-priority","name":"Requests in public","description":"In 2125 he sent a private petition back and passed it to the public window. By this deed the signature of the pipeline surveyor post rose into the ledger.","behavior":"In 2125 he sent a private petition back and passed it to the public window. By this deed the signature of the pipeline surveyor post rose into the ledger.","stress":"That the pipeline surveyor duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves under Byeon Goun on concourse shifts and conduit surveys.","effects":[]},{"id":"k600-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the pipeline surveyor duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves under Byeon Goun on concourse shifts and conduit surveys.","effects":[]}],"narrative":"In 2125 he sent a private petition back and passed it to the public window. By this deed the signature of the pipeline surveyor post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-c740-c9c4-5b8b","name":"Eunjin Song Clan","crest":"clan-crests/c1a1-c740-c9c4-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":50,"Openness":0,"Force":15,"Material":30,"Communal":30,"Principle":30,"Public":0,"Eligibility":5,"Dispersed":-40,"Transformative":-20},"desire":{"Longing":0,"Monopoly":-20,"Risk":-15,"Display":15,"Sustained":-10,"Orientation":"Same-Sex","Union":"None"},"fields":{"Affiliation":"Free City","Livelihood":"Waiting Hall Duty","Rank":"Clerk","Title":"Conduit Surveyor","Work Location":"Yeongdeungpobon-dong. Song Ha-ji transfers the record of passing a private solicitation on to the public window onto Byeon Go-un''s next shift roster at the Yeongdeungpobon-dong waiting hall.","Values":"Authority 50 | Openness 0 | Force 15 | Materiality 30 | Communality 30 | Principle 30 | Publicity 0 | Qualification 5 | Dispersion −40 | Transformation −20","Desires":"Craving 0 | Exclusivity −20 | Risk −15 | Display 15 | Persistence −10 | Orientation Same-Sex | Union None"},"sections":{"Life":"Generation of 2126. Grew up on the waiting hall duty. The Conduit Surveyor post opened through covering a shift absence without leave as a substitute duty.\n- Work location: Yeongdeungpobon-dong. Song Ha-ji transfers the record of passing a private solicitation on to the public window onto Byeon Go-un''s next shift roster at the Yeongdeungpobon-dong waiting hall.","Offices":"Rank: Clerk. Title: Conduit Surveyor. Song Haji transfers the record of passing a private solicitation to the public window into Byeon Goun''s next shift roster at the Yeongdeungpo-bondong concourse.","Anecdote":"In 2125, Song Haji sent a private solicitation back and redirected it to the public window. Because of this, the signature for the Conduit Surveyor post entered the ledger.","Relationships":"Handles waiting hall shifts and conduit surveys under Byeon Go-un''s command.","Ambition":"From the Conduit Surveyor post, to keep the Floodgate Bureau''s ledger unbroken.","Fear":"The fear that if the Conduit Surveyor''s duty post is left empty, the Water Gate Bureau''s passage becomes a hostage to the great powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty watch. Trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Free City\n- Occupation: Concourse duty watch\n- Rank: Clerk\n- Title: Conduit Surveyor\n**Life.** Born in the 2126 generation. Grew up on the concourse duty watch. The Conduit Surveyor post opened through a substitute duty after an unexcused shift absence.\n- Work location: Yeongdeungpo-bondong. Song Haji transfers the record of passing a private solicitation to the public window into Byeon Goun''s next shift roster at the Yeongdeungpo-bondong concourse.\n\n**Office.** Rank: Clerk. Title: Conduit Surveyor. Song Haji transfers the record of passing a private solicitation to the public window into Byeon Goun''s next shift roster at the Yeongdeungpo-bondong concourse.\n\n**Anecdote.** In 2125, sent a private solicitation back and redirected it to the public window. Because of this, the signature for the Conduit Surveyor post entered the ledger.\n\n**Relationships.** Under Byeon Goun''s command, handles concourse shifts and conduit surveying.\n\n**Ambition.** From the Conduit Surveyor post, to keep the Floodgate Bureau''s ledger unbroken.\n\n**Fear.** That if the Conduit Surveyor watch goes empty, the Floodgate Bureau''s passage will become a hostage to the great powers.\n\n**Intervention.** Can set up a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 50 | Openness 0 | Force 15 | Materialism 30 | Community 30 | Principle 30 | Publicity 0 | Credentials 5 | Decentralization −40 | Transformation −20\n- Desires: Longing 0 | Exclusivity −20 | Risk −15 | Display 15 | Persistence −10 | Orientation Same-sex | Union None\n:::","directLiege":{"personId":"K017","name":"Byeon Goun","courtId":"court:K017","effectiveYear":2126},"relations":{"outgoing":[{"from":"Song Haji","type":"Command","to":"Byeon Goun","basis":"Handles waiting hall shifts and pipeline surveys under Byeon Goun''s command"}],"incoming":[]}}', '{"id":"person-0600","name":"송하지","title":"관로 탐사원","position":"관로 탐사원","characterId":"K600","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-송하지","detailRoute":"/people/person-0600","birthDate":"2073-02-13","birthday":"02-13","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k600-public-counter-referral","name":"공개 창구 안내","rating":45}],"traits":[{"id":"k600-action-priority","name":"공개 요청으로","description":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다.","behavior":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다.","stress":"관로 탐사원 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"변고운의 지휘 아래 대합실 교대와 관로 탐사를 맡는다.","effects":[]},{"id":"k600-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"관로 탐사원 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"변고운의 지휘 아래 대합실 교대와 관로 탐사를 맡는다.","effects":[]}],"narrative":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c1a1-c740-c9c4-5b8b","name":"은진 송씨","crest":"clan-crests/c1a1-c740-c9c4-5b8b.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":50,"개방":0,"무력":15,"물질":30,"공동":30,"원칙":30,"공개":0,"자격":5,"분산":-40,"변혁":-20},"desire":{"갈망":0,"독점":-20,"위험":-15,"과시":15,"지속":-10,"지향":"동성","결합":"없음"},"fields":{"소속":"자유도시","생업":"대합실 당직","품계":"주사","직함":"관로 탐사원","업무 위치":"영등포본동. 송하지는 사적 청탁을 공개 창구로 넘긴 기록을 영등포본동 대합실에서 변고운의 다음 교대 명부에 옮긴다.","가치관":"권위 50 | 개방 0 | 무력 15 | 물질 30 | 공동 30 | 원칙 30 | 공개 0 | 자격 5 | 분산 −40 | 변혁 −20","욕망":"갈망 0 | 독점 −20 | 위험 −15 | 과시 15 | 지속 −10 | 지향 동성 | 결합 없음"},"sections":{"생애":"2126년 세대. 대합실 당직에서 자랐다. 관로 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 업무 위치: 영등포본동. 송하지는 사적 청탁을 공개 창구로 넘긴 기록을 영등포본동 대합실에서 변고운의 다음 교대 명부에 옮긴다.","관직":"품계 주사. 직함은 관로 탐사원이다. 송하지는 사적 청탁을 공개 창구로 넘긴 기록을 영등포본동 대합실에서 변고운의 다음 교대 명부에 옮긴다.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 관로 탐사원 자리의 서명이 장부에 올랐다.","관계":"변고운의 지휘 아래 대합실 교대와 관로 탐사를 맡는다.","야망":"관로 탐사원 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"관로 탐사원 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 대합실 당직\n- 품계: 주사\n- 직함: 관로 탐사원\n**생애.** 2126년 세대. 대합실 당직에서 자랐다. 관로 탐사원 자리는 교대 무단 결근 대체 당직으로 열렸다.\n- 업무 위치: 영등포본동. 송하지는 사적 청탁을 공개 창구로 넘긴 기록을 영등포본동 대합실에서 변고운의 다음 교대 명부에 옮긴다.\n\n**관직.** 품계 주사. 직함은 관로 탐사원이다. 송하지는 사적 청탁을 공개 창구로 넘긴 기록을 영등포본동 대합실에서 변고운의 다음 교대 명부에 옮긴다.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 이 일로 관로 탐사원 자리의 서명이 장부에 올랐다.\n\n**관계.** 변고운의 지휘 아래 대합실 교대와 관로 탐사를 맡는다.\n\n**야망.** 관로 탐사원 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 관로 탐사원 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 50 | 개방 0 | 무력 15 | 물질 30 | 공동 30 | 원칙 30 | 공개 0 | 자격 5 | 분산 −40 | 변혁 −20\n- 욕망: 갈망 0 | 독점 −20 | 위험 −15 | 과시 15 | 지속 −10 | 지향 동성 | 결합 없음\n:::","directLiege":{"personId":"K017","name":"변고운","courtId":"court:K017","effectiveYear":2126},"relations":{"outgoing":[{"from":"송하지","type":"지휘","to":"변고운","basis":"변고운의 지휘 아래 대합실 교대와 관로 탐사를 맡음"}],"incoming":[]}}');
