INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0614', 'd558-c9c4-c8fc', '{"id":"person-0614","name":"Ha Nameun","title":"Escort Logistics Merchant","position":"Myeongdong Station Relief Supplies Duty","rank":"Congregationioner","commonTier":"T5","occupation":"Relief Supplies Handover Records","gender":"Female","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0614","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0614","name":"하남은","title":"호송 물류상","position":"명동역 구휼 물자 당직","rank":"교우","commonTier":"T5","occupation":"구휼 물자 인수인계 기록","gender":"여성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0614","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0615', 'acfd-d604-d48d', '{"id":"person-0615","name":"Gwak Neulho","title":"Escort Patrol","position":"Escort Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Escort Patrol Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0615","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0615","name":"곽늘호","title":"호송 순찰대","position":"호송 순찰대","rank":"조합원","commonTier":"T5","occupation":"호송 순찰 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0615","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0616', 'cangnyeong-seong-yeolcha', '{"id":"person-0616","name":"Seong Dalhyeon","title":"Ration District Clerk","position":"Ration District Clerk","characterId":"K616","rank":"Clerk","commonTier":"T5","occupation":"Water Distribution Duty","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-seong-dalhyeon","detailRoute":"/people/person-0616","birthDate":"2073-04-06","birthday":"04-06","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k616-pressure-total-crosscheck","name":"Pressure-total crosscheck","rating":60}],"traits":[{"id":"k616-action-priority","name":"Pressure beside totals","description":"Word reaches the duty desk that the ration totals balance yet the water runs thin in alley after alley. Seong Dalhyeon walks the water-distribution duty round, writes the pressure at each tap beside the totals, marks the alleys where totals and pressure disagree, and shows them to I Seodam first.","behavior":"Word reaches the duty desk that the ration totals balance yet the water runs thin in alley after alley. Seong Dalhyeon walks the water-distribution duty round, writes the pressure at each tap beside the totals, marks the alleys where totals and pressure disagree, and shows them to I Seodam first.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]},{"id":"k616-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]}],"narrative":"Word reaches the duty desk that the ration totals balance yet the water runs thin in alley after alley. Seong Dalhyeon walks the water-distribution duty round, writes the pressure at each tap beside the totals, marks the alleys where totals and pressure disagree, and shows them to I Seodam first. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cangnyeong-seong-yeolcha","name":"Changnyeong Seong Clan","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":50,"Openness":-15,"Force":5,"Material":45,"Communal":20,"Principle":15,"Public":20,"Eligibility":10,"Dispersed":-45,"Transformative":-30},"desire":{"Longing":0,"Monopoly":-10,"Risk":-5,"Display":-5,"Sustained":-20,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Affiliation":"Free City","Livelihood":"Water Distribution Duty","Rank":"Clerk","Title":"Ration District Clerk","Work Location":"Sinjeong 2-dong. Seong Dalhyeon marks the alleys where the ration total and the tap pressure differ, shows them to I Seodam, and enters them in the Sinjeong 2-dong water supply handover.","Values":"Authority 50 | Openness −15 | Force 5 | Materialism 45 | Community 20 | Principle 15 | Publicity 20 | Qualification 10 | Decentralization −45 | Transformation −30","Desires":"Craving 0 | Monopoly −10 | Risk −5 | Display −5 | Persistence −20 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Of the 2126 cohort. Grew up at the Yeongdeungpo water purification watch. The post of Ration District Clerk opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. Seong Dalhyeon marks the alleys where the ration total and the tap pressure differ, shows them to I Seodam, and enters them in the Sinjeong 2-dong water supply handover.","Offices":"Rank: Clerk. Title: Ration District Clerk. Seong Dalhyeon marks the alleys where the ration total and the tap pressure differ, shows them to I Seodam, and enters them in the Sinjeong 2-dong water supply handover.","Anecdote":"Word reaches the watch that the ration totals add up but the water runs thin in every alley. Seong Dalhyeon makes the rounds of the water distribution watch, writes the pressure at each tap in the column beside the total, marks the alleys where total and pressure disagree, and shows them first to I Seodam.","Relationships":"Works as Lee Seodam''s Ration District Clerk and takes the water distribution watch.","Ambition":"In the post of Ration District Clerk, keeps the Water Gate Bureau''s ledger linked without a break.","Fear":"That the Water Gate Bureau''s passage becomes a hostage of the great powers if the Ration District Clerk''s watch is left vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the watch. Trusts a single line in the ledger over loud talk.\n\n- Affiliation: Waterworks Bureau\n- Occupation: Water distribution watch\n- Rank: Clerk\n- Title: Ration District Clerk\n**Life.** Of the 2126 cohort. Grew up at the Yeongdeungpo water purification watch. The post of Ration District Clerk opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. Seong Dalhyeon marks the alleys where the ration total and the tap pressure differ, shows them to I Seodam, and enters them in the Sinjeong 2-dong water supply handover.\n\n**Office.** Rank: Clerk. Title: Ration District Clerk. Seong Dalhyeon marks the alleys where the ration total and the tap pressure differ, shows them to I Seodam, and enters them in the Sinjeong 2-dong water supply handover.\n\n**Anecdote.** Word reaches the watch that the ration totals add up but the water runs thin in every alley. Seong Dalhyeon makes the rounds of the water distribution watch, writes the pressure at each tap in the column beside the total, marks the alleys where total and pressure disagree, and shows them first to I Seodam.\n\n**Relations.** Works as I Seodam''s Ration District Clerk and handles the water distribution watch.\n\n**Ambition.** To keep the Waterworks Bureau''s ledger unbroken from the post of Ration District Clerk.\n\n**Fear.** That if the Ration District Clerk''s watch goes empty, the Waterworks Bureau''s passage will become a hostage of the great powers.\n\n**Intervention.** Can appoint a witness to the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 50 | Openness −15 | Force 5 | Materialism 45 | Community 20 | Principle 15 | Publicity 20 | Qualification 10 | Decentralization −45 | Transformation −30\n- Desires: Craving 0 | Monopoly −10 | Risk −5 | Display −5 | Persistence −20 | Orientation Fluid | Bonding Non-exclusive\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Seong Dalhyeon","type":"Command","to":"I Seo-dam","basis":"Serves as clerk of Yi Seodam''s ration district and holds the water distribution watch"}],"incoming":[]}}', '{"id":"person-0616","name":"성달현","title":"배급구역 서기","position":"배급구역 서기","characterId":"K616","rank":"주사","commonTier":"T5","occupation":"급수 배분 당직","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-성달현","detailRoute":"/people/person-0616","birthDate":"2073-04-06","birthday":"04-06","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k616-pressure-total-crosscheck","name":"압력·합계 대조","rating":60}],"traits":[{"id":"k616-action-priority","name":"합계 옆의 압력","description":"배급 합계는 맞는데 골목마다 물줄기가 가늘다는 말이 당직에 들어온다. 성달현은 급수 배분 당직을 돌며 수도꼭지마다 나오는 압력을 합계 옆 칸에 적고, 합계와 압력이 어긋나는 골목에 표시를 달아 이서담에게 먼저 보인다.","behavior":"배급 합계는 맞는데 골목마다 물줄기가 가늘다는 말이 당직에 들어온다. 성달현은 급수 배분 당직을 돌며 수도꼭지마다 나오는 압력을 합계 옆 칸에 적고, 합계와 압력이 어긋나는 골목에 표시를 달아 이서담에게 먼저 보인다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]},{"id":"k616-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]}],"narrative":"배급 합계는 맞는데 골목마다 물줄기가 가늘다는 말이 당직에 들어온다. 성달현은 급수 배분 당직을 돌며 수도꼭지마다 나오는 압력을 합계 옆 칸에 적고, 합계와 압력이 어긋나는 골목에 표시를 달아 이서담에게 먼저 보인다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cangnyeong-seong-yeolcha","name":"창녕 성씨","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":50,"개방":-15,"무력":5,"물질":45,"공동":20,"원칙":15,"공개":20,"자격":10,"분산":-45,"변혁":-30},"desire":{"갈망":0,"독점":-10,"위험":-5,"과시":-5,"지속":-20,"지향":"유동","결합":"비독점"},"fields":{"소속":"자유도시","생업":"급수 배분 당직","품계":"주사","직함":"배급구역 서기","업무 위치":"신정2동. 성달현은 배급 합계와 수도꼭지 압력이 다른 골목을 표시해 이서담에게 보여 주고 신정2동 급수 인계에 올린다.","가치관":"권위 50 | 개방 −15 | 무력 5 | 물질 45 | 공동 20 | 원칙 15 | 공개 20 | 자격 10 | 분산 −45 | 변혁 −30","욕망":"갈망 0 | 독점 −10 | 위험 −5 | 과시 −5 | 지속 −20 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 성달현은 배급 합계와 수도꼭지 압력이 다른 골목을 표시해 이서담에게 보여 주고 신정2동 급수 인계에 올린다.","관직":"품계 주사. 직함은 배급구역 서기이다. 성달현은 배급 합계와 수도꼭지 압력이 다른 골목을 표시해 이서담에게 보여 주고 신정2동 급수 인계에 올린다.","일화":"배급 합계는 맞는데 골목마다 물줄기가 가늘다는 말이 당직에 들어온다. 성달현은 급수 배분 당직을 돌며 수도꼭지마다 나오는 압력을 합계 옆 칸에 적고, 합계와 압력이 어긋나는 골목에 표시를 달아 이서담에게 먼저 보인다.","관계":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","야망":"배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 급수 배분 당직\n- 품계: 주사\n- 직함: 배급구역 서기\n**생애.** 2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 성달현은 배급 합계와 수도꼭지 압력이 다른 골목을 표시해 이서담에게 보여 주고 신정2동 급수 인계에 올린다.\n\n**관직.** 품계 주사. 직함은 배급구역 서기이다. 성달현은 배급 합계와 수도꼭지 압력이 다른 골목을 표시해 이서담에게 보여 주고 신정2동 급수 인계에 올린다.\n\n**일화.** 배급 합계는 맞는데 골목마다 물줄기가 가늘다는 말이 당직에 들어온다. 성달현은 급수 배분 당직을 돌며 수도꼭지마다 나오는 압력을 합계 옆 칸에 적고, 합계와 압력이 어긋나는 골목에 표시를 달아 이서담에게 먼저 보인다.\n\n**관계.** 이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.\n\n**야망.** 배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 50 | 개방 −15 | 무력 5 | 물질 45 | 공동 20 | 원칙 15 | 공개 20 | 자격 10 | 분산 −45 | 변혁 −30\n- 욕망: 갈망 0 | 독점 −10 | 위험 −5 | 과시 −5 | 지속 −20 | 지향 유동 | 결합 비독점\n:::","directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"성달현","type":"지휘","to":"이서담","basis":"이서담의 배급구역 서기로 급수 배분 당직을 맡음"}],"incoming":[]}}');
