INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0643', 'ace0-d55c-c591', '{"id":"person-0643","name":"Go Dajin","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0643","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0643","name":"고다진","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0643","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0644', 'bb38-b0a8-d3c9-6587', '{"id":"person-0644","name":"Mun Baeun","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K644","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#Person-Mun-Baeun","detailRoute":"/people/person-0644","birthDate":"2093-02-06","birthday":"02-06","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"document-transcription","name":"Document transcription","rating":45}],"traits":[{"id":"stated-priority","name":"Dries and preserves papers","description":"A wet authorization at the platform was retained as a transcript. Preservation is reflected without adding skills from the sanitation title.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A wet authorization at the platform was retained as a transcript. Preservation is reflected without adding skills from the sanitation title.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":40,"Force":-65,"Material":-25,"Communal":30,"Principle":75,"Public":20,"Eligibility":25,"Dispersed":15,"Transformative":-5},"desire":{"Longing":40,"Monopoly":15,"Risk":5,"Display":-20,"Sustained":-10,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −10 | Openness 40 | Force −65 | Materialism −25 | Communal 30 | Principle 75 | Publicity 20 | Credentials 25 | Dispersal 15 | Transformation −5","Desires":"Craving 40 | Monopoly 15 | Risk 5 | Display −20 | Persistence −10 | Orientation same-sex | Union contract cohabitation"},"sections":{"Life":"Born on 2093-02-06. As of the 2126 opening, holds the post of Quarantine Records Officer, continuing the existing duty rosters and records. The post''s succession record opened with the deletion of one line from a double ledger.\n- The quarantine records and duty-key handover desk in Jegi-dong is Mun Baeun''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a noble title, a domain, or possession rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, dried a water-soaked ratification document on a platform and left it as a transcribed copy. That day''s record remained as a handover basis for the next duty officer to confirm.","Relationships":"Mun Baeun hands the preserved quarantine transcript to Su Chorong''s entry check. Su Chorong checks the quarantine screens and stamps on site and does not accept blurred records as grounds for release.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty chain. Trusts a single ledger line more than loud talk.\n\n- Livelihood: quarantine records and duty-key handover\n- Affiliation: White Cross Corps\n- Rank: Resident\n- Title: Quarantine Records Officer\n**Life.** Born on 2093-02-06. As of the 2126 opening, holds the post of Quarantine Records Officer, continuing the existing duty rosters and records. The post''s succession record opened with the deletion of one line from a double ledger.\n- The quarantine records and duty-key handover desk in Jegi-dong is Mun Baeun''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a noble title, a domain, or possession rights.\n\n**Office.** Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of their own post, and writes into the ledger the time at which the handed-over keys and records were received.\n\n**Anecdote.** In 2125, on the platform, dried a water-soaked ratification document and preserved it as a transcript. That day''s record remained as handover grounds for the next duty officer to verify.\n\n**Relationships.** Mun Baeun hands the preserved quarantine transcript to Su Chorong''s entry check. Su Chorong verifies the on-site quarantine curtain and seal, and does not accept a blurred record as grounds for release.\n\n**Ambition.** To keep the White Cross Corps'' ledger continuously connected from the Quarantine Resident''s post.\n\n**Fear.** Fears that if the Quarantine Resident''s duty post is left empty, the White Cross Corps'' passage will become a hostage of Seoul''s internal sponsoring powers.\n\n**Intervention.** Can bring in a witness for the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 40 | Force −65 | Materialism −25 | Communal 30 | Principle 75 | Publicity 20 | Credentials 25 | Dispersal 15 | Transformation −5\n- Desires: Craving 40 | Monopoly 15 | Risk 5 | Display −20 | Persistence −10 | Orientation same-sex | Union contract cohabitation\n:::","relations":{"outgoing":[{"from":"Mun Baeun","type":"Contract","to":"Su Choreong","basis":"Mun Baeun hands the preserved quarantine transcript to Su Chorong''s entry check. Su Chorong checks the quarantine screens and stamps on site and does not accept blurred records as grounds for release."}],"incoming":[]}}', '{"id":"person-0644","name":"문바은","title":"방역 기록관","position":"방역 기록관","characterId":"K644","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-문바은","detailRoute":"/people/person-0644","birthDate":"2093-02-06","birthday":"02-06","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"document-transcription","name":"문서 필사","rating":45}],"traits":[{"id":"stated-priority","name":"문서를 말려 남긴다","description":"승강장의 젖은 인준 문서를 필사본으로 남겼다. 문서 보존 능력은 반영하고 방역 직함에서 추가 기술은 만들지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"승강장의 젖은 인준 문서를 필사본으로 남겼다. 문서 보존 능력은 반영하고 방역 직함에서 추가 기술은 만들지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":40,"무력":-65,"물질":-25,"공동":30,"원칙":75,"공개":20,"자격":25,"분산":15,"변혁":-5},"desire":{"갈망":40,"독점":15,"위험":5,"과시":-20,"지속":-10,"지향":"동성","결합":"계약동거"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −10 | 개방 40 | 무력 −65 | 물질 −25 | 공동 30 | 원칙 75 | 공개 20 | 자격 25 | 분산 15 | 변혁 −5","욕망":"갈망 40 | 독점 15 | 위험 5 | 과시 −20 | 지속 −10 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"2093-02-06에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 문바은의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 승강장에서 물에 젖은 인준 문서를 말려 필사본으로 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"문바은은 보존한 방역 필사본을 수초롱의 출입 확인에 넘긴다. 수초롱은 현장의 격리 막과 도장을 확인해 흐린 기록을 해제 근거로 받아들이지 않는다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2093-02-06에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구가 문바은의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 승강장에서 물에 젖은 인준 문서를 말려 필사본으로 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 문바은은 보존한 방역 필사본을 수초롱의 출입 확인에 넘긴다. 수초롱은 현장의 격리 막과 도장을 확인해 흐린 기록을 해제 근거로 받아들이지 않는다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 40 | 무력 −65 | 물질 −25 | 공동 30 | 원칙 75 | 공개 20 | 자격 25 | 분산 15 | 변혁 −5\n- 욕망: 갈망 40 | 독점 15 | 위험 5 | 과시 −20 | 지속 −10 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"문바은","type":"계약","to":"수초롱","basis":"문바은은 보존한 방역 필사본을 수초롱의 출입 확인에 넘긴다. 수초롱은 현장의 격리 막과 도장을 확인해 흐린 기록을 해제 근거로 받아들이지 않는다."}],"incoming":[]}}');
