INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0648', 'bc31-c218-c6d0', '{"id":"person-0648","name":"Baek Charae","title":"Conduit Surveyor","position":"Conduit Surveyor","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Female","stage":"S4","state":"S01","stateName":"The Sluice","detailRoute":"/people/person-0648","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0648","name":"백차래","title":"관로 탐사원","position":"관로 탐사원","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"여성","stage":"S4","state":"S01","stateName":"수문국","detailRoute":"/people/person-0648","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0649', 'd5c8-ae40-d574-8a31', '{"id":"person-0649","name":"Heo Paseo","title":"Restoration Service Recorder","position":"Restoration Service Recorder","characterId":"K649","rank":"Guild Member","commonTier":"T5","occupation":"Registration & Records","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-02#person-Heo-Paseo","detailRoute":"/people/person-0649","birthDate":"2066-06-16","birthday":"06-16","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k649-drawing-number-check","name":"Drawing-box number crosscheck","rating":60}],"traits":[{"id":"k649-action-priority","name":"Separate unnumbered modifications","description":"The outgoing list of pump parts bound for Han Jaemok comes up to the records duty with the standards-drawing-cabinet numbers attached. Heo Paseo checks each part for its cabinet number, binds the modified parts whose number column is blank as the off-standard modifications Gang Minseo throws out, and lists them at the back of the outgoing list.","behavior":"The outgoing list of pump parts bound for Han Jaemok comes up to the records duty with the standards-drawing-cabinet numbers attached. Heo Paseo checks each part for its cabinet number, binds the modified parts whose number column is blank as the off-standard modifications Gang Minseo throws out, and lists them at the back of the outgoing list.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k649-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The outgoing list of pump parts bound for Han Jaemok comes up to the records duty with the standards-drawing-cabinet numbers attached. Heo Paseo checks each part for its cabinet number, binds the modified parts whose number column is blank as the off-standard modifications Gang Minseo throws out, and lists them at the back of the outgoing list. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-ae40-d574-8a31","name":"Gimhae Heo Clan","crest":"clan-crests/d5c8-ae40-d574-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":15,"Force":-5,"Material":35,"Communal":50,"Principle":30,"Public":35,"Eligibility":55,"Dispersed":15,"Transformative":30},"desire":{"Longing":35,"Monopoly":-40,"Risk":5,"Display":10,"Sustained":5,"Orientation":"Fluid","Union":"Polyamorous"},"fields":{"Affiliation":"Free City","Livelihood":"Registration & Records","Rank":"Guild Member","Title":"Restoration Service Recorder","Work Location":"Guro 2-dong. At the Guro 2-dong records duty desk, Heo Paseo cross-checks the shipping list of pump parts to be sent to Han Jaemok by drawing-cabinet number. Heo Paseo bundles the modified parts missing numbers separately, writes them after Gang Minseo''s sealed record, and asks the next clerk to verify.","Values":"Authority −30 | Openness 15 | Force −5 | Materialism 35 | Communal 50 | Principle 30 | Publicity 35 | Credentials 55 | Dispersal 15 | Transformation 30","Desires":"Craving 35 | Monopoly −40 | Risk 5 | Display 10 | Persistence 5 | Orientation fluid | Union multi-partner"},"sections":{"Life":"Of the 2126 cohort. Grew up at the Seoul Station registry office. The post of Restoration Service Records Officer opened with the deletion of one line from a double ledger.\n- Work location: Guro 2-dong. At the Guro 2-dong records duty desk, Heo Paseo cross-checks the shipping list of pump parts to be sent to Han Jaemok by drawing-cabinet number. Heo Paseo bundles the modified parts missing numbers separately, writes them after Gang Minseo''s sealed record, and asks the next clerk to verify.","Offices":"Rank: Guild Member. Title: Restoration Service Records Officer. Bundles the modified parts missing numbers separately, writes them after Gang Minseo''s sealed record, and asks the next clerk to verify.","Anecdote":"The shipping list of pump parts to be sent to Han Jaemok comes up to the records office duty desk together with the standard drawing-cabinet numbers. Heo Paseo goes through the parts to check whether each has a drawing-cabinet number attached, and bundles any modified parts with a blank number separately, as out-of-standard modifications that Gang Minseo rejects, and writes them after the shipping list.","Relationships":"The Lung Bureau hands Jang Useok a list of modified parts without drawing-cabinet numbers. Jang Useok checks the measurement seals and remeasurement records so that out-of-spec parts do not hide behind blank numbers in the shipping list.","Ambition":"Heo Paseo seeks to mark unnumbered modified parts separately on the shipping list so that they undergo cross-checking against the drawing cabinet and measurement records.","Fear":"That modified parts without drawing-cabinet numbers will hide in blank cells of the shipping list and evade Jang Useok''s measurement cross-check.","Intervention":"The player can cross-check part numbers against the drawing cabinet with Heo Paseo, or bring the list of missing numbers to Jang Useok."},"biography":"Heo Paseo does not bury unnumbered modified parts in the shipping list of standard parts.\n\n- Affiliation: Free City\n- Livelihood: registration and record-keeping\n- Rank: Guild Member\n- Title: Restoration Service Records Officer\n**Life.** Of the 2126 cohort. Grew up at the Seoul Station registry office. The post of Restoration Service Records Officer opened with the deletion of one line from a double ledger.\n- Work location: Guro 2-dong. At the Guro 2-dong records duty desk, Heo Paseo cross-checks the shipping list of pump parts to be sent to Han Jaemok by drawing-cabinet number. Heo Paseo bundles the modified parts missing numbers separately, writes them after Gang Minseo''s sealed record, and asks the next clerk to verify.\n\n**Office.** Rank: Guild Member. Title: Restoration Service Records Officer. Bundles the modified parts missing numbers separately, writes them after Gang Minseo''s sealed record, and asks the next clerk to verify.\n\n**Anecdote.** The shipping list of pump parts to be sent to Han Jaemok comes up to the records office duty desk together with the standard drawing-cabinet numbers. Heo Paseo goes through the parts to check whether each has a drawing-cabinet number attached, and bundles any modified parts with a blank number separately, as out-of-standard modifications that Gang Minseo rejects, and writes them after the shipping list.\n\n**Relationships.** Heo Paseo hands the list of modified parts without drawing-cabinet numbers to Jang Useok. Jang Useok checks the measurement seals and re-measurement records so that out-of-standard parts do not hide behind blank numbers on the shipping list.\n\n**Ambition.** Heo Paseo seeks to mark unnumbered modified parts separately on the shipping list so that they undergo cross-checking against the drawing cabinet and measurement records.\n\n**Fear.** That modified parts without drawing-cabinet numbers will hide in blank cells of the shipping list and evade Jang Useok''s measurement cross-check.\n\n**Intervention.** The player can cross-check part numbers against the drawing cabinet with Heo Paseo, or bring the list of missing numbers to Jang Useok.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 15 | Force −5 | Materialism 35 | Communal 50 | Principle 30 | Publicity 35 | Credentials 55 | Dispersal 15 | Transformation 30\n- Desires: Craving 35 | Monopoly −40 | Risk 5 | Display 10 | Persistence 5 | Orientation fluid | Union multi-partner\n:::","relations":{"outgoing":[{"from":"Heo Paseo","type":"Contract","to":"Jang Useok","basis":"The Lung Bureau hands Jang Useok a list of modified parts without drawing-cabinet numbers. Jang Useok checks the measurement seals and remeasurement records so that out-of-spec parts do not hide behind blank numbers in the shipping list."}],"incoming":[]}}', '{"id":"person-0649","name":"허파서","title":"복구복무 기록관","position":"복구복무 기록관","characterId":"K649","rank":"조합원","commonTier":"T5","occupation":"등기·기록","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-02#인물-허파서","detailRoute":"/people/person-0649","birthDate":"2066-06-16","birthday":"06-16","age":60,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k649-drawing-number-check","name":"도면함 번호 대조","rating":60}],"traits":[{"id":"k649-action-priority","name":"번호 없는 개조 분리","description":"한재목에게 보낼 펌프 부품의 출고 목록이 규격 도면함 번호와 함께 기록관 당직으로 올라온다. 허파서는 부품마다 도면함 번호가 붙었는지 짚어 가고, 번호가 비어 있는 개조 부품은 강민서가 내치는 규격 밖 개조로 따로 묶어 출고 목록 뒤에 적는다.","behavior":"한재목에게 보낼 펌프 부품의 출고 목록이 규격 도면함 번호와 함께 기록관 당직으로 올라온다. 허파서는 부품마다 도면함 번호가 붙었는지 짚어 가고, 번호가 비어 있는 개조 부품은 강민서가 내치는 규격 밖 개조로 따로 묶어 출고 목록 뒤에 적는다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k649-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"한재목에게 보낼 펌프 부품의 출고 목록이 규격 도면함 번호와 함께 기록관 당직으로 올라온다. 허파서는 부품마다 도면함 번호가 붙었는지 짚어 가고, 번호가 비어 있는 개조 부품은 강민서가 내치는 규격 밖 개조로 따로 묶어 출고 목록 뒤에 적는다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-ae40-d574-8a31","name":"김해 허씨","crest":"clan-crests/d5c8-ae40-d574-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":15,"무력":-5,"물질":35,"공동":50,"원칙":30,"공개":35,"자격":55,"분산":15,"변혁":30},"desire":{"갈망":35,"독점":-40,"위험":5,"과시":10,"지속":5,"지향":"유동","결합":"다자"},"fields":{"소속":"자유도시","생업":"등기·기록","품계":"조합원","직함":"복구복무 기록관","업무 위치":"구로2동. 허파서는 구로2동 기록 당직에서 한재목에게 보낼 펌프 부품 출고 목록을 도면함 번호별로 대조한다. 번호가 빠진 개조 부품을 따로 묶어 강민서의 봉인 기록 뒤에 적고 다음 서기에게 확인을 요청한다.","가치관":"권위 −30 | 개방 15 | 무력 −5 | 물질 35 | 공동 50 | 원칙 30 | 공개 35 | 자격 55 | 분산 15 | 변혁 30","욕망":"갈망 35 | 독점 −40 | 위험 5 | 과시 10 | 지속 5 | 지향 유동 | 결합 다자"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 허파서는 구로2동 기록 당직에서 한재목에게 보낼 펌프 부품 출고 목록을 도면함 번호별로 대조한다. 번호가 빠진 개조 부품을 따로 묶어 강민서의 봉인 기록 뒤에 적고 다음 서기에게 확인을 요청한다.","관직":"품계 조합원. 직함은 복구복무 기록관. 번호가 빠진 개조 부품을 따로 묶어 강민서의 봉인 기록 뒤에 적고 다음 서기에게 확인을 요청한다.","일화":"한재목에게 보낼 펌프 부품의 출고 목록이 규격 도면함 번호와 함께 기록관 당직으로 올라온다. 허파서는 부품마다 도면함 번호가 붙었는지 짚어 가고, 번호가 비어 있는 개조 부품은 강민서가 내치는 규격 밖 개조로 따로 묶어 출고 목록 뒤에 적는다.","관계":"허파서는 도면함 번호 없는 개조 부품 목록을 장우석에게 넘긴다. 장우석은 계측 도장과 재측정 기록을 확인해 규격 밖 부품이 출고 목록의 빈 번호로 숨지 않게 한다.","야망":"허파서는 번호 없는 개조 부품을 출고 목록에서 따로 표시해 도면함과 계측 기록의 대조를 받으려 한다.","공포":"도면함 번호 없는 개조 부품이 출고 목록의 빈 칸으로 숨어 장우석의 계측 대조를 피하는 것.","개입":"플레이어는 허파서와 부품 번호를 도면함에 대조하거나 빠진 번호의 목록을 장우석에게 가져갈 수 있다."},"biography":"허파서는 번호 없는 개조 부품을 규격 부품의 출고 목록에 묻어 보내지 않는다.\n\n- 소속: 자유도시\n- 생업: 등기·기록\n- 품계: 조합원\n- 직함: 복구복무 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 허파서는 구로2동 기록 당직에서 한재목에게 보낼 펌프 부품 출고 목록을 도면함 번호별로 대조한다. 번호가 빠진 개조 부품을 따로 묶어 강민서의 봉인 기록 뒤에 적고 다음 서기에게 확인을 요청한다.\n\n**관직.** 품계 조합원. 직함은 복구복무 기록관. 번호가 빠진 개조 부품을 따로 묶어 강민서의 봉인 기록 뒤에 적고 다음 서기에게 확인을 요청한다.\n\n**일화.** 한재목에게 보낼 펌프 부품의 출고 목록이 규격 도면함 번호와 함께 기록관 당직으로 올라온다. 허파서는 부품마다 도면함 번호가 붙었는지 짚어 가고, 번호가 비어 있는 개조 부품은 강민서가 내치는 규격 밖 개조로 따로 묶어 출고 목록 뒤에 적는다.\n\n**관계.** 허파서는 도면함 번호 없는 개조 부품 목록을 장우석에게 넘긴다. 장우석은 계측 도장과 재측정 기록을 확인해 규격 밖 부품이 출고 목록의 빈 번호로 숨지 않게 한다.\n\n**야망.** 허파서는 번호 없는 개조 부품을 출고 목록에서 따로 표시해 도면함과 계측 기록의 대조를 받으려 한다.\n\n**공포.** 도면함 번호 없는 개조 부품이 출고 목록의 빈 칸으로 숨어 장우석의 계측 대조를 피하는 것.\n\n**개입.** 플레이어는 허파서와 부품 번호를 도면함에 대조하거나 빠진 번호의 목록을 장우석에게 가져갈 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 15 | 무력 −5 | 물질 35 | 공동 50 | 원칙 30 | 공개 35 | 자격 55 | 분산 15 | 변혁 30\n- 욕망: 갈망 35 | 독점 −40 | 위험 5 | 과시 10 | 지속 5 | 지향 유동 | 결합 다자\n:::","relations":{"outgoing":[{"from":"허파서","type":"계약","to":"장우석","basis":"허파서는 도면함 번호 없는 개조 부품 목록을 장우석에게 넘긴다. 장우석은 계측 도장과 재측정 기록을 확인해 규격 밖 부품이 출고 목록의 빈 번호로 숨지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0650', 'c720-ac15-b989', '{"id":"person-0650","name":"Yu Eunyeong","title":"Certification Courier","position":"Certification Courier","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0650","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0650","name":"유은영","title":"인증 전령","position":"인증 전령","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0650","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0651', 'b0a8-c758-b839', '{"id":"person-0651","name":"Nam Namwon","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K651","rank":"","commonTier":"T3","occupation":"Wheel & Pump Maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-Nam-Namwon","detailRoute":"/people/person-0651","birthDate":"2085-10-08","birthday":"10-08","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"pump","name":"Pump disassembly and shaft replacement","rating":55},{"id":"wheel","name":"Wheel-defect inspection","rating":40}],"traits":[{"id":"replace-only-necessary-axles","name":"Replace Only Necessary Axles","description":"Nam Namwon shows a targeted repair disposition by replacing only the pump''s confirmed worn axle.","behavior":"He dismantled the stopped pump, replaced one worn axle, and restarted it.","stress":"If a duty gap could lead to dependent passage, he may focus on the confirmed repair need.","relationship":"He may give the senior duty holder a concrete account of the replaced axle and the pump''s restart.","effects":[]},{"id":"hand-over-records-and-tools","name":"Hand Over Records and Tools","description":"Nam Namwon shows an inclination to connect repair experience and post records to the next duty holder, although tool handover itself is unverified.","behavior":"He repairs the pump and passes on his post''s keys and records, while the source does not document transferring tools.","stress":"If a duty gap could make passage hostage to a powerful state, he may emphasize handing over verifiable repair details and records.","relationship":"He may rely on handover that shares repair results and post records with the senior duty holder.","effects":[]}],"narrative":"She restarted a pump after replacing a worn shaft. Specific repair is supported; a parts-logistics title does not add trade expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43750-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K651","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43750-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":5,"Force":-25,"Material":45,"Communal":25,"Principle":-10,"Public":-20,"Eligibility":35,"Dispersed":15,"Transformative":-5},"desire":{"Longing":-10,"Monopoly":-10,"Risk":-20,"Display":15,"Sustained":0,"Orientation":"None","Union":"None"},"fields":{"Affiliation":"Arc","Livelihood":"Wheel & Pump Maintenance","Rank":"Teacher","Title":"Parts Logistics Merchant","Values":"Authority −5 | Openness 5 | Force −25 | Material 45 | Communal 25 | Principle −10 | Publicity −20 | Qualification 35 | Dispersion 15 | Transformation −5","Desires":"Craving −10 | Monopoly −10 | Risk −20 | Display 15 | Persistence 0 | Orientation Unoriented | Union None"},"sections":{"Life":"Generation of 2126. Nam Namwon grew up at Sinjeong Depot. Nam Namwon took the Parts Logistics Chief post after a defect report filed just before a derailment.\n- Nam Namwon''s parts logistics work is tied to Seongsu 2-ga 1-dong.","Offices":"Nam Namwon hands over only the keys and records attached to the post. Authority that does not exist is not invented.","Anecdote":"In 2125, Nam Namwon disassembled a stalled pump, ground down just one worn shaft, and got it running again. Because of this, the signature for the Parts Logistics Chief post was entered in the ledger.","Relationships":"Nam Namwon is bound by handover to the senior duty-holder of the same living sphere.","Ambition":"In the Parts Logistics Chief duty, Nam Namwon seeks to keep the Arc''s ledger continuous and unbroken.","Fear":"Nam Namwon fears that if the Parts Logistics Chief duty falls vacant, the Arc''s passage will become a hostage of the great powers.","Intervention":"Nam Namwon can set up a witness for a duty handover or expose an empty key."},"biography":"Nam Namwon chooses first not to break the duty chain. Nam Namwon trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Arc\n- Occupation: Wheel and pump maintenance\n- Rank: Instructor\n- Title: Parts Logistics Chief\n**Life.** Generation of 2126. Nam Namwon grew up at Sinjeong Depot. Nam Namwon took the Parts Logistics Chief post after a defect report filed just before a derailment.\n- Nam Namwon''s parts logistics work is tied to Seongsu 2-ga 1-dong.\n\n**Office.** Nam Namwon hands over only the keys and records attached to the post. Authority that does not exist is not invented.\n\n**Anecdote.** In 2125, Nam Namwon disassembled a stalled pump, ground down just one worn shaft, and got it running again. Because of this, the signature for the Parts Logistics Chief post was entered in the ledger.\n\n**Relationships.** Nam Namwon is bound by handover to the senior duty-holder of the same living sphere.\n\n**Ambition.** In the Parts Logistics Chief duty, Nam Namwon seeks to keep the Arc''s ledger continuous and unbroken.\n\n**Fear.** Nam Namwon fears that if the Parts Logistics Chief duty falls vacant, the Arc''s passage will become a hostage of the great powers.\n\n**Intervention.** Nam Namwon can set up a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 5 | Force −25 | Material 45 | Communal 25 | Principle −10 | Publicity −20 | Qualification 35 | Dispersion 15 | Transformation −5\n- Desires: Craving −10 | Monopoly −10 | Risk −20 | Display 15 | Persistence 0 | Orientation Unoriented | Union None\n:::","relations":{"outgoing":[{"from":"Nam Namwon","type":"Contract","to":"Heo Gyeom","basis":"Nam Namwon informs Heo Gyeom of the worn shaft replaced in the pump and its maintenance condition. Heo Gyeom examines the alley pump''s packing and the blocked section to confirm whether the same supply outage continues at other pumps."}],"incoming":[]}}', '{"id":"person-0651","name":"남남원","title":"부품 물류상","position":"부품 물류상","characterId":"K651","rank":"","commonTier":"T3","occupation":"차륜·펌프 정비","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-남남원","detailRoute":"/people/person-0651","birthDate":"2085-10-08","birthday":"10-08","age":41,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"pump","name":"펌프 분해·축 교체","rating":55},{"id":"wheel","name":"차륜 결함 점검","rating":40}],"traits":[{"id":"replace-only-necessary-axles","name":"필요한 축만 교체","description":"남남원은 펌프에서 확인된 마모 축만 교체하는 제한적 수리 성향을 보인다.","behavior":"정지한 펌프를 분해해 마모 축 하나를 교체하고 재가동했다.","stress":"당직 공백이 통행 종속으로 이어질까 우려되면 확인된 수리 필요에 집중하려 할 수 있다.","relationship":"선배 당직에게는 교체한 축과 펌프 재가동 결과를 구체적으로 전달하려 할 수 있다.","effects":[]},{"id":"hand-over-records-and-tools","name":"기록과 공구 인계","description":"남남원은 수리 경험과 자기 직위의 기록을 다음 당직에 잇는 성향을 보이지만 공구 인계 자체는 확인되지 않는다.","behavior":"펌프 수리를 수행하고 자기 직위의 열쇠와 기록을 넘기며 공구를 넘겼다는 행동은 자료에 없다.","stress":"당직 공백이 통행을 강국의 볼모로 만들까 우려되면 확인 가능한 수리 내용과 기록의 인계를 중시할 수 있다.","relationship":"선배 당직과는 수리 결과와 직위 기록을 공유하는 인계에 의지할 수 있다.","effects":[]}],"narrative":"펌프 분해 후 마모 축 하나를 교체해 재가동했다. 구체적 수리는 확인되며 부품 물류 직함으로 거래 전문성을 추가하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43750-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K651","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43750-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":5,"무력":-25,"물질":45,"공동":25,"원칙":-10,"공개":-20,"자격":35,"분산":15,"변혁":-5},"desire":{"갈망":-10,"독점":-10,"위험":-20,"과시":15,"지속":0,"지향":"무성향","결합":"없음"},"fields":{"소속":"Arc","생업":"차륜·펌프 정비","품계":"교사","직함":"부품 물류상","가치관":"권위 −5 | 개방 5 | 무력 −25 | 물질 45 | 공동 25 | 원칙 −10 | 공개 −20 | 자격 35 | 분산 15 | 변혁 −5","욕망":"갈망 −10 | 독점 −10 | 위험 −20 | 과시 15 | 지속 0 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2126년 세대. 남남원은 신정 차량기지에서 자랐다. 남남원은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 남남원의 부품 물류상 업무는 성수2가1동과 연결된다.","관직":"남남원은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 남남원은 정지했던 펌프를 분해해 마모 축 하나만 갈아 다시 돌렸다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"남남원은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"남남원은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"남남원은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"남남원은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"남남원은 당직을 끊지 않는 쪽을 먼저 고른다. 남남원은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 차륜·펌프 정비\n- 품계: 교사\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 남남원은 신정 차량기지에서 자랐다. 남남원은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 남남원의 부품 물류상 업무는 성수2가1동과 연결된다.\n\n**관직.** 남남원은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 남남원은 정지했던 펌프를 분해해 마모 축 하나만 갈아 다시 돌렸다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 남남원은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 남남원은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 남남원은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 남남원은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 5 | 무력 −25 | 물질 45 | 공동 25 | 원칙 −10 | 공개 −20 | 자격 35 | 분산 15 | 변혁 −5\n- 욕망: 갈망 −10 | 독점 −10 | 위험 −20 | 과시 15 | 지속 0 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"남남원","type":"계약","to":"허겸","basis":"남남원은 펌프에서 교체한 마모 축과 정비 상태를 허겸에게 알린다. 허겸은 골목 펌프의 패킹과 막힌 구간을 살펴 같은 공급 중단이 다른 펌프에서도 이어지는지 확인한다."}],"incoming":[]}}');
