INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0679', 'c548-c21c-d765', '{"id":"person-0679","name":"An Sanneul","title":"Utility Tunnel Duty Officer","position":"Utility Tunnel Duty Officer","rank":"Guild Member","commonTier":"T5","occupation":"Utility Tunnel Duty Log · Duty Key Handover","gender":"Female","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0679","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0679","name":"안산늘","title":"공동구 당직","position":"공동구 당직","rank":"조합원","commonTier":"T5","occupation":"공동구 당직 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0679","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
