INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0698', 'c6b0-b2e8-c591', '{"id":"person-0698","name":"U Geummin","title":"Certification Courier","position":"Certification Courier","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0698","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0698","name":"우금민","title":"인증 전령","position":"인증 전령","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0698","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0699', 'ad6c-b2a5-c131', '{"id":"person-0699","name":"Gu Seogyeol","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K699","rank":"","commonTier":"T3","occupation":"Parts Shipment Inspection","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-gu-seogyeol","detailRoute":"/people/person-0699","birthDate":"2083-05-14","birthday":"05-14","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"parts","name":"Defective-parts dispatch inspection","rating":50},{"id":"wheel","name":"Wheel-defect inspection","rating":40}],"traits":[{"id":"return-defects-before-shipment","name":"Return Defects Before Shipment","description":"Gu Seogyeol shows a reluctance to send defective parts onward even immediately before shipment.","behavior":"He returned a box of defective parts just before shipment.","stress":"Even when concerned about duty gaps and dependent passage, he may hesitate to release confirmed defective parts.","relationship":"He may pass along both the returned box and the grounds for judging it defective to the senior duty holder.","effects":[]},{"id":"preserve-handover-grounds","name":"Preserve Handover Grounds","description":"Gu Seogyeol values connecting shipment decisions to records that leave grounds for the next duty holder.","behavior":"He returns the defective box and keeps handover within his post''s keys and records.","stress":"If vacant duty could make passage hostage to a powerful state, he may emphasize linking the return reason to handover records.","relationship":"He may share records that allow the senior duty holder to verify the reason for returning the defective parts.","effects":[]}],"narrative":"He returned defective parts just before dispatch. Physical checks and defect reporting are supported, not production design.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43760-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K699","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43760-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":15,"Force":-25,"Material":50,"Communal":25,"Principle":-5,"Public":-25,"Eligibility":35,"Dispersed":10,"Transformative":5},"desire":{"Longing":35,"Monopoly":10,"Risk":-25,"Display":30,"Sustained":20,"Orientation":"None","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Parts Shipment Inspection","Rank":"Teacher","Title":"Parts Logistics Merchant","Values":"Authority −5 | Openness 15 | Force −25 | Materialism 50 | Communalism 25 | Principle −5 | Transparency −25 | Qualification 35 | Decentralization 10 | Transformation 5","Desires":"Craving 35 | Possessiveness 10 | Risk −25 | Display 30 | Persistence 20 | Orientation None | Bonding Non-monogamous"},"sections":{"Life":"Generation of 2126. Gu Seogyeol grew up at the Sinjeong Depot. Gu Seogyeol took the post of Parts Logistics Merchant after a defect report just before a derailment.\n- Gu Seogyeol''s parts logistics work is connected to Seongsu 2-ga 1-dong.","Offices":"Gu Seogyeol hands over only the keys and records that come with the post. He does not invent authority that does not exist.","Anecdote":"In 2125, Gu Seogyeol sent a box of defective parts back just before shipment. Because of this, the signature of the Parts Logistics Chief post entered the ledger.","Relationships":"Gu Seogyeol is bound by handover to the senior watch-keeper of the same living sphere.","Ambition":"As Parts Logistics Chief on watch, Gu Seogyeol wants to keep the Arc''s ledger connected without a break.","Fear":"Gu Seogyeol fears that if the Parts Logistics Chief''s watch falls vacant, the Arc''s passage will become a hostage to a great power.","Intervention":"Gu Seogyeol can set up a witness for a watch handover or expose an empty key."},"biography":"Gu Seogyeol would rather keep the watch unbroken. Gu Seogyeol trusts a single line in the ledger more than a loud voice.\n\n- Affiliation: Arc\n- Occupation: Parts shipment inspection\n- Rank: Instructor\n- Title: Parts Logistics Chief\n**Life.** Generation of 2126. Gu Seogyeol grew up at the Sinjeong rail depot. Gu Seogyeol took the post of Parts Logistics Chief after reporting a defect just before a derailment.\n- Gu Seogyeol''s Parts Logistics Chief duties are connected to Seongsu 2-ga 1-dong.\n\n**Office.** Gu Seogyeol hands over only the keys and records that come with the post. He does not invent authority that does not exist.\n\n**Anecdote.** In 2125, Gu Seogyeol sent a box of defective parts back just before shipment. Because of this, the signature of the Parts Logistics Chief post entered the ledger.\n\n**Relations.** Gu Seogyeol is bound by handover to the senior watch-keeper of the same living sphere.\n\n**Ambition.** As Parts Logistics Chief on watch, Gu Seogyeol wants to keep the Arc''s ledger connected without a break.\n\n**Fear.** Gu Seogyeol fears that if the Parts Logistics Chief''s watch falls vacant, the Arc''s passage will become a hostage to a great power.\n\n**Intervention.** Gu Seogyeol can set up a witness for a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −5 | Openness 15 | Force −25 | Material 50 | Communal 25 | Principle −5 | Publicity −25 | Qualification 35 | Dispersion 10 | Transformation 5\n- Desires: Craving 35 | Monopoly 10 | Risk −25 | Display 30 | Continuity 20 | Orientation None | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Gu Seogyeol","type":"Contract","to":"Bak Serin","basis":"Gu Seogyeol sends the defective pump parts screened out before dispatch back to Bak Serin. Bak Serin checks the parts in the separate warehouse and the elder''s seal to find where the defective box got mixed in with the normal shipments."}],"incoming":[]}}', '{"id":"person-0699","name":"구서결","title":"부품 물류상","position":"부품 물류상","characterId":"K699","rank":"","commonTier":"T3","occupation":"부품 출고 검사","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-구서결","detailRoute":"/people/person-0699","birthDate":"2083-05-14","birthday":"05-14","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"parts","name":"불량 부품 출고 검사","rating":50},{"id":"wheel","name":"차륜 결함 점검","rating":40}],"traits":[{"id":"return-defects-before-shipment","name":"출고 직전 불량 반송","description":"구서결은 출고 직전이라도 불량 부품을 그대로 보내지 않는 성향을 보인다.","behavior":"불량 부품 상자를 출고 직전에 되돌려 보냈다.","stress":"당직 공백과 통행 종속을 우려하더라도 확인된 불량을 출고시키는 데 신중할 수 있다.","relationship":"선배 당직에게는 반송한 상자와 불량이라는 판단 근거를 함께 전달하려 할 수 있다.","effects":[]},{"id":"preserve-handover-grounds","name":"인계 근거 보존","description":"구서결은 출고 판단을 기록과 연결해 다음 당직에 근거를 남기는 쪽을 중시한다.","behavior":"불량 상자를 반송하고 자기 직위의 열쇠와 기록을 넘기는 범위를 지킨다.","stress":"당직이 비어 통행이 강국의 볼모가 될까 우려되면 반송 이유와 인계 기록의 연결을 중시할 수 있다.","relationship":"선배 당직과는 불량 반송의 이유를 확인할 수 있는 기록을 공유하려 할 수 있다.","effects":[]}],"narrative":"불량 부품 상자를 출고 직전에 돌려보냈다. 실물 점검과 결함 보고 생애가 근거이며 생산 설계는 확인되지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43760-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K699","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43760-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ad6c-b2a5-c131","name":"능성 구씨","crest":"clan-crests/ad6c-b2a5-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":15,"무력":-25,"물질":50,"공동":25,"원칙":-5,"공개":-25,"자격":35,"분산":10,"변혁":5},"desire":{"갈망":35,"독점":10,"위험":-25,"과시":30,"지속":20,"지향":"무성향","결합":"비독점"},"fields":{"소속":"Arc","생업":"부품 출고 검사","품계":"교사","직함":"부품 물류상","가치관":"권위 −5 | 개방 15 | 무력 −25 | 물질 50 | 공동 25 | 원칙 −5 | 공개 −25 | 자격 35 | 분산 10 | 변혁 5","욕망":"갈망 35 | 독점 10 | 위험 −25 | 과시 30 | 지속 20 | 지향 무성향 | 결합 비독점"},"sections":{"생애":"2126년 세대. 구서결은 신정 차량기지에서 자랐다. 구서결은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 구서결의 부품 물류상 업무는 성수2가1동과 연결된다.","관직":"구서결은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 구서결은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"구서결은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"구서결은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"구서결은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"구서결은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"구서결은 당직을 끊지 않는 쪽을 먼저 고른다. 구서결은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 부품 출고 검사\n- 품계: 교사\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 구서결은 신정 차량기지에서 자랐다. 구서결은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 구서결의 부품 물류상 업무는 성수2가1동과 연결된다.\n\n**관직.** 구서결은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 구서결은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 구서결은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 구서결은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 구서결은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 구서결은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 15 | 무력 −25 | 물질 50 | 공동 25 | 원칙 −5 | 공개 −25 | 자격 35 | 분산 10 | 변혁 5\n- 욕망: 갈망 35 | 독점 10 | 위험 −25 | 과시 30 | 지속 20 | 지향 무성향 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"구서결","type":"계약","to":"박세린","basis":"구서결은 출고 전에 가려낸 불량 펌프 부품을 박세린에게 돌려보낸다. 박세린은 별도 창고의 부품과 원로 날인을 확인해 불량 상자가 정상 출고품과 섞인 곳을 찾는다."}],"incoming":[]}}');
