INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0710', 'c7a5-d765-b355', '{"id":"person-0710","name":"Jang Hawon","title":"Escort Logistics Merchant","position":"Myeongdong Station Relief Supplies Duty","rank":"Congregationioner","commonTier":"T5","occupation":"Relief Supplies Handover Records","gender":"Female","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0710","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0710","name":"장하원","title":"호송 물류상","position":"명동역 구휼 물자 당직","rank":"교우","commonTier":"T5","occupation":"구휼 물자 인수인계 기록","gender":"여성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0710","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0711', 'c784-d48d-cc9c-4efb', '{"id":"person-0711","name":"Im Dongu","title":"Escort Patrol","position":"Escort Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Escort Patrol Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0711","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0711","name":"임동우","title":"호송 순찰대","position":"호송 순찰대","rank":"조합원","commonTier":"T5","occupation":"호송 순찰 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0711","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0712', 'd55c-ccad-c8fc', '{"id":"person-0712","name":"Han Bugu","title":"Ration District Clerk","position":"Ration District Clerk","characterId":"K712","rank":"Clerk","commonTier":"T5","occupation":"Water Distribution Duty","gender":"Female","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-han-bugu","detailRoute":"/people/person-0712","birthDate":"2093-04-21","birthday":"04-21","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k712-release-discussion","name":"Release discussion","rating":50}],"traits":[{"id":"k712-action-priority","name":"Discussion during drought","description":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","behavior":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]},{"id":"k712-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]}],"narrative":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d55c-ccad-c8fc","name":"Han Clan of Cheongju","crest":"clan-crests/d55c-ccad-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":45,"Openness":-15,"Force":5,"Material":55,"Communal":10,"Principle":10,"Public":0,"Eligibility":5,"Dispersed":-50,"Transformative":-15},"desire":{"Longing":50,"Monopoly":10,"Risk":5,"Display":10,"Sustained":35,"Orientation":"Reason","Union":"Monogamy"},"fields":{"Affiliation":"Free City","Livelihood":"Water Distribution Duty","Rank":"Clerk","Title":"Ration District Clerk","Work Location":"Sinjeong 2-dong. In the 2125 drought, Han Bugu spent the night cross-checking Seoul''s reservoir levels against the ration representatives'' requests for release, then handed the result over to I Seodam''s water supply watch in Sinjeong 2-dong.","Values":"Authority 45 | Openness −15 | Force 5 | Material 55 | Communal 10 | Principle 10 | Publicity 0 | Qualification 5 | Dispersion −50 | Transformation −15","Desires":"Craving 50 | Monopoly 10 | Risk 5 | Display 10 | Continuity 35 | Orientation Heterosexual | Bonding Monogamous"},"sections":{"Life":"Generation of 2126. Raised at the Yeongdeungpo Water Purification Watch. The post of Ration District Clerk opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. In the 2125 drought, Han Bugu spent the night cross-checking Seoul''s reservoir levels against the ration representatives'' requests for release, then handed the result over to I Seodam''s water supply watch in Sinjeong 2-dong.","Offices":"Rank: Administrator. Title: Ration District Clerk. In the 2125 drought, Han Bugu spent the night cross-checking Seoul''s reservoir levels against the ration representatives'' requests for release, then handed the result over to I Seodam''s water supply watch in Sinjeong 2-dong.","Anecdote":"In the 2125 drought, Han Bugu matched Seoul''s ration reservoir levels against the representatives'' requests for release and left a record for the next watch to read.","Relationships":"Works as Lee Seodam''s Ration District Clerk and takes the water distribution watch.","Ambition":"In the post of Ration District Clerk, keeps the Water Gate Bureau''s ledger linked without a break.","Fear":"That the Water Gate Bureau''s passage becomes a hostage of the great powers if the Ration District Clerk''s watch is left vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Han Bugu would rather keep the watch unbroken. Han Bugu trusts a single line in the ledger more than a loud voice.\n\n- Affiliation: Free City\n- Occupation: Water distribution watch\n- Rank: Administrator\n- Title: Ration District Clerk\n**Life.** Generation of 2126. Raised at the Yeongdeungpo Water Purification Watch. The post of Ration District Clerk opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. In the 2125 drought, Han Bugu spent the night cross-checking Seoul''s reservoir levels against the ration representatives'' requests for release, then handed the result over to I Seodam''s water supply watch in Sinjeong 2-dong.\n\n**Office.** Rank: Administrator. Title: Ration District Clerk. In the 2125 drought, Han Bugu spent the night cross-checking Seoul''s reservoir levels against the ration representatives'' requests for release, then handed the result over to I Seodam''s water supply watch in Sinjeong 2-dong.\n\n**Anecdote.** In the 2125 drought, Han Bugu matched Seoul''s ration reservoir levels against the representatives'' requests for release and left a record for the next watch to read.\n\n**Relations.** Works as I Seodam''s Ration District Clerk and handles the water distribution watch.\n\n**Ambition.** From the post of Ration District Clerk, keeps the Floodgate Bureau''s ledger connected without a break.\n\n**Fear.** That if the Ration District Clerk''s watch falls vacant, the Floodgate Bureau''s passage will become a hostage to a great power.\n\n**Intervention.** Can set up a witness for a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 45 | Openness −15 | Force 5 | Material 55 | Communal 10 | Principle 10 | Publicity 0 | Qualification 5 | Dispersion −50 | Transformation −15\n- Desires: Craving 50 | Monopoly 10 | Risk 5 | Display 10 | Continuity 35 | Orientation Heterosexual | Bonding Monogamous\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Han Bugu","type":"Command","to":"I Seo-dam","basis":"Serves as clerk of Yi Seodam''s ration district and holds the water distribution watch"}],"incoming":[]}}', '{"id":"person-0712","name":"한북우","title":"배급구역 서기","position":"배급구역 서기","characterId":"K712","rank":"주사","commonTier":"T5","occupation":"급수 배분 당직","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-한북우","detailRoute":"/people/person-0712","birthDate":"2093-04-21","birthday":"04-21","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k712-release-discussion","name":"방류량 협의","rating":50}],"traits":[{"id":"k712-action-priority","name":"가뭄의 논의","description":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","behavior":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]},{"id":"k712-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]}],"narrative":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d55c-ccad-c8fc","name":"청주 한씨","crest":"clan-crests/d55c-ccad-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":45,"개방":-15,"무력":5,"물질":55,"공동":10,"원칙":10,"공개":0,"자격":5,"분산":-50,"변혁":-15},"desire":{"갈망":50,"독점":10,"위험":5,"과시":10,"지속":35,"지향":"이성","결합":"단혼"},"fields":{"소속":"자유도시","생업":"급수 배분 당직","품계":"주사","직함":"배급구역 서기","업무 위치":"신정2동. 한북우는 2125년 가뭄에 서울의 저수조 수위와 배급 대표의 방류 요청을 밤새 대조한 뒤 신정2동 이서담의 급수 당직에 넘긴다.","가치관":"권위 45 | 개방 −15 | 무력 5 | 물질 55 | 공동 10 | 원칙 10 | 공개 0 | 자격 5 | 분산 −50 | 변혁 −15","욕망":"갈망 50 | 독점 10 | 위험 5 | 과시 10 | 지속 35 | 지향 이성 | 결합 단혼"},"sections":{"생애":"2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 한북우는 2125년 가뭄에 서울의 저수조 수위와 배급 대표의 방류 요청을 밤새 대조한 뒤 신정2동 이서담의 급수 당직에 넘긴다.","관직":"품계 주사. 직함은 배급구역 서기이다. 한북우는 2125년 가뭄에 서울의 저수조 수위와 배급 대표의 방류 요청을 밤새 대조한 뒤 신정2동 이서담의 급수 당직에 넘긴다.","일화":"2125년 가뭄에 한북우는 서울 배급 저수조 수위와 대표의 방류 요청을 맞대어 다음 당직이 읽을 기록을 남겼다.","관계":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","야망":"배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 급수 배분 당직\n- 품계: 주사\n- 직함: 배급구역 서기\n**생애.** 2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 한북우는 2125년 가뭄에 서울의 저수조 수위와 배급 대표의 방류 요청을 밤새 대조한 뒤 신정2동 이서담의 급수 당직에 넘긴다.\n\n**관직.** 품계 주사. 직함은 배급구역 서기이다. 한북우는 2125년 가뭄에 서울의 저수조 수위와 배급 대표의 방류 요청을 밤새 대조한 뒤 신정2동 이서담의 급수 당직에 넘긴다.\n\n**일화.** 2125년 가뭄에 한북우는 서울 배급 저수조 수위와 대표의 방류 요청을 맞대어 다음 당직이 읽을 기록을 남겼다.\n\n**관계.** 이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.\n\n**야망.** 배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 45 | 개방 −15 | 무력 5 | 물질 55 | 공동 10 | 원칙 10 | 공개 0 | 자격 5 | 분산 −50 | 변혁 −15\n- 욕망: 갈망 50 | 독점 10 | 위험 5 | 과시 10 | 지속 35 | 지향 이성 | 결합 단혼\n:::","directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"한북우","type":"지휘","to":"이서담","basis":"이서담의 배급구역 서기로 급수 배분 당직을 맡음"}],"incoming":[]}}');
