INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0722', 'ace0-d55c-c591', '{"id":"person-0722","name":"Go Paho","title":"Escort Courier","position":"Gangnam Station Escort Courier","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station Escort Records and Keys Handover","gender":"Male","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0722","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0722","name":"고파호","title":"호송 전령","position":"강남역 호송 전령","rank":"사원","commonTier":"T5","occupation":"강남역 호송 기록·열쇠 인계","gender":"남성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0722","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0723', 'bb38-b0a8-d3c9-6587', '{"id":"person-0723","name":"Mun Eunmin","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0723","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0723","name":"문은민","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0723","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0724', 'c591-b0a8-c6d0-694a', '{"id":"person-0724","name":"Yang Namtae","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K724","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-yang-namtae","detailRoute":"/people/person-0724","birthDate":"2083-01-04","birthday":"01-04","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"Ledger preservation","rating":40}],"traits":[{"id":"stated-priority","name":"People records before the flames","description":"During the station fire the people ledger came out first. Prioritizing records in danger is supported; prescribing ability remains separately unconfirmed.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"During the station fire the people ledger came out first. Prioritizing records in danger is supported; prescribing ability remains separately unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c591-b0a8-c6d0-694a","name":"Namwon Yang Clan","crest":"clan-crests/c591-b0a8-c6d0-694a.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":20,"Force":-55,"Material":-25,"Communal":20,"Principle":40,"Public":20,"Eligibility":20,"Dispersed":10,"Transformative":-10},"desire":{"Longing":30,"Monopoly":20,"Risk":-10,"Display":5,"Sustained":15,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −25 | Openness 20 | Force −55 | Materialism −25 | Community 20 | Principle 40 | Publicity 20 | Qualification 20 | Dispersion 10 | Transformation −10","Desires":"Craving 30 | Possessiveness 20 | Risk −10 | Display 5 | Persistence 15 | Orientation same-sex | Bonding non-exclusive"},"sections":{"Life":"Born on 2083-01-04. As of the opening in 2126, he holds the Prescription Clerk post and carries on its existing duty shifts and records. In the succession record for that post, it opened as a substitute duty shift for an unexcused absence from the rotation.\n- The prescription-record and duty-key handover desk in Jegi-dong is taken as Yang Namtae''s work reference point. This placement does not fix a residence, exact facility boundaries, a title of nobility, a fief or a right of possession.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In the 2125 station fire, carried out the register of lives first. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Yang Namtae hands over the patient roster and prescription records he has kept to Jeon Sol. Jeon Sol checks the bed waitlist and severity to find the missing names, so that the loss of records does not lead to anyone being dropped from treatment.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the duty shift. He trusts a single line in the ledger over loud talk.\n\n- Livelihood: prescription record and duty-key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Prescription Clerk\n**Life.** Born on 2083-01-04. As of the opening in 2126, he holds the Prescription Clerk post and carries on its existing duty shifts and records. In the succession record for that post, it opened as a substitute duty shift for an unexcused absence from the rotation.\n- The prescription-record and duty-key handover desk in Jegi-dong is taken as Yang Namtae''s work reference point. This placement does not fix a residence, exact facility boundaries, a title of nobility, a fief or a right of possession.\n\n**Office.** Rank: Resident. Title: Prescription Resident. Hands over only the keys and records of his own post, and writes in the ledger the time at which the handed-over keys and records were received.\n\n**Anecdote.** During the historic fire of 2125, he carried out the register of lives first. That day''s record remained as handover evidence for the next duty shift to verify.\n\n**Relations.** Yang Namtae hands the patient roster and prescription records he has kept over to Jeon Sol. Jeon Sol checks the bed queue and the severity of cases to find missing names, so that lost records do not lead to omitted treatment.\n\n**Ambition.** To keep the White Cross Order''s books unbroken from the Prescription Resident post.\n\n**Fear.** He fears that if the Prescription Resident''s duty shift goes unfilled, the White Cross Order''s passage will become hostage to Seoul''s internal patron factions.\n\n**Intervention.** Can bring in a witness to a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 20 | Force −55 | Materialism −25 | Community 20 | Principle 40 | Publicity 20 | Qualification 20 | Dispersion 10 | Transformation −10\n- Desires: Craving 30 | Possessiveness 20 | Risk −10 | Display 5 | Persistence 15 | Orientation same-sex | Bonding non-exclusive\n:::","relations":{"outgoing":[{"from":"Yang Namtae","type":"Contract","to":"Jeon Sol","basis":"Yang Namtae hands over the patient roster and prescription records he has kept to Jeon Sol. Jeon Sol checks the bed waitlist and severity to find the missing names, so that the loss of records does not lead to anyone being dropped from treatment."}],"incoming":[]}}', '{"id":"person-0724","name":"양남태","title":"처방 서기","position":"처방 서기","characterId":"K724","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-양남태","detailRoute":"/people/person-0724","birthDate":"2083-01-04","birthday":"01-04","age":43,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"장부 보존","rating":40}],"traits":[{"id":"stated-priority","name":"불길보다 인명 기록","description":"역사 화재에서 인명 장부를 먼저 들고 나왔다. 위기 때 기록을 우선한 사실은 있지만 처방 실력은 별도 미확인이다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"역사 화재에서 인명 장부를 먼저 들고 나왔다. 위기 때 기록을 우선한 사실은 있지만 처방 실력은 별도 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c591-b0a8-c6d0-694a","name":"남원 양씨","crest":"clan-crests/c591-b0a8-c6d0-694a.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":20,"무력":-55,"물질":-25,"공동":20,"원칙":40,"공개":20,"자격":20,"분산":10,"변혁":-10},"desire":{"갈망":30,"독점":20,"위험":-10,"과시":5,"지속":15,"지향":"동성","결합":"비독점"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −25 | 개방 20 | 무력 −55 | 물질 −25 | 공동 20 | 원칙 40 | 공개 20 | 자격 20 | 분산 10 | 변혁 −10","욕망":"갈망 30 | 독점 20 | 위험 −10 | 과시 5 | 지속 15 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2083-01-04에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 양남태의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"양남태는 보관한 환자 명부와 처방 기록을 전솔에게 넘긴다. 전솔은 병상 대기와 중증도를 확인해 빠진 이름을 찾고 기록 손실이 진료 누락으로 이어지지 않게 한다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2083-01-04에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 양남태의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 양남태는 보관한 환자 명부와 처방 기록을 전솔에게 넘긴다. 전솔은 병상 대기와 중증도를 확인해 빠진 이름을 찾고 기록 손실이 진료 누락으로 이어지지 않게 한다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 20 | 무력 −55 | 물질 −25 | 공동 20 | 원칙 40 | 공개 20 | 자격 20 | 분산 10 | 변혁 −10\n- 욕망: 갈망 30 | 독점 20 | 위험 −10 | 과시 5 | 지속 15 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"양남태","type":"계약","to":"전솔","basis":"양남태는 보관한 환자 명부와 처방 기록을 전솔에게 넘긴다. 전솔은 병상 대기와 중증도를 확인해 빠진 이름을 찾고 기록 손실이 진료 누락으로 이어지지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0725', 'c190-bc00-c591', '{"id":"person-0725","name":"Son Neuryeon","title":"Ridge Patrol","position":"Agwansa Ridge Patrol","rank":"Sergeant","commonTier":"T5","occupation":"Ridge Patrol Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0725","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0725","name":"손늘연","title":"능선 순찰대","position":"아관사 능선 순찰대","rank":"병장","commonTier":"T5","occupation":"능선 순찰 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0725","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0726', 'bc30-d765-d574-88f5', '{"id":"person-0726","name":"Bae Darwon","title":"Warehouse Duty Officer","position":"Myeongdong Station Confirmation Roster Duty Officer","rank":"Congregationioner","commonTier":"T5","occupation":"Confirmation Roster Handover Record","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0726","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0726","name":"배달원","title":"창고 당직","position":"명동역 인준 명부 당직","rank":"교우","commonTier":"T5","occupation":"인준 명부 인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0726","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0727', 'bc31-c218-c6d0', '{"id":"person-0727","name":"Baek Reumrae","title":"Utility Tunnel Duty Officer","position":"Utility Tunnel Duty Officer","rank":"Guild Member","commonTier":"T5","occupation":"Utility Tunnel Duty Log · Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0727","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0727","name":"백름래","title":"공동구 당직","position":"공동구 당직","rank":"조합원","commonTier":"T5","occupation":"공동구 당직 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0727","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0728', 'd5c8-d558-c591-8a31', '{"id":"person-0728","name":"Heo Bau","title":"Bridge Passage Herald","position":"Bridge Passage Herald","characterId":"K728","rank":"Clerk","commonTier":"T5","occupation":"Bridge Guard Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-heo-bau","detailRoute":"/people/person-0728","birthDate":"2102-07-02","birthday":"07-02","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":8,"effective":8},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":6,"effective":6}},"skills":[{"id":"k728-ambush-trace-reading","name":"Reading ambush traces","rating":55}],"traits":[{"id":"k728-action-priority","name":"Read traces first","description":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger.","behavior":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger.","stress":"That the bridge passage courier duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves under Kim Taeun on bridge passage and night-crossing reports.","effects":[]},{"id":"k728-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the bridge passage courier duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves under Kim Taeun on bridge passage and night-crossing reports.","effects":[]}],"narrative":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d558-c591-8a31","name":"Hayang Heo Clan","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":60,"Openness":0,"Force":20,"Material":20,"Communal":10,"Principle":15,"Public":20,"Eligibility":10,"Dispersed":-55,"Transformative":-25},"desire":{"Longing":40,"Monopoly":10,"Risk":-35,"Display":-25,"Sustained":-20,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Affiliation":"Free City","Livelihood":"Bridge Guard Duty","Rank":"Clerk","Title":"Bridge Passage Herald","Work Location":"Dangsan 2-dong. In 2125, Heo Bau read the traces of an ambush on a patrol of Seoul''s hill paths from the Amsa guard post and prevented casualties. He now passes the trace-reading he learned then, along with the nighttime river-crossing reports, to Kim Taeun''s bridge duty shift in Dangsan 2-dong.","Values":"Authority 60 | Openness 0 | Force 20 | Materialism 20 | Community 10 | Principle 15 | Publicity 20 | Qualification 10 | Dispersion −55 | Transformation −25","Desires":"Craving 40 | Possessiveness 10 | Risk −35 | Display −25 | Persistence −20 | Orientation opposite-sex | Bonding polyamorous"},"sections":{"Life":"Born in the 2126 cohort. Grew up at the Amsa guard post. The Bridge Crossing Herald post opened after an unauthorized night crossing was caught.\n- Duty station: Dangsan 2-dong. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.","Offices":"Rank: Clerk. Title: Bridge Crossing Herald. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.","Anecdote":"In 2125, on the Seoul hill-road patrol connected to the Amsa guard post, Heo Ba-u found the ambush traces first and warned the guard unit, then turned back the people crossing and prevented losses.","Relationships":"Under Kim Taeun''s command, handles bridge passage and nighttime river-crossing reports.","Ambition":"From the Bridge Crossing Herald post, he keeps the Water Gate Bureau''s ledger connected without a break.","Fear":"That if the Bridge Passage Courier''s duty shift goes unfilled, the Floodgate Bureau''s passage will become hostage to a major power.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the watch. He trusts a single line in the ledger over loud talk.\n\n- Affiliation: Water Gate Bureau\n- Occupation: Bridge guard duty\n- Rank: Clerk\n- Title: Bridge Crossing Herald\n**Life.** Born in the 2126 cohort. Grew up at the Amsa guard post. The Bridge Crossing Herald post opened after an unauthorized night crossing was caught.\n- Duty station: Dangsan 2-dong. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.\n\n**Office.** Rank: Clerk. Title: Bridge Crossing Herald. In 2125, Heo Ba-u read ambush traces on the Seoul hill-road patrol out of the Amsa guard post and prevented losses. Now he shares the trace-reading he learned then, along with the night crossing reports, with Kim Tae-un''s bridge watch at Dangsan 2-dong.\n\n**Anecdote.** In 2125, on the Seoul hill-road patrol connected to the Amsa guard post, Heo Ba-u found the ambush traces first and warned the guard unit, then turned back the people crossing and prevented losses.\n\n**Relations.** Under Kim Tae-un''s command, he handles bridge crossings and night crossing reports.\n\n**Ambition.** From the Bridge Crossing Herald post, he keeps the Water Gate Bureau''s ledger connected without a break.\n\n**Fear.** That if the Bridge Crossing Herald watch stands empty, the Water Gate Bureau''s passage will become a hostage to the powerful states.\n\n**Intervention.** He can bring in a witness for a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority 60 | Openness 0 | Force 20 | Material 20 | Community 10 | Principle 15 | Publicity 20 | Qualification 10 | Decentralization −55 | Transformation −25\n- Desires: Craving 40 | Exclusivity 10 | Risk −35 | Display −25 | Persistence −20 | Orientation: opposite-sex | Bonding: multiple partners\n:::","directLiege":{"personId":"K003","name":"Gim Tae-un","courtId":"court:K003","effectiveYear":2126},"relations":{"outgoing":[{"from":"Heo Bau","type":"Command","to":"Gim Tae-un","basis":"Handles bridge traffic and night-crossing reports under Gim Taeun''s command"}],"incoming":[]}}', '{"id":"person-0728","name":"허바우","title":"교량 통행 전령","position":"교량 통행 전령","characterId":"K728","rank":"주사","commonTier":"T5","occupation":"교량 경비 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-허바우","detailRoute":"/people/person-0728","birthDate":"2102-07-02","birthday":"07-02","age":24,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":8,"effective":8},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":6,"effective":6}},"skills":[{"id":"k728-ambush-trace-reading","name":"매복 흔적 확인","rating":55}],"traits":[{"id":"k728-action-priority","name":"흔적을 먼저 읽는다","description":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","behavior":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","stress":"교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","effects":[]},{"id":"k728-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","effects":[]}],"narrative":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d558-c591-8a31","name":"하양 허씨","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":60,"개방":0,"무력":20,"물질":20,"공동":10,"원칙":15,"공개":20,"자격":10,"분산":-55,"변혁":-25},"desire":{"갈망":40,"독점":10,"위험":-35,"과시":-25,"지속":-20,"지향":"이성","결합":"다자"},"fields":{"소속":"자유도시","생업":"교량 경비 당직","품계":"주사","직함":"교량 통행 전령","업무 위치":"당산2동. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.","가치관":"권위 60 | 개방 0 | 무력 20 | 물질 20 | 공동 10 | 원칙 15 | 공개 20 | 자격 10 | 분산 −55 | 변혁 −25","욕망":"갈망 40 | 독점 10 | 위험 −35 | 과시 −25 | 지속 −20 | 지향 이성 | 결합 다자"},"sections":{"생애":"2126년 세대. 암사 경비 초소에서 자랐다. 교량 통행 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 업무 위치: 당산2동. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.","관직":"품계 주사. 직함은 교량 통행 전령이다. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.","일화":"2125년 암사 경비 초소와 이어지는 서울 언덕길 초계에서 허바우는 매복 흔적을 먼저 찾아 경비대에 알렸고 통행 인원을 돌려 피해를 막았다.","관계":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","야망":"교량 통행 전령 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 교량 경비 당직\n- 품계: 주사\n- 직함: 교량 통행 전령\n**생애.** 2126년 세대. 암사 경비 초소에서 자랐다. 교량 통행 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 업무 위치: 당산2동. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.\n\n**관직.** 품계 주사. 직함은 교량 통행 전령이다. 허바우는 2125년 암사 경비 초소의 서울 언덕길 초계에서 매복 흔적을 읽어 피해를 막았다. 지금은 그때 배운 흔적 판독을 야간 도하 보고와 나누어 김태운의 당산2동 교량 당직에 전한다.\n\n**일화.** 2125년 암사 경비 초소와 이어지는 서울 언덕길 초계에서 허바우는 매복 흔적을 먼저 찾아 경비대에 알렸고 통행 인원을 돌려 피해를 막았다.\n\n**관계.** 김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.\n\n**야망.** 교량 통행 전령 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 60 | 개방 0 | 무력 20 | 물질 20 | 공동 10 | 원칙 15 | 공개 20 | 자격 10 | 분산 −55 | 변혁 −25\n- 욕망: 갈망 40 | 독점 10 | 위험 −35 | 과시 −25 | 지속 −20 | 지향 이성 | 결합 다자\n:::","directLiege":{"personId":"K003","name":"김태운","courtId":"court:K003","effectiveYear":2126},"relations":{"outgoing":[{"from":"허바우","type":"지휘","to":"김태운","basis":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡음"}],"incoming":[]}}');
