INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0730', 'b0a8-c758-b839', '{"id":"person-0730","name":"Nam Saewon","title":"Water Quality Gauger","position":"Water Quality Gauger","rank":"Assistant Manager","commonTier":"T5","occupation":"Duty Log Handover","gender":"Male","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0730","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0730","name":"남새원","title":"수질 계측원","position":"수질 계측원","rank":"대리","commonTier":"T5","occupation":"당직 기록 인수인계","gender":"남성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0730","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0731', 'b178-c7a5-c5f0-76e7', '{"id":"person-0731","name":"No Baa","title":"Workshop Herald","position":"Workshop Herald","characterId":"K731","rank":"Teacher","commonTier":"T5","occupation":"Timetable · Departure Check","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#character-noh-ba-a","detailRoute":"/people/person-0731","birthDate":"2097-07-25","birthday":"07-25","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure","name":"Departure and dispatch checks","rating":50},{"id":"handover","name":"Record and key handover","rating":40}],"traits":[{"id":"stop-unmarked-trains","name":"Stop Unmarked Trains","description":"No Baa shows a verification-centered reluctance to permit a train to depart without a dispatch sheet.","behavior":"He stopped a train without a dispatch sheet and prevented an unsigned departure.","stress":"If a duty gap could make passage hostage to a powerful state, he may pay closer attention to missing departure documentation.","relationship":"He may clearly tell the senior duty holder that departure was stopped because the dispatch sheet and signature were missing.","effects":[]},{"id":"respect-explicit-authority","name":"Respect Explicit Authority","description":"No Baa respects the scope of his post''s keys and records and does not invent authority.","behavior":"He enforces dispatch-sheet and signature checks while limiting handover to his post''s keys and records.","stress":"Even if a duty gap threatens passage, he may rely on verification requirements and his explicitly defined post scope.","relationship":"He may keep authority boundaries clear with the senior duty holder by specifying the records and keys being transferred.","effects":[]}],"narrative":"He halted a train departing without a dispatch sheet. Conditional enforcement is supported; messenger combat ability is unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-c7a5-c5f0-76e7","name":"Jangyeon No Clan","crest":"clan-crests/b178-c7a5-c5f0-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":20,"Force":-20,"Material":10,"Communal":40,"Principle":20,"Public":-15,"Eligibility":20,"Dispersed":30,"Transformative":0},"desire":{"Longing":45,"Monopoly":40,"Risk":5,"Display":5,"Sustained":5,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Affiliation":"Arc","Livelihood":"Timetable · Departure Check","Rank":"Teacher","Title":"Workshop Herald","Values":"Authority −5 | Openness 20 | Force −20 | Material 10 | Community 40 | Principle 20 | Publicity −15 | Qualification 20 | Decentralization 30 | Transformation 0","Desires":"Craving 45 | Exclusivity 40 | Risk 5 | Display 5 | Persistence 5 | Orientation: fluid | Bonding: non-exclusive"},"sections":{"Life":"Born in the 2126 cohort. Noh Ba-a grew up at the Sinnae transfer watch. Noh Ba-a took the Workshop Herald post after stopping a ticketless train''s departure.\n- Noh Ba-a''s Workshop Herald duties are connected to Seongsu 2-ga 3-dong.","Offices":"Noh Ba-a hands over only the keys and records attached to his own post. He does not invent authority he lacks.","Anecdote":"In 2125, Noh Ba-a stopped a train with no dispatch slip and prevented an unsigned departure. Because of this, the signature of the Workshop Herald post was entered in the ledger.","Relationships":"Noh Ba-a is bound by handover to the senior watch officer of the same living sphere.","Ambition":"Noh Ba-a wants to keep the Arc''s ledger connected without a break through the Workshop Herald watch.","Fear":"Noh Ba-a fears a situation in which, if the Workshop Herald watch stands empty, the Arc''s passage becomes a hostage to the powerful states.","Intervention":"Noh Ba-a can bring in a witness for a watch handover or expose an empty key."},"biography":"Noh Ba-a chooses first not to break the watch. Noh Ba-a trusts a single line in the ledger over loud talk.\n\n- Affiliation: Arc\n- Occupation: Dispatch slip and departure verification\n- Rank: Instructor\n- Title: Workshop Herald\n**Life.** Born in the 2126 cohort. Noh Ba-a grew up at the Sinnae transfer watch. Noh Ba-a took the Workshop Herald post after stopping a ticketless train''s departure.\n- Noh Ba-a''s Workshop Herald duties are connected to Seongsu 2-ga 3-dong.\n\n**Office.** Noh Ba-a hands over only the keys and records attached to his own post. He does not invent authority he lacks.\n\n**Anecdote.** In 2125, Noh Ba-a stopped a train with no dispatch slip and prevented an unsigned departure. Because of this, the signature of the Workshop Herald post was entered in the ledger.\n\n**Relations.** Noh Ba-a is bound by handover to the senior watch officer of the same living sphere.\n\n**Ambition.** Noh Ba-a wants to keep the Arc''s ledger connected without a break through the Workshop Herald watch.\n\n**Fear.** Noh Ba-a fears a situation in which, if the Workshop Herald watch stands empty, the Arc''s passage becomes a hostage to the powerful states.\n\n**Intervention.** Noh Ba-a can bring in a witness for a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −5 | Openness 20 | Force −20 | Material 10 | Community 40 | Principle 20 | Publicity −15 | Qualification 20 | Decentralization 30 | Transformation 0\n- Desires: Craving 45 | Exclusivity 40 | Risk 5 | Display 5 | Persistence 5 | Orientation: fluid | Bonding: non-exclusive\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0731","name":"노바아","title":"공방 전령","position":"공방 전령","characterId":"K731","rank":"교사","commonTier":"T5","occupation":"배차표·출발 확인","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-노바아","detailRoute":"/people/person-0731","birthDate":"2097-07-25","birthday":"07-25","age":29,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure","name":"배차표·출발 확인","rating":50},{"id":"handover","name":"기록·열쇠 인수인계","rating":40}],"traits":[{"id":"stop-unmarked-trains","name":"무표 열차 세우기","description":"노바아는 배차표가 없는 열차의 출발을 허용하지 않는 확인 중심 성향을 보인다.","behavior":"배차표 없는 열차를 세워 서명 없는 출발을 막았다.","stress":"당직 공백이 통행을 강국의 볼모로 만들까 우려되면 출발 확인 자료의 누락에 더 주의할 수 있다.","relationship":"선배 당직에게는 배차표와 서명이 없어 출발을 세운 사실을 분명히 넘기려 할 수 있다.","effects":[]},{"id":"respect-explicit-authority","name":"명시 권한 준수","description":"노바아는 자기 직위에 명시된 열쇠와 기록의 범위를 지키고 없는 권한을 만들지 않는다.","behavior":"배차표와 서명의 확인 조건을 집행하면서 인계는 자기 직위의 열쇠와 기록에 한정한다.","stress":"당직 공백으로 통행이 위태로워져도 확인 조건과 명시된 직위 범위에 기대려 할 수 있다.","relationship":"선배 당직과는 넘길 기록과 열쇠를 명확히 하며 권한의 경계를 유지하려 할 수 있다.","effects":[]}],"narrative":"배차표가 없는 열차의 출발을 세웠다. 확인 조건 집행만 근거이며 전령의 전투 기량은 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-c7a5-c5f0-76e7","name":"장연 노씨","crest":"clan-crests/b178-c7a5-c5f0-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":20,"무력":-20,"물질":10,"공동":40,"원칙":20,"공개":-15,"자격":20,"분산":30,"변혁":0},"desire":{"갈망":45,"독점":40,"위험":5,"과시":5,"지속":5,"지향":"유동","결합":"비독점"},"fields":{"소속":"Arc","생업":"배차표·출발 확인","품계":"교사","직함":"공방 전령","가치관":"권위 −5 | 개방 20 | 무력 −20 | 물질 10 | 공동 40 | 원칙 20 | 공개 −15 | 자격 20 | 분산 30 | 변혁 0","욕망":"갈망 45 | 독점 40 | 위험 5 | 과시 5 | 지속 5 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2126년 세대. 노바아는 신내 환승 당직에서 자랐다. 노바아는 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 노바아의 공방 전령 업무는 성수2가3동과 연결된다.","관직":"노바아는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 노바아는 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.","관계":"노바아는 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"노바아는 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"노바아는 공방 전령 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"노바아는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"노바아는 당직을 끊지 않는 쪽을 먼저 고른다. 노바아는 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 배차표·출발 확인\n- 품계: 교사\n- 직함: 공방 전령\n**생애.** 2126년 세대. 노바아는 신내 환승 당직에서 자랐다. 노바아는 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 노바아의 공방 전령 업무는 성수2가3동과 연결된다.\n\n**관직.** 노바아는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 노바아는 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 노바아는 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 노바아는 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 노바아는 공방 전령 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 노바아는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 20 | 무력 −20 | 물질 10 | 공동 40 | 원칙 20 | 공개 −15 | 자격 20 | 분산 30 | 변혁 0\n- 욕망: 갈망 45 | 독점 40 | 위험 5 | 과시 5 | 지속 5 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[],"incoming":[]}}');
