INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0738', 'ad6c-b2a5-c131', '{"id":"person-0738","name":"Gu Gu-hui","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0738","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0738","name":"구구희","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"사원","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0738","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0739', 'bbfc-c5ec-d765-9594', '{"id":"person-0739","name":"Min Gang-hyeon","title":"Medical Escort Recorder","position":"Medical Escort Recorder","characterId":"K739","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-12#character-min-gang-hyeon","detailRoute":"/people/person-0739","birthDate":"2067-02-08","birthday":"02-08","age":59,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k739-siding-stay-reconciliation","name":"Siding stay reconciliation","rating":50}],"traits":[{"id":"k739-priority","name":"Evidence for stay times","description":"Min Ganghyeon matched arrival and departure times with siding duty records and marked stays within licensed segments, without monopoly over license interpretation.","behavior":"Office. Rank: convoy hand. Title: medical convoy registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the medical convoy registrar duty post would stand empty and the City''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k739-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: convoy hand. Title: medical convoy registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the medical convoy registrar duty post would stand empty and the City''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Min Ganghyeon matched arrival and departure times with siding duty records and marked stays within licensed segments, without monopoly over license interpretation.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":50,"Force":-50,"Material":0,"Communal":15,"Principle":25,"Public":25,"Eligibility":10,"Dispersed":30,"Transformative":0},"desire":{"Longing":30,"Monopoly":-5,"Risk":20,"Display":-45,"Sustained":-10,"Orientation":"None","Union":"None"},"fields":{"Livelihood":"Medical Escort Log and Duty Key Handover","Affiliation":"The Government","Rank":"Escort","Title":"Medical Escort Recorder","Values":"Authority −20 | Openness 50 | Force −50 | Material 0 | Community 15 | Principle 25 | Publicity 25 | Qualification 10 | Decentralization 30 | Transformation 0","Desires":"Craving 30 | Exclusivity −5 | Risk 20 | Display −45 | Persistence −10 | Orientation: none | Bonding: none"},"sections":{"Life":"Born on 2067-02-08. Grew up at the Seoul Station Registry Office. At the 2126 opening he holds the Medical Escort Records Officer watch, and the post handover record retains a note that the post was opened by the deletion of a single line from a double ledger.\n- The dispatch, shift, maintenance, passage-screening, stretcher-handover and watch-key record desk at Sinnae 1-dong is proposed as the duty reference point for Min Gang-hyeon''s medical escort records and watch-key handover work. It is a proposal to cross-check handover records in the permanent winter; operating trains, new facilities, armament, passage tolls, market monopolies, residence, exact facility boundaries, titles, fiefs and possession rights are not confirmed.","Offices":"Rank: Escort. Title: Medical Escort Records Officer. He hands over the seal on ticketless departures together with the keys and records of his own watch, making the scope of the handover clear.","Anecdote":"A message arrives from the siding watch at Yongsan Track Gate asking how long the medical escort train stayed on the siding. Min Gang-hyeon pulls the arrival and departure times from the medical escort records, matches them against the siding watch''s records, and marks the times spent within the Jang clan''s licensed line section. The seal on the ticketless departure that he left then became the handover standard for the next watch.","Relationships":"He hands the seal on the ticketless departure to the senior watch officer of the same living sphere, and checks it against the next shift''s receipt time in the same duty district.","Ambition":"He intends to leave the seal on the ticketless departure as a public handover line that the next shift can check again.","Fear":"She fears that the receipt time of the Seal on Departure Without a Dispatch Sheet will be left blank, so that responsibility is shifted onto the patient and passenger lists.","Intervention":"She can bring in a witness for the handover of the Seal on Departure Without a Dispatch Sheet, or make the missing signature field public before the next shift."},"biography":"Min Ganghyeon, born 2067-02-08, first checks the sequence of the Seal on Departure Without a Dispatch Sheet. He trusts handover times and signature fields more than loud voices.\n\n- Livelihood: Medical escort records and duty key handover\n- Affiliation: The Government\n- Rank: Escort\n- Title: Medical Escort Recorder\n**Life.** Born on 2067-02-08. Grew up at the Seoul Station Registry Office. At the 2126 opening he holds the Medical Escort Recorder''s duty post, and his post-succession record includes the entry \"Opened by Deleting One Double-Ledger Line.\"\n- The Sinnae 1-dong dispatch, shift, maintenance, transit inspection, stretcher handover, and duty key record desk is proposed as Min Ganghyeon''s reference point for medical escort records and duty key handover work. This is a proposal to cross-check handover records of the Permanent Winter, and it does not fix running trains, new facilities, weapons, transit tolls, market monopolies, residence, exact facility boundaries, titles of nobility, fiefs, or possession rights.\n\n**Office.** Rank: Escort. Title: Medical Escort Recorder. He hands over the Seal on Departure Without a Dispatch Sheet together with the keys and records of his own duty post, making the scope of the handover clear.\n\n**Anecdote.** At the Yongsan Trackgate siding duty, a message arrives asking how long the medical escort train stayed on the siding. Min Ganghyeon pulls the arrival and departure times from the medical escort records, matches them against the siding duty''s records, and marks the time spent within the Jang clan''s licensed route section. The Seal on Departure Without a Dispatch Sheet that he left then became the handover standard for the next duty officer.\n\n**Relations.** He hands the Seal on Departure Without a Dispatch Sheet to the senior duty officer of the same living sphere, and checks it against the receipt time of the next shift in the same duty sphere.\n\n**Ambition.** He hopes to leave the Seal on Departure Without a Dispatch Sheet as a public handover line that the next shift can check again.\n\n**Fear.** He fears that the receipt time of the Seal on Departure Without a Dispatch Sheet will be left blank, so that responsibility is shifted onto the patient and passenger lists.\n\n**Intervention.** He can bring in a witness for the handover of the Seal on Departure Without a Dispatch Sheet, or make the missing signature field public before the next shift.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −20 | Openness 50 | Force −50 | Material 0 | Communal 15 | Principle 25 | Publicity 25 | Credentials 10 | Dispersal 30 | Transformation 0\n- Desires: Longing 30 | Monopoly −5 | Risk 20 | Display −45 | Continuity −10 | Orientation: None | Bonding: None\n:::","relations":{"outgoing":[{"from":"Min Gang-hyeon","type":"Contract","to":"So Dugam","basis":"Min Ganghyeon tells Sodugam the times the escort-duty cars stayed on the stabling track. Sodugam checks the dispatch sheet and maintenance log to distinguish time held for maintenance from the actual release time."}],"incoming":[]}}', '{"id":"person-0739","name":"민강현","title":"의무호송 기록관","position":"의무호송 기록관","characterId":"K739","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-12#인물-민강현","detailRoute":"/people/person-0739","birthDate":"2067-02-08","birthday":"02-08","age":59,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k739-siding-stay-reconciliation","name":"유치선 체류 대조","rating":50}],"traits":[{"id":"k739-priority","name":"체류 시각의 근거","description":"민강현은 도착·출발 시각을 유치선 당직과 맞추고 면허 구간의 체류를 표시했다. 면허 해석의 독점 권한은 없다.","behavior":"자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"의무호송 기록관 당직이 비면 신내운수의 통행이 노선 면허의 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k739-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 호송원. 직함은 의무호송 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 의무호송 기록관 당직이 비면 신내운수의 통행이 노선 면허의 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"민강현은 도착·출발 시각을 유치선 당직과 맞추고 면허 구간의 체류를 표시했다. 면허 해석의 독점 권한은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bbfc-c5ec-d765-9594","name":"여흥 민씨","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":50,"무력":-50,"물질":0,"공동":15,"원칙":25,"공개":25,"자격":10,"분산":30,"변혁":0},"desire":{"갈망":30,"독점":-5,"위험":20,"과시":-45,"지속":-10,"지향":"무성향","결합":"없음"},"fields":{"생업":"의무호송 기록·당직 열쇠 인계","소속":"정부","품계":"호송원","직함":"의무호송 기록관","가치관":"권위 −20 | 개방 50 | 무력 −50 | 물질 0 | 공동 15 | 원칙 25 | 공개 25 | 자격 10 | 분산 30 | 변혁 0","욕망":"갈망 30 | 독점 −5 | 위험 20 | 과시 −45 | 지속 −10 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2067-02-08에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 민강현의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 영구 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·작위·영지·점유권은 확정하지 않는다.","관직":"품계 호송원. 직함은 의무호송 기록관. 배차표 없는 출발의 봉인과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.","일화":"용산선로문의 유치선 당직에서 의무호송 열차가 유치선에 머문 시각을 묻는 전갈이 온다. 민강현은 의무호송 기록의 도착·출발 시각을 뽑아 유치선 당직의 기록과 맞추고, 장씨 가문의 노선 면허 구간 안에서 머문 시각에 표시를 해 둔다. 그때 남긴 배차표 없는 출발의 봉인이 다음 당직의 인수 기준이 되었다.","관계":"같은 생활권 선배 당직에게 배차표 없는 출발의 봉인을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.","야망":"배차표 없는 출발의 봉인을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.","공포":"배차표 없는 출발의 봉인의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.","개입":"배차표 없는 출발의 봉인의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다."},"biography":"2067-02-08생인 민강현은 배차표 없는 출발의 봉인의 순서를 먼저 확인한다. 큰소리보다 인수 시각과 서명 칸을 믿는다.\n\n- 생업: 의무호송 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 호송원\n- 직함: 의무호송 기록관\n**생애.** 2067-02-08에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 민강현의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 영구 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·작위·영지·점유권은 확정하지 않는다.\n\n**관직.** 품계 호송원. 직함은 의무호송 기록관. 배차표 없는 출발의 봉인과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.\n\n**일화.** 용산선로문의 유치선 당직에서 의무호송 열차가 유치선에 머문 시각을 묻는 전갈이 온다. 민강현은 의무호송 기록의 도착·출발 시각을 뽑아 유치선 당직의 기록과 맞추고, 장씨 가문의 노선 면허 구간 안에서 머문 시각에 표시를 해 둔다. 그때 남긴 배차표 없는 출발의 봉인이 다음 당직의 인수 기준이 되었다.\n\n**관계.** 같은 생활권 선배 당직에게 배차표 없는 출발의 봉인을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.\n\n**야망.** 배차표 없는 출발의 봉인을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.\n\n**공포.** 배차표 없는 출발의 봉인의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.\n\n**개입.** 배차표 없는 출발의 봉인의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 50 | 무력 −50 | 물질 0 | 공동 15 | 원칙 25 | 공개 25 | 자격 10 | 분산 30 | 변혁 0\n- 욕망: 갈망 30 | 독점 −5 | 위험 20 | 과시 −45 | 지속 −10 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"민강현","type":"계약","to":"소두감","basis":"민강현은 의무호송의 유치선 체류 시각을 소두감에게 전한다. 소두감은 배차표와 정비 일지를 확인해 정비로 머문 시간과 실제 출고 시간을 구분한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0740', 'c9c4-d48d-ae30', '{"id":"person-0740","name":"Jin Sup-hyeok","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K740","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-jin-suphyeok","detailRoute":"/people/person-0740","birthDate":"2077-06-06","birthday":"06-06","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"Payment ledger reconciliation","rating":50}],"traits":[{"id":"stated-priority","name":"Signs even a deletion","description":"One duplicate payment was checked, deleted, and signed. A single ledger correction supports the allocation; the sanitation apprentice title adds no skill.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"One duplicate payment was checked, deleted, and signed. A single ledger correction supports the allocation; the sanitation apprentice title adds no skill.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c9c4-d48d-ae30","name":"Pungi Jin Clan","crest":"clan-crests/c9c4-d48d-ae30.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":35,"Force":-80,"Material":-20,"Communal":25,"Principle":65,"Public":20,"Eligibility":30,"Dispersed":15,"Transformative":0},"desire":{"Longing":5,"Monopoly":15,"Risk":10,"Display":-35,"Sustained":15,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −15 | Openness 35 | Force −80 | Material −20 | Communal 25 | Principle 65 | Publicity 20 | Credentials 30 | Dispersal 15 | Transformation 0","Desires":"Longing 5 | Monopoly 15 | Risk 10 | Display −35 | Continuity 15 | Orientation: Bisexual | Bonding: Contract cohabitation"},"sections":{"Life":"Born on 2077-06-06. As of the 2126 opening, he holds the post of Quarantine Records Officer and continues the existing duty and records. The succession record for that post includes the entry \"Opened by Deleting One Double-Ledger Line.\"\n- The quarantine records and duty key handover desk in Jegi-dong is made Jin Suphyeok''s work reference point. This placement does not fix residence, exact facility boundaries, titles of nobility, fiefs, or possession rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.","Relationships":"Jin Suphyeok hands Su Chorong the duplicate-payment correction and the takeover signature for the quarantine records. Su Chorong checks the on-site entry stamps and quarantine status to find places where the same entry was recorded twice.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the duty chain. He trusts a single ledger line more than loud voices.\n\n- Livelihood: Quarantine records and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident Physician\n- Title: Quarantine Records Officer\n**Life.** Born on 2077-06-06. As of the 2126 opening, he holds the post of Quarantine Records Officer and continues the existing duty and records. The succession record for that post includes the entry \"Opened by Deleting One Double-Ledger Line.\"\n- The quarantine records and duty key handover desk in Jegi-dong is made Jin Suphyeok''s work reference point. This placement does not fix residence, exact facility boundaries, titles of nobility, fiefs, or possession rights.\n\n**Office.** Rank: Resident Physician. Title: Quarantine Resident. He hands over only the keys and records of his own post, and enters in the ledger the receipt time of the keys and records he handed over.\n\n**Anecdote.** In 2125 he cross-checked a double-payment ledger, erased one line, and left his signature. That day''s record remained as a handover basis for the next duty officer to verify.\n\n**Relations.** Jin Suphyeok passes the correction of duplicate payments in the quarantine records and the handover signature to Su Chorong. Su Chorong checks the site entry stamps and quarantine status to find places where the same entry was recorded twice.\n\n**Ambition.** From the post of Quarantine Resident, he wants to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** He fears that if the Quarantine Resident''s duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron powers.\n\n**Intervention.** He can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −15 | Openness 35 | Force −80 | Material −20 | Communal 25 | Principle 65 | Publicity 20 | Credentials 30 | Dispersal 15 | Transformation 0\n- Desires: Longing 5 | Monopoly 15 | Risk 10 | Display −35 | Continuity 15 | Orientation: Bisexual | Bonding: Contract cohabitation\n:::","relations":{"outgoing":[{"from":"Jin Sup-hyeok","type":"Contract","to":"Su Choreong","basis":"Jin Suphyeok hands Su Chorong the duplicate-payment correction and the takeover signature for the quarantine records. Su Chorong checks the on-site entry stamps and quarantine status to find places where the same entry was recorded twice."}],"incoming":[]}}', '{"id":"person-0740","name":"진숲혁","title":"방역 기록관","position":"방역 기록관","characterId":"K740","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-진숲혁","detailRoute":"/people/person-0740","birthDate":"2077-06-06","birthday":"06-06","age":49,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"지급 장부 대조","rating":50}],"traits":[{"id":"stated-priority","name":"삭제도 서명으로 남긴다","description":"이중 지급 한 줄을 대조해 삭제하고 서명을 남겼다. 단일 장부 정정의 근거이며 방역 수련의 직함은 숙련을 추가하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"이중 지급 한 줄을 대조해 삭제하고 서명을 남겼다. 단일 장부 정정의 근거이며 방역 수련의 직함은 숙련을 추가하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c9c4-d48d-ae30","name":"풍기 진씨","crest":"clan-crests/c9c4-d48d-ae30.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":35,"무력":-80,"물질":-20,"공동":25,"원칙":65,"공개":20,"자격":30,"분산":15,"변혁":0},"desire":{"갈망":5,"독점":15,"위험":10,"과시":-35,"지속":15,"지향":"양성","결합":"계약동거"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −15 | 개방 35 | 무력 −80 | 물질 −20 | 공동 25 | 원칙 65 | 공개 20 | 자격 30 | 분산 15 | 변혁 0","욕망":"갈망 5 | 독점 15 | 위험 10 | 과시 −35 | 지속 15 | 지향 양성 | 결합 계약동거"},"sections":{"생애":"2077-06-06에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 진숲혁의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"진숲혁은 방역 기록의 중복 지급 정정과 인수 서명을 수초롱에게 넘긴다. 수초롱은 현장 출입 도장과 격리 상태를 확인해 같은 출입이 두 번 기록된 곳을 찾는다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2077-06-06에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 진숲혁의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 진숲혁은 방역 기록의 중복 지급 정정과 인수 서명을 수초롱에게 넘긴다. 수초롱은 현장 출입 도장과 격리 상태를 확인해 같은 출입이 두 번 기록된 곳을 찾는다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 35 | 무력 −80 | 물질 −20 | 공동 25 | 원칙 65 | 공개 20 | 자격 30 | 분산 15 | 변혁 0\n- 욕망: 갈망 5 | 독점 15 | 위험 10 | 과시 −35 | 지속 15 | 지향 양성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"진숲혁","type":"계약","to":"수초롱","basis":"진숲혁은 방역 기록의 중복 지급 정정과 인수 서명을 수초롱에게 넘긴다. 수초롱은 현장 출입 도장과 격리 상태를 확인해 같은 출입이 두 번 기록된 곳을 찾는다."}],"incoming":[]}}');
