INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0746', 'c870-d3c9-c591-8d99', '{"id":"person-0746","name":"Jo Dong-jun","title":"Certification Courier","position":"Certification Courier","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Female","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0746","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0746","name":"조동준","title":"인증 전령","position":"인증 전령","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"여성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0746","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0747', 'c724-d30c-d3c9', '{"id":"person-0747","name":"Yun Buk-yul","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K747","rank":"","commonTier":"T3","occupation":"Parts Shipment Inspection","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#person-yun-bugyul","detailRoute":"/people/person-0747","birthDate":"2073-04-29","birthday":"04-29","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"parts","name":"Defective-parts dispatch inspection","rating":50},{"id":"wheel","name":"Wheel-defect inspection","rating":40}],"traits":[{"id":"no-defective-shipments","name":"No Defective Shipments","description":"Yun Bugyul shows a quality-checking disposition by refusing to pass on defective parts even just before shipment.","behavior":"He returned a box of defective parts immediately before shipment.","stress":"Even when concerned about duty gaps and dependent passage, he may be cautious about shipping confirmed defects.","relationship":"He may clearly hand over the returned parts box and the defect judgment to the senior duty holder.","effects":[]},{"id":"maintain-record-continuity","name":"Maintain Record Continuity","description":"Yun Bugyul values carrying his post''s records forward to avoid breaks in the ledger and duty.","behavior":"He returns defective parts and passes on his post''s keys and records to support ledger continuity.","stress":"If vacant duty could make passage hostage to a powerful state, he may take greater care to connect the return action with handover records.","relationship":"He may value handover that gives the senior duty holder a recorded reason why the parts were not shipped.","effects":[]}],"narrative":"She returned a defective-parts box. Release checks and wheel reporting are supported, not authority over an entire logistics network.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43770-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K747","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43770-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":5,"Force":-25,"Material":45,"Communal":20,"Principle":0,"Public":-25,"Eligibility":30,"Dispersed":25,"Transformative":-10},"desire":{"Longing":10,"Monopoly":0,"Risk":40,"Display":20,"Sustained":-5,"Orientation":"None","Union":"Polyamorous"},"fields":{"Affiliation":"Arc","Livelihood":"Parts Shipment Inspection","Rank":"Teacher","Title":"Parts Logistics Merchant","Values":"Authority −5 | Openness 5 | Force −25 | Material 45 | Communal 20 | Principle 0 | Publicity −25 | Credentials 30 | Dispersal 25 | Transformation −10","Desires":"Longing 10 | Monopoly 0 | Risk 40 | Display 20 | Continuity −5 | Orientation: None | Bonding: Polyamorous"},"sections":{"Life":"Generation of 2126. Yun Bugyul grew up at the Sinjeong Depot. She took the post of Parts Logistics Merchant through a defect report made just before a derailment.\n- Yun Bugyul''s Parts Logistics Merchant work is connected to Seongsu 2-ga 1-dong.","Offices":"Yun Bugyul hands over only the keys and records attached to her own post. She does not invent authority that she does not have.","Anecdote":"In 2125, Yun Bugyul sent a defective parts crate back just before shipment. Because of this, the signature for the post of Parts Logistics Merchant was entered in the ledger.","Relationships":"Yun Bugyul is bound by handover to the senior duty officer of the same living sphere.","Ambition":"Yun Bugyul wants to keep the Arc''s ledger continuous and unbroken through the Parts Logistics Merchant''s duty.","Fear":"Yun Bugyul fears that if the Parts Logistics Merchant''s duty falls vacant, the Arc''s passage will become a hostage of a great power.","Intervention":"Yun Bugyul can bring in a witness for a duty handover or expose an empty key."},"biography":"Yun Bugyul chooses first not to break the duty chain. Yun Bugyul trusts a single ledger line more than loud voices.\n\n- Affiliation: Arc\n- Livelihood: Parts shipment inspection\n- Rank: Instructor\n- Title: Parts Logistics Merchant\n**Life.** Generation of 2126. Yun Bugyul grew up at the Sinjeong Depot. She took the post of Parts Logistics Merchant through a defect report made just before a derailment.\n- Yun Bugyul''s Parts Logistics Merchant work is connected to Seongsu 2-ga 1-dong.\n\n**Office.** Yun Bugyul hands over only the keys and records attached to her own post. She does not invent authority that she does not have.\n\n**Anecdote.** In 2125, Yun Bugyul sent a defective parts crate back just before shipment. Because of this, the signature for the post of Parts Logistics Merchant was entered in the ledger.\n\n**Relations.** Yun Bugyul is bound by handover to the senior duty officer of the same living sphere.\n\n**Ambition.** Yun Bugyul wants to keep the Arc''s ledger continuous and unbroken through the Parts Logistics Merchant''s duty.\n\n**Fear.** Yun Bugyul fears that if the Parts Logistics Merchant''s duty falls vacant, the Arc''s passage will become a hostage of a great power.\n\n**Intervention.** Yun Bugyul can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −5 | Openness 5 | Force −25 | Material 45 | Communal 20 | Principle 0 | Publicity −25 | Credentials 30 | Dispersal 25 | Transformation −10\n- Desires: Longing 10 | Monopoly 0 | Risk 40 | Display 20 | Continuity −5 | Orientation: None | Bonding: Polyamorous\n:::","relations":{"outgoing":[{"from":"Yun Buk-yul","type":"Contract","to":"Bak Serin","basis":"Yun Bugyul sends the defective pump parts screened out in the dispatch inspection back to Bak Serin. Bak Serin checks the warehouse parts and the elder''s seal to find the point where the defective items got mixed into the normal dispatch list."}],"incoming":[]}}', '{"id":"person-0747","name":"윤북율","title":"부품 물류상","position":"부품 물류상","characterId":"K747","rank":"","commonTier":"T3","occupation":"부품 출고 검사","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-윤북율","detailRoute":"/people/person-0747","birthDate":"2073-04-29","birthday":"04-29","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"parts","name":"불량 부품 출고 검사","rating":50},{"id":"wheel","name":"차륜 결함 점검","rating":40}],"traits":[{"id":"no-defective-shipments","name":"불량 출고 거부","description":"윤북율은 출고 직전에도 불량 부품을 넘기지 않는 품질 확인 성향을 보인다.","behavior":"불량 부품 상자를 출고 직전에 되돌려 보냈다.","stress":"당직 공백과 통행 종속을 우려하더라도 확인된 불량을 그대로 출고하는 데 신중할 수 있다.","relationship":"선배 당직에게는 반송한 부품 상자와 불량 판단을 분명히 인계하려 할 수 있다.","effects":[]},{"id":"maintain-record-continuity","name":"기록 잇기","description":"윤북율은 자기 직위의 기록을 이어 장부와 당직의 중단을 피하는 데 무게를 둔다.","behavior":"불량 부품을 반송하고 자기 직위의 열쇠와 기록을 넘겨 장부의 연속성을 지향한다.","stress":"당직이 비어 통행이 강국의 볼모가 될까 우려되면 반송 조치와 인계 기록이 끊기지 않도록 더 신경 쓸 수 있다.","relationship":"선배 당직과는 출고하지 않은 이유를 기록으로 이어 주는 인계를 중시할 수 있다.","effects":[]}],"narrative":"불량 부품 상자를 되돌려 보냈다. 출고 검사와 생애의 차륜 보고만 평가하며 물류망 전체 운영 권한은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43770-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K747","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43770-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c724-d30c-d3c9","name":"파평 윤씨","crest":"clan-crests/c724-d30c-d3c9.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":5,"무력":-25,"물질":45,"공동":20,"원칙":0,"공개":-25,"자격":30,"분산":25,"변혁":-10},"desire":{"갈망":10,"독점":0,"위험":40,"과시":20,"지속":-5,"지향":"무성향","결합":"다자"},"fields":{"소속":"Arc","생업":"부품 출고 검사","품계":"교사","직함":"부품 물류상","가치관":"권위 −5 | 개방 5 | 무력 −25 | 물질 45 | 공동 20 | 원칙 0 | 공개 −25 | 자격 30 | 분산 25 | 변혁 −10","욕망":"갈망 10 | 독점 0 | 위험 40 | 과시 20 | 지속 −5 | 지향 무성향 | 결합 다자"},"sections":{"생애":"2126년 세대. 윤북율은 신정 차량기지에서 자랐다. 윤북율은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 윤북율의 부품 물류상 업무는 성수2가1동과 연결된다.","관직":"윤북율은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 윤북율은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"윤북율은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"윤북율은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"윤북율은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"윤북율은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"윤북율은 당직을 끊지 않는 쪽을 먼저 고른다. 윤북율은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 부품 출고 검사\n- 품계: 교사\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 윤북율은 신정 차량기지에서 자랐다. 윤북율은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 윤북율의 부품 물류상 업무는 성수2가1동과 연결된다.\n\n**관직.** 윤북율은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 윤북율은 불량 부품 상자를 출고 직전에 되돌려 보냈다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 윤북율은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 윤북율은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 윤북율은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 윤북율은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 5 | 무력 −25 | 물질 45 | 공동 20 | 원칙 0 | 공개 −25 | 자격 30 | 분산 25 | 변혁 −10\n- 욕망: 갈망 10 | 독점 0 | 위험 40 | 과시 20 | 지속 −5 | 지향 무성향 | 결합 다자\n:::","relations":{"outgoing":[{"from":"윤북율","type":"계약","to":"박세린","basis":"윤북율은 출고 검사에서 가려낸 불량 펌프 부품을 박세린에게 돌려보낸다. 박세린은 창고 부품과 원로 날인을 확인해 불량품이 정상 출고 목록에 섞인 지점을 찾는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0748', 'c7a5-baa9-cc9c-5f35', '{"id":"person-0748","name":"Jang Byeol-lin","title":"Water Supply Escort Patrol","position":"Eastern Patrol","rank":"Sergeant","commonTier":"T5","occupation":"Access Security · Roster Recheck","gender":"Male","stage":"S4","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0748","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0748","name":"장별린","title":"상수 호위 순찰대","position":"동부 순찰대","rank":"병장","commonTier":"T5","occupation":"출입 경비·명부 재점검","gender":"남성","stage":"S4","state":"S05","stateName":"동방사","detailRoute":"/people/person-0748","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0749', 'c784-c608-cc9c-6797', '{"id":"person-0749","name":"Im Bit-na","title":"Ratification Registrar","position":"Ratification Registrar","characterId":"K749","rank":"Unregistered","commonTier":"T5","occupation":"Ratification Ledger Handover · Continuous Record","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#person-im-bitna","detailRoute":"/people/person-0749","birthDate":"2084-02-07","birthday":"02-07","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k749-approval-handover","name":"Approval handover","rating":60}],"traits":[{"id":"k749-choice","name":"Records competing costs","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Anecdote. While Han Jaemok''s western plan waits for Yun Seorin''s seal, the ratification-registrar shift changes. Im Bitna copies the plan''s receipt time and hold status into the continuous record, and writes into two columns of the handover memo the debt that piles up while it stays stopped and Yangcheon''s veto that vanishes the moment it is stamped.","stress":"Fear. That the ratification registrar duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k749-boundary","name":"Maintains work boundaries","description":"Office. Rank: registrar. Title: ratification registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Office. Rank: registrar. Title: ratification registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the ratification registrar duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. The actual response is not yet recorded.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. While Han Jaemok''s western plan waits for Yun Seorin''s seal, the ratification-registrar shift changes. Im Bitna copies the plan''s receipt time and hold status into the continuous record, and writes into two columns of the handover memo the debt that piles up while it stays stopped and Yangcheon''s veto that vanishes the moment it is stamped. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-c608-cc9c-6797","name":"Yecheon Im Clan","crest":"clan-crests/c784-c608-cc9c-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":20,"Openness":-15,"Force":-35,"Material":-30,"Communal":20,"Principle":60,"Public":-15,"Eligibility":0,"Dispersed":-20,"Transformative":-30},"desire":{"Longing":5,"Monopoly":20,"Risk":40,"Display":-10,"Sustained":15,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Ratification Ledger Handover · Continuous Record","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Ratification Registrar","Values":"Authority 20 | Openness −15 | Force −35 | Material −30 | Communal 20 | Principle 60 | Publicity −15 | Qualification 0 | Dispersion −20 | Transformation −30","Desires":"Craving 5 | Monopoly 20 | Risk 40 | Display −10 | Persistence 15 | Orientation Fluid | Union Contract Cohabitation"},"sections":{"Life":"Grew up at the Seoul Station Registry Office. The Confirmation Recorder post opened through the deletion of a single line in a double ledger.\n- Im Bitna''s work on confirmation-ledger handover and continuous records is tied to Hoehyeon-dong.","Civil Servant Position and Grade":"The grade appropriate to a headquarters or field-office post in the Seoul Metropolitan Government, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Assistant Local Administrative Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Assistant Local Administrative Clerk (Grade 9). Duties: Confirmation Records Officer.","Anecdote":"While Han Jaemok''s Western Proposal waits for Yun Seorin''s seal, the Confirmation Recorder''s duty shift changes. Im Bitna copies the Western Proposal''s receipt time and hold status into the continuous record. She then divides two items between the two columns of the handover memo: the debt that piles up while the proposal is stalled, and Yangcheon''s veto, which vanishes the moment the seal is stamped.","Relationships":"Through the handover of the confirmation-ledger handover and continuous-record work, she is connected to a senior duty officer from the same living area.","Ambition":"From the post of Confirmation Recorder, she carries on the confirmation-ledger handover and continuous records so that the ledgers of the Seoul Metropolitan Government local civil service organization are not broken between duty shifts.","Fear":"That the Confirmation Recorder''s duty shift falls vacant, severing the seals and rosters for downtown passage tied to the confirmation-ledger handover and continuous-record work, and halting even the confirmation of the forces composing the Seoul Metropolitan Government local civil service organization that rely on those records.","Intervention":"She can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post."},"biography":"She chooses to leave out neither the receipt time nor the hold status. The debt and Yangcheon''s veto are left in separate columns of the handover.\n\n- Occupation: Confirmation-ledger handover and continuous records\n- Affiliation: Seoul Metropolitan Government local civil service organization\n- Position/Grade: Whichever grade fits a Seoul Metropolitan Government headquarters or field-office post among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Duties: Confirmation Recorder\n**Life.** Grew up at the Seoul Station Registry Office. The Confirmation Recorder post opened through the deletion of a single line in a double ledger.\n- Im Bitna''s work on confirmation-ledger handover and continuous records is tied to Hoehyeon-dong.\n\n**Civil Service Position and Grade.** Whichever grade fits a Seoul Metropolitan Government headquarters or field-office post among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Confirmation Recorder.\n\n**Anecdote.** While Han Jaemok''s Western Proposal waits for Yun Seorin''s seal, the Confirmation Recorder''s duty shift changes. Im Bitna copies the Western Proposal''s receipt time and hold status into the continuous record. She then divides two items between the two columns of the handover memo: the debt that piles up while the proposal is stalled, and Yangcheon''s veto, which vanishes the moment the seal is stamped.\n\n**Relationships.** Through the handover of the confirmation-ledger handover and continuous-record work, she is connected to a senior duty officer from the same living area.\n\n**Ambition.** From the post of Confirmation Recorder, she carries on the confirmation-ledger handover and continuous records so that the ledgers of the Seoul Metropolitan Government local civil service organization are not broken between duty shifts.\n\n**Fear.** That the Confirmation Recorder''s duty shift falls vacant, severing the seals and rosters for downtown passage tied to the confirmation-ledger handover and continuous-record work, and halting even the confirmation of the forces composing the Seoul Metropolitan Government local civil service organization that rely on those records.\n\n**Intervention.** She can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 20 | Openness −15 | Force −35 | Material −30 | Communal 20 | Principle 60 | Publicity −15 | Qualification 0 | Dispersion −20 | Transformation −30\n- Desires: Craving 5 | Monopoly 20 | Risk 40 | Display −10 | Persistence 15 | Orientation Fluid | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Im Bit-na","type":"Contract","to":"Yang Haeon","basis":"Im Bitna hands over the continuous record of approval receipt times and hold status to Yang Haeon. Yang Haeon checks the reviewer''s seal and the archive custody confirmation, and delivers a message with no omitted hold on the next shift."}],"incoming":[]}}', '{"id":"person-0749","name":"임빛나","title":"인준 기록관","position":"인준 기록관","characterId":"K749","rank":"미등록","commonTier":"T5","occupation":"인준 장부 인수인계·연속 기록","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-임빛나","detailRoute":"/people/person-0749","birthDate":"2084-02-07","birthday":"02-07","age":42,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k749-approval-handover","name":"인준 인수인계","rating":60}],"traits":[{"id":"k749-choice","name":"상충 비용을 함께 기록","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"일화. 한재목의 서부안이 윤서린의 도장을 기다리는 사이 인준 기록관 당직이 바뀐다. 임빛나는 서부안의 접수 시각과 보류 상태를 연속 기록에 옮기고, 멈춘 동안 쌓이는 빚과 찍는 순간 사라지는 양천의 거부권을 인수인계 메모의 두 칸에 나누어 적는다.","stress":"공포. 인준 기록관 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k749-boundary","name":"업무 경계를 지킴","description":"관직. 품계 주사. 직함은 인준 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"관직. 품계 주사. 직함은 인준 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 인준 기록관 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 한재목의 서부안이 윤서린의 도장을 기다리는 사이 인준 기록관 당직이 바뀐다. 임빛나는 서부안의 접수 시각과 보류 상태를 연속 기록에 옮기고, 멈춘 동안 쌓이는 빚과 찍는 순간 사라지는 양천의 거부권을 인수인계 메모의 두 칸에 나누어 적는다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-c608-cc9c-6797","name":"예천 임씨","crest":"clan-crests/c784-c608-cc9c-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":20,"개방":-15,"무력":-35,"물질":-30,"공동":20,"원칙":60,"공개":-15,"자격":0,"분산":-20,"변혁":-30},"desire":{"갈망":5,"독점":20,"위험":40,"과시":-10,"지속":15,"지향":"유동","결합":"계약동거"},"fields":{"생업":"인준 장부 인수인계·연속 기록","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"인준 기록관","가치관":"권위 20 | 개방 −15 | 무력 −35 | 물질 −30 | 공동 20 | 원칙 60 | 공개 −15 | 자격 0 | 분산 −20 | 변혁 −30","욕망":"갈망 5 | 독점 20 | 위험 40 | 과시 −10 | 지속 15 | 지향 유동 | 결합 계약동거"},"sections":{"생애":"서울역 등기소에서 자랐다. 인준 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 임빛나의 인준 장부 인수인계·연속 기록 업무는 회현동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 인준 기록관.","일화":"한재목의 서부안이 윤서린의 도장을 기다리는 사이 인준 기록관 당직이 바뀐다. 임빛나는 서부안의 접수 시각과 보류 상태를 연속 기록에 옮기고, 멈춘 동안 쌓이는 빚과 찍는 순간 사라지는 양천의 거부권을 인수인계 메모의 두 칸에 나누어 적는다.","관계":"인준 장부 인수인계·연속 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"인준 기록관 자리에서 인준 장부 인수인계·연속 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"인준 기록관 당직이 비어 인준 장부 인수인계·연속 기록 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.","개입":"인준 장부 인수인계·연속 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"접수 시각과 보류 상태를 빠뜨리지 않는 쪽을 고른다. 빚과 양천의 거부권은 인수인계의 서로 다른 칸에 남긴다.\n\n- 생업: 인준 장부 인수인계·연속 기록\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 인준 기록관\n**생애.** 서울역 등기소에서 자랐다. 인준 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 임빛나의 인준 장부 인수인계·연속 기록 업무는 회현동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 인준 기록관.\n\n**일화.** 한재목의 서부안이 윤서린의 도장을 기다리는 사이 인준 기록관 당직이 바뀐다. 임빛나는 서부안의 접수 시각과 보류 상태를 연속 기록에 옮기고, 멈춘 동안 쌓이는 빚과 찍는 순간 사라지는 양천의 거부권을 인수인계 메모의 두 칸에 나누어 적는다.\n\n**관계.** 인준 장부 인수인계·연속 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 인준 기록관 자리에서 인준 장부 인수인계·연속 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**공포.** 인준 기록관 당직이 비어 인준 장부 인수인계·연속 기록 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.\n\n**개입.** 인준 장부 인수인계·연속 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 20 | 개방 −15 | 무력 −35 | 물질 −30 | 공동 20 | 원칙 60 | 공개 −15 | 자격 0 | 분산 −20 | 변혁 −30\n- 욕망: 갈망 5 | 독점 20 | 위험 40 | 과시 −10 | 지속 15 | 지향 유동 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"임빛나","type":"계약","to":"양해온","basis":"임빛나는 인준 접수 시각과 보류 상태의 연속 기록을 양해온에게 넘긴다. 양해온은 심사관 날인과 문서고 보관 확인을 살펴 다음 교대에 보류가 누락되지 않은 전갈을 전한다."}],"incoming":[]}}');
