INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0758', 'b958-bb38-d654-67f3', '{"id":"person-0758","name":"Ryu Eun-hyeon","title":"Escort Logistics Merchant","position":"Myeongdong Station Relief Supplies Duty","rank":"Congregationioner","commonTier":"T5","occupation":"Relief Supplies Handover Records","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0758","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0758","name":"류은현","title":"호송 물류상","position":"명동역 구휼 물자 당직","rank":"교우","commonTier":"T5","occupation":"구휼 물자 인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0758","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0759', 'd64d-b0a8-c591', '{"id":"person-0759","name":"Hong Nam-won","title":"Escort Patrol","position":"Escort Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Escort Patrol Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0759","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0759","name":"홍남원","title":"호송 순찰대","position":"호송 순찰대","rank":"조합원","commonTier":"T5","occupation":"호송 순찰 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0759","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0760', 'ace0-d55c-c591', '{"id":"person-0760","name":"Go Neul-jin","title":"Ration District Clerk","position":"Ration District Clerk","characterId":"K760","rank":"Clerk","commonTier":"T5","occupation":"Water Distribution Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-go-neuljin","detailRoute":"/people/person-0760","birthDate":"2096-05-25","birthday":"05-25","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k760-sealed-allocation-log","name":"Sealed-allocation logging","rating":60}],"traits":[{"id":"k760-action-priority","name":"Compare before and after sealing","description":"An elected-monarch contract draft comes down without the joint signature of the contract council''s electors, and I Seodam seals the ration tables and the bridge tolls together. Go Neuljin copies the list of sealed ration tables into the duty handover record so the next shift can compare the allotments before and after the seal on a single page.","behavior":"An elected-monarch contract draft comes down without the joint signature of the contract council''s electors, and I Seodam seals the ration tables and the bridge tolls together. Go Neuljin copies the list of sealed ration tables into the duty handover record so the next shift can compare the allotments before and after the seal on a single page.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]},{"id":"k760-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]}],"narrative":"An elected-monarch contract draft comes down without the joint signature of the contract council''s electors, and I Seodam seals the ration tables and the bridge tolls together. Go Neuljin copies the list of sealed ration tables into the duty handover record so the next shift can compare the allotments before and after the seal on a single page. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":40,"Openness":-5,"Force":20,"Material":60,"Communal":30,"Principle":20,"Public":15,"Eligibility":-10,"Dispersed":-45,"Transformative":-15},"desire":{"Longing":25,"Monopoly":40,"Risk":-10,"Display":25,"Sustained":35,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Water Distribution Duty","Rank":"Clerk","Title":"Ration District Clerk","Work Location":"Sinjeong 2-dong. Go Neuljin copies the before-and-after distribution amounts of the ration tickets sealed by Yi Seodam onto a single page and hands it over so that the next duty officer in Sinjeong 2-dong can check them directly.","Values":"Authority 40 | Openness −5 | Force 20 | Material 60 | Communal 30 | Principle 20 | Publicity 15 | Qualification −10 | Dispersion −45 | Transformation −15","Desires":"Craving 25 | Monopoly 40 | Risk −10 | Display 25 | Persistence 35 | Orientation Bisexual | Union Contract Cohabitation"},"sections":{"Life":"Generation of 2126. Grew up at the Yeongdeungpo water purification duty post. The Ration District Clerk post opened through a valve signature on the Night of Turbid Water.\n- Work location: Sinjeong 2-dong. Go Neuljin copies the before-and-after distribution amounts of the ration tickets sealed by Yi Seodam onto a single page and hands it over so that the next duty officer in Sinjeong 2-dong can check them directly.","Offices":"Rank: Senior Clerk. Title: Ration District Clerk. Go Neuljin copies the before-and-after distribution amounts of the ration tickets sealed by Yi Seodam onto a single page and hands it over so that the next duty officer in Sinjeong 2-dong can check them directly.","Anecdote":"A contract proposal from an elected monarch, lacking the co-signatures of the Contract Council electors, comes down, and Yi Seodam seals the ration tickets and the bridge tolls together. Go Neuljin copies the list of sealed ration tickets into the duty handover record so that the next duty officer can check the distribution amounts before and after the seal on a single page.","Relationships":"Works as Lee Seodam''s Ration District Clerk and takes the water distribution watch.","Ambition":"In the post of Ration District Clerk, keeps the Water Gate Bureau''s ledger linked without a break.","Fear":"That the Water Gate Bureau''s passage becomes a hostage of the great powers if the Ration District Clerk''s watch is left vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first whichever course keeps the watch unbroken. Trusts a single ledger line over loud talk.\n\n- Affiliation: Water Gate Bureau\n- Livelihood: Water Distribution Watch\n- Rank: Jusa\n- Title: Ration District Clerk\n**Life.** Generation of 2126. Grew up at the Yeongdeungpo water purification watch. The post of Ration District Clerk opened through a valve signature on the Turbid Water Night.\n- Work location: Sinjeong 2-dong. Go Neuljin copies the before-and-after distribution amounts of the ration tickets that I Seodam sealed onto a single page, so that the next watch at Sinjeong 2-dong can check them directly.\n\n**Office.** Rank Jusa. Title: Ration District Clerk. Go Neuljin copies the before-and-after distribution amounts of the ration tickets that I Seodam sealed onto a single page, so that the next watch at Sinjeong 2-dong can check them directly.\n\n**Anecdote.** A draft Elected Monarch contract arrives from the Contract Council without the electors'' joint signatures, and I Seodam seals the ration tickets and the bridge tolls together. Go Neuljin copies the list of sealed ration tickets into the watch handover record, so that the next watch can reconcile the amounts distributed before and after the sealing on a single page.\n\n**Relationships.** Serves as I Seodam''s Ration District Clerk and holds the Water Distribution Watch.\n\n**Ambition.** To keep the Water Gate Bureau''s ledger continuously connected from the post of Ration District Clerk.\n\n**Fear.** That if the Ration District Clerk''s watch falls vacant, the Water Gate Bureau''s passage will become a hostage to the strong states.\n\n**Intervention.** Can set up a witness for the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 40 | Openness −5 | Force 20 | Materialism 60 | Communalism 30 | Principle 20 | Transparency 15 | Qualification −10 | Dispersal −45 | Change −15\n- Desires: Craving 25 | Monopoly 40 | Risk −10 | Display 25 | Endurance 35 | Orientation Bisexual | Union Contract Cohabitation\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Go Neul-jin","type":"Command","to":"I Seo-dam","basis":"Serves as clerk of Yi Seodam''s ration district and holds the water distribution watch"}],"incoming":[]}}', '{"id":"person-0760","name":"고늘진","title":"배급구역 서기","position":"배급구역 서기","characterId":"K760","rank":"주사","commonTier":"T5","occupation":"급수 배분 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-고늘진","detailRoute":"/people/person-0760","birthDate":"2096-05-25","birthday":"05-25","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k760-sealed-allocation-log","name":"봉인 배분 기록","rating":60}],"traits":[{"id":"k760-action-priority","name":"봉인 전후의 대조","description":"계약 회의 선거인의 연서가 빠진 선출 군주의 계약안이 내려오고, 이서담이 배급표와 교량 통행세를 함께 봉인한다. 고늘진은 봉인된 배급표의 목록을 당직 인수인계 기록에 옮겨, 봉인 전과 봉인 뒤의 배분량을 다음 당직이 한 쪽에서 맞춰 보게 한다.","behavior":"계약 회의 선거인의 연서가 빠진 선출 군주의 계약안이 내려오고, 이서담이 배급표와 교량 통행세를 함께 봉인한다. 고늘진은 봉인된 배급표의 목록을 당직 인수인계 기록에 옮겨, 봉인 전과 봉인 뒤의 배분량을 다음 당직이 한 쪽에서 맞춰 보게 한다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]},{"id":"k760-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]}],"narrative":"계약 회의 선거인의 연서가 빠진 선출 군주의 계약안이 내려오고, 이서담이 배급표와 교량 통행세를 함께 봉인한다. 고늘진은 봉인된 배급표의 목록을 당직 인수인계 기록에 옮겨, 봉인 전과 봉인 뒤의 배분량을 다음 당직이 한 쪽에서 맞춰 보게 한다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"ace0-d55c-c591","name":"한양 고씨","crest":"clan-crests/ace0-d55c-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":40,"개방":-5,"무력":20,"물질":60,"공동":30,"원칙":20,"공개":15,"자격":-10,"분산":-45,"변혁":-15},"desire":{"갈망":25,"독점":40,"위험":-10,"과시":25,"지속":35,"지향":"양성","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"급수 배분 당직","품계":"주사","직함":"배급구역 서기","업무 위치":"신정2동. 고늘진은 이서담이 봉인한 배급표의 전후 배분량을 한 쪽에 옮겨 신정2동의 다음 당직이 직접 대조하도록 넘긴다.","가치관":"권위 40 | 개방 −5 | 무력 20 | 물질 60 | 공동 30 | 원칙 20 | 공개 15 | 자격 −10 | 분산 −45 | 변혁 −15","욕망":"갈망 25 | 독점 40 | 위험 −10 | 과시 25 | 지속 35 | 지향 양성 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 고늘진은 이서담이 봉인한 배급표의 전후 배분량을 한 쪽에 옮겨 신정2동의 다음 당직이 직접 대조하도록 넘긴다.","관직":"품계 주사. 직함은 배급구역 서기이다. 고늘진은 이서담이 봉인한 배급표의 전후 배분량을 한 쪽에 옮겨 신정2동의 다음 당직이 직접 대조하도록 넘긴다.","일화":"계약 회의 선거인의 연서가 빠진 선출 군주의 계약안이 내려오고, 이서담이 배급표와 교량 통행세를 함께 봉인한다. 고늘진은 봉인된 배급표의 목록을 당직 인수인계 기록에 옮겨, 봉인 전과 봉인 뒤의 배분량을 다음 당직이 한 쪽에서 맞춰 보게 한다.","관계":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","야망":"배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 급수 배분 당직\n- 품계: 주사\n- 직함: 배급구역 서기\n**생애.** 2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 고늘진은 이서담이 봉인한 배급표의 전후 배분량을 한 쪽에 옮겨 신정2동의 다음 당직이 직접 대조하도록 넘긴다.\n\n**관직.** 품계 주사. 직함은 배급구역 서기이다. 고늘진은 이서담이 봉인한 배급표의 전후 배분량을 한 쪽에 옮겨 신정2동의 다음 당직이 직접 대조하도록 넘긴다.\n\n**일화.** 계약 회의 선거인의 연서가 빠진 선출 군주의 계약안이 내려오고, 이서담이 배급표와 교량 통행세를 함께 봉인한다. 고늘진은 봉인된 배급표의 목록을 당직 인수인계 기록에 옮겨, 봉인 전과 봉인 뒤의 배분량을 다음 당직이 한 쪽에서 맞춰 보게 한다.\n\n**관계.** 이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.\n\n**야망.** 배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 40 | 개방 −5 | 무력 20 | 물질 60 | 공동 30 | 원칙 20 | 공개 15 | 자격 −10 | 분산 −45 | 변혁 −15\n- 욕망: 갈망 25 | 독점 40 | 위험 −10 | 과시 25 | 지속 35 | 지향 양성 | 결합 계약동거\n:::","directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"고늘진","type":"지휘","to":"이서담","basis":"이서담의 배급구역 서기로 급수 배분 당직을 맡음"}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0761', 'bb38-b0a8-d3c9-6587', '{"id":"person-0761","name":"Mun Dal-eun","title":"Work Crew Courier","position":"Work Crew Courier","rank":"Guild Member","commonTier":"T5","occupation":"Transfer Message Delivery","gender":"Female","stage":"S4","state":"S02","stateName":"The Gauge","detailRoute":"/people/person-0761","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0761","name":"문달은","title":"작업반 전령","position":"작업반 전령","rank":"조합원","commonTier":"T5","occupation":"환승 전갈 전달","gender":"여성","stage":"S4","state":"S02","stateName":"규격맹","detailRoute":"/people/person-0761","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0762', 'c591-ccad-c8fc', '{"id":"person-0762","name":"Yang Reum-tae","title":"Retainer Recorder","position":"Retainer Recorder","characterId":"K762","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#inmul-yangreumtae","detailRoute":"/people/person-0762","birthDate":"2072-06-10","birthday":"06-10","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"log-gap","name":"Temperature-log gap reconciliation","rating":55},{"id":"handover","name":"Record and key handover","rating":45}],"traits":[{"id":"check-gaps-against-shifts","name":"Check Gaps Against Shifts","description":"Yang Reumtae traces gaps in temperature and humidity records against shift times.","behavior":"They compare entries surrounding a gap with shift times and mark the interrupted interval.","stress":"Concern that an unattended shift could compromise the group''s passage may heighten their attention to interrupted records.","relationship":"When explaining record gaps to a shift partner, they may rely on the marked intervals.","effects":[]},{"id":"hand-over-box-numbers","name":"Hand Over Box Numbers","description":"Yang Reumtae identifies boxes associated with a record gap by number for handover.","behavior":"They copy the affected box numbers onto the key handover sheet and pass it to Park Jinsol.","stress":"If a vacant shift threatens passage, they may become especially wary of omitting affected box numbers.","relationship":"When checking the handover with Park Jinsol, they may focus on sharing numbers and records rather than extending their authority.","effects":[]}],"narrative":"She matched temperature-log gaps to shift times during unstable power and passed affected box numbers. Record tracing is supported, not seed biology.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c591-ccad-c8fc","name":"Cheongju Yang Clan","crest":"clan-crests/c591-ccad-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":20,"Force":-40,"Material":0,"Communal":0,"Principle":75,"Public":35,"Eligibility":35,"Dispersed":5,"Transformative":15},"desire":{"Longing":40,"Monopoly":-5,"Risk":-40,"Display":5,"Sustained":40,"Orientation":"None","Union":"None"},"fields":{"Affiliation":"Arc","Livelihood":"Records and Keys Handover","Rank":"Assistant Manager","Title":"Retainer Recorder","Duty":"Gayang 1-dong. At Gayang 1-dong, Yang Reumtae matches seed records and handover signatures against the originals and passes them to the next watch. Boxes whose temperature and humidity records were broken have their numbers noted separately and are reported to Bak Jinsol.","Values":"Authority 0 | Openness 20 | Force −40 | Materialism 0 | Communalism 0 | Principle 75 | Transparency 35 | Qualification 35 | Dispersal 5 | Change 15","Desires":"Craving 40 | Monopoly −5 | Risk −40 | Display 5 | Endurance 40 | Orientation None | Union None"},"sections":{"Life":"Generation of 2126. Grew up at the Seoul Station Registry. Yang Reumtae is in charge of matching seed records against vault handover records.\n- Work: Gayang 1-dong. At Gayang 1-dong, Yang Reumtae matches seed records and handover signatures against the originals and passes them to the next watch. Boxes whose temperature and humidity records were broken have their numbers noted separately and are reported to Bak Jinsol.","Offices":"Rank: Deputy. Title: Seed Records Officer. Checks the originals against handover signatures, and marks the numbers of boxes with broken records and submits them for Park Jinsol''s release decision.","Anecdote":"During the night the power wavers and blanks appear in the cold storage''s temperature and humidity records. Yang Reumtae matches the records before and after each blank against the shift times, marks the broken interval, and copies the numbers of the boxes that were in that interval onto the key handover sheet and passes it to Bak Jinsol.","Relationships":"Yang Reumtae hands Bak Jinsol the times and box numbers of the severed temperature-humidity records. Bak Jinsol checks those boxes so that supplies from the stretch without a temperature log are not passed along as a normal release.","Ambition":"Yang Reumtae intends to record the shift times before and after the broken temperature and humidity records, together with the box numbers, in the key handover record.","Fear":"That a box left unrecorded during a power fluctuation will be shipped out as if in normal preservation condition.","Intervention":"The player can cross-check Yang Reumtae''s key handover sheet against the box numbers in the temperature and humidity gap."},"biography":"At Gayang 1-dong, Yang Reumtae first checks the original seed records for missing lines. Even when pressed to release items from the vault, Yang Reumtae matches the handover records against the temperature and humidity ledger before passing them to Bak Jinsol.\n\n- Affiliation: Arc\n- Livelihood: Record and Key Handover\n- Rank: Daeri\n- Title: Seed Records Keeper\n**Life.** Generation of 2126. Grew up at the Seoul Station Registry. Yang Reumtae is in charge of matching seed records against vault handover records.\n- Work: Gayang 1-dong. At Gayang 1-dong, Yang Reumtae matches seed records and handover signatures against the originals and passes them to the next watch. Boxes whose temperature and humidity records were broken have their numbers noted separately and are reported to Bak Jinsol.\n\n**Office.** Rank Daeri. Title: Seed Records Keeper. Checks the originals against the handover signatures, and marks the numbers of boxes whose records were broken and submits them to Bak Jinsol''s release decision.\n\n**Anecdote.** During the night the power wavers and blanks appear in the cold storage''s temperature and humidity records. Yang Reumtae matches the records before and after each blank against the shift times, marks the broken interval, and copies the numbers of the boxes that were in that interval onto the key handover sheet and passes it to Bak Jinsol.\n\n**Relationships.** Yang Reumtae passes the times of the broken temperature and humidity records and the box numbers to Bak Jinsol. Bak Jinsol checks those boxes so that supplies from the interval with no temperature log are not passed through as normal releases.\n\n**Ambition.** Yang Reumtae intends to record the shift times before and after the broken temperature and humidity records, together with the box numbers, in the key handover record.\n\n**Fear.** That a box left unrecorded during a power fluctuation will be shipped out as if in normal preservation condition.\n\n**Intervention.** The player can cross-check Yang Reumtae''s key handover sheet against the box numbers in the temperature and humidity gap.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 0 | Openness 20 | Force −40 | Materialism 0 | Communalism 0 | Principle 75 | Transparency 35 | Qualification 35 | Dispersal 5 | Change 15\n- Desires: Craving 40 | Monopoly −5 | Risk −40 | Display 5 | Endurance 40 | Orientation None | Union None\n:::","relations":{"outgoing":[{"from":"Yang Reum-tae","type":"Contract","to":"Bak Jinsol","basis":"Yang Reumtae hands Bak Jinsol the times and box numbers of the severed temperature-humidity records. Bak Jinsol checks those boxes so that supplies from the stretch without a temperature log are not passed along as a normal release."}],"incoming":[]}}', '{"id":"person-0762","name":"양름태","title":"종자 기록관","position":"종자 기록관","characterId":"K762","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-03#인물-양름태","detailRoute":"/people/person-0762","birthDate":"2072-06-10","birthday":"06-10","age":54,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"log-gap","name":"온습도 기록 공백 대조","rating":55},{"id":"handover","name":"기록·열쇠 인수인계","rating":45}],"traits":[{"id":"check-gaps-against-shifts","name":"공백을 교대와 대조","description":"양름태는 온습도 기록의 빈칸을 교대 시각과 맞춰 추적하는 쪽이다.","behavior":"빈칸 앞뒤 기록과 교대 시각을 대조해 기록이 끊긴 구간을 표시한다.","stress":"당직 공백이 통행의 종속으로 이어질 우려가 커지면 끊긴 구간의 확인을 더 중시할 수 있다.","relationship":"교대 상대와 기록 공백을 공유해야 한다면 표시된 구간을 설명의 근거로 삼을 수 있다.","effects":[]},{"id":"hand-over-box-numbers","name":"상자 번호 인계","description":"양름태는 기록 공백에 관련된 상자를 번호로 특정해 인계하는 쪽이다.","behavior":"끊긴 구간에 있던 상자 번호를 열쇠 인계 기록지에 옮겨 박진솔에게 넘긴다.","stress":"당직이 비어 통행이 위태로워질 우려가 있으면 관련 상자 번호의 누락을 더 경계할 수 있다.","relationship":"박진솔과 인계 내용을 확인할 때 권한을 넓히기보다 번호와 기록을 공유하는 데 집중할 수 있다.","effects":[]}],"narrative":"전력 불안 때 온습도 공백을 교대와 대조하고 관련 상자 번호를 넘겼다. 기록 추적이 강점이며 종자 생물학은 추가하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c591-ccad-c8fc","name":"청주 양씨","crest":"clan-crests/c591-ccad-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":20,"무력":-40,"물질":0,"공동":0,"원칙":75,"공개":35,"자격":35,"분산":5,"변혁":15},"desire":{"갈망":40,"독점":-5,"위험":-40,"과시":5,"지속":40,"지향":"무성향","결합":"없음"},"fields":{"소속":"Arc","생업":"기록·열쇠 인수인계","품계":"대리","직함":"종자 기록관","업무":"가양1동. 양름태는 가양1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 온습도 기록이 끊긴 상자는 번호를 따로 적어 박진솔에게 알린다.","가치관":"권위 0 | 개방 20 | 무력 −40 | 물질 0 | 공동 0 | 원칙 75 | 공개 35 | 자격 35 | 분산 5 | 변혁 15","욕망":"갈망 40 | 독점 −5 | 위험 −40 | 과시 5 | 지속 40 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 양름태는 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 가양1동. 양름태는 가양1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 온습도 기록이 끊긴 상자는 번호를 따로 적어 박진솔에게 알린다.","관직":"품계 대리. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.","일화":"밤사이 전력이 흔들려 냉온고 온습도 기록에 빈칸이 생긴다. 양름태는 빈칸 앞뒤의 기록을 교대 시각과 맞춰 끊긴 구간을 표시하고, 그 구간에 들어 있던 상자 번호를 열쇠를 넘기는 기록지에 옮겨 박진솔에게 넘긴다.","관계":"양름태는 끊긴 온습도 기록의 시각과 상자 번호를 박진솔에게 넘긴다. 박진솔은 해당 상자를 확인해 온도 로그가 없는 구간의 물자가 정상 출고로 넘어가지 않게 한다.","야망":"양름태는 끊긴 온습도 기록의 앞뒤 교대 시각과 상자 번호를 열쇠 인수 기록에 함께 남기려 한다.","공포":"전력 흔들림 때 기록되지 않은 상자가 정상 보존 상태로 출고되는 것.","개입":"플레이어는 양름태의 열쇠 인수지와 온습도 공백의 상자 번호를 대조할 수 있다."},"biography":"가양1동에서 양름태는 종자 원본의 빠진 줄을 먼저 살핀다. 보존고 출고를 재촉받아도 인수 기록과 온습도 장부를 맞춘 뒤 박진솔에게 넘긴다.\n\n- 소속: Arc\n- 생업: 기록·열쇠 인수인계\n- 품계: 대리\n- 직함: 종자 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 양름태는 종자 기록과 보존고 인수 기록을 맞추는 일을 맡는다.\n- 업무: 가양1동. 양름태는 가양1동에서 종자 기록과 인수 서명을 원본에 맞춰 다음 당직에 넘긴다. 온습도 기록이 끊긴 상자는 번호를 따로 적어 박진솔에게 알린다.\n\n**관직.** 품계 대리. 직함은 종자 기록관. 원본과 인수 서명을 대조하고, 기록이 끊긴 상자는 번호를 표시해 박진솔의 출고 판단에 올린다.\n\n**일화.** 밤사이 전력이 흔들려 냉온고 온습도 기록에 빈칸이 생긴다. 양름태는 빈칸 앞뒤의 기록을 교대 시각과 맞춰 끊긴 구간을 표시하고, 그 구간에 들어 있던 상자 번호를 열쇠를 넘기는 기록지에 옮겨 박진솔에게 넘긴다.\n\n**관계.** 양름태는 끊긴 온습도 기록의 시각과 상자 번호를 박진솔에게 넘긴다. 박진솔은 해당 상자를 확인해 온도 로그가 없는 구간의 물자가 정상 출고로 넘어가지 않게 한다.\n\n**야망.** 양름태는 끊긴 온습도 기록의 앞뒤 교대 시각과 상자 번호를 열쇠 인수 기록에 함께 남기려 한다.\n\n**공포.** 전력 흔들림 때 기록되지 않은 상자가 정상 보존 상태로 출고되는 것.\n\n**개입.** 플레이어는 양름태의 열쇠 인수지와 온습도 공백의 상자 번호를 대조할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 20 | 무력 −40 | 물질 0 | 공동 0 | 원칙 75 | 공개 35 | 자격 35 | 분산 5 | 변혁 15\n- 욕망: 갈망 40 | 독점 −5 | 위험 −40 | 과시 5 | 지속 40 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"양름태","type":"계약","to":"박진솔","basis":"양름태는 끊긴 온습도 기록의 시각과 상자 번호를 박진솔에게 넘긴다. 박진솔은 해당 상자를 확인해 온도 로그가 없는 구간의 물자가 정상 출고로 넘어가지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0763', 'c190-bc00-c591', '{"id":"person-0763","name":"Son Ba-ho","title":"Holding Track Patrol","position":"Holding Track Patrol","characterId":"K763","rank":"Teacher","commonTier":"T5","occupation":"Guard & Patrol","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-sonbaho","detailRoute":"/people/person-0763","birthDate":"2098-05-05","birthday":"05-05","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[{"id":"guard","name":"Entry control and pass replacement","rating":55},{"id":"handover","name":"Record and key handover","rating":40}],"traits":[{"id":"detect-unauthorized-crossings","name":"Detect Unauthorized Crossings","description":"Son Baho shows a disposition to uphold crossing controls, grounded in catching an unauthorized night crosser.","behavior":"He directly addressed a crossing violation by catching the unauthorized night crosser.","stress":"If a duty gap threatens to leave passage hostage to a powerful state, he may become more attentive to crossings.","relationship":"In handovers with senior duty staff, he may emphasize responsibility for maintaining crossing controls.","effects":[]},{"id":"reissue-security-tokens","name":"Reissue Security Tokens","description":"Son Baho shows a disposition to restore security conditions by changing guard tokens after a crossing violation.","behavior":"He replaced the guard password token after catching the unauthorized crosser.","stress":"If passage control appears threatened, he may prioritize token renewal within his actual authority.","relationship":"When handing over keys and records to senior duty staff, he may seek to clarify the token change.","effects":[]}],"narrative":"He stopped a night crosser and changed security passes. Guard experience is supported; rank does not grant troops or equipment.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c190-bc00-c591","name":"Miryang Son Clan","crest":"clan-crests/c190-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":20,"Openness":10,"Force":0,"Material":25,"Communal":30,"Principle":15,"Public":-20,"Eligibility":25,"Dispersed":25,"Transformative":10},"desire":{"Longing":40,"Monopoly":10,"Risk":25,"Display":-25,"Sustained":20,"Orientation":"None","Union":"None"},"fields":{"Affiliation":"Arc","Livelihood":"Guard & Patrol","Rank":"Teacher","Title":"Holding Track Patrol","Values":"Authority 20 | Openness 10 | Force 0 | Material 25 | Communal 30 | Principle 15 | Disclosure −20 | Qualification 25 | Dispersal 25 | Transformation 10","Desires":"Craving 40 | Monopoly 10 | Risk 25 | Display −25 | Endurance 20 | Orientation No orientation | Bonding None"},"sections":{"Life":"Generation of 2126. Son Baho grew up at the Amsa guard post. Son Baho took the Stabling-Line Patrol post after catching a night unauthorized river crossing.\n- Son Baho''s Stabling-Line Patrol work is connected to Yongdap-dong.","Offices":"Son Baho hands over only the keys and records attached to the post. Authority that does not exist is not made up.","Anecdote":"In 2125 Son Baho caught a night unauthorized crosser and replaced the guard passcode tag. Because of this, the signature for the Stabling-Line Patrol post was entered in the ledger.","Relationships":"Son Baho is bound by handover to a senior duty officer from the same living area.","Ambition":"Son Baho wishes to keep the Arc''s ledger unbroken through the Stabling-Line Patrol duty.","Fear":"Son Baho fears that if the Stabling-Line Patrol duty falls vacant, the Arc''s passage will become a hostage of a great power.","Intervention":"Son Baho can bring in a witness for the duty handover or expose an empty key."},"biography":"Son Baho chooses first not to break the duty. Son Baho trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Arc\n- Livelihood: Guard & Patrol\n- Rank: Instructor\n- Title: Stabling-Line Patrol\n**Life.** Generation of 2126. Son Baho grew up at the Amsa guard post. Son Baho took the Stabling-Line Patrol post after catching a night unauthorized river crossing.\n- Son Baho''s Stabling-Line Patrol work is connected to Yongdap-dong.\n\n**Office.** Son Baho hands over only the keys and records attached to the post. Authority that does not exist is not made up.\n\n**Anecdote.** In 2125 Son Baho caught a night unauthorized crosser and replaced the guard passcode tag. Because of this, the signature for the Stabling-Line Patrol post was entered in the ledger.\n\n**Relations.** Son Baho is bound by handover to a senior duty officer from the same living area.\n\n**Ambition.** Son Baho wishes to keep the Arc''s ledger unbroken through the Stabling-Line Patrol duty.\n\n**Fear.** Son Baho fears that if the Stabling-Line Patrol duty falls vacant, the Arc''s passage will become a hostage of a great power.\n\n**Intervention.** Son Baho can bring in a witness for the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 20 | Openness 10 | Force 0 | Material 25 | Communal 30 | Principle 15 | Disclosure −20 | Qualification 25 | Dispersal 25 | Transformation 10\n- Desires: Craving 40 | Monopoly 10 | Risk 25 | Display −25 | Endurance 20 | Orientation No orientation | Bonding None\n:::","relations":{"outgoing":[{"from":"Son Ba-ho","type":"Contract","to":"Chae Gu-reum","basis":"Son Baho passes the holding siding''s night access records and the contents of the replacement passcode tags to Chae Gureum. Chae Gureum keeps to double verification at bridge access and watches for approaches through gaps in the guard shift handover."}],"incoming":[]}}', '{"id":"person-0763","name":"손바호","title":"유치선 순찰대","position":"유치선 순찰대","characterId":"K763","rank":"교사","commonTier":"T5","occupation":"경비·순찰","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-손바호","detailRoute":"/people/person-0763","birthDate":"2098-05-05","birthday":"05-05","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[{"id":"guard","name":"출입 저지·암호패 교체","rating":55},{"id":"handover","name":"기록·열쇠 인수인계","rating":40}],"traits":[{"id":"detect-unauthorized-crossings","name":"무단 도하 적발","description":"손바호는 야간 무단 도하를 놓치지 않고 당직의 통행 경계를 지키려는 성향을 보인다.","behavior":"야간 무단 도하자를 붙잡아 통행 위반에 직접 대응했다.","stress":"당직 공백으로 통행이 강국의 볼모가 될 우려가 커지면 도하 감시에 더 주의를 기울일 수 있다.","relationship":"선배 당직과 인계할 때 통행 경계를 이어 맡을 책임을 중요하게 여길 수 있다.","effects":[]},{"id":"reissue-security-tokens","name":"보안패 재발급","description":"손바호는 통행 위반 뒤 경비 암호패를 바꾸어 보안 조건을 바로잡으려는 성향을 보인다.","behavior":"무단 도하자를 붙잡은 뒤 경비 암호패를 교체했다.","stress":"통행 통제가 흔들릴 우려가 생기면 자기 권한 안에서 보안패 갱신을 우선할 수 있다.","relationship":"선배 당직에게 열쇠와 기록을 넘길 때 암호패 변경 사실도 명확히 전달하려 할 수 있다.","effects":[]}],"narrative":"야간 도하자를 저지하고 암호패를 바꿨다. 실제 경비 경험은 있으나 지위만으로 병력이나 장비를 배정하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c190-bc00-c591","name":"밀양 손씨","crest":"clan-crests/c190-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":20,"개방":10,"무력":0,"물질":25,"공동":30,"원칙":15,"공개":-20,"자격":25,"분산":25,"변혁":10},"desire":{"갈망":40,"독점":10,"위험":25,"과시":-25,"지속":20,"지향":"무성향","결합":"없음"},"fields":{"소속":"Arc","생업":"경비·순찰","품계":"교사","직함":"유치선 순찰대","가치관":"권위 20 | 개방 10 | 무력 0 | 물질 25 | 공동 30 | 원칙 15 | 공개 −20 | 자격 25 | 분산 25 | 변혁 10","욕망":"갈망 40 | 독점 10 | 위험 25 | 과시 −25 | 지속 20 | 지향 무성향 | 결합 없음"},"sections":{"생애":"2126년 세대. 손바호는 암사 경비 초소에서 자랐다. 손바호는 야간 무단 도하 적발로 유치선 순찰대 자리를 맡았다.\n- 손바호의 유치선 순찰대 업무는 용답동과 연결된다.","관직":"손바호는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 손바호는 야간 무단 도꾼을 붙잡아 경비 암호패를 갈았다. 이 일로 유치선 순찰대 자리의 서명이 장부에 올랐다.","관계":"손바호는 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"손바호는 유치선 순찰대 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"손바호는 유치선 순찰대 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"손바호는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"손바호는 당직을 끊지 않는 쪽을 먼저 고른다. 손바호는 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 경비·순찰\n- 품계: 교사\n- 직함: 유치선 순찰대\n**생애.** 2126년 세대. 손바호는 암사 경비 초소에서 자랐다. 손바호는 야간 무단 도하 적발로 유치선 순찰대 자리를 맡았다.\n- 손바호의 유치선 순찰대 업무는 용답동과 연결된다.\n\n**관직.** 손바호는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 손바호는 야간 무단 도꾼을 붙잡아 경비 암호패를 갈았다. 이 일로 유치선 순찰대 자리의 서명이 장부에 올랐다.\n\n**관계.** 손바호는 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 손바호는 유치선 순찰대 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 손바호는 유치선 순찰대 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 손바호는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 20 | 개방 10 | 무력 0 | 물질 25 | 공동 30 | 원칙 15 | 공개 −20 | 자격 25 | 분산 25 | 변혁 10\n- 욕망: 갈망 40 | 독점 10 | 위험 25 | 과시 −25 | 지속 20 | 지향 무성향 | 결합 없음\n:::","relations":{"outgoing":[{"from":"손바호","type":"계약","to":"채구름","basis":"손바호는 유치선 야간 출입 기록과 교체 암호패 내용을 채구름에게 전한다. 채구름은 교량 출입에서 이중 확인을 지켜 경비 교대의 빈 곳을 통한 접근을 살핀다."}],"incoming":[]}}');
