INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0767', 'b0a8-c758-b839', '{"id":"person-0767","name":"Nam Ja-won","title":"Auction Clerk","position":"Auction Clerk","rank":"Corrections","commonTier":"T5","occupation":"Emergency Ration Coupon Disclosure","gender":"Female","stage":"S4","state":"S08","stateName":"Central Intelligence Bureau","detailRoute":"/people/person-0767","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0767","name":"남자원","title":"경매 서기","position":"경매 서기","rank":"교도","commonTier":"T5","occupation":"비상배급표 공개","gender":"여성","stage":"S4","state":"S08","stateName":"중앙정보부","detailRoute":"/people/person-0767","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0768', 'c2ec-ccad-c1a1', '{"id":"person-0768","name":"Sim Ta-yang","title":"Stand-In Courier","position":"Currency Exchange Courier","rank":"Clerk","commonTier":"T5","occupation":"Currency Exchange Courier Takeover and Ledger Delivery","gender":"Female","stage":"S4","state":"S09","stateName":"Yeouido Investors'' Association","detailRoute":"/people/person-0768","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0768","name":"심타양","title":"대역 전령","position":"환전 전령","rank":"서기","commonTier":"T5","occupation":"환전 전령 인수·장부 전달","gender":"여성","stage":"S4","state":"S09","stateName":"여의도출자연합회","detailRoute":"/people/person-0768","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0769', 'b178-ad50-d558-76e7', '{"id":"person-0769","name":"No Geum-ho","title":"Refugee Recorder","position":"Scripture Transcription Acolyte","characterId":"K769","rank":"Postulant","commonTier":"T5","occupation":"Transcribed Scripture and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-10#inmul-nogeumho","detailRoute":"/people/person-0769","birthDate":"2098-01-15","birthday":"01-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"register-separation","name":"Water and service-register separation","rating":50}],"traits":[{"id":"register-separation-disposition","name":"Separates bundled documents","description":"Unties bundled papers and submits overlapping names separately.","behavior":"Unties bundled papers and submits overlapping names separately.","stress":"Is wary of member rosters replaced by service registers.","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]},{"id":"recorded-boundary","name":"Reports duplicate names","description":"Submits names overlapping two registers to Yun Choa.","behavior":"Submits names overlapping two registers to Yun Choa.","stress":"Is wary of member rosters replaced by service registers.","relationship":"Maintains handover ties with senior duty workers of the same living area.","effects":[]}],"narrative":"Separated bundled water rights and service contracts for copying and gathered duplicate names across rosters. Separate recording does not itself establish a completed counter-institution.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-ad50-d558-76e7","name":"Gyoha No Clan","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-55,"Openness":60,"Force":-30,"Material":-30,"Communal":75,"Principle":50,"Public":45,"Eligibility":30,"Dispersed":60,"Transformative":-10},"desire":{"Longing":30,"Monopoly":-5,"Risk":-30,"Display":10,"Sustained":35,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Livelihood":"Transcribed Scripture and Duty Keys Handover","Affiliation":"The Government","Rank":"Postulant","Title":"Scripture Transcription Acolyte","Values":"Authority −55 | Openness 60 | Force −30 | Material −30 | Communal 75 | Principle 50 | Disclosure 45 | Qualification 30 | Dispersal 60 | Transformation −10","Desires":"Craving 30 | Monopoly −5 | Risk −30 | Display 10 | Endurance 35 | Orientation Opposite-sex | Bonding Non-exclusive"},"sections":{"Life":"Born 2098-01-15, active at the 2126 opening. Grew up at the Seoul Station registry office. The Sutra Copying Postulant''s duty record contains the deletion of one line of a double ledger.\n- Jongno 1·2·3·4-ga-dong is proposed as the reference point for No Geumho''s sutra transcript and duty key handover work. It does not confirm current posting, residence, fief, or ownership.","Offices":"Rank: Postulant. Title: Scripture Transcription Postulant. He hands over only the keys and transcripts of his own duty and creates no authority that he does not have. He casts his vote only at the Mountain General Assembly.","Anecdote":"A document binding a water-ration iron token and a service contract on one cord is posted again on the encampment notice board. No Geumho unties the two documents from the cord and transcribes them separately, then gathers the names that appear in both the believers'' register master ledger and the Standards League''s Restoration Service Register at the end of the transcript and hands them to Yun Choa.","Relationships":"No Geumho receives the last line of a senior duty officer''s ledger and begins the next shift''s record.","Ambition":"He keeps the transcription order of scriptures and ledgers so that the voting record continues alongside the original.","Fear":"That the vote lines and the supply lines will get mixed up in the gap between duties.","Intervention":"He can hand over the vote copy and the supply ledger separately, or call a shift witness."},"biography":"Untie the water-ration iron tokens and service contracts bound on one cord and transcribe each separately. Gather the overlapping names at the end of the document.\n\n- Livelihood: Sutra Transcripts & Duty Key Handover\n- Affiliation: The Government\n- Rank: Postulant\n- Title: Sutra Copying Postulant\n**Life.** Born 2098-01-15, active at the 2126 opening. Grew up at the Seoul Station registry office. The Sutra Copying Postulant''s duty record contains the deletion of one line of a double ledger.\n- Jongno 1·2·3·4-ga-dong is proposed as the reference point for No Geumho''s sutra transcript and duty key handover work. It does not confirm current posting, residence, fief, or ownership.\n\n**Office.** Rank: Postulant. Title: Sutra Copying Postulant. Hands over only the keys and transcripts of their own duty, and does not make up authority that does not exist. Votes only at the Mountain General Assembly.\n\n**Anecdote.** A document binding a water-ration iron token and a service contract on one cord is posted again on the encampment notice board. No Geumho unties the two documents from the cord and transcribes them separately, then gathers the names that appear in both the believers'' register master ledger and the Standards League''s Restoration Service Register at the end of the transcript and hands them to Yun Choa.\n\n**Relations.** No Geumho receives the last line of a senior duty officer''s ledger and begins the next shift''s record.\n\n**Ambition.** To keep the copying order of the scriptures and ledgers so that vote records continue together with the originals.\n\n**Fear.** Vote lines and supply lines getting mixed up in a gap between duties.\n\n**Intervention.** Can hand over vote copies and supply ledgers separately, or bring in a shift witness.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −55 | Openness 60 | Force −30 | Material −30 | Communal 75 | Principle 50 | Disclosure 45 | Qualification 30 | Dispersal 60 | Transformation −10\n- Desires: Craving 30 | Monopoly −5 | Risk −30 | Display 10 | Endurance 35 | Orientation Opposite-sex | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"No Geum-ho","type":"Contract","to":"Yun Choa","basis":"No Geumho hands Yun Choa the duplicated names between the separately transcribed water-ration documents and the service contracts. Yun Choa checks the believers'' and recovery-service registers to find where the two rights were bound by the same signature."}],"incoming":[]}}', '{"id":"person-0769","name":"노금호","title":"피난 기록관","position":"장경 필사 행자","characterId":"K769","rank":"행자","commonTier":"T5","occupation":"장경 필사본·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-10#인물-노금호","detailRoute":"/people/person-0769","birthDate":"2098-01-15","birthday":"01-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":10,"effective":10},"intrigue":{"base":11,"effective":11},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"register-separation","name":"급수·복무 명부 분리 대조","rating":50}],"traits":[{"id":"register-separation-disposition","name":"묶인 문서를 분리","description":"같은 끈의 문서를 풀고 겹친 이름을 따로 넘긴다.","behavior":"같은 끈의 문서를 풀고 겹친 이름을 따로 넘긴다.","stress":"신도 명부가 복무 명부로 대체될 것을 경계한다.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"recorded-boundary","name":"중복 이름 보고","description":"두 명부의 겹친 이름을 윤초아에게 넘긴다.","behavior":"두 명부의 겹친 이름을 윤초아에게 넘긴다.","stress":"장경 필사 행자 당직이 비면 안국총림의 필사본이 끊기고 문중 표가 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"한 끈의 급수권과 복무계약을 풀어 따로 필사하고 두 명부의 중복 이름을 모았다. 분리 기록은 강제등록을 완료한 반대 제도와 같지 않다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b178-ad50-d558-76e7","name":"교하 노씨","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-55,"개방":60,"무력":-30,"물질":-30,"공동":75,"원칙":50,"공개":45,"자격":30,"분산":60,"변혁":-10},"desire":{"갈망":30,"독점":-5,"위험":-30,"과시":10,"지속":35,"지향":"이성","결합":"비독점"},"fields":{"생업":"장경 필사본·당직 열쇠 인계","소속":"정부","품계":"행자","직함":"장경 필사 행자","가치관":"권위 −55 | 개방 60 | 무력 −30 | 물질 −30 | 공동 75 | 원칙 50 | 공개 45 | 자격 30 | 분산 60 | 변혁 −10","욕망":"갈망 30 | 독점 −5 | 위험 −30 | 과시 10 | 지속 35 | 지향 이성 | 결합 비독점"},"sections":{"생애":"2098-01-15 출생, 2126년 개막에 활동했다. 서울역 등기소에서 자랐다. 장경 필사 행자 당직 기록에는 이중 장부 한 줄 삭제 일이 남아 있다.\n- 노금호의 장경 필사본·당직 열쇠 인계 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.","관직":"품계 행자. 직함은 장경 필사 행자. 자기 당직의 열쇠와 필사본만 넘기고, 없는 권한은 만들지 않는다. 표는 산중총회에서만 던진다.","일화":"급수권 철표와 복무계약서를 한 끈으로 묶은 문서가 숙영지 게시판에 다시 붙는다. 노금호는 두 문서를 끈에서 풀어 따로 필사하고, 신도 명부 원장과 규격맹 복구복무 명부에 겹쳐 오른 이름을 필사본 끝에 모아 윤초아에게 넘긴다.","관계":"노금호는 선배 당직의 장부 끝줄을 받아 다음 교대 기록을 시작한다.","야망":"경전과 장부의 필사 순서를 지켜 표결 기록이 원본과 함께 이어지게 한다.","공포":"당직 공백 사이에 표결 줄과 물자 줄이 뒤섞이는 것.","개입":"표결 사본과 물자 장부를 분리해 건네거나 교대 증인을 세울 수 있다."},"biography":"한 끈에 묶인 급수권 철표와 복무계약서를 풀어 각각 필사한다. 겹친 이름은 문서 끝에 모은다.\n\n- 생업: 장경 필사본·당직 열쇠 인계\n- 소속: 정부\n- 품계: 행자\n- 직함: 장경 필사 행자\n**생애.** 2098-01-15 출생, 2126년 개막에 활동했다. 서울역 등기소에서 자랐다. 장경 필사 행자 당직 기록에는 이중 장부 한 줄 삭제 일이 남아 있다.\n- 노금호의 장경 필사본·당직 열쇠 인계 업무 기준점으로 종로1·2·3·4가동을 제안한다. 현재 근무 배치나 거주·영지·소유를 확정하지 않는다.\n\n**관직.** 품계 행자. 직함은 장경 필사 행자. 자기 당직의 열쇠와 필사본만 넘기고, 없는 권한은 만들지 않는다. 표는 산중총회에서만 던진다.\n\n**일화.** 급수권 철표와 복무계약서를 한 끈으로 묶은 문서가 숙영지 게시판에 다시 붙는다. 노금호는 두 문서를 끈에서 풀어 따로 필사하고, 신도 명부 원장과 규격맹 복구복무 명부에 겹쳐 오른 이름을 필사본 끝에 모아 윤초아에게 넘긴다.\n\n**관계.** 노금호는 선배 당직의 장부 끝줄을 받아 다음 교대 기록을 시작한다.\n\n**야망.** 경전과 장부의 필사 순서를 지켜 표결 기록이 원본과 함께 이어지게 한다.\n\n**공포.** 당직 공백 사이에 표결 줄과 물자 줄이 뒤섞이는 것.\n\n**개입.** 표결 사본과 물자 장부를 분리해 건네거나 교대 증인을 세울 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −55 | 개방 60 | 무력 −30 | 물질 −30 | 공동 75 | 원칙 50 | 공개 45 | 자격 30 | 분산 60 | 변혁 −10\n- 욕망: 갈망 30 | 독점 −5 | 위험 −30 | 과시 10 | 지속 35 | 지향 이성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"노금호","type":"계약","to":"윤초아","basis":"노금호는 따로 필사한 급수권 문서와 복무계약서의 중복 이름을 윤초아에게 넘긴다. 윤초아는 신도·복구복무 명부를 확인해 두 권리가 같은 서명으로 묶인 곳을 찾는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0770', 'd558-c9c4-c8fc', '{"id":"person-0770","name":"Ha Seo-eun","title":"Escort Courier","position":"Gangnam Station Escort Courier","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station Escort Records and Keys Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0770","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0770","name":"하서은","title":"호송 전령","position":"강남역 호송 전령","rank":"사원","commonTier":"T5","occupation":"강남역 호송 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0770","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0771', 'acfd-d604-d48d', '{"id":"person-0771","name":"Gwak Ha-hyeon","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0771","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0771","name":"곽하현","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0771","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0772', 'cangnyeong-seong-yeolcha', '{"id":"person-0772","name":"Seong Sol-hyeon","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K772","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-seongsolhyeon","detailRoute":"/people/person-0772","birthDate":"2098-10-03","birthday":"10-03","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"shift-condition-negotiation","name":"Shift condition negotiation","rating":55}],"traits":[{"id":"stated-priority","name":"Talks that reopen the next shift","description":"Overnight negotiation with a slowdown crew opened the next shift. Negotiation and sustained effort are reflected without filling in prescribing work from the title.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Overnight negotiation with a slowdown crew opened the next shift. Negotiation and sustained effort are reflected without filling in prescribing work from the title.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cangnyeong-seong-yeolcha","name":"Changnyeong Seong Clan","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":35,"Force":-55,"Material":-10,"Communal":25,"Principle":45,"Public":25,"Eligibility":15,"Dispersed":15,"Transformative":-10},"desire":{"Longing":0,"Monopoly":-40,"Risk":35,"Display":10,"Sustained":20,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −10 | Openness 35 | Force −55 | Material −10 | Communal 25 | Principle 45 | Disclosure 25 | Qualification 15 | Dispersal 15 | Transformation −10","Desires":"Craving 0 | Monopoly −40 | Risk 35 | Display 10 | Endurance 20 | Orientation Same-sex | Bonding Non-exclusive"},"sections":{"Life":"Born 2098-10-03. As of the 2126 opening, holds the Prescription Clerk post and continues the existing duties and records. In the succession record of that post, it opened as a substitute duty for an unauthorized shift absence.\n- The prescription record and duty key handover desk in Jegi-dong is taken as Seong Solhyeon''s work reference point. This posting does not confirm residence, exact facility boundaries, title, fief, or possession rights.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In 2125 shared terms overnight with the slowdown work crew and opened the next shift. That day''s record remained as grounds for handover that the next duty could verify.","Relationships":"Seong Solhyeon hands the records of the reopened prescription duty over to Eun Chaeyun. Eun Chaeyun checks the triage level and clinical findings and continues the treatment of patients who were dropped during the shift-change gap.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty. Trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Prescription Records & Duty Key Handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Prescription Clerk\n**Life.** Born 2098-10-03. As of the 2126 opening, holds the Prescription Clerk post and continues the existing duties and records. In the succession record of that post, it opened as a substitute duty for an unauthorized shift absence.\n- The prescription record and duty key handover desk in Jegi-dong is taken as Seong Solhyeon''s work reference point. This posting does not confirm residence, exact facility boundaries, title, fief, or possession rights.\n\n**Office.** Rank: Resident. Title: Prescription Resident. Hands over only the keys and records of their own post, and writes the time of receipt of the handed-over keys and records in the ledger.\n\n**Anecdote.** In 2125 shared terms overnight with the slowdown work crew and opened the next shift. That day''s record remained as grounds for handover that the next duty could verify.\n\n**Relations.** Seong Solhyeon passes the records of the reopened prescription duty to Eun Chaeyun. Eun Chaeyun checks severity and clinical findings and continues the treatment of patients who were dropped during the shift gap.\n\n**Ambition.** To keep the White Cross Order''s ledger unbroken from the post of Prescription Resident.\n\n**Fear.** Fears that if the Prescription Resident''s duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron powers.\n\n**Intervention.** Can bring in a witness for the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 35 | Force −55 | Material −10 | Communal 25 | Principle 45 | Disclosure 25 | Qualification 15 | Dispersal 15 | Transformation −10\n- Desires: Craving 0 | Monopoly −40 | Risk 35 | Display 10 | Endurance 20 | Orientation Same-sex | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Seong Sol-hyeon","type":"Contract","to":"Eun Chaeyun","basis":"Seong Solhyeon hands the records of the reopened prescription duty over to Eun Chaeyun. Eun Chaeyun checks the triage level and clinical findings and continues the treatment of patients who were dropped during the shift-change gap."}],"incoming":[]}}', '{"id":"person-0772","name":"성솔현","title":"처방 서기","position":"처방 서기","characterId":"K772","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-성솔현","detailRoute":"/people/person-0772","birthDate":"2098-10-03","birthday":"10-03","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"shift-condition-negotiation","name":"교대 조건 협의","rating":55}],"traits":[{"id":"stated-priority","name":"다음 교대를 여는 대화","description":"태업 작업반과 밤새 조건을 나눠 다음 교대를 열었다. 교섭과 긴장 감내를 반영하고 처방 수행은 직함으로 보충하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"태업 작업반과 밤새 조건을 나눠 다음 교대를 열었다. 교섭과 긴장 감내를 반영하고 처방 수행은 직함으로 보충하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cangnyeong-seong-yeolcha","name":"창녕 성씨","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":35,"무력":-55,"물질":-10,"공동":25,"원칙":45,"공개":25,"자격":15,"분산":15,"변혁":-10},"desire":{"갈망":0,"독점":-40,"위험":35,"과시":10,"지속":20,"지향":"동성","결합":"비독점"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −10 | 개방 35 | 무력 −55 | 물질 −10 | 공동 25 | 원칙 45 | 공개 25 | 자격 15 | 분산 15 | 변혁 −10","욕망":"갈망 0 | 독점 −40 | 위험 35 | 과시 10 | 지속 20 | 지향 동성 | 결합 비독점"},"sections":{"생애":"2098-10-03에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 성솔현의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 태업 작업반과 밤새 조건을 나눠 다음 교대를 열었다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"성솔현은 다시 열린 처방 당직의 기록을 은채윤에게 넘긴다. 은채윤은 중증도와 진료 소견을 확인해 교대 공백 중 빠진 환자의 치료를 잇는다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2098-10-03에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 성솔현의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 태업 작업반과 밤새 조건을 나눠 다음 교대를 열었다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 성솔현은 다시 열린 처방 당직의 기록을 은채윤에게 넘긴다. 은채윤은 중증도와 진료 소견을 확인해 교대 공백 중 빠진 환자의 치료를 잇는다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 35 | 무력 −55 | 물질 −10 | 공동 25 | 원칙 45 | 공개 25 | 자격 15 | 분산 15 | 변혁 −10\n- 욕망: 갈망 0 | 독점 −40 | 위험 35 | 과시 10 | 지속 20 | 지향 동성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"성솔현","type":"계약","to":"은채윤","basis":"성솔현은 다시 열린 처방 당직의 기록을 은채윤에게 넘긴다. 은채윤은 중증도와 진료 소견을 확인해 교대 공백 중 빠진 환자의 치료를 잇는다."}],"incoming":[]}}');
