INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0778', 'c9c4-d48d-ae30', '{"id":"person-0778","name":"Jin Ma-rin","title":"Water Quality Gauger","position":"Water Quality Gauger","rank":"Assistant Manager","commonTier":"T5","occupation":"Duty Log Handover","gender":"Female","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0778","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0778","name":"진마린","title":"수질 계측원","position":"수질 계측원","rank":"대리","commonTier":"T5","occupation":"당직 기록 인수인계","gender":"여성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0778","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0779', 'ae40-acbd-c8fc-91d1', '{"id":"person-0779","name":"Kim A-ho","title":"Workshop Herald","position":"Workshop Herald","characterId":"K779","rank":"","commonTier":"T3","occupation":"Escort and Personnel Ledger Management","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-gimaho","detailRoute":"/people/person-0779","birthDate":"2088-06-16","birthday":"06-16","age":38,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"save-register","name":"Emergency preservation of personnel registers","rating":45},{"id":"departure","name":"Departure and dispatch checks","rating":40}],"traits":[{"id":"save-ledgers-before-cargo","name":"Save Ledgers Before Cargo","description":"Kim Aho shows a disposition to prioritize preserving the register of people over cargo.","behavior":"When the convoy was attacked, he secured the register of people before the cargo.","stress":"If attack pressure coincides with fears of interrupted duty, he may give greater weight to preserving records.","relationship":"In handovers with senior duty staff, he may emphasize continuity of the personal records he prioritized over cargo.","effects":[]},{"id":"next-handover-accountability","name":"Next Handover Accountability","description":"Kim Aho values responsibility for carrying the preserved register forward to the next duty shift.","behavior":"He hands over only his position’s keys and records, staying within his remit to maintain ledger continuity.","stress":"If a duty gap could make passage dependent on a powerful state, he may become more alert to handover omissions.","relationship":"With senior duty staff in his community, he may seek trust through accountable transfer of the records in his care.","effects":[]}],"narrative":"She preserved personnel registers during a convoy attack. The choice of records is supported; subduing attackers is not claimed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43800-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K779","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43800-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ae40-acbd-c8fc-91d1","name":"Gyeongju Gim Clan","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":5,"Openness":20,"Force":-15,"Material":10,"Communal":35,"Principle":20,"Public":-10,"Eligibility":35,"Dispersed":10,"Transformative":0},"desire":{"Longing":20,"Monopoly":-35,"Risk":20,"Display":-10,"Sustained":5,"Orientation":"Bisexual","Union":"Polyamorous"},"fields":{"Affiliation":"Arc","Livelihood":"Escort and Personnel Ledger Management","Rank":"Teacher","Title":"Workshop Herald","Values":"Authority 5 | Openness 20 | Force −15 | Material 10 | Communal 35 | Principle 20 | Publicity −10 | Credential 35 | Dispersal 10 | Transformation 0","Desires":"Longing 20 | Possessiveness −35 | Risk 20 | Display −10 | Endurance 5 | Orientation Bisexual | Bonding Polyamorous"},"sections":{"Life":"Generation of 2126. Gim Aho grew up on the Sinnae Transfer watch. Gim Aho took the Workshop Courier post by stopping the ticketless departing train.\n- Gim Aho''s Workshop Courier duties are tied to Seongsu 2-ga 3-dong.","Offices":"Gim Aho hands over only the keys and records belonging to the post. Gim Aho does not invent authority that does not exist.","Anecdote":"In 2125, Gim Aho was ambushed during an escort and secured the people ledger before the cargo. Because of this, the Workshop Courier post''s signature was entered in the ledger.","Relationships":"Gim Aho is bound by handover to a senior watch member of the same living sphere.","Ambition":"As Workshop Courier on watch, Gim Aho wants to keep the Arc''s ledger connected without a break.","Fear":"Gim Aho fears that if the Workshop Courier watch falls vacant, the Arc''s passage would become a hostage of the great powers.","Intervention":"Gim Aho can call a witness to a watch handover or expose an empty key."},"biography":"Gim Aho chooses first not to break the watch. Gim Aho trusts a single line in the ledger over loud words.\n\n- Affiliation: Arc\n- Livelihood: Escort and people-ledger management\n- Rank: Instructor\n- Title: Workshop Courier\n**Life.** Generation of 2126. Gim Aho grew up on the Sinnae Transfer watch. Gim Aho took the Workshop Courier post by stopping the ticketless departing train.\n- Gim Aho''s Workshop Courier duties are tied to Seongsu 2-ga 3-dong.\n\n**Office.** Gim Aho hands over only the keys and records belonging to the post. Gim Aho does not invent authority that does not exist.\n\n**Anecdote.** In 2125, Gim Aho was ambushed during an escort and secured the people ledger before the cargo. Because of this, the Workshop Courier post''s signature was entered in the ledger.\n\n**Relationships.** Gim Aho is bound by handover to a senior watch member of the same living sphere.\n\n**Ambition.** As Workshop Courier on watch, Gim Aho wants to keep the Arc''s ledger connected without a break.\n\n**Fear.** Gim Aho fears that if the Workshop Courier watch falls vacant, the Arc''s passage would become a hostage of the great powers.\n\n**Intervention.** Gim Aho can call a witness to a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 5 | Openness 20 | Force −15 | Material 10 | Communal 35 | Principle 20 | Publicity −10 | Credential 35 | Dispersal 10 | Transformation 0\n- Desires: Longing 20 | Possessiveness −35 | Risk 20 | Display −10 | Endurance 5 | Orientation Bisexual | Bonding Polyamorous\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0779","name":"김아호","title":"공방 전령","position":"공방 전령","characterId":"K779","rank":"","commonTier":"T3","occupation":"호송·인명 장부 관리","gender":"남성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-김아호","detailRoute":"/people/person-0779","birthDate":"2088-06-16","birthday":"06-16","age":38,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"save-register","name":"위기 인명 장부 보존","rating":45},{"id":"departure","name":"배차표·출발 확인","rating":40}],"traits":[{"id":"save-ledgers-before-cargo","name":"화물보다 장부 구조","description":"김아호는 화물보다 인명 장부의 보존을 우선하는 성향을 보인다.","behavior":"호송 중 습격을 받자 화물보다 인명 장부부터 챙겼다.","stress":"습격과 당직 단절의 우려가 겹치면 기록을 잃지 않는 선택에 더 무게를 둘 수 있다.","relationship":"선배 당직과의 인계에서는 화물보다 먼저 지킨 인명 기록의 연속성을 중시할 수 있다.","effects":[]},{"id":"next-handover-accountability","name":"다음 인계 책임","description":"김아호는 지켜낸 인명 장부를 다음 당직으로 이어 넘기는 책임을 중시한다.","behavior":"자기 직위의 열쇠와 기록만 인계하며 장부가 끊기지 않도록 맡은 범위를 지킨다.","stress":"당직 공백이 통행의 종속으로 이어질까 우려되면 다음 인계의 누락을 더 경계할 수 있다.","relationship":"같은 생활권 선배 당직과는 맡은 기록을 정확히 이어 주는 책임을 통해 신뢰를 쌓으려 할 수 있다.","effects":[]}],"narrative":"호송 습격에서 인명 장부를 챙겼다. 기록을 선택한 행동이며 난입자를 제압했다고 쓰지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-43800-S04","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K779","stateId":"S04","politicalParentTitleId":"title:kingdom-s04","personalLieges":[{"holdingId":"holding:opening-duchy-43800-S04","directLiegePersonId":"K423"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"ae40-acbd-c8fc-91d1","name":"경주 김씨","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":5,"개방":20,"무력":-15,"물질":10,"공동":35,"원칙":20,"공개":-10,"자격":35,"분산":10,"변혁":0},"desire":{"갈망":20,"독점":-35,"위험":20,"과시":-10,"지속":5,"지향":"양성","결합":"다자"},"fields":{"소속":"Arc","생업":"호송·인명 장부 관리","품계":"교사","직함":"공방 전령","가치관":"권위 5 | 개방 20 | 무력 −15 | 물질 10 | 공동 35 | 원칙 20 | 공개 −10 | 자격 35 | 분산 10 | 변혁 0","욕망":"갈망 20 | 독점 −35 | 위험 20 | 과시 −10 | 지속 5 | 지향 양성 | 결합 다자"},"sections":{"생애":"2126년 세대. 김아호는 신내 환승 당직에서 자랐다. 김아호는 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 김아호의 공방 전령 업무는 성수2가3동과 연결된다.","관직":"김아호는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 김아호는 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.","관계":"김아호는 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"김아호는 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"김아호는 공방 전령 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"김아호는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"김아호는 당직을 끊지 않는 쪽을 먼저 고른다. 김아호는 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 호송·인명 장부 관리\n- 품계: 교사\n- 직함: 공방 전령\n**생애.** 2126년 세대. 김아호는 신내 환승 당직에서 자랐다. 김아호는 무표 출발 열차 저지로 공방 전령 자리를 맡았다.\n- 김아호의 공방 전령 업무는 성수2가3동과 연결된다.\n\n**관직.** 김아호는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 김아호는 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 공방 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 김아호는 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 김아호는 공방 전령 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 김아호는 공방 전령 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 김아호는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 5 | 개방 20 | 무력 −15 | 물질 10 | 공동 35 | 원칙 20 | 공개 −10 | 자격 35 | 분산 10 | 변혁 0\n- 욕망: 갈망 20 | 독점 −35 | 위험 20 | 과시 −10 | 지속 5 | 지향 양성 | 결합 다자\n:::","relations":{"outgoing":[],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0780', 'c774-c5f0-c548-674e', '{"id":"person-0780","name":"I Ka-seok","title":"Water Supply Herald","position":"Water Supply Herald","rank":"Sergeant","commonTier":"T5","occupation":"Pipeline Leak Inspection · Marking","gender":"Male","stage":"S4","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0780","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0780","name":"이카석","title":"급수 전령","position":"급수 전령","rank":"병장","commonTier":"T5","occupation":"관로 누수 점검·표시","gender":"남성","stage":"S4","state":"S05","stateName":"동방사","detailRoute":"/people/person-0780","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0781', 'bc15-bc00-c591', '{"id":"person-0781","name":"Bak Ha-yun","title":"Copy Herald","position":"Copy Herald","characterId":"K781","rank":"","commonTier":"T3","occupation":"Protecting the Convoy Casualty Ledger","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#person-bak-hayun","detailRoute":"/people/person-0781","birthDate":"2069-06-14","birthday":"06-14","age":57,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":5,"effective":5},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k781-escort-roster","name":"Escort roster preservation","rating":45}],"traits":[{"id":"k781-choice","name":"Life records despite attack","description":"Anecdote. In 2125, meeting a raid mid-convoy, he secured the roster of lives before the freight. By this deed the signature of the copy courier post rose into the ledger. A lasting disposition beyond this choice is unconfirmed.","behavior":"Anecdote. In 2125, meeting a raid mid-convoy, he secured the roster of lives before the freight. By this deed the signature of the copy courier post rose into the ledger.","stress":"Fear. That the copy courier duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k781-boundary","name":"Values duty continuity","description":"The source favors unbroken shifts and written records. Repeated wording does not establish a distinctive exceptional virtue.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the copy courier duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. The actual response is not yet recorded.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. In 2125, meeting a raid mid-convoy, he secured the roster of lives before the freight. By this deed the signature of the copy courier post rose into the ledger. Only one anecdote and repeated duty wording are available; enduring disposition, broader experience, and later results remain unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41570-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K781","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-41570-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":20,"Openness":-10,"Force":-20,"Material":-30,"Communal":15,"Principle":45,"Public":-5,"Eligibility":15,"Dispersed":-25,"Transformative":-50},"desire":{"Longing":50,"Monopoly":5,"Risk":-30,"Display":10,"Sustained":5,"Orientation":"Bisexual","Union":"Non-Exclusive"},"fields":{"Livelihood":"Protecting the Convoy Casualty Ledger","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Copy Herald","Values":"Authority 20 | Openness −10 | Force −20 | Material −30 | Communal 15 | Principle 45 | Publicity −5 | Credential 15 | Dispersal −25 | Transformation −50","Desires":"Longing 50 | Possessiveness 5 | Risk −30 | Display 10 | Endurance 5 | Orientation Bisexual | Bonding Non-exclusive"},"sections":{"Life":"Grew up on the Sinnae Transfer watch. The Copy Courier post opened up when the ticketless departing train was stopped.\n- Bak Hayun''s escort people-ledger protection duties are tied to Jongno 1·2·3·4-ga-dong.","Civil Servant Position and Grade":"A grade suited to a Seoul Metropolitan Government headquarters or office post, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duty: Copy Courier.","Anecdote":"In 2125, caught in an ambush during a convoy, secured the life ledger before the cargo. Because of this, the signature of the Copy Courier post was entered in the ledger.","Relationships":"Through the handover of the convoy life-ledger protection work, connected to senior duty staff in the same living sphere.","Ambition":"From the Copy Courier post, to carry on the records of convoy life-ledger protection so that the ledger of the Seoul Metropolitan Government Local Civil Service is not broken between duty shifts.","Fear":"That the Copy Courier duty will fall vacant, cutting the seals and rosters for downtown passage tied to the convoy life-ledger protection work, and halting even the ratification of the factions of the Seoul Metropolitan Government Local Civil Service that rely on those records.","Intervention":"Can appoint a witness to the duty handover of the convoy life-ledger protection work, or expose the empty key of that post."},"biography":"Even when ambushed, Bak Hayun secured the people ledger before the cargo. On watch, too, Bak Hayun chooses first to keep the records connected.\n\n- Livelihood: Escort people-ledger protection\n- Affiliation: Seoul Metropolitan Government local civil service organization\n- Position and grade: A grade suited to a post at the Seoul Metropolitan Government headquarters or project offices, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Duties: Copy Courier\n**Life.** Grew up on the Sinnae Transfer watch. The Copy Courier post opened up when the ticketless departing train was stopped.\n- Bak Hayun''s escort people-ledger protection duties are tied to Jongno 1·2·3·4-ga-dong.\n\n**Civil Service Position and Grade.** A grade suited to a post at the Seoul Metropolitan Government headquarters or project offices, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Copy Courier.\n\n**Anecdote.** In 2125, ambushed during an escort, Bak Hayun secured the people ledger before the cargo. Because of this, the Copy Courier post''s signature was entered in the ledger.\n\n**Relationships.** Through the handover of escort people-ledger protection duties, Bak Hayun is connected to a senior watch member of the same living sphere.\n\n**Ambition.** From the Copy Courier post, to keep the escort people-ledger protection records connected so that the ledgers of the Seoul Metropolitan Government local civil service organization are not broken between watches.\n\n**Fear.** That the Copy Courier watch falls vacant, cutting the seals and rosters for downtown passage tied to the escort people-ledger protection duties, and that even the approvals of the constituent groups of the Seoul Metropolitan Government local civil service organization, which rely on those records, come to a halt.\n\n**Intervention.** Bak Hayun can call a witness to a watch handover of the escort people-ledger protection duties, or expose an empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 20 | Openness −10 | Force −20 | Material −30 | Communal 15 | Principle 45 | Publicity −5 | Credential 15 | Dispersal −25 | Transformation −50\n- Desires: Longing 50 | Possessiveness 5 | Risk −30 | Display 10 | Endurance 5 | Orientation Bisexual | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Bak Ha-yun","type":"Contract","to":"Seop Do-yun","basis":"Bak Hayun passes to Seop Doyun the casualty ledger and copy that was protected during the escort. Seop Doyun conveys them to the Records Office and the council hall along with confirming testimony, so that human losses do not remain merely as cargo figures."}],"incoming":[]}}', '{"id":"person-0781","name":"박하윤","title":"사본 전령","position":"사본 전령","characterId":"K781","rank":"","commonTier":"T3","occupation":"호송 인명 장부 보호","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-박하윤","detailRoute":"/people/person-0781","birthDate":"2069-06-14","birthday":"06-14","age":57,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":3,"effective":3},"martial":{"base":5,"effective":5},"stewardship":{"base":5,"effective":5},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k781-escort-roster","name":"호송 장부 보전","rating":45}],"traits":[{"id":"k781-choice","name":"습격에도 인명 기록","description":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 이 선택을 넘어선 지속 성향은 미확인이다.","behavior":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","stress":"공포. 사본 전령 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k781-boundary","name":"당직 연속성을 중시","description":"당직 공백을 피하고 기록을 믿는 원문 성향이다. 반복 문구이므로 개인의 특별한 장점으로 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","stress":"공포. 사본 전령 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다. 단일 일화와 반복 당직 문구만 있어 장기 성향·광범위 경력·후속 결과는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-41570-S06","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K781","stateId":"S06","politicalParentTitleId":"title:kingdom-s06","personalLieges":[{"holdingId":"holding:opening-duchy-41570-S06","directLiegePersonId":"K144"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":20,"개방":-10,"무력":-20,"물질":-30,"공동":15,"원칙":45,"공개":-5,"자격":15,"분산":-25,"변혁":-50},"desire":{"갈망":50,"독점":5,"위험":-30,"과시":10,"지속":5,"지향":"양성","결합":"비독점"},"fields":{"생업":"호송 인명 장부 보호","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"사본 전령","가치관":"권위 20 | 개방 −10 | 무력 −20 | 물질 −30 | 공동 15 | 원칙 45 | 공개 −5 | 자격 15 | 분산 −25 | 변혁 −50","욕망":"갈망 50 | 독점 5 | 위험 −30 | 과시 10 | 지속 5 | 지향 양성 | 결합 비독점"},"sections":{"생애":"신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 박하윤의 호송 인명 장부 보호 업무는 종로1·2·3·4가동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.","일화":"2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.","관계":"호송 인명 장부 보호 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"사본 전령 자리에서 호송 인명 장부 보호 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"사본 전령 당직이 비어 호송 인명 장부 보호 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.","개입":"호송 인명 장부 보호 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"습격을 만났을 때도 화물보다 인명 장부를 챙겼다. 당직에서도 기록을 잇는 쪽을 먼저 고른다.\n\n- 생업: 호송 인명 장부 보호\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 사본 전령\n**생애.** 신내 환승 당직에서 자랐다. 사본 전령 자리는 무표 출발 열차 저지로 열렸다.\n- 박하윤의 호송 인명 장부 보호 업무는 종로1·2·3·4가동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 사본 전령.\n\n**일화.** 2125년 호송 도중 습격을 만나 화물보다 인명 장부부터 챙겼다. 이 일로 사본 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 호송 인명 장부 보호 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 사본 전령 자리에서 호송 인명 장부 보호 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**공포.** 사본 전령 당직이 비어 호송 인명 장부 보호 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.\n\n**개입.** 호송 인명 장부 보호 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 20 | 개방 −10 | 무력 −20 | 물질 −30 | 공동 15 | 원칙 45 | 공개 −5 | 자격 15 | 분산 −25 | 변혁 −50\n- 욕망: 갈망 50 | 독점 5 | 위험 −30 | 과시 10 | 지속 5 | 지향 양성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"박하윤","type":"계약","to":"섭도윤","basis":"박하윤은 호송에서 지킨 인명 장부와 사본을 섭도윤에게 전달한다. 섭도윤은 확인 증언과 함께 기록청·회의장에 전해 인명 손실이 화물 숫자로만 남지 않게 한다."}],"incoming":[]}}');
