INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0786', 'c724-d30c-d3c9', '{"id":"person-0786","name":"Yun San-u","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Male","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0786","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0786","name":"윤산우","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"사원","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"남성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0786","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0787', 'c7a5-d765-b355', '{"id":"person-0787","name":"Jang Da-won","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0787","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0787","name":"장다원","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0787","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0788', 'c784-d3c9-d0dd-6797', '{"id":"person-0788","name":"Im Ba-na","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K788","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-im-bana","detailRoute":"/people/person-0788","birthDate":"2101-09-17","birthday":"09-17","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"Payment ledger reconciliation","rating":50}],"traits":[{"id":"stated-priority","name":"Signs the wrong line correction","description":"A duplicate payment line was removed and the correction signed. Numerical reconciliation is clear, while the card does not establish sanitation scope.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A duplicate payment line was removed and the correction signed. Numerical reconciliation is clear, while the card does not establish sanitation scope.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-d3c9-d0dd-6797","name":"Pyeongtaek Im Clan","crest":"clan-crests/c784-d3c9-d0dd-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":35,"Force":-60,"Material":-20,"Communal":20,"Principle":70,"Public":20,"Eligibility":30,"Dispersed":20,"Transformative":-15},"desire":{"Longing":20,"Monopoly":-40,"Risk":-25,"Display":-20,"Sustained":15,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −30 | Openness 35 | Force −60 | Material −20 | Communal 20 | Principle 70 | Publicity 20 | Qualification 30 | Decentralization 20 | Transformation −15","Desires":"Craving 20 | Exclusivity −40 | Risk −25 | Display −20 | Endurance 15 | Orientation opposite-sex | Bonding non-exclusive"},"sections":{"Life":"Born on 2101-09-17. As of the 2126 opening, holds the post of Epidemic Control Records Officer, continuing the existing duty shifts and records. The succession record for that post opened with the deletion of one line from a double ledger.\n- Im Bana''s work reference point is the epidemic control records and duty-key handover window in Jegi-dong. This placement does not fix a residence, exact facility boundaries, a noble title, a fief, or tenure rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.","Relationships":"Im Bana hands the corrected quarantine ledger and the handover signature to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records to distinguish duplicated lines from actual patient movement.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first the option that keeps the duty watch unbroken. Trusts a single ledger line over loud talk.\n\n- Livelihood: epidemic control records and duty-key handover\n- Affiliation: White Cross Order\n- Rank: Trainee Physician\n- Title: Epidemic Control Records Officer\n**Life.** Born on 2101-09-17. As of the 2126 opening, holds the post of Epidemic Control Records Officer, continuing the existing duty shifts and records. The succession record for that post opened with the deletion of one line from a double ledger.\n- Im Bana''s work reference point is the epidemic control records and duty-key handover window in Jegi-dong. This placement does not fix a residence, exact facility boundaries, a noble title, a fief, or tenure rights.\n\n**Office.** Rank: Trainee Physician. Title: Epidemic Control Trainee Physician. Hands over only the keys and records of their own post, and writes in the ledger the time at which the handed-over keys and records were received.\n\n**Anecdote.** In 2125, cross-checked the double-payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.\n\n**Relationships.** Im Bana passes the corrected epidemic control ledger and the receipt signature to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records and distinguishes duplicated lines from actual patient movements.\n\n**Ambition.** From the position of Epidemic Control Trainee Physician, to keep the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** Fears that if the Epidemic Control Trainee Physician''s duty shift goes empty, the White Cross Order''s passage will become a hostage to Seoul''s internal patron factions.\n\n**Intervention.** Can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 35 | Force −60 | Material −20 | Communal 20 | Principle 70 | Publicity 20 | Qualification 30 | Decentralization 20 | Transformation −15\n- Desires: Craving 20 | Exclusivity −40 | Risk −25 | Display −20 | Endurance 15 | Orientation opposite-sex | Bonding non-exclusive\n:::","relations":{"outgoing":[{"from":"Im Ba-na","type":"Contract","to":"Ra Seyeong","basis":"Im Bana hands the corrected quarantine ledger and the handover signature to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records to distinguish duplicated lines from actual patient movement."}],"incoming":[]}}', '{"id":"person-0788","name":"임바나","title":"방역 기록관","position":"방역 기록관","characterId":"K788","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-임바나","detailRoute":"/people/person-0788","birthDate":"2101-09-17","birthday":"09-17","age":25,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"지급 장부 대조","rating":50}],"traits":[{"id":"stated-priority","name":"틀린 한 줄을 서명한다","description":"이중 지급 줄을 지우고 정정에 서명했다. 숫자 대조는 분명하지만 방역 실무의 범위는 짧은 카드로 확정할 수 없다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"이중 지급 줄을 지우고 정정에 서명했다. 숫자 대조는 분명하지만 방역 실무의 범위는 짧은 카드로 확정할 수 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c784-d3c9-d0dd-6797","name":"평택 임씨","crest":"clan-crests/c784-d3c9-d0dd-6797.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":35,"무력":-60,"물질":-20,"공동":20,"원칙":70,"공개":20,"자격":30,"분산":20,"변혁":-15},"desire":{"갈망":20,"독점":-40,"위험":-25,"과시":-20,"지속":15,"지향":"이성","결합":"비독점"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −30 | 개방 35 | 무력 −60 | 물질 −20 | 공동 20 | 원칙 70 | 공개 20 | 자격 30 | 분산 20 | 변혁 −15","욕망":"갈망 20 | 독점 −40 | 위험 −25 | 과시 −20 | 지속 15 | 지향 이성 | 결합 비독점"},"sections":{"생애":"2101-09-17에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 임바나의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"임바나는 정정한 방역 장부와 인수 서명을 라세영에게 넘긴다. 라세영은 격리 출입과 해제 기록을 확인해 중복된 줄을 실제 환자 이동과 구분한다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2101-09-17에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 임바나의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 임바나는 정정한 방역 장부와 인수 서명을 라세영에게 넘긴다. 라세영은 격리 출입과 해제 기록을 확인해 중복된 줄을 실제 환자 이동과 구분한다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 35 | 무력 −60 | 물질 −20 | 공동 20 | 원칙 70 | 공개 20 | 자격 30 | 분산 20 | 변혁 −15\n- 욕망: 갈망 20 | 독점 −40 | 위험 −25 | 과시 −20 | 지속 15 | 지향 이성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"임바나","type":"계약","to":"라세영","basis":"임바나는 정정한 방역 장부와 인수 서명을 라세영에게 넘긴다. 라세영은 격리 출입과 해제 기록을 확인해 중복된 줄을 실제 환자 이동과 구분한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0789', 'd55c-ccad-c8fc', '{"id":"person-0789","name":"Han Ga-seo","title":"Quarantine Clerk","position":"Guui Garrison Quarantine Clerk","rank":"Garrison Soldier","commonTier":"T5","occupation":"Quarantine Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0789","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0789","name":"한가서","title":"검역 서기","position":"구의수비대 검역 서기","rank":"수비대원","commonTier":"T5","occupation":"검역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0789","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0790', 'c624-d574-c8fc', '{"id":"person-0790","name":"O Ra-seo","title":"Auction Clerk","position":"Myeongdong Station Election Records Clerk","rank":"Congregationioner","commonTier":"T5","occupation":"Election Records and Handover Log","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0790","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0790","name":"오라서","title":"경매 서기","position":"명동역 선거 기록 서기","rank":"교우","commonTier":"T5","occupation":"선거 기록·인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0790","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0791', 'c11c-b2ec-c131', '{"id":"person-0791","name":"Seo Sa-seo","title":"Audit Recorder","position":"Audit Recorder","characterId":"K791","rank":"Unregistered","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#inmul-seosaseo","detailRoute":"/people/person-0791","birthDate":"2092-08-31","birthday":"08-31","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"audit-access-custody","name":"Audit access custody","rating":60}],"traits":[{"id":"evidenced-choice","name":"Withholds closure before public review","description":"Locks the original audit until public review is scheduled and marks outage fields separately on the copy. No authority or achievement beyond these actions is granted.","behavior":"The recorded choice shows this disposition within its context; it is not established for every situation.","stress":"May recheck originals and handovers when shifts are blocked or records disappear.","relationship":"Hands keys and records to the next duty worker and watches for factional obstruction.","effects":[]},{"id":"handover-continuity","name":"Concern for record continuity","description":"Seeks continuity of the specific records entrusted to this person, rather than new authority.","behavior":"Seeks to check the continuity of assigned records and signatures.","stress":"Loss of the assigned records or a blocked handover may heighten concern about accountability.","relationship":"Hands keys and records to the next duty worker and watches for factional obstruction.","effects":[]}],"narrative":"Locks the original audit until public review is scheduled and marks outage fields separately on the copy. No authority or achievement beyond these actions is granted.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":35,"Force":-20,"Material":-5,"Communal":15,"Principle":40,"Public":25,"Eligibility":25,"Dispersed":45,"Transformative":0},"desire":{"Longing":30,"Monopoly":40,"Risk":20,"Display":-40,"Sustained":20,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Audit Log and Duty Key Handover","Affiliation":"Arc","Community Role":"Guild Member","Duty":"Audit Recorder","Values":"Authority −25 | Openness 35 | Force −20 | Material −5 | Communal 15 | Principle 40 | Publicity 25 | Qualification 25 | Decentralization 45 | Transformation 0","Desires":"Craving 30 | Exclusivity 40 | Risk 20 | Display −40 | Endurance 20 | Orientation same-sex | Bonding contract cohabitation"},"sections":{"Life":"Born on 2092-08-31, Seo Saseo works as an Audit Records Officer at the Sicheong Station union workshop in the Permanent Winter. Checks the records of direct elections by union members and public votes, and distinguishes offices conferred by the Government from community duties.\n- Seo Saseo works as an Audit Records Officer at the Sicheong Station union workshop in Sogong-dong. This work reference point does not fix a residence, exact facility boundaries, a noble title, a fief, or tenure rights.","Duty":"The community role is union member, and the duty is Audit Records Officer. This duty is an internal function of the Jeongdong General Labor Federation, not The Government civil service office or a feudal rank.","Anecdote":"An audit sheet on which Gwak Eunjae wrote the water-supply interruption times and convoy delays on a single page awaits the closing stamp. Seo Saseo keeps the original audit sheet locked in the records cabinet until the public review by the Union Members'' Election Management Council is scheduled, and separately marks the water-cutoff time column on the copy to be spread out at the review.","Relationships":"Seo Saseo''s existing relationship records are as follows. Bound by duty shifts and handovers with a senior in the same work and living sphere.","Goals":"Seo Saseo seeks to keep the signing, handover, and public procedures of the Audit Records Officer''s work verifiable in the Sicheong Station union ledger.","Fear":"That the signatures or handover records of the Audit Records Officer''s work will be altered, so that Seo Saseo''s scope of responsibility and the union members'' public procedures collapse together.","Intervention":"Seo Saseo can cross-check the relevant signatures and handover times and make the records public, but cannot confer new offices, ranks, rights, or fiefs."},"biography":"In the Permanent Winter, at the Sicheong Station union workshop, Seo Saseo first cross-checks the Audit Records Officer''s work records against the public vote signatures. On days when water supply, passage, and contract schedules overlap, receipt times and handover order are entered in the same ledger.\n\n- Livelihood: audit records and duty-key handover\n- Affiliation: Arc\n- Community role: union member\n- Duty: Audit Records Officer\n**Life.** Born on 2092-08-31, Seo Saseo works as an Audit Records Officer at the Sicheong Station union workshop in the Permanent Winter. Checks the records of direct elections by union members and public votes, and distinguishes offices conferred by the Government from community duties.\n- Seo Saseo works as an Audit Records Officer at the Sicheong Station union workshop in Sogong-dong. This work reference point does not fix a residence, exact facility boundaries, a noble title, a fief, or tenure rights.\n\n**Duty.** The community role is union member, and the duty is Audit Records Officer. This duty is an internal function of the Jeongdong Labor Federation and is neither a civil service office of the Government of the Republic of Korea nor a feudal rank.\n\n**Anecdote.** An audit sheet on which Gwak Eunjae wrote the water-supply interruption times and convoy delays on a single page awaits the closing stamp. Seo Saseo keeps the original audit sheet locked in the records cabinet until the public review by the Union Members'' Election Management Council is scheduled, and separately marks the water-cutoff time column on the copy to be spread out at the review.\n\n**Relationships.** Seo Saseo''s existing relationship records are as follows. Bound by duty shifts and handovers with a senior in the same work and living sphere.\n\n**Goal.** Seo Saseo seeks to keep the signing, handover, and public procedures of the Audit Records Officer''s work verifiable in the Sicheong Station union ledger.\n\n**Fear.** That the signatures or handover records of the Audit Records Officer''s work will be altered, so that Seo Saseo''s scope of responsibility and the union members'' public procedures collapse together.\n\n**Intervention.** Seo Saseo can cross-check the relevant signatures and handover times and make the records public, but cannot confer new offices, ranks, rights, or fiefs.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 35 | Force −20 | Material −5 | Communal 15 | Principle 40 | Publicity 25 | Qualification 25 | Decentralization 45 | Transformation 0\n- Desires: Craving 30 | Exclusivity 40 | Risk 20 | Display −40 | Endurance 20 | Orientation same-sex | Bonding contract cohabitation\n:::","relations":{"outgoing":[{"from":"Seo Sa-seo","type":"Contract","to":"Gwak Eunjae","basis":"The Chronicle informs Gwak Eunjae of the storage status of audit slips awaiting public review and of the water-cutoff time slots it has marked. Gwak Eunjae checks the review copy so that no closing seal is stamped before public confirmation."}],"incoming":[]}}', '{"id":"person-0791","name":"서사서","title":"감사 기록관","position":"감사 기록관","characterId":"K791","rank":"미등록","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-16#인물-서사서","detailRoute":"/people/person-0791","birthDate":"2092-08-31","birthday":"08-31","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":11,"effective":11},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"audit-access-custody","name":"감사 열람 보관","rating":60}],"traits":[{"id":"evidenced-choice","name":"공개 열람 전 종결 보류","description":"공개 열람이 잡힐 때까지 감사 원본을 잠그고 사본에 단수 칸을 따로 표시했다. 확인된 행동 범위를 넘는 권한과 성과는 부여하지 않는다.","behavior":"확인된 선택에서는 공개 열람 전 종결 보류을 드러낸다. 다른 상황까지 불변 성향으로 확정하지 않는다.","stress":"교대가 막히거나 기록이 사라지면 원본과 인계를 재확인할 수 있다.","relationship":"다음 당직에게 열쇠와 기록을 넘기며 파벌의 인계 방해를 경계한다.","effects":[]},{"id":"handover-continuity","name":"기록 단절 경계","description":"감사 기록관 자리에서 시청역 조합 장부를 끊기지 않게 잇고, 작업장 파벌이 갈려도 조합원 전원의 위원장 직접선거 결과를 지킨다.","behavior":"맡은 기록과 서명의 연결을 확인하려 한다.","stress":"감사 기록관 당직이 비고 선거 파벌이 인수인계를 가로막아 Arc의 통행이 강국 볼모가 되는 것.","relationship":"다음 당직에게 열쇠와 기록을 넘기며 파벌의 인계 방해를 경계한다.","effects":[]}],"narrative":"공개 열람이 잡힐 때까지 감사 원본을 잠그고 사본에 단수 칸을 따로 표시했다. 확인된 행동 범위를 넘는 권한과 성과는 부여하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":35,"무력":-20,"물질":-5,"공동":15,"원칙":40,"공개":25,"자격":25,"분산":45,"변혁":0},"desire":{"갈망":30,"독점":40,"위험":20,"과시":-40,"지속":20,"지향":"동성","결합":"계약동거"},"fields":{"생업":"감사 기록·당직 열쇠 인계","소속":"Arc","공동체 역할":"조합원","직무":"감사 기록관","가치관":"권위 −25 | 개방 35 | 무력 −20 | 물질 −5 | 공동 15 | 원칙 40 | 공개 25 | 자격 25 | 분산 45 | 변혁 0","욕망":"갈망 30 | 독점 40 | 위험 20 | 과시 −40 | 지속 20 | 지향 동성 | 결합 계약동거"},"sections":{"생애":"2092-08-31에 태어난 서사서는 영구 겨울의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 서사서는 소공동의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 정하지 않는다.","직무":"공동체 역할은 조합원이며 직무는 감사 기록관이다. 이 직무는 Arc 내부 기능이고 대한민국 정부 공무원 관직이나 봉건 품계가 아니다.","일화":"곽은재가 급수 중단 시간과 호송 지연을 한 장에 적은 감사표가 종결 도장을 기다린다. 서사서는 조합원 선거관리회의 공개 열람이 잡힐 때까지 감사표 원본을 기록함에 잠가 두고, 열람 때 펼칠 사본에는 단수 시간 칸을 따로 표시한다.","관계":"서사서의 기존 관계 기록은 다음과 같다. 같은 업무·생활권 선배 당직과 인수인계로 묶인다.","목표":"서사서는 감사 기록관 업무의 서명·인계·공개 절차를 시청역 조합 장부에서 검증 가능하게 유지하려 한다.","공포":"감사 기록관 업무의 서명이나 인계 기록이 바뀌어 서사서의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.","개입":"서사서는 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다."},"biography":"서사서는 영구 겨울의 시청역 조합 작업장에서 감사 기록관 업무 기록과 공개 표결 서명을 먼저 대조한다. 급수·통행·계약 일정이 겹치는 날에는 접수 시각과 인계 순서를 같은 장부에 남긴다.\n\n- 생업: 감사 기록·당직 열쇠 인계\n- 소속: Arc\n- 공동체 역할: 조합원\n- 직무: 감사 기록관\n**생애.** 2092-08-31에 태어난 서사서는 영구 겨울의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 조합원 직접선거와 공개 표결 기록을 확인하며 대한민국 정부가 수여하는 관직과 공동체 직무를 구분한다.\n- 서사서는 소공동의 시청역 조합 작업장에서 감사 기록관 업무를 맡는다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 정하지 않는다.\n\n**직무.** 공동체 역할은 조합원이며 직무는 감사 기록관이다. 이 직무는 Arc 내부 기능이고 대한민국 정부 공무원 관직이나 봉건 품계가 아니다.\n\n**일화.** 곽은재가 급수 중단 시간과 호송 지연을 한 장에 적은 감사표가 종결 도장을 기다린다. 서사서는 조합원 선거관리회의 공개 열람이 잡힐 때까지 감사표 원본을 기록함에 잠가 두고, 열람 때 펼칠 사본에는 단수 시간 칸을 따로 표시한다.\n\n**관계.** 서사서의 기존 관계 기록은 다음과 같다. 같은 업무·생활권 선배 당직과 인수인계로 묶인다.\n\n**목표.** 서사서는 감사 기록관 업무의 서명·인계·공개 절차를 시청역 조합 장부에서 검증 가능하게 유지하려 한다.\n\n**공포.** 감사 기록관 업무의 서명이나 인계 기록이 바뀌어 서사서의 책임 범위와 조합원 공개 절차가 함께 무너지는 것.\n\n**개입.** 서사서는 관련 서명과 인계 시각을 대조하고 기록을 공개할 수 있지만 새 관직·품계·권리·영지를 부여할 수는 없다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 35 | 무력 −20 | 물질 −5 | 공동 15 | 원칙 40 | 공개 25 | 자격 25 | 분산 45 | 변혁 0\n- 욕망: 갈망 30 | 독점 40 | 위험 20 | 과시 −40 | 지속 20 | 지향 동성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"서사서","type":"계약","to":"곽은재","basis":"서사서는 공개 열람을 기다리는 감사표의 보관 상태와 표시한 단수 시간 칸을 곽은재에게 알린다. 곽은재는 열람 사본을 확인해 공개 확인 전 종결 도장이 찍히지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0792', 'c2e0-d3c9-c0b0', '{"id":"person-0792","name":"Sin Cha-min","title":"Conduit Surveyor","position":"Conduit Surveyor","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Male","stage":"S4","state":"S01","stateName":"The Sluice","detailRoute":"/people/person-0792","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0792","name":"신차민","title":"관로 탐사원","position":"관로 탐사원","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"남성","stage":"S4","state":"S01","stateName":"수문국","detailRoute":"/people/person-0792","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
