INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0795', 'c548-c21c-d765', '{"id":"person-0795","name":"An Namneul","title":"Parts Logistics Merchant","position":"Parts Logistics Merchant","characterId":"K795","rank":"","commonTier":"T3","occupation":"Wheel & Pump Maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-annamneul","detailRoute":"/people/person-0795","birthDate":"2096-09-23","birthday":"09-23","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"wheel","name":"Wheel-defect inspection","rating":50},{"id":"handover","name":"Record and key handover","rating":40}],"traits":[{"id":"stop-for-wheel-defects","name":"Stop for Wheel Defects","description":"An Namneul shows a disposition to prioritize stopping over continued movement when a wheel defect is detected.","behavior":"He detected a wheel defect by touch and stopped the train just before derailment.","stress":"If continued operation conflicts with addressing a defect, he may choose to stop first to protect passage.","relationship":"During handover to senior duty staff, he may emphasize the wheel defect he detected and the resulting stop.","effects":[]},{"id":"no-invented-authority","name":"No Invented Authority","description":"An Namneul maintains a boundary against claiming powers his position does not grant, even when addressing defects.","behavior":"He transfers only his position’s keys and records without treating defect detection as a source of additional authority.","stress":"Even if he fears a duty gap, he may seek continuity within his remit rather than expand his authority.","relationship":"With senior duty staff, he may favor clear boundaries around which keys and records he can transfer.","effects":[]}],"narrative":"He detected a wheel defect by touch and stopped a train. Narrow inspection is supported; a parts trader’s transaction history is absent.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:barony-gu-41131-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41131-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41133-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41133-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41135-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41135-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41461-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41461-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41463-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41463-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41465-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41465-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-43111-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43111-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43112-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43112-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43113-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43113-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43114-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43114-S04","directLiegePersonId":"K108"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-5,"Openness":20,"Force":-25,"Material":35,"Communal":40,"Principle":0,"Public":-10,"Eligibility":40,"Dispersed":25,"Transformative":-10},"desire":{"Longing":0,"Monopoly":-40,"Risk":-30,"Display":25,"Sustained":5,"Orientation":"Fluid","Union":"Monogamy"},"fields":{"Affiliation":"Arc","Livelihood":"Wheel & Pump Maintenance","Rank":"Teacher","Title":"Parts Logistics Merchant","Values":"Authority −5 | Openness 20 | Force −25 | Material 35 | Communal 40 | Principle 0 | Publicity −10 | Qualification 40 | Decentralization 25 | Transformation −10","Desires":"Craving 0 | Monopoly −40 | Risk −30 | Display 25 | Persistence 5 | Orientation Fluid | Bonding Monogamous"},"sections":{"Life":"Generation of 2126. An Namneul grew up at the Sinjeong Depot. An Namneul took the Parts Logistics Steward post after reporting a defect just before a derailment.\n- An Namneul''s Parts Logistics Steward duties are tied to Seongsu 2-ga 1-dong.","Offices":"An Namneul hands over only the keys and records that come with the post. They do not invent authority they do not hold.","Anecdote":"In 2125, An Namneul caught a wheel defect just before a derailment on the stabling siding and stopped the train. Because of this, the signature for the Parts Logistics Steward post was entered in the ledger.","Relationships":"An Namneul is bound by handover to a senior duty officer from the same living sphere.","Ambition":"As Parts Logistics Steward on duty, An Namneul wants to keep the Arc''s ledger unbroken.","Fear":"An Namneul fears that if the Parts Logistics Steward duty post falls vacant, the Arc''s passage will become a hostage of the great powers.","Intervention":"An Namneul can bring in a witness for a duty handover or expose an empty key."},"biography":"An Namneul chooses first not to break the duty chain. An Namneul trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Arc\n- Livelihood: Wheel and pump maintenance\n- Rank: Instructor\n- Title: Parts Logistics Steward\n**Life.** Generation of 2126. An Namneul grew up at the Sinjeong Depot. An Namneul took the Parts Logistics Steward post after reporting a defect just before a derailment.\n- An Namneul''s Parts Logistics Steward duties are tied to Seongsu 2-ga 1-dong.\n\n**Office.** An Namneul hands over only the keys and records that come with the post. They do not invent authority they do not hold.\n\n**Anecdote.** In 2125, An Namneul caught a wheel defect just before a derailment on the stabling siding and stopped the train. Because of this, the signature for the Parts Logistics Steward post was entered in the ledger.\n\n**Relationships.** An Namneul is bound by handover to a senior duty officer from the same living sphere.\n\n**Ambition.** As Parts Logistics Steward on duty, An Namneul wants to keep the Arc''s ledger unbroken.\n\n**Fear.** An Namneul fears that if the Parts Logistics Steward duty post falls vacant, the Arc''s passage will become a hostage of the great powers.\n\n**Intervention.** An Namneul can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −5 | Openness 20 | Force −25 | Material 35 | Communal 40 | Principle 0 | Publicity −10 | Qualification 40 | Decentralization 25 | Transformation −10\n- Desires: Craving 0 | Monopoly −40 | Risk −30 | Display 25 | Persistence 5 | Orientation Fluid | Bonding Monogamous\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0795","name":"안남늘","title":"부품 물류상","position":"부품 물류상","characterId":"K795","rank":"","commonTier":"T3","occupation":"차륜·펌프 정비","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-안남늘","detailRoute":"/people/person-0795","birthDate":"2096-09-23","birthday":"09-23","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":10,"effective":10},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"wheel","name":"차륜 결함 점검","rating":50},{"id":"handover","name":"기록·열쇠 인수인계","rating":40}],"traits":[{"id":"stop-for-wheel-defects","name":"바퀴 결함에 정지","description":"안남늘은 바퀴의 실제 결함을 확인하면 운행보다 정지를 우선하는 성향을 보인다.","behavior":"탈선 직전 바퀴 결함을 손으로 감지해 열차를 세웠다.","stress":"운행 지속과 결함 대응이 충돌하면 통행을 지키기 위해 먼저 멈추는 선택을 할 수 있다.","relationship":"선배 당직에게 인계할 때 자신이 확인한 바퀴 결함과 정지 사실을 중요하게 전달할 수 있다.","effects":[]},{"id":"no-invented-authority","name":"없는 권한 만들지 않기","description":"안남늘은 결함에 대응하더라도 자기 직위에 없는 권한을 내세우지 않는 태도를 지닌다.","behavior":"자기 직위의 열쇠와 기록만 넘기며 결함 발견을 근거로 별도의 권한을 만들어 내지 않는다.","stress":"당직 공백이 두려워도 대응 범위를 넓히기보다 맡은 권한 안에서 연속성을 지키려 할 수 있다.","relationship":"선배 당직과는 넘길 수 있는 열쇠와 기록의 범위를 분명히 하는 관계를 선호할 수 있다.","effects":[]}],"narrative":"탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 점검의 좁은 강점이며 부품 상인의 거래 이력은 원문에 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:barony-gu-41131-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41131-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41133-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41133-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41135-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41130-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41135-S04","directLiegePersonId":"K090"}],"directOwnership":false},{"id":"title:barony-gu-41461-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41461-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41463-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41463-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-41465-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-41460-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-41465-S04","directLiegePersonId":"K086"}],"directOwnership":false},{"id":"title:barony-gu-43111-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43111-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43112-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43112-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43113-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43113-S04","directLiegePersonId":"K108"}],"directOwnership":false},{"id":"title:barony-gu-43114-S04","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K795","stateId":"S04","politicalParentTitleId":"title:duchy-43110-S04","personalLieges":[{"holdingId":"holding:opening-barony-gu-43114-S04","directLiegePersonId":"K108"}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"순흥 안씨","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-5,"개방":20,"무력":-25,"물질":35,"공동":40,"원칙":0,"공개":-10,"자격":40,"분산":25,"변혁":-10},"desire":{"갈망":0,"독점":-40,"위험":-30,"과시":25,"지속":5,"지향":"유동","결합":"단혼"},"fields":{"소속":"Arc","생업":"차륜·펌프 정비","품계":"교사","직함":"부품 물류상","가치관":"권위 −5 | 개방 20 | 무력 −25 | 물질 35 | 공동 40 | 원칙 0 | 공개 −10 | 자격 40 | 분산 25 | 변혁 −10","욕망":"갈망 0 | 독점 −40 | 위험 −30 | 과시 25 | 지속 5 | 지향 유동 | 결합 단혼"},"sections":{"생애":"2126년 세대. 안남늘은 신정 차량기지에서 자랐다. 안남늘은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 안남늘의 부품 물류상 업무는 성수2가1동과 연결된다.","관직":"안남늘은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 안남늘은 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.","관계":"안남늘은 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"안남늘은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"안남늘은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"안남늘은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"안남늘은 당직을 끊지 않는 쪽을 먼저 고른다. 안남늘은 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 차륜·펌프 정비\n- 품계: 교사\n- 직함: 부품 물류상\n**생애.** 2126년 세대. 안남늘은 신정 차량기지에서 자랐다. 안남늘은 탈선 직전 결함 보고로 부품 물류상 자리를 맡았다.\n- 안남늘의 부품 물류상 업무는 성수2가1동과 연결된다.\n\n**관직.** 안남늘은 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 안남늘은 유치선 탈선 직전 바퀴 결함을 만져내 열차를 세웠다. 이 일로 부품 물류상 자리의 서명이 장부에 올랐다.\n\n**관계.** 안남늘은 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 안남늘은 부품 물류상 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 안남늘은 부품 물류상 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 안남늘은 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −5 | 개방 20 | 무력 −25 | 물질 35 | 공동 40 | 원칙 0 | 공개 −10 | 자격 40 | 분산 25 | 변혁 −10\n- 욕망: 갈망 0 | 독점 −40 | 위험 −30 | 과시 25 | 지속 5 | 지향 유동 | 결합 단혼\n:::","relations":{"outgoing":[],"incoming":[]}}');
