INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0802', 'bc30-c131-c8fc', '{"id":"person-0802","name":"Bae Bamin","title":"Wheel Technician","position":"Seongha Electronics Wheel Technician","rank":"Employee","commonTier":"T5","occupation":"Seongha Electronics Wheel Maintenance Records & Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0802","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0802","name":"배바민","title":"차륜 정비사","position":"성하전자 차륜 정비사","rank":"사원","commonTier":"T5","occupation":"성하전자 차륜 정비 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0802","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0803', 'bc31-c218-c6d0', '{"id":"person-0803","name":"Baek Jaseok","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0803","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0803","name":"백자석","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0803","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0804', 'd5c8-d558-c591-8a31', '{"id":"person-0804","name":"Heo Tau","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Logistics Merchant","characterId":"K804","rank":"Resident","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#Person-Heo-Tau","detailRoute":"/people/person-0804","birthDate":"2087-10-04","birthday":"10-04","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"home-visits-during-isolation","name":"Home visits during isolation","rating":50}],"traits":[{"id":"stated-priority","name":"Isolation without ending visits","description":"A suspected infectious patient was isolated while home visits continued. Care and handover orientation are evaluated without extending them to broad supply expertise.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A suspected infectious patient was isolated while home visits continued. Care and handover orientation are evaluated without extending them to broad supply expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d558-c591-8a31","name":"Hayang Heo Clan","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-10,"Openness":35,"Force":-55,"Material":-5,"Communal":20,"Principle":25,"Public":15,"Eligibility":20,"Dispersed":15,"Transformative":-15},"desire":{"Longing":45,"Monopoly":-30,"Risk":25,"Display":-20,"Sustained":20,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −10 | Openness 35 | Force −55 | Material −5 | Communal 20 | Principle 25 | Publicity 15 | Qualification 20 | Decentralization 15 | Transformation −15","Desires":"Craving 45 | Monopoly −30 | Risk 25 | Display −20 | Persistence 20 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Born on 2087-10-04. As of the 2126 opening, holds the Medicinal Herb Logistics Steward post and carries on the existing duty and records. In that post''s succession record, it opened with a counterfeit-medicine seal.\n- The medicinal herb management records and duty key handover desk in Jegi-dong is taken as Heo Tau''s reference point for work. This placement does not fix a residence, exact facility boundaries, a title of nobility, a fief, or possession rights.","Offices":"Rank: Resident. Title: Medicinal Herb Management Resident. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, kept a suspected-contagion patient in an isolation compartment and never stopped making house calls. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Heo Tau hands the custody records of the herbs for quarantined patients to Dong Juha. Dong Juha checks origin, drying date, and the treatment assignment seal, and inspects the supply needed for house calls.","Ambition":"From the post of Medicinal Herb Management Resident, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that if the Medicinal Herb Management Resident''s watch falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty chain. Trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Medicinal herb management records and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident Physician\n- Title: Medicinal Herb Logistics Steward\n**Life.** Born on 2087-10-04. As of the 2126 opening, holds the Medicinal Herb Logistics Steward post and carries on the existing duty and records. In that post''s succession record, it opened with a counterfeit-medicine seal.\n- The medicinal herb management records and duty key handover desk in Jegi-dong is taken as Heo Tau''s reference point for work. This placement does not fix a residence, exact facility boundaries, a title of nobility, a fief, or possession rights.\n\n**Office.** Rank: resident physician. Title: Medicinal Herb Management Resident. Hands over only the keys and records of their own post, and writes in the ledger the time the handed-over keys and records were received.\n\n**Anecdote.** In 2125, placed a suspected contagious patient in an isolation compartment and did not stop making house calls. That day''s record remained as the handover basis for the next duty officer to verify.\n\n**Relationships.** Heo Tau hands the management records of the medicinal herbs to be used for the quarantined patient to Dong Juha. Dong Juha checks the origin, drying date, and the treatment-assignment seal, and inspects the supply needed for house calls.\n\n**Ambition.** From the Medicinal Herb Management Resident post, to keep the White Cross Order''s ledger unbroken.\n\n**Fear.** Fears that if the Medicinal Herb Management Resident duty post falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron forces.\n\n**Intervention.** Can bring in a witness for a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −10 | Openness 35 | Force −55 | Material −5 | Communal 20 | Principle 25 | Publicity 15 | Qualification 20 | Decentralization 15 | Transformation −15\n- Desires: Craving 45 | Monopoly −30 | Risk 25 | Display −20 | Persistence 20 | Orientation Fluid | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Heo Tau","type":"Contract","to":"Dong Juha","basis":"Heo Tau hands the custody records of the herbs for quarantined patients to Dong Juha. Dong Juha checks origin, drying date, and the treatment assignment seal, and inspects the supply needed for house calls."}],"incoming":[]}}', '{"id":"person-0804","name":"허타우","title":"약재 물류상","position":"약재 물류상","characterId":"K804","rank":"수련의","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-허타우","detailRoute":"/people/person-0804","birthDate":"2087-10-04","birthday":"10-04","age":39,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"home-visits-during-isolation","name":"격리 중 왕진","rating":50}],"traits":[{"id":"stated-priority","name":"진료를 끊지 않는 격리","description":"전염 의심 환자를 격리하면서 왕진을 계속했다. 이 치료 행동과 인계 지향만 평가하고 약재 관리 전반의 실력은 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"전염 의심 환자를 격리하면서 왕진을 계속했다. 이 치료 행동과 인계 지향만 평가하고 약재 관리 전반의 실력은 확대하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"d5c8-d558-c591-8a31","name":"하양 허씨","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-10,"개방":35,"무력":-55,"물질":-5,"공동":20,"원칙":25,"공개":15,"자격":20,"분산":15,"변혁":-15},"desire":{"갈망":45,"독점":-30,"위험":25,"과시":-20,"지속":20,"지향":"유동","결합":"비독점"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"약재 물류상","가치관":"권위 −10 | 개방 35 | 무력 −55 | 물질 −5 | 공동 20 | 원칙 25 | 공개 15 | 자격 20 | 분산 15 | 변혁 −15","욕망":"갈망 45 | 독점 −30 | 위험 25 | 과시 −20 | 지속 20 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2087-10-04에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 허타우의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 전염 의심 환자를 격리 칸에 두고 왕진을 멈추지 않았다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"허타우는 격리 환자에게 쓸 약재의 관리 기록을 동주하에게 넘긴다. 동주하는 원산지·건조 일자와 진료 배정 날인을 확인해 왕진에 필요한 공급을 검수한다.","야망":"약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 약재 물류상\n**생애.** 2087-10-04에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 허타우의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 전염 의심 환자를 격리 칸에 두고 왕진을 멈추지 않았다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 허타우는 격리 환자에게 쓸 약재의 관리 기록을 동주하에게 넘긴다. 동주하는 원산지·건조 일자와 진료 배정 날인을 확인해 왕진에 필요한 공급을 검수한다.\n\n**야망.** 약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −10 | 개방 35 | 무력 −55 | 물질 −5 | 공동 20 | 원칙 25 | 공개 15 | 자격 20 | 분산 15 | 변혁 −15\n- 욕망: 갈망 45 | 독점 −30 | 위험 25 | 과시 −20 | 지속 20 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"허타우","type":"계약","to":"동주하","basis":"허타우는 격리 환자에게 쓸 약재의 관리 기록을 동주하에게 넘긴다. 동주하는 원산지·건조 일자와 진료 배정 날인을 확인해 왕진에 필요한 공급을 검수한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0805', 'c720-ac15-b989', '{"id":"person-0805","name":"Yu Geumyeong","title":"Outpost Courier","position":"Agwansa Outpost Courier","rank":"Sergeant","commonTier":"T5","occupation":"Outpost Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0805","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0805","name":"유금영","title":"초소 전령","position":"아관사 초소 전령","rank":"병장","commonTier":"T5","occupation":"초소 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0805","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
