INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0819', 'c774-c804-c758-674e', '{"id":"person-0819","name":"I Bungmin","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0819","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0819","name":"이북민","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0819","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0820', 'bc15-bc00-c591', '{"id":"person-0820","name":"Bak Byeoryun","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K820","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-Bak-Byeoryun","detailRoute":"/people/person-0820","birthDate":"2094-06-14","birthday":"06-14","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"Public desk referral","rating":40}],"traits":[{"id":"stated-priority","name":"Public desk before private requests","description":"The episode redirects a private request to the public desk. That procedural choice is visible; prescribing outcomes and large-scale negotiation are unconfirmed.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The episode redirects a private request to the public desk. That procedural choice is visible; prescribing outcomes and large-scale negotiation are unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-30,"Openness":30,"Force":-45,"Material":-25,"Communal":20,"Principle":35,"Public":20,"Eligibility":15,"Dispersed":20,"Transformative":0},"desire":{"Longing":10,"Monopoly":30,"Risk":10,"Display":15,"Sustained":15,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −30 | Openness 30 | Force −45 | Materialism −25 | Community 20 | Principle 35 | Publicity 20 | Qualification 15 | Decentralization 20 | Transformation 0","Desires":"Craving 10 | Monopoly 30 | Risk 10 | Display 15 | Persistence 15 | Orientation None | Bonding Contract Cohabitation"},"sections":{"Life":"Born 2094-06-14. As of the 2126 opening, holds the post of Prescription Clerk, linking the existing shifts and records. The succession record for that post opened as a replacement shift for an unexcused absence from the rotation.\n- The prescription record and duty key handover window at Jegi-dong is taken as Bak Byeoryun''s work reference point. This placement does not fix residence, exact facility boundaries, rank of nobility, fief, or possession rights.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In 2125, he turned away a private solicitation and sent it to the public counter. That day''s record remained as grounds for handover for the next duty holder to verify.","Relationships":"Bak Byeolyun redirects requests to change the treatment order to the public desk and passes the prescription records to Eun Chaeyun. Eun Chaeyun assigns by triage level and clinical findings so that a private request does not jump ahead of patients in line.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the shift chain. Trusts a single line in the ledger more than loud talk.\n\n- Occupation: Prescription Record and Duty Key Handover\n- Affiliation: White Cross Order\n- Rank: Resident Physician\n- Title: Prescription Clerk\n**Life.** Born 2094-06-14. As of the 2126 opening, holds the post of Prescription Clerk, linking the existing shifts and records. The succession record for that post opened as a replacement shift for an unexcused absence from the rotation.\n- The prescription record and duty key handover window at Jegi-dong is taken as Bak Byeoryun''s work reference point. This placement does not fix residence, exact facility boundaries, rank of nobility, fief, or possession rights.\n\n**Office.** Rank: Resident Physician. Title: Prescription Resident. Hands over only the keys and records of their own post, and writes the time of receipt of the handed-over keys and records in the ledger.\n\n**Anecdote.** In 2125, sent a private appeal back and directed it to the public window. That day''s record remained as handover evidence for the next shift to verify.\n\n**Relationships.** Bak Byeoryun redirects appeals to change the order of treatment to the public window and passes the prescription records to Eun Chaeyun. Eun Chaeyun assigns by severity and clinical findings so that private requests do not jump ahead of patients'' order.\n\n**Ambition.** From the post of Prescription Resident, to keep the White Cross Order''s ledger linked without a break.\n\n**Fear.** Fears that if the Prescription Resident''s shift goes empty, the White Cross Order''s passage will become a hostage of Seoul''s internal patron powers.\n\n**Intervention.** Can set up a witness for the shift handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −30 | Openness 30 | Force −45 | Materialism −25 | Community 20 | Principle 35 | Publicity 20 | Qualification 15 | Decentralization 20 | Transformation 0\n- Desires: Craving 10 | Monopoly 30 | Risk 10 | Display 15 | Persistence 15 | Orientation None | Bonding Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Bak Byeoryun","type":"Contract","to":"Eun Chaeyun","basis":"Bak Byeolyun redirects requests to change the treatment order to the public desk and passes the prescription records to Eun Chaeyun. Eun Chaeyun assigns by triage level and clinical findings so that a private request does not jump ahead of patients in line."}],"incoming":[]}}', '{"id":"person-0820","name":"박별윤","title":"처방 서기","position":"처방 서기","characterId":"K820","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-박별윤","detailRoute":"/people/person-0820","birthDate":"2094-06-14","birthday":"06-14","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"public-desk-referral","name":"창구 안내","rating":40}],"traits":[{"id":"stated-priority","name":"청탁보다 공개 창구","description":"사적 청탁을 공개 창구로 돌려보낸 일화가 있다. 제도 선택은 보이나 처방 성과와 대규모 교섭은 미확인이다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"사적 청탁을 공개 창구로 돌려보낸 일화가 있다. 제도 선택은 보이나 처방 성과와 대규모 교섭은 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-30,"개방":30,"무력":-45,"물질":-25,"공동":20,"원칙":35,"공개":20,"자격":15,"분산":20,"변혁":0},"desire":{"갈망":10,"독점":30,"위험":10,"과시":15,"지속":15,"지향":"무성향","결합":"계약동거"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −30 | 개방 30 | 무력 −45 | 물질 −25 | 공동 20 | 원칙 35 | 공개 20 | 자격 15 | 분산 20 | 변혁 0","욕망":"갈망 10 | 독점 30 | 위험 10 | 과시 15 | 지속 15 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2094-06-14에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 박별윤의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"박별윤은 치료 순서를 바꾸라는 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록을 전한다. 은채윤은 중증도와 진료 소견에 따라 배정해 사적 요청이 환자 순서를 앞지르지 않게 한다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2094-06-14에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 박별윤의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 사적 청탁을 돌려보내고 공개 창구로 보냈다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 박별윤은 치료 순서를 바꾸라는 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록을 전한다. 은채윤은 중증도와 진료 소견에 따라 배정해 사적 요청이 환자 순서를 앞지르지 않게 한다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −30 | 개방 30 | 무력 −45 | 물질 −25 | 공동 20 | 원칙 35 | 공개 20 | 자격 15 | 분산 20 | 변혁 0\n- 욕망: 갈망 10 | 독점 30 | 위험 10 | 과시 15 | 지속 15 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"박별윤","type":"계약","to":"은채윤","basis":"박별윤은 치료 순서를 바꾸라는 청탁을 공개 창구로 돌리고 은채윤에게 처방 기록을 전한다. 은채윤은 중증도와 진료 소견에 따라 배정해 사적 요청이 환자 순서를 앞지르지 않게 한다."}],"incoming":[]}}');
