INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0838', 'ace0-d55c-c591', '{"id":"person-0838","name":"Go Daho","title":"Auction Clerk","position":"Myeongdong Station Election Records Clerk","rank":"Congregationioner","commonTier":"T5","occupation":"Election Records and Handover Log","gender":"Female","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0838","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0838","name":"고다호","title":"경매 서기","position":"명동역 선거 기록 서기","rank":"교우","commonTier":"T5","occupation":"선거 기록·인수인계 기록","gender":"여성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0838","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0839', 'bb38-b0a8-d3c9-6587', '{"id":"person-0839","name":"Mun Bamin","title":"Audit Recorder","position":"Audit Recorder","rank":"Guild Member","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0839","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0839","name":"문바민","title":"감사 기록관","position":"감사 기록관","rank":"조합원","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0839","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0840', 'c591-b0a8-c6d0-694a', '{"id":"person-0840","name":"Yang Jatae","title":"Conduit Surveyor","position":"Conduit Surveyor","rank":"Clerk","commonTier":"T5","occupation":"Waiting Hall Duty","gender":"Female","stage":"S4","state":"S01","stateName":"The Sluice","detailRoute":"/people/person-0840","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0840","name":"양자태","title":"관로 탐사원","position":"관로 탐사원","rank":"주사","commonTier":"T5","occupation":"대합실 당직","gender":"여성","stage":"S4","state":"S01","stateName":"수문국","detailRoute":"/people/person-0840","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0841', 'c190-bc00-c591', '{"id":"person-0841","name":"Son Tayeon","title":"Restoration Service Recorder","position":"Restoration Service Recorder","characterId":"K841","rank":"Guild Member","commonTier":"T5","occupation":"Registration & Records","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-02#Person-Son-Tayeon","detailRoute":"/people/person-0841","birthDate":"2094-08-09","birthday":"08-09","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k841-overlapping-register-check","name":"Overlapping-register crosscheck","rating":60}],"traits":[{"id":"k841-action-priority","name":"Overlap between registers","description":"The refugee citizenship list of Baek On, which Gang Minseo backs, is laid on the same desk as the restoration-service records. Son Tayeon checks line by line whether each name on the refugee list also appears in the restoration-service registration, gathers the names found in both in registry order, and leaves them in the duty handover memo.","behavior":"The refugee citizenship list of Baek On, which Gang Minseo backs, is laid on the same desk as the restoration-service records. Son Tayeon checks line by line whether each name on the refugee list also appears in the restoration-service registration, gathers the names found in both in registry order, and leaves them in the duty handover memo.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k841-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the restoration service registrar duty post would stand empty and the Alliance''s passage would become a hostage of the great powers.","relationship":"Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The refugee citizenship list of Baek On, which Gang Minseo backs, is laid on the same desk as the restoration-service records. Son Tayeon checks line by line whether each name on the refugee list also appears in the restoration-service registration, gathers the names found in both in registry order, and leaves them in the duty handover memo. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c190-bc00-c591","name":"Miryang Son Clan","crest":"clan-crests/c190-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":50,"Principle":15,"Public":25,"Eligibility":45,"Dispersed":20,"Transformative":15},"desire":{"Longing":0,"Monopoly":-25,"Risk":30,"Display":-25,"Sustained":20,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Registration & Records","Rank":"Guild Member","Title":"Restoration Service Recorder","Work Location":"Guro 2-dong. At the duty desk in Guro 2-dong, Son Tayeon cross-checks Baek On''s refugee citizenship roster against the restoration service registration in name order. She re-matches the names that overlap on both rosters against Kim Nayul''s shift schedule and leaves the result in the next records officer''s handover memo.","Values":"Authority −20 | Openness 20 | Force −20 | Materiality 40 | Community 50 | Principle 15 | Publicity 25 | Qualification 45 | Dispersal 20 | Transformation 15","Desires":"Craving 0 | Monopoly −25 | Risk 30 | Display −25 | Persistence 20 | Orientation: Bisexual | Union: Contract Cohabitation"},"sections":{"Life":"Generation of 2126. Grew up at the Seoul Station Registry Office. The post of Restoration Service Records Officer opened with the deletion of one line in the double ledger.\n- Work location: Guro 2-dong. At the duty desk in Guro 2-dong, Son Tayeon cross-checks Baek On''s refugee citizenship roster against the restoration service registration in name order. She re-matches the names that overlap on both rosters against Kim Nayul''s shift schedule and leaves the result in the next records officer''s handover memo.","Offices":"Rank: Union Member. Title: Restoration Service Records Officer. She re-matches the names that overlap on both rosters against Kim Nayul''s shift schedule and leaves the result in the next records officer''s handover memo.","Anecdote":"The refugee citizenship roster of Baek On, which Gang Minseo supports, is placed on the same desk as the restoration service records. Son Tayeon checks line by line whether names on the refugee roster were also entered in the restoration service registration, and gathers the names that overlap in both in registry order into the duty handover memo.","Relationships":"Son Tayeon hands Gim Nayul the names that overlap between the refugee list and the restoration-service registration. Gim Nayul checks the actual shifts and registrations so that the same person does not remain as two laborers.","Ambition":"Son Tayeon seeks to mark the overlapping names on the refugee citizenship roster and the restoration service registration so that one person is not counted as two laborers.","Fear":"The same name on the refugee roster and in the restoration service registration being counted as two laborers.","Intervention":"The player can cross-check the overlapping names on the two rosters with Son Tayeon, or leave in the next records officer''s memo the lines to be verified against Kim Nayul''s shift schedule."},"biography":"Son Tayeon cross-checks the two rosters before the same name is counted as two laborers.\n\n- Affiliation: Free City\n- Livelihood: Registry and records\n- Rank: Union Member\n- Title: Restoration Service Records Officer\n**Life.** Generation of 2126. Grew up at the Seoul Station Registry Office. The post of Restoration Service Records Officer opened with the deletion of one line in the double ledger.\n- Work location: Guro 2-dong. At the duty desk in Guro 2-dong, Son Tayeon cross-checks Baek On''s refugee citizenship roster against the restoration service registration in name order. She re-matches the names that overlap on both rosters against Kim Nayul''s shift schedule and leaves the result in the next records officer''s handover memo.\n\n**Office.** Rank: Union Member. Title: Restoration Service Records Officer. She re-matches the names that overlap on both rosters against Kim Nayul''s shift schedule and leaves the result in the next records officer''s handover memo.\n\n**Anecdote.** The refugee citizenship roster of Baek On, which Gang Minseo supports, is placed on the same desk as the restoration service records. Son Tayeon checks line by line whether names on the refugee roster were also entered in the restoration service registration, and gathers the names that overlap in both in registry order into the duty handover memo.\n\n**Relationships.** Son Tayeon passes the names that overlap on the refugee roster and in the restoration service registration to Kim Nayul. Kim Nayul verifies actual shifts and registrations so that the same person does not remain on the books as two laborers.\n\n**Ambition.** Son Tayeon seeks to mark the overlapping names on the refugee citizenship roster and the restoration service registration so that one person is not counted as two laborers.\n\n**Fear.** The same name on the refugee roster and in the restoration service registration being counted as two laborers.\n\n**Intervention.** The player can cross-check the overlapping names on the two rosters with Son Tayeon, or leave in the next records officer''s memo the lines to be verified against Kim Nayul''s shift schedule.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 20 | Force −20 | Materiality 40 | Community 50 | Principle 15 | Publicity 25 | Qualification 45 | Dispersal 20 | Transformation 15\n- Desires: Craving 0 | Monopoly −25 | Risk 30 | Display −25 | Persistence 20 | Orientation: Bisexual | Union: Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Son Tayeon","type":"Contract","to":"Kim Nayul","basis":"Son Tayeon hands Gim Nayul the names that overlap between the refugee list and the restoration-service registration. Gim Nayul checks the actual shifts and registrations so that the same person does not remain as two laborers."}],"incoming":[]}}', '{"id":"person-0841","name":"손타연","title":"복구복무 기록관","position":"복구복무 기록관","characterId":"K841","rank":"조합원","commonTier":"T5","occupation":"등기·기록","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-02#인물-손타연","detailRoute":"/people/person-0841","birthDate":"2094-08-09","birthday":"08-09","age":32,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":7,"effective":7},"stewardship":{"base":11,"effective":11},"intrigue":{"base":12,"effective":12},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k841-overlapping-register-check","name":"명부 중복 대조","rating":60}],"traits":[{"id":"k841-action-priority","name":"두 명부의 겹침","description":"강민서가 지지하는 백온의 난민 시민권 명단이 복구복무 기록과 한 책상에 놓인다. 손타연은 난민 명단의 이름이 복구복무 등록에도 올랐는지 한 줄씩 대조하고, 두 곳에 겹친 이름을 등기 순서대로 모아 당직 인수인계 메모에 남긴다.","behavior":"강민서가 지지하는 백온의 난민 시민권 명단이 복구복무 기록과 한 책상에 놓인다. 손타연은 난민 명단의 이름이 복구복무 등록에도 올랐는지 한 줄씩 대조하고, 두 곳에 겹친 이름을 등기 순서대로 모아 당직 인수인계 메모에 남긴다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k841-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"복구복무 기록관 당직이 비면 규격맹의 통행이 강국 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"강민서가 지지하는 백온의 난민 시민권 명단이 복구복무 기록과 한 책상에 놓인다. 손타연은 난민 명단의 이름이 복구복무 등록에도 올랐는지 한 줄씩 대조하고, 두 곳에 겹친 이름을 등기 순서대로 모아 당직 인수인계 메모에 남긴다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c190-bc00-c591","name":"밀양 손씨","crest":"clan-crests/c190-bc00-c591.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":20,"무력":-20,"물질":40,"공동":50,"원칙":15,"공개":25,"자격":45,"분산":20,"변혁":15},"desire":{"갈망":0,"독점":-25,"위험":30,"과시":-25,"지속":20,"지향":"양성","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"등기·기록","품계":"조합원","직함":"복구복무 기록관","업무 위치":"구로2동. 손타연은 구로2동 당직 책상에서 백온의 난민 시민권 명단과 복구복무 등록을 이름 순서대로 대조한다. 두 명부에 겹친 이름을 김나율의 교대표와 다시 맞추고 결과를 다음 기록관의 인수 메모에 남긴다.","가치관":"권위 −20 | 개방 20 | 무력 −20 | 물질 40 | 공동 50 | 원칙 15 | 공개 25 | 자격 45 | 분산 20 | 변혁 15","욕망":"갈망 0 | 독점 −25 | 위험 30 | 과시 −25 | 지속 20 | 지향 양성 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 손타연은 구로2동 당직 책상에서 백온의 난민 시민권 명단과 복구복무 등록을 이름 순서대로 대조한다. 두 명부에 겹친 이름을 김나율의 교대표와 다시 맞추고 결과를 다음 기록관의 인수 메모에 남긴다.","관직":"품계 조합원. 직함은 복구복무 기록관. 두 명부에 겹친 이름을 김나율의 교대표와 다시 맞추고 결과를 다음 기록관의 인수 메모에 남긴다.","일화":"강민서가 지지하는 백온의 난민 시민권 명단이 복구복무 기록과 한 책상에 놓인다. 손타연은 난민 명단의 이름이 복구복무 등록에도 올랐는지 한 줄씩 대조하고, 두 곳에 겹친 이름을 등기 순서대로 모아 당직 인수인계 메모에 남긴다.","관계":"손타연은 난민 명단과 복구복무 등록에 겹친 이름을 김나율에게 넘긴다. 김나율은 실제 교대와 등록을 확인해 같은 사람이 두 명의 노동 인원으로 남지 않게 한다.","야망":"손타연은 난민 시민권 명단과 복구복무 등록의 겹친 이름을 표시해 한 사람을 두 노동 인원으로 세지 않게 하려 한다.","공포":"난민 명단과 복구복무 등록의 같은 이름을 두 노동 인원으로 집계하는 것.","개입":"플레이어는 손타연과 두 명부의 겹친 이름을 대조하거나 김나율의 교대표에서 확인할 줄을 다음 기록관 메모에 남길 수 있다."},"biography":"손타연은 같은 이름이 두 명의 노동 인원으로 집계되기 전에 두 명부를 대조한다.\n\n- 소속: 자유도시\n- 생업: 등기·기록\n- 품계: 조합원\n- 직함: 복구복무 기록관\n**생애.** 2126년 세대. 서울역 등기소에서 자랐다. 복구복무 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 업무 위치: 구로2동. 손타연은 구로2동 당직 책상에서 백온의 난민 시민권 명단과 복구복무 등록을 이름 순서대로 대조한다. 두 명부에 겹친 이름을 김나율의 교대표와 다시 맞추고 결과를 다음 기록관의 인수 메모에 남긴다.\n\n**관직.** 품계 조합원. 직함은 복구복무 기록관. 두 명부에 겹친 이름을 김나율의 교대표와 다시 맞추고 결과를 다음 기록관의 인수 메모에 남긴다.\n\n**일화.** 강민서가 지지하는 백온의 난민 시민권 명단이 복구복무 기록과 한 책상에 놓인다. 손타연은 난민 명단의 이름이 복구복무 등록에도 올랐는지 한 줄씩 대조하고, 두 곳에 겹친 이름을 등기 순서대로 모아 당직 인수인계 메모에 남긴다.\n\n**관계.** 손타연은 난민 명단과 복구복무 등록에 겹친 이름을 김나율에게 넘긴다. 김나율은 실제 교대와 등록을 확인해 같은 사람이 두 명의 노동 인원으로 남지 않게 한다.\n\n**야망.** 손타연은 난민 시민권 명단과 복구복무 등록의 겹친 이름을 표시해 한 사람을 두 노동 인원으로 세지 않게 하려 한다.\n\n**공포.** 난민 명단과 복구복무 등록의 같은 이름을 두 노동 인원으로 집계하는 것.\n\n**개입.** 플레이어는 손타연과 두 명부의 겹친 이름을 대조하거나 김나율의 교대표에서 확인할 줄을 다음 기록관 메모에 남길 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 20 | 무력 −20 | 물질 40 | 공동 50 | 원칙 15 | 공개 25 | 자격 45 | 분산 20 | 변혁 15\n- 욕망: 갈망 0 | 독점 −25 | 위험 30 | 과시 −25 | 지속 20 | 지향 양성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"손타연","type":"계약","to":"김나율","basis":"손타연은 난민 명단과 복구복무 등록에 겹친 이름을 김나율에게 넘긴다. 김나율은 실제 교대와 등록을 확인해 같은 사람이 두 명의 노동 인원으로 남지 않게 한다."}],"incoming":[]}}');
