INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0851', 'cc28-c5f0-c548', '{"id":"person-0851","name":"Cha Ahwan","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0851","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0851","name":"차아환","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0851","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0852', 'c8fc-c2e0-c548', '{"id":"person-0852","name":"Ju Kain","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Logistics Merchant","characterId":"K852","rank":"Resident","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-Ju-Kain","detailRoute":"/people/person-0852","birthDate":"2099-11-23","birthday":"11-23","age":27,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"suspect-medicine-sealing","name":"Suspect medicine sealing","rating":45}],"traits":[{"id":"stated-priority","name":"Preserves suspect boxes","description":"Counterfeit medicine boxes at auction were collected and sealed. Choosing custody over burning is supported; independent appraisal evidence is limited.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Counterfeit medicine boxes at auction were collected and sealed. Choosing custody over burning is supported; independent appraisal evidence is limited.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c8fc-c2e0-c548","name":"Sinan Ju Clan","crest":"clan-crests/c8fc-c2e0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":20,"Force":-45,"Material":0,"Communal":15,"Principle":35,"Public":10,"Eligibility":15,"Dispersed":15,"Transformative":-10},"desire":{"Longing":-5,"Monopoly":20,"Risk":35,"Display":-15,"Sustained":5,"Orientation":"Fluid","Union":"Non-Exclusive"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −15 | Openness 20 | Force −45 | Materiality 0 | Community 15 | Principle 35 | Publicity 10 | Qualification 15 | Decentralization 15 | Transformation −10","Desires":"Craving −5 | Monopoly 20 | Risk 35 | Display −15 | Persistence 5 | Orientation Fluid | Bonding Non-exclusive"},"sections":{"Life":"Born on 2099-11-23. As of the 2126 opening, holds the post of Medicinal Supply Merchant and continues the existing watch and records. The succession record of that post opens with the sealing of fake medicine.\n- The medicinal herb management records and watch key handover desk at Jegi-dong is taken as Ju Kain''s work reference point. This placement does not fix residence, exact facility boundaries, titles of nobility, fiefs, or tenure rights.","Offices":"Rank: Resident. Title: Medicinal Herb Management Resident. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, collected a box of counterfeit medicine from the auction house and sealed it instead of burning it. That day''s record remained as grounds for handover for the next duty-holder to verify.","Relationships":"Ju Kain seals suspect medicinal herbs and hands them to Won Miru along with custody records. Won Miru examines the samples and capsule seals, investigates the route, and leaves unidentified origins as dotted lines.","Ambition":"From the post of Medicinal Herb Management Resident, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that if the Medicinal Herb Management Resident''s watch falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to let the watch break. Trusts a single line in the ledger more than loud talk.\n\n- Occupation: Medicinal herb management records and watch key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Medicinal Supply Merchant\n**Life.** Born on 2099-11-23. As of the 2126 opening, holds the post of Medicinal Supply Merchant and continues the existing watch and records. The succession record of that post opens with the sealing of fake medicine.\n- The medicinal herb management records and watch key handover desk at Jegi-dong is taken as Ju Kain''s work reference point. This placement does not fix residence, exact facility boundaries, titles of nobility, fiefs, or tenure rights.\n\n**Office.** Rank: Resident. Title: Medicinal Supply Resident. Hands over only the keys and records of their own post, and writes into the ledger the time of receipt of the keys and records handed over.\n\n**Anecdote.** In 2125, collected a box of fake medicine from the auction house and sealed it instead of burning it. That day''s record remained as the handover basis for the next watch to check.\n\n**Relations.** Ju Kain seals suspect medicinal herbs and hands them over to Won Miru together with the management records. Won Miru examines the samples and capsule seals to investigate the route, and leaves unconfirmed places of origin as dotted lines.\n\n**Ambition.** From the Medicinal Supply Resident post, to keep the ledger of the White Cross Order unbroken.\n\n**Fear.** Fears that if the Medicinal Supply Resident watch falls empty, the passage of the White Cross Order will become a hostage of Seoul''s internal patron factions.\n\n**Intervention.** Can have a witness stand at a watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 20 | Force −45 | Materiality 0 | Community 15 | Principle 35 | Publicity 10 | Qualification 15 | Decentralization 15 | Transformation −10\n- Desires: Craving −5 | Monopoly 20 | Risk 35 | Display −15 | Persistence 5 | Orientation Fluid | Bonding Non-exclusive\n:::","relations":{"outgoing":[{"from":"Ju Kain","type":"Contract","to":"Won Miru","basis":"Ju Kain seals suspect medicinal herbs and hands them to Won Miru along with custody records. Won Miru examines the samples and capsule seals, investigates the route, and leaves unidentified origins as dotted lines."}],"incoming":[]}}', '{"id":"person-0852","name":"주카인","title":"약재 물류상","position":"약재 물류상","characterId":"K852","rank":"수련의","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-주카인","detailRoute":"/people/person-0852","birthDate":"2099-11-23","birthday":"11-23","age":27,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"suspect-medicine-sealing","name":"의심 약품 봉인","rating":45}],"traits":[{"id":"stated-priority","name":"의심 상자를 보존한다","description":"경매장의 가짜 약 상자를 거둬 봉인했다. 화형을 피한 보관 선택은 확인되지만 독립 감별 능력의 근거는 부족하다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"경매장의 가짜 약 상자를 거둬 봉인했다. 화형을 피한 보관 선택은 확인되지만 독립 감별 능력의 근거는 부족하다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c8fc-c2e0-c548","name":"신안 주씨","crest":"clan-crests/c8fc-c2e0-c548.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":20,"무력":-45,"물질":0,"공동":15,"원칙":35,"공개":10,"자격":15,"분산":15,"변혁":-10},"desire":{"갈망":-5,"독점":20,"위험":35,"과시":-15,"지속":5,"지향":"유동","결합":"비독점"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"약재 물류상","가치관":"권위 −15 | 개방 20 | 무력 −45 | 물질 0 | 공동 15 | 원칙 35 | 공개 10 | 자격 15 | 분산 15 | 변혁 −10","욕망":"갈망 −5 | 독점 20 | 위험 35 | 과시 −15 | 지속 5 | 지향 유동 | 결합 비독점"},"sections":{"생애":"2099-11-23에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 주카인의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 가짜 약 상자를 경매장에서 거둬 화형 대신 봉인했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"주카인은 의심 약재를 봉인해 원미루에게 관리 기록과 함께 넘긴다. 원미루는 표본·캡슐 인장을 살펴 경로를 조사하고 미확인 산지는 점선으로 남긴다.","야망":"약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 약재 물류상\n**생애.** 2099-11-23에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 주카인의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 가짜 약 상자를 경매장에서 거둬 화형 대신 봉인했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 주카인은 의심 약재를 봉인해 원미루에게 관리 기록과 함께 넘긴다. 원미루는 표본·캡슐 인장을 살펴 경로를 조사하고 미확인 산지는 점선으로 남긴다.\n\n**야망.** 약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 20 | 무력 −45 | 물질 0 | 공동 15 | 원칙 35 | 공개 10 | 자격 15 | 분산 15 | 변혁 −10\n- 욕망: 갈망 −5 | 독점 20 | 위험 35 | 과시 −15 | 지속 5 | 지향 유동 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"주카인","type":"계약","to":"원미루","basis":"주카인은 의심 약재를 봉인해 원미루에게 관리 기록과 함께 넘긴다. 원미루는 표본·캡슐 인장을 살펴 경로를 조사하고 미확인 산지는 점선으로 남긴다."}],"incoming":[]}}');
