INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0858', 'bc15-bc00-c591', '{"id":"person-0858","name":"Bak Daeun","title":"Retainer Recorder","position":"Retainer Recorder","rank":"Assistant Manager","commonTier":"T5","occupation":"Records and Keys Handover","gender":"Female","stage":"S4","state":"S03","stateName":"Taeuk Group","detailRoute":"/people/person-0858","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0858","name":"박다은","title":"종자 기록관","position":"종자 기록관","rank":"대리","commonTier":"T5","occupation":"기록·열쇠 인수인계","gender":"여성","stage":"S4","state":"S03","stateName":"태욱그룹","detailRoute":"/people/person-0858","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0859', 'cd5c-acbd-c8fc', '{"id":"person-0859","name":"Choe Baa","title":"Holding Track Patrol","position":"Holding Track Patrol","characterId":"K859","rank":"Teacher","commonTier":"T5","occupation":"Guard & Patrol","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#inmul-Choe-Baa","detailRoute":"/people/person-0859","birthDate":"2093-04-25","birthday":"04-25","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":7,"effective":7},"stewardship":{"base":7,"effective":7},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"scout","name":"Ambush-sign observation","rating":50},{"id":"guard","name":"Entry control and pass replacement","rating":45}],"traits":[{"id":"patrol-signs-first","name":"Patrol Signs First","description":"Choe Baa shows a disposition to attend first to traces of danger during patrol.","behavior":"During a ridge patrol, he read ambush traces early and prevented harm.","stress":"If he fears interrupted duty will threaten passage, he may examine immediate patrol signs more carefully.","relationship":"In handovers with senior duty staff, he may emphasize sharing the ambush traces he personally recognized.","effects":[]},{"id":"avoid-verified-hazards","name":"Avoid Verified Hazards","description":"Choe Baa shows a disposition to base harm avoidance on the ambush signs he has recognized.","behavior":"After recognizing ambush traces on the ridge, he prevented harm from that danger.","stress":"If continuing patrol conflicts with ambush danger, he may prioritize avoiding harm on the basis of observed signs.","relationship":"He may seek to pass senior duty staff the traces that supported his risk judgment.","effects":[]}],"narrative":"He prevented harm through ridge ambush signs. Observation is a strength, not ownership of an intelligence network or combat victories.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cd5c-acbd-c8fc","name":"Gyeongju Choe Clan","crest":"clan-crests/cd5c-acbd-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":25,"Openness":0,"Force":-5,"Material":20,"Communal":25,"Principle":0,"Public":-15,"Eligibility":40,"Dispersed":25,"Transformative":5},"desire":{"Longing":0,"Monopoly":25,"Risk":5,"Display":10,"Sustained":5,"Orientation":"Bisexual","Union":"Monogamy"},"fields":{"Affiliation":"Arc","Livelihood":"Guard & Patrol","Rank":"Teacher","Title":"Holding Track Patrol","Values":"Authority 25 | Openness 0 | Force −5 | Material 20 | Communal 25 | Principle 0 | Publicity −15 | Qualification 40 | Dispersal 25 | Transformation 5","Desires":"Craving 0 | Monopoly 25 | Risk 5 | Display 10 | Continuity 5 | Orientation Bisexual | Bonding Monogamous"},"sections":{"Life":"Generation of 2126. Choe Ba-a grew up at the Amsa guard post. Choe Ba-a took the Stabling Track Patrol post after catching an unauthorized night river crossing.\n- Choe Ba-a''s Stabling Track Patrol work is tied to Yongdap-dong.","Offices":"Choe Ba-a hands over only the keys and records that come with their own post. They do not invent authority that does not exist.","Anecdote":"In 2125, while on ridge patrol, Choe Ba-a read the signs of an ambush first and prevented harm. Because of this, the signature for the Stabling Track Patrol post was entered in the ledger.","Relationships":"Choe Ba-a is bound by handover to a senior duty officer from the same living sphere.","Ambition":"As Stabling Track Patrol duty officer, Choe Ba-a seeks to keep the Arc''s ledger connected without a break.","Fear":"Choe Ba-a fears that if the Stabling Track Patrol duty goes vacant, the Arc''s passage will be held hostage by the Great Powers.","Intervention":"Choe Ba-a can bring in a witness to the duty handover or expose an empty key."},"biography":"Choe Ba-a first chooses not to break the duty chain. Choe Ba-a trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Arc\n- Livelihood: Guard and Patrol\n- Rank: Teacher\n- Title: Stabling Track Patrol\n**Life.** Generation of 2126. Choe Ba-a grew up at the Amsa guard post. Choe Ba-a took the Stabling Track Patrol post after catching an unauthorized night river crossing.\n- Choe Ba-a''s Stabling Track Patrol work is tied to Yongdap-dong.\n\n**Office.** Choe Ba-a hands over only the keys and records that come with their own post. They do not invent authority that does not exist.\n\n**Anecdote.** In 2125, while on ridge patrol, Choe Ba-a read the signs of an ambush first and prevented harm. Because of this, the signature for the Stabling Track Patrol post was entered in the ledger.\n\n**Relations.** Choe Ba-a is bound by handover to a senior duty officer from the same living sphere.\n\n**Ambition.** As Stabling Track Patrol duty officer, Choe Ba-a seeks to keep the Arc''s ledger connected without a break.\n\n**Fear.** Choe Ba-a fears that if the Stabling Track Patrol duty goes vacant, the Arc''s passage will be held hostage by the Great Powers.\n\n**Intervention.** Choe Ba-a can bring in a witness to the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 25 | Openness 0 | Force −5 | Material 20 | Communal 25 | Principle 0 | Publicity −15 | Qualification 40 | Dispersal 25 | Transformation 5\n- Desires: Craving 0 | Monopoly 25 | Risk 5 | Display 10 | Continuity 5 | Orientation Bisexual | Bonding Monogamous\n:::","relations":{"outgoing":[{"from":"Choe Baa","type":"Contract","to":"Chae Gu-reum","basis":"Choe Baa tells Chae Gureum about the ambush traces read on patrol. Chae Gureum checks the bridge water level and the entry records to confirm whether the observation links to actual signs of an approach."}],"incoming":[]}}', '{"id":"person-0859","name":"최바아","title":"유치선 순찰대","position":"유치선 순찰대","characterId":"K859","rank":"교사","commonTier":"T5","occupation":"경비·순찰","gender":"여성","stage":"S4","state":"arc","stateName":"Arc","sourceRoute":"/world/Cast-State-04#인물-최바아","detailRoute":"/people/person-0859","birthDate":"2093-04-25","birthday":"04-25","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"excluded"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":7,"effective":7},"stewardship":{"base":7,"effective":7},"intrigue":{"base":10,"effective":10},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}},"skills":[{"id":"scout","name":"매복 징후 관찰","rating":50},{"id":"guard","name":"출입 저지·암호패 교체","rating":45}],"traits":[{"id":"patrol-signs-first","name":"초계 징후 먼저","description":"최바아는 초계에서 위험의 흔적을 먼저 읽는 데 주의를 두는 성향을 보인다.","behavior":"능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","stress":"당직 단절로 통행이 위협받을까 우려되면 눈앞의 초계 징후를 더 신중히 살필 수 있다.","relationship":"선배 당직과 인계할 때 직접 읽은 매복 흔적을 공유하는 데 무게를 둘 수 있다.","effects":[]},{"id":"avoid-verified-hazards","name":"확인된 위험 회피","description":"최바아는 읽어 낸 매복 징후를 근거로 피해를 피하는 판단을 중시하는 성향을 보인다.","behavior":"능선의 매복 흔적을 알아챈 뒤 그 위험으로 인한 피해를 막았다.","stress":"초계를 이어 가는 일과 매복 위험이 충돌하면 확인한 징후에 근거해 피해 회피를 우선할 수 있다.","relationship":"선배 당직에게는 위험 판단의 근거가 된 흔적을 함께 전달하려 할 수 있다.","effects":[]}],"narrative":"능선의 매복 흔적으로 피해를 막았다. 관찰 강점은 있으나 정보망 소유나 전투 승전은 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"cd5c-acbd-c8fc","name":"경주 최씨","crest":"clan-crests/cd5c-acbd-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":25,"개방":0,"무력":-5,"물질":20,"공동":25,"원칙":0,"공개":-15,"자격":40,"분산":25,"변혁":5},"desire":{"갈망":0,"독점":25,"위험":5,"과시":10,"지속":5,"지향":"양성","결합":"단혼"},"fields":{"소속":"Arc","생업":"경비·순찰","품계":"교사","직함":"유치선 순찰대","가치관":"권위 25 | 개방 0 | 무력 −5 | 물질 20 | 공동 25 | 원칙 0 | 공개 −15 | 자격 40 | 분산 25 | 변혁 5","욕망":"갈망 0 | 독점 25 | 위험 5 | 과시 10 | 지속 5 | 지향 양성 | 결합 단혼"},"sections":{"생애":"2126년 세대. 최바아는 암사 경비 초소에서 자랐다. 최바아는 야간 무단 도하 적발로 유치선 순찰대 자리를 맡았다.\n- 최바아의 유치선 순찰대 업무는 용답동과 연결된다.","관직":"최바아는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.","일화":"2125년 최바아는 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다. 이 일로 유치선 순찰대 자리의 서명이 장부에 올랐다.","관계":"최바아는 같은 생활권 선배 당직자와 인수인계로 묶인다.","야망":"최바아는 유치선 순찰대 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.","공포":"최바아는 유치선 순찰대 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.","개입":"최바아는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"최바아는 당직을 끊지 않는 쪽을 먼저 고른다. 최바아는 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: Arc\n- 생업: 경비·순찰\n- 품계: 교사\n- 직함: 유치선 순찰대\n**생애.** 2126년 세대. 최바아는 암사 경비 초소에서 자랐다. 최바아는 야간 무단 도하 적발로 유치선 순찰대 자리를 맡았다.\n- 최바아의 유치선 순찰대 업무는 용답동과 연결된다.\n\n**관직.** 최바아는 자신의 직위에 딸린 열쇠와 기록만 인계한다. 없는 권한은 만들지 않는다.\n\n**일화.** 2125년 최바아는 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다. 이 일로 유치선 순찰대 자리의 서명이 장부에 올랐다.\n\n**관계.** 최바아는 같은 생활권 선배 당직자와 인수인계로 묶인다.\n\n**야망.** 최바아는 유치선 순찰대 당직에서 Arc의 장부를 끊기지 않게 잇고자 한다.\n\n**공포.** 최바아는 유치선 순찰대 당직이 비면 Arc의 통행이 강국 볼모가 되는 상황을 두려워한다.\n\n**개입.** 최바아는 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 25 | 개방 0 | 무력 −5 | 물질 20 | 공동 25 | 원칙 0 | 공개 −15 | 자격 40 | 분산 25 | 변혁 5\n- 욕망: 갈망 0 | 독점 25 | 위험 5 | 과시 10 | 지속 5 | 지향 양성 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"최바아","type":"계약","to":"채구름","basis":"최바아는 순찰에서 읽은 매복 흔적을 채구름에게 알린다. 채구름은 교량 수위와 출입 기록을 살펴 그 관찰이 실제 접근 흔적과 이어지는지 확인한다."}],"incoming":[]}}');
