INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0866', 'd55c-ccad-c8fc', '{"id":"person-0866","name":"Han Namu","title":"Escort Courier","position":"Gangnam Station Escort Courier","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station Escort Records and Keys Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0866","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0866","name":"한남우","title":"호송 전령","position":"강남역 호송 전령","rank":"사원","commonTier":"T5","occupation":"강남역 호송 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0866","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0867', 'c624-d574-c8fc', '{"id":"person-0867","name":"O Neulho","title":"Queue Scout","position":"Queue Scout","rank":"Escort","commonTier":"T5","occupation":"Queue Survey Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0867","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}', '{"id":"person-0867","name":"오늘호","title":"대기열 탐사원","position":"대기열 탐사원","rank":"호송원","commonTier":"T5","occupation":"대기열 탐사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0867","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0868', 'c11c-b2ec-c131', '{"id":"person-0868","name":"Seo Dalseo","title":"Prescription Clerk","position":"Prescription Clerk","characterId":"K868","rank":"Resident","commonTier":"T3","occupation":"Prescription Records and Duty Keys Handover","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#person-seodalseo","detailRoute":"/people/person-0868","birthDate":"2076-01-25","birthday":"01-25","age":50,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"Ledger preservation","rating":40}],"traits":[{"id":"stated-priority","name":"Does not leave the people ledger","description":"The people ledger was rescued first in a fire. Concern for continuity is retained without adding prescribing expertise.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: prescription clerk. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the prescription clerk duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"The people ledger was rescued first in a fire. Concern for continuity is retained without adding prescribing expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-20,"Openness":40,"Force":-50,"Material":-25,"Communal":20,"Principle":40,"Public":10,"Eligibility":30,"Dispersed":10,"Transformative":0},"desire":{"Longing":40,"Monopoly":25,"Risk":15,"Display":-20,"Sustained":30,"Orientation":"None","Union":"Monogamy"},"fields":{"Livelihood":"Prescription Records and Duty Keys Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Prescription Clerk","Values":"Authority −20 | Openness 40 | Force −50 | Material −25 | Communal 20 | Principle 40 | Publicity 10 | Qualification 30 | Dispersal 10 | Transformation 0","Desires":"Craving 40 | Monopoly 25 | Risk 15 | Display −20 | Continuity 30 | Orientation None | Bonding Monogamous"},"sections":{"Life":"Born on 2076-01-25. As of the 2126 opening, holds the Prescription Clerk post and continues the existing duty and records. The succession record for that post shows it opened as a substitute duty after an unexcused shift absence.\n- The prescription records and duty-key handover window at Jegi-dong is taken as Seo Dalseo''s work reference point. This placement does not fix residence, exact facility boundaries, noble title, fief, or possession rights.","Offices":"Rank: Resident. Title: Prescription Resident. He hands over only the keys and records of his own post, and writes in the ledger the time of receipt of the keys and records he has handed over.","Anecdote":"In the 2125 station fire, carried out the register of lives first. That day''s record remained as a handover basis for the next duty shift to verify.","Relationships":"Seo Dalseo passes the patient roster and prescription records she has kept to Jeon Sol. Jeon Sol checks the bed waitlist and severity to find the patients who were left out because of the lost records.","Ambition":"From the Prescription Resident post, he carries on the White Cross Order''s ledger so that it is not broken.","Fear":"He fears that if the Prescription Resident duty falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal backing powers.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty chain. Trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Prescription Records and Duty-Key Handover\n- Affiliation: White Cross Order\n- Rank: Resident Physician\n- Title: Prescription Clerk\n**Life.** Born on 2076-01-25. As of the 2126 opening, holds the Prescription Clerk post and continues the existing duty and records. The succession record for that post shows it opened as a substitute duty after an unexcused shift absence.\n- The prescription records and duty-key handover window at Jegi-dong is taken as Seo Dalseo''s work reference point. This placement does not fix residence, exact facility boundaries, noble title, fief, or possession rights.\n\n**Office.** Rank: Resident Physician. Title: Prescription Resident. Hands over only the keys and records of their own post, and writes the time of receipt of the handed-over keys and records in the ledger.\n\n**Anecdote.** During the 2125 station fire, they carried out the casualty ledger first. That day''s record remained as handover evidence for the next duty officer to verify.\n\n**Relations.** Seo Dalseo passes the patient roster and prescription records in their keeping to Jeon Sol. Jeon Sol checks bed waiting lists and severity levels to find patients who were left off because of lost records.\n\n**Ambition.** From the Prescription Resident post, keeps the White Cross Order''s ledger connected without a break.\n\n**Fear.** Fears that if the Prescription Resident duty goes vacant, the White Cross Order''s passage will be held hostage by Seoul''s internal patron factions.\n\n**Intervention.** Can bring in a witness to the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −20 | Openness 40 | Force −50 | Material −25 | Communal 20 | Principle 40 | Publicity 10 | Qualification 30 | Dispersal 10 | Transformation 0\n- Desires: Craving 40 | Monopoly 25 | Risk 15 | Display −20 | Continuity 30 | Orientation None | Bonding Monogamous\n:::","relations":{"outgoing":[{"from":"Seo Dalseo","type":"Contract","to":"Jeon Sol","basis":"Seo Dalseo passes the patient roster and prescription records she has kept to Jeon Sol. Jeon Sol checks the bed waitlist and severity to find the patients who were left out because of the lost records."}],"incoming":[]}}', '{"id":"person-0868","name":"서달서","title":"처방 서기","position":"처방 서기","characterId":"K868","rank":"수련의","commonTier":"T3","occupation":"처방 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-서달서","detailRoute":"/people/person-0868","birthDate":"2076-01-25","birthday":"01-25","age":50,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"ledger-preservation","name":"장부 보존","rating":40}],"traits":[{"id":"stated-priority","name":"인명 장부를 놓지 않는다","description":"화재 때 인명 장부를 먼저 구했다. 기록 연속성을 중시하는 태도는 살리되 처방 실력을 추가하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 처방 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"화재 때 인명 장부를 먼저 구했다. 기록 연속성을 중시하는 태도는 살리되 처방 실력을 추가하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-20,"개방":40,"무력":-50,"물질":-25,"공동":20,"원칙":40,"공개":10,"자격":30,"분산":10,"변혁":0},"desire":{"갈망":40,"독점":25,"위험":15,"과시":-20,"지속":30,"지향":"무성향","결합":"단혼"},"fields":{"생업":"처방 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"처방 서기","가치관":"권위 −20 | 개방 40 | 무력 −50 | 물질 −25 | 공동 20 | 원칙 40 | 공개 10 | 자격 30 | 분산 10 | 변혁 0","욕망":"갈망 40 | 독점 25 | 위험 15 | 과시 −20 | 지속 30 | 지향 무성향 | 결합 단혼"},"sections":{"생애":"2076-01-25에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 서달서의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"서달서는 보관한 환자 명부와 처방 기록을 전솔에게 전한다. 전솔은 병상 대기와 중증도를 확인해 기록 손실 때문에 빠진 환자를 찾는다.","야망":"처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 처방 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 처방 서기\n**생애.** 2076-01-25에 태어났다. 2126년 개막 현재 처방 서기 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 교대 무단 결근 대체 당직으로 열렸다.\n- 제기동의 처방 기록·당직 열쇠 인계 창구를 서달서의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 처방 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 역사 화재 때 인명 장부부터 꺼내 들고 나왔다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 서달서는 보관한 환자 명부와 처방 기록을 전솔에게 전한다. 전솔은 병상 대기와 중증도를 확인해 기록 손실 때문에 빠진 환자를 찾는다.\n\n**야망.** 처방 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 처방 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 40 | 무력 −50 | 물질 −25 | 공동 20 | 원칙 40 | 공개 10 | 자격 30 | 분산 10 | 변혁 0\n- 욕망: 갈망 40 | 독점 25 | 위험 15 | 과시 −20 | 지속 30 | 지향 무성향 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"서달서","type":"계약","to":"전솔","basis":"서달서는 보관한 환자 명부와 처방 기록을 전솔에게 전한다. 전솔은 병상 대기와 중증도를 확인해 기록 손실 때문에 빠진 환자를 찾는다."}],"incoming":[]}}');
