INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0883', 'b0a8-c758-b839', '{"id":"person-0883","name":"Nam Ramwon","title":"Medical Escort Recorder","position":"Medical Escort Recorder","characterId":"K883","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-12#person-namramwon","detailRoute":"/people/person-0883","birthDate":"2093-02-16","birthday":"02-16","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k883-escort-end-time-recording","name":"Escort end-time recording","rating":45}],"traits":[{"id":"k883-priority","name":"Accountable until escort ends","description":"Nam Ramwon separated escort and patient cars and handed over keys after recording escort departure. Recording guards is not fighting proficiency.","behavior":"Office. Rank: convoy hand. Title: medical convoy registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the medical convoy registrar duty post would stand empty and the City''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k883-accountability","name":"Procedural accountability","description":"Makes responsibility traceable through the documented checks, records, and attendance conditions.","behavior":"Office. Rank: convoy hand. Title: medical convoy registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the medical convoy registrar duty post would stand empty and the City''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Nam Ramwon separated escort and patient cars and handed over keys after recording escort departure. Recording guards is not fighting proficiency.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":50,"Force":-40,"Material":0,"Communal":25,"Principle":25,"Public":15,"Eligibility":10,"Dispersed":40,"Transformative":-10},"desire":{"Longing":15,"Monopoly":-30,"Risk":30,"Display":-15,"Sustained":25,"Orientation":"None","Union":"Monogamy"},"fields":{"Livelihood":"Medical Escort Log and Duty Key Handover","Affiliation":"The Government","Rank":"Escort","Title":"Medical Escort Recorder","Values":"Authority −25 | Openness 50 | Force −40 | Material 0 | Communal 25 | Principle 25 | Publicity 15 | Qualification 10 | Dispersal 40 | Transformation −10","Desires":"Craving 15 | Monopoly −30 | Risk 30 | Display −15 | Continuity 25 | Orientation None | Bonding Monogamous"},"sections":{"Life":"Born on 2093-02-16. Grew up at the Seoul Station registry office. As of the 2126 opening, holds the Medical Escort Records Officer duty, and the post''s succession record remains showing that it opened with the deletion of one line from a double ledger.\n- The dispatch, shift change, maintenance, passage screening, stretcher handover and duty-key records desk at Sinnae 1-dong is proposed as Nam Ramwon''s work reference point for medical escort records and duty-key handover. It is a proposal to cross-check Permanent Winter handover records, and does not fix running trains, new equipment, armament, passage tolls, market monopoly rights, residence, exact facility boundaries, noble title, fief, or possession rights.","Offices":"Rank: Escort. Title: Medical Escort Records Officer. Hands over together the copy of the solicitation returned to the public window and the keys and records of their own duty, making the scope of the handover clear.","Anecdote":"On the day Jang Sehwa goes out on medical escort, Nam Ramwon records the escorted car and the patient car separately in the escort log. Only after writing down everything up to the time the escort ends and withdraws does the officer hand over the duty key. The copy of the solicitation returned to the public window that was left then became the handover standard for the next duty officer.","Relationships":"Hands the copy of the solicitation returned to the public window to a senior duty officer from the same living sphere, and checks it against the next shift''s receipt time within the same duty district.","Ambition":"Seeks to leave the copy of the solicitation returned to the public window as an open handover line that the next shift can verify again.","Fear":"Fears that the receipt time of the copy of the solicitation returned to the public window will be left blank, so that responsibility is shifted onto the patient and passenger lists.","Intervention":"You can appoint a witness to the receipt of the petition copy returned to the public window, or disclose the missing signature box before the next shift."},"biography":"Nam Ramwon, born 2093-02-16, first checks the order of the petition copies returned to the public window. Nam trusts the time of receipt and the signature box more than loud voices.\n\n- Occupation: Mandatory escort records and duty key handover\n- Affiliation: The Government\n- Rank: Escort\n- Title: Mandatory Escort Records Officer\n**Life.** Born on 2093-02-16. Grew up at the Seoul Station Registry. At the 2126 opening, Nam holds the duty post of Mandatory Escort Records Officer, and the succession record for the post notes that it opened with the deletion of one line from the double ledger.\n- The dispatch, shift, maintenance, passage inspection, stretcher handover and duty key record desk in Sinnae 1-dong is proposed as the duty reference point for Nam Ramwon''s mandatory escort records and duty key handover work. It is a proposal to cross-check the Permanent Winter handover records, and it does not fix running trains, new equipment, arms, passage tolls, market monopolies, residence, exact facility boundaries, titles, fiefs, or possession rights.\n\n**Office.** Rank: Escort. Title: Mandatory Escort Records Officer. Hands over the petition copy returned to the public window together with the keys and records of one''s own duty post, making the scope of the handover clear.\n\n**Anecdote.** On the day Jang Sehwa goes out on a mandatory escort, Nam Ramwon records the guarded car and the patient car separately in the escort record. Only after noting down the time the escort is released at the end of the run does Nam hand over the duty key. The copy of the petition returned to the public window that Nam left then became the handover standard for the next duty shift.\n\n**Relationships.** Hands the petition copy returned to the public window to the senior duty officer of the same living sphere, and checks it against the receipt time of the next shift in the same duty sphere.\n\n**Ambition.** Wants to leave the petition copy returned to the public window as a public handover line that the next shift can check again.\n\n**Fear.** Fears that the receipt time of the petition copy returned to the public window will be left blank, and that responsibility will be shifted onto the patient and passenger lists.\n\n**Intervention.** You can appoint a witness to the receipt of the petition copy returned to the public window, or disclose the missing signature box before the next shift.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 50 | Force −40 | Materialism 0 | Community 25 | Principle 25 | Publicity 15 | Qualification 10 | Decentralization 40 | Transformation −10\n- Desires: Longing 15 | Monopoly −30 | Risk 30 | Display −15 | Endurance 25 | Orientation None | Union Monogamy\n:::","relations":{"outgoing":[{"from":"Nam Ramwon","type":"Contract","to":"Gwak Taesan","basis":"Nam Ramwon hands Gwak Taesan the patient car and escort car of the medical convoy, along with the times the escort was absent. Gwak Taesan checks the car keys and the armory seals separately so that taking over the escort does not get mixed up with taking over the patients."}],"incoming":[]}}', '{"id":"person-0883","name":"남람원","title":"의무호송 기록관","position":"의무호송 기록관","characterId":"K883","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-12#인물-남람원","detailRoute":"/people/person-0883","birthDate":"2093-02-16","birthday":"02-16","age":33,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k883-escort-end-time-recording","name":"호위 종료 시각 기록","rating":45}],"traits":[{"id":"k883-priority","name":"호위 종료까지 책임","description":"남람원은 호위 칸과 환자 칸을 나누고 호위가 빠진 시각 뒤에 열쇠를 넘겼다. 호위 기록이 호위 전투 숙련은 아니다.","behavior":"자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"의무호송 기록관 당직이 비면 신내운수의 통행이 노선 면허의 볼모가 되는 것.","relationship":"같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k883-accountability","name":"절차를 통한 책임","description":"확인·기록·입회 조건으로 맡은 업무의 책임을 남긴다.","behavior":"관직. 품계 호송원. 직함은 의무호송 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 의무호송 기록관 당직이 비면 신내운수의 통행이 노선 면허의 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"남람원은 호위 칸과 환자 칸을 나누고 호위가 빠진 시각 뒤에 열쇠를 넘겼다. 호위 기록이 호위 전투 숙련은 아니다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":50,"무력":-40,"물질":0,"공동":25,"원칙":25,"공개":15,"자격":10,"분산":40,"변혁":-10},"desire":{"갈망":15,"독점":-30,"위험":30,"과시":-15,"지속":25,"지향":"무성향","결합":"단혼"},"fields":{"생업":"의무호송 기록·당직 열쇠 인계","소속":"정부","품계":"호송원","직함":"의무호송 기록관","가치관":"권위 −25 | 개방 50 | 무력 −40 | 물질 0 | 공동 25 | 원칙 25 | 공개 15 | 자격 10 | 분산 40 | 변혁 −10","욕망":"갈망 15 | 독점 −30 | 위험 30 | 과시 −15 | 지속 25 | 지향 무성향 | 결합 단혼"},"sections":{"생애":"2093-02-16에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 남람원의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 영구 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·작위·영지·점유권은 확정하지 않는다.","관직":"품계 호송원. 직함은 의무호송 기록관. 공개 창구로 되돌린 청탁 사본과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.","일화":"장세화가 의무호송에 나서는 날, 남람원은 호위가 붙은 칸과 환자 칸을 호송 기록에 따로 적는다. 호송이 끝나 호위가 빠지는 시각까지 받아 적은 뒤에야 그는 당직 열쇠를 넘긴다. 그때 남긴 공개 창구로 되돌린 청탁 사본이 다음 당직의 인수 기준이 되었다.","관계":"같은 생활권 선배 당직에게 공개 창구로 되돌린 청탁 사본을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.","야망":"공개 창구로 되돌린 청탁 사본을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.","공포":"공개 창구로 되돌린 청탁 사본의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.","개입":"공개 창구로 되돌린 청탁 사본의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다."},"biography":"2093-02-16생인 남람원은 공개 창구로 되돌린 청탁 사본의 순서를 먼저 확인한다. 큰소리보다 인수 시각과 서명 칸을 믿는다.\n\n- 생업: 의무호송 기록·당직 열쇠 인계\n- 소속: 정부\n- 품계: 호송원\n- 직함: 의무호송 기록관\n**생애.** 2093-02-16에 태어났다. 서울역 등기소에서 자랐다. 2126년 개막에는 의무호송 기록관 당직을 맡으며, 직위 인수 기록에는 이중 장부 한 줄 삭제로 열렸다이 남아 있다.\n- 신내1동의 배차·교대·정비·통행 심사·들것 인계·당직 열쇠 기록대가 남람원의 의무호송 기록·당직 열쇠 인계 근무 기준점으로 제안되어 있다. 영구 겨울의 인계 기록을 대조하는 제안이며 운행 열차·새 설비·무장·통행세·시장 독점권·거주·정확한 시설 경계·작위·영지·점유권은 확정하지 않는다.\n\n**관직.** 품계 호송원. 직함은 의무호송 기록관. 공개 창구로 되돌린 청탁 사본과 자기 당직의 열쇠·기록을 함께 넘겨 인수 범위를 분명히 한다.\n\n**일화.** 장세화가 의무호송에 나서는 날, 남람원은 호위가 붙은 칸과 환자 칸을 호송 기록에 따로 적는다. 호송이 끝나 호위가 빠지는 시각까지 받아 적은 뒤에야 그는 당직 열쇠를 넘긴다. 그때 남긴 공개 창구로 되돌린 청탁 사본이 다음 당직의 인수 기준이 되었다.\n\n**관계.** 같은 생활권 선배 당직에게 공개 창구로 되돌린 청탁 사본을 넘기고, 같은 근무권의 다음 교대 수령 시각과 맞대어 확인한다.\n\n**야망.** 공개 창구로 되돌린 청탁 사본을 다음 교대가 다시 확인할 수 있는 공개 인계선으로 남기려 한다.\n\n**공포.** 공개 창구로 되돌린 청탁 사본의 수령 시각이 비어 책임이 환자·승객 명단에 떠넘겨지는 일을 두려워한다.\n\n**개입.** 공개 창구로 되돌린 청탁 사본의 인수 증인을 세우거나, 빠진 서명 칸을 다음 교대 전에 공개할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 50 | 무력 −40 | 물질 0 | 공동 25 | 원칙 25 | 공개 15 | 자격 10 | 분산 40 | 변혁 −10\n- 욕망: 갈망 15 | 독점 −30 | 위험 30 | 과시 −15 | 지속 25 | 지향 무성향 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"남람원","type":"계약","to":"곽태산","basis":"남람원은 의료호송의 환자 칸과 호위 칸, 호위가 빠진 시각을 곽태산에게 넘긴다. 곽태산은 칸 열쇠와 무기함 봉인을 따로 확인해 호위 인수가 환자 인수로 섞이지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0884', 'c2ec-ccad-c1a1', '{"id":"person-0884","name":"Sim Nayang","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K884","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-sim-nayang","detailRoute":"/people/person-0884","birthDate":"2096-09-08","birthday":"09-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"document-transcription","name":"Document transcription","rating":45}],"traits":[{"id":"stated-priority","name":"Keeps authorization through transcription","description":"A wet platform authorization was dried and copied. This is the only specific handling episode, so sanitation outcomes are not claimed.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"A wet platform authorization was dried and copied. This is the only specific handling episode, so sanitation outcomes are not claimed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-15,"Openness":40,"Force":-80,"Material":-20,"Communal":20,"Principle":55,"Public":20,"Eligibility":20,"Dispersed":10,"Transformative":-5},"desire":{"Longing":20,"Monopoly":-10,"Risk":-30,"Display":-5,"Sustained":-10,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −15 | Openness 40 | Force −80 | Materialism −20 | Community 20 | Principle 55 | Publicity 20 | Qualification 20 | Decentralization 10 | Transformation −5","Desires":"Longing 20 | Monopoly −10 | Risk −30 | Display −5 | Endurance −10 | Orientation None | Union Contract Cohabitation"},"sections":{"Life":"Born on 2096-09-08. At the 2126 opening, holds the post of Epidemic Control Records Officer, continuing the existing duty shifts and records. The succession record for this post notes that it opened with the deletion of one line from the double ledger.\n- The epidemic-control records and duty key handover desk in Jegi-dong is the duty reference point for Sim Nayang. This placement does not fix residence, exact facility boundaries, titles, fiefs, or possession rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, dried a water-soaked ratification document on a platform and left it as a transcribed copy. That day''s record remained as a handover basis for the next duty officer to confirm.","Relationships":"Sim Nayang delivers the preserved quarantine transcript to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records so that an illegible seal is not used as grounds for release.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the duty chain. Trusts a single line in the ledger more than loud voices.\n\n- Occupation: Epidemic-control records and duty key handover\n- Affiliation: White Cross Society\n- Rank: Resident Physician\n- Title: Epidemic Control Records Officer\n**Life.** Born on 2096-09-08. At the 2126 opening, holds the post of Epidemic Control Records Officer, continuing the existing duty shifts and records. The succession record for this post notes that it opened with the deletion of one line from the double ledger.\n- The epidemic-control records and duty key handover desk in Jegi-dong is the duty reference point for Sim Nayang. This placement does not fix residence, exact facility boundaries, titles, fiefs, or possession rights.\n\n**Office.** Rank: Resident Physician. Title: Epidemic Control Resident Physician. Hands over only the keys and records of one''s own post, and writes the receipt time of the handed-over keys and records in the ledger.\n\n**Anecdote.** In 2125, dried a water-soaked approval document on the platform and preserved it as a transcribed copy. That day''s record remained as the handover basis for the next duty shift to verify.\n\n**Relationships.** Sim Nayang passes the preserved epidemic-control transcription to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records so that an illegible seal is not used as grounds for release.\n\n**Ambition.** Wants to keep the White Cross Society''s ledger continuous from the post of Epidemic Control Resident Physician.\n\n**Fear.** Fears that if the Epidemic Control Resident Physician''s duty goes vacant, the White Cross Society''s passage will become a hostage of Seoul''s internal patron factions.\n\n**Intervention.** You can appoint a witness to the duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −15 | Openness 40 | Force −80 | Materialism −20 | Community 20 | Principle 55 | Publicity 20 | Qualification 20 | Decentralization 10 | Transformation −5\n- Desires: Longing 20 | Monopoly −10 | Risk −30 | Display −5 | Endurance −10 | Orientation None | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Sim Nayang","type":"Contract","to":"Ra Seyeong","basis":"Sim Nayang delivers the preserved quarantine transcript to Ra Seyeong. Ra Seyeong checks the quarantine entry and release records so that an illegible seal is not used as grounds for release."}],"incoming":[]}}', '{"id":"person-0884","name":"심나양","title":"방역 기록관","position":"방역 기록관","characterId":"K884","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-심나양","detailRoute":"/people/person-0884","birthDate":"2096-09-08","birthday":"09-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"document-transcription","name":"문서 필사","rating":45}],"traits":[{"id":"stated-priority","name":"필사로 인준을 남긴다","description":"승강장의 젖은 인준을 말려 필사했다. 문서 처리 행동이 유일하게 구체적이므로 방역 성과는 주장하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"승강장의 젖은 인준을 말려 필사했다. 문서 처리 행동이 유일하게 구체적이므로 방역 성과는 주장하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-15,"개방":40,"무력":-80,"물질":-20,"공동":20,"원칙":55,"공개":20,"자격":20,"분산":10,"변혁":-5},"desire":{"갈망":20,"독점":-10,"위험":-30,"과시":-5,"지속":-10,"지향":"무성향","결합":"계약동거"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −15 | 개방 40 | 무력 −80 | 물질 −20 | 공동 20 | 원칙 55 | 공개 20 | 자격 20 | 분산 10 | 변혁 −5","욕망":"갈망 20 | 독점 −10 | 위험 −30 | 과시 −5 | 지속 −10 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2096-09-08에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 심나양의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 승강장에서 물에 젖은 인준 문서를 말려 필사본으로 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"심나양은 보존한 방역 필사본을 라세영에게 전한다. 라세영은 격리 출입·해제 기록을 확인해 읽히지 않는 날인이 해제 근거로 쓰이지 않게 한다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2096-09-08에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 심나양의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 승강장에서 물에 젖은 인준 문서를 말려 필사본으로 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 심나양은 보존한 방역 필사본을 라세영에게 전한다. 라세영은 격리 출입·해제 기록을 확인해 읽히지 않는 날인이 해제 근거로 쓰이지 않게 한다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −15 | 개방 40 | 무력 −80 | 물질 −20 | 공동 20 | 원칙 55 | 공개 20 | 자격 20 | 분산 10 | 변혁 −5\n- 욕망: 갈망 20 | 독점 −10 | 위험 −30 | 과시 −5 | 지속 −10 | 지향 무성향 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"심나양","type":"계약","to":"라세영","basis":"심나양은 보존한 방역 필사본을 라세영에게 전한다. 라세영은 격리 출입·해제 기록을 확인해 읽히지 않는 날인이 해제 근거로 쓰이지 않게 한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0885', 'b178-ad50-d558-76e7', '{"id":"person-0885","name":"No Maho","title":"Quarantine Clerk","position":"Guui Garrison Quarantine Clerk","rank":"Garrison Soldier","commonTier":"T5","occupation":"Quarantine Log and Duty Key Handover","gender":"Female","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0885","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0885","name":"노마호","title":"검역 서기","position":"구의수비대 검역 서기","rank":"수비대원","commonTier":"T5","occupation":"검역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0885","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0886', 'd558-c9c4-c8fc', '{"id":"person-0886","name":"Ha Aeun","title":"Auction Clerk","position":"Myeongdong Station Election Records Clerk","rank":"Congregationioner","commonTier":"T5","occupation":"Election Records and Handover Log","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0886","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0886","name":"하아은","title":"경매 서기","position":"명동역 선거 기록 서기","rank":"교우","commonTier":"T5","occupation":"선거 기록·인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0886","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0887', 'acfd-d604-d48d', '{"id":"person-0887","name":"Gwak Kahyeon","title":"Audit Recorder","position":"Audit Recorder","rank":"Guild Member","commonTier":"T5","occupation":"Audit Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0887","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0887","name":"곽카현","title":"감사 기록관","position":"감사 기록관","rank":"조합원","commonTier":"T5","occupation":"감사 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0887","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
