INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0918', 'd5c8-c591-cc9c', '{"id":"person-0918","name":"Heo Nau","title":"Warehouse Duty Officer","position":"Myeongdong Station Confirmation Roster Duty Officer","rank":"Congregationioner","commonTier":"T5","occupation":"Confirmation Roster Handover Record","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0918","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0918","name":"허나우","title":"창고 당직","position":"명동역 인준 명부 당직","rank":"교우","commonTier":"T5","occupation":"인준 명부 인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0918","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0919', 'c720-bb34-c1a1-5ebe', '{"id":"person-0919","name":"Yu Mayeong","title":"Utility Tunnel Duty Officer","position":"Utility Tunnel Duty Officer","rank":"Guild Member","commonTier":"T5","occupation":"Utility Tunnel Duty Log · Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0919","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0919","name":"유마영","title":"공동구 당직","position":"공동구 당직","rank":"조합원","commonTier":"T5","occupation":"공동구 당직 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0919","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0920', 'b0a8-c758-b839', '{"id":"person-0920","name":"Nam Aeun","title":"Bridge Passage Herald","position":"Bridge Passage Herald","characterId":"K920","rank":"Clerk","commonTier":"T5","occupation":"Bridge Guard Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#person-nam-aeun","detailRoute":"/people/person-0920","birthDate":"2073-10-10","birthday":"10-10","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":8,"effective":8},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":6,"effective":6}},"skills":[{"id":"k920-ambush-trace-reading","name":"Reading ambush traces","rating":55}],"traits":[{"id":"k920-action-priority","name":"Traces before harm","description":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger.","behavior":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger.","stress":"That the bridge passage courier duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves under Kim Taeun on bridge passage and night-crossing reports.","effects":[]},{"id":"k920-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the bridge passage courier duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves under Kim Taeun on bridge passage and night-crossing reports.","effects":[]}],"narrative":"In 2125, on a ridge patrol, he read the ambush traces first and prevented the harm. By this deed the signature of the bridge passage courier post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":50,"Openness":-10,"Force":10,"Material":25,"Communal":15,"Principle":25,"Public":30,"Eligibility":10,"Dispersed":-60,"Transformative":-25},"desire":{"Longing":10,"Monopoly":-5,"Risk":-5,"Display":10,"Sustained":-10,"Orientation":"None","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City","Livelihood":"Bridge Guard Duty","Rank":"Clerk","Title":"Bridge Passage Herald","Work Location":"Dangsan 2-dong. In 2125, Nam Aeun read the ambush traces on the Seoul hillside road leading from the Amsa Guard Post before anyone else and prevented harm. Now sends night-crossing records separately to Kim Taeun''s bridge watch in Dangsan 2-dong.","Values":"Authority 50 | Openness −10 | Force 10 | Material 25 | Communal 15 | Principle 25 | Publicity 30 | Qualification 10 | Decentralization −60 | Reform −25","Desires":"Craving 10 | Possessiveness −5 | Risk −5 | Display 10 | Persistence −10 | Orientation None | Union Contract Cohabitation"},"sections":{"Life":"Of the 2126 generation. Grew up at the Amsa Guard Post. The post of Bridge Crossing Courier opened after an unauthorized night crossing was caught.\n- Work location: Dangsan 2-dong. In 2125, Nam Aeun read the ambush traces on the Seoul hillside road leading from the Amsa Guard Post before anyone else and prevented harm. Now sends night-crossing records separately to Kim Taeun''s bridge watch in Dangsan 2-dong.","Offices":"Rank: Clerk. Title: Bridge Crossing Courier. In 2125, Nam Aeun read the ambush traces on the Seoul hillside road leading from the Amsa Guard Post before anyone else and prevented harm. Now sends night-crossing records separately to Kim Taeun''s bridge watch in Dangsan 2-dong.","Anecdote":"In 2125, while patrolling the Seoul hillside road leading from the Amsa Guard Post, Nam Aeun found ambush traces first, notified the guard corps, and diverted the travelers.","Relationships":"Under Kim Taeun''s command, handles bridge passage and nighttime river-crossing reports.","Ambition":"From the Bridge Crossing Herald post, he keeps the Water Gate Bureau''s ledger connected without a break.","Fear":"That if the Bridge Passage Courier''s duty shift goes unfilled, the Floodgate Bureau''s passage will become hostage to a major power.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first not to break the watch. Trusts a single line in the ledger over loud talk.\n\n- Affiliation: Free City\n- Livelihood: Bridge guard duty\n- Rank: Clerk\n- Title: Bridge Crossing Courier\n**Life.** Of the 2126 generation. Grew up at the Amsa Guard Post. The post of Bridge Crossing Courier opened after an unauthorized night crossing was caught.\n- Work location: Dangsan 2-dong. In 2125, Nam Aeun read the ambush traces on the Seoul hillside road leading from the Amsa Guard Post before anyone else and prevented harm. Now sends night-crossing records separately to Kim Taeun''s bridge watch in Dangsan 2-dong.\n\n**Office.** Rank: Clerk. Title: Bridge Crossing Courier. In 2125, Nam Aeun read the ambush traces on the Seoul hillside road leading from the Amsa Guard Post before anyone else and prevented harm. Now sends night-crossing records separately to Kim Taeun''s bridge watch in Dangsan 2-dong.\n\n**Anecdote.** In 2125, while patrolling the Seoul hillside road leading from the Amsa Guard Post, Nam Aeun found ambush traces first, notified the guard corps, and diverted the travelers.\n\n**Relationships.** Handles bridge crossings and night-crossing reports under the command of Kim Taeun.\n\n**Ambition.** To keep the Floodgate Bureau''s ledger unbroken from the post of Bridge Crossing Courier.\n\n**Fear.** That if the Bridge Crossing Courier''s watch is left vacant, the Floodgate Bureau''s passage will become a hostage of the river powers.\n\n**Intervention.** Can bring in a witness to the watch handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 50 | Openness −10 | Force 10 | Material 25 | Communal 15 | Principle 25 | Publicity 30 | Qualification 10 | Decentralization −60 | Reform −25\n- Desires: Craving 10 | Possessiveness −5 | Risk −5 | Display 10 | Persistence −10 | Orientation None | Union Contract Cohabitation\n:::","directLiege":{"personId":"K003","name":"Gim Tae-un","courtId":"court:K003","effectiveYear":2126},"relations":{"outgoing":[{"from":"Nam Aeun","type":"Command","to":"Gim Tae-un","basis":"Handles bridge traffic and night-crossing reports under Gim Taeun''s command"}],"incoming":[]}}', '{"id":"person-0920","name":"남아은","title":"교량 통행 전령","position":"교량 통행 전령","characterId":"K920","rank":"주사","commonTier":"T5","occupation":"교량 경비 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-남아은","detailRoute":"/people/person-0920","birthDate":"2073-10-10","birthday":"10-10","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":8,"effective":8},"intrigue":{"base":11,"effective":11},"learning":{"base":8,"effective":8},"prowess":{"base":6,"effective":6}},"skills":[{"id":"k920-ambush-trace-reading","name":"매복 흔적 확인","rating":55}],"traits":[{"id":"k920-action-priority","name":"피해 전 흔적","description":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","behavior":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다.","stress":"교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","effects":[]},{"id":"k920-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","effects":[]}],"narrative":"2125년 능선 초계 중 매복 흔적을 먼저 읽어 피해를 막았다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":50,"개방":-10,"무력":10,"물질":25,"공동":15,"원칙":25,"공개":30,"자격":10,"분산":-60,"변혁":-25},"desire":{"갈망":10,"독점":-5,"위험":-5,"과시":10,"지속":-10,"지향":"무성향","결합":"계약동거"},"fields":{"소속":"자유도시","생업":"교량 경비 당직","품계":"주사","직함":"교량 통행 전령","업무 위치":"당산2동. 남아은은 2125년 암사 경비 초소에서 이어지는 서울 언덕길의 매복 흔적을 먼저 읽어 피해를 막았다. 지금은 김태운의 당산2동 교량 당직에 야간 도하 기록을 별도로 보낸다.","가치관":"권위 50 | 개방 −10 | 무력 10 | 물질 25 | 공동 15 | 원칙 25 | 공개 30 | 자격 10 | 분산 −60 | 변혁 −25","욕망":"갈망 10 | 독점 −5 | 위험 −5 | 과시 10 | 지속 −10 | 지향 무성향 | 결합 계약동거"},"sections":{"생애":"2126년 세대. 암사 경비 초소에서 자랐다. 교량 통행 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 업무 위치: 당산2동. 남아은은 2125년 암사 경비 초소에서 이어지는 서울 언덕길의 매복 흔적을 먼저 읽어 피해를 막았다. 지금은 김태운의 당산2동 교량 당직에 야간 도하 기록을 별도로 보낸다.","관직":"품계 주사. 직함은 교량 통행 전령이다. 남아은은 2125년 암사 경비 초소에서 이어지는 서울 언덕길의 매복 흔적을 먼저 읽어 피해를 막았다. 지금은 김태운의 당산2동 교량 당직에 야간 도하 기록을 별도로 보낸다.","일화":"2125년 암사 경비 초소에서 이어지는 서울 언덕길을 돌던 남아은은 매복 흔적을 먼저 찾아 경비대에 알리고 통행 인원을 돌렸다.","관계":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.","야망":"교량 통행 전령 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 교량 경비 당직\n- 품계: 주사\n- 직함: 교량 통행 전령\n**생애.** 2126년 세대. 암사 경비 초소에서 자랐다. 교량 통행 전령 자리는 야간 무단 도하 적발로 열렸다.\n- 업무 위치: 당산2동. 남아은은 2125년 암사 경비 초소에서 이어지는 서울 언덕길의 매복 흔적을 먼저 읽어 피해를 막았다. 지금은 김태운의 당산2동 교량 당직에 야간 도하 기록을 별도로 보낸다.\n\n**관직.** 품계 주사. 직함은 교량 통행 전령이다. 남아은은 2125년 암사 경비 초소에서 이어지는 서울 언덕길의 매복 흔적을 먼저 읽어 피해를 막았다. 지금은 김태운의 당산2동 교량 당직에 야간 도하 기록을 별도로 보낸다.\n\n**일화.** 2125년 암사 경비 초소에서 이어지는 서울 언덕길을 돌던 남아은은 매복 흔적을 먼저 찾아 경비대에 알리고 통행 인원을 돌렸다.\n\n**관계.** 김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡는다.\n\n**야망.** 교량 통행 전령 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 교량 통행 전령 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 50 | 개방 −10 | 무력 10 | 물질 25 | 공동 15 | 원칙 25 | 공개 30 | 자격 10 | 분산 −60 | 변혁 −25\n- 욕망: 갈망 10 | 독점 −5 | 위험 −5 | 과시 10 | 지속 −10 | 지향 무성향 | 결합 계약동거\n:::","directLiege":{"personId":"K003","name":"김태운","courtId":"court:K003","effectiveYear":2126},"relations":{"outgoing":[{"from":"남아은","type":"지휘","to":"김태운","basis":"김태운의 지휘 아래 교량 통행과 야간 도하 보고를 맡음"}],"incoming":[]}}');
