INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0940', 'c7a5-b2e8-c591-5f35', '{"id":"person-0940","name":"Jang Bawon","title":"Water Supply Escort Patrol","position":"Eastern Patrol","rank":"Sergeant","commonTier":"T5","occupation":"Access Security · Roster Recheck","gender":"Male","stage":"S4","state":"S05","stateName":"Eastern Command","detailRoute":"/people/person-0940","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0940","name":"장바원","title":"상수 호위 순찰대","position":"동부 순찰대","rank":"병장","commonTier":"T5","occupation":"출입 경비·명부 재점검","gender":"남성","stage":"S4","state":"S05","stateName":"동방사","detailRoute":"/people/person-0940","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0941', 'c784-c870-c591-6797', '{"id":"person-0941","name":"Im Doru","title":"Ratification Registrar","position":"Ratification Registrar","rank":"Clerk","commonTier":"T5","occupation":"Forged Copy Disposal & Original Preservation","gender":"Male","stage":"S4","state":"S06","stateName":"Government of the Republic of Korea","detailRoute":"/people/person-0941","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0941","name":"임돌우","title":"인준 기록관","position":"인준 기록관","rank":"주사","commonTier":"T5","occupation":"위조 사본 폐기·원본 보관","gender":"남성","stage":"S4","state":"S06","stateName":"대한민국정부","detailRoute":"/people/person-0941","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0942', NULL, '{"id":"person-0942","name":"George Anderson","title":"Escort Courier","position":"Escort Courier","characterId":"K942","rank":"Clerk","commonTier":"T5","occupation":"Ticketless Train Departure and Signature Confirmation","gender":"Male","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-07#person-George-Anderson","detailRoute":"/people/person-0942","birthDate":"2092-02-22","birthday":"02-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure-document-check","name":"Departure document checking","rating":45}],"traits":[{"id":"k942-disposition","name":"Caution about unverified occupancy","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Office. Rank: registrar. Title: convoy courier. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the convoy courier duty post would stand empty, interrupting dispatch and transshipment handovers in Yongsan and passing unverified completion records to water-supply, medical-care and goods handover counterparts within Seoul.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. George Anderson reports missing dispatch sheets and departure signatures to Léa Martin. Léa checks posted copies so unverified departures do not become regular entries in subsequent slot occupation.","effects":[]},{"id":"k942-choice","name":"Refusing unsigned departures","description":"Anecdote. In 2125 he stopped a dispatch-sheetless train and blocked an unsigned departure. By this deed the signature of the convoy courier post rose into the ledger.","behavior":"Relations. Bound by handover to the senior duty line of the same living quarters. George Anderson reports missing dispatch sheets and departure signatures to Léa Martin. Léa checks posted copies so unverified departures do not become regular entries in subsequent slot occupation.","stress":"Fear. That the convoy courier duty post would stand empty, interrupting dispatch and transshipment handovers in Yongsan and passing unverified completion records to water-supply, medical-care and goods handover counterparts within Seoul.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. George Anderson reports missing dispatch sheets and departure signatures to Léa Martin. Léa checks posted copies so unverified departures do not become regular entries in subsequent slot occupation.","effects":[]}],"narrative":"Blocks an unsigned departure and notifies Lea. Lea checks the posted copies; the courier is not granted full ledger-review expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":10,"Openness":40,"Force":0,"Material":30,"Communal":0,"Principle":-10,"Public":0,"Eligibility":40,"Dispersed":0,"Transformative":5},"desire":{"Longing":30,"Monopoly":10,"Risk":-20,"Display":15,"Sustained":-10,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Affiliation":"The Government","Rank":"Clerk","Livelihood":"Ticketless Train Departure and Signature Confirmation","Title":"Escort Courier","Values":"Authority 10 | Openness 40 | Force 0 | Materialism 30 | Communality 0 | Principle −10 | Publicity 0 | Credentials 40 | Decentralization 0 | Transformation 5","Desires":"Craving 30 | Possessiveness 10 | Risk −20 | Display 15 | Endurance −10 | Orientation: opposite-sex | Bonding: non-exclusive"},"sections":{"Life":"Born in 2092, George Anderson takes up the Escort Courier''s work in the opening period of 2126. He grew up at the Sinnae transfer duty station. The Escort Courier work began with stopping a ticketless departing train. His European-American family has its roots in the Yongsan-Itaewon living area. Edward Anderson handled U.S. Army supply work in Yongsan-Itaewon in 2026 and went through the severing of the communication lines. The family passed its records of lodgings and goods handovers to the next generation, and George Anderson''s parents'' generation checked those records against the living ledgers of their own time. They speak English at home and Korean in daily life and at work.\n- George Anderson''s work of checking ticketless train departures and signatures is connected to Hangangno-dong.","Offices":"Rank: Senior Clerk. Title: Escort Courier. He hands over only the keys and records of his own post and does not invent authority he lacks.","Anecdote":"In 2125 he stopped a train that had no dispatch slip and prevented a departure without a signature. After this act, the Escort Courier post''s signature was entered in the ledger.","Relationships":"George Anderson reports omissions of the dispatch slip and departure signature to the records officer. The records officer checks the posted copy so that an unconfirmed departure does not carry over as a normal record of occupying a later slot.","Ambition":"He links the Escort Courier''s records of checking ticketless train departures and signatures to the Transfer Bureau ledger, so that the next duty officer checks the same records.","Fear":"That if the Escort Courier duty falls vacant, the dispatch and transshipment handovers of Yongsan will be cut off, and unverified completion records will pass to the water-supply, medical, and goods-handover counterparts within Seoul.","Intervention":"He can bring in a witness to the duty handover or expose an empty key."},"biography":"George Anderson handles departure and signature verification for ticketless trains. George Anderson reports missing dispatch sheets and departure signatures to the records clerk.\n\n- Affiliation: Transfer Bureau\n- Rank: Clerk\n- Occupation: Ticketless train departure and signature verification\n- Title: Escort Courier\n**Life.** Born in 2092, George Anderson takes up the Escort Courier duties in the 2126 opening period. He grew up at the Sinnae transfer duty post. The Escort Courier work began after he stopped a ticketless departing train. His European-American family has roots in the Yongsan–Itaewon living sphere. In 2026, Edward Anderson handled U.S. Army supply work in Yongsan–Itaewon and lived through the severing of communication lines. The family passed records of their dwellings and goods handovers to the next generation, and George Anderson''s parents'' generation checked those records against the living ledgers of their own day. They speak English at home and Korean in daily life and at work.\n- George Anderson''s work of verifying ticketless train departures and signatures is tied to Hangangno-dong.\n\n**Office.** Rank: Clerk. Title: Escort Courier. He hands over only the keys and records of his own post, and does not invent authority he does not have.\n\n**Anecdote.** In 2125 he stopped a train that had no dispatch sheet and prevented an unsigned departure. After this act, the Escort Courier post''s signature was entered in the ledger.\n\n**Relations.** George Anderson reports missing dispatch sheets and departure signatures to the records clerk. The records clerk checks the posted copy so that an unconfirmed departure does not carry over as a normal record of later window occupancy.\n\n**Ambition.** To link the Escort Courier''s records of ticketless train departure and signature verification to the Transfer Bureau''s ledger, so that the next duty shift checks the same records.\n\n**Fear.** That if the Escort Courier duty falls empty, the dispatch and transfer handover at Yongsan will break, and unverified completion records will pass to counterparts in Seoul for water supply, medical care, and goods handover.\n\n**Intervention.** Can set a witness at a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 10 | Openness 40 | Force 0 | Material 30 | Communal 0 | Principle −10 | Publicity 0 | Qualification 40 | Dispersion 0 | Transformation 5\n- Desires: Craving 30 | Monopoly 10 | Risk −20 | Display 15 | Persistence −10 | Orientation: opposite-sex | Bonding: non-exclusive\n:::","relations":{"outgoing":[],"incoming":[]}}', '{"id":"person-0942","name":"조지 앤더슨","title":"호송 전령","position":"호송 전령","characterId":"K942","rank":"주사","commonTier":"T5","occupation":"무표 열차 출발·서명 확인","gender":"남성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-07#인물-조지 앤더슨","detailRoute":"/people/person-0942","birthDate":"2092-02-22","birthday":"02-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure-document-check","name":"출발 문서 확인","rating":45}],"traits":[{"id":"k942-disposition","name":"미확인 점유 경계","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"관직. 품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 조지 앤더슨은 배차표·출발 서명 누락을 레아 마르탱에게 알린다. 레아 마르탱은 게시 사본을 확인해 미확인 출발이 후속 창 점유의 정상 기록으로 이어지지 않게 한다.","effects":[]},{"id":"k942-choice","name":"서명 없는 출발 거부","description":"일화. 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 호송 전령 자리의 서명이 장부에 올랐다.","behavior":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 조지 앤더슨은 배차표·출발 서명 누락을 레아 마르탱에게 알린다. 레아 마르탱은 게시 사본을 확인해 미확인 출발이 후속 창 점유의 정상 기록으로 이어지지 않게 한다.","stress":"공포. 호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 조지 앤더슨은 배차표·출발 서명 누락을 레아 마르탱에게 알린다. 레아 마르탱은 게시 사본을 확인해 미확인 출발이 후속 창 점유의 정상 기록으로 이어지지 않게 한다.","effects":[]}],"narrative":"서명 없는 출발을 막고 레아에게 알린다. 게시 사본 확인은 레아가 하며 전령에게 원장 심사 전체를 주지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":10,"개방":40,"무력":0,"물질":30,"공동":0,"원칙":-10,"공개":0,"자격":40,"분산":0,"변혁":5},"desire":{"갈망":30,"독점":10,"위험":-20,"과시":15,"지속":-10,"지향":"이성","결합":"비독점"},"fields":{"소속":"환적국","품계":"주사","생업":"무표 열차 출발·서명 확인","직함":"호송 전령","가치관":"권위 10 | 개방 40 | 무력 0 | 물질 30 | 공동 0 | 원칙 −10 | 공개 0 | 자격 40 | 분산 0 | 변혁 5","욕망":"갈망 30 | 독점 10 | 위험 −20 | 과시 15 | 지속 −10 | 지향 이성 | 결합 비독점"},"sections":{"생애":"2092년생인 조지 앤더슨은 2126년 개막기에 호송 전령 업무를 맡는다. 신내 환승 당직에서 자랐다. 호송 전령 업무는 무표 출발 열차 저지를 계기로 시작됐다. 유럽계 미국인 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 에드워드 앤더슨은 2026년 용산·이태원에서 미 육군 보급 업무를 맡다가 연락망 단절을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 조지 앤더슨의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 영어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 조지 앤더슨의 무표 열차 출발·서명 확인 업무는 한강로동과 연결된다.","관직":"품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.","일화":"2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 행동을 계기로 호송 전령 자리의 서명이 장부에 올랐다.","관계":"조지 앤더슨은 배차표·출발 서명 누락을 기록 담당자에게 알린다. 기록 담당자는 게시 사본을 확인해 미확인 출발이 후속 창 점유의 정상 기록으로 이어지지 않게 한다.","야망":"호송 전령 업무의 무표 열차 출발·서명 확인 기록을 환적국 장부와 이어, 다음 당직이 같은 기록을 확인하게 한다.","공포":"호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.","개입":"당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"조지 앤더슨은 무표 열차 출발·서명 확인 업무를 맡는다. 조지 앤더슨은 배차표·출발 서명 누락을 기록 담당자에게 알린다.\n\n- 소속: 환적국\n- 품계: 주사\n- 생업: 무표 열차 출발·서명 확인\n- 직함: 호송 전령\n**생애.** 2092년생인 조지 앤더슨은 2126년 개막기에 호송 전령 업무를 맡는다. 신내 환승 당직에서 자랐다. 호송 전령 업무는 무표 출발 열차 저지를 계기로 시작됐다. 유럽계 미국인 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 에드워드 앤더슨은 2026년 용산·이태원에서 미 육군 보급 업무를 맡다가 연락망 단절을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 조지 앤더슨의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 영어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 조지 앤더슨의 무표 열차 출발·서명 확인 업무는 한강로동과 연결된다.\n\n**관직.** 품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.\n\n**일화.** 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 행동을 계기로 호송 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 조지 앤더슨은 배차표·출발 서명 누락을 기록 담당자에게 알린다. 기록 담당자는 게시 사본을 확인해 미확인 출발이 후속 창 점유의 정상 기록으로 이어지지 않게 한다.\n\n**야망.** 호송 전령 업무의 무표 열차 출발·서명 확인 기록을 환적국 장부와 이어, 다음 당직이 같은 기록을 확인하게 한다.\n\n**공포.** 호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.\n\n**개입.** 당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 10 | 개방 40 | 무력 0 | 물질 30 | 공동 0 | 원칙 −10 | 공개 0 | 자격 40 | 분산 0 | 변혁 5\n- 욕망: 갈망 30 | 독점 10 | 위험 −20 | 과시 15 | 지속 −10 | 지향 이성 | 결합 비독점\n:::","relations":{"outgoing":[],"incoming":[]}}');
