INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0947', 'd669-c7a5-c218-9ec3', '{"id":"person-0947","name":"Hwang Geumjin","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0947","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0947","name":"황금진","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0947","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0948', 'c548-c21c-d765', '{"id":"person-0948","name":"An Seomin","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Logistics Merchant","characterId":"K948","rank":"Resident","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#inmul-an-seomin","detailRoute":"/people/person-0948","birthDate":"2096-11-04","birthday":"11-04","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"prescription-quantity-allocation","name":"Prescription quantity allocation","rating":50}],"traits":[{"id":"stated-priority","name":"Half portions for everyone","description":"Scarcity led to halved prescriptions for everyone. Allocation judgment has evidence; sustained procurement outcomes do not.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Scarcity led to halved prescriptions for everyone. Allocation judgment has evidence; sustained procurement outcomes do not.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":30,"Force":-50,"Material":0,"Communal":15,"Principle":30,"Public":10,"Eligibility":20,"Dispersed":15,"Transformative":-15},"desire":{"Longing":15,"Monopoly":-30,"Risk":-30,"Display":20,"Sustained":5,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −25 | Openness 30 | Force −50 | Material 0 | Communal 15 | Principle 30 | Publicity 10 | Qualification 20 | Dispersion 15 | Transformation −15","Desires":"Craving 15 | Monopoly −30 | Risk −30 | Display 20 | Persistence 5 | Orientation: opposite-sex | Bonding: multi-partner"},"sections":{"Life":"Born on 2096-11-04. As of the 2126 opening, takes on the Herb Logistics Dealer''s duties, continuing the existing duty shifts and records. The succession record of that post opened with a counterfeit medicine seal.\n- The herb management records and duty key handover desk in Jegi-dong is taken as An Seomin''s work reference point. This placement does not fix a residence, exact facility boundaries, rank of nobility, domain, or right of possession.","Offices":"Rank: Resident. Title: Medicinal Herb Management Resident. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, amid a herb shortage, he halved the prescription quantities and shared them out to everyone. That day''s record remained as handover evidence for the next watch to verify.","Relationships":"An Seomin hands the herb usage amounts and the remaining custody records to Dong Juha. Dong Juha checks origin, drying date, and the treatment assignment seal, and inspects the next supply.","Ambition":"From the post of Medicinal Herb Management Resident, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that if the Medicinal Herb Management Resident''s watch falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first to keep the duty unbroken. Trusts a single line in the ledger more than loud talk.\n\n- Occupation: Herb management records and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Herb Logistics Dealer\n**Life.** Born on 2096-11-04. As of the 2126 opening, takes on the Herb Logistics Dealer''s duties, continuing the existing duty shifts and records. The succession record of that post opened with a counterfeit medicine seal.\n- The herb management records and duty key handover desk in Jegi-dong is taken as An Seomin''s work reference point. This placement does not fix a residence, exact facility boundaries, rank of nobility, domain, or right of possession.\n\n**Office.** Rank: Resident. Title: Herb Management Resident. Hands over only the keys and records of his own post, and writes the time of receipt of the handed-over keys and records in the ledger.\n\n**Anecdote.** In 2125, because of a herb shortage, the prescribed amounts were halved and divided among everyone. The record of that day remained as a basis for handover for the next duty shift to check.\n\n**Relations.** An Seomin hands herb usage and the remaining management records to Dong Juha. Dong Juha checks the place of origin, the drying date, and the medical-assignment seal to inspect the next supply.\n\n**Ambition.** To keep the White Cross Order''s ledger unbroken from the post of Herb Management Resident.\n\n**Fear.** If the Herb Management Resident duty falls empty, he fears that the White Cross Order''s passage will become a hostage of the backing powers within Seoul.\n\n**Intervention.** Can set a witness at a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 30 | Force −50 | Material 0 | Communal 15 | Principle 30 | Publicity 10 | Qualification 20 | Dispersion 15 | Transformation −15\n- Desires: Craving 15 | Monopoly −30 | Risk −30 | Display 20 | Persistence 5 | Orientation: opposite-sex | Bonding: multi-partner\n:::","relations":{"outgoing":[{"from":"An Seomin","type":"Contract","to":"Dong Juha","basis":"An Seomin hands the herb usage amounts and the remaining custody records to Dong Juha. Dong Juha checks origin, drying date, and the treatment assignment seal, and inspects the next supply."}],"incoming":[]}}', '{"id":"person-0948","name":"안서민","title":"약재 물류상","position":"약재 물류상","characterId":"K948","rank":"수련의","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-안서민","detailRoute":"/people/person-0948","birthDate":"2096-11-04","birthday":"11-04","age":30,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"prescription-quantity-allocation","name":"처방량 배분","rating":50}],"traits":[{"id":"stated-priority","name":"모두에게 반씩","description":"약재 부족 때 처방량을 반으로 나눠 모두에게 줬다. 배분 판단의 근거는 있으나 지속적인 조달 성과까지는 없다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"약재 부족 때 처방량을 반으로 나눠 모두에게 줬다. 배분 판단의 근거는 있으나 지속적인 조달 성과까지는 없다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c548-c21c-d765","name":"순흥 안씨","crest":"clan-crests/c548-c21c-d765.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":30,"무력":-50,"물질":0,"공동":15,"원칙":30,"공개":10,"자격":20,"분산":15,"변혁":-15},"desire":{"갈망":15,"독점":-30,"위험":-30,"과시":20,"지속":5,"지향":"이성","결합":"다자"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"약재 물류상","가치관":"권위 −25 | 개방 30 | 무력 −50 | 물질 0 | 공동 15 | 원칙 30 | 공개 10 | 자격 20 | 분산 15 | 변혁 −15","욕망":"갈망 15 | 독점 −30 | 위험 −30 | 과시 20 | 지속 5 | 지향 이성 | 결합 다자"},"sections":{"생애":"2096-11-04에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 안서민의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 약재 부족으로 처방량을 반으로 나눠 모두에게 나눴다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"안서민은 약재 사용량과 남은 관리 기록을 동주하에게 넘긴다. 동주하는 원산지·건조 일자와 진료 배정 날인을 확인해 다음 공급을 검수한다.","야망":"약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 약재 물류상\n**생애.** 2096-11-04에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구를 안서민의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 약재 부족으로 처방량을 반으로 나눠 모두에게 나눴다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 안서민은 약재 사용량과 남은 관리 기록을 동주하에게 넘긴다. 동주하는 원산지·건조 일자와 진료 배정 날인을 확인해 다음 공급을 검수한다.\n\n**야망.** 약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 30 | 무력 −50 | 물질 0 | 공동 15 | 원칙 30 | 공개 10 | 자격 20 | 분산 15 | 변혁 −15\n- 욕망: 갈망 15 | 독점 −30 | 위험 −30 | 과시 20 | 지속 5 | 지향 이성 | 결합 다자\n:::","relations":{"outgoing":[{"from":"안서민","type":"계약","to":"동주하","basis":"안서민은 약재 사용량과 남은 관리 기록을 동주하에게 넘긴다. 동주하는 원산지·건조 일자와 진료 배정 날인을 확인해 다음 공급을 검수한다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0949', 'b958-bb38-d654-67f3', '{"id":"person-0949","name":"Ryu Soryeon","title":"Outpost Courier","position":"Agwansa Outpost Courier","rank":"Sergeant","commonTier":"T5","occupation":"Outpost Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0949","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0949","name":"류솔연","title":"초소 전령","position":"아관사 초소 전령","rank":"병장","commonTier":"T5","occupation":"초소 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0949","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0950', 'd64d-b0a8-c591', '{"id":"person-0950","name":"Hong Guwon","title":"Escort Logistics Merchant","position":"Myeongdong Station Relief Supplies Duty","rank":"Congregationioner","commonTier":"T5","occupation":"Relief Supplies Handover Records","gender":"Male","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0950","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}', '{"id":"person-0950","name":"홍구원","title":"호송 물류상","position":"명동역 구휼 물자 당직","rank":"교우","commonTier":"T5","occupation":"구휼 물자 인수인계 기록","gender":"남성","stage":"S4","state":"S15","stateName":"Arc","detailRoute":"/people/person-0950","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0951', 'ace0-d55c-c591', '{"id":"person-0951","name":"Go Gangho","title":"Escort Patrol","position":"Escort Patrol","rank":"Guild Member","commonTier":"T5","occupation":"Escort Patrol Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S16","stateName":"Jeongdong Federation","detailRoute":"/people/person-0951","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0951","name":"고강호","title":"호송 순찰대","position":"호송 순찰대","rank":"조합원","commonTier":"T5","occupation":"호송 순찰 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S16","stateName":"Arc","detailRoute":"/people/person-0951","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0952', 'bb38-b0a8-d3c9-6587', '{"id":"person-0952","name":"Mun Summin","title":"Ration District Clerk","position":"Ration District Clerk","characterId":"K952","rank":"Clerk","commonTier":"T5","occupation":"Water Distribution Duty","gender":"Male","stage":"S4","state":"free-city","stateName":"Free City","sourceRoute":"/world/Cast-State-01#inmul-mun-supmin","detailRoute":"/people/person-0952","birthDate":"2070-10-05","birthday":"10-05","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k952-release-discussion","name":"Release discussion","rating":50}],"traits":[{"id":"k952-action-priority","name":"Overnight release discussion","description":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","behavior":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]},{"id":"k952-bounded-handover","name":"Duty linked by records","description":"Passes keys and records to the next shift without enlarging authority.","behavior":"Passes keys and records to the next shift without enlarging authority.","stress":"That the ration district clerk duty post would stand empty and the Compact''s passage would become a hostage of the great powers.","relationship":"Serves as a ration clerk under I Seodam and manages the water allocation shift.","effects":[]}],"narrative":"In the 2125 drought he shared the upstream reservoir release volume with the ration representative through the night. By this deed the signature of the ration district clerk post rose into the ledger. The brief action and handover support only limited strengths; no unrelated proficiency or numeric trait bonus is issued.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":55,"Openness":-5,"Force":15,"Material":45,"Communal":20,"Principle":5,"Public":5,"Eligibility":-5,"Dispersed":-50,"Transformative":-30},"desire":{"Longing":15,"Monopoly":0,"Risk":10,"Display":-10,"Sustained":15,"Orientation":"Reason","Union":"Polyamorous"},"fields":{"Affiliation":"Free City","Livelihood":"Water Distribution Duty","Rank":"Clerk","Title":"Ration District Clerk","Work Location":"Sinjeong 2-dong. During the 2125 drought, Mun Supmin wrote down the water level of Seoul''s ration reservoir side by side with the requested discharge volume alongside the ration representative, and handed it to I Seodam''s Sinjeong 2-dong ration ledger.","Values":"Authority 55 | Openness −5 | Force 15 | Material 45 | Communal 20 | Principle 5 | Publicity 5 | Qualification −5 | Dispersion −50 | Transformation −30","Desires":"Craving 15 | Monopoly 0 | Risk 10 | Display −10 | Persistence 15 | Orientation: opposite-sex | Bonding: multi-partner"},"sections":{"Life":"Generation of 2126. Grew up at the Yeongdeungpo water purification post. The post of Ration District Clerk opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. During the 2125 drought, Mun Supmin wrote down the water level of Seoul''s ration reservoir side by side with the requested discharge volume alongside the ration representative, and handed it to I Seodam''s Sinjeong 2-dong ration ledger.","Offices":"Rank: Clerk. Title: Ration District Clerk. During the 2125 drought, Mun Supmin wrote down the water level of Seoul''s ration reservoir side by side with the requested discharge volume alongside the ration representative, and handed it to I Seodam''s Sinjeong 2-dong ration ledger.","Anecdote":"During the 2125 drought, Mun Supmin cross-checked the water level of Seoul''s ration reservoir and the requested discharge volume against the ration representative and handed them to I Seodam.","Relationships":"Works as Lee Seodam''s Ration District Clerk and takes the water distribution watch.","Ambition":"In the post of Ration District Clerk, keeps the Water Gate Bureau''s ledger linked without a break.","Fear":"That the Water Gate Bureau''s passage becomes a hostage of the great powers if the Ration District Clerk''s watch is left vacant.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"Chooses first to keep the duty unbroken. Trusts a single line in the ledger more than loud talk.\n\n- Affiliation: Water Gate Bureau\n- Occupation: Water distribution duty\n- Rank: Clerk\n- Title: Ration District Clerk\n**Life.** Generation of 2126. Grew up at the Yeongdeungpo water purification post. The post of Ration District Clerk opened through a valve signature on the Night of Muddy Water.\n- Work location: Sinjeong 2-dong. During the 2125 drought, Mun Supmin wrote down the water level of Seoul''s ration reservoir side by side with the requested discharge volume alongside the ration representative, and handed it to I Seodam''s Sinjeong 2-dong ration ledger.\n\n**Office.** Rank: Clerk. Title: Ration District Clerk. During the 2125 drought, Mun Supmin wrote down the water level of Seoul''s ration reservoir side by side with the requested discharge volume alongside the ration representative, and handed it to I Seodam''s Sinjeong 2-dong ration ledger.\n\n**Anecdote.** During the 2125 drought, Mun Supmin cross-checked the water level of Seoul''s ration reservoir and the requested discharge volume against the ration representative and handed them to I Seodam.\n\n**Relations.** Works as I Seodam''s Ration District Clerk and takes on the water distribution duty.\n\n**Ambition.** To keep the Water Gate Bureau''s ledger unbroken from the post of Ration District Clerk.\n\n**Fear.** That if the Ration District Clerk duty falls empty, the Water Gate Bureau''s passage will become a hostage of a great power.\n\n**Intervention.** Can set a witness at a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 55 | Openness −5 | Force 15 | Material 45 | Communal 20 | Principle 5 | Publicity 5 | Qualification −5 | Dispersion −50 | Transformation −30\n- Desires: Craving 15 | Monopoly 0 | Risk 10 | Display −10 | Persistence 15 | Orientation: opposite-sex | Bonding: multi-partner\n:::","directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"Mun Summin","type":"Command","to":"I Seo-dam","basis":"Serves as clerk of Yi Seodam''s ration district and holds the water distribution watch"}],"incoming":[]}}', '{"id":"person-0952","name":"문숲민","title":"배급구역 서기","position":"배급구역 서기","characterId":"K952","rank":"주사","commonTier":"T5","occupation":"급수 배분 당직","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시","sourceRoute":"/world/Cast-State-01#인물-문숲민","detailRoute":"/people/person-0952","birthDate":"2070-10-05","birthday":"10-05","age":56,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":3,"effective":3}},"skills":[{"id":"k952-release-discussion","name":"방류량 협의","rating":50}],"traits":[{"id":"k952-action-priority","name":"밤샘 방류 논의","description":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","behavior":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]},{"id":"k952-bounded-handover","name":"기록으로 잇는 당직","description":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","behavior":"열쇠와 기록을 다음 당직에 넘기며 권한을 늘리지 않는다.","stress":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","relationship":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","effects":[]}],"narrative":"2125년 가뭄에 상류 저수지 방류량을 두고 배급 대표와 밤새 나눴다. 짧은 행위와 인수인계가 근거여서 다른 분야의 숙련이나 보정은 발급하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":55,"개방":-5,"무력":15,"물질":45,"공동":20,"원칙":5,"공개":5,"자격":-5,"분산":-50,"변혁":-30},"desire":{"갈망":15,"독점":0,"위험":10,"과시":-10,"지속":15,"지향":"이성","결합":"다자"},"fields":{"소속":"자유도시","생업":"급수 배분 당직","품계":"주사","직함":"배급구역 서기","업무 위치":"신정2동. 문숲민은 2125년 가뭄에 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 맞대어 적고 이서담의 신정2동 배급 장부에 넘긴다.","가치관":"권위 55 | 개방 −5 | 무력 15 | 물질 45 | 공동 20 | 원칙 5 | 공개 5 | 자격 −5 | 분산 −50 | 변혁 −30","욕망":"갈망 15 | 독점 0 | 위험 10 | 과시 −10 | 지속 15 | 지향 이성 | 결합 다자"},"sections":{"생애":"2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 문숲민은 2125년 가뭄에 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 맞대어 적고 이서담의 신정2동 배급 장부에 넘긴다.","관직":"품계 주사. 직함은 배급구역 서기이다. 문숲민은 2125년 가뭄에 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 맞대어 적고 이서담의 신정2동 배급 장부에 넘긴다.","일화":"2125년 가뭄에 문숲민은 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 대조해 이서담에게 넘겼다.","관계":"이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.","야망":"배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.","공포":"배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 소속: 자유도시\n- 생업: 급수 배분 당직\n- 품계: 주사\n- 직함: 배급구역 서기\n**생애.** 2126년 세대. 영등포 정수 당직에서 자랐다. 배급구역 서기 자리는 탁수 밤의 밸브 서명으로 열렸다.\n- 업무 위치: 신정2동. 문숲민은 2125년 가뭄에 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 맞대어 적고 이서담의 신정2동 배급 장부에 넘긴다.\n\n**관직.** 품계 주사. 직함은 배급구역 서기이다. 문숲민은 2125년 가뭄에 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 맞대어 적고 이서담의 신정2동 배급 장부에 넘긴다.\n\n**일화.** 2125년 가뭄에 문숲민은 서울 배급 저수조의 수위와 요청 방류량을 배급 대표와 대조해 이서담에게 넘겼다.\n\n**관계.** 이서담의 배급구역 서기로 일하며 급수 배분 당직을 맡는다.\n\n**야망.** 배급구역 서기 자리에서 수문국의 장부를 끊기지 않게 잇는다.\n\n**공포.** 배급구역 서기 당직이 비면 수문국의 통행이 강국 볼모가 되는 것.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 55 | 개방 −5 | 무력 15 | 물질 45 | 공동 20 | 원칙 5 | 공개 5 | 자격 −5 | 분산 −50 | 변혁 −30\n- 욕망: 갈망 15 | 독점 0 | 위험 10 | 과시 −10 | 지속 15 | 지향 이성 | 결합 다자\n:::","directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126},"relations":{"outgoing":[{"from":"문숲민","type":"지휘","to":"이서담","basis":"이서담의 배급구역 서기로 급수 배분 당직을 맡음"}],"incoming":[]}}');
