INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0977', 'c724-d30c-d3c9', '{"id":"person-0977","name":"Yun Saeyul","title":"Family Herald","position":"Assembly Herald Acolyte","rank":"Postulant","commonTier":"T5","occupation":"Assembly Herald · Manuscript Handover","gender":"Male","stage":"S4","state":"S10","stateName":"Anguk Order","detailRoute":"/people/person-0977","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0977","name":"윤새율","title":"가족 전령","position":"총회 전령 행자","rank":"행자","commonTier":"T5","occupation":"총회 전령·필사본 인계","gender":"남성","stage":"S4","state":"S10","stateName":"안국총림","detailRoute":"/people/person-0977","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0978', 'c7a5-d765-b355', '{"id":"person-0978","name":"Jang Darin","title":"North Gate Patrol","position":"Gangnam Station North Gate Patrol","rank":"Employee","commonTier":"T5","occupation":"Gangnam Station North Gate Patrol Log and Key Handover","gender":"Male","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0978","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}', '{"id":"person-0978","name":"장다린","title":"북문 순찰대","position":"강남역 북문 순찰대","rank":"사원","commonTier":"T5","occupation":"강남역 북문 순찰 기록·열쇠 인계","gender":"남성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0978","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0979', 'd55c-ccad-c8fc', '{"id":"person-0979","name":"Han Jau","title":"Medical Escort Recorder","position":"Medical Escort Recorder","rank":"Escort","commonTier":"T5","occupation":"Medical Escort Log and Duty Key Handover","gender":"Male","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0979","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0979","name":"한자우","title":"의무호송 기록관","position":"의무호송 기록관","rank":"호송원","commonTier":"T5","occupation":"의무호송 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0979","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0980', 'c624-d574-c8fc', '{"id":"person-0980","name":"O Taho","title":"Epidemic Control Recorder","position":"Epidemic Control Recorder","characterId":"K980","rank":"Resident","commonTier":"T3","occupation":"Epidemic Control Log and Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#character-otaho","detailRoute":"/people/person-0980","birthDate":"2073-04-01","birthday":"04-01","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"Payment ledger reconciliation","rating":50}],"traits":[{"id":"stated-priority","name":"Leaves a name on the correction","description":"They reconciled duplicate payment and signed the deletion. Responsibility for records is supported; the scope of sanitation technical expertise is unconfirmed.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: quarantine registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the quarantine registrar duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"They reconciled duplicate payment and signed the deletion. Responsibility for records is supported; the scope of sanitation technical expertise is unconfirmed.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c624-d574-c8fc","name":"Haeju O Clan","crest":"clan-crests/c624-d574-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":35,"Force":-80,"Material":-20,"Communal":15,"Principle":55,"Public":25,"Eligibility":20,"Dispersed":20,"Transformative":-20},"desire":{"Longing":20,"Monopoly":10,"Risk":20,"Display":-5,"Sustained":-10,"Orientation":"Reason","Union":"Non-Exclusive"},"fields":{"Livelihood":"Epidemic Control Log and Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Epidemic Control Recorder","Values":"Authority −25 | Openness 35 | Force −80 | Materialism −20 | Community 15 | Principle 55 | Disclosure 25 | Qualification 20 | Decentralization 20 | Transformation −20","Desires":"Longing 20 | Possessiveness 10 | Risk 20 | Display −5 | Persistence −10 | Orientation: Opposite sex | Bonding: Non-exclusive"},"sections":{"Life":"Born on 2073-04-01. As of the opening of 2126, he holds the post of Quarantine Records Officer, continuing the existing duty and records. The succession record of that post was opened by the deletion of a single line from a double ledger.\n- The quarantine records and duty key handover window in Jegi-dong is O Taho''s work reference point. This placement does not fix residence, exact facility boundaries, rank of nobility, fief, or possession rights.","Offices":"Rank: Resident. Title: Quarantine Resident. Hands over only the keys and records of the post, and writes in the ledger the time of receipt for the keys and records handed over.","Anecdote":"In 2125, cross-checked the double payment ledger, struck out one line, and left a signature. That day''s record remained as the handover basis for the next duty shift to verify.","Relationships":"O Taho delivers the correction of the duplicate quarantine issuance and the signature to Ra Seyeong. Ra Seyeong checks the actual quarantine entries and releases to distinguish ledger duplication from patient movement.","Ambition":"From the Quarantine Resident post, to keep the White Cross Order''s ledger continuous and unbroken.","Fear":"Fears that if the Quarantine Resident duty falls vacant, the White Cross Order''s passage will become a hostage to Seoul''s internal sponsor factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the duty chain. He trusts a single ledger line over loud talk.\n\n- Livelihood: Quarantine records and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Quarantine Records Officer\n**Life.** Born on 2073-04-01. As of the opening of 2126, he holds the post of Quarantine Records Officer, continuing the existing duty and records. The succession record of that post was opened by the deletion of a single line from a double ledger.\n- The quarantine records and duty key handover window in Jegi-dong is O Taho''s work reference point. This placement does not fix residence, exact facility boundaries, rank of nobility, fief, or possession rights.\n\n**Office.** Rank: Resident. Title: Quarantine Resident. He hands over only the keys and records of his own post, and enters in the ledger the time of receipt for the keys and records handed over.\n\n**Anecdote.** In 2125 he cross-checked the double-payout ledger, erased a line, and left his signature. That day''s record remained as the handover basis for the next duty officer to verify.\n\n**Relationships.** O Taho passes the quarantine duplicate-payout correction and signature to Ra Seyeong. Ra Seyeong checks actual isolation entries and releases to tell ledger duplication apart from patient movement.\n\n**Ambition.** From the post of quarantine resident, he keeps the White Cross Order''s ledger continuous and unbroken.\n\n**Fear.** If the quarantine resident''s duty falls vacant, he fears the White Cross Order''s passage will become a hostage of Seoul''s internal patron powers.\n\n**Intervention.** He can put a witness to a duty handover or expose an empty key.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −25 | Openness 35 | Force −80 | Materialism −20 | Community 15 | Principle 55 | Disclosure 25 | Qualification 20 | Decentralization 20 | Transformation −20\n- Desires: Longing 20 | Possessiveness 10 | Risk 20 | Display −5 | Persistence −10 | Orientation: Opposite sex | Bonding: Non-exclusive\n:::","relations":{"outgoing":[{"from":"O Taho","type":"Contract","to":"Ra Seyeong","basis":"O Taho delivers the correction of the duplicate quarantine issuance and the signature to Ra Seyeong. Ra Seyeong checks the actual quarantine entries and releases to distinguish ledger duplication from patient movement."}],"incoming":[]}}', '{"id":"person-0980","name":"오타호","title":"방역 기록관","position":"방역 기록관","characterId":"K980","rank":"수련의","commonTier":"T3","occupation":"방역 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-오타호","detailRoute":"/people/person-0980","birthDate":"2073-04-01","birthday":"04-01","age":53,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"payment-ledger-reconciliation","name":"지급 장부 대조","rating":50}],"traits":[{"id":"stated-priority","name":"정정에 이름을 남긴다","description":"이중 지급을 대조하고 삭제 줄에 서명했다. 장부 책임은 확인되나 방역 수련의의 전문 기술 범위는 미확인이다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 방역 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"이중 지급을 대조하고 삭제 줄에 서명했다. 장부 책임은 확인되나 방역 수련의의 전문 기술 범위는 미확인이다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"c624-d574-c8fc","name":"해주 오씨","crest":"clan-crests/c624-d574-c8fc.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":35,"무력":-80,"물질":-20,"공동":15,"원칙":55,"공개":25,"자격":20,"분산":20,"변혁":-20},"desire":{"갈망":20,"독점":10,"위험":20,"과시":-5,"지속":-10,"지향":"이성","결합":"비독점"},"fields":{"생업":"방역 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"방역 기록관","가치관":"권위 −25 | 개방 35 | 무력 −80 | 물질 −20 | 공동 15 | 원칙 55 | 공개 25 | 자격 20 | 분산 20 | 변혁 −20","욕망":"갈망 20 | 독점 10 | 위험 20 | 과시 −5 | 지속 −10 | 지향 이성 | 결합 비독점"},"sections":{"생애":"2073-04-01에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 오타호의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.","관직":"품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"오타호는 방역 중복 지급 정정과 서명을 라세영에게 전한다. 라세영은 실제 격리 출입·해제를 확인해 장부 중복과 환자 이동을 구분한다.","야망":"방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 방역 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 방역 기록관\n**생애.** 2073-04-01에 태어났다. 2126년 개막 현재 방역 기록관 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 이중 장부 한 줄 삭제로 열렸다.\n- 제기동의 방역 기록·당직 열쇠 인계 창구를 오타호의 업무 기준점으로 한다. 이 배치는 거주지·정확한 시설 경계·작위·영지·점유권을 확정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 방역 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 이중 지급 장부를 대조해 한 줄을 지우고 서명을 남겼다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 오타호는 방역 중복 지급 정정과 서명을 라세영에게 전한다. 라세영은 실제 격리 출입·해제를 확인해 장부 중복과 환자 이동을 구분한다.\n\n**야망.** 방역 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 방역 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 35 | 무력 −80 | 물질 −20 | 공동 15 | 원칙 55 | 공개 25 | 자격 20 | 분산 20 | 변혁 −20\n- 욕망: 갈망 20 | 독점 10 | 위험 20 | 과시 −5 | 지속 −10 | 지향 이성 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"오타호","type":"계약","to":"라세영","basis":"오타호는 방역 중복 지급 정정과 서명을 라세영에게 전한다. 라세영은 실제 격리 출입·해제를 확인해 장부 중복과 환자 이동을 구분한다."}],"incoming":[]}}');
