INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0989', 'bb38-b0a8-d3c9-6587', '{"id":"person-0989","name":"Mun Maeun","title":"Ratification Registrar","position":"Ratification Registrar","characterId":"K989","rank":"Unregistered","commonTier":"T5","occupation":"Ratification Ledger Handover · Continuous Record","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-06#character-mun-maeun","detailRoute":"/people/person-0989","birthDate":"2095-11-28","birthday":"11-28","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k989-pending-copy-log","name":"Uncertified copy suspension log","rating":60}],"traits":[{"id":"k989-choice","name":"Separates receipt from validity","description":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","behavior":"Anecdote. The copy of the ration ledger to be exchanged with Nam Yungyeong reaches the ratification-registrar duty ahead of the government seal. Mun Maeun sets the copy in the hold column and marks in the continuous record the stretch of water contracts whose force stays suspended until the seal is stamped.","stress":"Fear. That the ratification registrar duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. Changes in behavior or state effects are unconfirmed.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"k989-boundary","name":"Maintains work boundaries","description":"Office. Rank: registrar. Title: ratification registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Office. Rank: registrar. Title: ratification registrar. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"Fear. That the ratification registrar duty post would stand empty and the Government''s passage would become a break in the eight states'' recognition. The actual response is not yet recorded.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Anecdote. The copy of the ration ledger to be exchanged with Nam Yungyeong reaches the ratification-registrar duty ahead of the government seal. Mun Maeun sets the copy in the hold column and marks in the continuous record the stretch of water contracts whose force stays suspended until the seal is stamped. Titles and ambitions are not treated as accomplished authority or results.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":15,"Openness":-10,"Force":-25,"Material":-35,"Communal":0,"Principle":60,"Public":-10,"Eligibility":20,"Dispersed":-40,"Transformative":-30},"desire":{"Longing":25,"Monopoly":25,"Risk":5,"Display":-40,"Sustained":5,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"fields":{"Livelihood":"Ratification Ledger Handover · Continuous Record","Affiliation":"Seoul Metropolitan Government Local Civil Service Organization","Position and Grade":"The grade matching a post in a Seoul Metropolitan Government headquarters or field office, among Local Administrative Deputy Director (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)","Assigned Duties":"Ratification Registrar","Values":"Authority 15 | Openness −10 | Force −25 | Materialism −35 | Community 0 | Principle 60 | Disclosure −10 | Qualification 20 | Decentralization −40 | Transformation −30","Desires":"Longing 25 | Possessiveness 25 | Risk 5 | Display −40 | Persistence 5 | Orientation: Both sexes | Bonding: Contract cohabitation"},"sections":{"Life":"She grew up at the Seoul Station Registry. The post of Ratification Records Officer was opened by the deletion of a single line from a double ledger.\n- Mun Maeun''s work of ratification ledger handover and continuity records is tied to Hoehyeon-dong.","Civil Servant Position and Grade":"The grade appropriate to a headquarters or field-office post in the Seoul Metropolitan Government, among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Assistant Local Administrative Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Assistant Local Administrative Clerk (Grade 9). Duties: Confirmation Records Officer.","Anecdote":"The copy of the ration ledger to be exchanged with Nam Yungyeong arrives at the Ratification Records Officer''s duty post before the government seal is stamped. Mun Maeun places the copy in the hold column and marks in the continuity record the water-supply contract section whose effect is suspended until the seal is stamped.","Relationships":"Through the handover of the confirmation-ledger handover and continuous-record work, she is connected to a senior duty officer from the same living area.","Ambition":"From the post of Confirmation Recorder, she carries on the confirmation-ledger handover and continuous records so that the ledgers of the Seoul Metropolitan Government local civil service organization are not broken between duty shifts.","Fear":"That the Confirmation Recorder''s duty shift falls vacant, severing the seals and rosters for downtown passage tied to the confirmation-ledger handover and continuous-record work, and halting even the confirmation of the forces composing the Seoul Metropolitan Government local civil service organization that rely on those records.","Intervention":"She can set up a witness to the duty takeover for the confirmation-ledger handover and continuous-record work, or expose the empty key of that post."},"biography":"Copies awaiting the government seal are kept in the holding slot. Even water-supply contracts whose effect is suspended are guarded so the record does not break between duty shifts.\n\n- Livelihood: Ratification ledger handover and continuous recording\n- Affiliation: Seoul Metropolitan Government Local Civil Service\n- Position and Grade: whichever grade fits a post at a Seoul Metropolitan Government headquarters or field office among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9)\n- Duties: Ratification Recorder\n**Life.** Grew up at the Seoul Station registry office. The Ratification Recorder post opened after a single line was deleted from a double ledger.\n- Mun Ma-eun''s work on ratification ledger handover and continuous recording is tied to Hoehyeon-dong.\n\n**Civil Service Position and Grade.** Whichever grade fits a post at a Seoul Metropolitan Government headquarters or field office among Local Administrative Officer (Grade 5), Local Administrative Senior Clerk (Grade 6), Local Administrative Assistant Senior Clerk (Grade 7), Local Administrative Clerk (Grade 8), and Local Administrative Assistant Clerk (Grade 9). Duties: Ratification Recorder.\n\n**Anecdote.** The ration ledger copy to be exchanged with Nam Yun-gyeong reaches the Ratification Recorder''s duty shift before the government seal is stamped on it. Mun Ma-eun places the copy in the holding slot and, until the seal is stamped, marks the suspended water-supply contract section in the continuous record.\n\n**Relationships.** Through the handover of the ratification ledger handover and continuous recording work, she is connected to a senior duty officer from the same neighborhood.\n\n**Ambition.** From the Ratification Recorder post, to carry on the ratification ledger handover and continuous recording so that the ledgers of the Seoul Metropolitan Government Local Civil Service do not break between duty shifts.\n\n**Fear.** That the Ratification Recorder''s duty shift will go empty, severing the seals and rosters for downtown passage tied to the ratification ledger handover and continuous recording work, and that the ratification of the forces within the Seoul Metropolitan Government Local Civil Service that rely on those records will halt as well.\n\n**Intervention.** You can bring in a witness for the duty handover of the ratification ledger handover and continuous recording work, or expose the empty key of that post.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 15 | Openness −10 | Force −25 | Materialism −35 | Community 0 | Principle 60 | Publicity −10 | Qualification 20 | Decentralization −40 | Transformation −30\n- Desires: Craving 25 | Exclusivity 25 | Risk 5 | Display −40 | Persistence 5 | Orientation Bisexual | Union Contract Cohabitation\n:::","relations":{"outgoing":[{"from":"Mun Maeun","type":"Contract","to":"Yang Haeon","basis":"Mun Maeun hands over to Yang Haeon the copies under approval hold and the continuous record of the sections where validity has stopped. Yang Haeon checks the review seal and custody confirmation and links up messages with no omitted hold."}],"incoming":[]}}', '{"id":"person-0989","name":"문마은","title":"인준 기록관","position":"인준 기록관","characterId":"K989","rank":"미등록","commonTier":"T5","occupation":"인준 장부 인수인계·연속 기록","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-06#인물-문마은","detailRoute":"/people/person-0989","birthDate":"2095-11-28","birthday":"11-28","age":31,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":6,"effective":6},"stewardship":{"base":10,"effective":10},"intrigue":{"base":9,"effective":9},"learning":{"base":8,"effective":8},"prowess":{"base":2,"effective":2}},"skills":[{"id":"k989-pending-copy-log","name":"미날인 사본 보류 기록","rating":60}],"traits":[{"id":"k989-choice","name":"접수와 효력을 구분","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"일화. 남윤경과 주고받을 배급 원장 사본이 정부 도장이 찍히기 전에 인준 기록관 당직으로 먼저 온다. 문마은은 사본을 보류 칸에 올려 두고, 도장이 찍힐 때까지 효력이 멈춘 급수계약 구간을 연속 기록에 표시한다.","stress":"공포. 인준 기록관 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 행동 변화나 상태 효과는 미확정이다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"k989-boundary","name":"업무 경계를 지킴","description":"관직. 품계 주사. 직함은 인준 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"관직. 품계 주사. 직함은 인준 기록관. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 인준 기록관 당직이 비면 도심 통행의 도장과 명부가 끊겨 질서 계열 여덟 나라의 인준이 멈추는 것. 실제 반응은 아직 기록되지 않았다.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"일화. 남윤경과 주고받을 배급 원장 사본이 정부 도장이 찍히기 전에 인준 기록관 당직으로 먼저 온다. 문마은은 사본을 보류 칸에 올려 두고, 도장이 찍힐 때까지 효력이 멈춘 급수계약 구간을 연속 기록에 표시한다. 직함·야망을 이미 이룬 권한이나 성과로 취급하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":15,"개방":-10,"무력":-25,"물질":-35,"공동":0,"원칙":60,"공개":-10,"자격":20,"분산":-40,"변혁":-30},"desire":{"갈망":25,"독점":25,"위험":5,"과시":-40,"지속":5,"지향":"양성","결합":"계약동거"},"fields":{"생업":"인준 장부 인수인계·연속 기록","소속":"서울특별시 지방공무원 조직","직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급","담당 업무":"인준 기록관","가치관":"권위 15 | 개방 −10 | 무력 −25 | 물질 −35 | 공동 0 | 원칙 60 | 공개 −10 | 자격 20 | 분산 −40 | 변혁 −30","욕망":"갈망 25 | 독점 25 | 위험 5 | 과시 −40 | 지속 5 | 지향 양성 | 결합 계약동거"},"sections":{"생애":"서울역 등기소에서 자랐다. 인준 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 문마은의 인준 장부 인수인계·연속 기록 업무는 회현동과 이어진다.","공무원 직위·직급":"지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 인준 기록관.","일화":"남윤경과 주고받을 배급 원장 사본이 정부 도장이 찍히기 전에 인준 기록관 당직으로 먼저 온다. 문마은은 사본을 보류 칸에 올려 두고, 도장이 찍힐 때까지 효력이 멈춘 급수계약 구간을 연속 기록에 표시한다.","관계":"인준 장부 인수인계·연속 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.","야망":"인준 기록관 자리에서 인준 장부 인수인계·연속 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.","공포":"인준 기록관 당직이 비어 인준 장부 인수인계·연속 기록 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.","개입":"인준 장부 인수인계·연속 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다."},"biography":"정부 도장을 기다리는 사본은 보류 칸에 둔다. 효력이 멈춘 급수계약도 당직 사이에서 기록이 끊기지 않게 지킨다.\n\n- 생업: 인준 장부 인수인계·연속 기록\n- 소속: 서울특별시 지방공무원 조직\n- 직위·직급: 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급\n- 담당 업무: 인준 기록관\n**생애.** 서울역 등기소에서 자랐다. 인준 기록관 자리는 이중 장부 한 줄 삭제로 열렸다.\n- 문마은의 인준 장부 인수인계·연속 기록 업무는 회현동과 이어진다.\n\n**공무원 직위·직급.** 지방행정사무관(5급)·지방행정주사(6급)·지방행정주사보(7급)·지방행정서기(8급)·지방행정서기보(9급) 중 서울특별시 본부·사업소 보직에 맞는 직급. 담당 업무: 인준 기록관.\n\n**일화.** 남윤경과 주고받을 배급 원장 사본이 정부 도장이 찍히기 전에 인준 기록관 당직으로 먼저 온다. 문마은은 사본을 보류 칸에 올려 두고, 도장이 찍힐 때까지 효력이 멈춘 급수계약 구간을 연속 기록에 표시한다.\n\n**관계.** 인준 장부 인수인계·연속 기록 업무의 인수인계를 통해 같은 생활권의 선배 당직과 이어진다.\n\n**야망.** 인준 기록관 자리에서 인준 장부 인수인계·연속 기록을 이어 서울특별시 지방공무원 조직의 장부가 당직 사이에 끊기지 않게 한다.\n\n**공포.** 인준 기록관 당직이 비어 인준 장부 인수인계·연속 기록 업무와 연결된 도심 통행의 도장·명부가 끊기고, 그 기록에 기대는 서울특별시 지방공무원 조직 구성 세력의 인준까지 멈추는 것.\n\n**개입.** 인준 장부 인수인계·연속 기록 업무의 당직 인수 증인을 세우거나, 그 직위의 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 15 | 개방 −10 | 무력 −25 | 물질 −35 | 공동 0 | 원칙 60 | 공개 −10 | 자격 20 | 분산 −40 | 변혁 −30\n- 욕망: 갈망 25 | 독점 25 | 위험 5 | 과시 −40 | 지속 5 | 지향 양성 | 결합 계약동거\n:::","relations":{"outgoing":[{"from":"문마은","type":"계약","to":"양해온","basis":"문마은은 인준 보류 중인 사본과 효력이 멈춘 구간의 연속 기록을 양해온에게 넘긴다. 양해온은 심사 날인·보관 확인을 살펴 보류가 누락되지 않은 전갈을 잇는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0990', NULL, '{"id":"person-0990","name":"Isabel Garcia","title":"Escort Courier","position":"Escort Courier","characterId":"K990","rank":"Clerk","commonTier":"T5","occupation":"Ticketless Train Departure and Signature Confirmation","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-07#Person-Isabel Garcia","detailRoute":"/people/person-0990","birthDate":"2098-05-12","birthday":"05-12","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure-check","name":"Departure checking","rating":45}],"traits":[{"id":"k990-disposition","name":"Refusing operation without receipt","description":"She chose the side that kept the duty line unbroken first. She trusted one line of the ledger more than a loud voice.","behavior":"Office. Rank: registrar. Title: convoy courier. She handed over only the keys and records of her own post, and never made authority she did not hold.","stress":"Fear. That the convoy courier duty post would stand empty, interrupting dispatch and transshipment handovers in Yongsan and passing unverified completion records to water-supply, medical-care and goods handover counterparts within Seoul.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. Isabel García reports an unsigned train departure to Eva Nováková. Eva checks occupied slots and boarding certification rather than entering a departure without receipt verification as completed operation.","effects":[]},{"id":"k990-choice","name":"Referring boarding checks","description":"Anecdote. In 2125 she stopped a dispatch-sheetless train and blocked an unsigned departure. By this deed the signature of the convoy courier post rose into the ledger.","behavior":"Relations. Bound by handover to the senior duty line of the same living quarters. Isabel García reports an unsigned train departure to Eva Nováková. Eva checks occupied slots and boarding certification rather than entering a departure without receipt verification as completed operation.","stress":"Fear. That the convoy courier duty post would stand empty, interrupting dispatch and transshipment handovers in Yongsan and passing unverified completion records to water-supply, medical-care and goods handover counterparts within Seoul.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters. Isabel García reports an unsigned train departure to Eva Nováková. Eva checks occupied slots and boarding certification rather than entering a departure without receipt verification as completed operation.","effects":[]}],"narrative":"Stops an unsigned train and refers it to Eva. Guards against completion without receipt without granting boarding-review expertise.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":0,"Openness":35,"Force":0,"Material":10,"Communal":-10,"Principle":10,"Public":-15,"Eligibility":20,"Dispersed":10,"Transformative":5},"desire":{"Longing":10,"Monopoly":-25,"Risk":35,"Display":-15,"Sustained":-10,"Orientation":"None","Union":"Non-Exclusive"},"fields":{"Affiliation":"The Government","Rank":"Clerk","Livelihood":"Ticketless Train Departure and Signature Confirmation","Title":"Escort Courier","Values":"Authority 0 | Openness 35 | Force 0 | Materialism 10 | Community −10 | Principle 10 | Publicity −15 | Qualification 20 | Decentralization 10 | Transformation 5","Desires":"Craving 10 | Exclusivity −25 | Risk 35 | Display −15 | Persistence −10 | Orientation None | Union Non-exclusive"},"sections":{"Life":"Isabel Garcia, born in 2098, takes up the Escort Courier duties in the opening period of 2126. She grew up on the duty shift at the Sinnae transfer station. The Escort Courier work began with her stopping a ticketless train departure. Her Spanish-descended family has roots in the Yongsan and Itaewon neighborhoods. Manuel Garcia lived through the Great Blackout in Yongsan and Itaewon around 2026, working in private food supply in Itaewon and in transport in Yongsan. The family passed its shelter and goods handover records to the next generation, and Isabel Garcia''s parents'' generation cross-checked those records against the living ledgers of their time. They speak Spanish at home and Korean in daily life and at work.\n- Isabel Garcia''s work on ticketless train departures and signature checks is tied to Hangang-ro-dong.","Offices":"Rank: Senior Clerk. Title: Escort Courier. He hands over only the keys and records of his own post and does not invent authority he lacks.","Anecdote":"In 2125 he stopped a train that had no dispatch slip and prevented a departure without a signature. After this act, the Escort Courier post''s signature was entered in the ledger.","Relationships":"Isabel Garcia reports an unsigned train departure to Eva Novakova. Eva Novakova checks the occupied window and the boarding proof, and does not record an entry lacking a departure handover as a completed run.","Ambition":"He links the Escort Courier''s records of checking ticketless train departures and signatures to the Transfer Bureau ledger, so that the next duty officer checks the same records.","Fear":"That if the Escort Courier duty falls vacant, the dispatch and transshipment handovers of Yongsan will be cut off, and unverified completion records will pass to the water-supply, medical, and goods-handover counterparts within Seoul.","Intervention":"He can bring in a witness to the duty handover or expose an empty key."},"biography":"Isabel Garcia handles ticketless train departure and signature checks. Isabel Garcia reports unsigned train departures to Eva Novakova.\n\n- Affiliation: Transshipment Bureau\n- Rank: Clerk\n- Livelihood: Ticketless train departure and signature checks\n- Title: Escort Courier\n**Life.** Isabel Garcia, born in 2098, takes up the Escort Courier duties in the opening period of 2126. She grew up on the duty shift at the Sinnae transfer station. The Escort Courier work began with her stopping a ticketless train departure. Her Spanish-descended family has roots in the Yongsan and Itaewon neighborhoods. Manuel Garcia lived through the Great Blackout in Yongsan and Itaewon around 2026, working in private food supply in Itaewon and in transport in Yongsan. The family passed its shelter and goods handover records to the next generation, and Isabel Garcia''s parents'' generation cross-checked those records against the living ledgers of their time. They speak Spanish at home and Korean in daily life and at work.\n- Isabel Garcia''s work on ticketless train departures and signature checks is tied to Hangang-ro-dong.\n\n**Office.** Rank: Clerk. Title: Escort Courier. She hands over only the keys and records of her own post, and does not invent authority she does not have.\n\n**Anecdote.** In 2125 she stopped a train with no dispatch sheet and blocked an unsigned departure. Because of that act, the Escort Courier post''s signature was entered in the ledger.\n\n**Relationships.** Isabel Garcia reports unsigned train departures to Eva Novakova. Eva Novakova checks the occupancy window and the boarding proof, and does not record a run with no departure handover as a completed run.\n\n**Ambition.** To link the Escort Courier''s ticketless train departure and signature check records to the Transshipment Bureau''s ledger, so that the next duty officer checks the same records.\n\n**Fear.** That if the Escort Courier''s duty shift goes empty, the dispatch and transshipment handover in Yongsan will break, and unverified completion records will be passed on to Seoul''s water-supply, medical, and goods-handover counterparts.\n\n**Intervention.** You can bring in a witness for the duty handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority 0 | Openness 35 | Force 0 | Materialism 10 | Community −10 | Principle 10 | Publicity −15 | Qualification 20 | Decentralization 10 | Transformation 5\n- Desires: Craving 10 | Exclusivity −25 | Risk 35 | Display −15 | Persistence −10 | Orientation None | Union Non-exclusive\n:::","relations":{"outgoing":[{"from":"Isabel Garcia","type":"Contract","to":"Eva Novakova","basis":"Isabel Garcia reports an unsigned train departure to Eva Novakova. Eva Novakova checks the occupied window and the boarding proof, and does not record an entry lacking a departure handover as a completed run."}],"incoming":[]}}', '{"id":"person-0990","name":"이사벨 가르시아","title":"호송 전령","position":"호송 전령","characterId":"K990","rank":"주사","commonTier":"T5","occupation":"무표 열차 출발·서명 확인","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-07#인물-이사벨 가르시아","detailRoute":"/people/person-0990","birthDate":"2098-05-12","birthday":"05-12","age":28,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"departure-check","name":"출발 확인","rating":45}],"traits":[{"id":"k990-disposition","name":"인수 없는 운행 거부","description":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.","behavior":"관직. 품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"공포. 호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다. 에바 노바코바는 점유 창과 탑승 증명을 확인해 출발 인수가 없는 기록을 완료 운행으로 적지 않는다.","effects":[]},{"id":"k990-choice","name":"탑승 확인에 넘김","description":"일화. 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 일로 호송 전령 자리의 서명이 장부에 올랐다.","behavior":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다. 에바 노바코바는 점유 창과 탑승 증명을 확인해 출발 인수가 없는 기록을 완료 운행으로 적지 않는다.","stress":"공포. 호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다. 이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다. 에바 노바코바는 점유 창과 탑승 증명을 확인해 출발 인수가 없는 기록을 완료 운행으로 적지 않는다.","effects":[]}],"narrative":"무서명 열차를 세워 에바의 확인에 넘겼다. 인수 없는 완료 기록을 경계하되 실제 탑승 심사 능력은 부여하지 않았다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":null,"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":0,"개방":35,"무력":0,"물질":10,"공동":-10,"원칙":10,"공개":-15,"자격":20,"분산":10,"변혁":5},"desire":{"갈망":10,"독점":-25,"위험":35,"과시":-15,"지속":-10,"지향":"무성향","결합":"비독점"},"fields":{"소속":"환적국","품계":"주사","생업":"무표 열차 출발·서명 확인","직함":"호송 전령","가치관":"권위 0 | 개방 35 | 무력 0 | 물질 10 | 공동 −10 | 원칙 10 | 공개 −15 | 자격 20 | 분산 10 | 변혁 5","욕망":"갈망 10 | 독점 −25 | 위험 35 | 과시 −15 | 지속 −10 | 지향 무성향 | 결합 비독점"},"sections":{"생애":"2098년생인 이사벨 가르시아는 2126년 개막기에 호송 전령 업무를 맡는다. 신내 환승 당직에서 자랐다. 호송 전령 업무는 무표 출발 열차 저지를 계기로 시작됐다. 스페인계 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 마누엘 가르시아는 약 2026년 용산·이태원에서 이태원 민간 식품 공급과 용산 운송 일을 하며 대정전을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 이사벨 가르시아의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 스페인어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 이사벨 가르시아의 무표 열차 출발·서명 확인 업무는 한강로동과 연결된다.","관직":"품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.","일화":"2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 행동을 계기로 호송 전령 자리의 서명이 장부에 올랐다.","관계":"이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다. 에바 노바코바는 점유 창과 탑승 증명을 확인해 출발 인수가 없는 기록을 완료 운행으로 적지 않는다.","야망":"호송 전령 업무의 무표 열차 출발·서명 확인 기록을 환적국 장부와 이어, 다음 당직이 같은 기록을 확인하게 한다.","공포":"호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.","개입":"당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"이사벨 가르시아는 무표 열차 출발·서명 확인 업무를 맡는다. 이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다.\n\n- 소속: 환적국\n- 품계: 주사\n- 생업: 무표 열차 출발·서명 확인\n- 직함: 호송 전령\n**생애.** 2098년생인 이사벨 가르시아는 2126년 개막기에 호송 전령 업무를 맡는다. 신내 환승 당직에서 자랐다. 호송 전령 업무는 무표 출발 열차 저지를 계기로 시작됐다. 스페인계 가계는 용산·이태원 생활권에 뿌리를 두고 있다. 마누엘 가르시아는 약 2026년 용산·이태원에서 이태원 민간 식품 공급과 용산 운송 일을 하며 대정전을 겪었다. 가족은 거처와 물품 인계 기록을 다음 세대에 전했고, 이사벨 가르시아의 부모 세대는 그 기록을 당대의 생활 장부와 대조했다. 집에서는 스페인어를 쓰고 일상과 업무에서는 한국어를 쓴다.\n- 이사벨 가르시아의 무표 열차 출발·서명 확인 업무는 한강로동과 연결된다.\n\n**관직.** 품계 주사. 직함은 호송 전령. 자기 직위의 열쇠와 기록만 인계하며, 없는 권한은 만들어 내지 않는다.\n\n**일화.** 2125년 배차표 없는 열차를 세워 서명 없는 출발을 막았다. 이 행동을 계기로 호송 전령 자리의 서명이 장부에 올랐다.\n\n**관계.** 이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다. 에바 노바코바는 점유 창과 탑승 증명을 확인해 출발 인수가 없는 기록을 완료 운행으로 적지 않는다.\n\n**야망.** 호송 전령 업무의 무표 열차 출발·서명 확인 기록을 환적국 장부와 이어, 다음 당직이 같은 기록을 확인하게 한다.\n\n**공포.** 호송 전령 당직이 비면 용산의 배차·환적 인계가 끊기고, 서울 안의 급수·진료·물품 인계 상대에게 확인되지 않은 완료 기록이 넘어가는 것.\n\n**개입.** 당직 인수에 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 0 | 개방 35 | 무력 0 | 물질 10 | 공동 −10 | 원칙 10 | 공개 −15 | 자격 20 | 분산 10 | 변혁 5\n- 욕망: 갈망 10 | 독점 −25 | 위험 35 | 과시 −15 | 지속 −10 | 지향 무성향 | 결합 비독점\n:::","relations":{"outgoing":[{"from":"이사벨 가르시아","type":"계약","to":"에바 노바코바","basis":"이사벨 가르시아는 서명 없는 열차 출발을 에바 노바코바에게 알린다. 에바 노바코바는 점유 창과 탑승 증명을 확인해 출발 인수가 없는 기록을 완료 운행으로 적지 않는다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0991', 'c190-bc00-c591', '{"id":"person-0991","name":"Son Kaho","title":"Ice Logistics Merchant","position":"Ice Logistics Merchant","rank":"Corrections","commonTier":"T5","occupation":"Receiving Smuggled Hoses · Writing the Pipeline Ledger","gender":"Female","stage":"S4","state":"S08","stateName":"Central Intelligence Bureau","detailRoute":"/people/person-0991","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0991","name":"손카호","title":"얼음 물류상","position":"얼음 물류상","rank":"교도","commonTier":"T5","occupation":"밀수 호스 접수·관로 대장 작성","gender":"여성","stage":"S4","state":"S08","stateName":"중앙정보부","detailRoute":"/people/person-0991","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0992', 'bc30-bd84-c131-88f5', '{"id":"person-0992","name":"Bae Hamin","title":"Antenna Technician","position":"Vault Technician","rank":"Clerk","commonTier":"T5","occupation":"Vault Equipment Inspection & Maintenance","gender":"Female","stage":"S4","state":"S09","stateName":"Yeouido Investors'' Association","detailRoute":"/people/person-0992","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0992","name":"배하민","title":"안테나 정비사","position":"금고 정비사","rank":"서기","commonTier":"T5","occupation":"금고 설비 점검·정비","gender":"여성","stage":"S4","state":"S09","stateName":"여의도출자연합회","detailRoute":"/people/person-0992","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}}}}');
