INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0994', 'd5c8-c591-cc9c', '{"id":"person-0994","name":"Heo Bukseo","title":"Wheel Technician","position":"Seongha Electronics Wheel Technician","rank":"Employee","commonTier":"T5","occupation":"Seongha Electronics Wheel Maintenance Records & Key Handover","gender":"Female","stage":"S4","state":"S11","stateName":"Seongha Group","detailRoute":"/people/person-0994","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}', '{"id":"person-0994","name":"허북서","title":"차륜 정비사","position":"성하전자 차륜 정비사","rank":"사원","commonTier":"T5","occupation":"성하전자 차륜 정비 기록·열쇠 인계","gender":"여성","stage":"S4","state":"S11","stateName":"성하그룹","detailRoute":"/people/person-0994","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0995', 'c720-ac15-b989', '{"id":"person-0995","name":"Yu Byeoryeong","title":"Dispatch Courier","position":"Dispatch Courier","rank":"Escort","commonTier":"T5","occupation":"Dispatch Courier Records & Duty Key Handover","gender":"Female","stage":"S4","state":"S12","stateName":"Sinnae Transport","detailRoute":"/people/person-0995","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}', '{"id":"person-0995","name":"유별영","title":"배차 전령","position":"배차 전령","rank":"호송원","commonTier":"T5","occupation":"배차 전령 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"S12","stateName":"신내운수","detailRoute":"/people/person-0995","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0996', 'b0a8-c758-b839', '{"id":"person-0996","name":"Nam Bichwon","title":"Medicinal Supplies Logistics Merchant","position":"Medicinal Supplies Logistics Merchant","characterId":"K996","rank":"Resident","commonTier":"T3","occupation":"Medicinal Supplies Management Records & Duty Key Handover","gender":"Female","stage":"S4","state":"government","stateName":"The Government","sourceRoute":"/world/Cast-State-13#Person-Nam Bit-won","detailRoute":"/people/person-0996","birthDate":"2075-04-06","birthday":"04-06","age":51,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"suspect-medicine-sealing","name":"Suspect medicine sealing","rating":45}],"traits":[{"id":"stated-priority","name":"Keeps recovered evidence","description":"Counterfeit auction boxes were sealed instead of burned. Custody and duty continuity support the profile without extending appraisal experience.","behavior":"He chose the side that kept the duty line unbroken first. He trusted one line of the ledger more than a loud voice.","stress":"Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]},{"id":"bounded-duty","name":"Boundaries of personal duty","description":"Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","behavior":"Recorded duty and limits: Office. Rank: member. Title: herb logistics merchant. He handed over only the keys and records of his own post, and never made authority he did not hold.","stress":"The card states this concern when those boundaries fail: Fear. That the herb logistics merchant duty post would stand empty and the League''s passage would become a hostage of the great powers.","relationship":"Relations. Bound by handover to the senior duty line of the same living quarters.","effects":[]}],"narrative":"Counterfeit auction boxes were sealed instead of burned. Custody and duty continuity support the profile without extending appraisal experience.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"Authority":-25,"Openness":30,"Force":-40,"Material":-10,"Communal":20,"Principle":25,"Public":25,"Eligibility":25,"Dispersed":10,"Transformative":-5},"desire":{"Longing":30,"Monopoly":10,"Risk":-30,"Display":-5,"Sustained":10,"Orientation":"Bisexual","Union":"Monogamy"},"fields":{"Livelihood":"Medicinal Supplies Management Records & Duty Key Handover","Affiliation":"White Cross Order","Rank":"Resident","Title":"Medicinal Supplies Logistics Merchant","Values":"Authority −25 | Openness 30 | Force −40 | Materialism −10 | Community 20 | Principle 25 | Publicity 25 | Qualification 25 | Decentralization 10 | Transformation −5","Desires":"Craving 30 | Exclusivity 10 | Risk −30 | Display −5 | Persistence 10 | Orientation Bisexual | Union Monogamy"},"sections":{"Life":"Born on 2075-04-06. As of the 2126 opening, he holds the Medicinal Herb Logistics Merchant post and carries on the existing duty shifts and records. The succession record for that post opened with the sealing of counterfeit medicine.\n- The herb management records and duty key handover desk in Jegi-dong is Nam Bit-won''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a noble title, a fief, or tenure rights.","Offices":"Rank: Resident. Title: Medicinal Herb Management Resident. Hands over only the keys and records of their own post, and enters in the ledger the time of receipt of the keys and records handed over.","Anecdote":"In 2125, collected a box of counterfeit medicine from the auction house and sealed it instead of burning it. That day''s record remained as grounds for handover for the next duty-holder to verify.","Relationships":"Nam Bichwon hands the sealed suspect medicinal herbs to Won Miru along with custody records. Won Miru examines the capsule seals and samples, investigates the route, and leaves unidentified origins as dotted lines.","Ambition":"From the post of Medicinal Herb Management Resident, keeps the White Cross Order''s ledgers continuous and unbroken.","Fear":"Fears that if the Medicinal Herb Management Resident''s watch falls vacant, the White Cross Order''s passage will become a hostage of Seoul''s internal patron factions.","Intervention":"Can bring in a witness to the watch handover or expose the empty key."},"biography":"He chooses first not to break the duty shift. He trusts a single line in the ledger more than loud talk.\n\n- Livelihood: Herb management records and duty key handover\n- Affiliation: White Cross Order\n- Rank: Resident\n- Title: Medicinal Herb Logistics Merchant\n**Life.** Born on 2075-04-06. As of the 2126 opening, he holds the Medicinal Herb Logistics Merchant post and carries on the existing duty shifts and records. The succession record for that post opened with the sealing of counterfeit medicine.\n- The herb management records and duty key handover desk in Jegi-dong is Nam Bit-won''s work reference point. This work reference point does not fix a residence, exact facility boundaries, a noble title, a fief, or tenure rights.\n\n**Office.** Rank: Resident. Title: Herb Management Resident. He hands over only the keys and records of his own post, and enters in the ledger the time of receipt for each key and record handed over.\n\n**Anecdote.** In 2125 he collected counterfeit medicine crates at the auction house and sealed them instead of burning them. That day''s record remained as the handover basis for the next duty officer to verify.\n\n**Relationships.** Nam Bit-won hands the sealed suspect herbs to Won Mi-ru together with the management records. Won Mi-ru examines the capsule seals and specimens to trace their routes, and marks unconfirmed origins with dotted lines.\n\n**Ambition.** From the Herb Management Resident post, to link the White Cross Order''s ledgers without a break.\n\n**Fear.** If the Herb Management Resident''s duty shift goes empty, he fears the White Cross Order''s passage will become a hostage of the backing forces inside Seoul.\n\n**Intervention.** You can bring in a witness for the duty handover or expose the empty key.\n\n::: details Appendix — Ledger Numbers\n\n- Values: Authority −25 | Openness 30 | Force −40 | Materialism −10 | Community 20 | Principle 25 | Publicity 25 | Qualification 25 | Decentralization 10 | Transformation −5\n- Desires: Craving 30 | Exclusivity 10 | Risk −30 | Display −5 | Persistence 10 | Orientation Bisexual | Union Monogamy\n:::","relations":{"outgoing":[{"from":"Nam Bichwon","type":"Contract","to":"Won Miru","basis":"Nam Bichwon hands the sealed suspect medicinal herbs to Won Miru along with custody records. Won Miru examines the capsule seals and samples, investigates the route, and leaves unidentified origins as dotted lines."}],"incoming":[]}}', '{"id":"person-0996","name":"남빛원","title":"약재 물류상","position":"약재 물류상","characterId":"K996","rank":"수련의","commonTier":"T3","occupation":"약재 관리 기록·당직 열쇠 인계","gender":"여성","stage":"S4","state":"government","stateName":"정부","sourceRoute":"/world/Cast-State-13#인물-남빛원","detailRoute":"/people/person-0996","birthDate":"2075-04-06","birthday":"04-06","age":51,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":6,"effective":6},"stewardship":{"base":8,"effective":8},"intrigue":{"base":8,"effective":8},"learning":{"base":7,"effective":7},"prowess":{"base":2,"effective":2}},"skills":[{"id":"suspect-medicine-sealing","name":"의심 약품 봉인","rating":45}],"traits":[{"id":"stated-priority","name":"회수한 증거를 남긴다","description":"경매장의 가짜 약 상자를 태우지 않고 봉인했다. 물품 보관과 당직 연속성만 근거로 삼고 감별 경력을 확대하지 않는다.","behavior":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다. 제기동의 중립 의료국 흰십자단에서 담당 전문의의 도제로 배우며, 적아 구분 없이 중증도만으로 치료한다.","stress":"공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]},{"id":"bounded-duty","name":"자기 당직의 경계","description":"관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","behavior":"확인된 당직 수행과 제한: 관직. 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 없는 권한은 만들지 않는다.","stress":"이 경계가 흔들릴 때 카드에 명시된 우려: 공포. 약재 관리 수련의 당직이 비면 흰십자단의 통행이 강국 볼모가 되는 것.","relationship":"관계. 같은 생활권 선배 당직과 인수인계로 묶인다.","effects":[]}],"narrative":"경매장의 가짜 약 상자를 태우지 않고 봉인했다. 물품 보관과 당직 연속성만 근거로 삼고 감별 경력을 확대하지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[],"clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","values":{"권위":-25,"개방":30,"무력":-40,"물질":-10,"공동":20,"원칙":25,"공개":25,"자격":25,"분산":10,"변혁":-5},"desire":{"갈망":30,"독점":10,"위험":-30,"과시":-5,"지속":10,"지향":"양성","결합":"단혼"},"fields":{"생업":"약재 관리 기록·당직 열쇠 인계","소속":"흰십자단","품계":"수련의","직함":"약재 물류상","가치관":"권위 −25 | 개방 30 | 무력 −40 | 물질 −10 | 공동 20 | 원칙 25 | 공개 25 | 자격 25 | 분산 10 | 변혁 −5","욕망":"갈망 30 | 독점 10 | 위험 −30 | 과시 −5 | 지속 10 | 지향 양성 | 결합 단혼"},"sections":{"생애":"2075-04-06에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 남빛원의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 정하지 않는다.","관직":"품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.","일화":"2125년 가짜 약 상자를 경매장에서 거둬 화형 대신 봉인했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.","관계":"남빛원은 봉인한 의심 약재를 원미루에게 관리 기록과 함께 넘긴다. 원미루는 캡슐 인장·표본을 살펴 경로를 조사하고 미확인 산지는 점선으로 남긴다.","야망":"약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.","공포":"약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.","개입":"당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다."},"biography":"당직을 끊지 않는 쪽을 먼저 고른다. 큰소리보다 장부 한 줄을 믿는다.\n\n- 생업: 약재 관리 기록·당직 열쇠 인계\n- 소속: 흰십자단\n- 품계: 수련의\n- 직함: 약재 물류상\n**생애.** 2075-04-06에 태어났다. 2126년 개막 현재 약재 물류상 직무를 맡아 기존 당직과 기록을 잇는다. 그 직무의 승계 기록에는 가짜 약 봉인으로 열렸다.\n- 제기동의 약재 관리 기록·당직 열쇠 인계 창구가 남빛원의 업무 기준점이다. 이 업무 기준점은 거주지·정확한 시설 경계·작위·영지·점유권을 정하지 않는다.\n\n**관직.** 품계 수련의. 직함은 약재 관리 수련의. 자기 직위의 열쇠와 기록만 넘기고, 인계한 열쇠와 기록의 수령 시각을 장부에 적는다.\n\n**일화.** 2125년 가짜 약 상자를 경매장에서 거둬 화형 대신 봉인했다. 그날의 기록은 다음 당직이 확인할 인계 근거로 남았다.\n\n**관계.** 남빛원은 봉인한 의심 약재를 원미루에게 관리 기록과 함께 넘긴다. 원미루는 캡슐 인장·표본을 살펴 경로를 조사하고 미확인 산지는 점선으로 남긴다.\n\n**야망.** 약재 관리 수련의 자리에서 흰십자단의 장부를 끊기지 않게 잇는다.\n\n**공포.** 약재 관리 수련의 당직이 비면 흰십자단의 통행이 서울 내부 후원 세력 볼모가 되는 일을 두려워한다.\n\n**개입.** 당직 인수 증인을 세우거나 빈 열쇠를 폭로할 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −25 | 개방 30 | 무력 −40 | 물질 −10 | 공동 20 | 원칙 25 | 공개 25 | 자격 25 | 분산 10 | 변혁 −5\n- 욕망: 갈망 30 | 독점 10 | 위험 −30 | 과시 −5 | 지속 10 | 지향 양성 | 결합 단혼\n:::","relations":{"outgoing":[{"from":"남빛원","type":"계약","to":"원미루","basis":"남빛원은 봉인한 의심 약재를 원미루에게 관리 기록과 함께 넘긴다. 원미루는 캡슐 인장·표본을 살펴 경로를 조사하고 미확인 산지는 점선으로 남긴다."}],"incoming":[]}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0997', 'c2ec-ccad-c1a1', '{"id":"person-0997","name":"Sim Sanyang","title":"Outpost Courier","position":"Agwansa Outpost Courier","rank":"Sergeant","commonTier":"T5","occupation":"Outpost Courier Records & Duty Key Handover","gender":"Male","stage":"S4","state":"S14","stateName":"Achasan Gate","detailRoute":"/people/person-0997","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}', '{"id":"person-0997","name":"심산양","title":"초소 전령","position":"아관사 초소 전령","rank":"병장","commonTier":"T5","occupation":"초소 전령 기록·당직 열쇠 인계","gender":"남성","stage":"S4","state":"S14","stateName":"아관사","detailRoute":"/people/person-0997","sourceStatus":"ck3-table-derived","characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0998', 'c774-c804-c758-674e', '{"id":"person-0998","name":"I Ilseop","title":"Heir of the I Clan, First Branch Workshop","position":"Duke of Gwanak · Heir of the I Clan, First Branch Workshop","characterId":"K998","rank":"","commonTier":"T2","occupation":"Field Cultivation and Grain Stock Management for First Sub-Workshop Duties in Oryu 2-dong","gender":"Male","stage":"S1","state":"geography:duchy:11620","stateName":"Gwanak-gu","sourceRoute":"/world/Cast-State-02#person-lee-ilseop","detailRoute":"/people/person-0998","birthDate":"2092-04-14","birthday":"04-14","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-identity-20260925","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"characterProfile":{"abilities":{"diplomacy":{"base":14,"effective":14},"martial":{"base":17,"effective":17},"stewardship":{"base":19,"effective":23},"intrigue":{"base":16,"effective":16},"learning":{"base":18,"effective":18},"prowess":{"base":8,"effective":8}},"skills":[{"id":"k998-skill-1","name":"Inventory management","rating":85},{"id":"k998-skill-2","name":"Ration planning","rating":80}],"traits":[{"id":"k998-trait-1","name":"Long preparation","description":"Prepares winter rations through stocks and seeds first.","behavior":"Prepares winter rations through stocks and seeds first.","stress":"Rechecks stocks and delays decisions after dangerous news.","relationship":"Proposes seed payments to the council and checks retainers’ reports himself.","effects":[{"ability":"stewardship","delta":4}]},{"id":"k998-trait-2","name":"Delayed decisions","description":"Spends substantial time recounting before deciding.","behavior":"Spends substantial time recounting before deciding.","stress":"Thinks first of a hiding place on hearing dangerous news.","relationship":"Stands firm in his beliefs, though delayed ration plans slow coordination.","effects":[]}],"narrative":"He counted grain stocks three times before submitting a winter ration plan and proposed accepting seeds for part of the parts payment. Fear and slow decisions coexist with persistence in sustaining food supplies.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-chungcheong-k998","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K998","stateId":"S02","politicalParentTitleId":"title:kingdom-s02","personalLieges":[],"directOwnership":false},{"id":"title:barony-chungcheong-3611025000","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K998","stateId":"S02","politicalParentTitleId":"title:duchy-chungcheong-k998","personalLieges":[{"holdingId":"holding:chungcheong-3611025000","directLiegePersonId":null}],"directOwnership":false},{"id":"title:barony-chungcheong-4420033000","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K998","stateId":"S02","politicalParentTitleId":"title:duchy-chungcheong-k998","personalLieges":[{"holdingId":"holding:chungcheong-4420033000","directLiegePersonId":null}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c774-c804-c758-674e","name":"Jeonui Lee","crest":"clan-crests/c774-c804-c758-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":false,"values":{"Authority":-20,"Openness":40,"Force":-30,"Material":40,"Communal":30,"Principle":50,"Public":50,"Eligibility":45,"Dispersed":30,"Transformative":40},"desire":{"Longing":35,"Monopoly":-25,"Risk":-20,"Display":-30,"Sustained":70,"Orientation":"Fluid","Union":"Contract Cohabitation"},"fields":{"Affiliation":"Free City Vassal: Lee Clan of the First Sub-Workshop","Rank":"Duke","Title":"Heir of the I Clan, First Branch Workshop","Livelihood":"Field Cultivation and Grain Stock Management for First Sub-Workshop Duties in Oryu 2-dong","Name":"Lee Ilseop. Public pen name iz.","Contributor":"[islee23520](https://github.com/islee23520)","Community of origin":"Lee clan of the First Sub-Workshop. Ancestral seat Jeonui.","Work Location":"Oryu 2-dong. At the First Sub-Workshop in Oryu 2-dong, Lee Ilseop recounts the grain stock for winter rations three times and sends a seed-payment proposal up to the Standards League Council. He entrusts Park Doyun with confirming receipt of the proposal and has Ryu Donghyeon report only power anomalies in the work area, and he does not extend the use of the field and storage space into clan territory.","Values":"Authority −20 | Openness 40 | Force −30 | Materialism 40 | Communal 30 | Principle 50 | Publicity 50 | Qualification 45 | Decentralization 30 | Transformation 40","Desires":"Craving 35 | Monopoly −25 | Risk −20 | Display −30 | Endurance 70 | Orientation Fluid | Union Contractual Cohabitation"},"sections":{"Life":"Heir of the Lee clan that carries on the First Sub-Workshop. In 2121, in his workshop duties at Oryu 2-dong, he tilled the field and managed the grain stock. The field and storage space were used for this work and were neither the clan''s territory nor its exclusive property. In 2123, before submitting the winter ration plan, he recounted the grain stock three times, and proposed to the Standards League Council that part of the sub-workshop''s parts payments be accepted in seed.","Anecdote":"In 2123, Lee Ilseop recounted the grain stock three times before submitting the winter ration plan, and in the same year proposed to the Standards League Council that part of the sub-workshop''s parts payments be accepted in seed. It was the heir, who handled field cultivation and stored grain management at Oryu 2-dong, submitting the clan''s proposal to the Council.","Houses":"The Lee clan is a vassal of the Free City, and Lee Ilseop is the heir who carries on the First Sub-Workshop.","Belief":"He believes the world gets better when farming leaves food to spare.","Relationships":"As heir of the Lee clan, a vassal of the Free City, he carries on the First Sub-Workshop and, in his workshop duties at Oryu 2-dong, submits proposals to the Standards League Council on the sub-workshop''s parts payments. He entrusts his direct courier Park Doyun with delivering messages and confirming receipt, and his direct guard Ryu Donghyeon with patrolling the power equipment and reporting anomalies. Lee Ilseop personally cross-checks grain quantities and the ration plan. With Gu Chansol he matches the grain loss ledger against parts transport records, and from Jang Useok he receives the audit results of the parts specification copies to be submitted to the Council. Heo Daon''s wheel inspection records are used to check the parts to be shipped from the sub-workshop.","Ambition":"To fill the winter ration plan with grain from the field he cultivates in his First Sub-Workshop duties at Oryu 2-dong, and so build a sub-workshop with food to spare.","Fear":"That the grain stock, recounted three times, will fall short of the winter ration plan.","Intervention":"One can count the grain stock together with him to bring the winter ration plan forward, or back or undermine the seed-payment proposal in the Council."},"biography":"He is timid and slow to decide. On hearing dangerous news, he first thinks of a place to hide, and he recounts the ledger all night and puts forward his proposal only the next day. Yet he does not back down when it comes to what he believes in.\n\n- Affiliation: Free City Vassal, Lee Clan of the First Sub-Workshop\n- Rank: Duke\n- Title: Heir of the Lee Clan of the First Sub-Workshop\n- Occupation: Field cultivation and grain stock management for First Sub-Workshop duties in Oryu 2-dong\n- Name: Lee Ilseop. Public pen name iz.\n- Contributor: [islee23520](https://github.com/islee23520)\n- Community of origin: Lee clan of the First Sub-Workshop. Ancestral seat Jeonui.\n- Work location: Oryu 2-dong. At the First Sub-Workshop in Oryu 2-dong, Lee Ilseop recounts the grain stock for winter rations three times and sends a seed-payment proposal up to the Standards League Council. He entrusts Park Doyun with confirming receipt of the proposal and has Ryu Donghyeon report only power anomalies in the work area, and he does not extend the use of the field and storage space into clan territory.\n\n**Life.** Heir of the Lee clan that carries on the First Sub-Workshop. In 2121, in his workshop duties at Oryu 2-dong, he tilled the field and managed the grain stock. The field and storage space were used for this work and were neither the clan''s territory nor its exclusive property. In 2123, before submitting the winter ration plan, he recounted the grain stock three times, and proposed to the Standards League Council that part of the sub-workshop''s parts payments be accepted in seed.\n\n**Anecdote.** In 2123, Lee Ilseop recounted the grain stock three times before submitting the winter ration plan, and in the same year proposed to the Standards League Council that part of the sub-workshop''s parts payments be accepted in seed. It was the heir, who handled field cultivation and stored grain management at Oryu 2-dong, submitting the clan''s proposal to the Council.\n\n**Clan.** The Lee clan is a vassal of the Free City, and Lee Ilseop is the heir who carries on the First Sub-Workshop.\n\n**Belief.** He believes the world gets better when farming leaves food to spare.\n\n**Relationships.** As heir of the Lee clan, a vassal of the Free City, he carries on the First Sub-Workshop and, in his workshop duties at Oryu 2-dong, submits proposals to the Standards League Council on the sub-workshop''s parts payments. He entrusts his direct courier Park Doyun with delivering messages and confirming receipt, and his direct guard Ryu Donghyeon with patrolling the power equipment and reporting anomalies. Lee Ilseop personally cross-checks grain quantities and the ration plan. With Gu Chansol he matches the grain loss ledger against parts transport records, and from Jang Useok he receives the audit results of the parts specification copies to be submitted to the Council. Heo Daon''s wheel inspection records are used to check the parts to be shipped from the sub-workshop.\n\n**Ambition.** To fill the winter ration plan with grain from the field he cultivates in his First Sub-Workshop duties at Oryu 2-dong, and so build a sub-workshop with food to spare.\n\n**Fear.** That the grain stock, recounted three times, will fall short of the winter ration plan.\n\n**Intervention.** One can count the grain stock together with him to bring the winter ration plan forward, or back or undermine the seed-payment proposal in the Council.\n\n::: details Appendix — Ledger Figures\n\n- Values: Authority −20 | Openness 40 | Force −30 | Materialism 40 | Communal 30 | Principle 50 | Publicity 50 | Qualification 45 | Decentralization 30 | Transformation 40\n- Desires: Craving 35 | Monopoly −25 | Risk −20 | Display −30 | Endurance 70 | Orientation Fluid | Union Contractual Cohabitation\n:::","court":{"id":"court:K998","members":[{"personId":"K425","name":"Bak Doyun"},{"personId":"K441","name":"Ryu Donghyeon"}]},"relations":{"outgoing":[{"from":"I Ilseop","type":"Contract","to":"Gu Chansol","basis":"Cross-checks the First Branch Workshop''s grain loss ledger against the part-transport records."},{"from":"I Ilseop","type":"Contract","to":"Jang Useok","basis":"Requests an audit of the sub-workshop parts standards copies to be submitted to the council"},{"from":"I Ilseop","type":"Contract","to":"Heo Daon","basis":"Cross-checks the measured values of the branch workshop''s shipped parts against the wheel inspection records."}],"incoming":[{"from":"Gu Chansol","type":"Contract","to":"I Ilseop","basis":"Returns the part-transport records to be matched against the branch workshop''s grain loss ledger."},{"from":"Jang Useok","type":"Contract","to":"I Ilseop","basis":"Returns the audit and remeasurement results for the parts standards copies"},{"from":"Heo Daon","type":"Contract","to":"I Ilseop","basis":"Sends the wheel inspection records so that shipped parts can be checked together."},{"from":"Bak Doyun","type":"Command","to":"I Ilseop","basis":"Serves as Lee Ilseop''s direct courier, in charge of delivering messages and confirming receipt"},{"from":"Ryu Donghyeon","type":"Command","to":"I Ilseop","basis":"Direct guard of I Ilseop, in charge of power unit patrols and anomaly reports"}]}}', '{"id":"person-0998","name":"이일섭","title":"제1분공방 이씨 가문 후계","position":"관악 공작 · 제1분공방 이씨 가문 후계","characterId":"K998","rank":"","commonTier":"T2","occupation":"오류2동 제1분공방 업무에 쓰는 밭 경작·곡물 재고 관리","gender":"남성","stage":"S1","state":"geography:duchy:11620","stateName":"관악구","sourceRoute":"/world/Cast-State-02#인물-이일섭","detailRoute":"/people/person-0998","birthDate":"2092-04-14","birthday":"04-14","age":34,"ageAsOf":"2126-12-31","sourceStatus":"owner-authored","proseContacts":[],"household":{"personFaith":"unknown","houseFaith":"unknown","humanoidAdmission":"deferred"},"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-identity-20260925","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"characterProfile":{"abilities":{"diplomacy":{"base":14,"effective":14},"martial":{"base":17,"effective":17},"stewardship":{"base":19,"effective":23},"intrigue":{"base":16,"effective":16},"learning":{"base":18,"effective":18},"prowess":{"base":8,"effective":8}},"skills":[{"id":"k998-skill-1","name":"재고 관리","rating":85},{"id":"k998-skill-2","name":"배급 계획","rating":80}],"traits":[{"id":"k998-trait-1","name":"장기 준비","description":"겨울 배급을 재고와 종자부터 준비한다.","behavior":"겨울 배급을 재고와 종자부터 준비한다.","stress":"위험 소식에는 재고를 반복 확인하며 결정을 늦춘다.","relationship":"평의회에 종자 대금을 제안하고 가신 보고를 직접 대조한다.","effects":[{"ability":"stewardship","delta":4}]},{"id":"k998-trait-2","name":"결정 지연","description":"결정 전에 장부를 다시 세는 시간이 길다.","behavior":"결정 전에 장부를 다시 세는 시간이 길다.","stress":"위험 소식을 들으면 먼저 숨을 곳을 생각한다.","relationship":"믿는 일에는 물러서지 않으나 배급안의 지연이 협의를 늦춘다.","effects":[]}],"narrative":"겨울 배급안을 올리기 전 곡물 재고를 세 차례 다시 세었고 부품 대금 일부를 종자로 받자고 제안했다. 위험에 대한 두려움과 느린 결정이 있지만 자신이 믿는 먹을거리의 지속에는 물러서지 않는다.","health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"politicalIdentities":[{"id":"title:duchy-chungcheong-k998","kind":"nonterritorial-political-identity","rank":"duchy","holderPersonId":"K998","stateId":"S02","politicalParentTitleId":"title:kingdom-s02","personalLieges":[],"directOwnership":false},{"id":"title:barony-chungcheong-3611025000","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K998","stateId":"S02","politicalParentTitleId":"title:duchy-chungcheong-k998","personalLieges":[{"holdingId":"holding:chungcheong-3611025000","directLiegePersonId":null}],"directOwnership":false},{"id":"title:barony-chungcheong-4420033000","kind":"nonterritorial-political-identity","rank":"barony","holderPersonId":"K998","stateId":"S02","politicalParentTitleId":"title:duchy-chungcheong-k998","personalLieges":[{"holdingId":"holding:chungcheong-4420033000","directLiegePersonId":null}],"directOwnership":false}],"confirmedHoldings":[],"clan":{"id":"c774-c804-c758-674e","name":"전의 이씨","crest":"clan-crests/c774-c804-c758-674e.svg"},"generation":"opening","minors":false,"sourceKind":"proposal","locked":false,"values":{"권위":-20,"개방":40,"무력":-30,"물질":40,"공동":30,"원칙":50,"공개":50,"자격":45,"분산":30,"변혁":40},"desire":{"갈망":35,"독점":-25,"위험":-20,"과시":-30,"지속":70,"지향":"유동","결합":"계약동거"},"fields":{"소속":"자유도시 봉신 제1분공방 이씨 가문","품계":"공작","직함":"제1분공방 이씨 가문 후계","생업":"오류2동 제1분공방 업무에 쓰는 밭 경작·곡물 재고 관리","성명":"이일섭. 공개 예명 iz.","기여자":"[islee23520](https://github.com/islee23520)","출신 공동체":"제1분공방 이씨 가문. 본관 전의.","업무 위치":"오류2동. 이일섭은 오류2동 제1분공방에서 겨울 배급에 쓸 곡물 재고를 세 차례 세고 종자 대금 제안서를 규격맹 평의회로 올린다. 박도윤에게 제안서 수령 확인을 맡기고 류동현에게 작업 구역의 전력 이상만 보고받으며 밭과 보관 공간의 사용은 가문 영토로 넓히지 않는다.","가치관":"권위 −20 | 개방 40 | 무력 −30 | 물질 40 | 공동 30 | 원칙 50 | 공개 50 | 자격 45 | 분산 30 | 변혁 40","욕망":"갈망 35 | 독점 −25 | 위험 −20 | 과시 −30 | 지속 70 | 지향 유동 | 결합 계약동거"},"sections":{"생애":"제1분공방을 잇는 이씨 가문의 후계다. 2121년 오류2동 공방 업무에서 밭을 일구고 곡물 재고를 맡았다. 밭과 보관 공간은 이 업무에 사용했으며 가문의 영토나 독점 소유는 아니었다. 2123년에는 겨울 배급안을 올리기 전 곡물 재고를 세 차례 다시 세었고, 분공방 부품 대금 일부를 종자로 받자고 규격맹 평의회에 제안하였다.","일화":"2123년 이일섭은 겨울 배급안을 올리기 전 곡물 재고를 세 차례 다시 세었고, 같은 해 분공방 부품 대금 일부를 종자로 받자고 규격맹 평의회에 제안하였다. 오류2동에서 밭의 경작과 보관 곡물 관리를 맡던 후계가 평의회에 가문의 안을 올린 일이다.","가문":"이씨 가문은 자유도시의 봉신이며, 이일섭은 제1분공방을 잇는 후계다.","신념":"농사를 지어 먹을 것이 남으면 세상이 좋아진다고 믿는다.","관계":"자유도시의 봉신인 이씨 가문의 후계로 제1분공방을 잇고, 오류2동의 공방 업무에서 분공방 부품 대금을 두고 규격맹 평의회에 제안을 올린다. 직속 전령 박도윤에게 전갈 전달과 수령 확인을, 직속 경비 류동현에게 전력장치 순찰과 이상 보고를 맡긴다. 곡물 수량과 배급안은 이일섭이 직접 대조한다. 구찬솔과는 곡물 손실 장부를 부품 운송 기록과 맞추고, 장우석에게는 평의회에 올릴 부품 규격 사본의 감사 결과를 받는다. 허다온의 차륜 검사 기록은 분공방에서 출고할 부품을 대조하는 데 쓴다.","야망":"오류2동 제1분공방 업무에서 맡아 경작하는 밭의 곡물로 겨울 배급안을 채워, 먹을 것이 남는 분공방을 만든다.","공포":"세 차례 다시 센 곡물 재고가 겨울 배급안에 모자라는 것.","개입":"함께 곡물 재고를 세어 겨울 배급안을 앞당기거나, 종자 대금 제안을 평의회에서 받치거나 흔들 수 있다."},"biography":"겁이 많고 결정이 느리다. 위험한 소식을 들으면 먼저 숨을 곳부터 생각하고, 밤새 장부를 다시 세어 다음 날에야 권안을 내놓는다. 그러나 믿는 일 앞에서는 물러서지 않는다.\n\n- 소속: 자유도시 봉신 제1분공방 이씨 가문\n- 품계: 이사\n- 직함: 제1분공방 이씨 가문 후계\n- 생업: 오류2동 제1분공방 업무에 쓰는 밭 경작·곡물 재고 관리\n- 성명: 이일섭. 공개 예명 iz.\n- 기여자: [islee23520](https://github.com/islee23520)\n- 출신 공동체: 제1분공방 이씨 가문. 본관 전의.\n- 업무 위치: 오류2동. 이일섭은 오류2동 제1분공방에서 겨울 배급에 쓸 곡물 재고를 세 차례 세고 종자 대금 제안서를 규격맹 평의회로 올린다. 박도윤에게 제안서 수령 확인을 맡기고 류동현에게 작업 구역의 전력 이상만 보고받으며 밭과 보관 공간의 사용은 가문 영토로 넓히지 않는다.\n\n**생애.** 제1분공방을 잇는 이씨 가문의 후계다. 2121년 오류2동 공방 업무에서 밭을 일구고 곡물 재고를 맡았다. 밭과 보관 공간은 이 업무에 사용했으며 가문의 영토나 독점 소유는 아니었다. 2123년에는 겨울 배급안을 올리기 전 곡물 재고를 세 차례 다시 세었고, 분공방 부품 대금 일부를 종자로 받자고 규격맹 평의회에 제안하였다.\n\n**일화.** 2123년 이일섭은 겨울 배급안을 올리기 전 곡물 재고를 세 차례 다시 세었고, 같은 해 분공방 부품 대금 일부를 종자로 받자고 규격맹 평의회에 제안하였다. 오류2동에서 밭의 경작과 보관 곡물 관리를 맡던 후계가 평의회에 가문의 안을 올린 일이다.\n\n**가문.** 이씨 가문은 자유도시의 봉신이며, 이일섭은 제1분공방을 잇는 후계다.\n\n**신념.** 농사를 지어 먹을 것이 남으면 세상이 좋아진다고 믿는다.\n\n**관계.** 자유도시의 봉신인 이씨 가문의 후계로 제1분공방을 잇고, 오류2동의 공방 업무에서 분공방 부품 대금을 두고 규격맹 평의회에 제안을 올린다. 직속 전령 박도윤에게 전갈 전달과 수령 확인을, 직속 경비 류동현에게 전력장치 순찰과 이상 보고를 맡긴다. 곡물 수량과 배급안은 이일섭이 직접 대조한다. 구찬솔과는 곡물 손실 장부를 부품 운송 기록과 맞추고, 장우석에게는 평의회에 올릴 부품 규격 사본의 감사 결과를 받는다. 허다온의 차륜 검사 기록은 분공방에서 출고할 부품을 대조하는 데 쓴다.\n\n**야망.** 오류2동 제1분공방 업무에서 맡아 경작하는 밭의 곡물로 겨울 배급안을 채워, 먹을 것이 남는 분공방을 만든다.\n\n**공포.** 세 차례 다시 센 곡물 재고가 겨울 배급안에 모자라는 것.\n\n**개입.** 함께 곡물 재고를 세어 겨울 배급안을 앞당기거나, 종자 대금 제안을 평의회에서 받치거나 흔들 수 있다.\n\n::: details 부록 — 장부 숫자\n\n- 가치관: 권위 −20 | 개방 40 | 무력 −30 | 물질 40 | 공동 30 | 원칙 50 | 공개 50 | 자격 45 | 분산 30 | 변혁 40\n- 욕망: 갈망 35 | 독점 −25 | 위험 −20 | 과시 −30 | 지속 70 | 지향 유동 | 결합 계약동거\n:::","court":{"id":"court:K998","members":[{"personId":"K425","name":"박도윤"},{"personId":"K441","name":"류동현"}]},"relations":{"outgoing":[{"from":"이일섭","type":"계약","to":"구찬솔","basis":"제1분공방의 곡물 손실 장부를 부품 운송 기록과 대조한다"},{"from":"이일섭","type":"계약","to":"장우석","basis":"평의회에 제출할 분공방 부품 규격 사본의 감사를 의뢰한다"},{"from":"이일섭","type":"계약","to":"허다온","basis":"차륜 검사 기록으로 분공방 출고 부품의 계측값을 대조한다"}],"incoming":[{"from":"구찬솔","type":"계약","to":"이일섭","basis":"분공방의 곡물 손실 장부와 맞출 부품 운송 기록을 돌려준다"},{"from":"장우석","type":"계약","to":"이일섭","basis":"부품 규격 사본의 감사와 재측정 결과를 돌려준다"},{"from":"허다온","type":"계약","to":"이일섭","basis":"출고 부품을 함께 확인하도록 차륜 검사 기록을 보낸다"},{"from":"박도윤","type":"지휘","to":"이일섭","basis":"이일섭의 직속 전령으로 전갈 전달과 수령 확인을 맡음"},{"from":"류동현","type":"지휘","to":"이일섭","basis":"이일섭의 직속 경비로 전력장치 순찰과 이상 보고를 맡음"}]}}');
